async function exportMlbMatchupRangeCsv(startDate = '', endDate = '', options = {}) {
  const fallbackDate = dateInput.value || formatDate(new Date());
  const range = dateRangeInclusive(startDate || fallbackDate, endDate || startDate || fallbackDate);
  const feedConcurrency = Math.max(1, Number(options.feedConcurrency) || 4);
  const rawRows = [];
  const errors = [];
  for (const date of range.dates) {
    const schedule = await getSchedule(date);
    const games = listify(schedule?.dates?.[0]?.games).sort((a, b) => String(a?.gameDate || '').localeCompare(String(b?.gameDate || '')));
    const rowsByGame = await mapWithConcurrency(games, feedConcurrency, async (game) => {
      try {
        const live = await getLiveGameFeed(game.gamePk);
        return extractMatchupRowsFromLiveFeed(date, game, live);
      } catch (error) {
        errors.push({ date, gamePk: game?.gamePk || '', message: error?.message || String(error) });
        return [];
      }
    });
    for (const rows of rowsByGame) rawRows.push(...rows);
  }
  rawRows.sort((a, b) =>
    String(a.matchup_key).localeCompare(String(b.matchup_key))
    || String(a.date).localeCompare(String(b.date))
    || String(a.game_pk).localeCompare(String(b.game_pk))
    || (Number(a.inning) - Number(b.inning))
    || matchupHalfSortValue(a.inning_half) - matchupHalfSortValue(b.inning_half)
    || (Number(a.at_bat_index) - Number(b.at_bat_index))
  );
  const summaryRows = aggregateMatchupCsvRows(rawRows);
  const suffix = `${range.startDate}_to_${range.endDate}`;
  const rawFilename = `mlb-matchups-plate-appearances-${suffix}.csv`;
  const summaryFilename = `mlb-matchups-summary-${suffix}.csv`;
  if (options.download !== false) {
    downloadCsvRowsFile(rawFilename, rawRows, MATCHUP_PA_CSV_COLUMNS);
    downloadCsvRowsFile(summaryFilename, summaryRows, MATCHUP_SUMMARY_CSV_COLUMNS);
  }
  console.info(`MLB matchup export complete for ${range.startDate} through ${range.endDate}: ${rawRows.length} plate appearances, ${summaryRows.length} unique batter/pitcher matchups.`);
  if (errors.length) {
    console.warn('Some games could not be exported:', errors);
  }
  return {
    ...range,
    rawFilename,
    summaryFilename,
    rawRows,
    summaryRows,
    errors,
  };
}

function normalizeLookupText(value) {
  return String(value || '').trim().toLowerCase();
}

async function getPerson(playerId) {
  return getJson(`${MLB_API_BASE}/people/${playerId}`);
}

async function getPlayerSeasonStats(playerId, group, season) {
  const url = new URL(`${MLB_API_BASE}/people/${playerId}/stats`);
  url.searchParams.set('stats', 'season');
  url.searchParams.set('group', group);
  url.searchParams.set('season', String(season));
  url.searchParams.set('gameType', 'R');
  url.searchParams.set('sportIds', '1');
  return getJson(url.toString());
}

function statSplit(response) {
  return response?.stats?.[0]?.splits?.[0]?.stat || {};
}

function seasonStatHasValue(stat = {}) {
  return [
    stat?.avg,
    stat?.obp,
    stat?.slg,
    stat?.ops,
    stat?.era,
    stat?.whip,
    stat?.atBats,
    stat?.hits,
    stat?.totalBases,
    stat?.inningsPitched,
    stat?.strikeOuts,
    stat?.gamesPlayed,
  ].some((value) => {
    if (value === null || value === undefined || value === '' || value === '---' || value === '--') return false;
    return Number.isFinite(Number(String(value).replace(/^\./, '0.'))) || cleanSummary(value);
  });
}

function hydratedSeasonStatSplit(response, group = '') {
  const normalizedGroup = String(group || '').toLowerCase();
  const stats = response?.people?.[0]?.stats || [];
  const found = stats.find((entry) => {
    const groupName = String(entry?.group?.displayName || entry?.group?.displayNamePlural || entry?.group || '').toLowerCase();
    const typeName = String(entry?.type?.displayName || entry?.type || '').toLowerCase();
    return (!normalizedGroup || groupName.includes(normalizedGroup)) && (!typeName || typeName.includes('season'));
  }) || stats[0];
  return found?.splits?.[0]?.stat || {};
}

async function getPlayerSeasonStatSplit(playerId, group, season) {
  const id = Number(playerId);
  const cacheKey = `${id}:${String(group || '').toLowerCase()}:${season || ''}:season:v1`;
  if (playerSeasonStatSplitCache.has(cacheKey)) {
    statsProfilerRecord({ kind: 'cache', label: `seasonStat:${group}`, status: 'hit', targetPlayerId: String(id), ms: 0 });
    return playerSeasonStatSplitCache.get(cacheKey);
  }
  const promise = statsProfilerMeasureAsync('stat-loader', `seasonStat:${group}`, { targetPlayerId: String(id), source: String(season || '') }, async () => {
    let direct = {};
    try {
      direct = statSplit(await getPlayerSeasonStats(playerId, group, season));
    } catch {
      direct = {};
    }
    if (seasonStatHasValue(direct)) return direct;
    try {
      const url = new URL(`${MLB_API_BASE}/people/${playerId}`);
      url.searchParams.set('hydrate', `stats(group=[${group}],type=[season],season=${season})`);
      const hydrated = hydratedSeasonStatSplit(await getJson(url.toString()), group);
      return seasonStatHasValue(hydrated) ? hydrated : direct;
    } catch {
      return direct;
    }
  }).catch((error) => {
    playerSeasonStatSplitCache.delete(cacheKey);
    throw error;
  });
  playerSeasonStatSplitCache.set(cacheKey, promise);
  return promise;
}

function seasonSplitMatchesSeason(split = {}, season = '') {
  const target = String(season || '').trim();
  if (!target) return true;
  const values = [
    split?.season,
    split?.stat?.season,
    split?.league?.season,
    split?.team?.season,
  ].map((value) => String(value ?? '').trim()).filter(Boolean);
  return values.includes(target);
}

function seasonSplitMatchesSport(split = {}, sportIds = '1') {
  const allowed = new Set(String(sportIds || '1').split(',').map((value) => value.trim()).filter(Boolean));
  if (!allowed.size) return true;
  const values = [
    split?.sport?.id,
    split?.league?.sport?.id,
    split?.team?.sport?.id,
  ].map((value) => String(value ?? '').trim()).filter(Boolean);
  return !values.length || values.some((value) => allowed.has(value));
}

function seasonStatFromSplitsPayload(payload = {}, group = '', season = '', sportIds = '1') {
  const normalizedGroup = String(group || '').toLowerCase();
  const statGroups = listify(payload?.stats || payload?.people?.[0]?.stats);
  for (const entry of statGroups) {
    const groupName = String(entry?.group?.displayName || entry?.group?.displayNamePlural || entry?.group || '').toLowerCase();
    if (normalizedGroup && groupName && !groupName.includes(normalizedGroup)) continue;
    const match = listify(entry?.splits).find((split) => (
      seasonSplitMatchesSeason(split, season)
      && seasonSplitMatchesSport(split, sportIds)
      && seasonStatHasGameActivity(split?.stat || {}, group)
    ));
    if (match?.stat) return match.stat;
  }
  return {};
}

async function getPlayerYearByYearSeasonStatSplit(playerId, group, season, sportIds = '1') {
  const url = new URL(`${MLB_API_BASE}/people/${playerId}/stats`);
  url.searchParams.set('stats', 'yearByYear');
  url.searchParams.set('group', group);
  url.searchParams.set('season', String(season));
  url.searchParams.set('gameType', 'R');
  url.searchParams.set('sportIds', sportIds);
  const payload = await getJson(url.toString());
  return seasonStatFromSplitsPayload(payload, group, season, sportIds);
}

function gameLogSplitMatchesRequestedSeason(split = {}, season = '', sportIds = '1') {
  const target = String(season || '').trim();
  if (!target) return seasonSplitMatchesSport(split, sportIds);
  const explicitSeason = seasonSplitMatchesSeason(split, target);
  const dateSeason = String(split?.date || split?.gameDate || '').slice(0, 4);
  const seasonMatch = explicitSeason || dateSeason === target || (!dateSeason && !listify(split?.season || split?.stat?.season || split?.team?.season).length);
  return seasonMatch && seasonSplitMatchesSport(split, sportIds);
}

function aggregateGameLogSeasonStatsForGroup(splits = [], group = '') {
  const normalizedGroup = String(group || '').toLowerCase();
  const rows = listify(splits).filter((split) => split?.stat || split);
  if (!rows.length) return {};

  if (normalizedGroup.includes('pitch')) {
    const totals = aggregatePlayerCardPitchingSplits(rows);
    if (!totals.games && !totals.outs) return {};
    return {
      gamesPlayed: totals.games,
      gamesPitched: totals.games,
      gamesStarted: totals.starts,
      wins: totals.wins,
      losses: totals.losses,
      saves: totals.saves,
      inningsPitched: outsToInnings(totals.outs),
      hits: totals.hits,
      atBats: totals.atBats,
      totalBases: totals.totalBases,
      baseOnBalls: totals.walks,
      strikeOuts: totals.strikeOuts,
      homeRuns: totals.homeRuns,
      earnedRuns: totals.earnedRuns,
      era: totals.outs > 0 ? formatSeasonStatRate((totals.earnedRuns * 27) / totals.outs, 2, false) : '---',
      whip: totals.outs > 0 ? formatSeasonStatRate(((totals.hits + totals.walks) * 3) / totals.outs, 2, false) : '---',
      avg: totals.atBats > 0 ? formatSeasonStatRate(totals.hits / totals.atBats) : '---',
      slg: totals.atBats > 0 ? formatSeasonStatRate(totals.totalBases / totals.atBats) : '---',
    };
  }

  if (normalizedGroup.includes('hit') || normalizedGroup.includes('bat')) {
    const totals = aggregatePlayerCardBattingSplits(rows);
    if (!totals.games && !totals.atBats && !totals.plateAppearances) return {};
    return {
      gamesPlayed: totals.games,
      plateAppearances: totals.plateAppearances,
      atBats: totals.atBats,
      hits: totals.hits,
      doubles: totals.doubles,
      triples: totals.triples,
      homeRuns: totals.homeRuns,
      rbi: totals.rbi,
      runs: totals.runs,
      totalBases: totals.totalBases,
      baseOnBalls: totals.walks,
      strikeOuts: totals.strikeOuts,
      avg: formatSeasonStatRate(totals.avg),
      obp: formatSeasonStatRate(totals.obp),
      slg: formatSeasonStatRate(totals.slg),
      ops: formatSeasonStatRate(totals.ops),
    };
  }

  return aggregateSeasonStatsForGroup(rows, group);
}

async function getPlayerGameLogSeasonStatSplit(playerId, group, season, sportIds = '1') {
  const url = new URL(`${MLB_API_BASE}/people/${playerId}/stats`);
  url.searchParams.set('stats', 'gameLog');
  url.searchParams.set('group', group);
  url.searchParams.set('season', String(season));
  url.searchParams.set('gameType', 'R');
  url.searchParams.set('sportIds', sportIds);
  const payload = await getJson(url.toString());
  const normalizedGroup = String(group || '').toLowerCase();
  const splits = [];
  for (const entry of listify(payload?.stats || payload?.people?.[0]?.stats)) {
    const groupName = String(entry?.group?.displayName || entry?.group?.displayNamePlural || entry?.group || '').toLowerCase();
    if (normalizedGroup && groupName && !groupName.includes(normalizedGroup)) continue;
    for (const split of listify(entry?.splits)) {
      if (gameLogSplitMatchesRequestedSeason(split, season, sportIds)) splits.push(split);
    }
  }
  return aggregateGameLogSeasonStatsForGroup(splits, group);
}

async function getPlayerPreviousMlbSeasonStatSplit(playerId, group, season) {
  const id = Number(playerId);
  const cacheKey = `${id}:${String(group || '').toLowerCase()}:${season || ''}:previous-mlb:v1`;
  if (playerPreviousMlbSeasonStatCache.has(cacheKey)) {
    statsProfilerRecord({ kind: 'cache', label: `previousMlb:${group}`, status: 'hit', targetPlayerId: String(id), ms: 0 });
    return playerPreviousMlbSeasonStatCache.get(cacheKey);
  }
  const promise = statsProfilerMeasureAsync('stat-loader', `previousMlb:${group}`, { targetPlayerId: String(id), source: String(season || '') }, async () => {
    const direct = await getPlayerSeasonStatSplit(playerId, group, season).catch(() => ({}));
    if (seasonStatHasGameActivity(direct, group)) return direct;
    const yearByYear = await getPlayerYearByYearSeasonStatSplit(playerId, group, season, '1').catch(() => ({}));
    if (seasonStatHasGameActivity(yearByYear, group)) return yearByYear;
    const gameLog = await getPlayerGameLogSeasonStatSplit(playerId, group, season, '1').catch(() => ({}));
    return seasonStatHasGameActivity(gameLog, group) ? gameLog : direct;
  }).catch((error) => {
    playerPreviousMlbSeasonStatCache.delete(cacheKey);
    throw error;
  });
  playerPreviousMlbSeasonStatCache.set(cacheKey, promise);
  return promise;
}

const FIRST_APPEARANCE_FALLBACK_MIN_TEAM_GAMES = 20;
const MINOR_LEAGUE_SPORT_IDS = '11,12,13,14,15,16';

function statRate(value) {
  const raw = cleanSummary(value);
  if (!raw || raw === '---' || raw === '--') return NaN;
  const parsed = Number(raw.replace(/^\./, '0.'));
  return Number.isFinite(parsed) ? parsed : NaN;
}

function seasonStatHasGameActivity(stat = {}, group = '') {
  const normalizedGroup = String(group || '').toLowerCase();
  const games = statNumber(stat.gamesPlayed ?? stat.games ?? stat.gamesPitched ?? stat.appearances);
  if (normalizedGroup.includes('pitch')) {
    const outs = inningsToOuts(stat.inningsPitched ?? stat.ip);
    const battersFaced = statNumber(stat.battersFaced);
    const pitches = statNumber(stat.numberOfPitches ?? stat.pitchesThrown);
    const countingStats = [
      stat.hits,
      stat.earnedRuns,
      stat.runs,
      stat.baseOnBalls ?? stat.walks,
      stat.strikeOuts,
      stat.homeRuns ?? stat.hrAllowed ?? stat.hr,
    ].some((value) => statNumber(value) > 0);
    // Scheduled/listed starters can appear in season payloads with gamesStarted/gamesPlayed
    // but no recorded pitching work yet. Do not treat that shell as usable season activity,
    // otherwise first-appearance/previous-season fallback never runs.
    return outs > 0 || battersFaced > 0 || pitches > 0 || countingStats;
  }
  if (normalizedGroup.includes('hit') || normalizedGroup.includes('bat')) {
    return games > 0
      || statNumber(stat.plateAppearances) > 0
      || statNumber(stat.atBats) > 0;
  }
  if (normalizedGroup.includes('field')) {
    return games > 0 || inningsToOuts(stat.innings ?? stat.inningsPlayed) > 0;
  }
  return games > 0 || seasonStatHasValue(stat);
}

function seasonStatIsCompletelyEmpty(stat = {}, group = '') {
  if (!stat || typeof stat !== 'object') return true;
  if (seasonStatHasGameActivity(stat, group)) return false;
  const keys = [
    'avg',
    'obp',
    'slg',
    'ops',
    'era',
    'whip',
    'gamesPlayed',
    'games',
    'gamesPitched',
    'plateAppearances',
    'atBats',
    'hits',
    'homeRuns',
    'inningsPitched',
    'strikeOuts',
  ];
  return !keys.some((key) => {
    const value = stat?.[key];
    if (value === null || value === undefined || value === '' || value === '---' || value === '--') return false;
    return cleanSummary(value) !== '';
  });
}

function firstAppearanceFallbackEligibleForStat(stat = {}, group = '') {
  return seasonStatIsCompletelyEmpty(stat, group);
}

function selectedDateIsPastAprilForFirstAppearanceFallback(dateValue = '') {
  const date = parseLocalDateValue(dateValue || dateInput.value || formatDate(new Date()));
  return date instanceof Date && !Number.isNaN(date.getTime()) && date.getMonth() >= 4;
}

function profileHasFirstAppearanceSeasonFallback(profile = null) {
  const sources = profile?.seasonStatSource || {};
  return Boolean(
    sources?.hitting?.fallback
    || sources?.pitching?.fallback
    || sources?.fielding?.fallback
  );
}

function profileHasNoCurrentSeasonActivity(profile = null) {
  if (!profile) return true;
  if (profileHasFirstAppearanceSeasonFallback(profile)) return false;
  const batting = profile?.batting || profile?.seasonStats?.batting || profile?.stats?.batting || {};
  const pitching = profile?.pitching || profile?.seasonStats?.pitching || profile?.stats?.pitching || {};
  const fielding = profile?.fielding || profile?.seasonStats?.fielding || profile?.stats?.fielding || {};
  const profileGames = statNumber(profile?.playerGames ?? profile?.playerGamesPlayed ?? profile?.gamesPlayed ?? profile?.games);
  return profileGames <= 0
    && !seasonStatHasGameActivity(batting, 'hitting')
    && !seasonStatHasGameActivity(pitching, 'pitching')
    && !seasonStatHasGameActivity(fielding, 'fielding');
}

function profileHasCompletelyEmptySeasonData(profile = null) {
  if (!profile) return true;
  if (profileHasFirstAppearanceSeasonFallback(profile)) return false;
  const batting = profile?.batting || profile?.seasonStats?.batting || profile?.stats?.batting || {};
  const pitching = profile?.pitching || profile?.seasonStats?.pitching || profile?.stats?.pitching || {};
  const fielding = profile?.fielding || profile?.seasonStats?.fielding || profile?.stats?.fielding || {};
  const profileGames = statNumber(profile?.playerGames ?? profile?.playerGamesPlayed ?? profile?.gamesPlayed ?? profile?.games);
  return profileGames <= 0
    && seasonStatIsCompletelyEmpty(batting, 'hitting')
    && seasonStatIsCompletelyEmpty(pitching, 'pitching')
    && seasonStatIsCompletelyEmpty(fielding, 'fielding');
}

function playerProfileNeedsFirstAppearanceFallback(playerId, profile = null, game = null, person = null) {
  if (!profileHasCompletelyEmptySeasonData(profile)) return false;
  const teamGames = teamGamesPlayedForPlayerFallback(playerId, game, profile, person);
  return teamGames >= FIRST_APPEARANCE_FALLBACK_MIN_TEAM_GAMES
    || selectedDateIsPastAprilForFirstAppearanceFallback(dateInput.value || game?.officialDate || game?.gameDate || formatDate(new Date()));
}

function teamGamesPlayedForPlayerFallback(playerId, game = null, fallbackProfile = null, person = null) {
  const context = typeof playerTeamContextFromGame === 'function'
    ? playerTeamContextFromGame(playerId, fallbackProfile, game)
    : {};
  if (!game) return 0;
  const team = canonicalTeamAbbrev(
    context?.teamAbbrev
      || fallbackProfile?.teamAbbrev
      || fallbackProfile?.team?.abbreviation
      || fallbackProfile?.currentTeam?.abbreviation
      || person?.currentTeam?.abbreviation
      || person?.currentTeam?.teamCode
      || '',
  );
  if (team) {
    if (sameTeamAbbrev(game.away, team)) return gamesFromRecordString(game.awayRecord);
    if (sameTeamAbbrev(game.home, team)) return gamesFromRecordString(game.homeRecord);
  }
  const teamId = Number(context?.teamId || fallbackProfile?.teamId || fallbackProfile?.team?.id || fallbackProfile?.currentTeam?.id || person?.currentTeam?.id);
  for (const side of ['away', 'home']) {
    const node = game?.teams?.[side] || {};
    const nodeTeam = node?.team || node;
    const nodeTeamId = Number(nodeTeam?.id || (side === 'away' ? game?.awayTeamId : game?.homeTeamId));
    if (Number.isFinite(teamId) && teamId > 0 && nodeTeamId === teamId) {
      return gamesFromRecordString(side === 'away' ? game.awayRecord : game.homeRecord);
    }
  }
  const side = String(context?.teamSide || fallbackProfile?.teamSide || '').toLowerCase();
  if (side === 'away') return gamesFromRecordString(game.awayRecord);
  if (side === 'home') return gamesFromRecordString(game.homeRecord);
  return 0;
}

function formatSeasonStatRate(value, digits = 3, trimLeadingZero = true) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return '---';
  return formatRateValue(numeric, digits, trimLeadingZero);
}

function aggregateSeasonStatsForGroup(splits = [], group = '') {
  const normalizedGroup = String(group || '').toLowerCase();
  const rows = listify(splits).map((split) => split?.stat || split).filter(Boolean);
  if (!rows.length) return {};
  const sum = (keys) => rows.reduce((total, stat) => {
    for (const key of keys) {
      if (stat?.[key] !== undefined && stat?.[key] !== null && stat?.[key] !== '') {
        return total + statNumber(stat[key]);
      }
    }
    return total;
  }, 0);

  if (normalizedGroup.includes('pitch')) {
    const outs = rows.reduce((total, stat) => total + inningsToOuts(stat.inningsPitched ?? stat.ip), 0);
    const hits = sum(['hits']);
    const walks = sum(['baseOnBalls', 'walks']);
    const earnedRuns = sum(['earnedRuns']);
    const strikeOuts = sum(['strikeOuts', 'strikeouts', 'so']);
    const homeRuns = sum(['homeRuns', 'hrAllowed', 'homeRunsAllowed']);
    const atBats = sum(['atBats', 'opponentAtBats']);
    const totalBases = sum(['totalBases', 'opponentTotalBases']);
    const stat = {
      gamesPlayed: sum(['gamesPlayed', 'gamesPitched', 'games', 'appearances']),
      gamesStarted: sum(['gamesStarted', 'starts']),
      gamesFinished: sum(['gamesFinished']),
      wins: sum(['wins']),
      losses: sum(['losses']),
      saves: sum(['saves']),
      inningsPitched: outsToInnings(outs),
      hits,
      baseOnBalls: walks,
      strikeOuts,
      homeRuns,
      earnedRuns,
      era: outs > 0 ? formatSeasonStatRate((earnedRuns * 27) / outs, 2, false) : '---',
      whip: outs > 0 ? formatSeasonStatRate(((hits + walks) * 3) / outs, 2, false) : '---',
      avg: atBats > 0 ? formatSeasonStatRate(hits / atBats) : '---',
      slg: atBats > 0 && totalBases > 0 ? formatSeasonStatRate(totalBases / atBats) : '---',
    };
    return stat;
  }

  if (normalizedGroup.includes('hit') || normalizedGroup.includes('bat')) {
    const atBats = sum(['atBats', 'ab']);
    const hits = sum(['hits']);
    const doubles = sum(['doubles']);
    const triples = sum(['triples']);
    const homeRuns = sum(['homeRuns', 'hr']);
    const walks = sum(['baseOnBalls', 'walks']);
    const hbp = sum(['hitByPitch']);
    const sacFlies = sum(['sacFlies', 'sacrificeFlies']);
    const totalBases = sum(['totalBases']) || Math.max(0, hits - doubles - triples - homeRuns) + (doubles * 2) + (triples * 3) + (homeRuns * 4);
    const obpDenom = atBats + walks + hbp + sacFlies;
    const stat = {
      gamesPlayed: sum(['gamesPlayed', 'games']),
      plateAppearances: sum(['plateAppearances']) || atBats + walks + hbp + sacFlies,
      atBats,
      hits,
      doubles,
      triples,
      homeRuns,
      rbi: sum(['rbi', 'runsBattedIn']),
      runs: sum(['runs']),
      totalBases,
      baseOnBalls: walks,
      strikeOuts: sum(['strikeOuts', 'strikeouts', 'so']),
      stolenBases: sum(['stolenBases']),
      caughtStealing: sum(['caughtStealing']),
      avg: atBats > 0 ? formatSeasonStatRate(hits / atBats) : '---',
      obp: obpDenom > 0 ? formatSeasonStatRate((hits + walks + hbp) / obpDenom) : '---',
      slg: atBats > 0 ? formatSeasonStatRate(totalBases / atBats) : '---',
    };
    const avg = statRate(stat.obp);
    const slg = statRate(stat.slg);
    stat.ops = Number.isFinite(avg) && Number.isFinite(slg) ? formatSeasonStatRate(avg + slg) : '---';
    return stat;
  }

  return rows[0] || {};
}

async function getPlayerMinorLeagueSeasonStatSplit(playerId, group, season) {
  const id = Number(playerId);
  const cacheKey = `${id}:${String(group || '').toLowerCase()}:${season || ''}:minors:v1`;
  if (playerMinorLeagueSeasonStatCache.has(cacheKey)) {
    statsProfilerRecord({ kind: 'cache', label: `minorSeason:${group}`, status: 'hit', targetPlayerId: String(id), ms: 0 });
    return playerMinorLeagueSeasonStatCache.get(cacheKey);
  }
  const promise = statsProfilerMeasureAsync('stat-loader', `minorSeason:${group}`, { targetPlayerId: String(id), source: String(season || '') }, async () => {
    const url = new URL(`${MLB_API_BASE}/people/${playerId}/stats`);
    url.searchParams.set('stats', 'season');
    url.searchParams.set('group', group);
    url.searchParams.set('season', String(season));
    url.searchParams.set('gameType', 'R');
    url.searchParams.set('sportIds', MINOR_LEAGUE_SPORT_IDS);
    const response = await getJson(url.toString());
    const splits = listify(response?.stats?.[0]?.splits);
    if (!splits.length) return {};
    return aggregateSeasonStatsForGroup(splits, group);
  }).catch((error) => {
    playerMinorLeagueSeasonStatCache.delete(cacheKey);
    throw error;
  });
  playerMinorLeagueSeasonStatCache.set(cacheKey, promise);
  return promise;
}

function tagSeasonStatSource(stat = {}, label = '', type = '', season = '') {
  if (!stat || !seasonStatHasValue(stat)) return stat || {};
  return {
    ...stat,
    __seasonSourceLabel: label,
    __seasonSourceType: type,
    __seasonSourceSeason: String(season || ''),
    __seasonSourceFallback: true,
  };
}

async function getPlayerSeasonStatSplitWithFirstAppearanceFallback(playerId, group, season, context = {}) {
  const current = context.currentStat || await getPlayerSeasonStatSplit(playerId, group, season);
  const normalizedGroup = String(group || '').toLowerCase();
  if (!(normalizedGroup.includes('pitch') || normalizedGroup.includes('hit') || normalizedGroup.includes('bat'))) return current;
  const explicitEligible = Object.prototype.hasOwnProperty.call(context, 'firstAppearanceFallbackEligible')
    ? context.firstAppearanceFallbackEligible === true
    : null;
  if (explicitEligible === false) return current;
  if (explicitEligible !== true && !firstAppearanceFallbackEligibleForStat(current, group)) return current;

  const id = Number(playerId);
  const selectedDate = String(context.selectedDate || dateInput.value || context.game?.officialDate || context.game?.gameDate || '');
  const cacheKey = `${id}:${normalizedGroup}:${season || ''}:${selectedDate}:fallback:v1`;
  if (playerSeasonStatFallbackCache.has(cacheKey)) {
    statsProfilerRecord({ kind: 'cache', label: `seasonStatWithFallback:${group}`, status: 'hit', targetPlayerId: String(id), ms: 0 });
    return playerSeasonStatFallbackCache.get(cacheKey);
  }

  const promise = statsProfilerMeasureAsync('stat-loader', `seasonStatWithFallback:${group}`, { targetPlayerId: String(id), source: selectedDate }, async () => {
    const numericSeason = Number(season);
    const priorSeasons = Number.isFinite(numericSeason) && numericSeason > 1900
      ? [1, 2, 3, 4, 5].map((offset) => numericSeason - offset).filter((year) => year > 1900)
      : [];

    // First-appearance/current-season shells are common for listed starters on future
    // or pregame slates. Searching only the immediately previous season left players
    // like Ben Brown stuck at IP 0.0 / ERA -- even though older MLB work existed.
    for (const priorSeason of priorSeasons) {
      const previousMlb = await getPlayerPreviousMlbSeasonStatSplit(playerId, group, priorSeason).catch(() => ({}));
      if (seasonStatHasGameActivity(previousMlb, group)) {
        return tagSeasonStatSource(previousMlb, `${priorSeason} MLB`, 'previous-mlb', priorSeason);
      }
    }

    const currentMinor = await getPlayerMinorLeagueSeasonStatSplit(playerId, group, season).catch(() => ({}));
    if (seasonStatHasGameActivity(currentMinor, group)) {
      return tagSeasonStatSource(currentMinor, `${season} MiLB`, 'current-minors', season);
    }

    for (const priorSeason of priorSeasons) {
      const previousMinor = await getPlayerMinorLeagueSeasonStatSplit(playerId, group, priorSeason).catch(() => ({}));
      if (seasonStatHasGameActivity(previousMinor, group)) {
        return tagSeasonStatSource(previousMinor, `${priorSeason} MiLB`, 'previous-minors', priorSeason);
      }
    }

    return current;
  }).catch((error) => {
    playerSeasonStatFallbackCache.delete(cacheKey);
    throw error;
  });
  playerSeasonStatFallbackCache.set(cacheKey, promise);
  return promise;
}

function playerSeasonStatSourcePayload(stat = {}) {
  const label = cleanSummary(stat?.__seasonSourceLabel || '');
  if (!label) return null;
  return {
    label,
    type: cleanSummary(stat?.__seasonSourceType || ''),
    season: cleanSummary(stat?.__seasonSourceSeason || ''),
    fallback: stat?.__seasonSourceFallback === true,
  };
}

function playerSeasonColumnLabel(profile = null, group = '', fallback = 'Season') {
  const key = String(group || '').toLowerCase().includes('pitch') ? 'pitching'
    : String(group || '').toLowerCase().includes('hit') || String(group || '').toLowerCase().includes('bat') ? 'hitting'
      : String(group || '').toLowerCase().includes('field') ? 'fielding'
        : group;
  return cleanSummary(profile?.seasonStatSource?.[key]?.label || '') || fallback;
}

function playerSeasonRowsTitle(profile = null, group = '', base = 'SEASON') {
  const label = playerSeasonColumnLabel(profile, group, '');
  return label ? `${base} - ${label}` : base;
}

async function getPlayerHandedBattingSplit(playerId, sitCode, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0 || !sitCode) return null;
  const cacheKey = `${id}:${season}:${sitCode}`;
  if (playerHandedSplitsCache.has(cacheKey)) return playerHandedSplitsCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'statSplits');
    url.searchParams.set('group', 'hitting');
    url.searchParams.set('season', String(season));
    url.searchParams.set('gameType', 'R');
    url.searchParams.set('sportIds', '1');
    url.searchParams.set('sitCodes', sitCode);
    const response = await getJson(url.toString());
    return response?.stats?.[0]?.splits?.[0]?.stat || null;
  })().catch((error) => {
    playerHandedSplitsCache.delete(cacheKey);
    throw error;
  });
  playerHandedSplitsCache.set(cacheKey, promise);
  return promise;
}

async function getPlayerHandedBattingSplits(playerId, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const [vsLeft, vsRight] = await Promise.all([
    getPlayerHandedBattingSplit(playerId, 'vl', season).catch(() => null),
    getPlayerHandedBattingSplit(playerId, 'vr', season).catch(() => null),
  ]);
  return { vsLeft, vsRight };
}

function rateNumber(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return NaN;
  const parsed = Number(raw.replace(/^\./, '0.'));
  return Number.isFinite(parsed) ? parsed : NaN;
}

function handedSplitFlagHtml(stat, splitHand, matchupHand = '') {
  if (!stat) return '';
  const avg = rateNumber(stat.avg);
  const slg = rateNumber(stat.slg);
  const flags = [];
  if (Number.isFinite(avg) && avg < 0.175) flags.push('<span title="Poor split AVG">👎</span>');
  if (Number.isFinite(avg) && avg >= 0.330) flags.push('<span title="Strong split AVG">👍</span>');
  if (Number.isFinite(slg) && slg >= 0.600) flags.push('<span title="Power split">⚡</span>');
  const splitMatchesToday = matchupHand && handednessCode(matchupHand) === splitHand;
  return `<span class="handed-split-flags${splitMatchesToday ? ' is-today-matchup' : ''}">${flags.join('')}</span>`;
}

function handedSplitEmojiHtml(stat, splitHand, matchupHand = '') {
  const avg = rateNumber(stat?.avg);
  const slg = rateNumber(stat?.slg);
  const matchesToday = matchupHand && handednessCode(matchupHand) === splitHand;
  const poorAvg = Number.isFinite(avg) && avg < 0.175;
  const poorPower = Number.isFinite(slg) && slg < 0.390 && (!Number.isFinite(avg) || avg < 0.255);
  const strongAvg = Number.isFinite(avg) && avg >= 0.330;
  const powerSplit = Number.isFinite(slg) && slg >= 0.600;
  if (!matchesToday && !poorAvg && !poorPower && !strongAvg && !powerSplit) return '';
  const pieces = [];
  if (poorAvg || poorPower) {
    const title = poorPower ? 'Poor handed power split' : 'Poor handed split';
    pieces.push(`<span class="lineup-split-flag poor-handed-power-split" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}">👎</span>`);
  }
  if (strongAvg) pieces.push('<span class="lineup-split-flag" title="Strong handed split" aria-label="Strong handed split">👍</span>');
  if (powerSplit) pieces.push('<span class="lineup-split-flag" title="Power handed split" aria-label="Power handed split">⚡</span>');
  return pieces.join('');
}

function formatAtBatsPerHomeRun(atBats, homeRuns) {
  const ab = statNumber(atBats);
  const hr = statNumber(homeRuns);
  if (ab <= 0 || hr <= 0) return '--';
  const rate = ab / hr;
  return Number.isInteger(rate) ? String(rate) : rate.toFixed(1);
}

function handedSplitTableRow(label, splitHand, stat, matchupHand = '') {
  const hits = statNumber(stat?.hits);
  const atBats = statNumber(stat?.atBats);
  const xbh = statNumber(stat?.doubles) + statNumber(stat?.triples) + statNumber(stat?.homeRuns);
  return `
    <tr${matchupHand && handednessCode(matchupHand) === splitHand ? ' class="is-today-matchup"' : ''}>
      <th>${escapeHtml(label)}</th>
      <td>${stat ? `${hits}-${atBats}` : '---'}</td>
      <td>${escapeHtml(cleanSummary(stat?.avg) || '---')}</td>
      <td>${escapeHtml(cleanSummary(stat?.slg) || '---')}</td>
      <td>${stat ? xbh : '---'}</td>
      <td>${statNumber(stat?.homeRuns)}</td>
      <td>${handedSplitFlagHtml(stat, splitHand, matchupHand)}</td>
    </tr>
  `;
}

function handedSplitsTableHtml({ vsLeft = null, vsRight = null } = {}, matchupHand = '') {
  const hand = handednessCode(matchupHand);
  const rows = hand === 'L'
    ? handedSplitTableRow('Vs LHP', 'L', vsLeft, matchupHand)
    : hand === 'R'
      ? handedSplitTableRow('Vs RHP', 'R', vsRight, matchupHand)
      : `${handedSplitTableRow('Vs LHP', 'L', vsLeft, matchupHand)}${handedSplitTableRow('Vs RHP', 'R', vsRight, matchupHand)}`;
  return `
    <table class="player-stat-table handed-splits-table">
      <thead>
        <tr>
          <th>Split</th>
          <th>H-AB</th>
          <th>AVG</th>
          <th>SLG</th>
          <th>XBH</th>
          <th>HR</th>
          <th></th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
  `;
}

function parseCsvRows(text = '') {
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  const source = String(text || '');
  for (let i = 0; i < source.length; i += 1) {
    const char = source[i];
    const next = source[i + 1];
    if (quoted && char === '"' && next === '"') {
      field += '"';
      i += 1;
      continue;
    }
    if (char === '"') {
      quoted = !quoted;
      continue;
    }
    if (!quoted && char === ',') {
      row.push(field);
      field = '';
      continue;
    }
    if (!quoted && (char === '\n' || char === '\r')) {
      if (char === '\r' && next === '\n') i += 1;
      row.push(field);
      if (row.some((value) => String(value).trim())) rows.push(row);
      row = [];
      field = '';
      continue;
    }
    field += char;
  }
  row.push(field);
  if (row.some((value) => String(value).trim())) rows.push(row);
  if (rows.length < 2) return [];
  const cleanCsvCell = (value) => {
    let textValue = String(value ?? '').replace(/^\uFEFF/, '').trim();
    if (textValue.length >= 2 && textValue.startsWith('"') && textValue.endsWith('"')) textValue = textValue.slice(1, -1).replace(/""/g, '"');
    return cleanSummary(textValue);
  };
  const headers = rows[0].map(cleanCsvCell);
  return rows.slice(1).map((values) => Object.fromEntries(headers.map((header, index) => [header, cleanCsvCell(values[index] ?? '')])));
}

function csvValue(row = {}, candidates = []) {
  const keys = Object.keys(row || {});
  for (const candidate of candidates) {
    const direct = row[candidate];
    if (direct !== undefined && direct !== '') return direct;
    const match = keys.find((key) => normalizeNameKey(key) === normalizeNameKey(candidate));
    if (match && row[match] !== undefined && row[match] !== '') return row[match];
  }
  return '';
}

function savantNumber(row = {}, candidates = []) {
  const value = csvValue(row, candidates);
  const numeric = Number(String(value || '').replace('%', '').replace(/,/g, '').replace(/^\./, '0.'));
  return Number.isFinite(numeric) ? numeric : 0;
}

function savantRate(row = {}, candidates = []) {
  const value = csvValue(row, candidates);
  if (value === '' || value === null || value === undefined) return null;
  const numeric = Number(String(value || '').replace('%', '').replace(/,/g, '').replace(/^\./, '0.'));
  return Number.isFinite(numeric) ? numeric : null;
}

const SAVANT_VELOCITY_KEYS = [
  'release_speed', 'Release Speed', 'api_p_release_speed', 'api_p_release_speed_avg',
  'release_speed_avg', 'avg_release_speed', 'average_release_speed',
  'start_speed', 'start_speed_avg', 'pitch_speed', 'pitch_speed_avg',
  'Velocity', 'velocity', 'MPH', 'mph', 'Velo', 'velo', 'avg_velo', 'velo_avg',
  'avgVelocity', 'avgVelo', 'averageVelocity', 'average_velocity',
  'avgFastballVelocity', 'averageFastballVelocity', 'fastballVelocity',
  'avg_speed', 'average_speed', 'mean_speed', 'pitch_velocity', 'pitchVelocity',
  'pitch_velocity_avg', 'avg_pitch_velocity', 'avgPitchVelocity', 'pitchAvgVelocity',
];

const SAVANT_MAX_VELOCITY_KEYS = [
  'maxVelocity', 'maxVelo', 'topVelocity', 'topVelo', 'peakVelocity',
  'maxFastballVelocity', 'topFastballVelocity', 'eventMaxVelocity', 'seasonMaxVelocity',
  'maxSpeed', 'maxMph', 'max_velocity', 'max_release_speed', 'api_p_release_speed_max',
  'releaseSpeedMax', 'pitchMaxVelocity', 'lastStartMaxVelocity',
  ...SAVANT_VELOCITY_KEYS,
];

function savantRowNumber(row = {}, candidates = []) {
  for (const key of candidates) {
    const value = row?.[key];
    if (value === undefined || value === null || String(value).trim?.() === '') continue;
    const numeric = Number(String(value).replace('%', '').replace(/,/g, '').replace(/^\./, '0.'));
    if (Number.isFinite(numeric)) return numeric;
  }
  return null;
}

function savantRowHomeRuns(row = {}) {
  return savantRowNumber(row, ['homeRuns', 'home_runs', 'home_run', 'hr', 'HR', 'hrs', 'Hrs']) ?? 0;
}

const PITCHER_ALLOWED_AVG_KEYS = ['pitcherAvg', 'pitcherBAA', 'pitcherAvgAllowed', 'avgAllowedByPitcher', 'baa', 'BAA', 'avg', 'AVG', 'batting_average_against'];
const PITCHER_ALLOWED_AVG_STRICT_KEYS = ['pitcherAvg', 'pitcherBAA', 'pitcherAvgAllowed', 'avgAllowedByPitcher', 'baa', 'batting_average_against'];
const PITCHER_ALLOWED_SLG_KEYS = ['pitcherSlg', 'pitcherSLG', 'pitcherSlgAllowed', 'slgAllowedByPitcher', 'slg', 'SLG', 'slugging', 'slugging_allowed'];
const PITCHER_ALLOWED_SLG_STRICT_KEYS = ['pitcherSlg', 'pitcherSLG', 'pitcherSlgAllowed', 'slgAllowedByPitcher', 'pitcherSlugging', 'pitcherSluggingAllowed', 'allowedSlugging', 'allowed_slg', 'slugging_allowed', 'pSlg', 'pSLG'];
const PITCHER_ALLOWED_AB_KEYS = ['pitcherAb', 'pitcherAB', 'pitcherAbs', 'pitcherAtBats', 'abAllowedByPitcher', 'ab', 'AB', 'abs', 'at_bats', 'At Bats'];
const PITCHER_ALLOWED_AB_STRICT_KEYS = ['pitcherAb', 'pitcherAB', 'pitcherAbs', 'pitcherAtBats', 'abAllowedByPitcher', 'battersFacedAB'];
const PITCHER_ALLOWED_HH_KEYS = ['pitcherHardHit', 'pitcherHardHitAllowed', 'pitcherHardHitPct', 'pitcherHardHitPercent', 'pitcherHardHitRate', 'pitcherHH', 'pitcherHhPct', 'pHardHit', 'pHardHitPct', 'pHardHitPercent', 'pHardHitAllowed', 'pHH', 'hardHitAllowedByPitcher', 'hardHitAllowed', 'hard_hit_allowed_percent', 'hard_hit_allowed_pct', 'hard_hit_percent_allowed', 'hard_hit_rate_allowed', 'allowed_hard_hit_percent', 'allowed_hard_hit_pct'];
const PITCHER_ALLOWED_WHIFF_KEYS = ['pitcherWhiff', 'pitcherWhiffAllowed', 'pitcherWhiffPct', 'pitcherWhiffPercent', 'pitcherWhiffRate', 'pWhiff', 'pWhiffPct', 'pWhiffPercent', 'pWhiffAllowed', 'whiffAllowedByPitcher', 'whiffAllowed', 'whiff_allowed_percent', 'whiff_allowed_pct', 'whiff_percent_allowed', 'whiff_rate_allowed', 'allowed_whiff_percent', 'allowed_whiff_pct'];
const GENERIC_HH_KEYS = ['hardHit', 'HardHit%', 'hardHit%', 'HH%', 'hhPct', 'hard_hit_percent', 'hard_hit_pct', 'hardhit_percent', 'hard_hit_rate', 'Hard Hit %', 'Hard Hit%', 'hard_hit'];
const GENERIC_WHIFF_KEYS = ['whiff', 'Whiff%', 'whiff%', 'whiff_percent', 'whiff_pct', 'whiff_rate', 'swing_miss_percent', 'swinging_strike_percent', 'Swinging Strike%', 'Whiff %', 'swstr_pct'];
const PITCHER_OWN_HH_KEYS = [...PITCHER_ALLOWED_HH_KEYS, ...GENERIC_HH_KEYS];
const PITCHER_OWN_WHIFF_KEYS = [...PITCHER_ALLOWED_WHIFF_KEYS, ...GENERIC_WHIFF_KEYS];

function pitcherMetricSourceLooksPitcherOwned(row = {}) {
  return row?.pitcherMetricSource === true
    || row?.pitcherSource === true
    || row?.playerType === 'pitcher'
    || row?.sourcePlayerType === 'pitcher'
    || row?.isPitcherPitchRow === true;
}

function pitcherAllowedHardHitNumber(row = {}) {
  const explicit = savantRowNumber(row, PITCHER_ALLOWED_HH_KEYS);
  if (Number.isFinite(explicit)) return explicit >= 0 && explicit <= 100 ? (explicit <= 1 && explicit > 0 ? explicit * 100 : explicit) : null;
  const generic = pitcherMetricSourceLooksPitcherOwned(row) ? savantRowNumber(row, GENERIC_HH_KEYS) : null;
  return Number.isFinite(generic) && generic >= 0 && generic <= 100 ? (generic <= 1 && generic > 0 ? generic * 100 : generic) : null;
}

function pitcherAllowedWhiffNumber(row = {}) {
  const explicit = savantRowNumber(row, PITCHER_ALLOWED_WHIFF_KEYS);
  if (Number.isFinite(explicit)) return explicit >= 0 && explicit <= 100 ? (explicit <= 1 && explicit > 0 ? explicit * 100 : explicit) : null;
  const generic = pitcherMetricSourceLooksPitcherOwned(row) ? savantRowNumber(row, GENERIC_WHIFF_KEYS) : null;
  return Number.isFinite(generic) && generic >= 0 && generic <= 100 ? (generic <= 1 && generic > 0 ? generic * 100 : generic) : null;
}

function pitchCardBoundedNumber(row = {}, keys = [], { min = null, max = null } = {}) {
  const numeric = savantRowNumber(row, keys);
  if (!Number.isFinite(numeric)) return null;
  if (Number.isFinite(min) && numeric < min) return null;
  if (Number.isFinite(max) && numeric > max) return null;
  return numeric;
}

function pitchCardCountNumber(row = {}, keys = []) {
  return pitchCardBoundedNumber(row, keys, { min: 0, max: 10000 });
}

function pitchCardRateNumber(row = {}, keys = [], max = 5) {
  return pitchCardBoundedNumber(row, keys, { min: 0, max });
}

function pitchCardPercentNumber(row = {}, keys = []) {
  const numeric = pitchCardBoundedNumber(row, keys, { min: 0, max: 100 });
  if (Number.isFinite(numeric)) return numeric <= 1 && numeric > 0 ? numeric * 100 : numeric;
  return null;
}

function batterPitchRowIsReal(row = {}) {
  if (!row || row.missingBatterPitchSplit === true || !visiblePitchCategoryName(row?.category)) return false;
  return Number.isFinite(pitchCardRateNumber(row, ['avg', 'AVG', 'ba', 'BA', 'batting_avg'], 1.5))
    || Number.isFinite(pitchCardRateNumber(row, ['slg', 'SLG', 'slugging', 'xslg', 'xSLG'], 5))
    || Number.isFinite(pitchCardRateNumber(row, ['ev', 'EV', 'exit_velocity_avg', 'avg_hit_speed', 'launch_speed'], 130))
    || Number.isFinite(pitchCardPercentNumber(row, ['hardHit', 'HardHit%', 'hard_hit_percent', 'hard_hit_pct', 'hardhit_percent']))
    || Number.isFinite(pitchCardPercentNumber(row, ['whiff', 'Whiff%', 'whiff_percent', 'swing_miss_percent', 'swinging_strike_percent']))
    || Number(pitchCardCountNumber(row, ['ab', 'AB', 'abs', 'at_bats', 'At Bats'])) > 0
    || Number(pitchCardCountNumber(row, ['pa', 'PA', 'plateAppearances', 'plate_appearances'])) > 0
    || Number(pitchCardCountNumber(row, ['homeRuns', 'home_runs', 'home_run', 'hr', 'HR', 'hrs', 'Hrs'])) > 0
    || Number(pitchCardCountNumber(row, ['pitches', 'Pitches', 'total_pitches', 'pitch_count'])) > 0
    || Number.isFinite(visiblePitchUsagePercent(row, ['pct', 'usage', 'usagePct', 'pitch_percent']));
}

function batterPitchRowHasRenderableStats(row = {}) {
  return batterPitchRowIsReal(row);
}

function batterPitchCardUsagePercent(row = {}) {
  const usage = visiblePitchUsagePercent(row, ['pitcherUsagePct', 'pct', 'usage', 'usagePct', 'pitch_percent']);
  if (Number.isFinite(usage)) return usage;
  const pitches = pitchCardCountNumber(row, ['pitches', 'Pitches', 'total_pitches', 'pitch_count']);
  return Number.isFinite(pitches) && pitches > 0 ? 100 : null;
}

function pitchCardRowHasPitcherContext(row = {}) {
  return Number.isFinite(pitchCardRateNumber(row, ['pitcherAvg', 'pitcherBAA', 'pitcherAvgAllowed', 'avgAllowedByPitcher', 'baa', 'batting_average_against'], 1.5))
    || Number.isFinite(pitchCardRateNumber(row, ['pitcherSlg', 'pitcherSLG', 'pitcherSlgAllowed', 'slgAllowedByPitcher', 'pitcherSlugging', 'pitcherSluggingAllowed', 'allowedSlugging', 'allowed_slg', 'slugging_allowed', 'pSlg', 'pSLG'], 5))
    || Number.isFinite(pitchCardCountNumber(row, ['pitcherAb', 'pitcherAB', 'pitcherAbs', 'pitcherAtBats', 'abAllowedByPitcher', 'battersFacedAB']))
    || Number.isFinite(pitchCardCountNumber(row, ['pitcherHomeRuns', 'pitcherHrAllowed', 'hrAllowedByPitcher', 'hrAllowed', 'pitcherHR']));
}

function batterPitchCardCanRender(row = {}) {
  return batterPitchRowIsReal(row) || pitchCardRowHasPitcherContext(row);
}

function pitchCardFamilyKey(category = '') {
  const key = pitchStrengthMatchKey(category || '');
  if (!key) return '';
  if (/^(fastball|4-seam|2-seam|sinker|cutter)$/.test(key)) return 'fastball';
  if (/^(slider|sweeper|curveball|knucklecurve)$/.test(key)) return 'breaking';
  if (/^(changeup|splitter)$/.test(key)) return 'offspeed';
  if (/^(breaking|offspeed)$/.test(key)) return key;
  return key;
}

function pitchCardCategoryIsBroadFamily(category = '') {
  const key = pitchStrengthMatchKey(category || '');
  return /^(fb|fastball|breaking|offspeed|off-speed|secondary)$/.test(key);
}

function pitcherAllowedSlugForFiery(row = {}) {
  const explicit = savantRowNumber(row, PITCHER_ALLOWED_SLG_STRICT_KEYS);
  if (Number.isFinite(explicit)) return explicit;
  if (pitcherMetricSourceLooksPitcherOwned(row)) {
    return savantRowNumber(row, ['slg', 'SLG', 'slugging', 'xslg', 'xSLG']);
  }
  return null;
}

function hitterSlugForFiery(row = {}) {
  return savantRowNumber(row, ['slg', 'SLG', 'slugging', 'xslg', 'xSLG']);
}

function shouldUseFieryPitchOutline(row = {}, playerType = 'batter') {
  if (playerType === 'pitcher') return false;
  const hitterSlg = hitterSlugForFiery(row);
  const pitcherSlg = pitcherAllowedSlugForFiery(row);
  return Number.isFinite(hitterSlg) && hitterSlg > 0.500 && Number.isFinite(pitcherSlg) && pitcherSlg > 0.500;
}

function savantRowOps(row = {}) {
  const direct = savantRowNumber(row, ['ops', 'OPS', 'on_base_plus_slg', 'on_base_plus_slugging']);
  if (Number.isFinite(direct)) return direct;
  const hits = savantRowNumber(row, ['hits', 'H']) ?? 0;
  const ab = savantRowNumber(row, ['ab', 'AB', 'abs', 'at_bats']) ?? 0;
  const doubles = savantRowNumber(row, ['doubles', '2B', 'double']) ?? 0;
  const triples = savantRowNumber(row, ['triples', '3B', 'triple']) ?? 0;
  const homeRuns = savantRowHomeRuns(row);
  const walks = savantRowNumber(row, ['walks', 'BB', 'base_on_balls']) ?? 0;
  const hitByPitch = savantRowNumber(row, ['hitByPitch', 'hit_by_pitch', 'HBP']) ?? 0;
  const sacFlies = savantRowNumber(row, ['sacFlies', 'sac_flies', 'SF']) ?? 0;
  const singles = Math.max(0, hits - doubles - triples - homeRuns);
  const totalBases = singles + (doubles * 2) + (triples * 3) + (homeRuns * 4);
  const slg = ab > 0 ? totalBases / ab : savantRowNumber(row, ['slg', 'SLG', 'slugging']);
  const obpDen = ab + walks + hitByPitch + sacFlies;
  const obp = obpDen > 0 ? (hits + walks + hitByPitch) / obpDen : savantRowNumber(row, ['obp', 'OBP', 'on_base_percent', 'on_base_percentage']);
  if (Number.isFinite(obp) && Number.isFinite(slg)) return obp + slg;
  const avg = ab > 0 ? hits / ab : savantRowNumber(row, ['avg', 'ba', 'BA', 'BAA', 'batting_avg']);
  return Number.isFinite(avg) && Number.isFinite(slg) ? avg + slg : null;
}

function savantRowIso(row = {}) {
  const direct = savantRowNumber(row, ['iso', 'ISO', 'isolated_power', 'isolatedPower']);
  if (Number.isFinite(direct)) return direct;
  const slg = savantRowNumber(row, ['slg', 'SLG', 'slugging']);
  const avg = savantRowNumber(row, ['avg', 'ba', 'BA', 'BAA', 'batting_avg']);
  return Number.isFinite(slg) && Number.isFinite(avg) ? slg - avg : null;
}

function addSavantWeighted(bucket, valueKey, denomKey, value, weight = 1) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return;
  const safeWeight = Math.max(1, Number(weight) || 1);
  bucket[valueKey] += numeric * safeWeight;
  bucket[denomKey] += safeWeight;
}

function savantPitchCategory(row = {}) {
  const raw = cleanSummary(csvValue(row, ['Pitch Group', 'Pitch Type', 'pitch_name', 'pitch_type', 'Pitch Name', 'pitch']));
  const key = raw.toLowerCase();
  if (!key) return '';
  if (/breaking|slider|sweeper|curve|knuckle curve|slurve|sl|st|cu|kc|sv|cs/.test(key)) return 'Breaking';
  if (/split-finger|splitter|fs/.test(key)) return 'Offspeed';
  if (/fastball|4-seam|2-seam|sinker|cutter|ff|fa|si|ft|fc/.test(key)) return 'Fastball';
  if (/offspeed|change|changeup|forkball|screwball|knuckleball|eephus|ch|fo|sc|kn|ep/.test(key)) return 'Offspeed';
  return raw;
}

function savantExactPitchCategory(row = {}) {
  const raw = cleanSummary(csvValue(row, ['Pitch Type', 'pitch_name', 'Pitch Name', 'pitch_type', 'pitch', 'Pitch Group']));
  const key = raw.toLowerCase();
  if (!key) return '';
  if (excludedVisiblePitchCategory(key)) return '';
  if (['ff', 'fa'].includes(key)) return '4-Seam';
  if (key === 'si') return 'Sinker';
  if (key === 'ft') return '2-Seam';
  if (key === 'fc') return 'Cutter';
  if (key === 'sl') return 'Slider';
  if (key === 'st') return 'Sweeper';
  if (['cu', 'kc', 'cs'].includes(key)) return key === 'kc' ? 'Knuckle Curve' : 'Curveball';
  if (key === 'ch') return 'Changeup';
  if (key === 'fs') return 'Splitter';
  return raw;
}

function excludedVisiblePitchCategory(value = '') {
  const key = String(value || '').trim().toLowerCase().replace(/[_\s-]+/g, ' ');
  return ['po', 'pitchout', 'pitch out', 'intentional ball', 'unknown', 'undefined', 'null', 'ep', 'eephus'].includes(key);
}

function visiblePitchCategoryName(value = '') {
  const raw = cleanSummary(value);
  return excludedVisiblePitchCategory(raw) ? '' : raw;
}

function emptyPitchStrengthBucket(category) {
  return {
    category,
    pitches: 0,
    percentNumerator: 0,
    pa: 0,
    ab: 0,
    hits: 0,
    doubles: 0,
    triples: 0,
    homeRuns: 0,
    walks: 0,
    hitByPitch: 0,
    sacFlies: 0,
    strikeOuts: 0,
    bbe: 0,
    avgWeight: 0,
    avgWeightDen: 0,
    slgWeight: 0,
    slgWeightDen: 0,
    obpWeight: 0,
    obpWeightDen: 0,
    opsWeight: 0,
    opsWeightDen: 0,
    wobaWeight: 0,
    wobaWeightDen: 0,
    xwobaWeight: 0,
    xwobaWeightDen: 0,
    evWeight: 0,
    evWeightDen: 0,
    laWeight: 0,
    laWeightDen: 0,
    whiffWeight: 0,
    whiffWeightDen: 0,
    hardHitWeight: 0,
    hardHitWeightDen: 0,
    chaseWeight: 0,
    chaseWeightDen: 0,
    putAwayWeight: 0,
    putAwayWeightDen: 0,
    velocityWeight: 0,
    velocityWeightDen: 0,
    breakWeight: 0,
    breakWeightDen: 0,
    maxBreak: null,
    maxVelocity: null,
  };
}

function addSavantPitchVelocity(bucket, row = {}, weight = 1) {
  if (!bucket || !row) return;
  const velocity = savantRate(row, SAVANT_VELOCITY_KEYS);
  if (!Number.isFinite(velocity) || velocity < 70 || velocity > 110) return;
  const w = Math.max(1, Number(weight) || 1);
  bucket.velocityWeight += velocity * w;
  bucket.velocityWeightDen += w;
  bucket.maxVelocity = Math.max(Number(bucket.maxVelocity) || 0, velocity);
}

function savantPitchBreakAmount(row = {}) {
  const explicit = savantRate(row, [
    'breakLength', 'break_length', 'break_length_deprecated', 'Break Length', 'Break Length (in)',
    'pitchBreak', 'pitch_break', 'totalBreak', 'total_break', 'movement', 'movement_inches',
    'inducedVerticalBreak', 'ivb', 'IVB', 'verticalBreak', 'vertical_break',
    'horizontalBreak', 'horizontal_break', 'HB', 'hb',
  ]);
  if (Number.isFinite(explicit) && explicit > 0) return Math.abs(explicit);
  const pfxX = savantRate(row, ['pfx_x', 'pfxX', 'horizontal_movement', 'horizontalMovement']);
  const pfxZ = savantRate(row, ['pfx_z', 'pfxZ', 'vertical_movement', 'verticalMovement']);
  if (Number.isFinite(pfxX) || Number.isFinite(pfxZ)) {
    const x = Number.isFinite(pfxX) ? pfxX : 0;
    const z = Number.isFinite(pfxZ) ? pfxZ : 0;
    const magnitude = Math.sqrt((x * x) + (z * z));
    if (Number.isFinite(magnitude) && magnitude > 0) return magnitude <= 3 ? magnitude * 12 : magnitude;
  }
  const liveBreak = Number(row?.breaks?.breakLength ?? row?.pitchData?.breaks?.breakLength ?? row?.pitchData?.breakLength);
  return Number.isFinite(liveBreak) && liveBreak > 0 ? Math.abs(liveBreak) : null;
}

function addSavantPitchBreak(bucket, row = {}, weight = 1) {
  if (!bucket || !row) return;
  const amount = savantPitchBreakAmount(row);
  if (!Number.isFinite(amount) || amount <= 0 || amount > 40) return;
  const w = Math.max(1, Number(weight) || 1);
  bucket.breakWeight += amount * w;
  bucket.breakWeightDen += w;
  bucket.maxBreak = Math.max(Number(bucket.maxBreak) || 0, amount);
}

function addSavantPitchRow(bucket, row = {}) {
  const pitches = savantNumber(row, ['#', 'pitches', 'Pitches', 'total_pitches', 'Total Pitches', 'pitch_count']) || 1;
  const pa = savantNumber(row, ['PA', 'pa', 'plate_appearances', 'Plate Appearances']);
  const ab = savantNumber(row, ['AB', 'ab', 'abs', 'at_bats', 'At Bats']);
  const hits = savantNumber(row, ['H', 'Hits', 'hits', 'hit']);
  const doubles = savantNumber(row, ['2B', 'Doubles', 'doubles', 'double']);
  const triples = savantNumber(row, ['3B', 'Triples', 'triples', 'triple']);
  const homeRuns = savantNumber(row, ['HR', 'Home Runs', 'home_runs', 'homeRuns', 'home_run', 'Home Run', 'hrs']);
  const walks = savantNumber(row, ['BB', 'Walks', 'walks', 'walk', 'base_on_balls', 'baseOnBalls']);
  const hitByPitch = savantNumber(row, ['HBP', 'Hit By Pitch', 'hit_by_pitch', 'hitByPitch']);
  const sacFlies = savantNumber(row, ['SF', 'Sac Fly', 'Sac Flies', 'sac_flies', 'sacFlies']);
  const strikeOuts = savantNumber(row, ['SO', 'K', 'Strikeouts', 'strikeouts', 'strikeOuts']);
  const bbe = savantNumber(row, ['BBE', 'Batted Balls', 'Batted Ball Events', 'bbe']);
  bucket.pitches += pitches;
  bucket.percentNumerator += savantNumber(row, ['%', 'Pitch %', 'Pitch%', 'pitch_percent', 'pitch_percentages']) * (pitches || 1);
  addSavantPitchVelocity(bucket, row, pitches || 1);
  addSavantPitchBreak(bucket, row, pitches || 1);
  bucket.pa += pa;
  bucket.ab += ab;
  bucket.hits += hits;
  bucket.doubles += doubles;
  bucket.triples += triples;
  bucket.homeRuns += homeRuns;
  bucket.walks += walks;
  bucket.hitByPitch += hitByPitch;
  bucket.sacFlies += sacFlies;
  bucket.strikeOuts += strikeOuts;
  bucket.bbe += bbe;
  const plateWeight = Math.max(1, ab || pa || pitches);
  const battedBallWeight = Math.max(1, bbe || pitches);
  addSavantWeighted(bucket, 'avgWeight', 'avgWeightDen', savantRate(row, ['BA', 'BAA', 'AVG', 'ba', 'avg', 'batting_avg']), plateWeight);
  addSavantWeighted(bucket, 'slgWeight', 'slgWeightDen', savantRate(row, ['SLG', 'slg', 'slugging']), plateWeight);
  addSavantWeighted(bucket, 'obpWeight', 'obpWeightDen', savantRate(row, ['OBP', 'obp', 'on_base_percent', 'on_base_percentage']), plateWeight);
  addSavantWeighted(bucket, 'opsWeight', 'opsWeightDen', savantRate(row, ['OPS', 'ops', 'on_base_plus_slg', 'on_base_plus_slugging', 'OBP+SLG']), plateWeight);
  addSavantWeighted(bucket, 'wobaWeight', 'wobaWeightDen', savantRate(row, ['wOBA', 'woba']), Math.max(1, pa || pitches));
  addSavantWeighted(bucket, 'xwobaWeight', 'xwobaWeightDen', savantRate(row, ['xwOBA', 'xwoba', 'estimated_woba_using_speedangle']), Math.max(1, pa || pitches));
  addSavantWeighted(bucket, 'evWeight', 'evWeightDen', savantRate(row, ['EV', 'Exit Velocity', 'Average Exit Velocity', 'Avg Exit Velocity', 'ev', 'launch_speed', 'exit_velocity_avg', 'avg_hit_speed']), battedBallWeight);
  addSavantWeighted(bucket, 'laWeight', 'laWeightDen', savantRate(row, ['LA', 'launch_angle', 'launch_angle_avg']), battedBallWeight);
  addSavantWeighted(bucket, 'whiffWeight', 'whiffWeightDen', savantRate(row, ['Whiff%', 'Whiff %', 'whiff_percent', 'swing_miss_percent', 'swinging_strike_percent']), Math.max(1, pitches));
  addSavantWeighted(bucket, 'hardHitWeight', 'hardHitWeightDen', savantRate(row, ['HardHit%', 'Hard Hit %', 'Hard Hit%', 'hard_hit_percent', 'hard_hit_rate']), battedBallWeight);
  addSavantWeighted(bucket, 'chaseWeight', 'chaseWeightDen', savantRate(row, ['Chase%', 'Chase %', 'chase_percent']), Math.max(1, pitches));
  addSavantWeighted(bucket, 'putAwayWeight', 'putAwayWeightDen', savantRate(row, ['PutAway%', 'PutAway %', 'put_away', 'put_away_percent']), Math.max(1, pitches));
}

function finalizeSavantPitchBucket(bucket, totalPitches) {
  const singles = Math.max(0, bucket.hits - bucket.doubles - bucket.triples - bucket.homeRuns);
  const totalBases = singles + (bucket.doubles * 2) + (bucket.triples * 3) + (bucket.homeRuns * 4);
  const pitchWeight = Math.max(1, bucket.pitches);
  const weightedAvg = bucket.avgWeightDen > 0 ? bucket.avgWeight / bucket.avgWeightDen : null;
  const weightedSlg = bucket.slgWeightDen > 0 ? bucket.slgWeight / bucket.slgWeightDen : null;
  const weightedObp = bucket.obpWeightDen > 0 ? bucket.obpWeight / bucket.obpWeightDen : null;
  const weightedOps = bucket.opsWeightDen > 0 ? bucket.opsWeight / bucket.opsWeightDen : null;
  const weightedWoba = bucket.wobaWeightDen > 0 ? bucket.wobaWeight / bucket.wobaWeightDen : null;
  const weightedXwoba = bucket.xwobaWeightDen > 0 ? bucket.xwobaWeight / bucket.xwobaWeightDen : null;
  const weightedEv = bucket.evWeightDen > 0 ? bucket.evWeight / bucket.evWeightDen : null;
  const weightedLa = bucket.laWeightDen > 0 ? bucket.laWeight / bucket.laWeightDen : null;
  const weightedWhiff = bucket.whiffWeightDen > 0 ? bucket.whiffWeight / bucket.whiffWeightDen : null;
  const weightedHardHit = bucket.hardHitWeightDen > 0 ? bucket.hardHitWeight / bucket.hardHitWeightDen : null;
  const weightedChase = bucket.chaseWeightDen > 0 ? bucket.chaseWeight / bucket.chaseWeightDen : null;
  const weightedPutAway = bucket.putAwayWeightDen > 0 ? bucket.putAwayWeight / bucket.putAwayWeightDen : null;
  const weightedVelocity = bucket.velocityWeightDen > 0 ? bucket.velocityWeight / bucket.velocityWeightDen : null;
  const weightedBreak = bucket.breakWeightDen > 0 ? bucket.breakWeight / bucket.breakWeightDen : null;
  const maxBreak = Number.isFinite(Number(bucket.maxBreak)) && Number(bucket.maxBreak) > 0 ? Number(bucket.maxBreak) : weightedBreak;
  const maxVelocity = Number.isFinite(Number(bucket.maxVelocity)) && Number(bucket.maxVelocity) > 0 ? Number(bucket.maxVelocity) : weightedVelocity;
  const derivedAvg = bucket.ab > 0 ? bucket.hits / bucket.ab : weightedAvg;
  const derivedSlg = bucket.ab > 0 ? totalBases / bucket.ab : weightedSlg;
  const obpDen = bucket.ab + bucket.walks + bucket.hitByPitch + bucket.sacFlies;
  const derivedObp = obpDen > 0 ? (bucket.hits + bucket.walks + bucket.hitByPitch) / obpDen : weightedObp;
  const derivedOps = weightedOps ?? (Number.isFinite(derivedObp) && Number.isFinite(derivedSlg)
    ? derivedObp + derivedSlg
    : (Number.isFinite(derivedAvg) && Number.isFinite(derivedSlg) ? derivedAvg + derivedSlg : null));
  return {
    category: bucket.category,
    pitches: bucket.pitches,
    pct: totalPitches > 0 ? (bucket.pitches / totalPitches) * 100 : bucket.percentNumerator / pitchWeight,
    pa: bucket.pa,
    ab: bucket.ab,
    hits: bucket.hits,
    doubles: bucket.doubles,
    triples: bucket.triples,
    homeRuns: bucket.homeRuns,
    xbh: bucket.doubles + bucket.triples + bucket.homeRuns,
    strikeOuts: bucket.strikeOuts,
    bbe: bucket.bbe,
    avg: derivedAvg,
    slg: derivedSlg,
    obp: derivedObp,
    ops: derivedOps,
    woba: weightedWoba,
    xwoba: weightedXwoba,
    ev: weightedEv,
    la: weightedLa,
    whiff: weightedWhiff,
    hardHit: weightedHardHit,
    chase: weightedChase,
    putAway: weightedPutAway,
    velocity: weightedVelocity,
    avgVelocity: weightedVelocity,
    breakAmount: weightedBreak,
    avgBreak: weightedBreak,
    maxBreak,
    topBreak: maxBreak,
    maxVelocity,
    topVelocity: maxVelocity,
    hrRate: bucket.ab > 0 ? bucket.homeRuns / bucket.ab : (bucket.pa > 0 ? bucket.homeRuns / bucket.pa : null),
  };
}

function savantPitchStrengthUrl(playerId, playerType = 'batter', season = seasonForDate(dateInput.value || formatDate(new Date())), filters = {}) {
  const url = new URL('https://baseballsavant.mlb.com/statcast_search/csv');
  url.searchParams.set('all', 'true');
  url.searchParams.set('hfGT', 'R|');
  url.searchParams.set('hfSea', `${season}|`);
  const dateFrom = calendarDateOnly(filters?.gameDateGt || filters?.dateFrom || filters?.pitchDataFromDate || '');
  const dateThrough = calendarDateOnly(filters?.gameDateLt || filters?.dateThrough || filters?.pitchDataThroughDate || '');
  if (dateFrom) url.searchParams.set('game_date_gt', dateFrom);
  if (dateThrough) url.searchParams.set('game_date_lt', dateThrough);
  const stand = handednessCode(filters?.stand);
  if (stand === 'L' || stand === 'R') url.searchParams.set('batter_stands', stand);
  const pitcherThrows = handednessCode(filters?.pThrows ?? filters?.pitcherThrows ?? filters?.throws);
  if (pitcherThrows === 'L' || pitcherThrows === 'R') url.searchParams.set('pitcher_throws', pitcherThrows);
  url.searchParams.set('player_type', playerType === 'pitcher' ? 'pitcher' : 'batter');
  url.searchParams.set('group_by', 'pitch-type');
  url.searchParams.set('min_pitches', '0');
  url.searchParams.set('min_results', '0');
  url.searchParams.set('min_pas', '0');
  url.searchParams.set('player_event_sort', 'api_p_release_speed');
  url.searchParams.set('sort_col', 'pitches');
  url.searchParams.set('sort_order', 'desc');
  [
    'chk_stats_pitches',
    'chk_stats_pitch_percent',
    ...(playerType === 'pitcher'
      ? [
        'chk_stats_abs',
        'chk_stats_hits',
        'chk_stats_singles',
        'chk_stats_doubles',
        'chk_stats_triples',
        'chk_stats_hrs',
        'chk_stats_ba',
        'chk_stats_obp',
        'chk_stats_slg',
        'chk_stats_woba',
        'chk_stats_xwoba',
        'chk_stats_bbe',
        'chk_stats_velocity',
        'chk_stats_hard_hit_percent',
        'chk_stats_swing_miss_percent',
        'chk_stats_put_away',
      ]
      : [
        'chk_stats_pa',
        'chk_stats_abs',
        'chk_stats_hits',
        'chk_stats_singles',
        'chk_stats_doubles',
        'chk_stats_triples',
        'chk_stats_hrs',
        'chk_stats_bbe',
        'chk_stats_ba',
        'chk_stats_obp',
        'chk_stats_slg',
        'chk_stats_woba',
        'chk_stats_xwoba',
        'chk_stats_velocity',
        'chk_stats_hard_hit_percent',
        'chk_stats_swing_miss_percent',
        'chk_stats_put_away',
      ]),
  ].forEach((param) => url.searchParams.set(param, 'on'));
  url.searchParams.append(playerType === 'pitcher' ? 'pitchers_lookup[]' : 'batters_lookup[]', String(playerId));
  return url.toString();
}

function savantPitchFilterCacheSuffix(filters = {}) {
  const parts = [];
  const stand = handednessCode(filters?.stand);
  if (stand === 'L' || stand === 'R') parts.push(`stand-${stand}`);
  const pitcherThrows = handednessCode(filters?.pThrows ?? filters?.pitcherThrows ?? filters?.throws);
  if (pitcherThrows === 'L' || pitcherThrows === 'R') parts.push(`pthrows-${pitcherThrows}`);
  return parts.length ? `:${parts.join(':')}` : '';
}

function savantPitchFilterThrowHand(filters = {}) {
  const pitcherThrows = handednessCode(filters?.pThrows ?? filters?.pitcherThrows ?? filters?.throws);
  return pitcherThrows === 'L' || pitcherThrows === 'R' ? pitcherThrows : '';
}

function pitchVelocityFamilyKey(value = '') {
  const family = pitchStrengthMatchKey(value);
  if (family === 'fastball' || family === 'sinker' || family === 'cutter') return 'fastball-family';
  const key = normalizeLookupText(value).replace(/[^a-z0-9]+/g, '');
  if (/^(ff|fa|four ?seam|4seam|fourseam|fastball|si|sinker|ft|twoseam|2seam|fc|cutter|cutfastball)$/.test(key)) return 'fastball-family';
  return family || key;
}

function isFastballVelocityFamily(value = '') {
  return pitchVelocityFamilyKey(value) === 'fastball-family';
}

function pitchRowCategoryText(row = {}) {
  return visiblePitchCategoryName(row?.category || row?.pitchName || row?.pitchType || row?.pitch_type || row?.pitch_name || row?.name || row?.type || row?.PitchType || row?.['Pitch Type'] || '');
}

function pitchRowVelocityNumberFromKeys(row = {}, keys = []) {
  for (const key of keys) {
    const numeric = pitcherVelocityNumber(row?.[key]);
    if (Number.isFinite(numeric)) return numeric;
  }
  return null;
}

function savantPlayerPageUrl(playerId, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return '';
  const url = new URL(`https://baseballsavant.mlb.com/savant-player/${id}`);
  url.searchParams.set('stats', 'statcast-r-pitching-mlb');
  return url.toString();
}

function savantVisibleTextFromHtml(html = '') {
  const raw = String(html || '');
  try {
    if (typeof DOMParser !== 'undefined') {
      const doc = new DOMParser().parseFromString(raw, 'text/html');
      const text = doc?.body?.innerText || doc?.body?.textContent || '';
      if (text) return text;
    }
  } catch (_) {}
  return raw
    .replace(/<script[\s\S]*?<\/script>/gi, '\n')
    .replace(/<style[\s\S]*?<\/style>/gi, '\n')
    .replace(/<[^>]+>/g, '\n')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&#x27;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/\s+\n/g, '\n')
    .replace(/\n\s+/g, '\n');
}

function savantPitchNameFromPageText(value = '') {
  const text = cleanSummary(value)
    .replace(/\b(?:NYY|BOS|TOR|BAL|TB|CLE|DET|KC|CWS|MIN|HOU|TEX|SEA|LAA|OAK|ATH|ATL|PHI|NYM|MIA|WSH|MIL|CHC|STL|CIN|PIT|LAD|SD|SF|ARI|COL)\b\s+[LR]\b.*$/i, '')
    .replace(/\b[LR]\b\s+\d.*$/i, '')
    .trim();
  return text;
}

function parseSavantPlayerPagePitchVelocityRows(html = '', season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const targetSeason = String(season || '').trim();
  const text = savantVisibleTextFromHtml(html);
  const lines = text.split(/\r?\n/).map((line) => cleanSummary(line)).filter(Boolean);
  const buckets = new Map();
  const addRow = (pitchName, pitches, mph, source = 'Savant player page pitch table') => {
    const category = visiblePitchCategoryName(pitchName || '');
    const key = savantPitchCategoryKey(category);
    const count = Number(String(pitches || '').replace(/,/g, '')) || 0;
    const velo = pitcherVelocityNumber(mph);
    if (!key || !category || !Number.isFinite(velo) || velo < 70 || velo > 110) return;
    const existing = buckets.get(key) || { category, pitches: 0, velocityWeight: 0, velocityWeightDen: 0, maxVelocity: null, source };
    const weight = Math.max(1, count || 1);
    existing.category = existing.category || category;
    existing.pitches += count || 0;
    existing.velocityWeight += velo * weight;
    existing.velocityWeightDen += weight;
    existing.maxVelocity = Math.max(Number(existing.maxVelocity) || 0, velo);
    existing.pageAvgVelocity = Math.max(Number(existing.pageAvgVelocity) || 0, velo);
    existing.source = source;
    buckets.set(key, existing);
  };

  for (const line of lines) {
    if (targetSeason && !line.startsWith(`${targetSeason} `)) continue;
    if (!/(Fastball|Four Seamer|4-Seam|Sinker|Cutter|Slider|Sweeper|Curveball|Changeup|Split|Splitter|Knuckle Curve|Slow Curve|Slurve|Screwball|Forkball|Eephus)/i.test(line)) continue;

    // Movement table shape from Savant player page: 2026 4-Seam Fastball NYY R 601 97.7 ...
    let m = line.match(/^\s*(20\d{2})\s+(.+?)\s+(?:[A-Z]{2,3}\s+)?[LR]\s+([\d,]+)\s+([7-9]\d(?:\.\d)?|10\d(?:\.\d)?)\b/);
    if (m) {
      const pitchName = savantPitchNameFromPageText(m[2]);
      addRow(pitchName, m[3], m[4], 'Savant player page Movement Profile');
      continue;
    }

    // Spin-direction table shape: 2026 4-Seam Fastball 601 97.7 87 ...
    m = line.match(/^\s*(20\d{2})\s+(.+?)\s+([\d,]+)\s+([7-9]\d(?:\.\d)?|10\d(?:\.\d)?)\s+\d{1,3}\b/);
    if (m) {
      const pitchName = savantPitchNameFromPageText(m[2]);
      addRow(pitchName, m[3], m[4], 'Savant player page Spin Direction');
      continue;
    }
  }

  // Backup parser for compressed player-page text where the movement table has fewer line breaks.
  const compact = text.replace(/\s+/g, ' ');
  const pitchPattern = /(20\d{2})\s+(4-Seam Fastball|Four Seamer|Fastball|Sinker|Cutter|Slider|Sweeper|Curveball|Knuckle Curve|Changeup|Split-Finger|Splitter|Forkball|Screwball|Slurve|Slow Curve|Eephus)\s+(?:[A-Z]{2,3}\s+)?[LR]\s+([\d,]+)\s+([7-9]\d(?:\.\d)?|10\d(?:\.\d)?)/gi;
  let match;
  while ((match = pitchPattern.exec(compact))) {
    if (targetSeason && match[1] !== targetSeason) continue;
    addRow(match[2], match[3], match[4], 'Savant player page compact pitch table');
  }

  const totalPitches = [...buckets.values()].reduce((sum, row) => sum + (Number(row.pitches) || 0), 0);
  return [...buckets.values()]
    .map((row) => {
      const avg = row.velocityWeightDen > 0 ? row.velocityWeight / row.velocityWeightDen : null;
      const max = Number(row.maxVelocity) > 0 ? Number(row.maxVelocity) : avg;
      return {
        category: row.category,
        pitches: row.pitches,
        pct: totalPitches > 0 && row.pitches > 0 ? (row.pitches / totalPitches) * 100 : null,
        velocity: avg,
        avgVelocity: avg,
        maxVelocity: max,
        topVelocity: max,
        pageAvgVelocity: avg,
        pageVelocitySource: row.source,
        source: row.source,
        pitcherMetricSource: true,
        pitcherSource: true,
      };
    })
    .filter((row) => Number(row.pitches) > 0 || Number.isFinite(row.velocity))
    .sort((a, b) => Number(b.pitches || 0) - Number(a.pitches || 0));
}

async function getSavantPlayerPagePitchVelocityRows(playerId, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const cacheKey = `${id}:pitcher:${season}:savant-player-page-velos-v1`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const promise = getText(savantPlayerPageUrl(id, season))
    .then((html) => parseSavantPlayerPagePitchVelocityRows(html, season))
    .catch((error) => {
      savantPitchStrengthCache.delete(cacheKey);
      throw error;
    });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}


function savantPlayerPagePitchNumber(value) {
  if (value === null || value === undefined || value === '' || value === '--' || value === '---') return null;
  const numeric = Number(String(value).replace(/,/g, '').replace(/%/g, '').replace(/^\./, '0.'));
  return Number.isFinite(numeric) ? numeric : null;
}

function parseSavantPlayerPageRunValuePitchRows(html = '', season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const targetSeason = String(season || '').trim();
  const text = savantVisibleTextFromHtml(html);
  const lines = text.split(/\r?\n/).map((line) => cleanSummary(line)).filter(Boolean);
  const compact = text.replace(/\s+/g, ' ');
  const allLines = [...lines, compact];
  const pitchNames = [
    '4-Seam Fastball', 'Four-Seam Fastball', 'Four Seamer', '2-Seam Fastball', 'Two-Seam Fastball',
    'Knuckle Curve', 'Slow Curve', 'Split-Finger', 'Split Finger', 'Changeup', 'Curveball',
    'Fastball', 'Sinker', 'Cutter', 'Slider', 'Sweeper', 'Splitter', 'Forkball', 'Screwball', 'Slurve', 'Eephus'
  ];
  const pitchPattern = pitchNames
    .slice()
    .sort((a, b) => b.length - a.length)
    .map((name) => name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+'))
    .join('|');
  const rowPattern = new RegExp(`(?:^|\\s)(${targetSeason || '20\\d{2}'})\\s+(${pitchPattern})\\s+([\\s\\S]*?)(?=\\s+20\\d{2}\\s+(?:${pitchPattern})\\s+|$)`, 'gi');
  const byKey = new Map();
  for (const source of allLines) {
    if (targetSeason && !String(source).includes(targetSeason)) continue;
    rowPattern.lastIndex = 0;
    let match;
    while ((match = rowPattern.exec(source))) {
      if (targetSeason && match[1] !== targetSeason) continue;
      const category = visiblePitchCategoryName(match[2]);
      const key = savantPitchCategoryKey(category);
      if (!key || !category) continue;
      const nums = String(match[3] || '').match(/--|-?\d+(?:\.\d+)?|-?\.\d+/g) || [];
      // Run Values by Pitch Type has: RV/100, RV, Pitches, %, PA, BA, SLG, wOBA, Whiff%, K%, PutAway%, xBA, xSLG, xwOBA, HardHit%.
      if (nums.length < 14) continue;
      const pitches = savantPlayerPagePitchNumber(nums[2]);
      const pct = savantPlayerPagePitchNumber(nums[3]);
      const pa = savantPlayerPagePitchNumber(nums[4]);
      if (!Number.isFinite(pitches) || pitches <= 0 || !Number.isFinite(pct)) continue;
      const row = {
        category,
        pitches,
        pct,
        pa: Number.isFinite(pa) ? pa : 0,
        avg: savantPlayerPagePitchNumber(nums[5]),
        slg: savantPlayerPagePitchNumber(nums[6]),
        woba: savantPlayerPagePitchNumber(nums[7]),
        whiff: savantPlayerPagePitchNumber(nums[8]),
        kPct: savantPlayerPagePitchNumber(nums[9]),
        putAway: savantPlayerPagePitchNumber(nums[10]),
        xba: savantPlayerPagePitchNumber(nums[11]),
        xslg: savantPlayerPagePitchNumber(nums[12]),
        xwoba: savantPlayerPagePitchNumber(nums[13]),
        hardHit: savantPlayerPagePitchNumber(nums[14]),
        source: 'Savant player page Run Values by Pitch Type',
        sourceLabel: `${match[1]} Baseball Savant`,
        playerType: 'pitcher',
        pitcherMetricSource: true,
        pitcherSource: true,
      };
      const existing = byKey.get(key);
      if (!existing || Number(row.pitches) > Number(existing.pitches || 0)) byKey.set(key, row);
    }
  }
  return [...byKey.values()].sort((a, b) => Number(b.pitches || 0) - Number(a.pitches || 0));
}

async function getSavantPlayerPageRunValuePitchRows(playerId, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const cacheKey = `${id}:pitcher:${season}:savant-player-page-run-values-v1`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const promise = getText(savantPlayerPageUrl(id, season))
    .then((html) => parseSavantPlayerPageRunValuePitchRows(html, season))
    .catch((error) => {
      savantPitchStrengthCache.delete(cacheKey);
      throw error;
    });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}

function mergePitcherPitchRowsWithPageRunValues(groupedRows = [], pageRows = []) {
  const rows = Array.isArray(groupedRows) ? groupedRows : [];
  const page = Array.isArray(pageRows) ? pageRows : [];
  if (!page.length) return rows;
  const pageByKey = new Map();
  for (const row of page) {
    const key = savantPitchCategoryKey(row.category);
    if (key) pageByKey.set(key, row);
  }
  const seen = new Set();
  const merged = rows.map((row) => {
    const key = savantPitchCategoryKey(row.category);
    const pageRow = key ? pageByKey.get(key) : null;
    if (!pageRow) return row;
    seen.add(key);
    return {
      ...pageRow,
      ...row,
      pitches: Number(row.pitches) > 0 ? row.pitches : pageRow.pitches,
      pct: Number.isFinite(Number(row.pct)) ? row.pct : pageRow.pct,
      pa: Number(row.pa) > 0 ? row.pa : pageRow.pa,
      avg: Number.isFinite(Number(row.avg)) ? row.avg : pageRow.avg,
      slg: Number.isFinite(Number(row.slg)) ? row.slg : pageRow.slg,
      woba: Number.isFinite(Number(row.woba)) ? row.woba : pageRow.woba,
      xwoba: Number.isFinite(Number(row.xwoba)) ? row.xwoba : pageRow.xwoba,
      whiff: Number.isFinite(Number(row.whiff)) ? row.whiff : pageRow.whiff,
      hardHit: Number.isFinite(Number(row.hardHit)) ? row.hardHit : pageRow.hardHit,
      putAway: Number.isFinite(Number(row.putAway)) ? row.putAway : pageRow.putAway,
      source: row.source || pageRow.source,
      sourceLabel: row.sourceLabel || pageRow.sourceLabel,
      playerType: 'pitcher',
      pitcherMetricSource: true,
      pitcherSource: true,
    };
  });
  for (const row of page) {
    const key = savantPitchCategoryKey(row.category);
    if (key && !seen.has(key)) merged.push(row);
  }
  return merged.sort((a, b) => Number(b.pct || b.pitches || 0) - Number(a.pct || a.pitches || 0));
}

function mergePitcherPitchRowsWithPageVelocity(groupedRows = [], pageRows = []) {
  const rows = Array.isArray(groupedRows) ? groupedRows : [];
  const page = Array.isArray(pageRows) ? pageRows : [];
  if (!page.length) return rows;
  const pageByKey = new Map();
  for (const row of page) {
    const key = savantPitchCategoryKey(row.category);
    if (!key) continue;
    const existing = pageByKey.get(key);
    if (!existing || Number(row.maxVelocity || row.velocity || 0) > Number(existing.maxVelocity || existing.velocity || 0)) pageByKey.set(key, row);
  }
  const seen = new Set();
  const merged = rows.map((row) => {
    const key = savantPitchCategoryKey(row.category);
    const pageRow = key ? pageByKey.get(key) : null;
    if (!pageRow) return row;
    seen.add(key);
    const pageAvg = pitcherVelocityNumber(pageRow.avgVelocity ?? pageRow.velocity ?? pageRow.pageAvgVelocity);
    const pageMaxEvidence = pitcherVelocityNumber(pageRow.maxVelocity ?? pageRow.topVelocity ?? pageRow.velocity);
    const currentAvg = pitcherVelocityNumber(row.avgVelocity ?? row.velocity);
    const currentMax = pitcherVelocityNumber(row.maxVelocity ?? row.topVelocity ?? row.maxVelo);
    const mergedMax = [currentMax, pageMaxEvidence].filter(Number.isFinite).reduce((max, value) => Math.max(max, value), null);
    return {
      ...row,
      pageAvgVelocity: pageAvg,
      pageVelocitySource: pageRow.pageVelocitySource || pageRow.source || 'Savant player page pitch table',
      velocity: Number.isFinite(currentAvg) ? currentAvg : (Number.isFinite(pageAvg) ? pageAvg : row.velocity),
      avgVelocity: Number.isFinite(currentAvg) ? currentAvg : (Number.isFinite(pageAvg) ? pageAvg : row.avgVelocity),
      maxVelocity: Number.isFinite(mergedMax) ? mergedMax : row.maxVelocity,
      topVelocity: Number.isFinite(mergedMax) ? mergedMax : row.topVelocity,
      maxVelo: Number.isFinite(mergedMax) ? mergedMax : row.maxVelo,
      pitchPagePitches: Number.isFinite(Number(pageRow.pitches)) ? Number(pageRow.pitches) : row.pitchPagePitches,
    };
  });
  for (const pageRow of page) {
    const key = savantPitchCategoryKey(pageRow.category);
    if (!key || seen.has(key)) continue;
    merged.push(pageRow);
  }
  return merged.sort((a, b) => Number(b.pitches || b.pitchPagePitches || 0) - Number(a.pitches || a.pitchPagePitches || 0));
}

function mergePitcherPitchRowsWithEventVelocity(groupedRows = [], eventRows = []) {
  if (!Array.isArray(groupedRows) || !groupedRows.length || !Array.isArray(eventRows) || !eventRows.length) return groupedRows || [];
  const eventAggregates = aggregateSavantPitchRows(eventRows, true, true);
  if (!eventAggregates.length) return groupedRows;
  const eventByKey = new Map();
  for (const row of eventAggregates) {
    const key = savantPitchCategoryKey(row.category);
    if (!key) continue;
    const existing = eventByKey.get(key);
    const rowPriority = Math.max(Number(row.maxVelocity || 0), Number(row.maxBreak || row.breakAmount || 0));
    const existingPriority = Math.max(Number(existing?.maxVelocity || 0), Number(existing?.maxBreak || existing?.breakAmount || 0));
    if (!existing || rowPriority > existingPriority) eventByKey.set(key, row);
  }
  return groupedRows.map((row) => {
    const key = savantPitchCategoryKey(row.category);
    const event = key ? eventByKey.get(key) : null;
    if (!event) return row;
    const eventMax = pitcherVelocityNumber(event.maxVelocity ?? event.topVelocity ?? event.velocity);
    const currentMax = pitcherVelocityNumber(row.maxVelocity ?? row.topVelocity ?? row.pitchMaxVelocity);
    const mergedMax = Number.isFinite(eventMax) && Number.isFinite(currentMax) ? Math.max(eventMax, currentMax) : (eventMax ?? currentMax);
    const eventAvg = pitcherVelocityNumber(event.avgVelocity ?? event.velocity);
    const eventBreak = Number(event.breakAmount ?? event.avgBreak);
    const eventMaxBreak = Number(event.maxBreak ?? event.topBreak ?? eventBreak);
    const currentBreak = Number(row.breakAmount ?? row.avgBreak);
    const currentMaxBreak = Number(row.maxBreak ?? row.topBreak ?? currentBreak);
    const mergedMaxBreak = Number.isFinite(eventMaxBreak) && Number.isFinite(currentMaxBreak) ? Math.max(eventMaxBreak, currentMaxBreak) : (Number.isFinite(eventMaxBreak) ? eventMaxBreak : currentMaxBreak);
    return {
      ...row,
      eventVelocitySource: 'Savant pitch events',
      eventBreakSource: 'Savant pitch events',
      eventPitchCount: event.pitches,
      eventMaxVelocity: eventMax,
      maxVelocity: Number.isFinite(mergedMax) ? mergedMax : row.maxVelocity,
      topVelocity: Number.isFinite(mergedMax) ? mergedMax : row.topVelocity,
      maxVelo: Number.isFinite(mergedMax) ? mergedMax : row.maxVelo,
      avgVelocity: Number.isFinite(row.avgVelocity) ? row.avgVelocity : (Number.isFinite(eventAvg) ? eventAvg : row.avgVelocity),
      velocity: Number.isFinite(row.velocity) ? row.velocity : (Number.isFinite(eventAvg) ? eventAvg : row.velocity),
      breakAmount: Number.isFinite(currentBreak) ? currentBreak : (Number.isFinite(eventBreak) ? eventBreak : row.breakAmount),
      avgBreak: Number.isFinite(currentBreak) ? currentBreak : (Number.isFinite(eventBreak) ? eventBreak : row.avgBreak),
      maxBreak: Number.isFinite(mergedMaxBreak) ? mergedMaxBreak : row.maxBreak,
      topBreak: Number.isFinite(mergedMaxBreak) ? mergedMaxBreak : row.topBreak,
    };
  });
}

function savantPitchEventsUrl(playerId, playerType = 'batter', season = seasonForDate(dateInput.value || formatDate(new Date())), filters = {}) {
  const url = new URL('https://baseballsavant.mlb.com/statcast_search/csv');
  url.searchParams.set('all', 'true');
  url.searchParams.set('type', 'details');
  url.searchParams.set('hfGT', 'R|');
  url.searchParams.set('hfSea', `${season}|`);
  const dateFrom = calendarDateOnly(filters?.gameDateGt || filters?.dateFrom || filters?.pitchDataFromDate || `${season}-03-01`);
  const dateThrough = calendarDateOnly(filters?.gameDateLt || filters?.dateThrough || filters?.pitchDataThroughDate || `${season}-12-31`);
  if (dateFrom) url.searchParams.set('game_date_gt', dateFrom);
  if (dateThrough) url.searchParams.set('game_date_lt', dateThrough);
  url.searchParams.set('player_type', playerType === 'pitcher' ? 'pitcher' : 'batter');
  url.searchParams.set('min_pitches', '0');
  url.searchParams.set('min_results', '0');
  url.searchParams.set('min_pas', '0');
  url.searchParams.set('sort_col', 'game_date');
  url.searchParams.set('sort_order', 'desc');
  url.searchParams.append(playerType === 'pitcher' ? 'pitchers_lookup[]' : 'batters_lookup[]', String(playerId));
  return url.toString();
}

function savantPitcherFastballMaxVelocityUrl(playerId, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const ids = (Array.isArray(playerId) ? playerId : [playerId])
    .map(Number)
    .filter((id) => Number.isFinite(id) && id > 0);
  if (!ids.length) return '';
  const url = new URL('https://baseballsavant.mlb.com/statcast_search/csv');
  url.searchParams.set('all', 'true');
  url.searchParams.set('type', 'details');
  url.searchParams.set('hfGT', 'R|');
  url.searchParams.set('hfSea', `${season}|`);
  url.searchParams.set('game_date_gt', `${season}-03-01`);
  url.searchParams.set('game_date_lt', `${season}-12-31`);
  url.searchParams.set('hfPT', 'FF|FA|SI|FT|FC|');
  url.searchParams.set('player_type', 'pitcher');
  url.searchParams.set('min_pitches', '0');
  url.searchParams.set('min_results', '0');
  url.searchParams.set('min_pas', '0');
  url.searchParams.set('player_event_sort', 'api_p_release_speed');
  url.searchParams.set('sort_col', 'api_p_release_speed');
  url.searchParams.set('sort_order', 'desc');
  [...new Set(ids)].forEach((id) => url.searchParams.append('pitchers_lookup[]', String(id)));
  return url.toString();
}

function parseSavantFastballMaxVelocityRows(rows = []) {
  let maxVelocity = null;
  let velocityTotal = 0;
  let velocityCount = 0;
  const familyRows = [];
  for (const row of rows || []) {
    const category = savantExactPitchCategory(row)
      || savantPitchCategory(row)
      || pitchRowCategoryText(row)
      || pitchRowCategoryText({ category: csvValue(row, ['pitch_type', 'Pitch Type', 'pitch_name', 'Pitch Name']) });
    if (!isFastballVelocityFamily(category)) continue;
    const velocity = pitcherVelocityNumber(csvValue(row, SAVANT_VELOCITY_KEYS));
    if (!Number.isFinite(velocity)) continue;
    maxVelocity = Math.max(Number(maxVelocity) || 0, velocity);
    velocityTotal += velocity;
    velocityCount += 1;
    familyRows.push({ category: visiblePitchCategoryName(category), velocity });
  }
  if (!Number.isFinite(maxVelocity) || maxVelocity <= 0) return null;
  return {
    category: 'Fastball',
    maxVelocity,
    topVelocity: maxVelocity,
    maxVelo: maxVelocity,
    avgVelocity: velocityCount > 0 ? velocityTotal / velocityCount : null,
    velocity: velocityCount > 0 ? velocityTotal / velocityCount : maxVelocity,
    pitches: velocityCount,
    source: 'Savant Statcast fastball-family release_speed max',
    velocitySource: 'Savant Statcast fastball-family release_speed max',
    pitcherMetricSource: true,
    pitcherSource: true,
    rows: familyRows,
  };
}

function savantPitcherIdFromRow(row = {}) {
  const direct = Number(csvValue(row, ['pitcher', 'pitcher_id', 'player_id', 'Player ID', 'mlbam_id']) || row?.pitcher || row?.pitcher_id || row?.player_id);
  return Number.isFinite(direct) && direct > 0 ? direct : null;
}

function getSavantFastballBatchQueue(season) {
  const key = String(season || seasonForDate(dateInput.value || formatDate(new Date())));
  if (!savantFastballBatchQueues.has(key)) {
    savantFastballBatchQueues.set(key, { ids: new Set(), waiters: new Map(), timer: null, running: false });
  }
  return savantFastballBatchQueues.get(key);
}

function flushSavantFastballBatch(season) {
  const queue = getSavantFastballBatchQueue(season);
  if (queue.running) return;
  const allIds = [...queue.ids].filter((id) => Number.isFinite(Number(id)) && Number(id) > 0).map(Number);
  if (!allIds.length) return;
  const ids = allIds.slice(0, SAVANT_FASTBALL_BATCH_SIZE);
  const remaining = allIds.slice(SAVANT_FASTBALL_BATCH_SIZE);
  queue.ids.clear();
  for (const id of remaining) queue.ids.add(id);
  queue.running = true;
  const waiters = new Map();
  for (const id of ids) {
    waiters.set(id, queue.waiters.get(id) || []);
    queue.waiters.delete(id);
  }
  const url = savantPitcherFastballMaxVelocityUrl(ids, season);
  getText(url, { priority: 'background', timeoutMs: SAVANT_BACKGROUND_TEXT_TIMEOUT_MS })
    .then((text) => {
      const rows = parseCsvRows(text);
      const byPitcher = new Map();
      for (const row of rows) {
        const id = savantPitcherIdFromRow(row);
        if (!Number.isFinite(id) || id <= 0) continue;
        const list = byPitcher.get(id) || [];
        list.push(row);
        byPitcher.set(id, list);
      }
      for (const id of ids) {
        const parsed = parseSavantFastballMaxVelocityRows(byPitcher.get(id) || []);
        const key = `${id}:pitcher:${season}:fb-family-release-speed-max-batched-v2`;
        savantPitchStrengthCache.set(key, Promise.resolve(parsed));
        (waiters.get(id) || []).forEach(({ resolve }) => resolve(parsed));
      }
    })
    .catch(() => {
      for (const id of ids) {
        const key = `${id}:pitcher:${season}:fb-family-release-speed-max-batched-v2`;
        savantPitchStrengthCache.delete(key);
        (waiters.get(id) || []).forEach(({ resolve }) => resolve(null));
      }
    })
    .finally(() => {
      queue.running = false;
      if (queue.ids.size) {
        if (queue.timer) clearTimeout(queue.timer);
        queue.timer = setTimeout(() => {
          queue.timer = null;
          flushSavantFastballBatch(season);
        }, 140);
      }
    });
}

async function getSavantPitcherFastballMaxVelocity(playerId, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const cacheKey = `${id}:pitcher:${season}:fb-family-release-speed-max-batched-v2`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const promise = new Promise((resolve, reject) => {
    const queue = getSavantFastballBatchQueue(season);
    queue.ids.add(id);
    const list = queue.waiters.get(id) || [];
    list.push({ resolve, reject });
    queue.waiters.set(id, list);
    if (!queue.timer) {
      queue.timer = setTimeout(() => {
        queue.timer = null;
        flushSavantFastballBatch(season);
      }, 80);
    }
  });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}

async function getSavantPitcherFastballMaxVelocityWithFallback(playerId, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const currentSeason = Number(season);
  const primary = await getSavantPitcherFastballMaxVelocity(playerId, currentSeason).catch(() => null);
  if (primary && (Number(primary.pitches) > 0 || Number.isFinite(pitcherVelocityNumber(primary.avgVelocity ?? primary.velocity)))) return primary;
  const fallbackSeason = currentSeason - 1;
  const fallback = Number.isFinite(fallbackSeason) && fallbackSeason > 1900
    ? await getSavantPitcherFastballMaxVelocity(playerId, fallbackSeason).catch(() => null)
    : null;
  if (fallback) {
    return {
      ...fallback,
      sourceSeason: String(fallbackSeason),
      source: `${fallbackSeason} ${fallback.source || 'Savant Statcast fastball-family release_speed max'}`,
    };
  }
  const previousStart = await getMlbPitcherPreviousStartPitchMix(playerId, currentSeason).catch(() => null);
  const previousRows = listify(previousStart?.rows).filter((row) => isFastballVelocityFamily(row?.category));
  if (!previousRows.length) return primary;
  const total = previousRows.reduce((sum, row) => sum + (Number(row?.pitches) || 0), 0);
  let velocityTotal = 0;
  let velocityWeight = 0;
  let maxVelocity = null;
  for (const row of previousRows) {
    const avg = pitcherVelocityNumber(row?.avgVelocity ?? row?.velocity);
    const max = pitcherVelocityNumber(row?.maxVelocity ?? row?.topVelocity ?? row?.maxVelo ?? row?.velocity);
    const weight = Math.max(1, Number(row?.pitches) || 1);
    if (Number.isFinite(avg)) {
      velocityTotal += avg * weight;
      velocityWeight += weight;
    }
    if (Number.isFinite(max)) maxVelocity = Math.max(Number(maxVelocity) || 0, max);
  }
  const avgVelocity = velocityWeight > 0 ? velocityTotal / velocityWeight : null;
  if (!Number.isFinite(avgVelocity) && !Number.isFinite(maxVelocity)) return primary;
  return {
    category: 'Fastball',
    maxVelocity,
    topVelocity: maxVelocity,
    maxVelo: maxVelocity,
    avgVelocity,
    velocity: avgVelocity,
    pitches: total || velocityWeight,
    source: `MLB previous start pitch speeds${previousStart?.date ? ` ${previousStart.date}` : ''}`,
    velocitySource: 'MLB previous start pitch speeds',
    pitcherMetricSource: true,
    pitcherSource: true,
    rows: previousRows,
  };
}

function mergePitcherPitchRowsWithFastballMax(groupedRows = [], fastballMax = null) {
  const rows = Array.isArray(groupedRows) ? groupedRows.slice() : [];
  const maxVelocity = pitcherVelocityNumber(fastballMax?.maxVelocity ?? fastballMax?.topVelocity ?? fastballMax?.maxVelo);
  const avgVelocity = pitcherVelocityNumber(fastballMax?.avgVelocity ?? fastballMax?.velocity);
  if (!fastballMax || (!Number.isFinite(maxVelocity) && !Number.isFinite(avgVelocity))) return rows;
  let merged = false;
  const fallbackVelocity = Number.isFinite(maxVelocity) ? maxVelocity : avgVelocity;
  const source = cleanSummary(fastballMax.source || fastballMax.velocitySource || 'Savant Statcast fastball-family release_speed max');
  const patched = rows.map((row) => {
    const category = pitchRowCategoryText(row);
    if (!isFastballVelocityFamily(category)) return row;
    merged = true;
    const currentMax = pitcherVelocityNumber(row.maxVelocity ?? row.topVelocity ?? row.maxVelo ?? row.eventMaxVelocity ?? row.release_speed);
    const currentAvg = pitcherVelocityNumber(row.avgVelocity ?? row.velocity ?? row.avgVelo);
    const nextMax = Number.isFinite(currentMax) && Number.isFinite(fallbackVelocity) ? Math.max(currentMax, fallbackVelocity) : fallbackVelocity;
    return {
      ...row,
      velocity: Number.isFinite(currentAvg) ? currentAvg : (Number.isFinite(avgVelocity) ? avgVelocity : row.velocity),
      avgVelocity: Number.isFinite(currentAvg) ? currentAvg : (Number.isFinite(avgVelocity) ? avgVelocity : row.avgVelocity),
      maxVelocity: nextMax,
      topVelocity: nextMax,
      maxVelo: nextMax,
      eventMaxVelocity: nextMax,
      velocitySource: source,
      eventVelocitySource: source,
      pitcherMetricSource: true,
      pitcherSource: true,
    };
  });
  if (merged) return patched;
  return [{
    category: 'Fastball',
    pitches: Number(fastballMax.pitches) || 0,
    pct: null,
    velocity: Number.isFinite(avgVelocity) ? avgVelocity : fallbackVelocity,
    avgVelocity: Number.isFinite(avgVelocity) ? avgVelocity : fallbackVelocity,
    maxVelocity: fallbackVelocity,
    topVelocity: fallbackVelocity,
    maxVelo: fallbackVelocity,
    eventMaxVelocity: fallbackVelocity,
    velocitySource: source,
    eventVelocitySource: source,
    pitcherMetricSource: true,
    pitcherSource: true,
  }, ...rows];
}


function addSavantPitchEventRow(bucket, row = {}) {
  const event = cleanSummary(csvValue(row, ['events', 'Events', 'event'])).toLowerCase();
  const description = cleanSummary(csvValue(row, ['description', 'Description', 'des', 'pitch_description', 'Pitch Description', 'call', 'type'])).toLowerCase();
  const pitchResultText = `${description} ${event}`;
  const launchSpeed = savantRate(row, ['launch_speed', 'Launch Speed', 'exit_velocity', 'EV']);
  bucket.pitches += 1;
  addSavantPitchVelocity(bucket, row, 1);
  addSavantPitchBreak(bucket, row, 1);
  const isSwing = /(swinging_strike|swinging strike|swing and miss|missed_bunt|foul_tip|foul tip|foul|hit_into_play|hit into play|in_play|in play)/i.test(pitchResultText);
  const isWhiff = /(swinging_strike|swinging strike|swing and miss|swinging_strike_blocked|missed_bunt|foul_tip|foul tip)/i.test(pitchResultText);
  if (isSwing) addSavantWeighted(bucket, 'whiffWeight', 'whiffWeightDen', isWhiff ? 100 : 0, 1);
  if (Number.isFinite(launchSpeed)) {
    bucket.bbe += 1;
    addSavantWeighted(bucket, 'evWeight', 'evWeightDen', launchSpeed, 1);
    addSavantWeighted(bucket, 'hardHitWeight', 'hardHitWeightDen', launchSpeed >= 95 ? 100 : 0, 1);
  }
  if (!event) return;
  const isHit = ['single', 'double', 'triple', 'home_run'].includes(event);
  const isWalk = ['walk', 'intent_walk'].includes(event);
  const isHbp = event === 'hit_by_pitch';
  const isSacFly = event === 'sac_fly' || event === 'sac_fly_double_play';
  const noAtBatEvents = new Set(['walk', 'intent_walk', 'hit_by_pitch', 'sac_bunt', 'sac_fly', 'sac_fly_double_play', 'catcher_interf', 'catcher_interference']);
  const isPlateAppearance = isHit || isWalk || isHbp || isSacFly || Boolean(event);
  if (isPlateAppearance) bucket.pa += 1;
  if (isWalk) bucket.walks += 1;
  if (isHbp) bucket.hitByPitch += 1;
  if (isSacFly) bucket.sacFlies += 1;
  if (isHit) bucket.hits += 1;
  if (event === 'double') bucket.doubles += 1;
  if (event === 'triple') bucket.triples += 1;
  if (event === 'home_run') bucket.homeRuns += 1;
  if (!noAtBatEvents.has(event)) bucket.ab += 1;
  if (event === 'strikeout' || event === 'strikeout_double_play') bucket.strikeOuts += 1;
}

function aggregateSavantPitchRows(rows = [], exact = false, fromEvents = false) {
  const buckets = new Map();
  for (const row of rows) {
    const category = exact ? savantExactPitchCategory(row) : savantPitchCategory(row);
    if (!category) continue;
    if (!buckets.has(category)) buckets.set(category, emptyPitchStrengthBucket(category));
    if (fromEvents) addSavantPitchEventRow(buckets.get(category), row);
    else addSavantPitchRow(buckets.get(category), row);
  }
  const totalPitches = [...buckets.values()].reduce((sum, bucket) => sum + bucket.pitches, 0);
  return [...buckets.values()]
    .map((bucket) => finalizeSavantPitchBucket(bucket, totalPitches))
    .filter((row) => row.pitches > 0)
    .sort((a, b) => b.pitches - a.pitches);
}

function savantPitchEventGameKey(row = {}) {
  const gamePk = cleanSummary(csvValue(row, ['game_pk', 'gamePk', 'GamePk', 'Game PK']));
  const date = cleanSummary(csvValue(row, ['game_date', 'Game Date', 'date']));
  return `${date || 'unknown'}:${gamePk || 'unknown'}`;
}

function savantPitchEventDate(row = {}) {
  return cleanSummary(csvValue(row, ['game_date', 'Game Date', 'date']));
}


function savantPitchEventThrowHand(row = {}) {
  const value = handednessCode(csvValue(row, ['p_throws', 'pitcher_throws', 'Pitcher Throws', 'throws', 'pitcherThrowHand']));
  return value === 'L' || value === 'R' ? value : '';
}

function savantPitchCategoryKey(value = '') {
  const text = cleanSummary(value).toLowerCase();
  if (!text) return '';
  if (/^(ff|fa|4-seam|four-seam|four seam|4 seam)/.test(text)) return '4-seam';
  if (/^(si|sinker)/.test(text)) return 'sinker';
  if (/^(ft|2-seam|two-seam|two seam|2 seam)/.test(text)) return '2-seam';
  if (/^(fc|cutter|cut fastball)/.test(text)) return 'cutter';
  if (/^(sl|slider)/.test(text)) return 'slider';
  if (/^(st|sweeper)/.test(text)) return 'sweeper';
  if (/^(cu|curveball|curve)/.test(text)) return 'curveball';
  if (/^(kc|knuckle curve)/.test(text)) return 'knuckle curve';
  if (/^(ch|changeup|change up)/.test(text)) return 'changeup';
  if (/^(fs|splitter|split-finger)/.test(text)) return 'splitter';
  return text.replace(/[^a-z0-9]+/g, ' ').trim();
}

async function getSavantPitchEventRows(playerId, playerType = 'batter', season = seasonForDate(dateInput.value || formatDate(new Date())), filters = {}) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const type = playerType === 'pitcher' ? 'pitcher' : 'batter';
  const dateFrom = calendarDateOnly(filters?.gameDateGt || filters?.dateFrom || filters?.pitchDataFromDate || '');
  const dateThrough = calendarDateOnly(filters?.gameDateLt || filters?.dateThrough || filters?.pitchDataThroughDate || '');
  const dateSuffix = [dateFrom ? `from-${dateFrom}` : '', dateThrough ? `through-${dateThrough}` : ''].filter(Boolean).join(':');
  const cacheKey = `${id}:${type}:${season}:event-rows-v3${dateSuffix ? `:${dateSuffix}` : ''}`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const visibleDemand = filters?.visibleCardDemand === true || filters?.foreground === true || filters?.priority === 'visible';
  const textOptions = visibleDemand
    ? { priority: 'visible', noTimeout: true, noFailureCooldown: true }
    : { priority: type === 'pitcher' ? 'background' : 'normal', timeoutMs: type === 'pitcher' ? SAVANT_BACKGROUND_TEXT_TIMEOUT_MS : 5200 };
  const loadText = () => getText(savantPitchEventsUrl(id, type, season, filters), textOptions);
  const promise = loadText()
    .catch((error) => {
      if (!visibleDemand || type !== 'batter') throw error;
      return new Promise((resolve) => setTimeout(resolve, 180)).then(loadText);
    })
    .then((text) => parseCsvRows(text))
    .catch((error) => {
      savantPitchStrengthCache.delete(cacheKey);
      throw error;
    });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}

function savantPitchEventBatterStand(row = {}) {
  const value = handednessCode(csvValue(row, ['stand', 'batter_stands', 'batter_stand', 'Batter Stand', 'batterSide']));
  return value === 'L' || value === 'R' ? value : '';
}

async function getSavantHandedPitchBreakdownFromEvents(playerId, playerType = 'batter', season = seasonForDate(dateInput.value || formatDate(new Date())), filters = {}) {
  const pitcherThrowHand = savantPitchFilterThrowHand(filters);
  const batterStand = handednessCode(filters?.stand ?? filters?.batterStand ?? filters?.bats);
  const rows = await getSavantPitchEventRows(playerId, playerType, season, filters);
  const filteredRows = rows.filter((row) => {
    if (pitcherThrowHand && savantPitchEventThrowHand(row) !== pitcherThrowHand) return false;
    if (playerType === 'pitcher' && (batterStand === 'L' || batterStand === 'R') && savantPitchEventBatterStand(row) !== batterStand) return false;
    return true;
  });
  return aggregateSavantPitchRows(filteredRows, true, true).map((row) => ({ ...row, pitcherThrowHand, batterStand, source: 'Savant pitch events' }));
}

async function getMlbPitcherPreviousStartPitchMix(playerId, season = seasonForDate(dateInput.value || formatDate(new Date())), selectedDate = dateInput.value || formatDate(new Date())) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const dateLimit = String(selectedDate || formatDate(new Date()));
  const cacheKey = `${id}:mlb-previous-start-pitch-mix:${season}:${dateLimit}`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'pitching');
    url.searchParams.set('season', String(season));
    url.searchParams.set('gameType', 'R');
    const payload = await getJson(url.toString());
    const splits = listify(payload?.stats?.[0]?.splits)
      .filter((split) => split?.date && String(split.date) < dateLimit)
      .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
    const selected = splits.find((split) => {
      const stat = split?.stat || {};
      const started = statNumber(stat.gamesStarted) > 0;
      const pitches = statNumber(stat.numberOfPitches ?? stat.pitchesThrown ?? stat.pitches);
      const outs = inningsToOuts(stat.inningsPitched);
      return started || pitches >= 35 || outs >= 9;
    }) || splits[0] || null;
    const gamePk = Number(selected?.game?.gamePk ?? selected?.gamePk);
    if (!selected || !Number.isFinite(gamePk) || gamePk <= 0) return null;
    const feed = await getJson(`${MLB_API_BASE_LIVE}/game/${gamePk}/feed/live`);
    const buckets = new Map();
    let pitchCount = 0;
    for (const play of listify(feed?.liveData?.plays?.allPlays)) {
      const pitcherId = Number(play?.matchup?.pitcher?.id ?? play?.matchup?.pitcher?.person?.id);
      if (pitcherId !== id) continue;
      for (const event of listify(play?.playEvents)) {
        if (!event?.isPitch) continue;
        const raw = cleanSummary(event?.details?.type?.description || event?.details?.type?.code || event?.pitchData?.type || '');
        const category = savantExactPitchCategory({ pitch_name: raw, pitch_type: event?.details?.type?.code || raw }) || raw;
        const key = savantPitchCategoryKey(category);
        if (!key) continue;
        if (!buckets.has(key)) buckets.set(key, { category, pitches: 0, velocityWeight: 0, velocityWeightDen: 0, breakWeight: 0, breakWeightDen: 0, maxVelocity: null, maxBreak: null });
        const bucket = buckets.get(key);
        bucket.pitches += 1;
        const speed = pitcherVelocityNumber(event?.pitchData?.startSpeed ?? event?.pitchData?.endSpeed ?? event?.pitchData?.releaseSpeed ?? event?.pitchData?.velocity);
        if (Number.isFinite(speed)) {
          bucket.velocityWeight += speed;
          bucket.velocityWeightDen += 1;
          bucket.maxVelocity = Math.max(Number(bucket.maxVelocity) || 0, speed);
        }
        const breakAmount = savantPitchBreakAmount(event);
        if (Number.isFinite(breakAmount) && breakAmount > 0) {
          bucket.breakWeight += breakAmount;
          bucket.breakWeightDen += 1;
          bucket.maxBreak = Math.max(Number(bucket.maxBreak) || 0, breakAmount);
        }
        pitchCount += 1;
      }
    }
    if (!pitchCount) return null;
    const rows = [...buckets.values()]
      .map((row) => ({
        ...row,
        pct: (row.pitches / pitchCount) * 100,
        velocity: row.velocityWeightDen > 0 ? row.velocityWeight / row.velocityWeightDen : null,
        avgVelocity: row.velocityWeightDen > 0 ? row.velocityWeight / row.velocityWeightDen : null,
        breakAmount: row.breakWeightDen > 0 ? row.breakWeight / row.breakWeightDen : null,
        avgBreak: row.breakWeightDen > 0 ? row.breakWeight / row.breakWeightDen : null,
        maxBreak: Number(row.maxBreak) > 0 ? Number(row.maxBreak) : null,
        topBreak: Number(row.maxBreak) > 0 ? Number(row.maxBreak) : null,
        maxVelocity: Number(row.maxVelocity) > 0 ? Number(row.maxVelocity) : null,
        topVelocity: Number(row.maxVelocity) > 0 ? Number(row.maxVelocity) : null,
      }))
      .sort((a, b) => b.pitches - a.pitches);
    return { date: selected.date || '', gamePk, pitches: pitchCount, rows };
  })().catch((error) => {
    savantPitchStrengthCache.delete(cacheKey);
    throw error;
  });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}

function mergePreviousStartPitchMix(currentRows = [], previousStart = null) {
  if (!previousStart?.rows?.length) return currentRows;
  const previousRows = previousStart.rows.map((row) => ({
    ...row,
    lastStartPct: Number.isFinite(Number(row?.pct)) ? Number(row.pct) : null,
    lastStartPitches: Number.isFinite(Number(row?.pitches)) ? Number(row.pitches) : null,
    lastStartDate: previousStart.date || '',
    lastStartMaxVelocity: pitcherVelocityNumber(row?.maxVelocity ?? row?.topVelocity ?? row?.maxVelo),
    source: row?.source || 'MLB last start pitch feed',
    sourceLabel: row?.sourceLabel || (previousStart.date ? `Last start ${previousStart.date}` : 'Last MLB start'),
    pitcherMetricSource: true,
    pitcherSource: true,
  }));
  if (!Array.isArray(currentRows) || !currentRows.length) return previousRows;
  const previousByCategory = new Map(previousRows.map((row) => [savantPitchCategoryKey(row.category), row]).filter(([key]) => key));
  const seen = new Set();
  const mergedRows = (currentRows || []).map((row) => {
    const previous = previousByCategory.get(savantPitchCategoryKey(row.category));
    const currentMax = pitcherVelocityNumber(row.maxVelocity ?? row.topVelocity ?? row.maxVelo);
    const previousMax = pitcherVelocityNumber(previous?.maxVelocity ?? previous?.topVelocity ?? previous?.maxVelo);
    const mergedMax = Number.isFinite(currentMax) && Number.isFinite(previousMax) ? Math.max(currentMax, previousMax) : (currentMax ?? previousMax);
    const previousAvg = pitcherVelocityNumber(previous?.avgVelocity ?? previous?.velocity);
    if (previous) seen.add(savantPitchCategoryKey(row.category));
    return {
      ...row,
      lastStartPct: Number.isFinite(Number(previous?.pct)) ? Number(previous.pct) : null,
      lastStartPitches: Number.isFinite(Number(previous?.pitches)) ? Number(previous.pitches) : null,
      lastStartDate: previousStart.date || '',
      lastStartMaxVelocity: previousMax,
      maxVelocity: Number.isFinite(mergedMax) ? mergedMax : row.maxVelocity,
      topVelocity: Number.isFinite(mergedMax) ? mergedMax : row.topVelocity,
      maxVelo: Number.isFinite(mergedMax) ? mergedMax : row.maxVelo,
      avgVelocity: Number.isFinite(row.avgVelocity) ? row.avgVelocity : (Number.isFinite(previousAvg) ? previousAvg : row.avgVelocity),
      velocity: Number.isFinite(row.velocity) ? row.velocity : (Number.isFinite(previousAvg) ? previousAvg : row.velocity),
    };
  });
  for (const previous of previousRows) {
    const key = savantPitchCategoryKey(previous.category);
    if (key && !seen.has(key)) mergedRows.push(previous);
  }
  return mergedRows.sort((a, b) => Number(b.pct || 0) - Number(a.pct || 0));
}

async function getSavantPreviousStartPitchMix(playerId, season = seasonForDate(dateInput.value || formatDate(new Date())), selectedDate = dateInput.value || formatDate(new Date())) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const dateLimit = String(selectedDate || formatDate(new Date()));
  const cacheKey = `${id}:pitcher:${season}:previous-start-pitch-mix:${dateLimit}`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const promise = (async () => {
    const rows = await getSavantPitchEventRows(id, 'pitcher', season);
    const games = new Map();
    for (const row of rows) {
      const date = savantPitchEventDate(row);
      if (!date || String(date) >= dateLimit) continue;
      const key = savantPitchEventGameKey(row);
      if (!games.has(key)) games.set(key, { date, rows: [] });
      games.get(key).rows.push(row);
    }
    const sortedGames = [...games.values()]
      .filter((game) => game.rows.length > 0)
      .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
    const previousStart = sortedGames.find((game) => game.rows.length >= 35) || sortedGames[0] || null;
    if (!previousStart) return null;
    return {
      date: previousStart.date,
      pitches: previousStart.rows.length,
      rows: aggregateSavantPitchRows(previousStart.rows, true, true),
    };
  })().catch((error) => {
    savantPitchStrengthCache.delete(cacheKey);
    throw error;
  });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}

async function getSavantPitchStrength(playerId, playerType = 'batter', season = seasonForDate(dateInput.value || formatDate(new Date())), filters = {}) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const type = playerType === 'pitcher' ? 'pitcher' : 'batter';
  const cacheKey = `${id}:${type}:${season}${savantPitchFilterCacheSuffix(filters)}`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const promise = (async () => {
    const rows = parseCsvRows(await getText(savantPitchStrengthUrl(id, type, season, filters)));
    const pitcherThrowHand = savantPitchFilterThrowHand(filters);
    return aggregateSavantPitchRows(rows, false, false).map((row) => ({ ...row, pitcherThrowHand, playerType: type, pitcherMetricSource: type === 'pitcher', pitcherSource: type === 'pitcher' }));
  })().catch((error) => {
    savantPitchStrengthCache.delete(cacheKey);
    throw error;
  });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}

async function getSavantExactPitchBreakdown(playerId, playerType = 'batter', season = seasonForDate(dateInput.value || formatDate(new Date())), filters = {}) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const type = playerType === 'pitcher' ? 'pitcher' : 'batter';
  const pitcherThrowHand = savantPitchFilterThrowHand(filters);
  const cacheKey = `${id}:${type}:${season}:exact-aggregate-v5${savantPitchFilterCacheSuffix(filters)}`;
  if (savantPitchStrengthCache.has(cacheKey)) return savantPitchStrengthCache.get(cacheKey);
  const promise = (async () => {
    let groupedRows = [];
    try {
      groupedRows = parseCsvRows(await getText(savantPitchStrengthUrl(id, type, season, filters)));
    } catch (_) {
      groupedRows = [];
    }
    let grouped = aggregateSavantPitchRows(groupedRows, true, false).map((row) => ({ ...row, pitcherThrowHand, playerType: type, pitcherMetricSource: type === 'pitcher', pitcherSource: type === 'pitcher' }));
    if (type === 'pitcher') {
      const [pageRunRows, pageVelocityRows, eventRows] = await Promise.all([
        withTimeoutValue(getSavantPlayerPageRunValuePitchRows(id, season), 2600, []),
        withTimeoutValue(getSavantPlayerPagePitchVelocityRows(id, season), 2600, []),
        withTimeoutValue(getSavantPitchEventRows(id, 'pitcher', season), 2400, []),
      ]);
      grouped = mergePitcherPitchRowsWithPageRunValues(grouped, pageRunRows);
      grouped = mergePitcherPitchRowsWithPageVelocity(grouped, pageVelocityRows);
      grouped = mergePitcherPitchRowsWithEventVelocity(grouped, eventRows);
      if (grouped.length) return grouped.map((row) => ({ ...row, pitcherThrowHand, playerType: type, pitcherMetricSource: true, pitcherSource: true }));
    }
    if (grouped.length) return grouped;
    if (type === 'batter' && pitcherThrowHand) {
      return getSavantHandedPitchBreakdownFromEvents(id, type, season, filters);
    }
    return grouped;
  })().catch((error) => {
    savantPitchStrengthCache.delete(cacheKey);
    throw error;
  });
  savantPitchStrengthCache.set(cacheKey, promise);
  return promise;
}

function mergeVisiblePitchRowsByCategory(primaryRows = [], fallbackRows = []) {
  const byCategory = new Map();
  const addRows = (rows = [], prefer = false) => {
    for (const row of listify(rows)) {
      const category = visiblePitchCategoryName(row?.category || row?.pitchName || row?.pitchType || '');
      if (!category) continue;
      const key = savantPitchCategoryKey(category) || pitchStrengthMatchKey(category) || category.toLowerCase();
      const existing = byCategory.get(key);
      if (!existing) {
        byCategory.set(key, { ...row, category });
        continue;
      }
      if (!prefer) continue;
      byCategory.set(key, {
        ...existing,
        ...Object.fromEntries(Object.entries(row || {}).filter(([, value]) => value !== undefined && value !== null && String(value).trim() !== '')),
        category,
      });
    }
  };
  addRows(fallbackRows, false);
  addRows(primaryRows, true);
  return [...byCategory.values()]
    .filter((row) => visiblePitchCategoryName(row?.category))
    .sort((a, b) => (Number(b?.pitches ?? b?.pct ?? b?.usagePct ?? 0) || 0) - (Number(a?.pitches ?? a?.pct ?? a?.usagePct ?? 0) || 0));
}

async function getVisiblePitchBreakdown(playerId, playerType = 'batter', timeoutMs = 4200, filters = {}, options = {}) {
  const currentSeason = Number(options?.season) || seasonForDate(dateInput.value || formatDate(new Date()));
  const fallbackSeason = Number(options?.fallbackSeason);
  const fallbackPitchThroughDate = calendarDateOnly(options?.pitchDataThroughDate || options?.fallbackPitchDataThroughDate || '');
  const sourceLabel = cleanSummary(options?.sourceLabel || (Number.isFinite(fallbackSeason) && fallbackSeason > 1900 ? `${fallbackSeason} Baseball Savant` : ''));
  const tagRows = (rows = [], targetSeason, label = '') => rows.map((row) => ({
    ...row,
    sourceSeason: String(targetSeason),
    ...(label ? { sourceLabel: label } : {}),
  }));
  const readPlayerPagePitchRowsForSeason = async (targetSeason, targetTimeoutMs = timeoutMs, label = '') => {
    if (playerType !== 'pitcher') return [];
    const [pageRunRows, pageVelocityRows] = await Promise.all([
      withTimeoutValue(getSavantPlayerPageRunValuePitchRows(playerId, targetSeason), Math.max(1800, Math.min(3200, targetTimeoutMs)), []),
      withTimeoutValue(getSavantPlayerPagePitchVelocityRows(playerId, targetSeason), Math.max(1800, Math.min(3200, targetTimeoutMs)), []),
    ]);
    const mergedPageRows = mergePitcherPitchRowsWithPageVelocity(pageRunRows, pageVelocityRows);
    return tagRows(visiblePitchRowsForPlayerType(mergedPageRows, playerType), targetSeason, label);
  };
  const readVisibleRowsForSeason = async (targetSeason, targetTimeoutMs = timeoutMs, label = '') => {
    const seasonFilters = (playerType === 'pitcher'
      && fallbackPitchThroughDate
      && Number(targetSeason) === Number(fallbackSeason))
      ? { ...filters, pitchDataThroughDate: fallbackPitchThroughDate }
      : filters;
    if (options?.preferFallbackSeason === true && playerType === 'pitcher') {
      const pageFirstRows = await readPlayerPagePitchRowsForSeason(targetSeason, Math.max(2600, Math.min(3600, targetTimeoutMs)), label);
      if (pageFirstRows.length) return pageFirstRows;
    }
    if (playerType === 'batter' && savantPitchFilterThrowHand(seasonFilters)) {
      const pitcherThrowHand = savantPitchFilterThrowHand(seasonFilters);
      const quickRows = await withTimeoutValue(getSavantPitchStrength(playerId, playerType, targetSeason, seasonFilters), Math.max(1800, Math.min(3400, targetTimeoutMs)), []);
      const visibleQuickRows = visiblePitchRowsForPlayerType(quickRows || [], playerType);
      if (options?.allowDeepBatterEvents !== true) {
        if (visibleQuickRows.length) return tagRows(visibleQuickRows, targetSeason, label);
        const broadRows = await withTimeoutValue(getSavantPitchStrength(playerId, playerType, targetSeason, {}), Math.max(1500, Math.min(2400, targetTimeoutMs - 900)), []);
        const visibleBroadRows = visiblePitchRowsForPlayerType(broadRows || [], playerType);
        if (visibleBroadRows.length) return tagRows(visibleBroadRows.map((row) => ({ ...row, pitcherThrowHand, sourceLabel: row.sourceLabel || 'Savant season pitch mix' })), targetSeason, label || 'Savant season pitch mix');
        return [];
      }
      const eventFilters = options?.visibleCardDemand === true ? { ...seasonFilters, visibleCardDemand: true } : seasonFilters;
      const eventRows = options?.visibleCardDemand === true
        ? await getSavantHandedPitchBreakdownFromEvents(playerId, playerType, targetSeason, eventFilters).catch(() => [])
        : await withTimeoutValue(getSavantHandedPitchBreakdownFromEvents(playerId, playerType, targetSeason, eventFilters), Math.max(4200, Math.min(SAVANT_VISIBLE_TEXT_TIMEOUT_MS + 600, targetTimeoutMs + 2600)), []);
      const visibleEventRows = visiblePitchRowsForPlayerType(eventRows || [], playerType);
      let visibleBroadRows = [];
      if (options?.visibleCardDemand === true && (visibleEventRows.length < 2 || visibleQuickRows.length < 2)) {
        const broadRows = await getSavantPitchStrength(playerId, playerType, targetSeason, {}).catch(() => []);
        visibleBroadRows = visiblePitchRowsForPlayerType(broadRows || [], playerType);
      }
      const mergedVisibleRows = mergeVisiblePitchRowsByCategory(visibleEventRows, [...visibleQuickRows, ...visibleBroadRows]);
      if (mergedVisibleRows.length) return tagRows(mergedVisibleRows.map((row) => ({ ...row, pitcherThrowHand, sourceLabel: row.sourceLabel || 'Savant visible pitch mix' })), targetSeason, label || 'Savant visible pitch mix');
      const broadRows = await getSavantPitchStrength(playerId, playerType, targetSeason, {}).catch(() => []);
      visibleBroadRows = visiblePitchRowsForPlayerType(broadRows || [], playerType);
      if (visibleBroadRows.length) return tagRows(visibleBroadRows.map((row) => ({ ...row, pitcherThrowHand, sourceLabel: row.sourceLabel || 'Savant season pitch mix' })), targetSeason, label || 'Savant season pitch mix');
      return [];
    }

    const exactRows = await withTimeoutValue(getSavantExactPitchBreakdown(playerId, playerType, targetSeason, seasonFilters), targetTimeoutMs, null);
    const visibleExactRows = visiblePitchRowsForPlayerType(exactRows, playerType);
    if (visibleExactRows.length) return tagRows(visibleExactRows, targetSeason, label);

    if (playerType === 'pitcher') {
      const pageRows = await readPlayerPagePitchRowsForSeason(targetSeason, Math.max(2200, targetTimeoutMs - 700), label);
      if (pageRows.length) return pageRows;
    }

    const shouldTryEventRows = playerType === 'pitcher'
      || Boolean(savantPitchFilterThrowHand(filters));
    if (shouldTryEventRows) {
      const eventRows = await withTimeoutValue(getSavantHandedPitchBreakdownFromEvents(playerId, playerType, targetSeason, seasonFilters), Math.max(2200, targetTimeoutMs - 700), []);
      const visibleEventRows = visiblePitchRowsForPlayerType(eventRows, playerType);
      if (visibleEventRows.length) return tagRows(visibleEventRows, targetSeason, label);
    }

    const broadRows = await withTimeoutValue(getSavantPitchStrength(playerId, playerType, targetSeason, seasonFilters), Math.max(1800, targetTimeoutMs - 1000), []);
    return tagRows(visiblePitchRowsForPlayerType(broadRows, playerType), targetSeason, label);
  };

  if (options?.preferFallbackSeason === true && playerType === 'pitcher' && Number.isFinite(fallbackSeason) && fallbackSeason > 1900) {
    const fallbackRows = await readVisibleRowsForSeason(fallbackSeason, timeoutMs, sourceLabel || `${fallbackSeason} Baseball Savant`);
    if (fallbackRows.length) return fallbackRows;
  }

  const currentRows = await readVisibleRowsForSeason(currentSeason, timeoutMs);
  if (currentRows.length) return currentRows;

  if (playerType === 'pitcher' && Number.isFinite(fallbackSeason) && fallbackSeason > 1900 && fallbackSeason !== currentSeason) {
    const fallbackRows = await readVisibleRowsForSeason(fallbackSeason, Math.max(3200, timeoutMs - 500), sourceLabel || `${fallbackSeason} Baseball Savant`);
    if (fallbackRows.length) return fallbackRows;
  }

  return currentRows;
}

function pitchStrengthMatchKey(value = '') {
  const key = normalizeLookupText(value).replace(/[^a-z0-9]+/g, '');
  if (!key) return '';
  // Canonicalize Savant/UI labels before exact-pitch comparisons. The short labels
  // used in cards are often 4SFB/SIN/SWP/CB/CH, while CSV/page rows can use
  // FF/SI/ST/CU/etc. Without this, exact-pitch archetypes miss true matches.
  if (/^(ff|fa|fb|4fb|4sf|4sfb|4seam|4seamer|4seamfastball|fourseam|fourseamer|fourseamfastball)$/.test(key)) return 'fastball';
  if (/^(si|sin|sinker|twoseam|2seam|twoseamfastball|2seamfastball)$/.test(key)) return 'sinker';
  if (/^(fc|ct|cut|cutter|cutfastball)$/.test(key)) return 'cutter';
  if (/^(sl|slider)$/.test(key)) return 'slider';
  if (/^(st|swp|sweep|sweeper)$/.test(key)) return 'sweeper';
  if (/^(cu|cb|curve|curveball|kc|knucklecurve)$/.test(key)) return 'curveball';
  if (/^(ch|chg|change|changeup)$/.test(key)) return 'changeup';
  if (/^(fs|spl|split|splitter|splitfinger)$/.test(key)) return 'splitter';
  return key;
}

function findPitcherPitchStrengthRow(pitcherRows = [], batterRow = null) {
  const key = pitchStrengthMatchKey(batterRow?.category || batterRow?.pitchName || batterRow?.pitchType || '');
  if (!key) return null;
  return listify(pitcherRows).find((row) => pitchStrengthMatchKey(row?.category || row?.pitchName || row?.pitchType || '') === key) || null;
}

function pitchStrengthCompareCell(batterValue, pitcherValue, decimals = 3, forceLeadingZero = true) {
  return `${formatRateValue(batterValue, decimals, forceLeadingZero)} | ${formatRateValue(pitcherValue, decimals, forceLeadingZero)}`;
}

function pitchStrengthTableHtml(rows = null, playerType = 'batter', options = {}) {
  const title = playerType === 'pitcher' ? 'PITCH ARSENAL' : 'PITCH STRENGTH';
  if (!Array.isArray(rows)) {
    return `<strong>${title} <span class="player-stat-source">Savant</span></strong><div class="player-stat-loading">Loading pitch type data</div>`;
  }
  if (!rows.length) {
    return `<strong>${title} <span class="player-stat-source">Savant</span></strong><div class="player-stat-loading">Pitch type data unavailable</div>`;
  }
  const visibleRows = playerType === 'pitcher'
    ? rows.filter((row) => pitchClearsVisibleUsageThreshold(row, ['pct', 'usage', 'usagePct', 'pitch_percent']))
    : rows;
  if (!visibleRows.length) {
    return `<strong>${title} <span class="player-stat-source">Savant</span></strong><div class="player-stat-loading">Pitch type data unavailable</div>`;
  }
  const pitcherRows = listify(options.pitcherRows);
  const hasPitcherCompare = playerType !== 'pitcher' && pitcherRows.length;
  const sourceLabel = cleanSummary(options.sourceLabel || visibleRows.find((row) => cleanSummary(row?.sourceLabel))?.sourceLabel || 'Savant');
  const sourceHtml = `<span class="player-stat-source">${escapeHtml(sourceLabel || 'Savant')}</span>`;
  const body = visibleRows.map((row) => {
    const pitcherRow = hasPitcherCompare ? findPitcherPitchStrengthRow(pitcherRows, row) : null;
    return `
    <tr>
      <th>${escapeHtml(row.category)}</th>
      ${playerType === 'pitcher'
        ? `<td>${Math.round(row.pitches)}</td><td class="pitch-use-cell">${playerStatHeatMapUsageWithPreviousStartHtml(row)}</td><td>${formatRateValue(row.avg, 3, true)}</td><td>${formatRateValue(row.slg, 3, true)}</td>`
        : hasPitcherCompare
          ? `<td>${pitchStrengthCompareCell(row.avg, pitcherRow?.avg, 3, true)}</td><td>${pitchStrengthCompareCell(row.slg, pitcherRow?.slg, 3, true)}</td><td>${formatRateValue(row.ev, 1, false)}</td>`
          : `<td>${formatRateValue(row.avg, 3, true)}</td><td>${formatRateValue(row.slg, 3, true)}</td><td>${formatRateValue(row.ev, 1, false)}</td>`}
    </tr>
  `;
  }).join('');
  return `
    <strong>${title} ${sourceHtml}${hasPitcherCompare ? '<small class="player-stat-source"> Batter | Pitcher Allowed</small>' : ''}</strong>
    <div class="pitch-strength-table-wrap">
      <table class="player-stat-table pitch-strength-table">
        <thead>
          <tr>
            <th>Type</th>
            ${playerType === 'pitcher'
              ? '<th>#</th><th>%</th><th>BAA</th><th>SLG</th>'
              : '<th>AVG</th><th>SLG</th><th>EV</th>'}
          </tr>
        </thead>
        <tbody>${body}</tbody>
      </table>
    </div>
  `;
}

function pitchTypeRow(rows = [], category = '') {
  const target = cleanSummary(category).toLowerCase();
  return Array.isArray(rows)
    ? rows.find((row) => cleanSummary(row?.category).toLowerCase() === target) || null
    : null;
}

const ARSENAL_FAMILIES = [
  { key: 'fb', label: 'FB', name: 'Fastball', category: 'Fastball' },
  { key: 'breaking', label: 'Breaking', name: 'Breaking', category: 'Breaking' },
  { key: 'offspeed', label: 'Off-speed', name: 'Off-speed', category: 'Offspeed' },
];

function arsenalPercent(value) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return null;
  return Math.abs(numeric) <= 1 ? numeric * 100 : numeric;
}

function arsenalRate(value) {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

function arsenalMetricText(value, digits = 3, trimLeadingZero = true, suffix = '') {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? `${formatRateValue(numeric, digits, trimLeadingZero)}${suffix}` : '---';
}

function arsenalFamilyStats(rows = [], family) {
  const row = pitchTypeRow(rows, family.category) || {};
  const usagePct = arsenalPercent(row.pct);
  const whiff = arsenalPercent(row.whiff);
  const hardHit = arsenalPercent(row.hardHit);
  const chase = arsenalPercent(row.chase);
  const putAway = arsenalPercent(row.putAway);
  return {
    ...family,
    row,
    usagePct,
    avg: arsenalRate(row.avg),
    slg: arsenalRate(row.slg),
    woba: arsenalRate(row.woba),
    xwoba: arsenalRate(row.xwoba),
    ev: arsenalRate(row.ev),
    whiff,
    hardHit,
    chase,
    putAway,
    hrRate: arsenalRate(row.hrRate),
    homeRuns: statNumber(row.homeRuns),
    sample: statNumber(row.ab || row.pa || row.pitches),
  };
}

function arsenalHitterScore(stat = {}) {
  return clamp(
    predictionPoints(stat.avg, 0.180, 0.340, 24, { fallbackPoints: 10 })
      + predictionPoints(stat.slg, 0.300, 0.650, 30, { fallbackPoints: 12 })
      + predictionPoints(stat.xwoba ?? stat.woba, 0.280, 0.430, 18, { fallbackPoints: 8 })
      + predictionPoints(stat.ev, 86, 94, 10, { fallbackPoints: 4 })
      + predictionPoints(stat.hrRate, 0.015, 0.075, 10, { fallbackPoints: 3 })
      + predictionPoints(stat.hardHit, 32, 55, 8, { fallbackPoints: 3 })
      + predictionPoints(stat.whiff, 16, 38, 10, { invert: true, fallbackPoints: 5 }),
    0,
    100,
  );
}

function arsenalPitcherSuppressionScore(stat = {}) {
  return clamp(
    predictionPoints(stat.avg, 0.180, 0.330, 23, { invert: true, fallbackPoints: 11 })
      + predictionPoints(stat.slg, 0.300, 0.600, 28, { invert: true, fallbackPoints: 13 })
      + predictionPoints(stat.xwoba ?? stat.woba, 0.280, 0.430, 16, { invert: true, fallbackPoints: 8 })
      + predictionPoints(stat.ev, 86, 94, 8, { invert: true, fallbackPoints: 4 })
      + predictionPoints(stat.hrRate, 0.015, 0.070, 10, { invert: true, fallbackPoints: 4 })
      + predictionPoints(stat.hardHit, 32, 55, 7, { invert: true, fallbackPoints: 3 })
      + predictionPoints(stat.whiff, 16, 38, 8, { fallbackPoints: 3 }),
    0,
    100,
  );
}

function arsenalFamilyResultLabel(edge) {
  if (edge >= 14) return 'Batter edge';
  if (edge <= -14) return 'Pitcher edge';
  return 'Neutral';
}

function arsenalAdvantageLabel(score) {
  if (score >= 9) return 'Batter advantage';
  if (score <= -9) return 'Pitcher advantage';
  return 'Neutral';
}

function arsenalFamilyDescription(family) {
  const hitterText = [
    Number.isFinite(family.hitter.avg) ? `AVG ${formatRateValue(family.hitter.avg, 3, true)}` : '',
    Number.isFinite(family.hitter.slg) ? `SLG ${formatRateValue(family.hitter.slg, 3, true)}` : '',
  ].filter(Boolean).join(' / ') || 'limited batter data';
  const pitcherText = [
    Number.isFinite(family.pitcher.avg) ? `BAA ${formatRateValue(family.pitcher.avg, 3, true)}` : '',
    Number.isFinite(family.pitcher.slg) ? `SLG ${formatRateValue(family.pitcher.slg, 3, true)}` : '',
  ].filter(Boolean).join(' / ') || 'limited pitcher data';
  return `${family.label} ${arsenalMetricText(family.usagePct, 1, false, '%')} | ${hitterText} vs ${pitcherText}`;
}

function arsenalHrFamilyScore(family) {
  return clamp(
    predictionPoints(family.hitter.slg, 0.330, 0.700, 26, { fallbackPoints: 10 })
      + predictionPoints(family.hitter.hrRate, 0.015, 0.080, 20, { fallbackPoints: 6 })
      + predictionPoints(family.hitter.ev, 87, 95, 12, { fallbackPoints: 4 })
      + predictionPoints(family.hitter.hardHit, 35, 58, 12, { fallbackPoints: 4 })
      + predictionPoints(family.pitcher.slg, 0.330, 0.650, 18, { fallbackPoints: 7 })
      + predictionPoints(family.pitcher.hrRate, 0.015, 0.075, 12, { fallbackPoints: 4 }),
    0,
    100,
  );
}

function arsenalKFamilyScore(family) {
  return clamp(
    predictionPoints(family.hitter.whiff, 18, 42, 42, { fallbackPoints: 16 })
      + predictionPoints(family.pitcher.whiff, 18, 42, 42, { fallbackPoints: 16 })
      + predictionPoints(family.hitter.chase, 24, 40, 8, { fallbackPoints: 3 })
      + predictionPoints(family.pitcher.putAway, 16, 28, 8, { fallbackPoints: 3 }),
    0,
    100,
  );
}

function arsenalFamilyFlags(family) {
  const flags = [];
  const usage = Number(family.usagePct) || 0;
  const hitterStrong = family.hitterScore >= 64 || Number(family.hitter.slg) >= 0.560 || Number(family.hitter.avg) >= 0.300;
  const hitterWeak = family.hitterScore <= 40 || Number(family.hitter.avg) < 0.200 || Number(family.hitter.slg) < 0.320 || Number(family.hitter.whiff) >= 34;
  const pitcherStrong = family.pitcherScore >= 64 || Number(family.pitcher.avg) < 0.200;
  const pitcherWeak = family.pitcherScore <= 40 || Number(family.pitcher.slg) > 0.600;
  if (family.key === 'fb' && hitterStrong && usage >= 42) flags.push('Fastball Punisher');
  if (family.key === 'breaking' && hitterWeak && usage >= 25) flags.push('Breaking Ball Trap');
  if (family.key === 'offspeed' && Number(family.hitter.whiff) >= 32 && usage >= 15 && pitcherStrong) flags.push('Off-Speed Vulnerable');
  if (hitterWeak && usage < 15) flags.push('Pitcher Cannot Attack Weakness');
  if (hitterStrong && pitcherStrong && usage >= 20) flags.push('Strength-on-Strength');
  if (hitterWeak && pitcherWeak && usage >= 10) flags.push('Weakness-on-Weakness');
  return flags;
}


function arsenalRowRateValue(row = {}, keys = []) {
  for (const key of keys) {
    if (!Object.prototype.hasOwnProperty.call(row || {}, key)) continue;
    const value = predictionRateValue(row?.[key]);
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function arsenalRowNumberValue(row = {}, keys = []) {
  for (const key of keys) {
    if (!Object.prototype.hasOwnProperty.call(row || {}, key)) continue;
    const numeric = Number(String(row?.[key] ?? '').replace(/,/g, ''));
    if (Number.isFinite(numeric)) return numeric;
  }
  return null;
}

function arsenalExactRowCategory(row = {}) {
  return row?.category || row?.pitchName || row?.pitchType || row?.pitch_type || row?.pitch_name || row?.name || row?.type || '';
}

function arsenalExactDamageStack(batterRows = [], pitcherRows = []) {
  const batterSlgKeys = ['hitterSlg', 'batterSlg', 'batterSLG', 'slg', 'SLG', 'slugging', 'xslg', 'xSLG'];
  const pitcherSlgKeys = ['pitcherSlg', 'pitcherSLG', 'pitcherSlgAllowed', 'slgAllowedByPitcher', 'pitcherSlugging', 'pitcherSluggingAllowed', 'allowedSlugging', 'allowed_slg', 'slugging_allowed', 'pSlg', 'pSLG', 'slg', 'SLG', 'slugging', 'xslg', 'xSLG'];
  const batterAvgKeys = ['hitterAvg', 'batterAvg', 'batterAVG', 'avg', 'AVG', 'average'];
  const pitcherAvgKeys = ['pitcherAvg', 'pitcherBAA', 'pitcherAvgAllowed', 'avgAllowedByPitcher', 'baa', 'BAA', 'avg', 'AVG', 'average', 'batting_average_against'];
  const hitterHitKeys = ['hitterHits', 'batterHits', 'H', 'h', 'hits', 'hit'];
  const hitterAbKeys = ['hitterAb', 'hitterAB', 'batterAb', 'batterAB', 'AB', 'ab', 'abs', 'atBats', 'at_bats'];
  const hitterHrKeys = ['hitterHr', 'hitterHR', 'batterHr', 'batterHR', 'HR', 'hr', 'homeRuns', 'home_runs', 'home_run', 'hrs'];
  const pitcherHitKeys = ['pitcherHits', 'pitcherHitsAllowed', 'hitsAllowed', 'H', 'h', 'hits', 'hit'];
  const pitcherAbKeys = ['pitcherAb', 'pitcherAB', 'abAllowed', 'AB', 'ab', 'abs', 'atBats', 'at_bats', 'battersFacedAB'];
  const pitcherHrKeys = ['pitcherHr', 'pitcherHR', 'pitcherHrAllowed', 'hrAllowed', 'HR', 'hr', 'homeRuns', 'home_runs', 'home_run', 'hrs'];
  const pitcherByKey = new Map();
  for (const row of listify(pitcherRows)) {
    const key = pitchStrengthMatchKey(arsenalExactRowCategory(row));
    if (!key) continue;
    const usage = visiblePitchUsagePercent(row, ['visibleUsagePct', 'pitcherUsagePct', 'pct', 'usage', 'usagePct', 'pitch_percent', 'pitchPercent']);
    const pitcherSlg = arsenalRowRateValue(row, pitcherSlgKeys);
    const pitcherAb = arsenalRowNumberValue(row, pitcherAbKeys);
    const quality = (Number.isFinite(pitcherSlg) ? 1000 : 0) + (Number.isFinite(Number(pitcherAb)) ? Math.min(400, Number(pitcherAb)) : 0) + (Number.isFinite(Number(usage)) ? Number(usage) : 0);
    const current = pitcherByKey.get(key);
    if (!current || quality > Number(current.quality || 0)) {
      pitcherByKey.set(key, { row, usagePct: usage, pitcherSlg, quality });
    }
  }
  const hits = [];
  const seen = new Set();
  for (const batterRow of listify(batterRows)) {
    const key = pitchStrengthMatchKey(arsenalExactRowCategory(batterRow));
    if (!key || seen.has(key)) continue;
    const pitcherMatch = pitcherByKey.get(key);
    if (!pitcherMatch) continue;
    const pitcherRow = pitcherMatch.row || {};
    const hitterSlg = arsenalRowRateValue(batterRow, batterSlgKeys);
    const pitcherSlg = Number.isFinite(pitcherMatch.pitcherSlg) ? pitcherMatch.pitcherSlg : arsenalRowRateValue(pitcherRow, pitcherSlgKeys);
    const usage = Number(pitcherMatch.usagePct);
    if (!Number.isFinite(hitterSlg) || !Number.isFinite(pitcherSlg)) continue;
    if (Number.isFinite(usage) && usage > 0 && usage < 3) continue;
    if (hitterSlg >= 0.500 && pitcherSlg >= 0.500) {
      seen.add(key);
      const rawCategory = arsenalExactRowCategory(batterRow) || arsenalExactRowCategory(pitcherRow) || key;
      const category = typeof visiblePitchCategoryName === 'function' ? visiblePitchCategoryName(rawCategory) : cleanSummary(rawCategory);
      const hitterHits = arsenalRowNumberValue(batterRow, hitterHitKeys);
      const hitterAb = arsenalRowNumberValue(batterRow, hitterAbKeys);
      const hitterHr = arsenalRowNumberValue(batterRow, hitterHrKeys);
      const pitcherHits = arsenalRowNumberValue(pitcherRow, pitcherHitKeys);
      const pitcherAb = arsenalRowNumberValue(pitcherRow, pitcherAbKeys);
      const pitcherHr = arsenalRowNumberValue(pitcherRow, pitcherHrKeys);
      hits.push({
        key,
        category,
        hitterSlg,
        pitcherSlg,
        usagePct: Number.isFinite(usage) ? usage : null,
        hitterAvg: arsenalRowRateValue(batterRow, batterAvgKeys),
        pitcherAvg: arsenalRowRateValue(pitcherRow, pitcherAvgKeys),
        hitterHits: Number.isFinite(hitterHits) ? hitterHits : null,
        hitterAb: Number.isFinite(hitterAb) ? hitterAb : null,
        hitterHr: Number.isFinite(hitterHr) ? hitterHr : null,
        pitcherHits: Number.isFinite(pitcherHits) ? pitcherHits : null,
        pitcherAb: Number.isFinite(pitcherAb) ? pitcherAb : null,
        pitcherHr: Number.isFinite(pitcherHr) ? pitcherHr : null,
      });
    }
  }
  hits.sort((a, b) => ((Number(b.hitterSlg) + Number(b.pitcherSlg)) - (Number(a.hitterSlg) + Number(a.pitcherSlg))) || (Number(b.usagePct || 0) - Number(a.usagePct || 0)));
  const qualifies = hits.length >= 2;
  const avgExcess = hits.length
    ? hits.reduce((sum, row) => sum + Math.max(0, row.hitterSlg - 0.500) + Math.max(0, row.pitcherSlg - 0.500), 0) / hits.length
    : 0;
  const hitterHits = hits.reduce((sum, row) => sum + (Number.isFinite(Number(row.hitterHits)) ? Number(row.hitterHits) : 0), 0);
  const hitterAb = hits.reduce((sum, row) => sum + (Number.isFinite(Number(row.hitterAb)) ? Number(row.hitterAb) : 0), 0);
  const hitterHr = hits.reduce((sum, row) => sum + (Number.isFinite(Number(row.hitterHr)) ? Number(row.hitterHr) : 0), 0);
  const pitcherHits = hits.reduce((sum, row) => sum + (Number.isFinite(Number(row.pitcherHits)) ? Number(row.pitcherHits) : 0), 0);
  const pitcherAb = hits.reduce((sum, row) => sum + (Number.isFinite(Number(row.pitcherAb)) ? Number(row.pitcherAb) : 0), 0);
  const pitcherHr = hits.reduce((sum, row) => sum + (Number.isFinite(Number(row.pitcherHr)) ? Number(row.pitcherHr) : 0), 0);
  const score = qualifies ? clamp(Math.round(70 + Math.min(16, (hits.length - 2) * 6) + Math.min(14, avgExcess * 70)), 0, 100) : 0;
  return {
    rows: hits,
    count: hits.length,
    qualifies,
    score,
    hitterHits: hitterAb > 0 ? hitterHits : null,
    hitterAb: hitterAb > 0 ? hitterAb : null,
    hitterHr: hitterHr > 0 ? hitterHr : 0,
    pitcherHits: pitcherAb > 0 ? pitcherHits : null,
    pitcherAb: pitcherAb > 0 ? pitcherAb : null,
    pitcherHr: pitcherHr > 0 ? pitcherHr : 0,
    detail: hits.length
      ? hits.slice(0, 4).map((row) => `${row.category} H ${formatRateValue(row.hitterSlg, 3, true)} / P ${formatRateValue(row.pitcherSlg, 3, true)}${Number.isFinite(row.hitterAb) && row.hitterAb > 0 ? `, H-AB ${Math.round(Number(row.hitterHits || 0))}-${Math.round(Number(row.hitterAb))}` : ''}${Number.isFinite(row.usagePct) ? `, ${arsenalMetricText(row.usagePct, 1, false, '%')}` : ''}`).join('; ')
      : 'No exact pitch types with both hitter and pitcher SLG .500+',
  };
}

function arsenalImbalanceArchetypeFromDamageStack(stack = null) {
  if (!stack?.qualifies) return null;
  const score = clamp(Math.round(stack.score || 72), 0, 100);
  return {
    letter: 'I',
    label: 'Arsenal Imbalance',
    score,
    confidence: score,
    isPrimary: true,
    isSecondary: true,
    title: `Arsenal Imbalance: two or more exact pitches are .500+ SLG for both hitter and pitcher allowed. ${stack.detail}.`,
    damageStack: stack,
    contextualImbalance: true,
  };
}

function buildArsenalMatchup(batterRows = [], pitcherRows = [], context = {}) {
  if (!Array.isArray(batterRows) || !Array.isArray(pitcherRows) || !batterRows.length || !pitcherRows.length) {
    return null;
  }
  const rawFamilies = ARSENAL_FAMILIES.map((family) => {
    const hitter = arsenalFamilyStats(batterRows, family);
    const pitcher = arsenalFamilyStats(pitcherRows, family);
    const hitterScore = arsenalHitterScore(hitter);
    const pitcherScore = arsenalPitcherSuppressionScore(pitcher);
    const edge = hitterScore - pitcherScore;
    return {
      ...family,
      usagePct: Number.isFinite(Number(pitcher.usagePct)) ? Number(pitcher.usagePct) : null,
      hitter,
      pitcher,
      hitterScore,
      pitcherScore,
      edge,
      result: arsenalFamilyResultLabel(edge),
    };
  });
  const usageTotal = rawFamilies.reduce((sum, family) => sum + (Number.isFinite(Number(family.usagePct)) ? Number(family.usagePct) : 0), 0);
  const families = rawFamilies.map((family) => {
    const weight = usageTotal > 0 && Number.isFinite(Number(family.usagePct)) ? Number(family.usagePct) / usageTotal : 1 / rawFamilies.length;
    return {
      ...family,
      weight,
      weightedEdge: family.edge * weight,
      hrScore: arsenalHrFamilyScore(family),
      kScore: arsenalKFamilyScore(family),
    };
  });
  const overallScore = Math.round(families.reduce((sum, family) => sum + family.weightedEdge, 0));
  const hrThreatScore = clamp(Math.round(
    families.reduce((sum, family) => sum + (family.hrScore * family.weight), 0)
      + (context.handStrong ? 7 : 0)
      + predictionPoints(context.weakness?.hr9, 0.8, 1.8, 8, { fallbackPoints: 2 })
      + predictionPoints(context.weakness?.handSlg, 0.390, 0.620, 7, { fallbackPoints: 2 }),
  ), 0, 100);
  const kRiskScore = clamp(Math.round(
    families.reduce((sum, family) => sum + (family.kScore * family.weight), 0)
      + predictionPoints(context.weakness?.k9, 6.5, 11.5, 8, { fallbackPoints: 2 }),
  ), 0, 100);
  const damageStack = arsenalExactDamageStack(batterRows, pitcherRows);
  const flags = [...new Set([
    ...families.flatMap(arsenalFamilyFlags),
    ...(damageStack.qualifies ? ['Arsenal Imbalance Damage Stack'] : []),
  ])];
  const strongest = [...families].sort((a, b) => Math.abs(b.weightedEdge) - Math.abs(a.weightedEdge))[0] || families[0];
  const label = arsenalAdvantageLabel(overallScore);
  const hitterName = context.batterName || 'the hitter';
  const pitcherName = context.pitcherName || 'the pitcher';
  const explanation = strongest
    ? `${label} because ${pitcherName} uses ${strongest.name.toLowerCase()} ${arsenalMetricText(strongest.usagePct, 1, false, '%')} of the time and ${hitterName} ${strongest.edge >= 0 ? 'matches up well' : 'is vulnerable'} there. ${arsenalFamilyDescription(strongest)}.`
    : `${label} from the available pitch-family data.`;
  return {
    label,
    overallScore,
    hrThreatScore,
    kRiskScore,
    families,
    flags,
    damageStack,
    explanation: damageStack.qualifies ? `${explanation} Damage stack: ${damageStack.detail}.` : explanation,
  };
}

function arsenalMatchupQualifies(matchup = null) {
  if (!matchup) return false;
  return matchup.overallScore >= 10
    || matchup.hrThreatScore >= 64
    || Boolean(matchup.damageStack?.qualifies)
    || matchup.flags.some((flag) => ['Fastball Punisher', 'Weakness-on-Weakness', 'Pitcher Cannot Attack Weakness', 'Arsenal Imbalance Damage Stack'].includes(flag));
}

function arsenalMatchupRows(matchup = null) {
  if (!matchup) return [];
  return [
    { section: 'Arsenal Matchup' },
    ['Overall', `${matchup.label} | ${matchup.overallScore > 0 ? '+' : ''}${matchup.overallScore}`],
    ['HR Threat', `${matchup.hrThreatScore}/100`],
    ['K Risk', `${matchup.kRiskScore}/100`],
    ['Flags', matchup.flags.join(', ') || '--'],
    ['Explanation', matchup.explanation],
    ...matchup.families.map((family) => [
      family.label,
      `${arsenalMetricText(family.usagePct, 1, false, '%')} usage | edge ${family.edge > 0 ? '+' : ''}${Math.round(family.edge)} | ${family.result}`,
    ]),
  ];
}

function arsenalMatchupCardHtml(matchup = null) {
  if (!matchup) return '';
  return `
    <div class="arsenal-matchup-card">
      <div class="arsenal-matchup-head">
        <span>Arsenal</span>
        <strong>${escapeHtml(matchup.label)}</strong>
        <b>${matchup.overallScore > 0 ? '+' : ''}${Math.round(matchup.overallScore)}</b>
      </div>
      <p class="arsenal-explanation">${escapeHtml(matchup.explanation)}</p>
      <div class="arsenal-score-grid">
        <span><b>${Math.round(matchup.hrThreatScore)}</b>HR</span>
        <span><b>${Math.round(matchup.kRiskScore)}</b>K Risk</span>
      </div>
      <div class="arsenal-family-grid">
        ${matchup.families.map((family) => `
          <span class="${family.edge >= 14 ? 'is-batter' : family.edge <= -14 ? 'is-pitcher' : 'is-neutral'}" title="${escapeHtml(arsenalFamilyDescription(family))}">
            <b>${escapeHtml(family.label)}</b>
            <strong>${arsenalMetricText(family.usagePct, 1, false, '%')}</strong>
            <em>${family.edge > 0 ? '+' : ''}${Math.round(family.edge)}</em>
            <small>${escapeHtml(family.result)}</small>
          </span>
        `).join('')}
      </div>
      ${matchup.flags.length ? `<div class="arsenal-flags">${matchup.flags.map((flag) => `<span>${escapeHtml(flag)}</span>`).join('')}</div>` : ''}
    </div>
  `;
}

function predictionPitcherBagCardHtml(summary = null) {
  if (!summary || !summary.count) return '';
  return `
    <div class="arsenal-matchup-card pitcher-bag-card">
      <div class="arsenal-matchup-head">
        <span>Pitch Bag</span>
        <strong>${escapeHtml(summary.label)}</strong>
        <b>${escapeHtml(summary.code)}</b>
      </div>
      <p class="arsenal-explanation">${escapeHtml(summary.description || summary.detail || '')}</p>
      <div class="arsenal-score-grid">
        <span><b>${Math.round(Math.max(summary.deepScore || 0, summary.shallowScore || summary.score || 0))}</b>Bag Score</span>
        <span><b>${Math.round(summary.count || 0)}</b>Pitches</span>
      </div>
    </div>
  `;
}


function pitcherArchetypeMatchupFamily(rows = [], key = 'fb') {
  const families = key === 'secondary' ? ['Breaking', 'Offspeed'] : key === 'breaking' ? ['Breaking'] : key === 'offspeed' ? ['Offspeed'] : key === 'primary' ? ['Fastball', 'Breaking', 'Offspeed'] : ['Fastball'];
  const matched = families.map((family) => pitchTypeRow(rows, family)).filter(Boolean);
  if (!matched.length) return null;
  const avg = (keyName) => {
    const values = matched.map((row) => arsenalRate(row[keyName])).filter(Number.isFinite);
    return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
  };
  const usageValues = matched.map((row) => arsenalPercent(row.pct)).filter(Number.isFinite);
  return {
    category: families.join('/'),
    rows: matched,
    usagePct: usageValues.length ? usageValues.reduce((sum, value) => sum + value, 0) : null,
    avg: avg('avg'),
    slg: avg('slg'),
    ev: avg('ev'),
    whiff: avg('whiff'),
    hardHit: avg('hardHit'),
    hrRate: avg('hrRate'),
  };
}

function archetypeMatchupMetricText(stat = null) {
  if (!stat) return 'limited data';
  const parts = [
    Number.isFinite(stat.slg) ? `SLG ${formatRateValue(stat.slg, 3, true)}` : '',
    Number.isFinite(stat.avg) ? `AVG ${formatRateValue(stat.avg, 3, true)}` : '',
    Number.isFinite(stat.ev) ? `EV ${formatRateValue(stat.ev, 1, false)}` : '',
    Number.isFinite(stat.whiff) ? `Whiff ${formatRateValue(stat.whiff, 1, false)}%` : '',
  ];
  return parts.filter(Boolean).join(' / ') || 'limited data';
}


function archetypePitchFamilyName(category = '') {
  const exact = visiblePitchCategoryName(category);
  if (!exact) return '';
  return visiblePitchCategoryName(savantPitchCategory({
    'Pitch Type': exact,
    'Pitch Name': exact,
    pitch_name: exact,
    pitch_type: exact,
    pitch: exact,
    'Pitch Group': exact,
  }));
}

function archetypePitchCategoryMatches(row = {}, category = '') {
  const rowCategory = visiblePitchCategoryName(row?.category || row?.pitchName || row?.pitchType || '');
  const targetCategory = visiblePitchCategoryName(category);
  if (!rowCategory || !targetCategory) return false;
  if (pitchStrengthMatchKey(rowCategory) === pitchStrengthMatchKey(targetCategory)) return true;
  const targetFamily = archetypePitchFamilyName(targetCategory);
  const rowFamily = archetypePitchFamilyName(rowCategory);
  return ['Fastball', 'Breaking', 'Offspeed'].includes(targetCategory) && rowFamily === targetCategory
    || ['Fastball', 'Breaking', 'Offspeed'].includes(targetFamily) && targetFamily === rowFamily && pitchStrengthMatchKey(targetCategory) === pitchStrengthMatchKey(targetFamily);
}

function uniquePitchCategories(categories = []) {
  const seen = new Set();
  const output = [];
  for (const category of listify(categories).map(visiblePitchCategoryName).filter(Boolean)) {
    const key = pitchStrengthMatchKey(category);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    output.push(category);
  }
  return output;
}

function pitcherRowUsageScore(row = {}) {
  const usage = visiblePitchUsagePercent(row, ['pct', 'usage', 'usagePct', 'pitch_percent']);
  return Number.isFinite(usage) ? usage : 0;
}

function pitcherRowDamageScore(row = {}) {
  const slg = pitcherAllowedSlugForFiery(row);
  const hr = savantRowHomeRuns(row);
  const ab = savantRowNumber(row, PITCHER_ALLOWED_AB_KEYS) ?? savantRowNumber(row, ['ab', 'AB', 'abs', 'at_bats', 'At Bats']);
  const usage = pitcherRowUsageScore(row);
  const hrRate = Number.isFinite(hr) && Number.isFinite(ab) && ab > 0 ? (hr / ab) : null;
  return (Number.isFinite(slg) ? slg * 100 : 0)
    + (Number.isFinite(hrRate) ? hrRate * 650 : 0)
    + (Number.isFinite(hr) ? hr * 4 : 0)
    + Math.min(18, usage / 2);
}

function topPitcherExactCategories(pitcherRows = [], limit = 2, minUsage = 0) {
  return uniquePitchCategories(listify(pitcherRows)
    .filter((row) => visiblePitchCategoryName(row?.category))
    .map((row) => ({ category: visiblePitchCategoryName(row.category), usage: pitcherRowUsageScore(row) }))
    .filter((row) => row.usage >= minUsage)
    .sort((a, b) => b.usage - a.usage)
    .slice(0, limit)
    .map((row) => row.category));
}

function vulnerablePitcherExactCategories(pitcherRows = [], limit = 2) {
  const ranked = listify(pitcherRows)
    .filter((row) => visiblePitchCategoryName(row?.category))
    .map((row) => {
      const slg = pitcherAllowedSlugForFiery(row);
      const hr = savantRowHomeRuns(row);
      const ab = savantRowNumber(row, PITCHER_ALLOWED_AB_KEYS) ?? savantRowNumber(row, ['ab', 'AB', 'abs', 'at_bats', 'At Bats']);
      const hrRate = Number.isFinite(hr) && Number.isFinite(ab) && ab > 0 ? (hr / ab) : null;
      return {
        category: visiblePitchCategoryName(row.category),
        slg,
        hr,
        hrRate,
        score: pitcherRowDamageScore(row),
      };
    })
    .filter((row) => (Number.isFinite(row.slg) && row.slg > 0.500) || (Number.isFinite(row.hr) && row.hr > 0) || (Number.isFinite(row.hrRate) && row.hrRate >= 0.035))
    .sort((a, b) => b.score - a.score);
  return uniquePitchCategories(ranked.slice(0, limit).map((row) => row.category));
}



function archetypePitchCategories(arch = {}, pitcherRows = []) {
  const letter = String(arch?.letter || '').toUpperCase();
  if (letter === 'F') return ['Fastball'];
  if (letter === 'K') return ['Breaking', 'Offspeed'];
  if (letter === 'RS') {
    const breakRows = topBreakPitcherExactCategories(pitcherRows, 2);
    return breakRows.length ? breakRows : ['Breaking'];
  }
  if (letter === 'DB') {
    const deepRows = topPitcherExactCategories(pitcherRows, 4, 3);
    return deepRows.length ? deepRows : topPitcherExactCategories(pitcherRows, 4, 0);
  }
  if (letter === 'SB') {
    const shallowRows = topPitcherExactCategories(pitcherRows, 2, 8);
    return shallowRows.length ? shallowRows : topPitcherExactCategories(pitcherRows, 2, 0);
  }
  if (letter === 'L') {
    const vulnerable = vulnerablePitcherExactCategories(pitcherRows, 2);
    return vulnerable.length ? vulnerable : [];
  }
  if (letter === 'I') {
    const stacked = uniquePitchCategories(listify(arch?.damageStack?.rows).map((row) => row?.category).filter(Boolean));
    if (stacked.length) return stacked;
    return [];
  }
  if (letter === 'R') {
    const repeated = topPitcherExactCategories(pitcherRows, 2, 12);
    return repeated.length ? repeated : topPitcherExactCategories(pitcherRows, 1, 4);
  }
  return topPitcherExactCategories(pitcherRows, 2, 4);
}

function rowHitsEstimate(row = {}) {
  const direct = savantRowNumber(row, ['h', 'H', 'hits', 'Hits']);
  if (Number.isFinite(direct)) return direct;
  const ab = savantRowNumber(row, ['ab', 'AB', 'abs', 'at_bats', 'At Bats']);
  const avg = savantRowNumber(row, ['avg', 'AVG', 'ba', 'BA', 'batting_avg']);
  return Number.isFinite(ab) && Number.isFinite(avg) ? Math.round(avg * ab) : null;
}

function archetypePitchRowSummary(arch = {}, batterRows = [], pitcherRows = []) {
  const categories = archetypePitchCategories(arch, pitcherRows);
  const matched = [];
  const seen = new Set();
  for (const category of categories) {
    for (const row of listify(batterRows)) {
      if (!archetypePitchCategoryMatches(row, category)) continue;
      const rowKey = pitchStrengthMatchKey(row?.category || row?.pitchName || row?.pitchType || `${category}:${matched.length}`);
      if (rowKey && seen.has(rowKey)) continue;
      if (rowKey) seen.add(rowKey);
      matched.push(row);
    }
  }
  const rows = matched;
  if (!rows.length) {
    return { categories, h: null, ab: null, slg: null, hr: null, limited: true, source: 'pitch-family' };
  }
  let totalAb = 0;
  let totalHits = 0;
  let totalHr = 0;
  let hasHits = false;
  let slgWeighted = 0;
  let slgWeight = 0;
  const slgValues = [];
  for (const row of rows) {
    const ab = savantRowNumber(row, ['ab', 'AB', 'abs', 'at_bats', 'At Bats']);
    const h = rowHitsEstimate(row);
    const slg = savantRowNumber(row, ['slg', 'SLG', 'slugging', 'xslg', 'xSLG']);
    const hr = savantRowHomeRuns(row);
    if (Number.isFinite(ab)) totalAb += ab;
    if (Number.isFinite(h)) {
      totalHits += h;
      hasHits = true;
    }
    if (Number.isFinite(hr)) totalHr += hr;
    if (Number.isFinite(slg)) {
      slgValues.push(slg);
      if (Number.isFinite(ab) && ab > 0) {
        slgWeighted += slg * ab;
        slgWeight += ab;
      }
    }
  }
  return {
    categories,
    h: hasHits ? totalHits : null,
    ab: totalAb > 0 ? totalAb : null,
    slg: slgWeight > 0 ? (slgWeighted / slgWeight) : (slgValues.length ? slgValues.reduce((a, b) => a + b, 0) / slgValues.length : null),
    hr: Number.isFinite(totalHr) ? totalHr : null,
    limited: !totalAb,
    source: 'pitch-family',
  };
}

function formatArchetypeSlg(summary = {}) {
  if (summary?.loading) return '…';
  const value = summary?.slg;
  return value === null || value === undefined || value === '' ? '--' : formatRateValue(value, 3, true);
}

function formatArchetypeHab(summary = {}) {
  if (summary?.loading) return '…';
  return Number.isFinite(summary.h) && Number.isFinite(summary.ab)
    ? `${Math.round(summary.h)}-${Math.round(summary.ab)}`
    : '--';
}

function formatArchetypeHr(summary = {}) {
  if (summary?.loading) return '…';
  return Number.isFinite(summary.hr) ? String(Math.round(summary.hr)) : '--';
}

function savantPitchEventPitcherId(row = {}) {
  const id = Number(csvValue(row, ['pitcher', 'Pitcher', 'pitcher_id', 'pitcherId', 'Pitcher ID', 'PitcherId']));
  return Number.isFinite(id) && id > 0 ? id : null;
}

function normalizedTooltipNameKey(value = '') {
  return String(value || '')
    .normalize?.('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function savantPitchEventPitcherName(row = {}) {
  // For batter Statcast exports, generic player_name/Name usually refers to the batter,
  // not the pitcher. Only trust pitcher-specific name fields here.
  const name = cleanSummary(csvValue(row, [
    'pitcher_name',
    'Pitcher Name',
    'pitcherFullName',
    'pitcher_full_name',
    'pitcherFullname',
    'pitcherName',
  ]));
  if (!name || /^unknown$/i.test(name) || /^\d+$/.test(name)) return '';
  return name;
}

function uniquePitcherIdsFromRows(rows = []) {
  const seen = new Set();
  const ids = [];
  for (const row of listify(rows)) {
    const id = savantPitchEventPitcherId(row);
    if (!Number.isFinite(id) || id <= 0 || seen.has(id)) continue;
    seen.add(id);
    ids.push(id);
  }
  return ids;
}

function uniquePitcherNamesFromRows(rows = [], options = {}) {
  const exclude = new Set(listify(options.excludeNames).map(normalizedTooltipNameKey).filter(Boolean));
  const seen = new Set();
  const names = [];
  for (const row of listify(rows)) {
    const id = savantPitchEventPitcherId(row);
    const name = savantPitchEventPitcherName(row);
    const nameKey = normalizedTooltipNameKey(name);
    if (nameKey && exclude.has(nameKey)) continue;
    const key = id ? `id:${id}` : (nameKey ? `name:${nameKey}` : '');
    if (!key || seen.has(key)) continue;
    seen.add(key);
    if (name) names.push(name);
  }
  return names.sort((a, b) => a.localeCompare(b));
}

function savantPitchEventPitcherRoleText(row = {}) {
  return cleanSummary(csvValue(row, [
    'pitcher_role', 'Pitcher Role', 'pitcherRole', 'p_role', 'P Role',
    'role', 'Role', 'position', 'Position', 'player_position', 'Pitcher Position',
    'game_role', 'Game Role', 'appearance_role', 'Appearance Role',
  ]));
}

function savantPitchEventRoleSaysRelief(row = {}) {
  const role = savantPitchEventPitcherRoleText(row).toLowerCase();
  return /(^|\b)(rp|cp|cl|closer|closing|relief|reliever|bullpen)(\b|$)/i.test(role);
}

function savantPitchEventRoleSaysStarter(row = {}) {
  const role = savantPitchEventPitcherRoleText(row).toLowerCase();
  return /(^|\b)(sp|starter|starting pitcher|probable starter)(\b|$)/i.test(role);
}

const archetypeStartingPitcherEligibilityCache = new Map();

async function startingPitcherEligibilityForIds(ids = [], targetDate = '') {
  const season = seasonForDate(targetDate || dateInput?.value || formatDate(new Date()));
  const uniqueIds = [...new Set(listify(ids).map(Number).filter((id) => Number.isFinite(id) && id > 0))];
  if (!uniqueIds.length) return new Map();
  const cacheKey = `${season}:sp-eligibility`;
  let promise = archetypeStartingPitcherEligibilityCache.get(cacheKey);
  if (!promise) {
    promise = (async () => {
      const rankings = await getPitcherSeasonRankings(season).catch(() => null);
      const map = new Map();
      const byPlayer = rankings?.byPlayer instanceof Map ? rankings.byPlayer : new Map();
      for (const [idKey, row] of byPlayer.entries()) {
        const id = Number(idKey);
        if (!Number.isFinite(id) || id <= 0) continue;
        const role = cleanSummary(row?.role || pitcherDisplayUsageRole(row, row?.role || '')).toUpperCase();
        const gs = pitcherGamesStarted(row);
        const gp = pitcherGamesPlayed(row);
        const avgStartIp = pitcherAverageInningsPerStart(row);
        const saves = pitcherSaveCount(row);
        const isCloserish = role === 'CP' || saves >= 2 && gp > 0 && saves >= Math.max(1, gp * 0.12);
        const isStarter = role === 'SP' || (gs >= 3 && avgStartIp >= 3.0 && gp > 0 && gs >= Math.ceil(gp * 0.35));
        map.set(id, Boolean(isStarter && !isCloserish));
      }
      return map;
    })().catch((error) => {
      archetypeStartingPitcherEligibilityCache.delete(cacheKey);
      throw error;
    });
    archetypeStartingPitcherEligibilityCache.set(cacheKey, promise);
  }
  const seasonMap = await promise.catch(() => new Map());
  return new Map(uniqueIds.map((id) => [id, seasonMap.get(id) === true]));
}

async function filterBatterEventRowsToStartingPitchers(rows = [], targetDate = '') {
  const sourceRows = listify(rows);
  if (!sourceRows.length) return [];
  const ids = uniquePitcherIdsFromRows(sourceRows);
  const eligibility = await startingPitcherEligibilityForIds(ids, targetDate).catch(() => new Map());
  const eligibilityReady = eligibility instanceof Map && eligibility.size > 0;
  return sourceRows.filter((row) => {
    if (savantPitchEventRoleSaysRelief(row)) return false;
    const id = savantPitchEventPitcherId(row);
    if (Number.isFinite(id) && id > 0) {
      if (eligibility.has(id)) return eligibility.get(id) === true;
      // Live/cold-load guard: do not throw away batter archetype history just because
      // the season SP eligibility map has not hydrated for this id yet. Downstream
      // archetype filters still re-check season profiles/letters before counting rows.
      return !eligibilityReady && !savantPitchEventRoleSaysRelief(row);
    }
    // Only keep id-less rows when the source explicitly says the pitcher was a starter.
    // Otherwise the batter-side archetype table would silently mix in relievers/closers.
    return savantPitchEventRoleSaysStarter(row);
  });
}

const archetypePitcherSeasonProfileCache = new Map();

async function pitcherSeasonProfilesForArchetypeIds(ids = [], targetDate = '') {
  const season = seasonForDate(targetDate || dateInput?.value || formatDate(new Date()));
  const uniqueIds = [...new Set(listify(ids).map(Number).filter((id) => Number.isFinite(id) && id > 0))];
  if (!uniqueIds.length) return new Map();
  const cacheKey = `${season}:sp-archetype-profile`;
  let promise = archetypePitcherSeasonProfileCache.get(cacheKey);
  if (!promise) {
    promise = (async () => {
      const rankings = await getPitcherSeasonRankings(season).catch(() => null);
      const byPlayer = rankings?.byPlayer instanceof Map ? rankings.byPlayer : new Map();
      const map = new Map();
      for (const [idKey, row] of byPlayer.entries()) {
        const id = Number(idKey);
        if (!Number.isFinite(id) || id <= 0) continue;
        const role = cleanSummary(row?.role || pitcherDisplayUsageRole(row, row?.role || '')).toUpperCase();
        const gs = pitcherGamesStarted(row);
        const gp = pitcherGamesPlayed(row);
        const avgStartIp = pitcherAverageInningsPerStart(row);
        const saves = pitcherSaveCount(row);
        const isCloserish = role === 'CP' || saves >= 2 && gp > 0 && saves >= Math.max(1, gp * 0.12);
        const isStarter = role === 'SP' || (gs >= 3 && avgStartIp >= 3.0 && gp > 0 && gs >= Math.ceil(gp * 0.35));
        const archetypes = isStarter && !isCloserish ? lineupPitcherArchetypes(row) : [];
        map.set(id, {
          row,
          isStarter: Boolean(isStarter && !isCloserish),
          archetypes,
          letters: new Set(archetypes.filter((arch) => arch.isPrimary || arch.isSecondary).map((arch) => String(arch.letter || '').toUpperCase())),
        });
      }
      return map;
    })().catch((error) => {
      archetypePitcherSeasonProfileCache.delete(cacheKey);
      throw error;
    });
    archetypePitcherSeasonProfileCache.set(cacheKey, promise);
  }
  const seasonMap = await promise.catch(() => new Map());
  return new Map(uniqueIds.map((id) => [id, seasonMap.get(id)]).filter(([, value]) => value));
}


const flamePitcherEligibilityCache = new Map();


function pitcherProfileQualifiesAsFinesseKiller(profile = null) {
  const row = profile?.row || profile || {};
  if (profile && profile.isStarter === false) return false;
  const ipOuts = inningsToOuts(pitcherInningsPitched(row));
  const ip = ipOuts > 0 ? ipOuts / 3 : null;
  const whip = Number(pitcherWhip(row));
  const k9 = Number(pitcherKPerNine(row));
  const era = Number(pitcherEra(row));
  const oppAvg = pitcherOpponentAvgAgainst(row);
  const hasIp = Number.isFinite(ip) && ip >= 30;
  const hasWhip = Number.isFinite(whip) && whip <= 1.08;
  const hasK = Number.isFinite(k9) && k9 >= 7.5;
  const hasRunPrevention = Number.isFinite(era) && era <= 3.35;
  const hasOppAvg = Number.isFinite(oppAvg) && oppAvg <= 0.235;
  const hasNoAvgFallback = !Number.isFinite(oppAvg) && hasWhip && hasK && hasRunPrevention;
  return Boolean(hasIp && hasWhip && hasK && hasRunPrevention && (hasOppAvg || hasNoAvgFallback));
}

async function flamePitcherEligibilityForArchetypeIds(ids = [], targetDate = '') {
  const season = seasonForDate(targetDate || dateInput?.value || formatDate(new Date()));
  const uniqueIds = [...new Set(listify(ids).map(Number).filter((id) => Number.isFinite(id) && id > 0))];
  if (!uniqueIds.length) return new Map();
  const starterMap = await startingPitcherEligibilityForIds(uniqueIds, targetDate).catch(() => new Map());
  const output = new Map();
  const missing = [];
  for (const id of uniqueIds) {
    const key = `${season}:flame-max97-avg95-v2:${id}`;
    if (flamePitcherEligibilityCache.has(key)) {
      output.set(id, flamePitcherEligibilityCache.get(key));
    } else {
      missing.push(id);
    }
  }
  await mapWithConcurrency(missing, 4, async (id) => {
    const key = `${season}:flame-max97-avg95-v2:${id}`;
    const isStarter = starterMap.get(id) === true;
    let result = { isStarter, qualifies: false, maxVelocity: null, avgVelocity: null };
    if (isStarter) {
      const fastballMax = await withTimeoutValue(getSavantPitcherFastballMaxVelocityWithFallback(id, season), 3600, null).catch(() => null);
      const maxVelocity = pitcherVelocityNumber(fastballMax?.maxVelocity ?? fastballMax?.topVelocity ?? fastballMax?.maxVelo);
      const avgVelocity = pitcherVelocityNumber(fastballMax?.avgVelocity ?? fastballMax?.velocity ?? fastballMax?.avgVelo);
      result = {
        isStarter,
        qualifies: Number.isFinite(maxVelocity) && maxVelocity > 97.0 && Number.isFinite(avgVelocity) && avgVelocity >= 95.0,
        maxVelocity: Number.isFinite(maxVelocity) ? maxVelocity : null,
        avgVelocity: Number.isFinite(avgVelocity) ? avgVelocity : null,
      };
    }
    flamePitcherEligibilityCache.set(key, result);
    output.set(id, result);
  }).catch(() => {});
  return output;
}

function filterStarterEventRowsForPitcherArchetype(rows = [], arch = {}, seasonProfiles = new Map(), flameEligibility = new Map()) {
  const letter = String(arch?.letter || '').toUpperCase();
  const sourceRows = listify(rows);
  if (!letter || !sourceRows.length) return [];
  const flameEventQualifiedIds = new Set();
  if (letter === 'F') {
    const grouped = new Map();
    for (const row of sourceRows) {
      const id = savantPitchEventPitcherId(row);
      if (!Number.isFinite(id) || id <= 0) continue;
      const category = savantExactPitchCategory(row) || savantPitchCategory(row) || pitchRowCategoryText(row);
      const pitchName = csvValue(row, ['pitch_name', 'Pitch Name', 'pitch_type', 'Pitch Type']);
      if (!isFastballVelocityFamily(category) && !isFastballVelocityFamily(pitchName)) continue;
      const velocity = savantPitchEventReleaseSpeed(row);
      if (!Number.isFinite(velocity)) continue;
      const bucket = grouped.get(id) || { max: 0, total: 0, count: 0 };
      bucket.max = Math.max(bucket.max, velocity);
      bucket.total += velocity;
      bucket.count += 1;
      grouped.set(id, bucket);
    }
    for (const [id, bucket] of grouped.entries()) {
      const avg = bucket.count > 0 ? bucket.total / bucket.count : null;
      if (Number.isFinite(bucket.max) && bucket.max > 97.0 && Number.isFinite(avg) && avg >= 95.0) flameEventQualifiedIds.add(id);
    }
  }
  const arsenalEventQualifiedIds = new Set();
  if (letter === 'I' || letter === 'A' || letter === 'R') {
    const grouped = new Map();
    for (const row of sourceRows) {
      const id = savantPitchEventPitcherId(row);
      if (!Number.isFinite(id) || id <= 0) continue;
      const category = visiblePitchCategoryName(savantExactPitchCategory(row) || savantPitchCategory(row) || pitchRowCategoryText(row));
      const family = archetypePitchFamilyName(category) || category;
      if (!family) continue;
      const bucket = grouped.get(id) || { total: 0, families: new Map() };
      bucket.total += 1;
      bucket.families.set(family, (bucket.families.get(family) || 0) + 1);
      grouped.set(id, bucket);
    }
    for (const [id, bucket] of grouped.entries()) {
      const profile = seasonProfiles.get(id);
      if (!profile?.isStarter || bucket.total < 20) continue;
      const counts = [...bucket.families.values()].sort((a, b) => b - a);
      const topOne = counts[0] || 0;
      const topTwo = (counts[0] || 0) + (counts[1] || 0);
      if ((topOne / bucket.total) >= 0.45 || (topTwo / bucket.total) >= 0.70) arsenalEventQualifiedIds.add(id);
    }
  }
  const rockSpinnerEventQualifiedIds = new Set();
  if (letter === 'RS') {
    const grouped = new Map();
    for (const row of sourceRows) {
      const id = savantPitchEventPitcherId(row);
      if (!Number.isFinite(id) || id <= 0) continue;
      const breakAmount = savantPitchBreakAmount(row);
      if (!Number.isFinite(breakAmount) || breakAmount <= 0) continue;
      const category = visiblePitchCategoryName(savantExactPitchCategory(row) || savantPitchCategory(row) || pitchRowCategoryText(row));
      const bucket = grouped.get(id) || { total: 0, weighted: 0, max: 0, breaking: 0 };
      bucket.total += 1;
      bucket.weighted += breakAmount;
      bucket.max = Math.max(bucket.max, breakAmount);
      if (/breaking|slider|sweeper|curve|knuckle curve|slurve/i.test(category)) bucket.breaking += 1;
      grouped.set(id, bucket);
    }
    for (const [id, bucket] of grouped.entries()) {
      const profile = seasonProfiles.get(id);
      if (!profile?.isStarter || bucket.total < 20) continue;
      const avgBreak = bucket.weighted / bucket.total;
      if (avgBreak >= 16.5 || bucket.max >= 21.0 || (bucket.breaking / bucket.total >= 0.32 && avgBreak >= 14.5)) rockSpinnerEventQualifiedIds.add(id);
    }
  }
  const deepBagEventQualifiedIds = new Set();
  const shallowBagEventQualifiedIds = new Set();
  if (letter === 'DB' || letter === 'SB') {
    const grouped = new Map();
    for (const row of sourceRows) {
      const id = savantPitchEventPitcherId(row);
      if (!Number.isFinite(id) || id <= 0) continue;
      const category = visiblePitchCategoryName(savantExactPitchCategory(row) || savantPitchCategory(row) || pitchRowCategoryText(row));
      const key = savantPitchCategoryKey(category);
      if (!key) continue;
      const bucket = grouped.get(id) || { total: 0, pitches: new Map() };
      bucket.total += 1;
      bucket.pitches.set(key, (bucket.pitches.get(key) || 0) + 1);
      grouped.set(id, bucket);
    }
    for (const [id, bucket] of grouped.entries()) {
      const profile = seasonProfiles.get(id);
      if (!profile?.isStarter || bucket.total < 20) continue;
      const meaningful = [...bucket.pitches.values()].filter((count) => count >= 3 && (count / bucket.total) >= 0.03).length;
      if (meaningful >= 6) deepBagEventQualifiedIds.add(id);
      if (meaningful > 0 && meaningful <= 3) shallowBagEventQualifiedIds.add(id);
    }
  }
  const leakerEventQualifiedIds = new Set();
  if (letter === 'L') {
    const grouped = new Map();
    for (const row of sourceRows) {
      const id = savantPitchEventPitcherId(row);
      if (!Number.isFinite(id) || id <= 0) continue;
      const bucket = grouped.get(id) || { ab: 0, hr: 0, tb: 0 };
      const event = cleanSummary(csvValue(row, ['events', 'Events', 'event'])).toLowerCase();
      const abFlag = Number(csvValue(row, ['is_ab', 'isAtBat', 'at_bat_number'])) || (/(single|double|triple|home_run|field_out|force_out|grounded_into_double_play|strikeout)/i.test(event) ? 1 : 0);
      if (abFlag) bucket.ab += 1;
      if (event === 'home_run') bucket.hr += 1;
      const tb = event === 'home_run' ? 4 : event === 'triple' ? 3 : event === 'double' ? 2 : event === 'single' ? 1 : 0;
      bucket.tb += tb;
      grouped.set(id, bucket);
    }
    for (const [id, bucket] of grouped.entries()) {
      const profile = seasonProfiles.get(id);
      if (!profile?.isStarter || bucket.ab < 20) continue;
      const slg = bucket.ab > 0 ? bucket.tb / bucket.ab : 0;
      const hrRate = bucket.ab > 0 ? bucket.hr / bucket.ab : 0;
      if (slg >= 0.500 || hrRate >= 0.035 || bucket.hr >= 2) leakerEventQualifiedIds.add(id);
    }
  }
  return sourceRows.filter((row) => {
    const id = savantPitchEventPitcherId(row);
    const profile = Number.isFinite(id) && id > 0 ? seasonProfiles.get(id) : null;
    if (letter === 'F') {
      const flame = Number.isFinite(id) && id > 0 ? flameEligibility.get(id) : null;
      return Boolean(
        flame?.isStarter && flame?.qualifies
        || flameEventQualifiedIds.has(id) && (profile?.isStarter !== false)
        || profile?.isStarter && profile.letters?.has('F') === true
      );
    }
    if (letter === 'I' || letter === 'A') {
      return Boolean(arsenalEventQualifiedIds.has(id) || (profile?.isStarter && (profile.letters?.has('I') === true || profile.letters?.has('A') === true)));
    }
    if (letter === 'R') {
      return Boolean(arsenalEventQualifiedIds.has(id) || (profile?.isStarter && profile.letters?.has('R') === true));
    }
    if (letter === 'RS') {
      return Boolean(rockSpinnerEventQualifiedIds.has(id) || (profile?.isStarter && profile.letters?.has('RS') === true));
    }
    if (letter === 'DB') {
      return Boolean(deepBagEventQualifiedIds.has(id) || (profile?.isStarter && profile.letters?.has('DB') === true));
    }
    if (letter === 'SB') {
      return Boolean(shallowBagEventQualifiedIds.has(id) || (profile?.isStarter && profile.letters?.has('SB') === true));
    }
    if (letter === 'L') {
      return Boolean(leakerEventQualifiedIds.has(id) || (profile?.isStarter && profile.letters?.has('L') === true));
    }
    if (letter === 'K') {
      return Boolean(profile?.isStarter && (profile.letters?.has('K') === true || pitcherProfileQualifiesAsFinesseKiller(profile)));
    }
    if (!profile?.isStarter) return false;
    return profile.letters?.has(letter) === true;
  });
}

const archetypePitcherNameLookupCache = new Map();

async function resolveArchetypePitcherNamesById(ids = []) {
  const uniqueIds = [...new Set(listify(ids).map(Number).filter((id) => Number.isFinite(id) && id > 0))];
  if (!uniqueIds.length) return new Map();
  const missing = uniqueIds.filter((id) => !archetypePitcherNameLookupCache.has(id));
  if (missing.length) {
    try {
      const url = new URL(`${MLB_API_BASE}/people`);
      url.searchParams.set('personIds', missing.slice(0, 24).join(','));
      const payload = await withTimeoutValue(getJson(url.toString()), 1800, null);
      if (!payload) throw new Error('Archetype pitcher name lookup timed out');
      const found = new Set();
      for (const person of listify(payload?.people)) {
        const id = Number(person?.id);
        const name = cleanSummary(person?.fullName || person?.name || '');
        if (!Number.isFinite(id) || id <= 0) continue;
        found.add(id);
        archetypePitcherNameLookupCache.set(id, name || '');
      }
      for (const id of missing) {
        if (!found.has(id)) archetypePitcherNameLookupCache.set(id, '');
      }
    } catch {
      for (const id of missing) {
        if (!archetypePitcherNameLookupCache.has(id)) archetypePitcherNameLookupCache.set(id, '');
      }
    }
  }
  return new Map(uniqueIds.map((id) => [id, archetypePitcherNameLookupCache.get(id) || '']).filter(([, name]) => name));
}

function dedupeTooltipPitcherNames(names = [], excludeNames = []) {
  const exclude = new Set(listify(excludeNames).map(normalizedTooltipNameKey).filter(Boolean));
  const seen = new Set();
  const output = [];
  for (const raw of listify(names)) {
    const name = cleanSummary(raw);
    const key = normalizedTooltipNameKey(name);
    if (!name || !key || exclude.has(key) || seen.has(key)) continue;
    seen.add(key);
    output.push(name);
  }
  return output.sort((a, b) => a.localeCompare(b));
}

async function hydrateArchetypeMatchupPitcherNames(matchups = [], profile = null) {
  const excludeNames = [profile?.fullName, profile?.name].filter(Boolean);
  const allIds = [];
  for (const row of listify(matchups)) {
    allIds.push(...listify(row?.summary?.pitcherIds));
  }
  const resolved = await resolveArchetypePitcherNamesById(allIds);
  for (const row of listify(matchups)) {
    const summary = row?.summary;
    if (!summary) continue;
    const resolvedNames = listify(summary.pitcherIds).map((id) => resolved.get(Number(id))).filter(Boolean);
    summary.pitcherStatlines = listify(summary.pitcherStatlines)
      .map((line) => {
        const id = Number(line?.pitcherId);
        const resolvedName = Number.isFinite(id) && id > 0 ? resolved.get(id) : '';
        return { ...line, pitcherName: cleanSummary(line?.pitcherName || resolvedName || (Number.isFinite(id) && id > 0 ? `Pitcher ${id}` : '')) };
      })
      .filter((line) => Number.isFinite(Number(line?.ab)) && Number(line.ab) > 0);
    const statlineNames = summary.pitcherStatlines.map((line) => line.pitcherName).filter(Boolean);
    summary.pitchers = dedupeTooltipPitcherNames([...listify(summary.pitchers), ...resolvedNames, ...statlineNames], excludeNames);
  }
  return matchups;
}

function savantPitchEventReleaseSpeed(row = {}) {
  return savantRate(row, SAVANT_VELOCITY_KEYS);
}

function summarizeArchetypeEventRowsByPitcher(rows = [], options = {}) {
  const groups = new Map();
  const exclude = new Set(listify(options.excludeNames).map(normalizedTooltipNameKey).filter(Boolean));
  for (const row of listify(rows)) {
    const id = savantPitchEventPitcherId(row);
    const name = savantPitchEventPitcherName(row);
    const nameKey = normalizedTooltipNameKey(name);
    if (nameKey && exclude.has(nameKey)) continue;
    const key = Number.isFinite(id) && id > 0 ? `id:${id}` : (nameKey ? `name:${nameKey}` : '');
    if (!key) continue;
    if (!groups.has(key)) groups.set(key, { pitcherId: Number.isFinite(id) && id > 0 ? id : null, pitcherName: name || '', rows: [] });
    groups.get(key).rows.push(row);
  }
  const statlines = [];
  for (const group of groups.values()) {
    const bucket = emptyPitchStrengthBucket(options.category || 'Archetype');
    for (const row of group.rows) addSavantPitchEventRow(bucket, row);
    const finalized = finalizeSavantPitchBucket(bucket, bucket.pitches || 0);
    const ab = Number(finalized?.ab);
    if (!Number.isFinite(ab) || ab <= 0) continue;
    const h = Number.isFinite(Number(finalized?.hits)) ? Number(finalized.hits) : null;
    const slg = Number.isFinite(Number(finalized?.slg)) ? Number(finalized.slg) : null;
    const hr = Number.isFinite(Number(finalized?.homeRuns)) ? Number(finalized.homeRuns) : null;
    statlines.push({
      pitcherId: group.pitcherId,
      pitcherName: group.pitcherName,
      h,
      ab,
      slg,
      hr,
    });
  }
  return statlines.sort((a, b) => String(a.pitcherName || '').localeCompare(String(b.pitcherName || '')) || Number(b.ab || 0) - Number(a.ab || 0));
}

function summarizeArchetypeEventRows(rows = [], options = {}) {
  const sourceRows = listify(rows);
  const bucket = emptyPitchStrengthBucket(options.category || 'Archetype');
  for (const row of sourceRows) addSavantPitchEventRow(bucket, row);
  const finalized = finalizeSavantPitchBucket(bucket, bucket.pitches || 0);
  const hasAb = Number.isFinite(finalized.ab) && finalized.ab > 0;
  const hasSlg = Number.isFinite(finalized.slg);
  const hasHr = Number.isFinite(finalized.homeRuns);
  const pitchers = uniquePitcherNamesFromRows(sourceRows, { excludeNames: options.excludeNames });
  const pitcherIds = uniquePitcherIdsFromRows(sourceRows);
  const pitcherStatlines = summarizeArchetypeEventRowsByPitcher(sourceRows, options);
  if (!hasAb && !hasSlg && !hasHr) {
    return {
      h: null,
      ab: null,
      slg: null,
      hr: null,
      limited: true,
      source: options.source || 'event-archetype',
      categories: listify(options.categories),
      pitchers,
      pitcherIds,
      pitcherStatlines,
    };
  }
  return {
    h: Number.isFinite(finalized.hits) ? finalized.hits : null,
    ab: hasAb ? finalized.ab : null,
    slg: hasSlg ? finalized.slg : null,
    hr: hasHr ? finalized.homeRuns : null,
    limited: !hasAb,
    source: options.source || 'event-archetype',
    categories: listify(options.categories),
    pitchers,
    pitcherIds,
    pitcherStatlines,
  };
}

function archetypePitchFamilyEventSummary(arch = {}, batterEventRows = [], pitcherRows = [], profile = null) {
  const categories = archetypePitchCategories(arch, pitcherRows);
  if (!categories.length) {
    return { categories, h: null, ab: null, slg: null, hr: null, limited: true, source: 'pitch-family-events', pitchers: [], pitcherIds: [] };
  }
  const selected = [];
  for (const row of listify(batterEventRows)) {
    for (const category of categories) {
      if (archetypePitchCategoryMatches({
        category: savantExactPitchCategory(row) || savantPitchCategory(row),
        pitchName: csvValue(row, ['pitch_name', 'Pitch Name', 'pitch_type', 'Pitch Type']),
      }, category)) {
        selected.push(row);
        break;
      }
    }
  }
  return summarizeArchetypeEventRows(selected, { source: 'pitch-family-events', categories, excludeNames: [profile?.fullName, profile?.name] });
}


function flameQualifiedPitcherIdsFromAvailableEvents(rows = []) {
  const byPitcher = new Map();
  for (const row of listify(rows)) {
    const pitcherId = savantPitchEventPitcherId(row);
    if (!Number.isFinite(pitcherId) || pitcherId <= 0) continue;
    const category = savantExactPitchCategory(row) || savantPitchCategory(row) || pitchRowCategoryText(row);
    const pitchName = csvValue(row, ['pitch_name', 'Pitch Name', 'pitch_type', 'Pitch Type']);
    if (!isFastballVelocityFamily(category) && !isFastballVelocityFamily(pitchName)) continue;
    const velocity = savantPitchEventReleaseSpeed(row);
    if (!Number.isFinite(velocity)) continue;
    const bucket = byPitcher.get(pitcherId) || { max: 0, total: 0, count: 0 };
    bucket.max = Math.max(bucket.max, velocity);
    bucket.total += velocity;
    bucket.count += 1;
    byPitcher.set(pitcherId, bucket);
  }
  const qualified = new Set();
  for (const [pitcherId, bucket] of byPitcher.entries()) {
    const avg = bucket.count > 0 ? bucket.total / bucket.count : null;
    if (Number.isFinite(bucket.max) && bucket.max > 97.0 && Number.isFinite(avg) && avg >= 95.0) qualified.add(pitcherId);
  }
  return qualified;
}

function archetypeEventRowSummary(arch = {}, batterEventRows = [], pitcher = null, profile = null) {
  const letter = String(arch?.letter || '').toUpperCase();
  const rows = listify(batterEventRows);
  if (!rows.length) return { h: null, ab: null, slg: null, hr: null, limited: true, source: 'event-archetype', pitchers: [], pitcherIds: [] };

  if (letter === 'F') {
    const flamePitcherIds = new Set();
    for (const row of rows) {
      const pitcherId = savantPitchEventPitcherId(row);
      if (pitcherId) flamePitcherIds.add(pitcherId);
    }
    const currentPitcherId = Number(pitcher?.id ?? pitcher?.person?.id);
    const currentMaxVelo = pitcherMaxVelocityMph(pitcher);
    const currentAvgVelo = pitcherVelocityMph(pitcher);
    if (Number.isFinite(currentPitcherId) && currentPitcherId > 0 && Number.isFinite(currentMaxVelo) && currentMaxVelo > 97 && Number.isFinite(currentAvgVelo) && currentAvgVelo > 95) {
      flamePitcherIds.add(currentPitcherId);
    }
    const selected = rows.filter((row) => flamePitcherIds.has(savantPitchEventPitcherId(row)));
    return summarizeArchetypeEventRows(selected, { source: 'event-archetype', categories: ['SP max >97 / avg FB >=95'], excludeNames: [profile?.fullName, profile?.name] });
  }

  // No handedness-split fallback here. These rows are player-vs-archetype only.
  // For K/I/L/R, the input rows have already been filtered to starting pitchers
  // that qualify for the displayed archetype, so summarize the real batter events
  // instead of falling back to generic handedness data.
  const label = String(arch?.label || arch?.title || letter || 'Archetype').replace(/^vs\s+/i, '');
  return summarizeArchetypeEventRows(rows, {
    source: 'starter-only-archetype-events',
    categories: [label],
    excludeNames: [profile?.fullName, profile?.name],
  });
}


function archetypeSummaryHasUsableSample(summary = {}) {
  return Boolean(summary)
    && ((Number.isFinite(summary.ab) && summary.ab > 0)
      || Number.isFinite(summary.slg)
      || Number.isFinite(summary.hr));
}

function archetypeHandedSplitSummary(handed = null, matchupHand = '') {
  const hand = handednessCode(matchupHand);
  const split = hand === 'L' ? handed?.vsLeft : hand === 'R' ? handed?.vsRight : null;
  if (!split) return null;
  const h = statNumber(split.hits);
  const ab = statNumber(split.atBats);
  const slg = rateNumber(split.slg);
  const hr = statNumber(split.homeRuns);
  const hasValue = (Number.isFinite(ab) && ab > 0) || Number.isFinite(slg) || Number.isFinite(hr);
  if (!hasValue) return null;
  return {
    h: Number.isFinite(h) ? h : null,
    ab: Number.isFinite(ab) && ab > 0 ? ab : null,
    slg: Number.isFinite(slg) ? slg : null,
    hr: Number.isFinite(hr) ? hr : null,
    limited: false,
    fallback: true,
  };
}



function archetypeDisplaySummary(row = {}, handed = null, matchupHand = '') {
  const summary = row.summary || {};
  if (summary.loading) return { ...summary, loading: true };
  const letter = String(row?.letter || '').toUpperCase();
  if (letter === 'I' && row?.damageStack?.qualifies) {
    const rows = listify(row.damageStack.rows);
    const avgHitterSlg = rows.length ? rows.reduce((sum, item) => sum + Number(item.hitterSlg || 0), 0) / rows.length : null;
    const stackH = Number(row.damageStack.hitterHits);
    const stackAb = Number(row.damageStack.hitterAb);
    const stackHr = Number(row.damageStack.hitterHr);
    const fallbackHr = rows.reduce((sum, item) => sum + (Number.isFinite(Number(item.hitterHr)) ? Number(item.hitterHr) : 0), 0);
    return {
      ...summary,
      h: Number.isFinite(stackH) && Number.isFinite(stackAb) && stackAb > 0 ? stackH : summary.h,
      ab: Number.isFinite(stackAb) && stackAb > 0 ? stackAb : summary.ab,
      slg: Number.isFinite(avgHitterSlg) ? avgHitterSlg : summary.slg,
      hr: Number.isFinite(stackHr) && stackHr > 0 ? stackHr : (fallbackHr > 0 ? fallbackHr : summary.hr),
      categories: uniquePitchCategories(rows.map((item) => item.category).filter(Boolean)),
      limited: true,
      starterOnly: true,
      damageStack: row.damageStack,
    };
  }
  return summary;
}

function pitcherArchetypeRowBadgesHtml(pitcher = null, row = null) {
  const parts = [];
  const rowLetter = String(row?.letter || '').toUpperCase();
  const hand = pitcher ? handednessHtml(pitcherThrowHandValue(pitcher)) : '';
  // Handedness is the highest-value compact marker, so render it first and outside
  // the shrinking label text. This prevents F/Flame Thrower from visually eating L/R.
  if (hand) parts.push(`<span class="player-archetype-hand-anchor">${hand}</span>`);
  if (pitcher) {
    const highVelo = pitcherHighVeloMarkerHtml(pitcher);
    if (highVelo) parts.push(highVelo);
    const visibleArchetypes = listify(lineupPitcherArchetypes(pitcher))
      .filter((arch) => arch?.letter)
      .filter((arch) => {
        const letter = String(arch?.letter || '').toUpperCase();
        return letter === rowLetter || arch.isPrimary || (['K', 'RS', 'DB', 'SB'].includes(letter) && arch.isSecondary);
      })
      .sort((a, b) => {
        const al = String(a?.letter || '').toUpperCase();
        const bl = String(b?.letter || '').toUpperCase();
        if (al === rowLetter && bl !== rowLetter) return -1;
        if (bl === rowLetter && al !== rowLetter) return 1;
        return Number(b?.confidence || b?.score || 0) - Number(a?.confidence || a?.score || 0);
      })
      .slice(0, 3)
      .map((arch) => pitcherArchetypeBadgeHtml(arch, arch.isPrimary ? '' : 'is-secondary'))
      .join('');
    if (visibleArchetypes) parts.push(visibleArchetypes);
    const hrRisk = pitcherHomeRunRiskMarkerHtml(pitcher);
    if (hrRisk) parts.push(hrRisk);
    const whipRisk = pitcherWhipRiskMarkerHtml(pitcher);
    if (whipRisk) parts.push(whipRisk);
  }
  if (!parts.length && rowLetter && rowLetter !== '…' && rowLetter !== '—') {
    parts.push(pitcherArchetypeBadgeHtml({
      letter: rowLetter,
      label: String(row?.label || row?.title || 'Pitcher archetype').replace(/^vs\s+/i, ''),
      title: row?.title || row?.label || 'Pitcher archetype',
      confidence: Number(row?.score),
    }, 'is-row-archetype'));
  }
  const html = parts.filter(Boolean).join('');
  return `<span class="player-archetype-pitcher-badges" data-required-pitcher-badges="1" aria-label="Pitcher archetype markers">${html}</span>`;
}

function pitcherArchetypeShortLabel(row = {}, pitcher = null) {
  const rawLetter = String(row?.letter || '').trim().toUpperCase();
  const fallbackLabels = {
    F: 'Flame Thrower',
    K: 'Finesse Killer',
    L: 'Mistake Leaker',
    I: 'Arsenal Imbalance',
    R: 'Repeat Pattern',
    RS: 'Rock Spinner',
    DB: 'Deep Bag',
    SB: 'Shallow Bag',
  };
  const labelText = String(row?.label || row?.name || row?.title || fallbackLabels[rawLetter] || 'Pitcher archetype')
    .replace(/^vs\s+/i, '')
    .trim();
  const titleText = labelText || fallbackLabels[rawLetter] || 'Pitcher archetype';
  return `<span class="player-archetype-name-only" title="${escapeHtml(titleText)}">${escapeHtml(titleText)}</span>`;
}

function ensurePlayerArchetypeBadgeVisibility(rootEl = null, pitcher = null) {
  if (!rootEl || !pitcher) return;
  rootEl.querySelectorAll?.('.player-archetype-label-wrap').forEach((wrap) => {
    const letter = String(wrap.dataset.archetypeLetter || wrap.querySelector('.player-archetype-letter')?.textContent || '').trim().toUpperCase();
    if (!letter) return;
    const badgeEl = wrap.querySelector('.player-archetype-pitcher-badges');
    const hasMarker = badgeEl && badgeEl.querySelector('.handed-badge, .handedness-tag, .lineup-archetype-badge, .pitcher-hr-risk, .pitcher-whip-risk, .pitcher-used-yesterday');
    if (hasMarker) return;
    const headEl = wrap.querySelector('.player-archetype-fixed-head') || wrap;
    const label = String(wrap.querySelector('.player-archetype-label-main')?.textContent || letter || 'Pitcher archetype');
    const html = pitcherArchetypeRowBadgesHtml(pitcher, { letter, label });
    if (badgeEl) {
      badgeEl.outerHTML = html;
    } else {
      headEl.insertAdjacentHTML('beforeend', html);
    }
  });
}

function scoreBatterVsPitcherArchetype(arch = {}, batterRows = [], pitcherRows = [], arsenalMatchup = null, pitcher = null) {
  const letter = arch?.letter || '';
  const maxVelo = pitcherMaxVelocityMph(pitcher);
  if (letter === 'F') {
    const fb = pitcherArchetypeMatchupFamily(batterRows, 'fb');
    const pitcherFb = pitcherArchetypeMatchupFamily(pitcherRows, 'fb');
    const score = clamp(Math.round(
      predictionPoints(fb?.slg, 0.330, 0.700, 36, { fallbackPoints: 13 })
      + predictionPoints(fb?.avg, 0.200, 0.330, 16, { fallbackPoints: 6 })
      + predictionPoints(fb?.ev, 87, 95, 18, { fallbackPoints: 7 })
      + predictionPoints(fb?.whiff, 18, 34, 18, { invert: true, fallbackPoints: 8 })
      + predictionPoints(pitcherFb?.usagePct, 35, 65, 8, { fallbackPoints: 3 })
      + (Number.isFinite(maxVelo) && maxVelo >= 100 ? 4 : 0)
    ), 0, 100);
    return {
      letter,
      label: 'vs Flame Thrower',
      score,
      title: `Fastball/velocity timing profile. Batter: ${archetypeMatchupMetricText(fb)}. Flame tag requires pitcher max/top fastball velocity >97 mph and average fastball-family velocity >=95 mph. Pitcher FB usage ${arsenalMetricText(pitcherFb?.usagePct, 1, false, '%')}${Number.isFinite(maxVelo) ? `, max ${maxVelo.toFixed(1)} mph` : ''}.`,
      detail: fb ? `FB ${archetypeMatchupMetricText(fb)}` : 'Fastball sample limited',
    };
  }
  if (letter === 'K') {
    const spin = pitcherArchetypeMatchupFamily(batterRows, 'secondary');
    const score = clamp(Math.round(
      predictionPoints(spin?.slg, 0.300, 0.620, 34, { fallbackPoints: 12 })
      + predictionPoints(spin?.avg, 0.190, 0.310, 18, { fallbackPoints: 7 })
      + predictionPoints(spin?.whiff, 20, 38, 24, { invert: true, fallbackPoints: 9 })
      + predictionPoints(spin?.ev, 86, 94, 12, { fallbackPoints: 5 })
      + (Number(arsenalMatchup?.overallScore) > 6 ? 8 : 0)
    ), 0, 100);
    return {
      letter,
      label: 'vs Finesse Killer',
      score,
      title: `Breaking/off-speed recognition profile. ${archetypeMatchupMetricText(spin)}.`,
      detail: spin ? `Spin/off-speed ${archetypeMatchupMetricText(spin)}` : 'Secondary-pitch sample limited',
    };
  }
  if (letter === 'RS') {
    const spin = pitcherArchetypeMatchupFamily(batterRows, 'breaking') || pitcherArchetypeMatchupFamily(batterRows, 'secondary');
    const breakProfile = pitcherBreakProfile(pitcher);
    const score = clamp(Math.round(
      predictionPoints(spin?.slg, 0.300, 0.660, 34, { fallbackPoints: 12 })
      + predictionPoints(spin?.avg, 0.185, 0.315, 16, { fallbackPoints: 6 })
      + predictionPoints(spin?.whiff, 20, 38, 24, { invert: true, fallbackPoints: 8 })
      + predictionPoints(spin?.ev, 86, 95, 12, { fallbackPoints: 5 })
      + predictionPoints(breakProfile.score, 86, 100, 10, { fallbackPoints: 4 })
      + (Number(arsenalMatchup?.overallScore) > 6 ? 4 : 0)
    ), 0, 100);
    return {
      letter,
      label: 'vs Rock Spinner',
      score,
      title: `High-break pitch recognition profile. Batter: ${archetypeMatchupMetricText(spin)}. Pitcher break profile: ${breakProfile.description || 'break sample limited'}.`,
      detail: spin ? `Break ${archetypeMatchupMetricText(spin)}` : 'High-break pitch sample limited',
    };
  }
  if (letter === 'DB') {
    const contextualRows = pitcherRowsForContextualArchetypes(pitcherRows);
    const usageSummary = pitcherPitchBagSummary({ ...pitcher, pitchBreakdown: contextualRows, pitchMix: contextualRows, pitchRows: contextualRows });
    if (!usageSummary.deep) return null;
    const score = clamp(Math.round(
      36
      + predictionPoints(arsenalMatchup?.overallScore, -10, 18, 28, { fallbackPoints: 10 })
      + predictionPoints(arsenalMatchup?.hrThreatScore, 35, 75, 22, { fallbackPoints: 8 })
      + predictionPoints(usageSummary.deepScore, 64, 100, 14, { fallbackPoints: 6 })
    ), 0, 100);
    return {
      letter,
      label: 'vs Deep Bag',
      score,
      title: `Six-plus pitch mix. ${usageSummary.description}. Matchup rewards hitters with damage across multiple pitch families. ${arsenalMatchup?.explanation || ''}`,
      detail: `${usageSummary.count || 0} pitch bag`,
    };
  }
  if (letter === 'SB') {
    const contextualRows = pitcherRowsForContextualArchetypes(pitcherRows);
    const usageSummary = pitcherPitchBagSummary({ ...pitcher, pitchBreakdown: contextualRows, pitchMix: contextualRows, pitchRows: contextualRows });
    if (!usageSummary.shallow) return null;
    const leanedOn = pitcherArchetypeMatchupFamily(batterRows, 'primary') || null;
    const score = clamp(Math.round(
      34
      + predictionPoints(arsenalMatchup?.overallScore, -8, 18, 30, { fallbackPoints: 10 })
      + predictionPoints(arsenalMatchup?.hrThreatScore, 35, 78, 22, { fallbackPoints: 8 })
      + predictionPoints(usageSummary.shallowScore, 62, 100, 14, { fallbackPoints: 6 })
    ), 0, 100);
    return {
      letter,
      label: 'vs Shallow Bag',
      score,
      title: `Three-or-fewer meaningful pitches. ${usageSummary.description}. Matchup rewards hitters who can sit on the concentrated arsenal.`,
      detail: leanedOn ? `Primary ${archetypeMatchupMetricText(leanedOn)}` : `${usageSummary.count || 0} pitch bag`,
    };
  }
  if (letter === 'L') {
    const score = clamp(Math.round((Number(arsenalMatchup?.hrThreatScore) || 45) + 8), 0, 100);
    return {
      letter,
      label: 'vs Mistake Leaker',
      score,
      title: `Power conversion against an attackable damage profile. Arsenal HR threat ${Math.round(arsenalMatchup?.hrThreatScore || 0)}/100.`,
      detail: `Arsenal HR ${Math.round(arsenalMatchup?.hrThreatScore || 0)}/100`,
    };
  }
  if (letter === 'I') {
    const contextualRows = pitcherRowsForContextualArchetypes(pitcherRows);
    const damageStack = arch?.damageStack?.qualifies ? arch.damageStack : (arsenalMatchup?.damageStack || arsenalExactDamageStack(batterRows, contextualRows));
    if (!damageStack?.qualifies || Number(damageStack.count) < 2) return null;
    const score = clamp(Math.round((Number(arsenalMatchup?.overallScore) || 0) + Number(damageStack.score || 70)), 0, 100);
    const reason = `Damage stack: ${damageStack.detail}`;
    return {
      letter,
      label: 'vs Arsenal Imbalance',
      score,
      title: `Damage-stack Arsenal Imbalance. Requires 2+ exact pitch types where hitter SLG and pitcher SLG allowed are both .500+. ${reason}.`,
      detail: reason,
      damageStack,
    };
  }
  if (letter === 'R') {
    const fb = pitcherArchetypeMatchupFamily(batterRows, 'fb');
    const score = clamp(Math.round(
      predictionPoints(fb?.slg, 0.320, 0.620, 28, { fallbackPoints: 11 })
      + predictionPoints(fb?.avg, 0.200, 0.320, 18, { fallbackPoints: 7 })
      + predictionPoints(fb?.whiff, 18, 34, 16, { invert: true, fallbackPoints: 7 })
      + (Number(arsenalMatchup?.overallScore) > 6 ? 10 : 0)
      + 30
    ), 0, 100);
    return {
      letter,
      label: 'vs Repeat Pattern',
      score,
      title: `Sit-on-it profile against lower-K/repeatable sequencing. Batter fastball profile: ${archetypeMatchupMetricText(fb)}.`,
      detail: fb ? `FB ${archetypeMatchupMetricText(fb)}` : 'Timing sample limited',
    };
  }
  return null;
}

const playerVsPitcherArchetypeCache = new Map();
const playerCardFastStatHydrationCache = new Map();

async function getPlayerVsPitcherArchetypeMatchup(profile = null, pitcher = null, game = null) {
  const batterId = Number(profile?.id);
  const pitcherId = Number(pitcher?.id ?? pitcher?.person?.id);
  if (!Number.isFinite(batterId) || batterId <= 0 || !Number.isFinite(pitcherId) || pitcherId <= 0) return null;
  const targetDate = typeof playerStatTargetDate === 'function' ? playerStatTargetDate(game) : (dateInput.value || formatDate(new Date()));
  const cacheKey = `${batterId}:${pitcherId}:${targetDate}:archetype-match-v12`;
  if (playerVsPitcherArchetypeCache.has(cacheKey)) return playerVsPitcherArchetypeCache.get(cacheKey);
  const promise = (async () => {
    const syncedPitcher = await syncedFirstAppearancePitcherProfileForGame(pitcher, game).catch(() => pitcher);
    const pitcherForRows = syncedPitcher || pitcher;
    const pitcherHand = pitcherThrowHandValue(pitcherForRows);
    const batterStand = effectiveBatterHandForPitcher(profile?.bats, pitcherHand) || handednessCode(profile?.bats);
    const pitcherRowPromise = pitcherRowsForBatterForecast(pitcherForRows, game, batterStand ? { stand: batterStand } : {}, 5200).catch(() => ({ rows: [], pitcher: pitcherForRows }));
    const [batterRows, pitcherPayload, batterEventRows] = await Promise.all([
      pitcherHand ? getVisiblePitchBreakdown(batterId, 'batter', 5200, { pThrows: pitcherHand }).catch(() => []) : getVisiblePitchBreakdown(batterId, 'batter', 4200).catch(() => []),
      pitcherRowPromise,
      withTimeoutValue(getSavantPitchEventRows(batterId, 'batter'), 10500, []).catch(() => []),
    ]);
    const pitcherRows = pitcherPayload?.rows || [];
    const matchupPitcher = pitcherPayload?.pitcher || pitcherForRows;
    const starterOnlyEventRows = await filterBatterEventRowsToStartingPitchers(batterEventRows, targetDate).catch(() => []);
    const starterPitcherIds = uniquePitcherIdsFromRows(starterOnlyEventRows);
    const eventDerivedFlameIds = flameQualifiedPitcherIdsFromAvailableEvents(starterOnlyEventRows);
    const activePitcherId = Number(matchupPitcher?.id ?? matchupPitcher?.person?.id ?? pitcherId);
    const activePitcherProfilePromise = Number.isFinite(activePitcherId) && activePitcherId > 0
      ? withTimeoutValue(pitcherSeasonProfilesForArchetypeIds([activePitcherId], targetDate), 5200, new Map()).catch(() => new Map())
      : Promise.resolve(new Map());
    const [starterPitcherProfiles, activePitcherProfileMap, flamePitcherEligibility] = await Promise.all([
      withTimeoutValue(pitcherSeasonProfilesForArchetypeIds(starterPitcherIds, targetDate), 5200, new Map()).catch(() => new Map()),
      activePitcherProfilePromise,
      withTimeoutValue(flamePitcherEligibilityForArchetypeIds(starterPitcherIds, targetDate), 5600, new Map()).catch(() => new Map()),
    ]);
    let activePitcherSeasonProfile = activePitcherProfileMap instanceof Map ? activePitcherProfileMap.get(activePitcherId) : null;
    if (Number.isFinite(activePitcherId) && activePitcherId > 0 && (!activePitcherSeasonProfile || !listify(activePitcherSeasonProfile.archetypes).length)) {
      const season = seasonForDate(targetDate || dateInput?.value || formatDate(new Date()));
      const directPitchingStat = await withTimeoutValue(getPlayerSeasonStatSplit(activePitcherId, 'pitching', season), 4200, null).catch(() => null);
      if (seasonStatHasGameActivity(directPitchingStat, 'pitching') || seasonStatHasValue(directPitchingStat)) {
        const directRow = {
          ...(matchupPitcher || pitcher || {}),
          ...(directPitchingStat || {}),
          id: activePitcherId,
          person: {
            ...(matchupPitcher?.person || pitcher?.person || {}),
            id: activePitcherId,
          },
          fullName: matchupPitcher?.fullName || matchupPitcher?.name || pitcher?.fullName || pitcher?.name,
          name: matchupPitcher?.name || matchupPitcher?.fullName || pitcher?.name || pitcher?.fullName,
          role: 'SP',
          rankRole: 'SP',
          usageRole: 'SP',
          pitching: {
            ...(matchupPitcher?.pitching || pitcher?.pitching || {}),
            ...(directPitchingStat || {}),
          },
          seasonStats: {
            ...(matchupPitcher?.seasonStats || pitcher?.seasonStats || {}),
            pitching: {
              ...(matchupPitcher?.seasonStats?.pitching || pitcher?.seasonStats?.pitching || {}),
              ...(directPitchingStat || {}),
            },
          },
        };
        const directArchetypes = lineupPitcherArchetypes(directRow);
        if (!activePitcherSeasonProfile || directArchetypes.length > listify(activePitcherSeasonProfile.archetypes).length) {
          activePitcherSeasonProfile = {
            row: directRow,
            isStarter: true,
            archetypes: directArchetypes,
            letters: new Set(directArchetypes.filter((arch) => arch.isPrimary || arch.isSecondary).map((arch) => String(arch.letter || '').toUpperCase())),
            directSeasonFallback: true,
          };
        }
      }
    }
    for (const flameId of eventDerivedFlameIds) {
      const current = flamePitcherEligibility.get(flameId) || {};
      flamePitcherEligibility.set(flameId, {
        ...current,
        isStarter: current.isStarter !== false,
        qualifies: true,
        eventDerived: true,
      });
    }
    const contextualPitchRows = pitcherRowsForContextualArchetypes(pitcherRows);
    const arsenal = buildArsenalMatchup(batterRows, contextualPitchRows, {
      batterName: profile?.fullName || profile?.name || 'hitter',
      pitcherName: matchupPitcher?.fullName || matchupPitcher?.name || 'pitcher',
    });
    const usageSummary = pitcherArsenalUsageSummaryFromRows(contextualPitchRows);
    const hasCurrentPitchRows = pitcherHasCurrentPitchUsageRows(contextualPitchRows);
    const currentBagSummary = pitcherPitchBagSummary({ pitchBreakdown: contextualPitchRows, pitchMix: contextualPitchRows, pitchRows: contextualPitchRows });
    const contextualBagArchetype = pitchBagArchetypeFromSummary(currentBagSummary);
    const contextualImbalanceArchetype = arsenalImbalanceArchetypeFromDamageStack(arsenal?.damageStack);
    const bagArchetypeAllowed = (arch) => pitcherBagArchetypeIsAllowed(arch?.letter, currentBagSummary, hasCurrentPitchRows);
    const seasonProfileRow = activePitcherSeasonProfile?.row || null;
    const pitcherForArchetypes = {
      ...(seasonProfileRow || {}),
      ...(matchupPitcher || pitcher || {}),
      id: activePitcherId || pitcherId,
      person: {
        ...(seasonProfileRow?.person || {}),
        ...(matchupPitcher?.person || pitcher?.person || {}),
        id: activePitcherId || pitcherId,
      },
      fullName: matchupPitcher?.fullName || matchupPitcher?.name || seasonProfileRow?.fullName || seasonProfileRow?.name || pitcher?.fullName || pitcher?.name,
      name: matchupPitcher?.name || matchupPitcher?.fullName || seasonProfileRow?.name || seasonProfileRow?.fullName || pitcher?.name || pitcher?.fullName,
      pitchBreakdown: contextualPitchRows.length ? contextualPitchRows : listify(seasonProfileRow?.pitchBreakdown || seasonProfileRow?.pitchMix || []),
      pitchMix: contextualPitchRows.length ? contextualPitchRows : listify(seasonProfileRow?.pitchMix || seasonProfileRow?.pitchBreakdown || []),
    };
    const directArchetypes = listify(lineupPitcherArchetypes(pitcherForArchetypes))
      .filter((arch) => arch?.letter && (arch.isPrimary || arch.isSecondary || Number(arch.confidence) >= 52))
      .filter(bagArchetypeAllowed);
    const seasonProfileArchetypes = listify(activePitcherSeasonProfile?.archetypes)
      .filter((arch) => arch?.letter && (arch.isPrimary || arch.isSecondary || Number(arch.confidence) >= 52))
      .filter(bagArchetypeAllowed);
    const archetypeByLetter = new Map();
    [...seasonProfileArchetypes, ...directArchetypes, contextualBagArchetype, contextualImbalanceArchetype].forEach((arch) => {
      const letter = String(arch?.letter || '').toUpperCase();
      if (!letter) return;
      const current = archetypeByLetter.get(letter);
      if (!current || Number(arch.confidence || arch.score || 0) > Number(current.confidence || current.score || 0) || arch.contextualBag || arch.contextualImbalance) {
        archetypeByLetter.set(letter, arch);
      }
    });
    let archetypeCandidates = [...archetypeByLetter.values()].filter((arch) => String(arch?.letter || '').toUpperCase() !== 'I');
    if (contextualImbalanceArchetype) {
      archetypeCandidates.push(contextualImbalanceArchetype);
      archetypeCandidates.sort((a, b) => Number(b.score || b.confidence || 0) - Number(a.score || a.confidence || 0));
    }
    const archetypes = archetypeCandidates
      .filter(bagArchetypeAllowed)
      .slice(0, 5);
    const matchups = archetypes
      .map((arch) => {
        const scored = scoreBatterVsPitcherArchetype(arch, batterRows, contextualPitchRows, arsenal, pitcherForArchetypes);
        if (!scored) return null;
        const archetypeStarterRows = filterStarterEventRowsForPitcherArchetype(starterOnlyEventRows, arch, starterPitcherProfiles, flamePitcherEligibility);
        const eventSummary = archetypeEventRowSummary(arch, archetypeStarterRows, matchupPitcher, profile);
        let familyEventSummary = archetypePitchFamilyEventSummary(arch, archetypeStarterRows, contextualPitchRows, profile);
        if (String(arch?.letter || '').toUpperCase() === 'K'
          && !archetypeSummaryHasUsableSample(eventSummary)
          && !archetypeSummaryHasUsableSample(familyEventSummary)) {
          const starterSecondaryFallback = archetypePitchFamilyEventSummary(arch, starterOnlyEventRows, contextualPitchRows, profile);
          if (archetypeSummaryHasUsableSample(starterSecondaryFallback)) {
            familyEventSummary = {
              ...starterSecondaryFallback,
              limited: true,
              starterOnly: true,
              source: 'starter-only-secondary-finesse-fallback',
            };
          }
        }
        const emptyStarterSummary = {
          categories: archetypePitchCategories(arch, contextualPitchRows),
          h: null,
          ab: null,
          slg: null,
          hr: null,
          limited: true,
          starterOnly: true,
          source: 'starter-only-archetype-events',
          pitchers: [],
          pitcherIds: [],
        };
        const summary = archetypeSummaryHasUsableSample(eventSummary)
          ? eventSummary
          : (archetypeSummaryHasUsableSample(familyEventSummary) ? familyEventSummary : emptyStarterSummary);
        summary.starterOnly = true;
        if (String(arch?.letter || '').toUpperCase() === 'I' && scored?.damageStack?.qualifies) {
          const currentPitcherName = cleanSummary(matchupPitcher?.fullName || matchupPitcher?.name || pitcherForArchetypes?.fullName || pitcherForArchetypes?.name || pitcher?.fullName || pitcher?.name || '');
          if (currentPitcherName) {
            summary.currentPitcherName = currentPitcherName;
            summary.pitchers = dedupeTooltipPitcherNames([currentPitcherName, ...listify(summary.pitchers)], [profile?.fullName, profile?.name]);
          }
          summary.currentPitcherId = activePitcherId || pitcherId || null;
          summary.currentPitcherDamageStack = true;
        }
        if (!summary.pitchers?.length && familyEventSummary.pitchers?.length) summary.pitchers = familyEventSummary.pitchers;
        if (!summary.categories?.length && familyEventSummary.categories?.length) summary.categories = familyEventSummary.categories;
        return { ...scored, summary };
      })
      .filter(Boolean)
      .sort((a, b) => b.score - a.score);
    await hydrateArchetypeMatchupPitcherNames(matchups, profile);
    return { matchups, arsenal, pitcherName: pitcher?.fullName || pitcher?.name || 'pitcher' };
  })().catch((error) => {
    playerVsPitcherArchetypeCache.delete(cacheKey);
    throw error;
  });
  playerVsPitcherArchetypeCache.set(cacheKey, promise);
  return promise;
}

function archetypeStatlineHoverTitle(row = {}, pitcherName = '') {
  const summary = row.displaySummary || row.summary || {};
  const lines = [];
  const label = String(row.label || row.title || 'Pitcher archetype').replace(/^vs\s+/i, '');
  const letter = String(row?.letter || '').toUpperCase();
  const pitchers = dedupeTooltipPitcherNames(summary.pitchers, []);
  lines.push(`${label}${pitcherName ? ` vs ${pitcherName}` : ''}`);
  if (row.title) lines.push(String(row.title));
  const categories = uniquePitchCategories(listify(summary.categories).map(visiblePitchCategoryName).filter(Boolean));
  if (categories.length) lines.push(`Pitch families used: ${categories.join(', ')}`);

  if (letter === 'I' && row?.damageStack?.qualifies) {
    const currentPitcher = cleanSummary(summary.currentPitcherName || pitcherName || '');
    if (currentPitcher) lines.push(`Current pitcher: ${currentPitcher}`);
    const damageRows = listify(row.damageStack.rows);
    if (damageRows.length) {
      lines.push('Qualifying pitch damage:');
      damageRows.slice(0, 6).forEach((item) => {
        const parts = [
          `${cleanSummary(item.category || 'Pitch')}`,
          `H ${formatRateValue(item.hitterSlg, 3, true)}`,
          `P ${formatRateValue(item.pitcherSlg, 3, true)}`,
        ];
        if (Number.isFinite(Number(item.hitterHits)) && Number.isFinite(Number(item.hitterAb)) && Number(item.hitterAb) > 0) {
          parts.push(`H-AB ${Math.round(Number(item.hitterHits))}-${Math.round(Number(item.hitterAb))}`);
        }
        if (Number.isFinite(Number(item.usagePct))) parts.push(`${arsenalMetricText(item.usagePct, 1, false, '%')}`);
        lines.push(`• ${parts.join(' | ')}`);
      });
    }
    const statlines = listify(summary.pitcherStatlines)
      .filter((line) => Number.isFinite(Number(line?.ab)) && Number(line.ab) > 0)
      .sort((a, b) => Number(b.ab || 0) - Number(a.ab || 0) || String(a.pitcherName || '').localeCompare(String(b.pitcherName || '')));
    if (statlines.length) {
      lines.push('Historical starter sample:');
      statlines.slice(0, 8).forEach((line) => {
        const name = cleanSummary(line.pitcherName || (line.pitcherId ? `Pitcher ${line.pitcherId}` : 'Pitcher'));
        lines.push(`• ${name}: ${formatArchetypeHab(line)} | ${formatArchetypeSlg(line)} SLG | HR ${formatArchetypeHr(line)}`);
      });
      if (statlines.length > 8) lines.push(`• +${statlines.length - 8} more pitcher statlines`);
    } else if (pitchers.length > 1) {
      lines.push('Historical starter names:');
      pitchers.filter((name) => normalizedTooltipNameKey(name) !== normalizedTooltipNameKey(currentPitcher)).slice(0, 8).forEach((name) => lines.push(`• ${name}`));
    }
    lines.push('Sample scope: current pitcher exact-pitch damage stack; relief/closer historical rows excluded where available.');
    if (summary.limited) lines.push('Sample note: limited archetype-specific sample.');
    return lines.filter(Boolean).join('\n');
  }

  lines.push(summary.starterOnly ? 'Starting pitchers in sample:' : 'Pitchers in sample:');
  const statlines = listify(summary.pitcherStatlines)
    .filter((line) => Number.isFinite(Number(line?.ab)) && Number(line.ab) > 0)
    .sort((a, b) => Number(b.ab || 0) - Number(a.ab || 0) || String(a.pitcherName || '').localeCompare(String(b.pitcherName || '')));
  if (statlines.length) {
    lines.push('Pitcher statlines:');
    statlines.slice(0, 12).forEach((line) => {
      const name = cleanSummary(line.pitcherName || (line.pitcherId ? `Pitcher ${line.pitcherId}` : 'Pitcher'));
      lines.push(`• ${name}: ${formatArchetypeHab(line)} | ${formatArchetypeSlg(line)} SLG | HR ${formatArchetypeHr(line)}`);
    });
    if (statlines.length > 12) lines.push(`• +${statlines.length - 12} more pitcher statlines`);
  } else if (pitchers.length) {
    pitchers.slice(0, 12).forEach((name) => lines.push(`• ${name}`));
    if (pitchers.length > 12) lines.push(`• +${pitchers.length - 12} more unique pitchers`);
  } else {
    lines.push(summary.starterOnly ? '• No qualifying starting-pitcher names available for this sample' : '• Pitcher names unavailable for this sample');
  }
  if (summary.starterOnly) lines.push('Sample scope: starting pitchers only; relief/closer rows excluded.');
  if (summary.limited) lines.push('Sample note: limited archetype-specific sample.');
  return lines.filter(Boolean).join('\n');
}

function playerVsPitcherArchetypeLoadingRows(pitcherForRows = {}, loading = false, noSample = false) {
  const existing = listify(lineupPitcherArchetypes(pitcherForRows))
    .filter((arch) => arch?.letter && (arch.isPrimary || arch.isSecondary || Number(arch.confidence) >= 52));
  const rows = existing.map((arch) => ({
    letter: arch.letter,
    label: `vs ${arch.label || arch.name || 'Pitcher Type'}`,
    title: arch.description || arch.title || `${arch.label || 'Pitcher archetype'} profile.`,
    score: Number(arch.confidence) || 50,
    summary: {
      h: null,
      ab: null,
      slg: null,
      hr: null,
      loading: Boolean(loading),
      noSample: Boolean(noSample || !loading),
      limited: true,
      starterOnly: true,
      categories: archetypePitchCategories(arch, pitcherForRows.pitchMix || []),
    },
  }));

  // Do not show every possible archetype as a placeholder. Only show the archetypes
  // the opposing pitcher currently qualifies for. If the async sample finishes with no
  // usable rows, make that a final state instead of leaving the card stuck on loading.
  if (!rows.length && (loading || noSample || pitcherForRows?.id || pitcherForRows?.person?.id)) {
    rows.push({
      letter: loading ? '…' : '—',
      label: loading ? 'Loading pitcher type' : 'No archetype sample',
      title: loading ? 'Loading the opposing pitcher archetype profile.' : 'No qualifying starter-only batter-vs-archetype sample found for this matchup.',
      score: 50,
      summary: { h: null, ab: null, slg: null, hr: null, loading: Boolean(loading), noSample: !loading, limited: true, starterOnly: true, categories: [] },
    });
  }
  return rows;
}

function playerVsPitcherArchetypeCardHtml(matchup = null, pitcher = null, loading = false, handed = null, matchupHand = '') {
  if (!pitcher?.id && !pitcher?.person?.id) return '';
  const pitcherForRows = {
    ...(pitcher || {}),
    pitchBreakdown: pitcher?.pitchBreakdown || pitcher?.pitchMix || pitcher?.pitchRows || [],
    pitchMix: pitcher?.pitchMix || pitcher?.pitchBreakdown || pitcher?.pitchRows || [],
  };
  const resolvedMatchups = listify(matchup?.matchups).filter((row) => row?.letter);
  const profileArchetypes = listify(lineupPitcherArchetypes(pitcherForRows))
    .filter((arch) => arch?.letter && (arch.isPrimary || arch.isSecondary || Number(arch.confidence) >= 52));
  // Once the async matchup has resolved, trust its pitcher-archetype rows. Re-filtering those rows
  // against the older/base pitcher object was dropping F/L/I/R rows whenever velocity/usage hydrated late.
  const activePitcherArchetypes = resolvedMatchups.length ? resolvedMatchups : profileArchetypes;
  const activeLetters = new Set(activePitcherArchetypes.map((arch) => String(arch.letter || '').toUpperCase()).filter(Boolean));
  const sourceMatchups = resolvedMatchups.length
    ? resolvedMatchups
    : [];
  const fallbackRows = playerVsPitcherArchetypeLoadingRows(pitcherForRows, loading);
  const sourceRows = sourceMatchups.length ? sourceMatchups : fallbackRows;
  const byLetter = new Map();
  [...sourceRows, ...(loading ? fallbackRows : [])].forEach((row) => {
    const letter = String(row?.letter || '').toUpperCase();
    if (!letter) return;
    if (activeLetters.size && !activeLetters.has(letter)) return;
    const existing = byLetter.get(letter);
    const rowHasSample = archetypeSummaryHasUsableSample(row?.summary || row?.displaySummary || {});
    const existingHasSample = archetypeSummaryHasUsableSample(existing?.summary || existing?.displaySummary || {});
    if (!existing || (rowHasSample && !existingHasSample) || Number(row?.score || 0) > Number(existing?.score || 0)) byLetter.set(letter, row);
  });
  const rows = [...byLetter.values()]
    .map((row) => ({ ...row, displaySummary: archetypeDisplaySummary(row, handed, matchupHand) }))
    .filter((row) => {
      const letter = String(row?.letter || '').toUpperCase();
      if (!letter) return false;
      if (letter === 'I') return Boolean(row?.damageStack?.qualifies) && Number(row?.damageStack?.count || 0) >= 2;
      if (row.displaySummary?.loading || row.displaySummary?.noSample) return true;
      // Do not render score-only archetype rows. If there is no H-AB, SLG, or HR sample,
      // the table looks like an attribution error and the tooltip cannot explain the row.
      return archetypeSummaryHasUsableSample(row.displaySummary || row.summary || {});
    })
    .sort((a, b) => {
      const order = { F: 0, K: 1, RS: 2, L: 3, I: 4, A: 4, DB: 5, SB: 5, R: 6 };
      const ao = order[String(a.letter || '').toUpperCase()] ?? 99;
      const bo = order[String(b.letter || '').toUpperCase()] ?? 99;
      return ao - bo || Number(b.score || 0) - Number(a.score || 0);
    })
    .slice(0, 5);
  if (!rows.length) return '';
  const pitcherName = matchup?.pitcherName || pitcher?.fullName || pitcher?.name || 'Pitcher';
  const handLabel = handednessCode(matchupHand) ? ` vs ${handednessCode(matchupHand)}HP` : '';
  const title = `Vs pitcher archetype profile for ${pitcherName}${handLabel}`;
  return `
    <div class="player-archetype-matchup-card${loading ? ' is-loading' : ''}" title="${escapeHtml(title)}">
      <table class="player-stat-table handed-splits-table player-archetype-matchup-table">
        <thead><tr><th>Archetype</th><th>H-AB</th><th>SLG</th><th>HR</th></tr></thead>
        <tbody>
          ${rows.map((row) => {
            const hoverTitle = archetypeStatlineHoverTitle(row, pitcherName);
            const loadingClass = row.displaySummary?.loading ? ' is-loading' : '';
            return `
            <tr class="${row.score >= 66 ? 'is-batter' : row.score <= 42 ? 'is-pitcher' : 'is-neutral'}${row.displaySummary?.limited ? ' is-limited' : ''}${loadingClass}" title="${escapeHtml(hoverTitle)}">
              <th title="${escapeHtml(hoverTitle)}">${pitcherArchetypeShortLabel(row, pitcherForRows)}</th>
              <td title="${escapeHtml(hoverTitle)}">${row.displaySummary?.loading ? playerStatLoadingDotsHtml('Loading H-AB') : escapeHtml(formatArchetypeHab(row.displaySummary))}</td>
              <td title="${escapeHtml(hoverTitle)}">${row.displaySummary?.loading ? playerStatLoadingDotsHtml('Loading SLG') : escapeHtml(formatArchetypeSlg(row.displaySummary))}</td>
              <td title="${escapeHtml(hoverTitle)}">${row.displaySummary?.loading ? playerStatLoadingDotsHtml('Loading HR') : escapeHtml(formatArchetypeHr(row.displaySummary))}</td>
            </tr>
          `;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;
}


function updatePlayerSeasonArchetypeTable(html = '') {
  if (!playerStatSeasonEl) return;
  const existing = playerStatSeasonEl.querySelector('[data-player-season-archetype-slot]');
  if (!html) {
    if (existing) existing.remove();
    return;
  }
  if (existing) {
    existing.outerHTML = `<div data-player-season-archetype-slot>${html}</div>`;
    return;
  }
  playerStatSeasonEl.insertAdjacentHTML('beforeend', `<div data-player-season-archetype-slot>${html}</div>`);
}

function battingContextHtml(splits = null, matchupHand = '') {
  return `
    ${splits ? handedSplitsTableHtml(splits, matchupHand) : '<div class="player-stat-loading">Loading handed splits</div>'}
  `;
}

function formatProjectedSeasonTotal(total, games) {
  const count = statNumber(total);
  const played = statNumber(games);
  if (played <= 0) return '---';
  return formatRateValue((count / played) * 162, 1, false);
}

function formatProjectedRemainingSeasonTotal(total, playerGames, teamGamesPlayed = playerGames) {
  const count = statNumber(total);
  const played = statNumber(playerGames);
  const teamPlayed = statNumber(teamGamesPlayed) || played;
  if (played <= 0) return '---';
  const gamesLeft = Math.max(0, 162 - teamPlayed);
  return formatRateValue(count + ((count / played) * gamesLeft), 1, false);
}

function formatGamesPerEvent(total, games) {
  const count = statNumber(total);
  const played = statNumber(games);
  if (count <= 0 || played <= 0) return '---';
  return formatRateValue(played / count, 1, false);
}

function formatGamesPerEventLabel(total, games, label) {
  const value = formatGamesPerEvent(total, games);
  return value === '---' ? '---' : `${value} per ${label}`;
}

function gamesFromRecordString(record = '') {
  const parsed = parseRecordValue(record);
  const games = statNumber(parsed.wins) + statNumber(parsed.losses);
  return games > 0 ? games : 0;
}

function battingProjectionGames(profile, game = null) {
  const batting = profile?.batting || {};
  const direct = statNumber(
    batting.playerGames
    ?? batting.gamesPlayed
    ?? profile?.playerGames
    ?? profile?.playerGamesPlayed
  );
  if (direct > 0) return direct;

  const team = String(profile?.teamAbbrev || '').toUpperCase();
  if (!team || !game) return 0;
  if (String(game.away || '').toUpperCase() === team) {
    return gamesFromRecordString(game.awayRecord);
  }
  if (String(game.home || '').toUpperCase() === team) {
    return gamesFromRecordString(game.homeRecord);
  }
  return 0;
}

function battingProjectionTeamGames(profile, game = null) {
  const team = String(profile?.teamAbbrev || '').toUpperCase();
  if (!team || !game) return battingProjectionGames(profile, game);
  if (String(game.away || '').toUpperCase() === team) return gamesFromRecordString(game.awayRecord);
  if (String(game.home || '').toUpperCase() === team) return gamesFromRecordString(game.homeRecord);
  return battingProjectionGames(profile, game);
}

function formatGamesSinceEvent(value) {
  const count = Number(value);
  if (!Number.isFinite(count) || count < 0) return '---';
  return `${Math.floor(count)} games`;
}

function battingProjectionRows(profile, game = null, gamesSince = null) {
  const batting = profile?.batting || {};
  const games = battingProjectionGames(profile, game);
  const teamGames = battingProjectionTeamGames(profile, game);
  const homeRuns = statNumber(batting.hr);
  const extraBaseHits = statNumber(batting.doubles) + statNumber(batting.triples) + homeRuns;
  return [
    ['Proj HR', formatProjectedRemainingSeasonTotal(homeRuns, games, teamGames || games)],
    ['Proj XBH', formatProjectedRemainingSeasonTotal(extraBaseHits, games, teamGames || games)],
    ['Per HR', formatGamesPerEventLabel(homeRuns, games, 'HR')],
    ['Per XBH', formatGamesPerEventLabel(extraBaseHits, games, 'XBH')],
    ['Since HR', formatGamesSinceEvent(gamesSince?.hr)],
    ['Since XBH', formatGamesSinceEvent(gamesSince?.xbh)],
  ];
}

function pitcherOpponentHandSeed(profile, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(profile?.id);
  const nameKey = normalizeNameKey(profile?.fullName || profile?.name || '');
  const seed = FANGRAPHS_PITCHER_HAND_SPLIT_SEEDS[nameKey]
    || Object.values(FANGRAPHS_PITCHER_HAND_SPLIT_SEEDS).find((entry) => Number(entry.playerId) === id)
    || null;
  if (!seed || Number(seed.season) !== Number(season)) return null;
  return seed;
}

async function getPitcherOpponentHandSplit(playerId, sitCode, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0 || !sitCode) return null;
  const cacheKey = `pitcher:${id}:${season}:${sitCode}`;
  if (pitcherOpponentHandSplitsCache.has(cacheKey)) return pitcherOpponentHandSplitsCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'statSplits');
    url.searchParams.set('group', 'pitching');
    url.searchParams.set('season', String(season));
    url.searchParams.set('gameType', 'R');
    url.searchParams.set('sportIds', '1');
    url.searchParams.set('sitCodes', sitCode);
    const response = await getJson(url.toString());
    return response?.stats?.[0]?.splits?.[0]?.stat || null;
  })().catch((error) => {
    pitcherOpponentHandSplitsCache.delete(cacheKey);
    throw error;
  });
  pitcherOpponentHandSplitsCache.set(cacheKey, promise);
  return promise;
}


function pitcherOpponentHandStatHasData(stat = null) {
  if (!stat) return false;
  return Number(statNumber(stat.atBats ?? stat.ab ?? stat.plateAppearances ?? stat.pa ?? stat.battersFaced)) > 0
    || Number(statNumber(stat.hits ?? stat.h)) > 0
    || Number(statNumber(stat.homeRuns ?? stat.hrAllowed ?? stat.hr)) > 0
    || Number(statNumber(stat.strikeOuts ?? stat.so)) > 0
    || Boolean(cleanSummary(stat.avg || stat.slg || stat.ops || stat.obp));
}

function pitcherOpponentHandSeasonForProfile(profile = null, fallback = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const sourceSeason = Number(profile?.seasonStatSource?.pitching?.season || profile?.seasonStatSource?.pitching?.sourceSeason || 0);
  return Number.isFinite(sourceSeason) && sourceSeason > 1900 ? sourceSeason : fallback;
}

const pitcherOpponentHandGameLogSplitCache = new Map();

async function getPitcherOpponentHandSplitsFromGameLogs(profile, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const id = Number(profile?.id);
  const targetSeason = Number(season);
  if (!Number.isFinite(id) || id <= 0 || !Number.isFinite(targetSeason) || targetSeason <= 1900) return null;
  const cacheKey = `${id}:${targetSeason}:season-hand-from-game-feeds-v1`;
  if (pitcherOpponentHandGameLogSplitCache.has(cacheKey)) return pitcherOpponentHandGameLogSplitCache.get(cacheKey);
  const promise = (async () => {
    const splits = await playerStatGameLogSplits(id, 'pitching', null, targetSeason).catch(() => []);
    const gamePks = [...new Set(listify(splits)
      .sort((a, b) => String(b?.date || '').localeCompare(String(a?.date || '')))
      .map((split) => statLogSplitGamePk(split))
      .filter((pk) => Number.isFinite(Number(pk)) && Number(pk) > 0))];
    if (!gamePks.length) return null;
    const summary = { vsLeft: emptyPitcherRecentHandStat(), vsRight: emptyPitcherRecentHandStat() };
    let found = false;
    await mapWithConcurrency(gamePks, 3, async (gamePk) => {
      const feed = await getLiveGameFeed(gamePk).catch(() => null);
      let gameFound = false;
      for (const play of listify(feed?.liveData?.plays?.allPlays)) {
        if (addPitcherRecentHandPlay(summary, play, id)) {
          found = true;
          gameFound = true;
        }
      }
      if (gameFound) {
        summary.vsLeft.sourceGames += 1;
        summary.vsRight.sourceGames += 1;
      }
    });
    if (!found) return null;
    return {
      vsLeft: finalizePitcherRecentHandStat(summary.vsLeft),
      vsRight: finalizePitcherRecentHandStat(summary.vsRight),
      source: `${targetSeason} MLB game-feed handedness fallback`,
    };
  })().catch((error) => {
    pitcherOpponentHandGameLogSplitCache.delete(cacheKey);
    throw error;
  });
  pitcherOpponentHandGameLogSplitCache.set(cacheKey, promise);
  return promise;
}

async function getPitcherOpponentHandSplits(profile, season = seasonForDate(dateInput.value || formatDate(new Date()))) {
  const targetSeason = pitcherOpponentHandSeasonForProfile(profile, season);
  const seed = pitcherOpponentHandSeed(profile, targetSeason);
  const [apiLeft, apiRight] = await Promise.all([
    getPitcherOpponentHandSplit(profile?.id, 'vl', targetSeason).catch(() => null),
    getPitcherOpponentHandSplit(profile?.id, 'vr', targetSeason).catch(() => null),
  ]);
  if (seed) {
    return {
      vsLeft: { ...(apiLeft || {}), ...(seed.vsLeft || {}) },
      vsRight: { ...(apiRight || {}), ...(seed.vsRight || {}) },
      source: seed.source,
      sourceUrl: seed.sourceUrl,
    };
  }
  if (pitcherOpponentHandStatHasData(apiLeft) || pitcherOpponentHandStatHasData(apiRight)) {
    return { vsLeft: apiLeft, vsRight: apiRight, source: `${targetSeason} MLB Stats API` };
  }
  const gameLogFallback = await getPitcherOpponentHandSplitsFromGameLogs(profile, targetSeason).catch(() => null);
  if (gameLogFallback) return gameLogFallback;
  return { vsLeft: apiLeft, vsRight: apiRight, source: `${targetSeason} MLB Stats API` };
}

function pitcherOpponentHandValue(stat, key) {
  if (!stat) return '---';
  if (key === 'avg') return cleanSummary(stat.avg) || '---';
  if (key === 'slg') return cleanSummary(stat.slg) || '---';
  if (key === 'homeRuns') return statNumber(stat.homeRuns ?? stat.hrAllowed ?? stat.hr);
  if (key === 'strikeOuts') return statNumber(stat.strikeOuts ?? stat.so);
  return '---';
}

function pitcherOpponentHandHits(stat = {}) {
  const direct = statNumber(stat?.hits ?? stat?.h);
  if (direct > 0) return direct;
  const avg = rateNumber(stat?.avg);
  const atBats = statNumber(stat?.atBats ?? stat?.ab);
  if (Number.isFinite(avg) && atBats > 0) return avg * atBats;
  const plateAppearances = statNumber(stat?.plateAppearances ?? stat?.pa);
  if (Number.isFinite(avg) && plateAppearances > 0) return avg * plateAppearances;
  return 0;
}

function pitcherOpponentHandPaProxy(stat = {}) {
  return statNumber(
    stat?.plateAppearances
      ?? stat?.battersFaced
      ?? stat?.totalBattersFaced
      ?? stat?.atBats
      ?? stat?.ab,
  );
}

function pitcherOpponentHandDoublePlayOuts(stat = {}) {
  return statNumber(
    stat?.groundIntoDoublePlay
      ?? stat?.groundIntoDoublePlays
      ?? stat?.groundedIntoDoublePlay
      ?? stat?.groundedIntoDoublePlays
      ?? stat?.gidp
      ?? stat?.gdp
      ?? stat?.doublePlays,
  );
}

function pitcherOpponentHandWalks(stat = {}) {
  return statNumber(stat?.baseOnBalls ?? stat?.walks ?? stat?.bb);
}

function pitcherOpponentHandHitByPitch(stat = {}) {
  return statNumber(stat?.hitByPitch ?? stat?.hitBatsmen ?? stat?.hbp);
}

function pitcherOpponentHandSacrificeOuts(stat = {}) {
  const flies = statNumber(stat?.sacFlies ?? stat?.sacrificeFlies);
  const bunts = statNumber(stat?.sacBunts ?? stat?.sacrificeBunts);
  const total = statNumber(stat?.sacrifices);
  return total > 0 ? Math.max(total, flies + bunts) : flies + bunts;
}

function pitcherOpponentHandOutCount(value) {
  if (value == null || value === '') return 0;
  const raw = String(value).trim();
  if (raw.includes('.')) return inningsToOuts(raw);
  const outs = Number(raw);
  return Number.isFinite(outs) ? outs : 0;
}

function pitcherOpponentHandOutsProxy(stat = {}) {
  const statOuts = pitcherOpponentHandOutCount(stat?.outsPitched ?? stat?.outs);
  if (statOuts > 0) return statOuts;
  const directOuts = inningsToOuts(stat?.inningsPitched ?? stat?.ip);
  if (directOuts > 0) return directOuts;
  const hits = pitcherOpponentHandHits(stat);
  const doublePlayOuts = pitcherOpponentHandDoublePlayOuts(stat);
  const sacrificeOuts = pitcherOpponentHandSacrificeOuts(stat);
  const atBats = statNumber(stat?.atBats ?? stat?.ab);
  if (atBats > 0) return Math.max(0, atBats - hits + sacrificeOuts + doublePlayOuts);
  const plateAppearances = pitcherOpponentHandPaProxy(stat);
  if (plateAppearances > 0) {
    return Math.max(0, plateAppearances - hits - pitcherOpponentHandWalks(stat) - pitcherOpponentHandHitByPitch(stat) + doublePlayOuts);
  }
  return 0;
}

function pitcherOpponentHandHr9(stat = {}) {
  if (!stat) return null;
  const homeRuns = statNumber(stat?.homeRuns ?? stat?.hrAllowed ?? stat?.hr);
  const official = rateNumber(stat?.homeRunsPer9 ?? stat?.homeRunsPer9Inn ?? stat?.hr9);
  if (Number.isFinite(official) && !(official === 0 && homeRuns > 0)) return official;
  const outsProxy = pitcherOpponentHandOutsProxy(stat);
  const ipProxy = outsProxy / 3;
  return ipProxy > 0 ? (homeRuns * 9) / ipProxy : null;
}

function pitcherOpponentHandHr9Text(stat = {}) {
  const hr9 = pitcherOpponentHandHr9(stat);
  return Number.isFinite(hr9) ? hr9.toFixed(2) : '--';
}

function pitcherOpponentHandAvgMarker(stat, hand) {
  const avg = rateNumber(stat?.avg);
  const slg = rateNumber(stat?.slg);
  const code = handednessCode(hand);
  if (!code) return '';
  const markers = [];
  if (Number.isFinite(avg) && avg < 0.210) {
    markers.push(`<span class="pitcher-hand-avg-marker is-low" title="Opponent ${code} AVG ${formatRateValue(avg, 3, true)}">${code}</span>`);
  }
  if (Number.isFinite(avg) && avg >= 0.300) {
    markers.push(`<span class="pitcher-hand-avg-marker is-high" title="Opponent ${code} AVG ${formatRateValue(avg, 3, true)}">${code}</span>`);
  }
  if (Number.isFinite(slg) && slg > 0.600) {
    markers.push(`<span class="pitcher-hand-avg-marker is-power" title="Opponent ${code} SLG ${formatRateValue(slg, 3, true)}">${code}</span>`);
  }
  return markers.join('');
}

function pitcherOpponentHandStackCell(stat, recentStat, key, options = {}) {
  const seasonValue = key === 'hr9'
    ? pitcherOpponentHandHr9Text(stat)
    : pitcherOpponentHandValue(stat, key);
  const recentValue = recentStat
    ? (key === 'hr9' ? '--' : pitcherOpponentHandValue(recentStat, key))
    : '';
  const safeSeason = escapeHtml(seasonValue ?? '--');
  const safeRecent = escapeHtml(recentValue ?? '--');
  const hasRecent = recentStat && safeRecent !== '' && safeRecent !== '---' && safeRecent !== '--';
  const recentLabel = options.recentLabel || 'L3 GS';
  const title = hasRecent
    ? `${options.label || key.toUpperCase()}: season ${seasonValue || '--'} | ${recentLabel} ${recentValue || '--'}`
    : `${options.label || key.toUpperCase()}: season ${seasonValue || '--'}`;
  return `<td class="pitcher-hand-stacked-cell" title="${escapeHtml(title)}"><span class="pitcher-hand-season">${safeSeason}</span>${hasRecent ? `<br><em class="pitcher-hand-l3">${safeRecent}</em>` : ''}</td>`;
}

function pitcherOpponentHandRow(label, stat, recentStat = null) {
  return `
    <tr>
      <th>${escapeHtml(label)}</th>
      ${pitcherOpponentHandStackCell(stat, recentStat, 'avg', { label: 'Opp AVG' })}
      ${pitcherOpponentHandStackCell(stat, recentStat, 'slg', { label: 'Opp SLG' })}
      ${pitcherOpponentHandStackCell(stat, recentStat, 'homeRuns', { label: 'HR' })}
      ${pitcherOpponentHandStackCell(stat, null, 'hr9', { label: 'HR/9' })}
      ${pitcherOpponentHandStackCell(stat, recentStat, 'strikeOuts', { label: 'K' })}
    </tr>
  `;
}

function emptyPitcherRecentHandStat() {
  return { atBats: 0, hits: 0, totalBases: 0, homeRuns: 0, strikeOuts: 0, sourceGames: 0 };
}

function finalizePitcherRecentHandStat(stat = {}) {
  const atBats = statNumber(stat.atBats);
  const hits = statNumber(stat.hits);
  const totalBases = statNumber(stat.totalBases);
  return {
    ...stat,
    avg: atBats > 0 ? formatRateValue(hits / atBats, 3, true) : '---',
    slg: atBats > 0 ? formatRateValue(totalBases / atBats, 3, true) : '---',
  };
}

function addPitcherRecentHandPlay(summary, play, pitcherId) {
  const id = Number(pitcherId);
  if (!Number.isFinite(id) || Number(play?.matchup?.pitcher?.id) !== id) return false;
  const batterHand = handednessCode(play?.matchup?.batSide?.code || play?.matchup?.batSide?.description || '');
  if (batterHand !== 'L' && batterHand !== 'R') return false;
  const event = String(play?.result?.eventType || '').toLowerCase();
  if (!event) return false;
  const target = batterHand === 'L' ? summary.vsLeft : summary.vsRight;
  if (battingEventCountsAtBat(event)) target.atBats += 1;
  const bases = battingEventTotalBases(event);
  if (bases > 0) target.hits += 1;
  target.totalBases += bases;
  if (event === 'home_run') target.homeRuns += 1;
  if (/strikeout|strike_out/.test(event)) target.strikeOuts += 1;
  return true;
}

const pitcherRecentOpponentHandSplitsCache = new Map();

async function getPitcherRecentOpponentHandSplits(playerId, starts = []) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const gamePks = [...new Set(listify(starts).slice(0, 3).map((split) => statLogSplitGamePk(split)).filter((pk) => Number.isFinite(Number(pk)) && Number(pk) > 0))];
  if (!gamePks.length) return null;
  const cacheKey = `${id}:${gamePks.join(',')}:last3-hand`;
  if (pitcherRecentOpponentHandSplitsCache.has(cacheKey)) return pitcherRecentOpponentHandSplitsCache.get(cacheKey);
  const promise = (async () => {
    const summary = { vsLeft: emptyPitcherRecentHandStat(), vsRight: emptyPitcherRecentHandStat(), source: 'Last 3 Starts' };
    let found = false;
    await mapWithConcurrency(gamePks, 3, async (gamePk) => {
      const feed = await getLiveGameFeed(gamePk).catch(() => null);
      let gameFound = false;
      for (const play of listify(feed?.liveData?.plays?.allPlays)) {
        if (addPitcherRecentHandPlay(summary, play, id)) {
          found = true;
          gameFound = true;
        }
      }
      if (gameFound) {
        summary.vsLeft.sourceGames += 1;
        summary.vsRight.sourceGames += 1;
      }
    });
    if (!found) return null;
    return {
      vsLeft: finalizePitcherRecentHandStat(summary.vsLeft),
      vsRight: finalizePitcherRecentHandStat(summary.vsRight),
      source: summary.source,
    };
  })().catch((error) => {
    pitcherRecentOpponentHandSplitsCache.delete(cacheKey);
    throw error;
  });
  pitcherRecentOpponentHandSplitsCache.set(cacheKey, promise);
  return promise;
}

function pitcherStartGraphStat(split = {}) {
  const stat = split?.stat || {};
  return {
    date: formatLeadersDateLabel(split?.date || ''),
    ip: inningsToOuts(stat.inningsPitched) / 3,
    hits: statNumber(stat.hits),
    er: statNumber(stat.earnedRuns),
    hr: statNumber(stat.homeRuns ?? stat.hrAllowed ?? stat.hr),
  };
}

function pitcherLastFiveStartsGraphHtml(starts = null, label = 'Last 5 Starts') {
  const games = Array.isArray(starts) ? starts.slice(0, 5).reverse().map(pitcherStartGraphStat) : [];
  const metrics = [
    ['ip', 'IP', '#7bd0ff'],
    ['hits', 'H', '#ffd166'],
    ['er', 'ER', '#ff6b7d'],
    ['hr', 'HR', '#bda7ff'],
  ];
  const maxValue = Math.max(1, ...games.flatMap((game) => metrics.map(([key]) => Number(game[key]) || 0)));
  const top = 14;
  const right = 30;
  const bottom = 24;
  const left = 28;
  const width = 320;
  const height = 118;
  const plotW = width - left - right;
  const plotH = height - top - bottom;
  const xFor = (index) => left + (games.length <= 1 ? plotW / 2 : (plotW * index) / (games.length - 1));
  const yFor = (value) => top + plotH - ((Number(value) || 0) / maxValue) * plotH;
  const tickCount = 4;
  const yTicks = Array.from({ length: tickCount + 1 }, (_, index) => {
    const value = (maxValue * index) / tickCount;
    const y = yFor(value);
    const label = value.toFixed(maxValue < 10 ? 1 : 0);
    return { value, y, label };
  });
  const grid = yTicks.map((tick, index) => `
      <line class="grid" x1="${left}" y1="${tick.y.toFixed(1)}" x2="${width - right}" y2="${tick.y.toFixed(1)}" />
      <text class="tick" x="${index === 0 ? 8 : 4}" y="${(tick.y + (index === 0 ? 4 : 3)).toFixed(1)}">${escapeHtml(index === 0 ? '0' : tick.label)}</text>
  `).join('');
  const lines = metrics.map(([key, label, color]) => {
    const points = games.map((game, index) => `${xFor(index).toFixed(1)},${yFor(game[key]).toFixed(1)}`).join(' ');
    const dots = games.map((game, index) => `<circle cx="${xFor(index).toFixed(1)}" cy="${yFor(game[key]).toFixed(1)}" r="2.7" aria-label="${escapeHtml(`${game.date} ${label}: ${key === 'ip' ? game[key].toFixed(1) : game[key]}`)}"></circle>`).join('');
    return `<g style="--metric-color:${color}"><polyline points="${points}" />${dots}</g>`;
  }).join('');
  const labels = games.map((game, index) => {
    const anchor = index === 0 ? 'start' : index === games.length - 1 ? 'end' : 'middle';
    return `<text x="${xFor(index).toFixed(1)}" y="111" text-anchor="${anchor}">${escapeHtml(String(game.date || '').replace(/^0/, ''))}</text>`;
  }).join('');
  const legend = metrics.map(([, label, color]) => `<span style="--metric-color:${color}">${escapeHtml(label)}</span>`).join('');
  const safeLabel = cleanSummary(label) || 'Last 5 Starts';
  const body = games.length ? `
    <svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(`${safeLabel} graph`)}">
      <line class="axis" x1="${left}" y1="${top}" x2="${left}" y2="${height - bottom}" />
      <line class="axis" x1="${left}" y1="${height - bottom}" x2="${width - right}" y2="${height - bottom}" />
      ${grid}
      ${lines}
      ${labels}
    </svg>
  ` : `<div class="pitcher-starts-graph-empty">${escapeHtml(safeLabel)} unavailable</div>`;
  return `
    <div class="pitcher-starts-graph-card">
      <div class="pitcher-starts-graph-head">
        <span>${escapeHtml(safeLabel)}</span>
        <div>${legend}</div>
      </div>
      ${body}
    </div>
  `;
}

function visiblePlayerCardPitchTableShell(kind = 'pitcher', playerId = '', pitcherId = '', pitcherHand = '') {
  const safeKind = kind === 'batter' ? 'batter' : 'pitcher';
  const safePitcherHand = handednessCode(pitcherHand);
  return `<div class="visible-player-card-pitch-shell" data-visible-card-pitch="${escapeHtml(safeKind)}" data-player-id="${escapeHtml(playerId || '')}" data-pitcher-id="${escapeHtml(pitcherId || '')}" data-pitcher-hand="${escapeHtml(safePitcherHand || '')}">${visiblePlayerCardPitchStripHtml(null, safeKind)}</div>`;
}

function visibleBatterVelocityBucketTableShell(playerId = '', pitcherId = '', pitcherHand = '') {
  const safePitcherHand = handednessCode(pitcherHand);
  return `<div class="visible-batter-velo-bucket-shell" data-visible-batter-velo-buckets="true" data-player-id="${escapeHtml(playerId || '')}" data-pitcher-id="${escapeHtml(pitcherId || '')}" data-pitcher-hand="${escapeHtml(safePitcherHand || '')}">${batterVelocityBucketSplitTableHtml(null)}</div>`;
}

function batterVelocityBucketXbh(row = {}) {
  const direct = pitchCardCountNumber(row || {}, ['xbh', 'XBH', 'extraBaseHits', 'extra_base_hits']);
  if (Number.isFinite(direct)) return direct;
  const doubles = pitchCardCountNumber(row || {}, ['doubles', 'Doubles', '2B']);
  const triples = pitchCardCountNumber(row || {}, ['triples', 'Triples', '3B']);
  const hr = pitchCardCountNumber(row || {}, ['homeRuns', 'home_runs', 'home_run', 'hr', 'HR', 'hrs', 'Hrs']);
  return (Number(doubles) || 0) + (Number(triples) || 0) + (Number(hr) || 0);
}

function batterVelocityBucketSplitTableHtml(bucketRows = null, context = {}) {
  const rows = listify(bucketRows);
  const velocityProfile = pitcherFastballVelocityProfile(context?.opposingPitcher || null, context?.opposingPitcherRows || null);
  const avgVelocity = pitcherVelocityNumber(velocityProfile.avgVelocity);
  const activeBucket = Number.isFinite(avgVelocity) ? pitcherVelocityBucket(avgVelocity) : '';
  const title = Number.isFinite(avgVelocity)
    ? `Batter results against fastball-family pitch speed buckets. Opposing pitcher average fastball-family velocity ${avgVelocity.toFixed(1)} mph (${pitcherVelocityBucketLabel(activeBucket)}).`
    : 'Batter results against fastball-family pitch speed buckets.';
  const activeKeys = activeBucket ? [activeBucket] : [];
  const rowHtml = activeKeys.length ? activeKeys.map((key) => {
    const row = batterVelocityBucketStatRow(rows, key) || {};
    const label = pitcherVelocityBucketLabel(key);
    const ab = pitchCardCountNumber(row, ['ab', 'AB', 'abs', 'at_bats', 'At Bats']);
    const hits = pitchCardCountNumber(row, ['hits', 'Hits', 'h', 'H']);
    const avg = pitchCardRateNumber(row, ['avg', 'AVG', 'ba', 'BA', 'batting_avg'], 1.5);
    const slg = pitchCardRateNumber(row, ['slg', 'SLG', 'slugging', 'xslg', 'xSLG'], 5);
    const xbh = batterVelocityBucketXbh(row);
    const hr = pitchCardCountNumber(row, ['homeRuns', 'home_runs', 'home_run', 'hr', 'HR', 'hrs', 'Hrs']);
    const hasSample = Number.isFinite(ab) && ab > 0;
    const sample = Number.isFinite(hits) && hasSample
      ? `${Math.round(hits)}-${Math.round(ab)}`
      : '--';
    return `<tr class="${key === activeBucket ? 'is-batter' : 'is-neutral'}${key === activeBucket ? ' is-active-velo-bucket' : ''}" title="${escapeHtml(`${label} mph fastball-family bucket`)}"><th>${escapeHtml(label)}</th><td>${escapeHtml(sample)}</td><td>${escapeHtml(hasSample ? playerStatHeatMapSavantRate(avg, 3, true) : '--')}</td><td>${escapeHtml(hasSample ? playerStatHeatMapSavantRate(slg, 3, true) : '--')}</td><td>${hasSample && Number.isFinite(xbh) ? Math.round(xbh) : '--'}</td><td>${hasSample && Number.isFinite(hr) ? Math.round(hr) : '--'}</td></tr>`;
  }).join('') : '<tr class="is-neutral"><th>Velo</th><td colspan="5">Loading</td></tr>';
  return `
    <table class="player-stat-table handed-splits-table batter-velo-bucket-table" title="${escapeHtml(title)}">
      <thead>
        <tr>
          <th>Split</th>
          <th>H-AB</th>
          <th>AVG</th>
          <th>SLG</th>
          <th>XBH</th>
          <th>HR</th>
        </tr>
      </thead>
      <tbody>${rowHtml}</tbody>
    </table>
  `;
}

function fitVisiblePitchCardValues(root = document) {
  const container = root && root.querySelectorAll ? root : document;
  const cells = Array.from(container.querySelectorAll('.visible-pitch-card span:not(.pitch)'));
  if (!cells.length) return;
  const classes = ['is-tight', 'is-extra-tight', 'is-micro-tight'];
  cells.forEach((cell) => {
    cell.classList.remove(...classes);
    cell.style.removeProperty('--fit-scale');
    const applyUntilFits = () => {
      if (cell.scrollWidth <= cell.clientWidth + 1) return;
      cell.classList.add('is-tight');
      if (cell.scrollWidth <= cell.clientWidth + 1) return;
      cell.classList.add('is-extra-tight');
      if (cell.scrollWidth <= cell.clientWidth + 1) return;
      cell.classList.add('is-micro-tight');
    };
    applyUntilFits();
  });
}

function normalizedPitchUsagePercent(row = {}, keys = ['pitcherUsagePct', 'pct', 'usagePct', 'usage', 'pitch_percent']) {
  for (const key of keys) {
    const raw = row?.[key];
    const text = String(raw ?? '').trim();
    if (raw === undefined || raw === null || text === '') continue;
    const value = typeof raw === 'number' ? raw : Number(text.replace(/%/g, ''));
    if (!Number.isFinite(value)) continue;
    return !/%/.test(text) && Math.abs(value) <= 1 ? value * 100 : value;
  }
  return null;
}

function pitchClearsVisibleUsageThreshold(row = {}, keys) {
  const usage = normalizedPitchUsagePercent(row, keys);
  return Number.isFinite(usage) && usage > 4;
}

function visiblePitchUsagePercent(row = {}, keys = ['pct', 'usagePct', 'usage', 'pitch_percent']) {
  const usage = normalizedPitchUsagePercent(row, keys);
  return Number.isFinite(usage) ? usage : null;
}

function visiblePitchRowsForPlayerType(rows = [], playerType = 'batter') {
  if (!Array.isArray(rows)) return [];
  const validRows = rows.filter((row) => visiblePitchCategoryName(row?.category));
  if (playerType !== 'pitcher') return validRows;
  return validRows.filter((row) => visiblePitchUsagePercent(row, ['pct', 'usage', 'usagePct', 'pitch_percent']) > 4);
}

function visiblePlayerCardPitchStripHtml(rows = null, kind = 'pitcher', orderedCategories = []) {
  if (!Array.isArray(rows)) return '<div class="visible-pitch-strip is-loading">Loading pitches</div>';
  const pitcherMode = kind === 'pitcher';
  let displayRows = pitcherMode
    ? [...rows]
      .filter((row) => visiblePitchCategoryName(row.category))
      .map((row) => ({ ...row, visibleUsagePct: visiblePitchUsagePercent(row, ['pct', 'usage', 'usagePct', 'pitch_percent']) }))
      .filter((row) => Number(row.visibleUsagePct) > 4)
      .sort((a, b) => (Number(b.visibleUsagePct) || 0) - (Number(a.visibleUsagePct) || 0))
    : playerStatHeatMapAlignPitchRows(rows, orderedCategories)
        .filter((row) => visiblePitchCategoryName(row.category))
        .filter((row) => batterPitchCardCanRender(row))
        .map((row) => ({ ...row, visibleUsagePct: batterPitchCardUsagePercent(row) }))
        .filter((row) => Number(row.visibleUsagePct) > 4);
  displayRows = displayRows.slice(0, 7);
  if (!displayRows.length) return ''; // keep player card compact when no usable pitch data is available
  if (pitcherMode) while (displayRows.length < 3) displayRows.push({ category: '--', pct: '', avg: '', ops: '', hardHit: '', homeRuns: '', pitcherUsagePct: '' });
  const cards = displayRows.map((item) => {
    const hitterAvg = pitchCardRateNumber(item, ['avg', 'AVG', 'ba', 'BA', 'batting_avg'], 1.5);
    const hitterSlg = pitchCardRateNumber(item, ['slg', 'SLG', 'slugging', 'xslg', 'xSLG'], 5);
    const pitcherAvgAllowed = pitchCardRateNumber(item, PITCHER_ALLOWED_AVG_STRICT_KEYS, 1.5);
    const pitcherSlgAllowed = pitchCardRateNumber(item, PITCHER_ALLOWED_SLG_STRICT_KEYS, 5);
    const pitcherCardSlgAllowed = pitcherMode ? pitchCardRateNumber(item, ['slg', 'SLG', 'slugging', 'xslg', 'xSLG'], 5) : pitcherSlgAllowed;
    const heat = pitcherMode
      ? (Number.isFinite(pitcherCardSlgAllowed) ? clamp(pitcherCardSlgAllowed / 0.700, 0, 1) : 0.5)
      : (Number.isFinite(hitterSlg) ? clamp(hitterSlg / 0.600, 0, 1) : 0.5);
    const heatRgb = pitcherMode
      ? [
          Math.round(255 + ((62 - 255) * heat)),
          Math.round(69 + ((154 - 69) * heat)),
          Math.round(48 + ((244 - 48) * heat)),
        ]
      : [
          Math.round(62 + ((255 - 62) * heat)),
          Math.round(154 + ((69 - 154) * heat)),
          Math.round(244 + ((48 - 244) * heat)),
        ];
    const fieryPitcherSlug = shouldUseFieryPitchOutline(item, pitcherMode ? 'pitcher' : 'batter');
    const heatStyle = `--pitch-bg:linear-gradient(180deg, rgba(${heatRgb[0]}, ${heatRgb[1]}, ${heatRgb[2]}, .42), rgba(10, 27, 42, .78));${fieryPitcherSlug ? '--pitch-fire-border:rgba(255, 209, 102, .95);--pitch-fire-glow:rgba(255, 92, 40, .58);' : ''}`;
    const hitterAb = pitchCardCountNumber(item, ['ab', 'AB', 'abs', 'at_bats', 'At Bats']);
    const pitcherAb = pitchCardCountNumber(item, PITCHER_ALLOWED_AB_STRICT_KEYS);
    const hitterHardHit = pitchCardPercentNumber(item, ['hardHit', 'HardHit%', 'hard_hit_percent', 'hard_hit_pct', 'hardhit_percent']);
    const pitcherHardHit = pitcherAllowedHardHitNumber(item);
    const hitterWhiff = pitchCardPercentNumber(item, ['whiff', 'Whiff%', 'whiff_percent', 'swing_miss_percent', 'swinging_strike_percent']);
    const pitcherWhiff = pitcherAllowedWhiffNumber(item);
    const splitPair = (left, right, decimals = 3, signed = true) => `${playerStatHeatMapSavantRate(left, decimals, signed)}|${playerStatHeatMapSavantRate(right, decimals, signed)}`;
    const percentPair = (left, right) => `${playerStatHeatMapPercentValue(left)}|${playerStatHeatMapPercentValue(right)}`;
    const abPair = `${Number.isFinite(hitterAb) ? Math.round(hitterAb) : '--'}|${Number.isFinite(pitcherAb) ? Math.round(pitcherAb) : '--'} AB`;
    const hitterHr = pitchCardCountNumber(item, ['homeRuns', 'home_runs', 'home_run', 'hr', 'HR', 'hrs', 'Hrs']);
    const pitcherHr = pitchCardCountNumber(item, ['pitcherHomeRuns', 'pitcherHrAllowed', 'hrAllowedByPitcher', 'hrAllowed', 'pitcherHR']);
    const hrPair = `${Number.isFinite(hitterHr) ? Math.round(hitterHr) : '--'}|${Number.isFinite(pitcherHr) ? Math.round(pitcherHr) : '--'} HR`;
    const values = pitcherMode
      ? [
        playerStatHeatMapPitchDisplayLabel(item, 'pitcher'),
        playerStatHeatMapUsageWithPreviousStartHtml({ ...item, pct: item.visibleUsagePct ?? item.pct }),
        playerStatHeatMapSavantRate(pitchCardRateNumber(item, ['avg', 'AVG', 'ba', 'BA', 'batting_avg'], 1.5), 3, true),
        playerStatHeatMapPercentValue(pitchCardPercentNumber(item, ['hardHit', 'HardHit%', 'hard_hit_percent', 'hard_hit_pct', 'hardhit_percent'])),
        String(savantRowHomeRuns(item)),
      ]
      : [
        playerStatHeatMapPitchDisplayLabel(item, 'batter'),
        splitPair(hitterAvg, pitcherAvgAllowed, 3, true),
        splitPair(hitterSlg, pitcherSlgAllowed, 3, true),
        hrPair,
        playerStatHeatMapSavantRate(item.ev, 1, false),
        percentPair(hitterHardHit, pitcherHardHit),
        percentPair(hitterWhiff, pitcherWhiff),
        abPair,
      ];
    const title = pitcherMode ? 'Pitch / Usage / BAA / HardHit% / HR allowed' : 'Pitch / AVG batter|pitcher allowed / SLG batter|pitcher allowed / batter HR|pitcher HRA / EV / HH% batter|pitcher allowed / Whiff% batter|pitcher / batter AB|pitcher AB';
    const cardCells = values.map((value, index) => {
      const rawValue = String(value ?? '');
      const cellClasses = index === 0 ? 'pitch' : '';
      return `<span class="${cellClasses}" title="${escapeHtml(rawValue.replace(/<[^>]*>/g, ''))}">${pitcherMode && index === 1 ? value : escapeHtml(value)}</span>`;
    }).join('');
    return `<div class="visible-pitch-card${pitcherMode ? ' pitcher' : ' batter'}${fieryPitcherSlug ? ' is-fiery-pitch' : ''}" style="--pitch-heat:${heat};${heatStyle}" title="${escapeHtml(title)}">${cardCells}</div>`;
  }).join('');
  const count = Math.max(1, displayRows.length);
  return `<div class="visible-pitch-strip${pitcherMode ? ' pitcher' : ' batter'}" data-pitch-count="${count}" style="--pitch-count:${count}">${cards}</div>`;
}

function pitcherOpponentHandHtml(splits = null, starts = null, graphLabel = 'Last 5 Starts', pitcherId = '', recentHand = null, profile = null) {
  const source = splits?.source || '';
  return `
    <div class="pitcher-card-extra-stack"${source ? ` title="${escapeHtml(source)}"` : ''}>
      <div class="pitcher-card-hand-table-wrap">
        <table class="player-stat-table handed-splits-table pitcher-opponent-hand-table">
          <thead>
            <tr>
              <th>Split</th>
              <th>Opp AVG</th>
              <th>Opp SLG</th>
              <th>HR</th>
              <th>HR/9</th>
              <th>K</th>
            </tr>
          </thead>
          <tbody>
            ${pitcherOpponentHandRow('vs LHB', splits?.vsLeft, recentHand?.vsLeft)}
            ${pitcherOpponentHandRow('vs RHB', splits?.vsRight, recentHand?.vsRight)}
          </tbody>
        </table>
      </div>
      <div class="pitcher-starts-below-table">
        ${pitcherLastFiveStartsGraphHtml(starts, graphLabel)}
        ${visiblePlayerCardPitchTableShell('pitcher', pitcherId)}
      </div>
    </div>
  `;
}

function batterStarterHandednessHtml(pitcher = null, splits = null, batterHand = '', recentHand = null, batterId = '') {
  const pitcherHand = pitcherThrowHandValue(pitcher);
  const effectiveHand = effectiveBatterHandForPitcher(batterHand, pitcherHand);
  const pitcherName = cleanSummary(pitcher?.fullName || pitcher?.name || pitcher?.person?.fullName || '');
  const title = `${pitcherName || 'Starter'}${pitcherHand ? ` (${handednessCode(pitcherHand) || pitcherHand})` : ''}${effectiveHand ? ` vs ${effectiveHand}HB` : ''}`;
  const rows = effectiveHand === 'L'
    ? pitcherOpponentHandRow('vs LHB', splits?.vsLeft, recentHand?.vsLeft)
    : effectiveHand === 'R'
      ? pitcherOpponentHandRow('vs RHB', splits?.vsRight, recentHand?.vsRight)
      : `${pitcherOpponentHandRow('vs LHB', splits?.vsLeft, recentHand?.vsLeft)}${pitcherOpponentHandRow('vs RHB', splits?.vsRight, recentHand?.vsRight)}`;
  return `
    <table class="player-stat-table handed-splits-table pitcher-opponent-hand-table" title="${escapeHtml(title)}">
      <thead>
        <tr>
          <th>Split</th>
          <th>Opp AVG</th>
          <th>Opp SLG</th>
          <th>HR</th>
          <th>HR/9</th>
          <th>K</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
    ${visibleBatterVelocityBucketTableShell(batterId, pitcher?.id || pitcher?.person?.id || '', pitcherHand)}
  `;
}

function hydrateVisibleBatterVelocityBucketTables(profile, game, token) {
  const shells = [...(playerStatExtraEl?.querySelectorAll?.('[data-visible-batter-velo-buckets]') || [])];
  if (!shells.length) return;
  const isCurrent = (shell) => Boolean(playerStatExtraEl && playerStatExtraEl.dataset.splitToken === token && shell?.isConnected && playerStatOverlayEl && !playerStatOverlayEl.hidden);
  for (const shell of shells) {
    const playerId = Number(shell.dataset.playerId || profile?.id);
    const matchupPitcher = currentMatchupPitcher(profile, game) || resolvePitcherProfileById(game, shell.dataset.pitcherId);
    const pitcherId = Number(shell.dataset.pitcherId || matchupPitcher?.id || matchupPitcher?.person?.id);
    if (!Number.isFinite(playerId) || playerId <= 0) continue;
    (async () => {
      const season = seasonForDate(typeof playerStatTargetDate === 'function' ? playerStatTargetDate(game) : (dateInput?.value || formatDate(new Date())));
      const syncedPitcher = Number.isFinite(pitcherId) && pitcherId > 0
        ? await syncedFirstAppearancePitcherProfileForGame(matchupPitcher, game).catch(() => matchupPitcher)
        : matchupPitcher;
      const fastballMaxPromise = Number.isFinite(pitcherId) && pitcherId > 0
        ? getSavantPitcherFastballMaxVelocityWithFallback(pitcherId, season).catch(() => null)
        : Promise.resolve(null);
      const bucketRowsPromise = getBatterVelocityBucketStatsWithFallback(playerId, season, {}).catch(() => []);
      const [fastballMax, bucketRows] = await Promise.all([fastballMaxPromise, bucketRowsPromise]);
      if (!isCurrent(shell)) return;
      shell.innerHTML = batterVelocityBucketSplitTableHtml(bucketRows, {
        opposingPitcher: pitcherProfileWithFastballMaxVelocity(syncedPitcher || matchupPitcher, fastballMax),
      });
    })();
  }
}

function hydrateVisiblePlayerCardPitchTables(profile, game, token) {
  const shells = [...(playerStatExtraEl?.querySelectorAll?.('[data-visible-card-pitch]') || [])];
  if (!shells.length) return;
  const isPitchShellCurrent = (shell) => Boolean(playerStatExtraEl && playerStatExtraEl.dataset.splitToken === token && shell?.isConnected && playerStatOverlayEl && !playerStatOverlayEl.hidden);
  const paintShell = (shell, html) => {
    if (!isPitchShellCurrent(shell)) return;
    const cleanHtml = String(html || '').trim();
    shell.innerHTML = cleanHtml;
    const panel = shell.closest?.('.player-heatmap-table-panel');
    if (panel) panel.hidden = !cleanHtml;
    else shell.hidden = !cleanHtml;
    if (cleanHtml) requestAnimationFrame(() => fitVisiblePitchCardValues(shell));
  };
  for (const shell of shells) {
    const kind = shell.dataset.visibleCardPitch === 'pitcher' ? 'pitcher' : 'batter';
    const playerId = Number(shell.dataset.playerId || profile?.id);
    const matchupPitcher = currentMatchupPitcher(profile, game) || resolvePitcherProfileById(game, shell.dataset.pitcherId);
    const pitcherId = Number(shell.dataset.pitcherId || matchupPitcher?.id || matchupPitcher?.person?.id);
    (async () => {
      try {
        if (!isPitchShellCurrent(shell)) return '';
        if (kind === 'pitcher') {
          const pitchOptions = firstAppearancePitchBreakdownOptions(profile);
          const usingFallbackPitchSeason = Number.isFinite(Number(pitchOptions.fallbackSeason)) && Number(pitchOptions.fallbackSeason) > 1900;
          let seedPreviousStartMix = null;
          let readPitchOptions = pitchOptions;
          if (usingFallbackPitchSeason) {
            seedPreviousStartMix = await withTimeoutValue(
              getMlbPitcherPreviousStartPitchMix(playerId, Number(pitchOptions.fallbackSeason)).then((mix) => mix || getSavantPreviousStartPitchMix(playerId, Number(pitchOptions.fallbackSeason))),
              3200,
              null
            );
            const throughDate = seedPreviousStartMix?.date ? addDaysToDateValue(seedPreviousStartMix.date, 1) : '';
            if (throughDate) readPitchOptions = { ...pitchOptions, pitchDataThroughDate: throughDate };
          }
          if (!isPitchShellCurrent(shell)) return '';
          const rawRows = await getVisiblePitchBreakdown(playerId, 'pitcher', usingFallbackPitchSeason ? 6800 : 4200, {}, readPitchOptions);
          const mixSeason = Number(rawRows?.[0]?.sourceSeason || pitchOptions.fallbackSeason || seasonForDate(dateInput.value || formatDate(new Date())));
          const previousStartMix = seedPreviousStartMix || await withTimeoutValue(
            getMlbPitcherPreviousStartPitchMix(playerId, mixSeason).then((mix) => mix || getSavantPreviousStartPitchMix(playerId, mixSeason)),
            usingFallbackPitchSeason ? 5200 : 4200,
            null
          );
          const rows = mergePreviousStartPitchMix(rawRows, previousStartMix);
          return visiblePlayerCardPitchStripHtml(rows, 'pitcher');
        }

        const syncedMatchupPitcher = await syncedFirstAppearancePitcherProfileForGame(matchupPitcher, game).catch(() => matchupPitcher);
        const matchupPitcherThrowHand = pitcherThrowHandFromGame(game, pitcherId, shell.dataset.pitcherHand || pitcherThrowHandValue(syncedMatchupPitcher || matchupPitcher));
        const batterStand = effectiveBatterHandForPitcher(profile?.bats, matchupPitcherThrowHand) || handednessCode(profile?.bats);
        if (!isPitchShellCurrent(shell)) return '';
        const pitcherPayloadPromise = Number.isFinite(pitcherId) && pitcherId > 0
          ? pitcherRowsForBatterForecast(syncedMatchupPitcher || matchupPitcher, game, batterStand ? { stand: batterStand } : {}, 5200).catch(() => ({ rows: [] }))
          : Promise.resolve({ rows: [] });
        const pitcherAllPayloadPromise = Number.isFinite(pitcherId) && pitcherId > 0
          ? pitcherRowsForBatterForecast(syncedMatchupPitcher || matchupPitcher, game, {}, 5200).catch(() => ({ rows: [] }))
          : Promise.resolve({ rows: [] });
        const batterRowsPromise = matchupPitcherThrowHand
          ? getVisiblePitchBreakdown(playerId, 'batter', 5200, { pThrows: matchupPitcherThrowHand }, { allowDeepBatterEvents: true, visibleCardDemand: true }).catch(() => [])
          : getVisiblePitchBreakdown(playerId, 'batter', 4200, {}, { allowDeepBatterEvents: true, visibleCardDemand: true }).catch(() => []);
        const [pitcherPayload, pitcherAllPayload, initialBatterRows] = await Promise.all([pitcherPayloadPromise, pitcherAllPayloadPromise, batterRowsPromise]);
        const pitcherRows = mergePitcherArsenalRowsForBatterCard(pitcherPayload?.rows || [], pitcherAllPayload?.rows || []);
        const pitcherOrder = pitcherRows
          .filter((item) => visiblePitchCategoryName(item.category))
          .map((item) => ({
            ...item,
            visibleUsagePct: visiblePitchUsagePercent(item, ['pct', 'usage', 'usagePct', 'pitch_percent'])
          }))
          .filter((item) => Number(item.visibleUsagePct) > 4)
          .sort((a, b) => (Number(b.visibleUsagePct) || 0) - (Number(a.visibleUsagePct) || 0))
          .map((item) => ({
            category: item.category,
            pct: item.visibleUsagePct ?? item.pct,
            avg: pitchCardRateNumber(item, ['pitcherAvg', 'pitcherBAA', 'pitcherAvgAllowed', 'avgAllowedByPitcher', 'baa', 'batting_average_against', 'avg', 'AVG', 'BAA'], 1.5),
            slg: pitchCardRateNumber(item, ['pitcherSlg', 'pitcherSLG', 'pitcherSlgAllowed', 'slgAllowedByPitcher', 'pitcherSlugging', 'pitcherSluggingAllowed', 'allowedSlugging', 'allowed_slg', 'slugging_allowed', 'pSlg', 'pSLG', 'slg', 'SLG', 'slugging'], 5),
            hardHit: pitcherAllowedHardHitNumber({ ...item, pitcherMetricSource: true, pitcherSource: true }),
            whiff: pitcherAllowedWhiffNumber({ ...item, pitcherMetricSource: true, pitcherSource: true }),
            pitcherHardHit: pitcherAllowedHardHitNumber({ ...item, pitcherMetricSource: true, pitcherSource: true }),
            pitcherWhiff: pitcherAllowedWhiffNumber({ ...item, pitcherMetricSource: true, pitcherSource: true }),
            pitcherMetricSource: true,
            pitcherSource: true,
            pitcherAb: pitchCardCountNumber(item, [...PITCHER_ALLOWED_AB_KEYS, 'pa', 'PA', 'plateAppearances', 'pitches']),
            pitcherHomeRuns: pitchCardCountNumber(item, ['pitcherHomeRuns', 'pitcherHrAllowed', 'hrAllowedByPitcher', 'hrAllowed', 'homeRuns', 'home_runs', 'HR']),
            pitcherThrowHand: matchupPitcherThrowHand,
          }));

        if (!isPitchShellCurrent(shell)) return '';
        let rows = initialBatterRows || [];

        const hasUsableHandedRows = Array.isArray(rows) && rows.some((row) => (
          Number(row?.pa || row?.ab || row?.hits || row?.homeRuns || row?.pitches) > 0
          || Number.isFinite(Number(row?.avg))
          || Number.isFinite(Number(row?.slg))
          || Number.isFinite(Number(row?.ev))
        ));
        if (matchupPitcherThrowHand && !hasUsableHandedRows) {
          rows = await getSavantHandedPitchBreakdownFromEvents(playerId, 'batter', undefined, { pThrows: matchupPitcherThrowHand, visibleCardDemand: true }).catch(() => []);
        }
        rows = (rows || []).map((row) => ({ ...row, pitcherThrowHand: matchupPitcherThrowHand || row.pitcherThrowHand || '' }));
        return visiblePlayerCardPitchStripHtml(rows, 'batter', pitcherOrder);
      } catch {
        return '';
      }
    })().then((html) => paintShell(shell, html));
  }
}

async function getPitcherLastFiveStarts(playerId, game = null, profile = null) {
  const fallbackSeason = Number(profile?.seasonStatSource?.pitching?.season || 0);
  const splits = await playerStatGameLogSplits(playerId, 'pitching', game, fallbackSeason);
  const eligible = filteredRecentHistorySplits(splits, game);
  const appearances = eligible.filter(playerStatPitchingAppearanceSplit).slice(0, 5);
  if (!pitcherShouldUseStartHistory(profile)) return appearances;
  const starts = eligible.filter(isPitchingStartSplit).slice(0, 5);
  return starts.length ? starts : appearances;
}

function renderPitcherOpponentHandSplits(profile, token, game = null) {
  if (!playerStatExtraEl || !profile?.id) return;
  const graphLabel = pitcherShouldUseStartHistory(profile) ? 'Last 5 Starts' : 'Last 5 Apps';
  playerStatExtraEl.innerHTML = `${pitcherOpponentHandHtml(null, null, graphLabel, profile.id, null, profile)}<div class="player-stat-loading">Loading opponent handed splits</div>`;
  hydrateVisiblePlayerCardPitchTables(profile, game, token);
  const handSplitSeason = pitcherOpponentHandSeasonForProfile(profile);
  Promise.allSettled([
    getPitcherOpponentHandSplits(profile, handSplitSeason),
    getPitcherLastFiveStarts(profile.id, game, profile),
  ])
    .then(async ([splitResult, startsResult]) => {
      if (!playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return;
      const splits = splitResult.status === 'fulfilled' ? splitResult.value : null;
      const starts = startsResult.status === 'fulfilled' ? startsResult.value : [];
      const recentHand = await getPitcherRecentOpponentHandSplits(profile.id, starts.slice(0, 3)).catch(() => null);
      if (!playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return;
      playerStatExtraEl.innerHTML = splits
        ? pitcherOpponentHandHtml(splits, starts, graphLabel, profile.id, recentHand, profile)
        : `${pitcherOpponentHandHtml(null, starts, graphLabel, profile.id, recentHand, profile)}<div class="player-stat-loading">Unavailable</div>`;
      hydrateVisiblePlayerCardPitchTables(profile, game, token);
    });
}

function hydratePitcherOpponentHandMarkers(rootEl) {
  const markers = Array.from(rootEl?.querySelectorAll?.('.pitcher-hand-markers[data-pitcher-hand-id]') || []);
  if (!markers.length) return;
  const selectedDate = selectedPitcherMarkerDate();
  const pendingMarkers = markers.filter((marker) => marker.dataset.handHydratedDate !== selectedDate || marker.dataset.handHydratedId !== marker.dataset.pitcherHandId);
  if (!pendingMarkers.length) return;
  const ids = [...new Set(pendingMarkers.map((marker) => Number(marker.dataset.pitcherHandId)).filter((id) => Number.isFinite(id) && id > 0))];
  if (!ids.length) return;
  for (const marker of pendingMarkers) {
    const cached = pitcherCachedMarkerValue('hand', marker.dataset.pitcherHandId, selectedDate);
    if (cached !== undefined) {
      marker.innerHTML = cached || '';
      marker.dataset.handHydratedDate = selectedDate;
      marker.dataset.handHydratedId = String(marker.dataset.pitcherHandId || '');
    }
  }
  Promise.all(ids.map(async (id) => {
    const profile = latestRenderedGames
      .map((game) => game?.playerLookup?.[String(id)])
      .find(Boolean) || { id };
    const splits = await getPitcherOpponentHandSplits(profile, pitcherOpponentHandSeasonForProfile(profile)).catch(() => null);
    return [id, splits];
  })).then((results) => {
    const splitMap = new Map(results);
    for (const [id, splits] of splitMap.entries()) {
      const html = splits
        ? `${pitcherOpponentHandAvgMarker(splits.vsLeft, 'L')}${pitcherOpponentHandAvgMarker(splits.vsRight, 'R')}`
        : '';
      pitcherSetCachedMarkerValue('hand', id, html, selectedDate);
    }
    if (selectedPitcherMarkerDate() !== selectedDate) return;
    const currentMarkers = Array.from(rootEl?.querySelectorAll?.('.pitcher-hand-markers[data-pitcher-hand-id]') || []);
    for (const marker of currentMarkers) {
      const id = Number(marker.dataset.pitcherHandId);
      if (!splitMap.has(id)) continue;
      const html = pitcherCachedMarkerValue('hand', id, selectedDate) || '';
      marker.innerHTML = html;
      marker.dataset.handHydratedDate = selectedDate;
      marker.dataset.handHydratedId = String(marker.dataset.pitcherHandId || '');
    }
  }).catch(() => {});
}



function batterBattedBallPct(value) {
  if (value === null || value === undefined || value === '' || value === '--' || value === '---') return '--';
  const numeric = Number(String(value).replace('%', '').replace(/,/g, '').replace(/^\./, '0.'));
  return Number.isFinite(numeric) ? `${formatRateValue(numeric, 1, false)}%` : '--';
}

function batterBattedBallRate(value, digits = 1) {
  if (value === null || value === undefined || value === '' || value === '--' || value === '---') return '--';
  const numeric = Number(String(value).replace(/,/g, '').replace(/^\./, '0.'));
  return Number.isFinite(numeric) && numeric > 0 ? formatRateValue(numeric, digits, false) : '--';
}

function savantBattedBallType(row = {}) {
  return cleanSummary(csvValue(row, ['bb_type', 'BB Type', 'batted_ball_type', 'bbtype'])).toLowerCase();
}

function savantHitDistance(row = {}) {
  return savantRowNumber(row, ['hit_distance_sc', 'Hit Distance', 'distance', 'estimated_distance']);
}

function savantLaunchAngle(row = {}) {
  return savantRowNumber(row, ['launch_angle', 'Launch Angle', 'la']);
}

function isSavantPlateAppearanceRow(row = {}) {
  const event = cleanSummary(csvValue(row, ['events', 'Events', 'event'])).toLowerCase();
  return Boolean(event) && event !== 'null' && event !== 'undefined';
}

function isSavantBattedBallRow(row = {}) {
  const launchSpeed = savantRowNumber(row, ['launch_speed', 'Launch Speed', 'exit_velocity', 'EV']);
  const bbType = savantBattedBallType(row);
  const event = cleanSummary(csvValue(row, ['events', 'Events', 'event'])).toLowerCase();
  return Number.isFinite(launchSpeed) || Boolean(bbType) || ['single', 'double', 'triple', 'home_run', 'field_out', 'force_out', 'grounded_into_double_play', 'fielders_choice', 'field_error', 'sac_fly', 'sac_fly_double_play'].includes(event);
}

function isSavantGroundBall(row = {}) {
  const bbType = savantBattedBallType(row);
  if (bbType.includes('ground')) return true;
  if (bbType.includes('line') || bbType.includes('fly') || bbType.includes('popup') || bbType.includes('pop_up')) return false;
  const angle = savantLaunchAngle(row);
  return Number.isFinite(angle) ? angle < 10 : false;
}

function isSavantAirBall(row = {}) {
  const bbType = savantBattedBallType(row);
  if (bbType.includes('line') || bbType.includes('fly') || bbType.includes('popup') || bbType.includes('pop_up')) return true;
  if (bbType.includes('ground')) return false;
  const angle = savantLaunchAngle(row);
  return Number.isFinite(angle) ? angle >= 10 : false;
}

function finiteBattedBallNumber(value) {
  if (value === null || value === undefined || value === '' || value === '--' || value === '---') return null;
  const numeric = Number(String(value).replace('%', '').replace(/,/g, '').replace(/^\./, '0.'));
  return Number.isFinite(numeric) ? numeric : null;
}

function validAirGroundPair(airPct, groundPct) {
  if (!Number.isFinite(airPct) || !Number.isFinite(groundPct)) return false;
  if (airPct < 0 || groundPct < 0 || airPct > 100 || groundPct > 100) return false;
  const total = airPct + groundPct;
  if (total < 85 || total > 115) return false;
  if (airPct >= 99 && groundPct <= 1) return false;
  if (groundPct >= 99 && airPct <= 1) return false;
  return true;
}

function chooseBattedBallSplitValue(eventValue, leaderboardValue, pairedValue, eventSample) {
  const eventNumeric = Number(eventValue);
  if (Number.isFinite(eventNumeric) && Number(eventSample) >= 20) return eventNumeric;
  if (validAirGroundPair(Number(leaderboardValue), Number(pairedValue))) return Number(leaderboardValue);
  if (Number.isFinite(eventNumeric) && Number(eventSample) > 0) return eventNumeric;
  return null;
}


function mlbStatNumber(value) {
  if (value === null || value === undefined || value === '' || value === '--' || value === '---') return 0;
  const numeric = Number(String(value).replace(/,/g, '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(numeric) ? numeric : 0;
}

function mlbFiniteStatNumber(value) {
  if (value === null || value === undefined || value === '' || value === '--' || value === '---') return null;
  const numeric = Number(String(value).replace(/,/g, '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(numeric) ? numeric : null;
}

function mlbBatterGameLogPa(split = {}) {
  const stat = split?.stat || {};
  const explicit = mlbFiniteStatNumber(stat.plateAppearances ?? stat.plateAppearance ?? stat.pa);
  if (Number.isFinite(explicit)) return explicit;
  return mlbStatNumber(stat.atBats) + mlbStatNumber(stat.baseOnBalls ?? stat.walks) + mlbStatNumber(stat.hitByPitch)
    + mlbStatNumber(stat.sacFlies ?? stat.sacFly) + mlbStatNumber(stat.sacBunts ?? stat.sacBunt);
}

function mlbPlayBatterId(play = {}) {
  return Number(play?.matchup?.batter?.id ?? play?.batter?.id ?? play?.about?.batter?.id ?? 0);
}

function mlbPlayResultEventType(play = {}) {
  return cleanSummary(play?.result?.eventType || play?.result?.event || play?.about?.eventType || '').toLowerCase();
}

function mlbPlayHitData(play = {}) {
  const events = listify(play?.playEvents);
  for (let i = events.length - 1; i >= 0; i -= 1) {
    if (events[i]?.hitData) return events[i].hitData;
  }
  return play?.hitData || null;
}

function mlbHitDataNumber(hitData = {}, keys = []) {
  for (const key of keys) {
    const value = hitData?.[key];
    if (value === null || value === undefined || value === '') continue;
    const numeric = Number(String(value).replace(/,/g, '').replace(/[^0-9.\-]/g, ''));
    if (Number.isFinite(numeric)) return numeric;
  }
  return null;
}

function mlbPlayIsPlateAppearance(play = {}) {
  const event = mlbPlayResultEventType(play);
  return Boolean(event) && event !== 'undefined' && event !== 'null';
}

function mlbPlayBattedBallClass(play = {}) {
  const hitData = mlbPlayHitData(play);
  const angle = mlbHitDataNumber(hitData, ['launchAngle', 'launch_angle']);
  const distance = mlbHitDataNumber(hitData, ['totalDistance', 'hitDistance', 'hit_distance_sc']);
  const trajectory = cleanSummary(hitData?.trajectory || hitData?.trajectoryCode || '').toLowerCase();
  const event = mlbPlayResultEventType(play);
  const battedEvent = /single|double|triple|home_run|field_out|force_out|grounded_into_double_play|fielders_choice|field_error|sac_fly|sac_bunt/.test(event);
  const hasBattedBall = Number.isFinite(angle) || Number.isFinite(distance) || Boolean(trajectory) || battedEvent;
  if (!hasBattedBall) return null;
  let isAir = null;
  let isGround = null;
  if (trajectory.includes('ground')) {
    isAir = false;
    isGround = true;
  } else if (trajectory.includes('line') || trajectory.includes('fly') || trajectory.includes('popup') || trajectory.includes('pop')) {
    isAir = true;
    isGround = false;
  } else if (Number.isFinite(angle)) {
    isAir = angle >= 10;
    isGround = angle < 10;
  }
  return { hasBattedBall, isAir, isGround, angle, distance };
}

function mlbPlayPitcherThrowHand(play = {}) {
  return handednessCode(play?.matchup?.pitchHand?.code || play?.matchup?.pitchHand?.description || play?.pitchHand?.code || play?.pitchHand?.description || '');
}

function mlbPlayBatterStand(play = {}) {
  return handednessCode(play?.matchup?.batSide?.code || play?.matchup?.batSide?.description || play?.batSide?.code || play?.batSide?.description || '');
}

function battedBallSprayBucketFromXy(xValue, yValue, batterStand = '') {
  const x = Number(xValue);
  const y = Number(yValue);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return '';
  // MLB/Statcast batted-ball coordinates are screen-space; this centerline estimate is the common Savant transform baseline.
  const angle = Math.atan2(x - 125.42, 198.27 - y) * (180 / Math.PI);
  const stand = handednessCode(batterStand);
  if (Math.abs(angle) <= 15) return 'center';
  if (stand === 'L') return angle > 15 ? 'pull' : 'push';
  if (stand === 'R') return angle < -15 ? 'pull' : 'push';
  return angle < -15 ? 'pull' : angle > 15 ? 'push' : 'center';
}

function mlbPlaySprayBucket(play = {}, fallbackStand = '') {
  const hitData = mlbPlayHitData(play) || {};
  const coords = hitData.coordinates || hitData.coord || {};
  const x = mlbHitDataNumber(coords, ['coordX', 'x', 'hc_x']) ?? mlbHitDataNumber(hitData, ['coordX', 'x', 'hc_x']);
  const y = mlbHitDataNumber(coords, ['coordY', 'y', 'hc_y']) ?? mlbHitDataNumber(hitData, ['coordY', 'y', 'hc_y']);
  return battedBallSprayBucketFromXy(x, y, mlbPlayBatterStand(play) || fallbackStand);
}

function savantRowBatterStand(row = {}, fallback = '') {
  return handednessCode(csvValue(row, ['stand', 'Stand', 'batter_stands', 'batterStand']) || fallback);
}

function savantRowPitcherThrows(row = {}) {
  return handednessCode(csvValue(row, ['p_throws', 'Pitcher Throws', 'pitcher_throws', 'throws', 'pitcherThrowHand']));
}

function savantRowSprayBucket(row = {}, fallbackStand = '') {
  const x = savantRowNumber(row, ['hc_x', 'HCX', 'hit_coord_x', 'coordX']);
  const y = savantRowNumber(row, ['hc_y', 'HCY', 'hit_coord_y', 'coordY']);
  return battedBallSprayBucketFromXy(x, y, savantRowBatterStand(row, fallbackStand));
}

function emptyBattedBallProfileCounter() {
  return { pa: 0, bbe: 0, classifiedBbe: 0, air: 0, ground: 0, air300: 0, spray: 0, pull: 0, center: 0, push: 0 };
}

function finalizeBattedBallProfileCounter(counter = {}, source = '') {
  const classified = statNumber(counter.classifiedBbe);
  const spray = statNumber(counter.spray);
  const pa = statNumber(counter.pa);
  const air300 = statNumber(counter.air300);
  return {
    pullPct: spray > 0 ? (statNumber(counter.pull) / spray) * 100 : null,
    centerPct: spray > 0 ? (statNumber(counter.center) / spray) * 100 : null,
    pushPct: spray > 0 ? (statNumber(counter.push) / spray) * 100 : null,
    airPct: classified > 0 ? (statNumber(counter.air) / classified) * 100 : null,
    groundPct: classified > 0 ? (statNumber(counter.ground) / classified) * 100 : null,
    paPer300Air: air300 > 0 && pa > 0 ? pa / air300 : null,
    pa,
    bbe: statNumber(counter.bbe),
    classifiedBbe: classified,
    air300,
    source,
  };
}

function addMlbPlayToBattedBallCounter(counter, play = {}, options = {}) {
  const pitcherThrows = handednessCode(options.pitcherThrows);
  if (pitcherThrows && mlbPlayPitcherThrowHand(play) !== pitcherThrows) return;
  if (mlbPlayIsPlateAppearance(play)) counter.pa += 1;
  const batted = mlbPlayBattedBallClass(play);
  if (!batted?.hasBattedBall) return;
  counter.bbe += 1;
  if (batted.isAir === true) {
    counter.classifiedBbe += 1;
    counter.air += 1;
    if (Number.isFinite(batted.distance) && batted.distance >= 300) counter.air300 += 1;
  } else if (batted.isGround === true) {
    counter.classifiedBbe += 1;
    counter.ground += 1;
  }
  const bucket = mlbPlaySprayBucket(play, options.batterStand || '');
  if (bucket) {
    counter.spray += 1;
    counter[bucket] += 1;
  }
}

function computeSavantBattedBallProfileFromRows(rows = [], options = {}) {
  const counter = emptyBattedBallProfileCounter();
  const pitcherThrows = handednessCode(options.pitcherThrows);
  const batterStand = handednessCode(options.batterStand);
  for (const row of listify(rows)) {
    if (pitcherThrows && savantRowPitcherThrows(row) !== pitcherThrows) continue;
    if (isSavantPlateAppearanceRow(row)) counter.pa += 1;
    if (!isSavantBattedBallRow(row)) continue;
    counter.bbe += 1;
    if (isSavantAirBall(row)) {
      counter.classifiedBbe += 1;
      counter.air += 1;
      const distance = savantHitDistance(row);
      if (Number.isFinite(distance) && distance >= 300) counter.air300 += 1;
    } else if (isSavantGroundBall(row)) {
      counter.classifiedBbe += 1;
      counter.ground += 1;
    }
    const bucket = savantRowSprayBucket(row, batterStand);
    if (bucket) {
      counter.spray += 1;
      counter[bucket] += 1;
    }
  }
  return finalizeBattedBallProfileCounter(counter, options.source || 'Savant Statcast event rows');
}

function battedBallProfileHasAnyValue(profile = null) {
  return Boolean(profile) && ['pullPct', 'centerPct', 'pushPct', 'airPct', 'groundPct', 'paPer300Air'].some((key) => Number.isFinite(Number(profile[key])));
}

async function getMlbBatterGameLogSplits(playerId, season) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const cacheKey = `${id}:mlb-batter-gamelog:${season}:v1`;
  if (savantAirSprayCache.has(cacheKey)) return savantAirSprayCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'hitting');
    url.searchParams.set('season', String(season));
    url.searchParams.set('gameType', 'R');
    const payload = await getJson(url.toString());
    return listify(payload?.stats?.[0]?.splits);
  })().catch((error) => {
    savantAirSprayCache.delete(cacheKey);
    throw error;
  });
  savantAirSprayCache.set(cacheKey, promise);
  return promise;
}

async function getMlbBatterBattedBallProfileFromGameFeeds(playerId, season, targetDate, options = {}) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const dateLimit = String(targetDate || `${season}-12-31`);
  const pitcherThrows = handednessCode(options.pitcherThrows);
  const lastGameCount = Math.max(0, Number(options.lastGameCount) || 0);
  const cacheKey = `${id}:mlb-batted-ball-feed-profile:${season}:${dateLimit}:${pitcherThrows || 'all'}:${lastGameCount || 'season'}:v4`;
  if (savantAirSprayCache.has(cacheKey)) return savantAirSprayCache.get(cacheKey);
  const promise = (async () => {
    const splits = await getMlbBatterGameLogSplits(id, season);
    let eligible = listify(splits)
      .filter((split) => split?.date && String(split.date).slice(0, 10) <= dateLimit)
      .sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')));
    if (lastGameCount > 0) eligible = eligible.slice(-lastGameCount);
    const paFromLog = pitcherThrows ? 0 : eligible.reduce((sum, split) => sum + mlbBatterGameLogPa(split), 0);
    const gamePks = [...new Set(eligible.map(statLogSplitGamePk).filter((gamePk) => Number.isFinite(gamePk) && gamePk > 0))];
    const counter = emptyBattedBallProfileCounter();
    await mapWithConcurrency(gamePks, 4, async (gamePk) => {
      const live = await getLiveGameFeed(gamePk).catch(() => null);
      const plays = listify(live?.liveData?.plays?.allPlays);
      for (const play of plays) {
        if (mlbPlayBatterId(play) !== id) continue;
        addMlbPlayToBattedBallCounter(counter, play, { pitcherThrows, batterStand: options.batterStand });
      }
    });
    if (!pitcherThrows && paFromLog > counter.pa) counter.pa = paFromLog;
    return finalizeBattedBallProfileCounter(
      counter,
      `MLB StatsAPI game feeds (${season}${pitcherThrows ? ` vs ${pitcherThrows}HP` : ''}${lastGameCount ? `, last ${lastGameCount} games` : ''})`
    );
  })().catch((error) => {
    savantAirSprayCache.delete(cacheKey);
    throw error;
  });
  savantAirSprayCache.set(cacheKey, promise);
  return promise;
}

async function getBatterBattedBallProfile(playerId, game = null, options = {}) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const targetDate = typeof playerStatTargetDate === 'function'
    ? playerStatTargetDate(game)
    : (dateInput.value || formatDate(new Date()));
  const season = seasonForDate(targetDate);
  const pitcherThrows = handednessCode(options.pitcherThrows);
  const batterStand = handednessCode(options.batterStand);
  const cacheKey = `${id}:batted-ball-pop-profile:${season}:${targetDate}:${pitcherThrows || 'all'}:${batterStand || 'unk'}:v12`;
  if (savantAirSprayCache.has(cacheKey)) return savantAirSprayCache.get(cacheKey);
  const promise = (async () => {
    const [spray, rowsResult, mlbFeed, mlbL3Feed] = await Promise.all([
      pitcherThrows ? Promise.resolve(null) : getSavantAirSprayProfile(id, season).catch(() => null),
      getSavantPitchEventRows(id, 'batter', season).catch(() => []),
      getMlbBatterBattedBallProfileFromGameFeeds(id, season, targetDate, { pitcherThrows, batterStand }).catch(() => null),
      getMlbBatterBattedBallProfileFromGameFeeds(id, season, targetDate, { pitcherThrows, batterStand, lastGameCount: 3 }).catch(() => null),
    ]);
    const eligible = listify(rowsResult).filter((row) => {
      const date = cleanSummary(csvValue(row, ['game_date', 'Game Date', 'date'])).slice(0, 10);
      return !date || String(date) <= String(targetDate);
    });
    const recentKeys = [...new Set(eligible
      .map((row) => cleanSummary(csvValue(row, ['game_pk', 'gamePk', 'Game PK'])) || cleanSummary(csvValue(row, ['game_date', 'Game Date', 'date'])).slice(0, 10))
      .filter(Boolean))].slice(-3);
    const recentRows = recentKeys.length ? eligible.filter((row) => {
      const key = cleanSummary(csvValue(row, ['game_pk', 'gamePk', 'Game PK'])) || cleanSummary(csvValue(row, ['game_date', 'Game Date', 'date'])).slice(0, 10);
      return recentKeys.includes(key);
    }) : [];
    const eventProfile = computeSavantBattedBallProfileFromRows(eligible, { pitcherThrows, batterStand, source: `Savant Statcast event rows (${season}${pitcherThrows ? ` vs ${pitcherThrows}HP` : ''})` });
    const eventL3Profile = computeSavantBattedBallProfileFromRows(recentRows, { pitcherThrows, batterStand, source: `Savant Statcast event rows last 3 games (${season}${pitcherThrows ? ` vs ${pitcherThrows}HP` : ''})` });

    const paFromLeaderboard = statNumber(spray?.pa);
    const leaderboardAirPct = finiteBattedBallNumber(spray?.airPct);
    const leaderboardGroundPct = finiteBattedBallNumber(spray?.groundPct);
    const base = battedBallProfileHasAnyValue(mlbFeed) ? mlbFeed : eventProfile;
    const l3 = battedBallProfileHasAnyValue(mlbL3Feed) ? mlbL3Feed : eventL3Profile;
    const profile = {
      pitcherThrows,
      pullPct: Number.isFinite(base?.pullPct) ? base.pullPct : finiteBattedBallNumber(spray?.pullPct ?? spray?.pullAirPctCurrent),
      centerPct: Number.isFinite(base?.centerPct) ? base.centerPct : finiteBattedBallNumber(spray?.straightPct ?? spray?.straightAirPctCurrent),
      pushPct: Number.isFinite(base?.pushPct) ? base.pushPct : finiteBattedBallNumber(spray?.oppoPct ?? spray?.oppoAirPctCurrent),
      airPct: Number.isFinite(base?.airPct)
        ? base.airPct
        : (validAirGroundPair(leaderboardAirPct, leaderboardGroundPct) ? leaderboardAirPct : null),
      groundPct: Number.isFinite(base?.groundPct)
        ? base.groundPct
        : (validAirGroundPair(leaderboardAirPct, leaderboardGroundPct) ? leaderboardGroundPct : null),
      paPer300Air: Number.isFinite(base?.paPer300Air) && base.paPer300Air > 0 ? base.paPer300Air : null,
      pa: base?.pa || paFromLeaderboard,
      bbe: base?.bbe || statNumber(spray?.bip),
      classifiedBbe: base?.classifiedBbe || null,
      air300: base?.air300 || 0,
      recent: battedBallProfileHasAnyValue(l3) ? l3 : null,
      source: base?.source || `Savant details + spray leaderboard (${season})`,
    };
    return profile;
  })().catch((error) => {
    savantAirSprayCache.delete(cacheKey);
    throw error;
  });
  savantAirSprayCache.set(cacheKey, promise);
  return promise;
}


function batterBattedBallStackCell(profile = null, key = '', formatter = batterBattedBallPct, label = '') {
  const season = formatter(profile?.[key]);
  const recent = profile?.recent ? formatter(profile.recent?.[key]) : '--';
  const hasRecent = recent && recent !== '--';
  const handText = profile?.pitcherThrows ? ` vs ${handednessCode(profile.pitcherThrows)}HP` : ' vs current pitcher handedness';
  const title = `${label || key}${handText}: season ${season || '--'}${hasRecent ? ` | L3 games ${recent}` : ''}`;
  return `<td class="player-batted-ball-stacked-cell" title="${escapeHtml(title)}"><span>${escapeHtml(season || '--')}</span>${hasRecent ? `<br><em>${escapeHtml(recent)}</em>` : ''}</td>`;
}

function batterBattedBallProfileHtml(profile = null) {
  const loading = !profile;
  const sourceTitle = profile?.source || 'Loading batted-ball profile';
  if (loading) {
    return `
      <table class="player-stat-table player-batted-ball-profile-table" title="${escapeHtml(sourceTitle)}">
        <thead><tr><th>Pull</th><th>Ctr</th><th>Push</th><th>Air</th><th>GB</th><th>PA/300</th></tr></thead>
        <tbody><tr><td>--</td><td>--</td><td>--</td><td>--</td><td>--</td><td>--</td></tr></tbody>
      </table>
    `;
  }
  return `
    <table class="player-stat-table player-batted-ball-profile-table" title="${escapeHtml(sourceTitle)}">
      <thead>
        <tr>
          <th title="Pull percentage vs the handedness of the current opposing pitcher">Pull</th>
          <th title="Center-field percentage vs the handedness of the current opposing pitcher">Ctr</th>
          <th title="Push/opposite-field percentage vs the handedness of the current opposing pitcher">Push</th>
          <th title="Air-ball percentage vs the handedness of the current opposing pitcher">Air</th>
          <th title="Ground-ball percentage vs the handedness of the current opposing pitcher">GB</th>
          <th title="Plate appearances per 300+ ft air ball vs the handedness of the current opposing pitcher">PA/300</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          ${batterBattedBallStackCell(profile, 'pullPct', batterBattedBallPct, 'Pull')}
          ${batterBattedBallStackCell(profile, 'centerPct', batterBattedBallPct, 'Center')}
          ${batterBattedBallStackCell(profile, 'pushPct', batterBattedBallPct, 'Push')}
          ${batterBattedBallStackCell(profile, 'airPct', batterBattedBallPct, 'Air')}
          ${batterBattedBallStackCell(profile, 'groundPct', batterBattedBallPct, 'Ground')}
          ${batterBattedBallStackCell(profile, 'paPer300Air', (value) => batterBattedBallRate(value, 1), 'PA/300')}
        </tr>
      </tbody>
    </table>
  `;
}

function renderPlayerHandedSplits(profile, game, token) {
  if (!playerStatExtraEl || !profile?.id) return;
  let matchupPitcher = currentMatchupPitcher(profile, game);
  const matchupHand = pitcherThrowHandValue(matchupPitcher);
  const matchupPitcherId = matchupPitcher?.id || '';
  let handed = null;
  let starterSplits = null;
  let starterRecentHand = null;
  let showPitchTable = false;
  const pitchHtml = () => showPitchTable
    ? playerStatHeatMapTable('', visiblePlayerCardPitchTableShell('batter', profile.id, matchupPitcherId, matchupHand))
    : '';
  const paint = () => {
    if (!playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return;
    updatePlayerSeasonArchetypeTable('');
    playerStatExtraEl.innerHTML = `${battingContextHtml(handed, matchupHand)}${batterStarterHandednessHtml(matchupPitcher, starterSplits, profile?.bats, starterRecentHand, profile?.id)}${pitchHtml()}`;
    hydratePitcherFireStreaks(playerStatExtraEl);
    hydratePitcherColdStreaks(playerStatExtraEl);
    hydratePitcherLastStartHrMarkers(playerStatExtraEl);
    hydratePitcherOpponentHandMarkers(playerStatExtraEl);
    hydrateVisibleBatterVelocityBucketTables(profile, game, token);
    if (showPitchTable) hydrateVisiblePlayerCardPitchTables(profile, game, token);
  };
  paint();
  Promise.allSettled([
    getPlayerHandedBattingSplits(profile.id),
    getPlayerRecentBattingDetails(profile.id, game),
  ]).then(([splitResult, recentResult]) => {
    if (!playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return;
    const splits = splitResult.status === 'fulfilled' ? splitResult.value : null;
    const gamesSince = recentResult.status === 'fulfilled' ? recentResult.value?.gamesSince || null : null;
    renderPlayerBattingSeasonBlock(profile, game, gamesSince);
    handed = splits ? { vsLeft: splits.vsLeft, vsRight: splits.vsRight } : null;
    paint();
  });
  if (matchupPitcher?.id) {
    const syncedPitcherPromise = syncedFirstAppearancePitcherProfileForGame(matchupPitcher, game)
      .then((syncedPitcher) => {
        if (syncedPitcher && playerStatExtraEl?.dataset?.splitToken === token) {
          matchupPitcher = syncedPitcher;
          paint();
        }
        return syncedPitcher || matchupPitcher;
      })
      .catch(() => matchupPitcher);
    syncedPitcherPromise
      .then((pitcherForSplits) => getPitcherOpponentHandSplits(pitcherForSplits || matchupPitcher))
      .then((splits) => {
        if (!playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return;
        starterSplits = splits;
        paint();
      })
      .catch(() => {});
    syncedPitcherPromise
      .then((pitcherForSplits) => playerStatGameLogSplits((pitcherForSplits || matchupPitcher).id, 'pitching', game, pitcherOpponentHandSeasonForProfile(pitcherForSplits || matchupPitcher)))
      .then((splits) => {
        if (!playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return null;
        const starts = filteredRecentHistorySplits(splits, game).filter(isPitchingStartSplit).slice(0, 3);
        return getPitcherRecentOpponentHandSplits(matchupPitcher.id, starts);
      })
      .then((recentHand) => {
        if (!recentHand || !playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return;
        starterRecentHand = recentHand;
        paint();
      })
      .catch(() => {});
  } else {
    paint();
  }
  // The pitch-by-pitch table is useful, but it is no longer a priority load. Let
  // season/14D/handedness paint first, then hydrate pitches quietly.
  window.setTimeout(() => {
    if (!playerStatExtraEl || playerStatExtraEl.dataset.splitToken !== token) return;
    showPitchTable = true;
    paint();
  }, 1200);
}

function matchupPitcherHandForLineup(game, battingSide) {
  const pitcher = matchupPitcherForLineup(game, battingSide);
  return pitcherThrowHandValue(pitcher);
}

function matchupPitcherForLineup(game, battingSide) {
  const pitcherSide = battingSide === 'home' ? 'away' : battingSide === 'away' ? 'home' : '';
  if (!pitcherSide) return null;
  const probable = typeof predictionProbableStarterForSide === 'function'
    ? predictionProbableStarterForSide(game, pitcherSide)
    : null;
  if (shouldPreferProbablePitcher(game) && probable) return probable;
  return scoreboardPitcherForSide(game, pitcherSide)
    || resolveLineupPitcherForDisplay(game, pitcherSide)?.current
    || resolveLineupPitcherForDisplay(game, pitcherSide)?.starter
    || probable
    || null;
}

async function handedSplitFlagMapForLineup(game, side, lineup = []) {
  const matchupHand = matchupPitcherHandForLineup(game, side);
  const splitHand = handednessCode(matchupHand);
  if (!splitHand || !Array.isArray(lineup) || !lineup.length) return new Map();
  const pairs = await Promise.all(
    lineup.map(async (entry) => {
      const id = Number(entry?.id);
      if (!Number.isFinite(id) || id <= 0) return null;
      const stat = await getPlayerHandedBattingSplit(id, splitHand === 'L' ? 'vl' : 'vr').catch(() => null);
      const html = handedSplitEmojiHtml(stat, splitHand, matchupHand);
      return html ? [String(id), html] : null;
    }),
  );
  return new Map(pairs.filter(Boolean));
}

function effectiveBatterHandForPitcher(batterHand, pitcherHand) {
  const batter = handednessCode(batterHand);
  if (batter === 'S') return handednessCode(pitcherHand) === 'L' ? 'R' : 'L';
  return batter === 'L' || batter === 'R' ? batter : '';
}

function isGoodHitterHandedSplit(stat = null) {
  const avg = rateNumber(stat?.avg);
  const slg = rateNumber(stat?.slg);
  return (Number.isFinite(avg) && avg >= 0.300) || (Number.isFinite(slg) && slg >= 0.500);
}

function isBadPitcherOpponentHandSplit(stat = null) {
  const avg = rateNumber(stat?.avg);
  const slg = rateNumber(stat?.slg);
  return (Number.isFinite(avg) && avg >= 0.300) || (Number.isFinite(slg) && slg > 0.600);
}

async function eliteMatchupMapForLineup(game, side, lineup = [], batterBadgeMap = new Map()) {
  const pitcher = matchupPitcherForLineup(game, side);
  const pitcherHand = handednessCode(pitcherThrowHandValue(pitcher));
  const pitcherId = Number(pitcher?.id);
  if (!pitcherHand || !Number.isFinite(pitcherId) || pitcherId <= 0 || !Array.isArray(lineup) || !lineup.length) return new Map();
  const pitcherSplits = await getPitcherOpponentHandSplits(pitcher).catch(() => null);
  if (!pitcherSplits) return new Map();
  const pairs = await Promise.all(lineup.map(async (entry) => {
    const id = Number(entry?.id);
    if (!Number.isFinite(id) || id <= 0) return null;
    const badges = batterBadgeMap?.get?.(String(id));
    if (!badges?.slugBurst) return null;
    const batterHand = effectiveBatterHandForPitcher(entry?.bats, pitcherHand);
    if (!batterHand) return null;
    const pitcherSplit = batterHand === 'L' ? pitcherSplits.vsLeft : pitcherSplits.vsRight;
    if (!isBadPitcherOpponentHandSplit(pitcherSplit)) return null;
    const hitterSplit = await getPlayerHandedBattingSplit(id, pitcherHand === 'L' ? 'vl' : 'vr').catch(() => null);
    if (!isGoodHitterHandedSplit(hitterSplit)) return null;
    const title = [
      `Elite matchup vs ${handednessCode(pitcherHand)}HP`,
      `recent SLG ${formatRateValue(badges.slugBurstValue, 3, true)}`,
      `hitter split ${cleanSummary(hitterSplit?.avg) || '---'} AVG/${cleanSummary(hitterSplit?.slg) || '---'} SLG`,
      `pitcher vs ${batterHand} ${cleanSummary(pitcherSplit?.avg) || '---'} AVG/${cleanSummary(pitcherSplit?.slg) || '---'} SLG`,
    ].join(' | ');
    return [String(id), title];
  }));
  return new Map(pairs.filter(Boolean));
}

function hexToRgb(hex) {
  const raw = hex.replace('#', '');
  const full = raw.length === 3 ? raw.split('').map((c) => c + c).join('') : raw;
  const num = Number.parseInt(full, 16);
  return `${(num >> 16) & 255}, ${(num >> 8) & 255}, ${num & 255}`;
}

function rgbChannels(hex) {
  const raw = String(hex || '').replace('#', '');
  const full = raw.length === 3 ? raw.split('').map((c) => c + c).join('') : raw;
  const num = Number.parseInt(full, 16);
  if (!Number.isFinite(num)) return { r: 221, g: 233, b: 255 };
  return { r: (num >> 16) & 255, g: (num >> 8) & 255, b: num & 255 };
}

function mixHex(hex, target, amount) {
  const c = rgbChannels(hex);
  const t = target === 'white' ? { r: 255, g: 255, b: 255 } : { r: 0, g: 0, b: 0 };
  const a = Math.max(0, Math.min(1, Number(amount) || 0));
  const r = Math.round(c.r * (1 - a) + t.r * a);
  const g = Math.round(c.g * (1 - a) + t.g * a);
  const b = Math.round(c.b * (1 - a) + t.b * a);
  return `rgb(${r}, ${g}, ${b})`;
}

function cleanPlayText(value) {
  return cleanSummary(value)
    .replace(/\bGame Advisory\b/gi, '')
    .replace(/\s+([.,;:!?])/g, '$1')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

function isAdministrativePlayText(value = '') {
  return /\b(game advisory|status change|review|challenge|delay|delayed|weather advisory|official scorer|umpire|mound visit)\b/i.test(String(value || ''));
}

function latestBaseballPlayEvent(play = null) {
  const events = Array.isArray(play?.playEvents) ? play.playEvents : [];
  for (const event of [...events].reverse()) {
    const text = cleanPlayText(event?.details?.description || event?.details?.event || event?.type || '');
    if (!text || isAdministrativePlayText(text)) continue;
    if (event?.isPitch || event?.pitchData || event?.hitData || event?.details?.isInPlay || event?.details?.isOut || event?.details?.isScoringPlay) return event;
  }
  return null;
}

function latestBaseballPlayEventText(play = null) {
  const event = latestBaseballPlayEvent(play);
  return cleanPlayText(event?.details?.description || event?.details?.event || event?.type || '');
}

function eventLabel(play) {
  const batterName = cleanPlayText(play?.matchup?.batter?.fullName || 'Unknown');
  const shortName = lastName(batterName);
  const event = cleanPlayText(play?.result?.event || play?.result?.eventType || 'Play') || 'Play';
  const description = cleanPlayText(play?.result?.description || '');
  if (isAdministrativePlayText(event) || isAdministrativePlayText(description)) {
    const liveEvent = latestBaseballPlayEventText(play);
    if (liveEvent) return `${shortName} ${liveEvent}`;
  }
  const describedName = (pattern) => {
    const match = String(description || '').match(pattern);
    return match?.[1] ? lastName(match[1].trim()) : '';
  };
  if (/stolen base/i.test(event) || /steals/i.test(description)) {
    const runner = describedName(/^(.+?)\s+steals\b/i) || describedName(/^(.+?)\s+to\s+\d/i);
    return `${runner || shortName} SB`;
  }
  if (/caught stealing/i.test(event) || /caught stealing/i.test(description)) {
    const runner = describedName(/^(.+?)\s+caught stealing/i);
    return `${runner || shortName} CS`;
  }
  if (/pitching substitution|pitching change/i.test(event) || /pitching change/i.test(description)) {
    const change = description.match(/pitching change:\s*(.+?)\s+replaces\s+(.+?)(?:\.|$)/i)
      || description.match(/(.+?)\s+replaces\s+(.+?)(?:\.|$)/i);
    if (change) return `${lastName(change[2])} substituted for ${lastName(change[1])}`;
    return description || 'Pitching substitution';
  }
  if (/defensive substitution|offensive substitution|pinch/i.test(event) || /defensive substitution|offensive substitution|pinch/i.test(description)) {
    const change = description.match(/(.+?)\s+replaces\s+(.+?)(?:\.|$)/i)
      || description.match(/(.+?)\s+enters.*?for\s+(.+?)(?:\.|$)/i);
    if (change) return `${lastName(change[2])} substituted for ${lastName(change[1])}`;
    return description || 'Substitution';
  }
  if (/home run/i.test(event)) return `${shortName} HR`;
  if (/single/i.test(event)) return `${shortName} 1B`;
  if (/double/i.test(event)) return `${shortName} 2B`;
  if (/triple/i.test(event)) return `${shortName} 3B`;
  if (/^play$/i.test(event)) return `${shortName} At Bat`;
  if (event.includes('Strikeout')) return `${shortName} K`;
  const shorthand = description.match(/\bP\d{1,2}\b/i)?.[0];
  if (shorthand) return `${shortName} ${shorthand.toUpperCase()}`;
  return `${shortName} ${event}`;
}

function playByPlayDescription(play) {
  const label = eventLabel(play);
  const description = cleanPlayText(play?.result?.description || '');
  if (isAdministrativePlayText(description)) {
    const liveEvent = latestBaseballPlayEventText(play);
    if (liveEvent) return `${label} - ${liveEvent}`;
  }
  if (!description) return label;
  return description.toLowerCase().startsWith(label.toLowerCase()) ? description : `${label} - ${description}`;
}


function isScoreboardAtBatText(value) {
  return /\bat bat\b/i.test(cleanPlayText(value || ''));
}

function isScoreboardTerminalPlay(play = null) {
  if (!play) return false;
  const label = cleanPlayText(eventLabel(play));
  if (!label || isPlaceholderPlay(label) || isScoreboardAtBatText(label)) return false;
  if (typeof isLiveLabTransientAdministrativeText === 'function' && isLiveLabTransientAdministrativeText(label)) return false;
  const event = cleanPlayText(play?.result?.event || play?.result?.eventType || '');
  const description = cleanPlayText(play?.result?.description || '');
  if (/^play$/i.test(event) && !description) return false;
  return true;
}

function scoreboardCompletedPlayText(game = null) {
  const candidates = [];
  if (game?.activePlay) candidates.push(game.activePlay);
  if (Array.isArray(game?.allPlays)) candidates.push(...[...game.allPlays].reverse());
  const seen = new Set();
  for (const play of candidates) {
    const key = [
      play?.about?.atBatIndex ?? '',
      play?.matchup?.batter?.id ?? '',
      play?.result?.event || play?.result?.eventType || '',
      play?.result?.description || '',
    ].join('|');
    if (seen.has(key)) continue;
    seen.add(key);
    if (isScoreboardTerminalPlay(play)) return cleanPlayText(eventLabel(play));
  }
  return '';
}

function firstScoreboardNonAtBatText(...values) {
  for (const value of values) {
    const text = cleanPlayText(value || '');
    if (!text || isPlaceholderPlay(text) || isScoreboardAtBatText(text)) continue;
    if (typeof isLiveLabTransientAdministrativeText === 'function' && isLiveLabTransientAdministrativeText(text)) continue;
    return text;
  }
  return '';
}

function scoreboardActiveBatterName(game = null) {
  if (!game || !hasLiveAtBat(game)) return '';
  const directName = cleanSummary(game?.activeBatterName || '');
  if (directName) return lastName(directName);
  const side = game?.battingSide === 'home' ? 'home' : 'away';
  const hitter = scoreboardHitterForSide(game, side);
  const hitterName = scoreboardHitterName(hitter);
  if (hitterName && hitterName !== '-') return hitterName;
  const fallbackLine = cleanSummary(side === 'home' ? game?.homeHitter : game?.awayHitter);
  const fallbackName = fallbackLine.replace(/\s*\(.*$/, '').replace(/\s+AVG\b.*$/i, '').trim();
  return fallbackName ? lastName(fallbackName) : '';
}

function scoreboardActiveAtBatText(game = null) {
  if (!game || !hasLiveAtBat(game)) return '';
  const currentEvent = cleanPlayText(game?.currentEvent || '');
  const lastPlayText = cleanPlayText(game?.lastPlay || '');
  const activeComplete = Boolean(game?.activePlayComplete);
  if (activeComplete) return '';
  if (/home run|strikeout|walk|single|double|triple|field out|groundout|flyout|lineout|pop out|forceout|hit by pitch/i.test(currentEvent)) return '';
  const name = scoreboardActiveBatterName(game);
  return name && name !== '-' ? `${name} at bat` : '';
}

function scoreboardPlayTextForGame(game = null, ticker = []) {
  const activeAtBat = scoreboardActiveAtBatText(game);
  if (activeAtBat) return activeAtBat;
  const completed = scoreboardCompletedPlayText(game);
  if (completed) return completed;
  const tickerTexts = Array.isArray(ticker) ? ticker.map((item) => item?.text) : [];
  return firstScoreboardNonAtBatText(game?.lastPlay, ...tickerTexts, game?.currentEvent)
    || firstRealPlayText(...tickerTexts, game?.lastPlay, game?.currentEvent);
}

function scoreFromPlayHistory(allPlays, side) {
  const keyName = side === 'away' ? 'awayScore' : 'homeScore';
  for (const play of [...(Array.isArray(allPlays) ? allPlays : [])].reverse()) {
    const value = Number(play?.result?.[keyName]);
    if (Number.isFinite(value)) return value;
  }
  return null;
}

function scoreFromLineInnings(linescore, side) {
  const total = (Array.isArray(linescore?.innings) ? linescore.innings : [])
    .reduce((sum, inning) => {
      const runs = Number(inning?.[side]?.runs);
      return Number.isFinite(runs) ? sum + runs : sum;
    }, 0);
  return total > 0 ? total : null;
}

function gameScoreForSide(game, linescore, allPlays, side) {
  const lineValue = Number(linescore?.teams?.[side]?.runs);
  if (Number.isFinite(lineValue)) return lineValue;
  const inningValue = scoreFromLineInnings(linescore, side);
  if (Number.isFinite(Number(inningValue))) return inningValue;
  const scheduleValue = Number(game?.teams?.[side]?.score);
  if (Number.isFinite(scheduleValue)) return scheduleValue;
  const playValue = scoreFromPlayHistory(allPlays, side);
  if (Number.isFinite(Number(playValue))) return playValue;
  return '-';
}

function gameHitsForSide(linescore, side) {
  const lineValue = Number(linescore?.teams?.[side]?.hits);
  if (Number.isFinite(lineValue)) return lineValue;
  const inningValue = (Array.isArray(linescore?.innings) ? linescore.innings : [])
    .reduce((sum, inning) => {
      const hits = Number(inning?.[side]?.hits);
      return Number.isFinite(hits) ? sum + hits : sum;
    }, 0);
  return inningValue > 0 ? inningValue : '-';
}

function setupOverflowMarquee(el) {
  if (!el) return;
  const text = String(el.dataset.renderValue ?? el.textContent ?? '');
  const visibleWidth = Math.round(el.clientWidth || el.getBoundingClientRect?.().width || 0);

  // During first dashboard paint the scoreboard can briefly report a 0px text box.
  // Do not lock that bad measurement into the marquee state. Retry on the next
  // frame so pregame start times and pitcher names become visible without a hover.
  if (visibleWidth <= 5) {
    el.dataset.marqueePending = '1';
    requestAnimationFrame(() => {
      if (el.dataset.renderValue === text) setupOverflowMarquee(el);
    });
    return;
  }

  if (
    el.dataset.marqueeMode === 'single'
    && el.dataset.marqueeText === text
    && Number(el.dataset.marqueeWidth || 0) === visibleWidth
    && el.querySelector('.marquee-track')
  ) return;

  el.dataset.marqueePending = '';
  el.dataset.marqueeMode = 'single';
  el.dataset.marqueeText = text;
  el.dataset.marqueeWidth = String(visibleWidth);
  el.classList.remove('overflow-marquee');
  el.style.removeProperty('--marquee-distance');
  el.style.removeProperty('--marquee-duration');
  el.style.removeProperty('--marquee-delay');

  let track = el.querySelector('.marquee-track');
  if (!track) {
    el.replaceChildren();
    track = document.createElement('span');
    track.className = 'marquee-track';
    el.appendChild(track);
  }

  track.textContent = text;
  // Force a true content-width measurement. Some compact dashboard overrides
  // set min-width: 0 before the overflow class is added, which made scrollWidth
  // equal the clipped container and prevented the marquee from ever starting.
  track.style.display = 'inline-block';
  track.style.whiteSpace = 'nowrap';
  track.style.minWidth = 'max-content';
  track.style.width = 'max-content';
  track.style.transform = 'translate3d(0, 0, 0)';

  void track.offsetWidth;
  const contentWidth = Math.ceil(track.scrollWidth || track.getBoundingClientRect?.().width || 0);
  const overflow = Math.ceil(contentWidth - visibleWidth);
  if (overflow <= 10) {
    el.textContent = text;
    return;
  }

  const travel = overflow + 8;
  const duration = SCOREBOARD_MARQUEE_DURATION_S;
  const elapsed = typeof performance !== 'undefined' ? (performance.now() / 1000) % duration : 0;
  el.style.setProperty('--marquee-distance', `${travel}px`);
  el.style.setProperty('--marquee-duration', `${duration.toFixed(2)}s`);
  el.style.setProperty('--marquee-delay', `-${elapsed.toFixed(2)}s`);
  el.classList.add('overflow-marquee');
}

function clearOverflowMarquee(el) {
  if (!el) return;
  el.classList.remove('overflow-marquee');
  el.style.removeProperty('--marquee-distance');
  el.style.removeProperty('--marquee-duration');
  el.style.removeProperty('--marquee-delay');
  el.dataset.marqueeMode = '';
  el.dataset.marqueeWidth = '';
  el.replaceChildren();
}

function renderSingleLineMarquee(el, text) {
  if (!el) return;
  const nextText = String(text || '');
  const nextWidth = Math.round(el.clientWidth || 0);
  const contentChanged = el.dataset.renderMode !== 'single' || el.dataset.renderValue !== nextText;
  const widthChanged = Number(el.dataset.renderWidth || 0) !== nextWidth;
  if (!contentChanged && !widthChanged) return;
  if (contentChanged) {
    el.classList.remove('is-multi');
    clearOverflowMarquee(el);
    el.textContent = nextText;
  }
  el.dataset.renderMode = 'single';
  el.dataset.renderValue = nextText;
  el.dataset.renderWidth = String(nextWidth);
  setupOverflowMarquee(el);
}

function renderMultiLineSummary(el, items) {
  if (!el) return;
  const normalizedItems = (items || []).map((item) => ({
    text: String(item?.text || 'Awaiting first pitch'),
    color: String(item?.color || ''),
  }));
  const signature = JSON.stringify(normalizedItems);
  if (el.dataset.renderMode === 'multi' && el.dataset.renderValue === signature) return;
  clearOverflowMarquee(el);
  el.classList.add('is-multi');
  for (const item of normalizedItems) {
    const line = document.createElement('span');
    line.className = 'score-mini-play-line';
    line.textContent = item.text;
    if (item.color) line.style.color = item.color;
    el.appendChild(line);
  }
  el.dataset.renderMode = 'multi';
  el.dataset.renderValue = signature;
  el.dataset.renderWidth = String(Math.round(el.clientWidth || 0));
}

function isFocusedGame(gamePk) {
  return false;
}

function animateNumericChange(el, color) {
  if (!el) return;
  el.style.setProperty('--number-flash-rgb', hexToRgb(color || '#66d9ff'));
  el.classList.remove('number-flip');
  void el.offsetWidth;
  el.classList.add('number-flip');
}

function suppressScoreAnimations(ms = 8000) {
  suppressScoreAnimationsUntil = Math.max(suppressScoreAnimationsUntil, Date.now() + ms);
}

function scoreAnimationMemoryKey(game, side, runs) {
  return [String(game?.gamePk || ''), String(side || ''), Number(runs)].join(':');
}

function rememberScoreAnimation(game, side, runs) {
  scoreAnimationMemory.set(scoreAnimationMemoryKey(game, side, runs), Date.now());
  if (scoreAnimationMemory.size <= 240) return;
  const cutoff = Date.now() - (6 * 60 * 60 * 1000);
  for (const [key, savedAt] of scoreAnimationMemory.entries()) {
    if (savedAt < cutoff || scoreAnimationMemory.size > 240) scoreAnimationMemory.delete(key);
  }
}

function canAnimateScoreIncrease(game, prev, currentRuns, previousRuns, side = '') {
  const current = Number(currentRuns);
  const previous = Number(previousRuns);
  if (!prev || !Number.isFinite(current) || !Number.isFinite(previous)) return false;
  if (gameIsFinalForTeamRecord(game) || isCompletedGameCard(game)) return false;
  const highWater = side === 'home' ? Number(prev.homeHighWaterRuns) : Number(prev.awayHighWaterRuns);
  if (Number.isFinite(highWater) && current <= highWater) return false;
  const delta = current - previous;
  const lastRendered = side === 'home' ? Number(prev.homeRuns) : Number(prev.awayRuns);
  if (!Number.isFinite(lastRendered) || current !== lastRendered + delta) return false;
  if (!Number.isInteger(delta) || delta <= 0 || delta > 4) return false;
  if (scoreAnimationMemory.has(scoreAnimationMemoryKey(game, side, current))) return false;
  if (Date.now() < suppressScoreAnimationsUntil) return false;
  if (document.visibilityState === 'hidden') return false;
  if (!lineupGameShouldAutoRefresh(game)) return false;
  return !prev.seenAt || Date.now() - prev.seenAt <= 45000;
}

function scoreRunAnimationSignature(game, side = '') {
  if (gameIsFinalForTeamRecord(game) || isCompletedGameCard(game)) return '';
  const tickerText = Array.isArray(game?.ticker) ? game.ticker.map((item) => item?.text || '').join(' | ') : '';
  const playText = firstRealPlayText(game?.lastPlay, tickerText, game?.currentEvent) || '';
  const eventText = [game?.currentEvent || '', playText].join(' ');
  const looksScoring = /\b(scores?|scored|run|runs|rbi|homers?|home\s*run|grand\s*slam)\b/i.test(eventText);
  if (!looksScoring) return '';
  return [
    side,
    Number(game?.awayScore),
    Number(game?.homeScore),
    cleanPlayText(eventText).toLowerCase().slice(0, 180),
  ].join('|');
}

function scoreboardScoringSummaryRows(game = null) {
  const rows = [];
  const seen = new Set();
  for (const play of listify(game?.allPlays)) {
    if (!play?.about || !play?.result) continue;
    const runs = liveLabReplayRunTotal(play);
    if (!runs) continue;
    const side = liveLabReplayBattingSide(play);
    if (side !== 'away' && side !== 'home') continue;
    const description = scoreboardScoringPlayLabel(play, runs);
    const inning = Number(play?.about?.inning);
    const key = `${play?.about?.atBatIndex ?? rows.length}:${side}:${description}`;
    if (seen.has(key)) continue;
    seen.add(key);
    rows.push({
      inning: Number.isFinite(inning) && inning > 0 ? inning : 0,
      side,
      text: cleanPlayText(description),
      color: side === 'home' ? (game?.homeColor || getTeamColor(game?.home)) : (game?.awayColor || getTeamColor(game?.away)),
    });
  }
  return rows;
}

function scoreboardScoringPlayAbbreviation(play = null) {
  const event = cleanPlayText(play?.result?.event || play?.result?.eventType || '');
  const description = cleanPlayText(play?.result?.description || '');
  const text = `${event} ${description}`;
  if (/grand slam|home run|homers?\b/i.test(text)) return 'HR';
  if (/\btriples?\b|triple/i.test(text)) return '3B';
  if (/\bdoubles?\b|double/i.test(text)) return '2B';
  if (/\bsingles?\b|single/i.test(text)) return '1B';
  if (/sacrifice fly|\bsac fly\b/i.test(text)) return 'SF';
  if (/sacrifice bunt|\bsac bunt\b/i.test(text)) return 'SAC';
  if (/grounded into double play|double play/i.test(text)) return 'GIDP';
  if (/fielder'?s choice/i.test(text)) return 'FC';
  if (/walk|base on balls/i.test(text)) return 'BB';
  if (/hit by pitch/i.test(text)) return 'HBP';
  if (/wild pitch/i.test(text)) return 'WP';
  if (/passed ball/i.test(text)) return 'PB';
  if (/balk/i.test(text)) return 'BK';
  if (/stolen base|steals?\b/i.test(text)) return 'SB';
  if (/error|fielding error|throwing error/i.test(text)) return 'E';
  if (/groundout|grounds? out/i.test(text)) return 'GO';
  if (/flyout|flies? out|lineout|pop out|pops? out/i.test(text)) return 'OUT';
  if (/strikeout|strikes? out/i.test(text)) return 'K';
  return 'PLAY';
}

function scoreboardScoringPlayLabel(play = null, runs = 0) {
  const batterName = cleanPlayText(play?.matchup?.batter?.fullName || play?.matchup?.batter?.name || 'Player');
  const name = lastName(batterName) || batterName || 'Player';
  const abbr = scoreboardScoringPlayAbbreviation(play);
  const runCount = Math.max(1, Number(runs) || 1);
  return `${name} ${abbr} ${runCount}R scored`;
}

function scoreboardScoringSummaryHtml(game = null) {
  const rows = scoreboardScoringSummaryRows(game);
  if (!rows.length) return '';
  const groups = new Map();
  rows.forEach((row) => {
    const key = row.inning || 0;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(row);
  });
  return Array.from(groups.entries())
    .sort(([a], [b]) => Number(a) - Number(b))
    .map(([inning, items]) => {
      const label = inning ? ordinalNumber(inning) : 'Inning';
      const plays = items.map((item, index) => {
        const separator = index
          ? `<span class="theme-tooltip-score-separator">${items[index - 1]?.side === item.side ? ', ' : ' | '}</span>`
          : '';
        return `${separator}<span class="theme-tooltip-score-play" style="--score-play-color:${escapeHtml(item.color || '#7bd0ff')}">${escapeHtml(item.text)}</span>`;
      }).join('');
      return `<div class="theme-tooltip-score-inning"><b>${escapeHtml(label)}</b> ${plays}</div>`;
    })
    .join('');
}

function syncFocusedGameLayout() {
  focusedGamePk = null;
  priorityHydrationGamePk = '';
  if (!gamesEl) return;
  gamesEl.classList.remove('has-focused-game');
  for (const card of gamesEl.querySelectorAll('.game-card')) {
    card.classList.remove('is-focused', 'is-condensed', 'is-priority-hydrating');
    delete card.dataset.priorityHydrating;
    card.dataset.focusedMatchupSide = '';
    const panel = card.querySelector('.focused-matchup-panel');
    if (panel) {
      panel.hidden = true;
      panel.dataset.renderToken = '';
      panel.dataset.renderSignature = '';
      panel.replaceChildren();
    }
  }
  requestAnimationFrame(refreshAllScoreboardResponsiveLayout);
}

function setFocusedGame(gamePk) {
  focusedGamePk = null;
  priorityHydrationGamePk = '';
  focusedGameHydrationSeq += 1;
  syncFocusedGameLayout();
}

function focusedMatchupSide(gamePk) {
  return focusedMatchupSideByGame.get(String(gamePk || '')) || 'away';
}

function setFocusedMatchupSide(gamePk, side) {
  const normalizedGamePk = String(gamePk || '');
  if (!normalizedGamePk || (side !== 'away' && side !== 'home')) return;
  if (focusedMatchupSideByGame.get(normalizedGamePk) === side) return;
  focusedMatchupSideByGame.set(normalizedGamePk, side);
  const card = gamesEl?.querySelector(`.game-card[data-game-pk='${normalizedGamePk}']`);
  if (card?._game) upsertCard(card._game);
}

function syncFocusedMatchupSelection(card) {
  if (!card) return;
  const isFocused = isFocusedGame(card.dataset.gamePk);
  const activeSide = isFocused ? focusedMatchupSide(card.dataset.gamePk) : '';
  card.dataset.focusedMatchupSide = activeSide;
  const awayTargets = card.querySelectorAll('.away-row, .away-score');
  const homeTargets = card.querySelectorAll('.home-row, .home-score');
  awayTargets.forEach((el) => el.classList.toggle('is-matchup-active', isFocused && activeSide === 'away'));
  homeTargets.forEach((el) => el.classList.toggle('is-matchup-active', isFocused && activeSide === 'home'));
}

function toggleFocusedGame(gamePk) {
  setFocusedGame(null);
}

function statusLine(game) {
  const detailed = cleanSummary(game?.status?.detailedState || game?.status || '');
  const coded = String(game?.status?.codedGameState || '').toUpperCase();
  if (/cancel|postpon|suspend|delay|makeup/i.test(detailed) || ['C', 'D'].includes(coded)) return detailed || 'Game status unavailable';
  if (!gameHasReachedOfficialStart(game)) return `Not Started | ${gameStartTimeText(game)}`;
  const st = game?.status?.abstractGameState;
  if (st === 'Preview') return `Not Started | ${gameStartTimeText(game)}`;
  if (st === 'Final') return 'Final';
  if (/^(live|in progress)$/i.test(detailed)) {
    const text = cleanSummary(game?.inning || game?.inningShort || '');
    if (/(top|bot|bottom|mid|middle)\s*\d+/i.test(text)) return text.replace(/\bBottom\b/i, 'Bot').replace(/\bMiddle\b/i, 'Mid');
    return 'Top 1';
  }
  return detailed || 'Unknown';
}

function shouldPreferProbablePitcher(game) {
  if (!game) return false;
  if (gameHasLiveProgressSignals(game)) return false;
  if (!gameHasReachedOfficialStart(game)) return true;
  if (game?.status?.abstractGameState === 'Preview') return true;
  const inningShort = String(game?.inningShort || '').toUpperCase();
  if (inningShort === 'PRE') return true;
  const status = String(game?.status?.detailedState || game?.status || '').toLowerCase();
  const coded = String(game?.status?.codedGameState || game?.status?.statusCode || '').toUpperCase();
  return status.includes('not started')
    || status.includes('scheduled')
    || status.includes('pre-game')
    || status.includes('warmup')
    || coded === 'P'
    || coded === 'PW';
}

function normalizeHalfInning(value) {
  const raw = String(value || '').toLowerCase();
  if (raw.includes('top')) return 'top';
  if (raw.includes('bottom') || raw.includes('bot')) return 'bottom';
  if (raw.includes('middle') || raw === 'mid') return 'middle';
  if (raw.includes('end')) return 'end';
  return '';
}

function gameWithInferredFinalStatus(game, isFinal) {
  if (!isFinal) return game;
  const status = typeof game?.status === 'object' && game.status
    ? game.status
    : {};
  return {
    ...game,
    status: {
      ...status,
      abstractGameState: 'Final',
      detailedState: 'Final',
      codedGameState: 'F',
      statusCode: 'F',
    },
  };
}

function linescoreLastCompletedInningNumber(linescore = {}, play = null) {
  const innings = Array.isArray(linescore?.innings) ? linescore.innings : [];
  const halfHasRecordedLine = (half = {}) => {
    if (!half || typeof half !== 'object') return false;
    return ['runs', 'hits', 'errors', 'leftOnBase'].some((key) => Number.isFinite(Number(half[key])));
  };
  const lastCompletedFromLinescore = innings.reduce((max, inning) => {
    const n = Number(inning?.num ?? inning?.ordinalNum);
    if (!Number.isFinite(n) || n <= max) return max;
    const awayDone = halfHasRecordedLine(inning?.away);
    const homeDone = halfHasRecordedLine(inning?.home);
    return awayDone && homeDone ? n : max;
  }, 0);
  if (lastCompletedFromLinescore > 0) return lastCompletedFromLinescore;
  const playInning = Number(play?.about?.inning);
  const playHalf = normalizeHalfInning(play?.about?.halfInning);
  const playOuts = liveLabReplayOutsAfterPlay(play);
  if (Number.isFinite(playInning) && playInning > 0 && playHalf === 'bottom' && playOuts >= 3) return playInning;
  const current = Number(linescore?.currentInning);
  const stateHalf = normalizeHalfInning(linescore?.inningHalf || linescore?.inningState);
  if (Number.isFinite(current) && current > 1 && stateHalf === 'middle') return current - 1;
  if (Number.isFinite(current) && current > 0 && stateHalf === 'end') return current;
  return 0;
}

function gameLooksFinalByScore(game, linescore = {}, allPlays = [], activePlay = null) {
  const status = game?.status && typeof game.status === 'object' ? game.status : {};
  const statusText = `${status.abstractGameState || ''} ${status.detailedState || ''} ${game?.status || ''}`.toLowerCase();
  if (/final|game over|completed/.test(statusText)) return true;
  const coded = String(status.codedGameState || status.statusCode || '').toUpperCase();
  return coded === 'F' || coded === 'O';
}

function ordinalForDisplay(linescore) {
  return linescore?.currentInningOrdinal || (Number.isFinite(linescore?.currentInning) ? `${linescore.currentInning}` : '-');
}

function inningDisplay(linescore, game, activePlay) {
  const unavailable = statusLine(game);
  if (/cancel|postpon|suspend|delay|makeup/i.test(unavailable)) return { short: unavailable, long: unavailable };
  if (!gameHasReachedOfficialStart(game)) return { short: 'PRE', long: `Starts ${gameStartTimeText(game)}` };
  const st = game?.status?.abstractGameState;
  if (st === 'Preview') return { short: 'PRE', long: `Starts ${gameStartTimeText(game)}` };
  if (st === 'Final') return { short: 'F', long: 'Final' };

  const rawOrdinal = ordinalForDisplay(linescore);
  const activeInning = Number(activePlay?.about?.inning);
  const lineInning = Number(linescore?.currentInning);
  const textInning = String(game?.inningShort || game?.inning || '').match(/(\d+)/)?.[1] || '';
  const ordinal = rawOrdinal && rawOrdinal !== '-'
    ? rawOrdinal
    : Number.isFinite(activeInning) && activeInning > 0
      ? String(activeInning)
      : Number.isFinite(lineInning) && lineInning > 0
        ? String(lineInning)
        : textInning || '1';
  const liveHalf = normalizeHalfInning(activePlay?.about?.halfInning);
  const stateHalf = normalizeHalfInning(linescore?.inningHalf || linescore?.inningState);
  const textHalf = normalizeHalfInning(game?.inningShort || game?.inning || game?.status?.detailedState || game?.status || '');
  let half = stateHalf || liveHalf || textHalf;
  if (!half && linescore?.isTopInning === true) half = 'top';
  if (!half && linescore?.isTopInning === false) half = 'bottom';

  if (half === 'top') return { short: `TOP ${ordinal}`, long: `Top ${ordinal}` };
  if (half === 'bottom') return { short: `BOT ${ordinal}`, long: `Bot ${ordinal}` };
  if (half === 'middle' || half === 'end') return { short: `MID ${ordinal}`, long: `Mid ${ordinal}` };

  const statusText = `${game?.status?.abstractGameState || ''} ${game?.status?.detailedState || ''} ${game?.status || ''}`;
  if (/live|in progress|warmup/i.test(statusText) || gameHasLiveProgressSignals(game)) {
    return { short: `TOP ${ordinal}`, long: `Top ${ordinal}` };
  }
  return { short: game?.status?.codedGameState === 'D' ? 'DEL' : 'PRE', long: `Starts ${gameStartTimeText(game)}` };
}

function countForGame(linescore, currentPlay) {
  const c = currentPlay?.count;
  if (c && Number.isInteger(c.balls)) {
    return { balls: c.balls, strikes: c.strikes ?? 0, outs: c.outs ?? linescore?.outs ?? 0 };
  }
  return { balls: linescore?.balls ?? 0, strikes: linescore?.strikes ?? 0, outs: linescore?.outs ?? 0 };
}

function playerById(players, id) {
  return players?.[`ID${id}`] || null;
}

function resolveCurrentSide(activePlay, linescore) {
  const liveHalf = normalizeHalfInning(activePlay?.about?.halfInning);
  const lineHalf = normalizeHalfInning(linescore?.inningHalf || linescore?.inningState);
  const lineHalfIsPlayable = lineHalf === 'top' || lineHalf === 'bottom';
  const liveHalfIsPlayable = liveHalf === 'top' || liveHalf === 'bottom';
  const half = lineHalfIsPlayable ? lineHalf : (liveHalfIsPlayable ? liveHalf : lineHalf);
  return {
    half,
    battingSide: half === 'bottom' ? 'home' : half === 'top' ? 'away' : '',
    fieldingSide: half === 'bottom' ? 'away' : half === 'top' ? 'home' : '',
  };
}

function linescorePitcherSnapshot(linescore) {
  const pitcher = linescore?.defense?.pitcher || linescore?.defense?.currentPitcher || null;
  const id = Number(pitcher?.id);
  return {
    pitcher: Number.isFinite(id) && id > 0 ? pitcher : null,
    pitcherId: Number.isFinite(id) && id > 0 ? id : null,
  };
}

function currentPeople(activePlay, linescore, game, awayPlayers, homePlayers) {
  const probableAway = game?.teams?.away?.probablePitcher;
  const probableHome = game?.teams?.home?.probablePitcher;

  let awayPitcher = formatPitcherLine(playerById(awayPlayers, probableAway?.id), probableAway?.fullName || '');
  let homePitcher = formatPitcherLine(playerById(homePlayers, probableHome?.id), probableHome?.fullName || '');
  let awayHitter = '-';
  let homeHitter = '-';

  const activePitcher = activePlay?.matchup?.pitcher;
  const activeBatter = activePlay?.matchup?.batter;
  const side = resolveCurrentSide(activePlay, linescore);
  const livePitcher = linescorePitcherSnapshot(linescore);
  const currentPitcherId = livePitcher.pitcherId || activePitcher?.id;
  const currentPitcherName = livePitcher.pitcher?.fullName || activePitcher?.fullName || '';
  const currentPitcherRosterSide = playerById(awayPlayers, currentPitcherId)
    ? 'away'
    : playerById(homePlayers, currentPitcherId)
      ? 'home'
      : '';
  const battingSide = currentPitcherRosterSide === 'away'
    ? 'home'
    : currentPitcherRosterSide === 'home'
      ? 'away'
      : side.battingSide;

  if (battingSide === 'away') {
    awayHitter = formatBatterLine(playerById(awayPlayers, activeBatter?.id), activeBatter?.fullName || '');
    homePitcher = formatPitcherLine(playerById(homePlayers, currentPitcherId), currentPitcherName);
  } else if (battingSide === 'home') {
    homeHitter = formatBatterLine(playerById(homePlayers, activeBatter?.id), activeBatter?.fullName || '');
    awayPitcher = formatPitcherLine(playerById(awayPlayers, currentPitcherId), currentPitcherName);
  }

  return { awayPitcher, homePitcher, awayHitter, homeHitter, battingSide, currentPitcherId };
}

function scoreboardHitterForSide(game, side) {
  if (hasLiveAtBat(game)) {
    const batterId = Number(game?.activeBatterId);
    const profile = Number.isFinite(batterId) && batterId > 0 ? game?.playerLookup?.[String(batterId)] || null : null;
    return profile || {
      id: batterId || null,
      fullName: side === 'away' ? game?.awayHitter : game?.homeHitter,
      name: side === 'away' ? game?.awayHitter : game?.homeHitter,
      batting: {},
    };
  }
  const lineup = fallbackTeamLineupFromLookup(game, side);
  const hitter = lineup.find((entry) => Number(entry?.slot) === 1) || lineup[0] || null;
  if (!hitter) return null;
  const profile = Number.isFinite(Number(hitter?.id)) ? game?.playerLookup?.[String(hitter.id)] || null : null;
  return profile ? { ...hitter, ...profile, avg: hitter.avg || profile?.batting?.avg || '---' } : hitter;
}

function scoreboardPitcherSideForLine(game, side) {
  if (!game) return '';
  if (shouldPreferProbablePitcher(game)) return side === 'home' ? 'home' : 'away';
  const battingSide = game?.battingSide || 'away';
  return side === battingSide ? '' : side;
}

function scoreboardHitterName(hitter) {
  if (!hitter) return '-';
  const fullName = cleanSummary(hitter.fullName || hitter.name || '');
  if (!fullName) return '-';
  const nameOnly = fullName.replace(/\s*\(.*$/, '').replace(/\s+AVG\b.*$/i, '').trim();
  return lastName(nameOnly || fullName);
}

function scoreboardHitterAvg(hitter) {
  const raw = cleanSummary(hitter?.batting?.avg || hitter?.avg || '');
  return raw && raw !== '---' ? raw : '---';
}

function scoreboardHitterHr(hitter) {
  return statNumber(hitter?.batting?.hr ?? hitter?.batting?.homeRuns ?? hitter?.homeRuns);
}

function scoreboardPitcherEra(pitcher) {
  const raw = cleanSummary(pitcher?.pitching?.era || pitcher?.era || '');
  return raw && raw !== '---' ? raw : '---';
}

function scoreboardPitcherName(pitcher) {
  const fullName = cleanSummary(pitcher?.fullName || pitcher?.name || '');
  const nameOnly = fullName.replace(/\s+\(P\d+\).*$/i, '').replace(/\s+\d+P\b.*$/i, '').trim();
  if (!nameOnly) return '-';
  const shortName = /^TBD$/i.test(nameOnly) ? 'TBD' : lastName(nameOnly);
  return pitcher?.isTbdFallbackStarter && shortName !== 'TBD' ? `TBD ${shortName}` : shortName;
}

function hasLiveAtBat(game) {
  if (shouldPreferProbablePitcher(game)) return false;
  if (isCompletedGameCard(game)) return false;
  return Number.isFinite(Number(game?.activeBatterId)) && Number(game.activeBatterId) > 0;
}

function matchupLineForSide(game, side) {
  if (shouldPreferProbablePitcher(game)) {
    const pitcher = scoreboardPitcherForSide(game, side);
    const pitcherName = scoreboardPitcherName(pitcher);
    const pitchTag = pitchCountTag(pitcher);
    return pitcherName === '-' ? 'Probable pitcher pending' : `${pitcherName}${pitchTag ? ` ${pitchTag}` : ''}${handednessSuffixText(pitcherThrowHandValue(pitcher))} ERA ${scoreboardPitcherEra(pitcher)}`;
  }
  const battingSide = game?.battingSide || 'away';
  if (side === battingSide) {
    const hitter = scoreboardHitterForSide(game, battingSide);
    const hitterName = scoreboardHitterName(hitter);
    if (hitterName === '-') return 'Hitter pending';
    return `${hitterName}${handednessSuffixText(hitter?.bats || hitter?.batSide?.code || hitter?.batSide?.description)} AVG ${scoreboardHitterAvg(hitter)} ${scoreboardHitterHr(hitter)} HR`;
  }
  const pitcher = scoreboardPitcherForSide(game, side);
  const pitcherName = scoreboardPitcherName(pitcher);
  const pitchTag = pitchCountTag(pitcher);
  return pitcherName === '-' ? 'Pitcher pending' : `${pitcherName}${pitchTag ? ` ${pitchTag}` : ''}${handednessSuffixText(pitcherThrowHandValue(pitcher))} ERA ${scoreboardPitcherEra(pitcher)}`;
}

function scoreboardPitcherForSide(game, side) {
  if (!game) return null;
  const pitcherSide = scoreboardPitcherSideForLine(game, side);
  if (!pitcherSide) return null;
  const display = resolvePitchingSideForDisplay(game, pitcherSide);
  const previewProbable = shouldPreferProbablePitcher(game) ? previewProbableForSide(game, pitcherSide) : null;
  let pitcher = (shouldPreferProbablePitcher(game)
    ? previewProbable
      || game?.probablePitchers?.[pitcherSide]
      || game?.teams?.[pitcherSide]?.probablePitcher
      || display?.current
      || display?.starter
      || game?.pitching?.[pitcherSide]?.current
      || null
    : display?.current
      || game?.pitching?.[pitcherSide]?.current
      || game?.probablePitchers?.[pitcherSide]
      || game?.teams?.[pitcherSide]?.probablePitcher)
    || null;
  pitcher = visualTbdFallbackForPitcher(pitcher, game, 'starter') || pitcher;
  const profile = pitcher?.id ? game?.playerLookup?.[String(pitcher.id)] || null : null;
  return profile ? {
    ...pitcher,
    ...profile,
    isTbdFallbackStarter: Boolean(pitcher?.isTbdFallbackStarter),
    fallbackStarter: pitcher?.fallbackStarter || profile?.fallbackStarter,
    tbdPrimaryName: pitcher?.tbdPrimaryName || profile?.tbdPrimaryName,
    role: pitcher?.role || profile?.role,
  } : pitcher;
}

function renderScoreboardMatchupLine(el, game, side) {
  if (!el) return;
  const text = matchupLineForSide(game, side);
  const pitcher = scoreboardPitcherForSide(game, side);
  const pitcherId = Number(pitcher?.id);
  const markerId = Number.isFinite(pitcherId) && pitcherId > 0 ? String(pitcherId) : '';
  const width = Math.round(el.clientWidth || 0);
  const riskHtml = markerId ? `${pitcherHomeRunRiskMarkerHtml(pitcher)}${pitcherWhipRiskMarkerHtml(pitcher)}` : '';
  const signature = JSON.stringify([text, markerId, width, riskHtml]);
  const hasExpectedPitcherMarker = !markerId || Boolean(el.querySelector(`.pitcher-fire-streak[data-pitcher-fire-id="${markerId}"]`));
  const riskCount = (riskHtml.match(/class="pitcher-/g) || []).length;
  const hasExpectedRiskMarkers = !riskCount || el.querySelectorAll('.pitcher-hr-risk, .pitcher-whip-risk').length === riskCount;
  if (el.dataset.scoreboardMatchupSignature === signature && hasExpectedPitcherMarker && hasExpectedRiskMarkers) return;
  const forceRender = el.dataset.scoreboardPitcherId !== markerId || Number(el.dataset.renderWidth || 0) !== width;
  if (forceRender) {
    el.dataset.renderMode = '';
    el.dataset.renderValue = '';
  }
  renderSingleLineMarquee(el, text);
  el.dataset.scoreboardPitcherId = markerId;
  el.dataset.scoreboardMatchupSignature = signature;
  el.querySelectorAll('.pitcher-fire-streak, .pitcher-cold-streak, .pitcher-hr-risk, .pitcher-whip-risk').forEach((marker) => marker.remove());
  if (!markerId) return;
  const markerWrap = document.createElement('span');
  const track = el.querySelector('.marquee-track');
  const target = track || el;
  markerWrap.innerHTML = pitcherFireMarkerHtml(markerId);
  const marker = markerWrap.firstElementChild;
  if (marker) target.appendChild(marker);
  const riskWrap = document.createElement('span');
  riskWrap.innerHTML = riskHtml;
  for (const riskMarker of Array.from(riskWrap.children)) {
    target.appendChild(riskMarker);
  }
}

function baseRunnerState(runner, battingSide = '', game = null) {
  if (!runner) return null;
  const id = Number(runner?.id ?? runner?.person?.id ?? runner?.player?.id);
  const profile = Number.isFinite(id) && id > 0 ? game?.playerLookup?.[String(id)] || null : null;
  const fullName = cleanSummary(
    profile?.fullName
      || runner?.fullName
      || runner?.person?.fullName
      || runner?.player?.fullName
      || runner?.name
      || '',
  );
  const side = battingSide === 'home' || battingSide === 'away' ? battingSide : '';
  return {
    id: Number.isFinite(id) && id > 0 ? id : null,
    fullName,
    name: lastName(fullName) || 'Runner',
    side,
    color: side === 'home' ? (game?.homeColor || getTeamColor(game?.home)) : side === 'away' ? (game?.awayColor || getTeamColor(game?.away)) : '#ffd166',
  };
}

function baseState(linescore, game = null, activePlay = null) {
  const o = linescore?.offense || {};
  const battingSide = resolveCurrentSide(activePlay, linescore).battingSide || game?.battingSide || '';
  return {
    first: baseRunnerState(o.first, battingSide, game),
    second: baseRunnerState(o.second, battingSide, game),
    third: baseRunnerState(o.third, battingSide, game),
  };
}

function parseHrNumber(description) {
  const m = description?.match(/(\d+)(st|nd|rd|th)\s+home run/i);
  if (m) return Number(m[1]);
  const parenthetical = description?.match(/\bhomers?\s*\((\d+)\)/i);
  return parenthetical ? Number(parenthetical[1]) : null;
}

function homeRunResultLabel(play, isWalkOff = false) {
  const rbi = Number(play?.result?.rbi);
  const prefix = isWalkOff ? 'Walkoff ' : '';
  if (rbi >= 4) return `${prefix}Grand Slam`;
  if (rbi === 3) return `${prefix}Three Run Homerun`;
  if (rbi === 2) return `${prefix}2 Run Homerun`;
  if (rbi === 1) return `${prefix}Solo Homerun`;
  const description = String(play?.result?.description || '').toLowerCase();
  if (description.includes('grand slam')) return `${prefix}Grand Slam`;
  if (description.includes('three-run') || description.includes('3-run')) return `${prefix}Three Run Homerun`;
  if (description.includes('two-run') || description.includes('2-run')) return `${prefix}2 Run Homerun`;
  if (description.includes('solo')) return `${prefix}Solo Homerun`;
  return `${prefix}Homerun`;
}

function ordinalInningNumber(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return '';
  const suffix = n % 100 >= 11 && n % 100 <= 13 ? 'th' : (n % 10 === 1 ? 'st' : n % 10 === 2 ? 'nd' : n % 10 === 3 ? 'rd' : 'th');
  return `${n}${suffix}`;
}

function formatHrInningText(play) {
  const half = normalizeHalfInning(play?.about?.halfInning);
  const inning = ordinalInningNumber(play?.about?.inning);
  if (!half && !inning) return '';
  return `${half === 'top' ? 'Top' : half === 'bottom' ? 'Bot' : cleanSummary(play?.about?.halfInning || '')} ${inning}`.trim();
}

function homeRunRunsScored(play) {
  const rbi = Number(play?.result?.rbi);
  if (Number.isFinite(rbi) && rbi > 0) return Math.min(4, Math.max(1, Math.round(rbi)));
  const label = homeRunResultLabel(play).toLowerCase();
  if (label.includes('grand')) return 4;
  if (label.includes('three')) return 3;
  if (label.includes('2') || label.includes('two')) return 2;
  return 1;
}

function homeRunInningPoints(inning) {
  const n = Number(inning);
  if (!Number.isFinite(n) || n <= 0) return 10;
  if (n <= 3) return 10;
  if (n === 4) return 30;
  if (n === 5) return 45;
  if (n === 6) return 60;
  if (n === 7) return 75;
  if (n === 8) return 95;
  if (n === 9) return 115;
  return 120;
}

function homeRunRunsPoints(runs) {
  if (runs >= 4) return 150;
  if (runs === 3) return 115;
  if (runs === 2) return 75;
  return 35;
}

function homeRunDistancePoints(distance) {
  const feet = Number(distance);
  if (!Number.isFinite(feet)) return 0;
  if (feet < 360) return 10;
  if (feet < 380) return 25;
  if (feet < 400) return 40;
  if (feet < 420) return 60;
  if (feet < 440) return 75;
  if (feet < 460) return 88;
  return 100;
}

function pitcherDifficultyDetails(profile) {
  if (!profile) {
    return {
      points: 0,
      hr9: null,
      ip: null,
      base: 0,
      multiplier: 0,
    };
  }
  const ipOuts = inningsToOuts(profile?.pitching?.ip ?? profile?.ip ?? profile?.seasonStats?.pitching?.inningsPitched);
  const ip = ipOuts > 0 ? ipOuts / 3 : 0;
  const hrAllowed = pitcherHomeRunsAllowed(profile);
  const hr9 = ip > 0 ? (hrAllowed * 9) / ip : Number.POSITIVE_INFINITY;
  const base = hr9 <= 0.40 ? 200
    : hr9 <= 0.70 ? 175
      : hr9 <= 1.00 ? 140
        : hr9 <= 1.30 ? 100
          : hr9 <= 1.70 ? 60
            : 25;
  const multiplier = ip < 20 ? 0.45
    : ip < 40 ? 0.65
      : ip < 70 ? 0.80
        : ip < 110 ? 0.95
          : 1;
  return {
    points: base * multiplier,
    hr9: Number.isFinite(hr9) ? hr9 : null,
    ip,
    base,
    multiplier,
  };
}

function pitcherDifficultyPoints(profile) {
  return pitcherDifficultyDetails(profile).points;
}

function homeRunResultPoints(play, battingSide) {
  const runs = homeRunRunsScored(play);
  const beforeAway = Number(play?.result?.awayScore) - (battingSide === 'away' ? runs : 0);
  const beforeHome = Number(play?.result?.homeScore) - (battingSide === 'home' ? runs : 0);
  const afterAway = Number(play?.result?.awayScore);
  const afterHome = Number(play?.result?.homeScore);
  if (![beforeAway, beforeHome, afterAway, afterHome].every(Number.isFinite)) return 20;
  const beforeBatting = battingSide === 'away' ? beforeAway : beforeHome;
  const beforeOpponent = battingSide === 'away' ? beforeHome : beforeAway;
  const afterBatting = battingSide === 'away' ? afterAway : afterHome;
  const afterOpponent = battingSide === 'away' ? afterHome : afterAway;
  if (beforeBatting > beforeOpponent && afterBatting > afterOpponent) return 20;
  if (afterBatting < afterOpponent) return 60;
  if (afterBatting === afterOpponent) return 110;
  if (beforeBatting === beforeOpponent && afterBatting > afterOpponent) return 140;
  if (beforeBatting < beforeOpponent && afterBatting > afterOpponent) return 180;
  return 20;
}

function homeRunWalkOffPoints(play, battingSide) {
  const description = `${play?.result?.description || ''} ${play?.result?.event || ''}`;
  const runs = homeRunRunsScored(play);
  const inning = Number(play?.about?.inning);
  const afterAway = Number(play?.result?.awayScore);
  const afterHome = Number(play?.result?.homeScore);
  const beforeHome = afterHome - (battingSide === 'home' ? runs : 0);
  const isBottomWalkOffScore = battingSide === 'home'
    && Number.isFinite(inning)
    && inning >= 9
    && Number.isFinite(afterAway)
    && Number.isFinite(afterHome)
    && Number.isFinite(beforeHome)
    && beforeHome <= afterAway
    && afterHome > afterAway;
  const isWalkOff = Boolean(play?.about?.isWalkOff || play?.result?.isWalkOff || /walk-?off/i.test(description) || isBottomWalkOffScore);
  if (!isWalkOff) return 0;
  const beforeAway = Number(play?.result?.awayScore) - (battingSide === 'away' ? runs : 0);
  const beforeHomeScore = Number(play?.result?.homeScore) - (battingSide === 'home' ? runs : 0);
  if (!Number.isFinite(beforeAway) || !Number.isFinite(beforeHomeScore)) return 180;
  const beforeBatting = battingSide === 'away' ? beforeAway : beforeHomeScore;
  const beforeOpponent = battingSide === 'away' ? beforeHomeScore : beforeAway;
  if (runs >= 4 && beforeBatting < beforeOpponent) return 250;
  if (beforeBatting < beforeOpponent) return 230;
  return 180;
}

function isWalkOffHomeRunByPlayHistory(play, allPlays = [], battingSide = '') {
  if (play?.about?.isWalkOff || play?.result?.isWalkOff) return true;
  const description = `${play?.result?.description || ''} ${play?.result?.event || ''}`;
  if (/walk-?off/i.test(description)) return true;
  const half = normalizeHalfInning(play?.about?.halfInning);
  const inning = Number(play?.about?.inning);
  const runs = homeRunRunsScored(play);
  const afterAway = Number(play?.result?.awayScore);
  const afterHome = Number(play?.result?.homeScore);
  const beforeHome = afterHome - (battingSide === 'home' ? runs : 0);
  if (
    battingSide !== 'home'
    || half !== 'bottom'
    || !Number.isFinite(inning)
    || inning < 9
    || !Number.isFinite(afterAway)
    || !Number.isFinite(afterHome)
    || !Number.isFinite(beforeHome)
    || beforeHome > afterAway
    || afterHome <= afterAway
  ) return false;
  const atBatIndex = Number(play?.about?.atBatIndex);
  if (!Number.isFinite(atBatIndex)) return true;
  return !(allPlays || []).some((candidate) => (
    Number(candidate?.about?.atBatIndex) > atBatIndex
    && candidate?.matchup?.batter?.id
    && candidate?.matchup?.pitcher?.id
    && candidate?.about?.isComplete !== false
  ));
}

function homeRunRatingBreakdown(play, pitcherProfile, distance, battingSide) {
  const pitcherDifficulty = pitcherDifficultyDetails(pitcherProfile);
  const runsScored = homeRunRunsScored(play);
  const walkOff = homeRunWalkOffPoints(play, battingSide);
  const inning = homeRunInningPoints(play?.about?.inning);
  const result = homeRunResultPoints(play, battingSide);
  const runs = homeRunRunsPoints(runsScored);
  const distancePoints = homeRunDistancePoints(distance);
  const score = walkOff + inning + result + runs + pitcherDifficulty.points + distancePoints;
  return {
    score: Math.round(Math.max(0, Math.min(1000, score))),
    walkOff,
    inning,
    result,
    runs,
    pitcher: pitcherDifficulty.points,
    distance: distancePoints,
    runsScored,
    inningText: formatHrInningText(play),
    distanceFeet: Number.isFinite(Number(distance)) ? Number(distance) : null,
    pitcherHr9: pitcherDifficulty.hr9,
    pitcherIp: pitcherDifficulty.ip,
    pitcherBase: pitcherDifficulty.base,
    pitcherMultiplier: pitcherDifficulty.multiplier,
  };
}

function homeRunRating(play, pitcherProfile, distance, battingSide) {
  const { score } = homeRunRatingBreakdown(play, pitcherProfile, distance, battingSide);
  return Math.round(Math.max(0, Math.min(1000, score)));
}

function positiveStatNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : null;
}

function lookupPlayerSeasonHomeRuns(playerId, lookup = {}) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const profile = lookup[String(id)] || lookup[`ID${id}`] || null;
  return positiveStatNumber(profile?.batting?.hr ?? profile?.batting?.homeRuns ?? profile?.seasonStats?.batting?.homeRuns);
}

async function getPlayerSeasonHomeRuns(playerId, season) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const normalizedSeason = seasonForDate(season || (dateInput.value || formatDate(new Date())));
  const cacheKey = `${id}:${normalizedSeason}:hr`;
  if (playerSeasonHomeRunCache.has(cacheKey)) return playerSeasonHomeRunCache.get(cacheKey);

  const promise = getPlayerSeasonStats(id, 'hitting', normalizedSeason)
    .then((response) => positiveStatNumber(statSplit(response)?.homeRuns))
    .catch((error) => {
      playerSeasonHomeRunCache.delete(cacheKey);
      throw error;
    });
  playerSeasonHomeRunCache.set(cacheKey, promise);
  return promise;
}

function deriveSlotFromOrder(order) {
  const num = Number(order);
  if (!Number.isFinite(num) || num <= 0) return null;
  return Math.floor(num / 100) || num;
}

function numericPlayerId(value) {
  const direct = Number(value);
  if (Number.isFinite(direct)) return direct;
  const match = String(value || '').match(/(\d{4,})/);
  return match ? Number(match[1]) : NaN;
}

function shortPosition(player) {
  return player?.position?.abbreviation || player?.position?.code || player?.allPositions?.[0]?.abbreviation || '';
}

function buildLineup(players, activeBatterId, battingOrderIds = [], nextBatterId = null) {
  const bySlot = new Map();
  const substitutionsBySlot = new Map();
  const byId = new Map(
    Object.values(players || {})
      .map((player) => [Number(player?.person?.id), player])
      .filter(([id]) => Number.isFinite(id)),
  );

  if (Array.isArray(battingOrderIds) && battingOrderIds.length && battingOrderIds.length <= 9) {
    for (let i = 0; i < battingOrderIds.length; i += 1) {
      const id = numericPlayerId(battingOrderIds[i]);
      if (!Number.isFinite(id)) continue;
      const player = byId.get(id);
      if (!player) continue;
      bySlot.set(i + 1, player);
    }
  }

  for (const player of Object.values(players || {})) {
    const slot = deriveSlotFromOrder(player?.battingOrder);
    if (!slot) continue;
    if (!substitutionsBySlot.has(slot)) substitutionsBySlot.set(slot, []);
    substitutionsBySlot.get(slot).push(player);
    const existing = bySlot.get(slot);
    const currentOrder = Number(player?.battingOrder) || 0;
    const existingOrder = Number(existing?.battingOrder) || 0;
    if (!existing || currentOrder >= existingOrder) {
      bySlot.set(slot, player);
    }
  }

  return [...bySlot.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([slot, player]) => {
      const slotPlayers = (substitutionsBySlot.get(slot) || [player])
        .slice()
        .sort((a, b) => (Number(a?.battingOrder) || 0) - (Number(b?.battingOrder) || 0));
      const starter = slotPlayers[0] || player;
      const hasSubstitution = Number(starter?.person?.id) !== Number(player?.person?.id);
      const currentGameBatting = lineupGameBattingStatsFromPlayer(player);
      const slotGameBatting = hasSubstitution ? combineLineupGameBattingStats(slotPlayers) : currentGameBatting;
      const substitutionPlayers = hasSubstitution ? slotPlayers.map((slotPlayer) => {
        const playerGameBatting = lineupGameBattingStatsFromPlayer(slotPlayer);
        return {
          id: slotPlayer?.person?.id ?? null,
          name: lastName(slotPlayer?.person?.fullName || slotPlayer?.person?.lastName || 'Unknown'),
          fullName: slotPlayer?.person?.fullName || 'Unknown',
          position: shortPosition(slotPlayer),
          bats: slotPlayer?.person?.batSide?.code || slotPlayer?.batSide?.code || slotPlayer?.batSide?.description || '',
          avg: battingAverage(slotPlayer),
          today: battingTodaySummaryFromGameStats(playerGameBatting),
          gameBatting: playerGameBatting,
          source: 'mlb-boxscore-lineup',
        };
      }) : [];
      return {
        slot,
        id: player?.person?.id ?? null,
        name: lastName(player?.person?.fullName || player?.person?.lastName || 'Unknown'),
        fullName: player?.person?.fullName || 'Unknown',
        position: shortPosition(player),
        bats: player?.person?.batSide?.code || player?.batSide?.code || player?.batSide?.description || '',
        throws: player?.person?.pitchHand?.code || player?.pitchHand?.code || player?.pitchHand?.description || '',
        avg: battingAverage(player),
        today: hasSubstitution ? battingTodaySummaryFromGameStats(slotGameBatting) : battingTodaySummary(player),
        substitutionLineToday: battingTodaySummaryFromGameStats(currentGameBatting),
        gameBatting: slotGameBatting,
        batting: player?.seasonStats?.batting || {},
        isActive: Number(player?.person?.id) === Number(activeBatterId),
        isNextUp: Number(player?.person?.id) === Number(nextBatterId),
        source: 'mlb-boxscore-lineup',
        substitutionStarter: hasSubstitution ? substitutionPlayers[0] : null,
        substitutionPlayers,
      };
    });
}

function buildStartingLineupFromBoxscore(players, battingOrderIds = []) {
  const startersBySlot = new Map();
  for (const player of Object.values(players || {})) {
    const slot = deriveSlotFromOrder(player?.battingOrder);
    if (!slot) continue;
    const existing = startersBySlot.get(slot);
    const order = Number(player?.battingOrder) || 0;
    const existingOrder = Number(existing?.battingOrder) || 0;
    if (!existing || order < existingOrder) startersBySlot.set(slot, player);
  }
  if (!startersBySlot.size && Array.isArray(battingOrderIds)) {
    const byId = new Map(
      Object.values(players || {})
        .map((player) => [Number(player?.person?.id), player])
        .filter(([id]) => Number.isFinite(id)),
    );
    battingOrderIds.slice(0, 9).forEach((value, index) => {
      const player = byId.get(numericPlayerId(value));
      if (player) startersBySlot.set(index + 1, player);
    });
  }
  return [...startersBySlot.entries()]
    .sort((a, b) => a[0] - b[0])
    .slice(0, 9)
    .map(([slot, player]) => ({
      slot,
      id: player?.person?.id ?? null,
      name: lastName(player?.person?.fullName || player?.person?.lastName || 'Unknown'),
      fullName: player?.person?.fullName || 'Unknown',
      position: shortPosition(player),
      bats: player?.person?.batSide?.code || player?.batSide?.code || player?.batSide?.description || '',
      throws: player?.person?.pitchHand?.code || player?.pitchHand?.code || player?.pitchHand?.description || '',
      avg: battingAverage(player),
      today: '0-0',
      gameBatting: {},
      batting: player?.seasonStats?.batting || {},
      isActive: false,
      isNextUp: false,
      substitutionStarter: null,
      source: 'mlb-previous-boxscore',
    }));
}

function battingSideForPlay(play) {
  const half = normalizeHalfInning(play?.about?.halfInning);
  return half === 'top' ? 'away' : half === 'bottom' ? 'home' : '';
}

function nextBatterIdFromOrder(orderIds = [], lastBatterId = null) {
  const order = listify(orderIds)
    .map(numericPlayerId)
    .filter((id) => Number.isFinite(id) && id > 0);
  if (!order.length) return null;
  const last = Number(lastBatterId);
  if (!Number.isFinite(last) || last <= 0) return order[0];
  const index = order.findIndex((id) => Number(id) === last);
  return index >= 0 ? order[(index + 1) % order.length] : order[0];
}

function nextBatterIdsFromPlayLog(allPlays = [], awayOrder = [], homeOrder = []) {
  const lastBySide = { away: null, home: null };
  for (const play of listify(allPlays)) {
    if (!play?.about?.isComplete) continue;
    const side = battingSideForPlay(play);
    const batterId = Number(play?.matchup?.batter?.id);
    if (!side || !Number.isFinite(batterId) || batterId <= 0) continue;
    lastBySide[side] = batterId;
  }
  return {
    away: nextBatterIdFromOrder(awayOrder, lastBySide.away),
    home: nextBatterIdFromOrder(homeOrder, lastBySide.home),
  };
}

function nextBatterIdsForLiveState(allPlays = [], awayOrder = [], homeOrder = [], activePlay = null, battingSide = '') {
  const next = nextBatterIdsFromPlayLog(allPlays, awayOrder, homeOrder);
  const activeBatterId = Number(activePlay?.matchup?.batter?.id);
  const activeSide = battingSideForPlay(activePlay) || (battingSide === 'away' || battingSide === 'home' ? battingSide : '');
  if (activeSide && Number.isFinite(activeBatterId) && activeBatterId > 0) {
    next[activeSide] = nextBatterIdFromOrder(activeSide === 'away' ? awayOrder : homeOrder, activeBatterId);
  }
  return next;
}


function buildBench(players, lineup) {
  const lineupIds = new Set();
  for (const entry of lineup || []) {
    [entry, entry?.substitutionStarter, ...(Array.isArray(entry?.substitutionPlayers) ? entry.substitutionPlayers : [])]
      .map((value) => Number(value?.id))
      .filter(Number.isFinite)
      .forEach((id) => lineupIds.add(id));
  }
  return Object.values(players || {})
    .filter((player) => !isPitcherOnlyPlayer(player))
    .filter((player) => !lineupIds.has(Number(player?.person?.id)))
    .map((player) => ({
      id: player?.person?.id ?? null,
      name: lastName(player?.person?.fullName || player?.person?.lastName || 'Unknown'),
      fullName: player?.person?.fullName || 'Unknown',
      position: shortPosition(player),
      bats: player?.person?.batSide?.code || player?.batSide?.code || player?.batSide?.description || '',
      throws: player?.person?.pitchHand?.code || player?.pitchHand?.code || player?.pitchHand?.description || '',
      avg: battingAverage(player),
      today: battingTodaySummary(player),
      gameBatting: lineupGameBattingStats({ gameBatting: player?.stats?.batting || {} }),
      batting: player?.seasonStats?.batting || {},
    }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

function isPitcherPlayer(player) {
  const primary = String(shortPosition(player) || '').toUpperCase();
  if (primary === 'P') return true;
  return Array.isArray(player?.allPositions)
    && player.allPositions.some((pos) => String(pos?.abbreviation || pos?.code || '').toUpperCase() === 'P');
}

function playerHasBattingEvidence(player = {}) {
  if (deriveSlotFromOrder(player?.battingOrder)) return true;
  const batting = player?.stats?.batting || player?.seasonStats?.batting || player?.batting || player?.gameBatting || {};
  return [
    batting.atBats,
    batting.hits,
    batting.homeRuns,
    batting.doubles,
    batting.triples,
    batting.rbi,
    batting.runs,
    batting.baseOnBalls,
    batting.walks,
    batting.gamesPlayed,
    batting.games,
  ].some((value) => statNumber(value) > 0);
}

function isPitcherOnlyPlayer(player) {
  return isPitcherPlayer(player) && !playerHasBattingEvidence(player);
}

function buildPitcherEntry(player, forceActive = false, role = 'current') {
  if (!player) return null;
  return {
    id: player?.person?.id ?? null,
    name: lastName(player?.person?.fullName || player?.person?.lastName || 'Unknown'),
    fullName: player?.person?.fullName || 'Unknown',
    ip: pitcherInningsPitched(player),
    era: pitcherEra(player),
    whip: pitcherWhip(player),
    hrAllowed: pitcherHomeRunsAllowed(player),
    gs: pitcherGamesStarted(player),
    gp: pitcherGamesPlayed(player),
    gf: pitcherGamesFinished(player),
    saves: pitcherSaveCount(player),
    so: pitcherStrikeoutCount(player),
    throws: player?.throws || player?.person?.pitchHand?.code || player?.pitchHand?.code || player?.pitchHand?.description || '',
    today: pitcherTodaySummary(player),
    pitches: pitchCount(player),
    isActive: forceActive,
    role,
  };
}

function starterCandidateFromPitchers(allPitchers, probablePitcher, pitcherOrder = []) {
  if (!Array.isArray(allPitchers) || !allPitchers.length) return null;
  if (probablePitcher?.id) {
    const probableMatch = allPitchers.find((player) => Number(player?.person?.id) === Number(probablePitcher.id));
    if (probableMatch) return probableMatch;
  }

  const orderedIds = Array.isArray(pitcherOrder) ? pitcherOrder.map((id) => Number(id)).filter(Number.isFinite) : [];
  for (const pitcherId of orderedIds) {
    const orderedMatch = allPitchers.find((player) => Number(player?.person?.id) === pitcherId);
    if (orderedMatch) return orderedMatch;
  }

  const byWorkload = [...allPitchers]
    .map((player) => ({
      player,
      seasonOuts: inningsToOuts(player?.seasonStats?.pitching?.inningsPitched),
      outs: inningsToOuts(player?.stats?.pitching?.inningsPitched),
      pitches: pitchCount(player),
    }))
    .sort((a, b) => {
      if (b.seasonOuts !== a.seasonOuts) return b.seasonOuts - a.seasonOuts;
      if (b.outs !== a.outs) return b.outs - a.outs;
      if (b.pitches !== a.pitches) return b.pitches - a.pitches;
      return String(a.player?.person?.fullName || '').localeCompare(String(b.player?.person?.fullName || ''));
    });
  if (byWorkload[0]?.player) return byWorkload[0].player;

  return allPitchers[0] || null;
}

function buildPitchingStaff(players, activePitcherId, probablePitcher, pitcherOrder = []) {
  const allPitchers = Object.values(players || {}).filter(isPitcherPlayer);
  const activeNumericId = Number(activePitcherId);
  const activePlayer = Number.isFinite(activeNumericId) ? allPitchers.find((player) => Number(player?.person?.id) === activeNumericId) : null;
  let current = buildPitcherEntry(activePlayer, true, 'current');
  const starterPlayer = starterCandidateFromPitchers(allPitchers, probablePitcher, pitcherOrder);

  if (!current && probablePitcher?.id) {
    const probablePlayer = allPitchers.find((player) => Number(player?.person?.id) === Number(probablePitcher.id));
    current = buildPitcherEntry(probablePlayer, true, 'starter') || {
      id: probablePitcher.id,
      name: lastName(probablePitcher.fullName || 'Unknown'),
      fullName: probablePitcher.fullName || 'Unknown',
      ip: '0.0',
      era: '---',
      whip: '---',
      hrAllowed: 0,
      throws: probablePitcher.pitchHand?.code || probablePitcher.pitchHand?.description || '',
      today: 'Not in yet',
      pitches: 0,
      isActive: true,
      role: 'starter',
    };
  }
  if (!current && starterPlayer) {
    current = buildPitcherEntry(starterPlayer, true, 'starter');
  }

  const bullpen = allPitchers
    .filter((player) => Number(player?.person?.id) !== Number(current?.id))
    .map((player) => buildPitcherEntry(player, false, 'bullpen'))
    .filter(Boolean)
    .sort((a, b) => {
      const aToday = a.today !== 'Unused today' ? 1 : 0;
      const bToday = b.today !== 'Unused today' ? 1 : 0;
      if (bToday !== aToday) return bToday - aToday;
      if (b.pitches !== a.pitches) return b.pitches - a.pitches;
      return a.name.localeCompare(b.name);
    });

  return { current, bullpen };
}

function latestBoxscorePitcherEntry(boxscore, side) {
  const team = boxscore?.teams?.[side] || {};
  const players = team?.players || {};
  const ordered = Array.isArray(team?.pitchers) ? team.pitchers : [];
  for (let i = ordered.length - 1; i >= 0; i -= 1) {
    const id = numericPlayerId(ordered[i]);
    if (!Number.isFinite(id) || id <= 0) continue;
    const player = players[`ID${id}`];
    if (!player) continue;
    const entry = buildPitcherEntry(player, true, 'current');
    if (entry) return entry;
  }
  return null;
}

function pitchingWithLatestBoxscoreSnapshot(pitching, boxscore, allPlays = []) {
  const next = {
    away: { ...(pitching?.away || { current: null, bullpen: [] }) },
    home: { ...(pitching?.home || { current: null, bullpen: [] }) },
  };
  for (const side of ['away', 'home']) {
    const current = latestBoxscorePitcherEntry(boxscore, side);
    next[side] = {
      ...next[side],
      current: current || next[side].current || null,
      history: pitcherAppearanceHistoryForSide(boxscore, side, allPlays),
    };
  }
  return next;
}

async function fetchTeamPitcherRosterProfiles(teamAbbrev, game, options = {}) {
  const selectedDate = officialDateForGame(game);
  const team = await getTeamByAbbrev(teamAbbrev, selectedDate).catch(() => null);
  const teamId = Number(team?.id);
  if (!Number.isFinite(teamId)) return [];
  const season = seasonForDate(selectedDate);
  const rosterType = cleanSummary(options.rosterType || 'active') || 'active';
  const cacheKey = `${teamId}:${season}:${selectedDate}:${rosterType}`;
  if (teamPitcherRosterCache.has(cacheKey)) return teamPitcherRosterCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/teams/${teamId}/roster`);
    url.searchParams.set('rosterType', rosterType);
    url.searchParams.set('season', String(season));
    const roster = await getJson(url.toString());
    const pitcherEntries = listify(roster?.roster)
      .filter((entry) => String(entry?.position?.abbreviation || entry?.position?.code || '').toUpperCase() === 'P');
    const entryById = new Map(pitcherEntries
      .map((entry) => [Number(entry?.person?.id), entry])
      .filter(([id]) => Number.isFinite(id) && id > 0));
    const pitcherIds = [...entryById.keys()];
    const profiles = await Promise.all(
      [...new Set(pitcherIds)].map(async (id) => {
        const profile = await fetchMlbPlayerProfile(id, game, { role: 'pitcher', allowFirstAppearanceFallback: false }).catch(() => null);
        const rosterEntry = entryById.get(id) || {};
        return profile ? {
          ...profile,
          status: profile.status || rosterEntry?.status || rosterEntry?.person?.status || {},
          rosterStatus: rosterEntry?.status?.description || rosterEntry?.status?.code || '',
        } : null;
      }),
    );
    return profiles.filter(Boolean);
  })().catch((error) => {
    teamPitcherRosterCache.delete(cacheKey);
    throw error;
  });
  teamPitcherRosterCache.set(cacheKey, promise);
  return promise;
}

function pitcherUsedInGame(entry) {
  if (!entry) return false;
  const today = cleanSummary(entry?.today || entry?.todayPitching || '');
  if (inningsToOuts(entry?.ip || entry?.innings || entry?.inningsText || entry?.pitching?.ip || entry?.stats?.pitching?.inningsPitched) > 0) return true;
  if (Number(entry?.pitches || entry?.pitchCount || entry?.stats?.pitching?.numberOfPitches || 0) > 0) return true;
  return /\b\d+(?:\.\d)?\s*IP\b/i.test(today) || /\b\d+\s*(?:P|pitches)\b/i.test(today);
}

function pitcherUsageIdsForArchivedSide(staff) {
  const ids = new Set();
  const add = (entry) => {
    const id = Number(entry?.id ?? entry?.person?.id ?? entry?.playerId);
    if (Number.isFinite(id) && pitcherUsedInGame(entry)) ids.add(id);
  };
  add(staff?.current);
  add(staff?.starter);
  for (const arm of listify(staff?.bullpen)) add(arm);
  for (const arm of listify(staff?.history)) add(arm);
  return ids;
}

function pitcherUsedYesterdayIdsForTeam(game, teamAbbrev) {
  const selectedDate = officialDateForGame(game);
  const [yesterday] = recentCalendarDateWindow(selectedDate, 2);
  if (!yesterday || yesterday === selectedDate) return new Set();
  const team = canonicalTeamAbbrev(teamAbbrev || '');
  const ids = new Set();
  for (const archived of getArchivedGames(yesterday).map(normalizeCompletedCard)) {
    const side = sameTeamAbbrev(archived?.away, team)
      ? 'away'
      : sameTeamAbbrev(archived?.home, team)
        ? 'home'
        : '';
    if (!side) continue;
    for (const id of pitcherUsageIdsForArchivedSide(archived?.pitching?.[side])) ids.add(id);
  }
  return ids;
}

function markPitchersUsedYesterday(entries, usedIds = new Set()) {
  return listify(entries).map((entry) => {
    const id = Number(entry?.id ?? entry?.person?.id);
    return Number.isFinite(id) && usedIds.has(id) ? { ...entry, usedYesterday: true } : entry;
  });
}

async function pitcherUsedOnDate(playerId, date, game) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0 || !date) return false;
  const season = seasonForDate(date);
  const cacheKey = `${id}:${date}:used`;
  if (pitcherUsageDateCache.has(cacheKey)) return pitcherUsageDateCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'pitching');
    url.searchParams.set('season', String(season));
    url.searchParams.set('gameType', 'R');
    const response = await getJson(url.toString());
    return listify(response?.stats?.[0]?.splits).some((split) => {
      if (String(split?.date || '') !== String(date)) return false;
      return inningsToOuts(split?.stat?.inningsPitched) > 0
        || statNumber(split?.stat?.numberOfPitches ?? split?.stat?.pitchesThrown) > 0
        || statNumber(split?.stat?.battersFaced) > 0;
    });
  })().catch((error) => {
    pitcherUsageDateCache.delete(cacheKey);
    throw error;
  });
  pitcherUsageDateCache.set(cacheKey, promise);
  return promise;
}

async function markPitchersUsedOnPreviousDate(entries, game) {
  const selectedDate = officialDateForGame(game);
  const [yesterday] = recentCalendarDateWindow(selectedDate, 2);
  if (!yesterday || yesterday === selectedDate) return entries;
  const marked = await mapWithConcurrency(listify(entries), 6, async (entry) => {
    const id = Number(entry?.id ?? entry?.person?.id);
    if (!Number.isFinite(id)) return entry;
    const used = await pitcherUsedOnDate(id, yesterday, game).catch(() => false);
    return used ? { ...entry, usedYesterday: true } : entry;
  });
  return marked;
}

async function ensurePreviewBullpen(game) {
  if (!shouldPreferProbablePitcher(game)) return;
  game.pitching = game.pitching || emptyPitchingData();
  for (const side of ['away', 'home']) {
    const team = side === 'away' ? game.away : game.home;
    const existing = game.pitching?.[side] || { current: null, bullpen: [] };
    const probableId = Number(game?.probablePitchers?.[side]?.id);
    const profiles = await fetchTeamPitcherRosterProfiles(team, game).catch(() => []);
    const profilesById = new Map(profiles.map((profile) => [String(profile.id), profile]));
    const existingBullpen = listify(existing.bullpen)
      .map((entry) => {
        const profile = profilesById.get(String(entry?.id ?? ''));
        return normalizePitcherDisplayEntry(profile ? { ...entry, ...profile, role: entry?.role || 'bullpen' } : entry, entry?.role || 'bullpen');
      })
      .filter(Boolean);
    // Keep the full active pitching staff here. The Pitching tab splits this pool into
    // STARTERS and RELIEF later; filtering starter-like arms out here made the starters
    // section look incomplete on future/pre-game slates.
    let bullpen = profiles
      .filter((profile) => Number(profile?.id) !== probableId)
      .map((profile) => normalizePitcherDisplayEntry(profile, 'bullpen'))
      .filter(Boolean)
      .sort((a, b) => {
        const aStarter = isStarterLikePitcher(a) ? 1 : 0;
        const bStarter = isStarterLikePitcher(b) ? 1 : 0;
        if (bStarter !== aStarter) return bStarter - aStarter;
        return pitcherGamesStarted(b) - pitcherGamesStarted(a)
          || pitcherSaveCount(b) - pitcherSaveCount(a)
          || pitcherGamesFinished(b) - pitcherGamesFinished(a)
          || pitcherStrikeoutCount(b) - pitcherStrikeoutCount(a)
          || String(a?.name || '').localeCompare(String(b?.name || ''));
      });
    const merged = new Map();
    for (const arm of [...existingBullpen, ...bullpen]) {
      const id = String(arm?.id ?? arm?.fullName ?? arm?.name ?? '');
      if (!id) continue;
      const prev = merged.get(id);
      merged.set(id, prev ? normalizePitcherDisplayEntry({ ...prev, ...arm, role: prev.role || arm.role || 'bullpen' }, 'bullpen') : arm);
    }
    bullpen = [...merged.values()]
      .filter((arm) => Number(arm?.id) !== probableId)
      .sort((a, b) => pitcherSaveCount(b) - pitcherSaveCount(a) || pitcherGamesFinished(b) - pitcherGamesFinished(a) || pitcherStrikeoutCount(b) - pitcherStrikeoutCount(a) || String(a?.name || '').localeCompare(String(b?.name || '')));
    bullpen = await markPitchersUsedOnPreviousDate(bullpen, game);
    game.pitching[side] = { ...existing, bullpen };
    const lookup = Object.fromEntries(profiles.map((profile) => [String(profile.id), profile]));
    if (Object.keys(lookup).length) persistPlayerLookupForGame(game, lookup);
  }
}

function lineupEntryCount(lineup) {
  const away = Array.isArray(lineup?.away) ? lineup.away.length : 0;
  const home = Array.isArray(lineup?.home) ? lineup.home.length : 0;
  const awayBench = Array.isArray(lineup?.awayBench) ? lineup.awayBench.length : 0;
  const homeBench = Array.isArray(lineup?.homeBench) ? lineup.homeBench.length : 0;
  return away + home + awayBench + homeBench;
}

function hasLineupData(lineup) {
  return lineupEntryCount(lineup) > 0;
}

function normalizeLineupForDisplay(lineup) {
  const safe = lineup || { away: [], home: [], awayBench: [], homeBench: [] };
  const away = Array.isArray(safe.away) ? [...safe.away] : [];
  const home = Array.isArray(safe.home) ? [...safe.home] : [];
  const awayBench = Array.isArray(safe.awayBench) ? [...safe.awayBench] : [];
  const homeBench = Array.isArray(safe.homeBench) ? [...safe.homeBench] : [];

  if (!away.length && awayBench.length) {
    const promoted = awayBench.slice(0, 9).map((entry, idx) => ({ ...entry, slot: idx + 1 }));
    away.push(...promoted);
  }
  if (!home.length && homeBench.length) {
    const promoted = homeBench.slice(0, 9).map((entry, idx) => ({ ...entry, slot: idx + 1 }));
    home.push(...promoted);
  }

  const awayIds = new Set(away.map((entry) => Number(entry?.id)).filter(Number.isFinite));
  const homeIds = new Set(home.map((entry) => Number(entry?.id)).filter(Number.isFinite));
  const awayBenchFiltered = awayBench.filter((entry) => !awayIds.has(Number(entry?.id)));
  const homeBenchFiltered = homeBench.filter((entry) => !homeIds.has(Number(entry?.id)));

  return { away, home, awayBench: awayBenchFiltered, homeBench: homeBenchFiltered };
}

function lineupEntryQuality(entry = {}) {
  const source = String(entry?.source || '').toLowerCase();
  let score = 1;
  if (source.includes('boxscore')) score += 4;
  if (source.includes('starting-lineups')) score += 3;
  if (source.includes('previous') || source.includes('archive')) score -= 4;
  if (source.includes('completion')) score -= 2;
  if (lineupTodayHasAction(entry?.today)) score += 2;
  if (lineupGameStatsHasAction(entry?.gameBatting)) score += 2;
  if (entry?.substitutionStarter) score += 1;
  if (Number.isFinite(Number(entry?.battingOrder)) && Number(entry.battingOrder) > 0) score += 1;
  return score;
}

function lineupSideQualityScore(sideLineup = [], bench = []) {
  const rows = Array.isArray(sideLineup) ? sideLineup : [];
  const hitters = rows.filter((entry) => Number.isFinite(Number(entry?.id)) && Number(entry.id) > 0 && !lineupEntryIsPitcherOnly(entry));
  const benchCount = Array.isArray(bench) ? bench.length : 0;
  const base = Math.min(hitters.length, 9) * 10;
  const detail = hitters.reduce((sum, entry) => sum + lineupEntryQuality(entry), 0);
  const alphabeticalPenalty = lineupLooksAlphabetical(hitters) ? 18 : 0;
  return base + detail + Math.min(benchCount, 8) * 0.15 - alphabeticalPenalty;
}

function lineupQualityScore(lineup = {}) {
  return lineupSideQualityScore(lineup?.away, lineup?.awayBench)
    + lineupSideQualityScore(lineup?.home, lineup?.homeBench);
}

function chooseBetterLineup(primary, secondary) {
  if (!primary && !secondary) return { away: [], home: [], awayBench: [], homeBench: [] };
  if (!primary) return secondary;
  if (!secondary) return primary;
  const primaryScore = lineupQualityScore(primary);
  const secondaryScore = lineupQualityScore(secondary);
  if (primaryScore !== secondaryScore) return primaryScore > secondaryScore ? primary : secondary;
  return lineupEntryCount(primary) >= lineupEntryCount(secondary) ? primary : secondary;
}

function pitchingEntryCount(side) {
  const current = side?.current ? 1 : 0;
  const bullpen = Array.isArray(side?.bullpen) ? side.bullpen.length : 0;
  return current + bullpen;
}

function pitchingTotalCount(pitching) {
  return pitchingEntryCount(pitching?.away) + pitchingEntryCount(pitching?.home);
}

function pitchingCurrentPriority(entry) {
  if (!entry) return 0;
  let score = 1;
  const role = cleanSummary(entry?.role || '').toLowerCase();
  const today = cleanSummary(entry?.today || entry?.todayPitching || '').toLowerCase();
  if (role === 'current') score += 10;
  if (entry?.isActive) score += 4;
  if (pitcherUsedInGame(entry)) score += 14;
  if (today === 'not in yet' || today === 'unused today') score -= 12;
  if (role === 'starter' && pitcherUsedInGame(entry)) score += 2;
  else if (role === 'starter') score += 0.5;
  return score;
}

function chooseBetterPitchingSide(primary, secondary) {
  if (!primary && !secondary) return { current: null, bullpen: [] };
  if (!primary) return secondary;
  if (!secondary) return primary;
  const primaryCount = pitchingEntryCount(primary);
  const secondaryCount = pitchingEntryCount(secondary);
  const current = pitchingCurrentPriority(primary.current) >= pitchingCurrentPriority(secondary.current)
    ? (primary.current || secondary.current || null)
    : (secondary.current || primary.current || null);
  const history = primary.history?.length ? primary.history : (secondary.history || []);
  if (primaryCount !== secondaryCount) {
    const bullpenSource = (primary.bullpen?.length || 0) >= (secondary.bullpen?.length || 0) ? primary : secondary;
    return {
      current,
      bullpen: bullpenSource.bullpen || [],
      history,
    };
  }
  return {
    current,
    bullpen: (primary.bullpen?.length ? primary.bullpen : secondary.bullpen) || [],
    history,
  };
}

function chooseBetterPitching(primary, secondary) {
  if (!primary && !secondary) return { away: { current: null, bullpen: [] }, home: { current: null, bullpen: [] } };
  if (!primary) return secondary;
  if (!secondary) return primary;
  return {
    away: chooseBetterPitchingSide(primary.away, secondary.away),
    home: chooseBetterPitchingSide(primary.home, secondary.home),
  };
}

function tickerQuality(ticker) {
  if (!Array.isArray(ticker) || !ticker.length) return 0;
  const first = String(ticker[0]?.text || '').trim().toLowerCase();
  if (!first) return 0;
  if (first.includes('awaiting first pitch')) return 1;
  return Math.min(5, ticker.length) + 1;
}

function chooseBetterTicker(primary, secondary) {
  return tickerQuality(primary) >= tickerQuality(secondary) ? (primary || []) : (secondary || []);
}

function scoreCardData(card) {
  if (!card) return 0;
  const lineup = lineupEntryCount(card.lineup);
  const pitching = pitchingTotalCount(card.pitching);
  const ticker = tickerQuality(card.ticker);
  const lookup = Object.keys(card.playerLookup || {}).length;
  const awayScore = Number(card.awayScore);
  const homeScore = Number(card.homeScore);
  const scoreKnown = Number.isFinite(awayScore) && Number.isFinite(homeScore) ? 3 : 0;
  const playKnown = isPlaceholderPlay(card.lastPlay) ? 0 : 2;
  return lineup + pitching + ticker + Math.min(lookup, 25) + scoreKnown + playKnown;
}

function probablePitcherEntryIsUsableForMerge(pitcher = null) {
  if (!pitcher) return false;
  if (probablePitcherHasTbdFallback(pitcher)) return true;
  return Boolean(!probablePitcherIsTbd(pitcher) && cleanSummary(pitcher.fullName || pitcher.name || ''));
}

function probablePitcherMergePriority(pitcher = null, candidateIndex = 0) {
  if (!pitcher) return -1000;
  const tinyOrderTieBreak = Math.max(0, 20 - candidateIndex) / 1000;
  if (probablePitcherHasTbdFallback(pitcher)) return 900 + tinyOrderTieBreak;
  if (isHighConfidenceProbableSource(pitcher) && !probablePitcherIsTbd(pitcher)) return 1000 + tinyOrderTieBreak;
  if (isAuthoritativeProbableSource(pitcher) && !probablePitcherIsTbd(pitcher)) return 700 + tinyOrderTieBreak;
  if (pitcher?.isPotentialStarter) return 550 + tinyOrderTieBreak;
  if (!probablePitcherIsTbd(pitcher) && cleanSummary(pitcher.fullName || pitcher.name || '')) return 450 + tinyOrderTieBreak;
  return 50 + tinyOrderTieBreak;
}

function mergeCardProbablePitchers(primary = {}, secondary = {}, tertiary = {}) {
  const game = { ...(tertiary || {}), ...(secondary || {}), ...(primary || {}) };
  const chooseSide = (side) => {
    const candidates = [
      primary?.probablePitchers?.[side],
      secondary?.probablePitchers?.[side],
      tertiary?.probablePitchers?.[side],
      primary?.pitching?.[side]?.current,
      secondary?.pitching?.[side]?.current,
      tertiary?.pitching?.[side]?.current,
    ].filter(Boolean);
    if (!candidates.length) return null;
    const ranked = candidates
      .map((candidate, index) => ({ candidate, priority: probablePitcherMergePriority(candidate, index) }))
      .filter((entry) => probablePitcherEntryIsUsableForMerge(entry.candidate))
      .sort((a, b) => b.priority - a.priority);
    return ranked[0]?.candidate || candidates[0] || null;
  };
  return sanitizeProbablePitchers({
    away: chooseSide('away'),
    home: chooseSide('home'),
  }, game, game?.away, game?.home);
}

function chooseBestGameCard(existing, incoming) {
  if (!existing) return incoming;
  if (!incoming) return existing;

  const existingFinal = isCompletedGameCard(existing);
  const incomingFinal = isCompletedGameCard(incoming);
  const incomingHasAwayScore = Number.isFinite(Number(incoming.awayScore));
  const incomingHasHomeScore = Number.isFinite(Number(incoming.homeScore));
  const pregame = shouldPreferProbablePitcher(incoming);

  if (existingFinal || incomingFinal) {
    const finalized = incomingFinal
      ? normalizeCompletedCard(mergeFinishedGameState(incoming, existing))
      : normalizeCompletedCard(existing);
    const canReplaceFinalScore = incomingFinal || !existingFinal;
    return {
      ...finalized,
      awayScore: pregame ? '-' : (canReplaceFinalScore && incomingHasAwayScore ? incoming.awayScore : finalized.awayScore),
      homeScore: pregame ? '-' : (canReplaceFinalScore && incomingHasHomeScore ? incoming.homeScore : finalized.homeScore),
      lineup: chooseBetterLineup(finalized.lineup, existing.lineup),
      pitching: chooseBetterPitching(finalized.pitching, existing.pitching),
      ticker: chooseBetterTicker(finalized.ticker, existing.ticker),
      lastPlay: !isPlaceholderPlay(finalized.lastPlay) ? finalized.lastPlay : (existing.lastPlay || incoming.lastPlay || 'Final'),
      awayStreak: finalized.awayStreak || incoming.awayStreak || existing.awayStreak || '',
      homeStreak: finalized.homeStreak || incoming.homeStreak || existing.homeStreak || '',
      probablePitchers: mergeCardProbablePitchers(finalized, incoming, existing),
      playerLookup: { ...(existing.playerLookup || {}), ...(incoming.playerLookup || {}) },
    };
  }

  const incomingScore = scoreCardData(incoming);
  const existingScore = scoreCardData(existing);
  const preferred = incomingScore >= existingScore ? incoming : existing;
  const fallback = preferred === incoming ? existing : incoming;
  const liveState = pregame ? null : incoming;
  const liveLineScoreInnings = Array.isArray(liveState?.lineScoreInnings) && liveState.lineScoreInnings.length
    ? liveState.lineScoreInnings
    : null;

  return {
    ...fallback,
    ...preferred,
    awayScore: pregame ? '-' : (Number.isFinite(Number(liveState?.awayScore)) ? liveState.awayScore : (Number.isFinite(Number(preferred.awayScore)) ? preferred.awayScore : fallback.awayScore)),
    homeScore: pregame ? '-' : (Number.isFinite(Number(liveState?.homeScore)) ? liveState.homeScore : (Number.isFinite(Number(preferred.homeScore)) ? preferred.homeScore : fallback.homeScore)),
    awayHits: pregame ? '-' : (Number.isFinite(Number(liveState?.awayHits)) ? liveState.awayHits : (preferred.awayHits ?? fallback.awayHits)),
    homeHits: pregame ? '-' : (Number.isFinite(Number(liveState?.homeHits)) ? liveState.homeHits : (preferred.homeHits ?? fallback.homeHits)),
    status: liveState?.status || preferred.status || fallback.status,
    inning: liveState?.inning || preferred.inning || fallback.inning,
    inningShort: liveState?.inningShort || preferred.inningShort || fallback.inningShort,
    balls: pregame ? 0 : (liveState?.balls ?? preferred.balls ?? fallback.balls ?? 0),
    strikes: pregame ? 0 : (liveState?.strikes ?? preferred.strikes ?? fallback.strikes ?? 0),
    outs: pregame ? 0 : (liveState?.outs ?? preferred.outs ?? fallback.outs ?? 0),
    bases: pregame ? { first: false, second: false, third: false } : (liveState?.bases || preferred.bases || fallback.bases),
    lineScoreInnings: pregame ? [] : (liveLineScoreInnings || preferred.lineScoreInnings || fallback.lineScoreInnings || []),
    activeBatterId: pregame ? null : (liveState?.activeBatterId ?? preferred.activeBatterId ?? fallback.activeBatterId ?? null),
    activeBatterName: pregame ? '' : (liveState?.activeBatterName || preferred.activeBatterName || fallback.activeBatterName || ''),
    activePlayComplete: pregame ? false : Boolean(liveState?.activePlayComplete ?? preferred.activePlayComplete ?? fallback.activePlayComplete ?? false),
    activePlayAtBatIndex: pregame ? null : (liveState?.activePlayAtBatIndex ?? preferred.activePlayAtBatIndex ?? fallback.activePlayAtBatIndex ?? null),
    battingSide: pregame ? 'away' : (liveState?.battingSide || preferred.battingSide || fallback.battingSide || 'away'),
    currentEvent: pregame ? '' : (liveState?.currentEvent || preferred.currentEvent || fallback.currentEvent || ''),
    probablePitchers: mergeCardProbablePitchers(preferred, fallback, incoming),
    lineup: chooseBetterLineup(preferred.lineup, fallback.lineup),
    pitching: chooseBetterPitching(preferred.pitching, fallback.pitching),
    ticker: pregame ? [] : chooseBetterTicker(preferred.ticker, fallback.ticker),
    lastPlay: pregame ? defaultPlayText(incoming) : (!isPlaceholderPlay(preferred.lastPlay) ? preferred.lastPlay : (fallback.lastPlay || preferred.lastPlay)),
    awayStreak: preferred.awayStreak || fallback.awayStreak || '',
    homeStreak: preferred.homeStreak || fallback.homeStreak || '',
    playerLookup: { ...(fallback.playerLookup || {}), ...(preferred.playerLookup || {}) },
  };
}

function mergeCardsWithArchive(cards, archivedCards) {
  const archivedByPk = new Map((archivedCards || []).map((card) => [String(card.gamePk), card]));
  return cards.map((card) => chooseBestGameCard(archivedByPk.get(String(card.gamePk)), card));
}

function emptyLineupData() {
  return { away: [], home: [], awayBench: [], homeBench: [] };
}

function emptyPitchingData() {
  return { away: { current: null, bullpen: [] }, home: { current: null, bullpen: [] } };
}

function normalizeBoxscorePayload(rawBox) {
  return rawBox?.teams ? rawBox : rawBox?.liveData?.boxscore || {};
}

function buildGameDataFromBoxscore(boxscore, game, options = {}) {
  const activePlay = options.activePlay || null;
  const gamePlayers = options.gamePlayers || {};
  const awayAbbrev = canonicalTeamAbbrev(options.awayAbbrev || game?.teams?.away?.team?.abbreviation || game?.away || 'AWAY');
  const homeAbbrev = canonicalTeamAbbrev(options.homeAbbrev || game?.teams?.home?.team?.abbreviation || game?.home || 'HOME');
  const awayColor = options.awayColor || getTeamColor(awayAbbrev);
  const homeColor = options.homeColor || getTeamColor(homeAbbrev);
  const battingSide = options.battingSide || 'away';
  let awayProbablePitcher = shouldPreferProbablePitcher(game)
    ? options?.probablePitchers?.away || game?.probablePitchers?.away || null
    : options?.probablePitchers?.away || game?.probablePitchers?.away || game?.teams?.away?.probablePitcher || null;
  let homeProbablePitcher = shouldPreferProbablePitcher(game)
    ? options?.probablePitchers?.home || game?.probablePitchers?.home || null
    : options?.probablePitchers?.home || game?.probablePitchers?.home || game?.teams?.home?.probablePitcher || null;
  const awayPlayers = boxscore?.teams?.away?.players || {};
  const homePlayers = boxscore?.teams?.home?.players || {};
  const awayPitcherOrder = boxscore?.teams?.away?.pitchers || [];
  const homePitcherOrder = boxscore?.teams?.home?.pitchers || [];
  const awayOrder = boxscore?.teams?.away?.battingOrder || boxscore?.teams?.away?.batters || [];
  const homeOrder = boxscore?.teams?.home?.battingOrder || boxscore?.teams?.home?.batters || [];
  const activePitcherId = options.currentPitcherId || activePlay?.matchup?.pitcher?.id;
  const nextBatterIds = options.nextBatterIds || nextBatterIdsForLiveState(options.allPlays || [], awayOrder, homeOrder, activePlay, battingSide);
  const activeBatterId = activePlay?.matchup?.batter?.id;
  const awayLineup = buildLineup(awayPlayers, activeBatterId, awayOrder, nextBatterIds.away);
  const homeLineup = buildLineup(homePlayers, activeBatterId, homeOrder, nextBatterIds.home);

  return {
    lineup: {
      away: awayLineup,
      home: homeLineup,
      awayBench: buildBench(awayPlayers, awayLineup),
      homeBench: buildBench(homePlayers, homeLineup),
    },
    pitching: {
      away: buildPitchingStaff(
        awayPlayers,
        battingSide === 'home' ? activePitcherId : awayProbablePitcher?.id,
        awayProbablePitcher,
        awayPitcherOrder,
      ),
      home: buildPitchingStaff(
        homePlayers,
        battingSide === 'away' ? activePitcherId : homeProbablePitcher?.id,
        homeProbablePitcher,
        homePitcherOrder,
      ),
    },
    playerLookup: {
      ...buildPlayerLookup(awayPlayers, gamePlayers, awayAbbrev, awayColor, getLogoPath(awayAbbrev)),
      ...buildPlayerLookup(homePlayers, gamePlayers, homeAbbrev, homeColor, getLogoPath(homeAbbrev)),
    },
  };
}

function lineupCount(lineup) {
  const away = Array.isArray(lineup?.away) ? lineup.away.length : 0;
  const home = Array.isArray(lineup?.home) ? lineup.home.length : 0;
  return away + home;
}

function isCompletedGameCard(card) {
  const s = String(card?.status || '').toLowerCase();
  const i = String(card?.inning || '').toLowerCase();
  const sh = String(card?.inningShort || '').toLowerCase();
  return s.includes('final') || i.includes('final') || sh.includes('final');
}

function normalizeCompletedCard(card) {
  if (!isCompletedGameCard(card) && shouldPreferProbablePitcher(card)) {
    return repairDuplicatedTeamLineups({
      ...card,
      awayScore: '-',
      homeScore: '-',
      awayHits: '-',
      homeHits: '-',
      inning: `Starts ${gameStartTimeText(card)}`,
      inningShort: 'PRE',
      balls: 0,
      strikes: 0,
      outs: 0,
      bases: { first: false, second: false, third: false },
      ticker: [],
      lastPlay: defaultPlayText(card),
      currentEvent: '',
      activeBatterId: null,
      activeBatterName: '',
      activePlayComplete: false,
      activePlayAtBatIndex: null,
      lineScoreInnings: [],
    });
  }
  if (!isCompletedGameCard(card)) return repairDuplicatedTeamLineups(card);
  return repairDuplicatedTeamLineups({
    ...card,
    status: 'Final',
    inning: 'Final',
    inningShort: 'Final',
    balls: 0,
    strikes: 0,
    outs: 0,
    bases: { first: false, second: false, third: false },
    activeBatterId: null,
    activeBatterName: '',
    activePlayComplete: false,
    activePlayAtBatIndex: null,
    currentEvent: '',
  });
}

function isPlaceholderPlay(text) {
  const t = String(text || '').trim().toLowerCase();
  return !t
    || t.includes('awaiting first pitch')
    || t.includes('live feed updating')
    || t.startsWith('starts ')
    || t.includes('not started')
    || t.includes('start time pending')
    || t.includes('loading full live pitch data')
    || t.includes('waiting for pitch feed')
    || t.includes('waiting for full at-bat pitch feed');
}

function firstRealPlayText(...values) {
  for (const value of values) {
    const text = cleanPlayText(value || '');
    if (text && !isPlaceholderPlay(text) && !isLiveLabTransientAdministrativeText(text)) return text;
  }
  return '';
}

function playEventSearchText(play = {}) {
  return [
    play?.result?.eventType,
    play?.result?.event,
    play?.result?.description,
    play?.details?.eventType,
    play?.details?.description,
  ].map((value) => cleanPlayText(value || '')).filter(Boolean).join(' ');
}

function isSubstitutionText(value) {
  const text = String(value || '').toLowerCase().replace(/[_-]+/g, ' ');
  if (!text) return false;
  return /\bpitching\s+(substitution|change)\b/.test(text)
    || /\b(defensive|offensive|batting)\s+substitution\b/.test(text)
    || /\bpinch\s+(hitter|runner|hit|run)\b/.test(text)
    || /\bdefensive\s+switch\b/.test(text)
    || /\bsubstitution\b/.test(text);
}

function isBattingOrDefensiveSubstitutionText(value) {
  const text = String(value || '').toLowerCase().replace(/[_-]+/g, ' ');
  if (!text) return false;
  if (/\bpitching\s+(substitution|change)\b/.test(text)) return false;
  return isSubstitutionText(text);
}

function isSubstitutionPlay(play = {}) {
  return isSubstitutionText(playEventSearchText(play));
}

function isBattingOrDefensiveSubstitutionPlay(play = {}) {
  return isBattingOrDefensiveSubstitutionText(playEventSearchText(play));
}

function isLiveLabTransientAdministrativeText(value) {
  const text = String(value || '').toLowerCase().replace(/[_-]+/g, ' ');
  if (!text) return false;
  return /\bbatter\s+timeout\b/.test(text);
}

function isLiveLabTransientAdministrativePlay(play = {}) {
  return isLiveLabTransientAdministrativeText(playEventSearchText(play));
}

function firstLiveLabPlayText(...values) {
  for (const value of values) {
    const text = cleanPlayText(value || '');
    if (
      text
      && !isPlaceholderPlay(text)
      && !isSubstitutionText(text)
      && !isLiveLabTransientAdministrativeText(text)
    ) return text;
  }
  return '';
}

function liveLabBatterNameForDisplay(play = null, game = null, selectedPlayerId = '') {
  return cleanSummary(
    play?.matchup?.batter?.fullName
      || play?.matchup?.batter?.name
      || (Number(selectedPlayerId) === Number(game?.activeBatterId)
        ? (game?.battingSide === 'home' ? game?.homeHitter : game?.awayHitter)
        : '')
      || (game?.battingSide === 'home' ? game?.homeHitter : game?.awayHitter)
      || 'Batter',
  );
}

function liveLabResultTextForPlay(play = null) {
  if (!play || !liveLabPitchKnownOutcome(play)) return '';
  return firstLiveLabPlayText(
    play?.result?.description,
    play?.result?.event,
    play?.result?.eventType,
  );
}

function liveLabInningTransitionText(game = null) {
  const text = cleanSummary(game?.inningShort || game?.inning || game?.status || '');
  if (!text || /^(live|in progress)$/i.test(text)) return '';
  if (/\b(mid|middle|end)\b/i.test(text)) return text;
  return '';
}

function liveLabDisplayPlayText({ play = null, game = null, selectedPlayerId = '', loadingText = '' } = {}) {
  const resultText = liveLabResultTextForPlay(play);
  if (resultText) return resultText;
  const hasCurrentBatter = Boolean(
    play?.matchup?.batter?.id
      || (Number.isFinite(Number(game?.activeBatterId)) && Number(game.activeBatterId) > 0),
  );
  if (hasCurrentBatter && gameHasLiveProgress(game)) {
    return `${liveLabBatterNameForDisplay(play, game, selectedPlayerId)} up to bat`;
  }
  return liveLabInningTransitionText(game)
    || firstLiveLabPlayText(game?.lastPlay, ...(Array.isArray(game?.ticker) ? game.ticker.map((item) => item?.text) : []))
    || loadingText;
}

function mergeFinishedGameState(card, cached) {
  if (!cached) return card;
  const sameOfficialDate = calendarDateOnly(card?.officialDate || card?.gameDate || '') === calendarDateOnly(cached?.officialDate || cached?.gameDate || '');
  const mayUseCachedLineup = sameOfficialDate && isCompletedGameCard(card);
  const cachedLineupCount = (cached?.lineup?.away?.length || 0) + (cached?.lineup?.home?.length || 0);
  const cachedPitchCount = (cached?.pitching?.away?.bullpen?.length || 0) + (cached?.pitching?.home?.bullpen?.length || 0)
    + (cached?.pitching?.away?.current ? 1 : 0) + (cached?.pitching?.home?.current ? 1 : 0);
  const cachedTickerGood = Array.isArray(cached?.ticker) && cached.ticker.length && !isPlaceholderPlay(cached.ticker[0]?.text);
  const cardTickerGood = Array.isArray(card?.ticker) && card.ticker.length && !isPlaceholderPlay(card.ticker[0]?.text);
  const ticker = cachedTickerGood ? cached.ticker : (cardTickerGood ? card.ticker : (cached?.ticker?.length ? cached.ticker : card.ticker));
  const lastPlay = !isPlaceholderPlay(card?.lastPlay) ? card.lastPlay
    : (!isPlaceholderPlay(cached?.lastPlay) ? cached.lastPlay : 'Final');
  return {
    ...card,
    awayPitcher: cached.awayPitcher || card.awayPitcher,
    homePitcher: cached.homePitcher || card.homePitcher,
    awayHitter: cached.awayHitter || card.awayHitter,
    homeHitter: cached.homeHitter || card.homeHitter,
    ticker,
    lastPlay,
    balls: cached.balls ?? card.balls,
    strikes: cached.strikes ?? card.strikes,
    outs: cached.outs ?? card.outs,
    bases: cached.bases || card.bases,
    lineup: mayUseCachedLineup && cachedLineupCount > 0 ? cached.lineup : card.lineup,
    pitching: cachedPitchCount > 0 ? cached.pitching : card.pitching,
    awayStreak: card.awayStreak || cached.awayStreak || '',
    homeStreak: card.homeStreak || cached.homeStreak || '',
    playerLookup: { ...(cached.playerLookup || {}), ...(card.playerLookup || {}) },
  };
}

function latestPlayableLiveLabPlay(allPlays = [], currentPlay = null) {
  const candidates = listify(allPlays)
    .filter((play) => play?.matchup)
    .filter((play) => !isSubstitutionPlay(play))
    .filter((play) => !isLiveLabTransientAdministrativePlay(play));
  const activeIndex = Number(currentPlay?.about?.atBatIndex);
  if (Number.isFinite(activeIndex)) {
    const sameAtBat = [...candidates].reverse().find((play) => Number(play?.about?.atBatIndex) === activeIndex);
    if (sameAtBat) return sameAtBat;
  }
  return candidates[candidates.length - 1] || null;
}

function resolveActivePlay(game, currentPlay, allPlays) {
  if (!gameHasReachedOfficialStart(game)) return null;
  const fallbackPlay = latestPlayableLiveLabPlay(allPlays, currentPlay);
  if (game?.status?.abstractGameState === 'Final' && allPlays.length) return fallbackPlay || allPlays[allPlays.length - 1];
  if (currentPlay?.matchup) {
    const matchingPlay = listify(allPlays).find((play) => liveLabSameAtBat(play, currentPlay));
    const play = liveLabBetterPlay(currentPlay, matchingPlay);
    const matchingFallback = matchingPlay && !isSubstitutionPlay(matchingPlay) && !isLiveLabTransientAdministrativePlay(matchingPlay)
      ? matchingPlay
      : null;
    if (isAdministrativePlayText(`${play?.result?.event || ''} ${play?.result?.description || ''}`) && latestBaseballPlayEvent(play)) return play;
    return isSubstitutionPlay(play) || isLiveLabTransientAdministrativePlay(play) ? (fallbackPlay || matchingFallback || null) : play;
  }
  if (allPlays.length) return fallbackPlay || allPlays[allPlays.length - 1];
  return game?.status?.abstractGameState === 'Final' ? null : currentPlay || null;
}

function betPropDefinition(type) {
  return BET_PROP_DEFS[type] || { label: String(type || 'Prop').toUpperCase(), multiLabel: String(type || 'Prop').toUpperCase(), statKind: 'batting', statKey: '', activeRole: 'batter' };
}

function normalizeBetTarget(target) {
  const value = Math.floor(Number(target));
  return Number.isFinite(value) && value > 0 ? value : 1;
}

function betPropLabel(type, target = 1) {
  const prop = betPropDefinition(type);
  return normalizeBetTarget(target) > 1 ? prop.multiLabel : prop.label;
}

function formatBetLegProp(leg) {
  const target = normalizeBetTarget(leg?.target);
  const label = betPropLabel(leg?.propType || leg?.type, target);
  return target > 1 ? `${target}+ ${label}` : label;
}

function queueTextSelection(input) {
  if (!input) return;
  requestAnimationFrame(() => {
    if (document.activeElement !== input) return;
    try {
      input.select();
    } catch {}
    try {
      input.setSelectionRange(0, String(input.value || '').length);
    } catch {}
  });
}

function focusBetPlayerSearch() {
  if (!betPlayerSearchEl) return;
  betPlayerSearchEl.focus();
  queueTextSelection(betPlayerSearchEl);
}

function betBuilderIsTeamWin() {
  return (betPropSelectEl?.value || '') === 'teamWin';
}

function normalizeGamePickSide(side) {
  return side === 'home' ? 'home' : side === 'away' ? 'away' : '';
}

function scoreStateForGame(game) {
  const awayScore = Number(game?.awayScore);
  const homeScore = Number(game?.homeScore);
  const scoreKnown = Number.isFinite(awayScore) && Number.isFinite(homeScore);
  let leaderSide = '';
  if (scoreKnown) {
    if (awayScore > homeScore) leaderSide = 'away';
    else if (homeScore > awayScore) leaderSide = 'home';
  }
  return { awayScore, homeScore, scoreKnown, leaderSide };
}

function createGamePickLeg(game, side) {
  const normalizedSide = normalizeGamePickSide(side);
  if (!game || !normalizedSide) return null;
  const isAway = normalizedSide === 'away';
  const teamAbbrev = isAway ? game.away : game.home;
  const opponentAbbrev = isAway ? game.home : game.away;
  return {
    type: 'teamWin',
    propType: 'teamWin',
    target: 1,
    gamePk: game.gamePk,
    side: normalizedSide,
    teamAbbrev,
    opponentAbbrev,
    teamLogo: isAway ? game.awayLogo : game.homeLogo,
    teamColor: isAway ? game.awayColor : game.homeColor,
  };
}

function getPendingGamePickEntries(games = latestRenderedGames) {
  const cards = games?.length ? games : latestRenderedGames;
  const seen = new Set();
  return [...pendingGamePickSelections.entries()]
    .map(([key, side]) => {
      const game = gameForManualStateKey(key, cards);
      if (!game) return null;
      const stableKey = manualGameStateKey(game);
      if (seen.has(stableKey)) return null;
      seen.add(stableKey);
      return createGamePickLeg(game, side);
    })
    .filter(Boolean);
}

function readPendingGamePickStore(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const dateKey = `${PENDING_GAME_PICKS_STORAGE_KEY}:${selectedDate}`;
  const candidates = [];
  const rememberCandidate = (value, updatedAt = 0) => {
    const normalized = normalizePendingGamePickEntries(value);
    if (normalized.length) candidates.push({ items: normalized, updatedAt: Number(updatedAt) || 0 });
  };
  try {
    const keys = [dateKey, PENDING_GAME_PICKS_STORAGE_KEY];
    for (const key of keys) {
      const parsed = JSON.parse(localStorage.getItem(key) || '[]');
      if (Array.isArray(parsed) && parsed.length) {
        rememberCandidate(parsed);
      }
      if (parsed && typeof parsed === 'object') {
        const values = Object.values(parsed).filter(Array.isArray).flat();
        if (values.length) {
          rememberCandidate(values);
        }
      }
    }
  } catch {
    // Fall through to the protected same-day backup.
  }
  const backupState = readManualStateBackup(selectedDate);
  const mirrorState = readManualStateMirror(selectedDate);
  const durableState = readManualStateDurable(selectedDate);
  rememberCandidate(backupState.pendingGamePicks, backupState.updatedAt);
  rememberCandidate(mirrorState.pendingGamePicks, mirrorState.updatedAt);
  rememberCandidate(durableState.pendingGamePicks, durableState.updatedAt);
  try {
    const sessionState = JSON.parse(sessionStorage.getItem(manualStateBackupKey(selectedDate)) || '{}');
    rememberCandidate(sessionState?.pendingGamePicks, sessionState?.updatedAt);
  } catch {}
  const best = candidates
    .map((candidate) => manualStateCandidate(candidate.items, candidate.updatedAt, 'pending-store'))
    .sort(compareManualStateCandidates)[0]?.value || [];
  if (best.length) {
    writePendingGamePickStore(best, { backup: false });
    return best;
  }
  return [];
}

function normalizePendingGamePickEntries(picks = []) {
  return listify(picks)
    .map((entry) => Array.isArray(entry) ? [String(entry[0] || ''), normalizeGamePickSide(entry[1])] : null)
    .filter((entry) => entry?.[0] && entry?.[1]);
}

function manualStateWeight(value) {
  if (!value) return 0;
  if (Array.isArray(value)) return value.reduce((sum, item) => sum + 2 + manualStateWeight(item), value.length);
  if (typeof value === 'object') return Object.values(value).reduce((sum, item) => sum + manualStateWeight(item), Object.keys(value).length);
  return String(value).trim() ? 1 : 0;
}

function manualStatePayloadSize(value) {
  try {
    return JSON.stringify(value ?? null).length;
  } catch {
    return String(value ?? '').length;
  }
}

function compareManualStateCandidates(a = {}, b = {}) {
  return (Number(b.weight) || 0) - (Number(a.weight) || 0)
    || (Number(b.updatedAt) || 0) - (Number(a.updatedAt) || 0)
    || (Number(b.size) || 0) - (Number(a.size) || 0);
}

function compareTrackedPlayerStateCandidates(a = {}, b = {}) {
  return (Number(b.updatedAt) || 0) - (Number(a.updatedAt) || 0)
    || (Number(b.weight) || 0) - (Number(a.weight) || 0)
    || (Number(b.size) || 0) - (Number(a.size) || 0);
}

function manualStateCandidate(value, updatedAt = 0, source = '') {
  return {
    value,
    updatedAt: Number(updatedAt) || 0,
    source,
    weight: manualStateWeight(value),
    size: manualStatePayloadSize(value),
  };
}

function syncMetaUpdatedAt(key = '') {
  try {
    const parsed = JSON.parse(localStorage.getItem('owentools-sync-meta:baseball-dashboard') || '{}') || {};
    const time = Date.parse(parsed[String(key || '')] || '');
    return Number.isFinite(time) ? time : 0;
  } catch {
    return 0;
  }
}

function trackedPlayersBackupUpdatedAt(date = dateInput.value || formatDate(new Date())) {
  const times = [];
  const remember = (source) => {
    if (hasOwnManualStateField(source, 'trackedPlayers')) times.push(Number(source?.updatedAt) || 0);
  };
  remember(readManualStateMirror(date));
  remember(readManualStateBackup(date));
  remember(readManualStateDurable(date));
  try {
    remember(JSON.parse(sessionStorage.getItem(manualStateBackupKey(date)) || '{}'));
  } catch {}
  return Math.max(0, ...times);
}

function activeManualStateDateMatches(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  return String(manualStateInMemoryDate || dateInput.value || '') === selectedDate;
}

function activeManualStateFieldValue(date, field, normalizer = (value) => value) {
  if (!activeManualStateDateMatches(date)) return null;
  if (field === 'pendingGamePicks') return normalizePendingGamePickEntries([...pendingGamePickSelections.entries()]);
  if (field === 'tossupScoreboards') return normalizer([...tossupScoreboardGamePks]);
  if (field === 'lockedTossupScoreboards') return normalizer([...lockedTossupScoreboardGamePks]);
  if (field === 'overUnderScoreboards') return normalizer(serializeOverUnderScoreboards());
  if (field === 'trackedPlayers') {
    const key = typeof trackedPlayersStorageKey === 'function' ? trackedPlayersStorageKey(date) : '';
    if (key && trackedPlayersMemoryByDate?.has?.(key)) return normalizer(trackedPlayersMemoryByDate.get(key) || []);
  }
  return null;
}

function shouldWriteManualStateField(currentValue, nextValue, options = {}) {
  const nextWeight = manualStateWeight(nextValue);
  if (nextWeight > 0) return true;
  if (!options.allowEmpty) return false;
  if (options.forceEmpty) return true;
  return manualStateWeight(currentValue) === 0;
}

function manualStateBackupKey(date = dateInput.value || formatDate(new Date())) {
  return `${MANUAL_STATE_BACKUP_KEY}:${date || formatDate(new Date())}`;
}

function manualStateSyncKey(date = dateInput.value || formatDate(new Date())) {
  return `${MANUAL_STATE_SYNC_KEY}:${date || formatDate(new Date())}`;
}

function readManualStateBackup(date = dateInput.value || formatDate(new Date())) {
  try {
    const parsed = JSON.parse(localStorage.getItem(manualStateBackupKey(date)) || '{}');
    return parsed && typeof parsed === 'object' ? parsed : {};
  } catch {
    return {};
  }
}

function readManualStateMirror(date = dateInput.value || formatDate(new Date())) {
  try {
    const parsed = JSON.parse(localStorage.getItem(MANUAL_STATE_MIRROR_KEY) || '{}');
    return parsed?.[date] && typeof parsed[date] === 'object' ? parsed[date] : {};
  } catch {
    return {};
  }
}

function readManualStateDurable(date = dateInput.value || formatDate(new Date())) {
  try {
    const parsed = JSON.parse(localStorage.getItem(MANUAL_STATE_DURABLE_KEY) || '{}');
    return parsed?.[date] && typeof parsed[date] === 'object' ? parsed[date] : {};
  } catch {
    return {};
  }
}

function readManualStateSyncSnapshot(date = dateInput.value || formatDate(new Date())) {
  try {
    const selectedDate = String(date || dateInput.value || formatDate(new Date()));
    const parsed = JSON.parse(localStorage.getItem(manualStateSyncKey(selectedDate)) || '{}');
    if (!parsed || typeof parsed !== 'object' || String(parsed.date || selectedDate) !== selectedDate) return {};
    return parsed;
  } catch {
    return {};
  }
}

function normalizeManualStatePatchField(key = '', value = []) {
  if (key === 'trackedPlayers') return normalizeTrackedPlayerEntries(value);
  if (key === 'pendingGamePicks') return normalizePendingGamePickEntries(value);
  if (key === 'overUnderScoreboards') return normalizeOverUnderScoreboardEntries(value);
  if (key === 'tossupScoreboards' || key === 'lockedTossupScoreboards') {
    return listify(value).map((item) => String(item || '')).filter(Boolean);
  }
  return value;
}

function writeManualStateDurablePatch(patch = {}, date = dateInput.value || formatDate(new Date()), options = {}) {
  try {
    const targetDate = String(date || dateInput.value || formatDate(new Date()));
    const store = JSON.parse(localStorage.getItem(MANUAL_STATE_DURABLE_KEY) || '{}') || {};
    const current = store[targetDate] && typeof store[targetDate] === 'object' ? store[targetDate] : {};
    const next = { ...current };
    let changed = false;
    for (const key of ['trackedPlayers', 'pendingGamePicks', 'tossupScoreboards', 'lockedTossupScoreboards', 'overUnderScoreboards']) {
      if (!hasOwnManualStateField(patch, key)) continue;
      const normalized = normalizeManualStatePatchField(key, patch[key]);
      if (shouldWriteManualStateField(current[key], normalized, options)) {
        next[key] = normalized;
        changed = true;
      }
    }
    if (!changed) return;
    store[targetDate] = { ...next, updatedAt: Date.now() };
    localStorage.setItem(MANUAL_STATE_DURABLE_KEY, JSON.stringify(store));
  } catch {}
}

function chooseManualStateFieldValue(date, field, normalizer = (value) => value) {
  const candidates = [];
  const remember = (source) => {
    if (!hasOwnManualStateField(source, field)) return;
    const value = normalizer(source[field]);
    candidates.push(manualStateCandidate(value, source?.updatedAt, 'stored'));
  };
  const activeValue = activeManualStateFieldValue(date, field, normalizer);
  if (activeValue !== null) candidates.push(manualStateCandidate(activeValue, Date.now(), 'active'));
  if (field === 'trackedPlayers') {
    const directTracked = readTrackedPlayersStore(date);
    if (directTracked !== null) {
      const trackedKey = trackedPlayersStorageKey(date);
      const updatedAt = syncMetaUpdatedAt(trackedKey);
      if (directTracked.length || updatedAt >= trackedPlayersBackupUpdatedAt(date)) {
        candidates.push(manualStateCandidate(normalizer(directTracked), updatedAt, 'tracked-date-key'));
      }
    }
  }
  remember(readManualStateMirror(date));
  remember(readManualStateBackup(date));
  remember(readManualStateDurable(date));
  try {
    const sessionState = JSON.parse(sessionStorage.getItem(manualStateBackupKey(date)) || '{}');
    remember(sessionState);
  } catch {}
  if (!candidates.length) return null;
  candidates.sort(field === 'trackedPlayers' ? compareTrackedPlayerStateCandidates : compareManualStateCandidates);
  return candidates[0].value;
}

function writeManualStateMirrorPatch(patch = {}, date = dateInput.value || formatDate(new Date()), options = {}) {
  try {
    const targetDate = String(date || dateInput.value || formatDate(new Date()));
    const parsed = JSON.parse(localStorage.getItem(MANUAL_STATE_MIRROR_KEY) || '{}') || {};
    const current = parsed?.[targetDate] && typeof parsed[targetDate] === 'object' ? parsed[targetDate] : {};
    const next = { ...current };
    let changed = false;
    for (const key of ['trackedPlayers', 'pendingGamePicks', 'tossupScoreboards', 'lockedTossupScoreboards', 'overUnderScoreboards']) {
      if (!hasOwnManualStateField(patch, key)) continue;
      const normalized = normalizeManualStatePatchField(key, patch[key]);
      if (shouldWriteManualStateField(current[key], normalized, options)) {
        next[key] = normalized;
        changed = true;
      }
    }
    if (!changed) return;
    localStorage.setItem(MANUAL_STATE_MIRROR_KEY, JSON.stringify({
      ...parsed,
      [targetDate]: { ...next, updatedAt: Date.now() },
    }));
  } catch {}
}

function writeManualStateBackupPatch(patch = {}, date = dateInput.value || formatDate(new Date()), options = {}) {
  try {
    const current = readManualStateBackup(date);
    const next = { ...current };
    let changed = false;
    for (const key of ['trackedPlayers', 'pendingGamePicks', 'tossupScoreboards', 'lockedTossupScoreboards', 'overUnderScoreboards']) {
      if (!hasOwnManualStateField(patch, key)) continue;
      const normalized = normalizeManualStatePatchField(key, patch[key]);
      if (shouldWriteManualStateField(current[key], normalized, options)) {
        next[key] = normalized;
        changed = true;
      }
    }
    if (changed) localStorage.setItem(manualStateBackupKey(date), JSON.stringify({ ...next, updatedAt: Date.now() }));
  } catch {}
  writeManualStateMirrorPatch(patch, date, options);
  writeManualStateDurablePatch(patch, date, options);
  try {
    const current = JSON.parse(sessionStorage.getItem(manualStateBackupKey(date)) || '{}');
    const next = { ...current };
    let changed = false;
    for (const key of ['trackedPlayers', 'pendingGamePicks', 'tossupScoreboards', 'lockedTossupScoreboards', 'overUnderScoreboards']) {
      if (!hasOwnManualStateField(patch, key)) continue;
      const normalized = normalizeManualStatePatchField(key, patch[key]);
      if (shouldWriteManualStateField(current[key], normalized, options)) {
        next[key] = normalized;
        changed = true;
      }
    }
    if (changed) sessionStorage.setItem(manualStateBackupKey(date), JSON.stringify({ ...next, updatedAt: Date.now() }));
  } catch {}
}

function writePendingGamePickStore(picks, options = {}) {
  const cleanPicks = normalizePendingGamePickEntries(picks);
  const selectedDate = String(options.date || dateInput.value || formatDate(new Date()));
  const dateKey = `${PENDING_GAME_PICKS_STORAGE_KEY}:${selectedDate}`;
  try {
    localStorage.setItem(dateKey, JSON.stringify(cleanPicks));
    localStorage.setItem(PENDING_GAME_PICKS_STORAGE_KEY, JSON.stringify(cleanPicks));
  } catch {}
  manualStateInMemoryDate = selectedDate;
  if (options.backup !== false && (cleanPicks.length || options.allowEmpty)) {
    writeManualStateBackupPatch({ pendingGamePicks: cleanPicks }, selectedDate, { allowEmpty: options.allowEmpty, forceEmpty: options.forceEmpty });
  }
}

function savePendingGamePicks(options = {}) {
  const picks = normalizePendingGamePickEntries([...pendingGamePickSelections.entries()]);
  writePendingGamePickStore(picks, options);
}

function restorePendingGamePicks(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const picks = readPendingGamePickStore(selectedDate);
  if (!picks.length && pendingGamePickSelections.size) {
    if (activeManualStateDateMatches(selectedDate)) savePendingGamePicks({ backup: false, date: selectedDate });
    return;
  }
  const restored = new Map(
    (Array.isArray(picks) ? picks : [])
      .map(([key, side]) => [String(key), normalizeGamePickSide(side)])
      .filter(([key, side]) => key && side),
  );
  if (activeManualStateDateMatches(selectedDate)) {
    for (const [key, side] of pendingGamePickSelections.entries()) {
      const normalizedSide = normalizeGamePickSide(side);
      if (key && normalizedSide) restored.set(String(key), normalizedSide);
    }
  }
  pendingGamePickSelections = restored;
  manualStateInMemoryDate = selectedDate;
}

function pendingGamePickSideForGame(game) {
  for (const key of manualGameStateKeysForGame(game)) {
    const side = normalizeGamePickSide(pendingGamePickSelections.get(key));
    if (side) return side;
  }
  for (const [key, sideValue] of pendingGamePickSelections.entries()) {
    const side = normalizeGamePickSide(sideValue);
    if (side && gameForManualStateKey(key, [game])) return side;
  }
  return '';
}


function normalizeOverUnderSide(side = '') {
  const normalized = String(side || '').toLowerCase();
  if (normalized === 'over' || normalized === 'o' || normalized === 'up') return 'over';
  if (normalized === 'under' || normalized === 'u' || normalized === 'down') return 'under';
  return '';
}

function overUnderScoreboardStorageKey(date = dateInput.value || formatDate(new Date())) {
  return `${OVER_UNDER_SCOREBOARD_STORAGE_KEY}:${date || formatDate(new Date())}`;
}

function normalizeOverUnderScoreboardEntries(entries = []) {
  return listify(entries)
    .map((entry) => {
      if (Array.isArray(entry)) {
        const key = String(entry[0] || '');
        const side = normalizeOverUnderSide(entry[1]);
        const locked = Boolean(entry[2] === true || entry[2] === 'lock' || entry[3] === true || entry[3] === 'lock');
        return key && side ? { key, side, locked } : null;
      }
      if (entry && typeof entry === 'object') {
        const key = String(entry.key || entry.gamePk || entry.gameKey || entry.id || '');
        const side = normalizeOverUnderSide(entry.side || entry.pick || entry.type || entry.value);
        const locked = Boolean(entry.locked || entry.state === 'lock' || entry.status === 'lock');
        return key && side ? { key, side, locked } : null;
      }
      return null;
    })
    .filter(Boolean);
}

function serializeOverUnderScoreboards() {
  return [...overUnderScoreboardSelections.entries()]
    .map(([key, value]) => ({
      key: String(key || ''),
      side: normalizeOverUnderSide(value?.side),
      locked: Boolean(value?.locked),
    }))
    .filter((entry) => entry.key && entry.side);
}

function readOverUnderScoreboardStore(date = dateInput.value || formatDate(new Date())) {
  const candidates = [];
  const remember = (value, updatedAt = 0) => {
    const items = normalizeOverUnderScoreboardEntries(value);
    if (items.length) candidates.push({ items, updatedAt: Number(updatedAt) || 0 });
  };
  try {
    remember(JSON.parse(localStorage.getItem(overUnderScoreboardStorageKey(date)) || '[]'));
  } catch {}
  const backupState = readManualStateBackup(date);
  const mirrorState = readManualStateMirror(date);
  const durableState = readManualStateDurable(date);
  remember(backupState.overUnderScoreboards, backupState.updatedAt);
  remember(mirrorState.overUnderScoreboards, mirrorState.updatedAt);
  remember(durableState.overUnderScoreboards, durableState.updatedAt);
  try {
    const sessionState = JSON.parse(sessionStorage.getItem(manualStateBackupKey(date)) || '{}');
    remember(sessionState?.overUnderScoreboards, sessionState?.updatedAt);
  } catch {}
  const best = candidates
    .map((candidate) => manualStateCandidate(candidate.items, candidate.updatedAt, 'over-under-store'))
    .sort(compareManualStateCandidates)[0]?.value || [];
  if (best.length) {
    try { localStorage.setItem(overUnderScoreboardStorageKey(date), JSON.stringify(best)); } catch {}
  }
  return best;
}

function saveOverUnderScoreboards(date = dateInput.value || formatDate(new Date()), options = {}) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const values = serializeOverUnderScoreboards();
  try {
    localStorage.setItem(overUnderScoreboardStorageKey(selectedDate), JSON.stringify(values));
  } catch {}
  manualStateInMemoryDate = selectedDate;
  if (values.length || options.allowEmpty) writeManualStateBackupPatch({ overUnderScoreboards: values }, selectedDate, { allowEmpty: options.allowEmpty, forceEmpty: options.forceEmpty });
}

function restoreOverUnderScoreboards(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const stored = readOverUnderScoreboardStore(selectedDate);
  if (!stored.length && overUnderScoreboardSelections.size) {
    if (activeManualStateDateMatches(selectedDate)) saveOverUnderScoreboards(selectedDate);
    return;
  }
  overUnderScoreboardSelections.clear();
  stored.forEach((entry) => {
    const side = normalizeOverUnderSide(entry.side);
    if (entry.key && side) overUnderScoreboardSelections.set(String(entry.key), { side, locked: Boolean(entry.locked) });
  });
  manualStateInMemoryDate = selectedDate;
}

function overUnderScoreboardEntryForGame(game) {
  for (const key of manualGameStateKeysForGame(game)) {
    const entry = overUnderScoreboardSelections.get(key);
    if (normalizeOverUnderSide(entry?.side)) return entry;
  }
  for (const [key, entry] of overUnderScoreboardSelections.entries()) {
    if (gameForManualStateKey(key, [game]) && normalizeOverUnderSide(entry?.side)) return entry;
  }
  return null;
}

function overUnderScoreboardStateForGame(game) {
  const entry = overUnderScoreboardEntryForGame(game);
  const side = normalizeOverUnderSide(entry?.side);
  const locked = Boolean(entry?.locked);
  return {
    side,
    state: side ? (locked ? 'lock' : 'tossup') : 'default',
    locked,
  };
}

function overUnderButtonTitle(side = '', selected = false, locked = false) {
  const label = normalizeOverUnderSide(side) === 'over' ? 'over' : 'under';
  if (locked) return `Locked ${label}. Click to clear.`;
  if (selected) return `${label[0].toUpperCase()}${label.slice(1)} marked. Click to lock.`;
  return `Mark ${label}`;
}

function createLineupOverUnderButton(side = '') {
  const normalized = normalizeOverUnderSide(side);
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = `lineup-ou-btn lineup-ou-${normalized}`.trim();
  btn.dataset.overUnderSide = normalized;
  btn.textContent = normalized === 'over' ? '↑' : '↓';
  btn.setAttribute('aria-label', normalized === 'over' ? 'Mark over' : 'Mark under');
  btn.setAttribute('aria-pressed', 'false');
  return btn;
}

function syncOverUnderControlsForGame(root, game, pregame = shouldPreferProbablePitcher(game)) {
  if (!root) return;
  const state = overUnderScoreboardStateForGame(game);
  const selectedSide = state.side;
  const locked = state.locked;
  root.querySelectorAll?.('.score-mini-context')?.forEach((context) => {
    context.classList.toggle('has-over-under', Boolean(pregame));
  });
  root.querySelectorAll?.('.score-mini-over-under')?.forEach((wrap) => {
    wrap.hidden = !pregame;
    wrap.classList.toggle('has-over-under-selection', Boolean(pregame && selectedSide));
    wrap.classList.toggle('is-over-under-locked', Boolean(pregame && locked));
  });
  root.querySelectorAll?.('.score-mini-ou-btn[data-over-under-side], .lineup-ou-btn[data-over-under-side]')?.forEach((btn) => {
    const side = normalizeOverUnderSide(btn.dataset.overUnderSide);
    const selected = Boolean(pregame && side && selectedSide === side);
    const isLocked = Boolean(selected && locked);
    btn.hidden = !pregame;
    btn.classList.toggle('is-selected', selected);
    btn.classList.toggle('is-locked', isLocked);
    btn.setAttribute('aria-pressed', isLocked ? 'mixed' : selected ? 'true' : 'false');
    btn.setAttribute('title', pregame ? overUnderButtonTitle(side, selected, isLocked) : '');
  });
}

function syncOverUnderScoreboardStates(games = latestRenderedGames) {
  for (const game of games || []) {
    const card = cardForGamePk(game?.gamePk);
    const state = overUnderScoreboardStateForGame(game);
    const scoreboard = card?.querySelector('.scoreboard');
    scoreboard?.classList.toggle('has-over-under-selection', Boolean(state.side));
    scoreboard?.classList.toggle('is-over-under-locked', Boolean(state.locked));
    if (scoreboard) {
      scoreboard.dataset.overUnderSelectedSide = state.side || '';
      scoreboard.removeAttribute('data-over-under-side');
    }
    syncOverUnderControlsForGame(card, game, shouldPreferProbablePitcher(game));
  }
  if (activeLineupGame) syncOverUnderControlsForGame(lineupOverlayEl, activeLineupGame, shouldPreferProbablePitcher(activeLineupGame));
}

function setOverUnderScoreboardState(gamePk, side = '', state = 'default') {
  const normalizedSide = normalizeOverUnderSide(side);
  const normalizedState = state === 'lock' ? 'lock' : state === 'tossup' ? 'tossup' : 'default';
  const game = gameForManualStateKey(gamePk);
  const key = manualGameStateKey(game || gamePk);
  if (!key) return false;
  const aliases = game ? manualGameStateKeysForGame(game) : [String(gamePk || '')].filter(Boolean);
  aliases.forEach((alias) => overUnderScoreboardSelections.delete(alias));
  if (normalizedSide && normalizedState !== 'default') {
    overUnderScoreboardSelections.set(key, { side: normalizedSide, locked: normalizedState === 'lock' });
  }
  saveOverUnderScoreboards(undefined, { allowEmpty: true, forceEmpty: !overUnderScoreboardSelections.size });
  const liveGame = game || gameForManualStateKey(key) || activeLineupGame || null;
  const card = cardForGamePk(liveGame?.gamePk || gamePk);
  if (card && liveGame) syncOverUnderControlsForGame(card, liveGame, shouldPreferProbablePitcher(liveGame));
  if (activeLineupGame && String(activeLineupGame.gamePk || '') === String(liveGame?.gamePk || gamePk || '')) {
    syncOverUnderControlsForGame(lineupOverlayEl, activeLineupGame, shouldPreferProbablePitcher(activeLineupGame));
  }
  syncOverUnderScoreboardStates(liveGame ? [liveGame] : latestRenderedGames);
  return true;
}

function toggleOverUnderScoreboardMarked(gamePk, side = '') {
  const normalizedSide = normalizeOverUnderSide(side);
  if (!normalizedSide) return false;
  const game = gameForManualStateKey(gamePk);
  const current = game ? overUnderScoreboardStateForGame(game) : (() => {
    const entry = overUnderScoreboardSelections.get(String(gamePk || ''));
    const entrySide = normalizeOverUnderSide(entry?.side);
    return { side: entrySide, locked: Boolean(entry?.locked), state: entrySide ? (entry?.locked ? 'lock' : 'tossup') : 'default' };
  })();
  let next = 'tossup';
  if (current.side === normalizedSide) next = current.state === 'default' ? 'tossup' : current.state === 'tossup' ? 'lock' : 'default';
  return setOverUnderScoreboardState(gamePk, normalizedSide, next);
}

function tossupScoreboardStorageKey(date = dateInput.value || formatDate(new Date())) {
  return `${TOSSUP_SCOREBOARD_STORAGE_KEY}:${date || formatDate(new Date())}`;
}


function lockedTossupScoreboardStorageKey(date = dateInput.value || formatDate(new Date())) {
  return `${LOCKED_TOSSUP_SCOREBOARD_STORAGE_KEY}:${date || formatDate(new Date())}`;
}

function readLockedTossupScoreboardStore(date = dateInput.value || formatDate(new Date())) {
  const candidates = [];
  const remember = (value, updatedAt = 0) => {
    if (!Array.isArray(value)) return;
    const items = value.map((gamePk) => String(gamePk)).filter(Boolean);
    if (items.length) candidates.push({ items, updatedAt: Number(updatedAt) || 0 });
  };
  try {
    const parsed = JSON.parse(localStorage.getItem(lockedTossupScoreboardStorageKey(date)) || '[]');
    remember(parsed);
  } catch {}
  const backupState = readManualStateBackup(date);
  const mirrorState = readManualStateMirror(date);
  const durableState = readManualStateDurable(date);
  remember(backupState.lockedTossupScoreboards, backupState.updatedAt);
  remember(mirrorState.lockedTossupScoreboards, mirrorState.updatedAt);
  remember(durableState.lockedTossupScoreboards, durableState.updatedAt);
  const best = candidates
    .map((candidate) => manualStateCandidate(candidate.items, candidate.updatedAt, 'locked-tossup-store'))
    .sort(compareManualStateCandidates)[0]?.value || [];
  if (best.length) {
    try { localStorage.setItem(lockedTossupScoreboardStorageKey(date), JSON.stringify(best)); } catch {}
  }
  return best;
}

function saveLockedTossupScoreboards(date = dateInput.value || formatDate(new Date()), options = {}) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const values = [...lockedTossupScoreboardGamePks];
  try {
    localStorage.setItem(lockedTossupScoreboardStorageKey(selectedDate), JSON.stringify(values));
  } catch {}
  manualStateInMemoryDate = selectedDate;
  if (values.length || options.allowEmpty) writeManualStateBackupPatch({ lockedTossupScoreboards: values }, selectedDate, { allowEmpty: options.allowEmpty, forceEmpty: options.forceEmpty });
}

function lockedTossupScoreboardMarkedForGame(game) {
  return manualGameStateKeysForGame(game).some((key) => lockedTossupScoreboardGamePks.has(key) && tossupScoreboardGamePks.has(key));
}

function unlockedTossupScoreboardMarkedForGame(game) {
  return manualGameStateKeysForGame(game).some((key) => lockedTossupScoreboardGamePks.has(key) && !tossupScoreboardGamePks.has(key));
}

function tossupScoreboardStateForGame(game) {
  const keys = manualGameStateKeysForGame(game);
  const hasTossup = keys.some((key) => tossupScoreboardGamePks.has(key));
  const hasLocked = keys.some((key) => lockedTossupScoreboardGamePks.has(key));
  if (hasTossup && hasLocked) return 'lock';
  if (hasLocked) return 'unlock';
  return hasTossup ? 'tossup' : 'default';
}

function readTossupScoreboardStore(date = dateInput.value || formatDate(new Date())) {
  const candidates = [];
  const remember = (value, updatedAt = 0) => {
    if (!Array.isArray(value)) return;
    const items = value.map((gamePk) => String(gamePk)).filter(Boolean);
    if (items.length) candidates.push({ items, updatedAt: Number(updatedAt) || 0 });
  };
  try {
    remember(JSON.parse(localStorage.getItem(tossupScoreboardStorageKey(date)) || '[]'));
  } catch {}
  const backupState = readManualStateBackup(date);
  const mirrorState = readManualStateMirror(date);
  const durableState = readManualStateDurable(date);
  remember(backupState.tossupScoreboards, backupState.updatedAt);
  remember(mirrorState.tossupScoreboards, mirrorState.updatedAt);
  remember(durableState.tossupScoreboards, durableState.updatedAt);
  const best = candidates
    .map((candidate) => manualStateCandidate(candidate.items, candidate.updatedAt, 'tossup-store'))
    .sort(compareManualStateCandidates)[0]?.value || [];
  if (best.length) {
    try { localStorage.setItem(tossupScoreboardStorageKey(date), JSON.stringify(best)); } catch {}
    writeManualStateBackupPatch({ tossupScoreboards: best }, date);
  }
  return best;
}

function saveTossupScoreboards(date = dateInput.value || formatDate(new Date()), options = {}) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const values = [...tossupScoreboardGamePks];
  try {
    localStorage.setItem(tossupScoreboardStorageKey(selectedDate), JSON.stringify(values));
  } catch {}
  manualStateInMemoryDate = selectedDate;
  if (values.length || options.allowEmpty) writeManualStateBackupPatch({ tossupScoreboards: values }, selectedDate, { allowEmpty: options.allowEmpty, forceEmpty: options.forceEmpty });
}

function restoreTossupScoreboards(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const stored = readTossupScoreboardStore(selectedDate);
  if (!stored.length && tossupScoreboardGamePks.size) {
    saveTossupScoreboards(selectedDate);
    return;
  }
  tossupScoreboardGamePks.clear();
  stored.forEach((gamePk) => tossupScoreboardGamePks.add(String(gamePk)));
  const lockedStored = readLockedTossupScoreboardStore(selectedDate);
  if (!lockedStored.length && lockedTossupScoreboardGamePks.size) {
    saveLockedTossupScoreboards(selectedDate);
  } else {
    lockedTossupScoreboardGamePks.clear();
    lockedStored.forEach((gamePk) => lockedTossupScoreboardGamePks.add(String(gamePk)));
  }
  manualStateInMemoryDate = selectedDate;
}


function tossupScoreboardMarkedForGame(game) {
  return manualGameStateKeysForGame(game).some((key) => tossupScoreboardGamePks.has(key));
}

function syncTossupScoreboardStates(games = latestRenderedGames) {
  for (const game of games || []) {
    const card = cardForGamePk(game?.gamePk);
    const scoreboard = card?.querySelector('.scoreboard');
    const state = tossupScoreboardStateForGame(game);
    const tossup = state === 'tossup';
    const unlocked = state === 'unlock';
    const locked = state === 'lock';
    scoreboard?.classList.toggle('is-tossup-marked', tossup);
    scoreboard?.classList.toggle('is-tossup-unlocked', unlocked);
    scoreboard?.classList.toggle('is-tossup-locked', locked);
    card?.querySelectorAll('.score-mini-inning.is-pregame-toggle')?.forEach((el) => {
      el.classList.toggle('is-tossup-unlocked', unlocked);
      el.classList.toggle('is-tossup-locked', locked);
      el.setAttribute('aria-pressed', locked ? 'mixed' : (tossup || unlocked) ? 'true' : 'false');
      el.setAttribute('title', locked ? 'Locked. Click to clear.' : unlocked ? 'Nearly locked. Click to lock.' : tossup ? 'Tossup marked. Click for near-lock.' : 'Mark this pregame as a tossup');
    });
  }
}

function normalizeManualGameStateForGames(games = latestRenderedGames, date = dateInput.value || formatDate(new Date())) {
  let picksChanged = false;
  let tossupsChanged = false;
  let overUnderChanged = false;
  for (const game of listify(games)) {
    const stableKey = manualGameStateKey(game, date);
    if (!stableKey) continue;
    const aliases = manualGameStateKeysForGame(game, date);
    const pickedSide = aliases.map((key) => normalizeGamePickSide(pendingGamePickSelections.get(key))).find(Boolean);
    if (pickedSide) {
      for (const key of aliases) {
        if (pendingGamePickSelections.get(key) !== pickedSide) {
          pendingGamePickSelections.set(key, pickedSide);
          picksChanged = true;
        }
      }
    }
    const marked = aliases.some((key) => tossupScoreboardGamePks.has(key));
    if (marked) {
      for (const key of aliases) {
        if (key !== stableKey && tossupScoreboardGamePks.delete(key)) tossupsChanged = true;
      }
      if (!tossupScoreboardGamePks.has(stableKey)) {
        tossupScoreboardGamePks.add(stableKey);
        tossupsChanged = true;
      }
    }
    const locked = aliases.some((key) => lockedTossupScoreboardGamePks.has(key));
    if (locked) {
      for (const key of aliases) {
        if (key !== stableKey && lockedTossupScoreboardGamePks.delete(key)) tossupsChanged = true;
      }
      if (!lockedTossupScoreboardGamePks.has(stableKey)) {
        lockedTossupScoreboardGamePks.add(stableKey);
        tossupsChanged = true;
      }
    }
    const overUnderEntry = aliases.map((key) => overUnderScoreboardSelections.get(key)).find((entry) => normalizeOverUnderSide(entry?.side));
    if (overUnderEntry) {
      for (const key of aliases) {
        if (key !== stableKey && overUnderScoreboardSelections.delete(key)) overUnderChanged = true;
      }
      const current = overUnderScoreboardSelections.get(stableKey);
      const normalizedSide = normalizeOverUnderSide(overUnderEntry.side);
      const normalizedLocked = Boolean(overUnderEntry.locked);
      if (!current || current.side !== normalizedSide || Boolean(current.locked) !== normalizedLocked) {
        overUnderScoreboardSelections.set(stableKey, { side: normalizedSide, locked: normalizedLocked });
        overUnderChanged = true;
      }
    }
  }
  if (picksChanged) savePendingGamePicks();
  if (tossupsChanged) {
    saveTossupScoreboards(date);
    saveLockedTossupScoreboards(date, { allowEmpty: true });
  }
  if (overUnderChanged) saveOverUnderScoreboards(date, { allowEmpty: true });
}

let manualStateCrossDeviceFingerprint = '';

function hasOwnManualStateField(source = {}, key = '') {
  return Boolean(source && Object.prototype.hasOwnProperty.call(source, key));
}

function reconcileCrossDeviceManualState(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const patch = {};
  const tracked = chooseManualStateFieldValue(selectedDate, 'trackedPlayers', normalizeTrackedPlayerEntries);
  const trackedBackup = tracked === null ? readTrackedPlayersBackup(selectedDate) : [];
  const pending = chooseManualStateFieldValue(selectedDate, 'pendingGamePicks', normalizePendingGamePickEntries);
  const tossups = chooseManualStateFieldValue(selectedDate, 'tossupScoreboards', (value) => listify(value).map((key) => String(key)).filter(Boolean));
  const locked = chooseManualStateFieldValue(selectedDate, 'lockedTossupScoreboards', (value) => listify(value).map((key) => String(key)).filter(Boolean));
  const overUnder = chooseManualStateFieldValue(selectedDate, 'overUnderScoreboards', normalizeOverUnderScoreboardEntries);
  if (tracked !== null) patch.trackedPlayers = tracked;
  else if (trackedBackup.length) patch.trackedPlayers = trackedBackup;
  if (pending !== null) patch.pendingGamePicks = pending;
  if (tossups !== null) patch.tossupScoreboards = tossups;
  if (locked !== null) patch.lockedTossupScoreboards = locked;
  if (overUnder !== null) patch.overUnderScoreboards = overUnder;
  if (!Object.keys(patch).length) return false;
  const fingerprint = JSON.stringify({ date: selectedDate, ...patch });
  if (fingerprint === manualStateCrossDeviceFingerprint) return false;
  manualStateCrossDeviceFingerprint = fingerprint;
  if (hasOwnManualStateField(patch, 'trackedPlayers')) {
    const trackedKey = trackedPlayersStorageKey(selectedDate);
    const normalizedTracked = normalizeTrackedPlayerEntries(patch.trackedPlayers);
    trackedPlayersMemoryByDate.set(trackedKey, normalizedTracked);
    try { localStorage.setItem(trackedKey, JSON.stringify(normalizedTracked)); } catch {}
    writeTrackedPlayersBackup(normalizedTracked, selectedDate);
    if (playerTrackerListEl) playerTrackerListEl.dataset.renderFingerprint = '';
  }
  if (hasOwnManualStateField(patch, 'pendingGamePicks')) pendingGamePickSelections = new Map(patch.pendingGamePicks);
  if (hasOwnManualStateField(patch, 'tossupScoreboards')) {
    tossupScoreboardGamePks.clear();
    patch.tossupScoreboards.forEach((key) => tossupScoreboardGamePks.add(String(key)));
  }
  if (hasOwnManualStateField(patch, 'lockedTossupScoreboards')) {
    lockedTossupScoreboardGamePks.clear();
    patch.lockedTossupScoreboards.forEach((key) => lockedTossupScoreboardGamePks.add(String(key)));
  }
  if (hasOwnManualStateField(patch, 'overUnderScoreboards')) {
    overUnderScoreboardSelections.clear();
    normalizeOverUnderScoreboardEntries(patch.overUnderScoreboards).forEach((entry) => overUnderScoreboardSelections.set(String(entry.key), { side: entry.side, locked: Boolean(entry.locked) }));
  }
  manualStateInMemoryDate = selectedDate;
  writeManualStateBackupPatch(patch, selectedDate);
  normalizeManualGameStateForGames(latestRenderedGames, selectedDate);
  renderPlayerTrackerList(latestRenderedGames);
  renderPendingGamePicks(latestRenderedGames);
  syncAllCardGamePickStates(latestRenderedGames);
  syncTossupScoreboardStates(latestRenderedGames);
  syncOverUnderScoreboardStates(latestRenderedGames);
  if (activeLineupGame) syncLineupGamePickState(activeLineupGame);
  return true;
}

function initCrossDeviceManualStateSync() {
  // Cross-device state now moves only through the explicit Push/Pull sync controls.
}

function currentManualStatePatchForSync(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const trackedKey = trackedPlayersStorageKey(selectedDate);
  const tracked = trackedPlayersMemoryByDate.has(trackedKey)
    ? normalizeTrackedPlayerEntries(trackedPlayersMemoryByDate.get(trackedKey) || [])
    : normalizeTrackedPlayerEntries(getTrackedPlayers(selectedDate));
  return {
    trackedPlayers: tracked,
    pendingGamePicks: normalizePendingGamePickEntries([...pendingGamePickSelections.entries()]),
    tossupScoreboards: [...tossupScoreboardGamePks].map((key) => String(key)).filter(Boolean),
    lockedTossupScoreboards: [...lockedTossupScoreboardGamePks].map((key) => String(key)).filter(Boolean),
    overUnderScoreboards: normalizeOverUnderScoreboardEntries(serializeOverUnderScoreboards()),
  };
}

function writeManualStateSyncSnapshot(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const snapshot = {
    date: selectedDate,
    updatedAt: Date.now(),
    ...currentManualStatePatchForSync(selectedDate),
  };
  try {
    localStorage.setItem(manualStateSyncKey(selectedDate), JSON.stringify(snapshot));
  } catch {}
  writeManualStateBackupPatch(snapshot, selectedDate, { allowEmpty: true, forceEmpty: true });
  return snapshot;
}

function applyManualStateSnapshot(snapshot = {}, date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(snapshot?.date || date || dateInput.value || formatDate(new Date()));
  if (!snapshot || typeof snapshot !== 'object') return false;
  const hasAny = ['trackedPlayers', 'pendingGamePicks', 'tossupScoreboards', 'lockedTossupScoreboards', 'overUnderScoreboards']
    .some((key) => hasOwnManualStateField(snapshot, key));
  if (!hasAny) return false;

  const tracked = normalizeTrackedPlayerEntries(snapshot.trackedPlayers || []);
  const pending = normalizePendingGamePickEntries(snapshot.pendingGamePicks || []);
  const tossups = listify(snapshot.tossupScoreboards).map((key) => String(key)).filter(Boolean);
  const locked = listify(snapshot.lockedTossupScoreboards).map((key) => String(key)).filter(Boolean);
  const overUnder = normalizeOverUnderScoreboardEntries(snapshot.overUnderScoreboards || []);

  pendingGamePickSelections = new Map(pending);
  tossupScoreboardGamePks.clear();
  tossups.forEach((key) => tossupScoreboardGamePks.add(String(key)));
  lockedTossupScoreboardGamePks.clear();
  locked.forEach((key) => lockedTossupScoreboardGamePks.add(String(key)));
  overUnderScoreboardSelections.clear();
  overUnder.forEach((entry) => overUnderScoreboardSelections.set(String(entry.key), { side: entry.side, locked: Boolean(entry.locked) }));

  saveTrackedPlayers(tracked, selectedDate, { allowEmpty: true, forceEmpty: !tracked.length });
  savePendingGamePicks({ allowEmpty: true, forceEmpty: !pendingGamePickSelections.size, date: selectedDate });
  saveTossupScoreboards(selectedDate, { allowEmpty: true, forceEmpty: !tossupScoreboardGamePks.size });
  saveLockedTossupScoreboards(selectedDate, { allowEmpty: true, forceEmpty: !lockedTossupScoreboardGamePks.size });
  saveOverUnderScoreboards(selectedDate, { allowEmpty: true, forceEmpty: !overUnderScoreboardSelections.size });
  try {
    localStorage.setItem(manualStateSyncKey(selectedDate), JSON.stringify({ date: selectedDate, updatedAt: Number(snapshot.updatedAt) || Date.now(), trackedPlayers: tracked, pendingGamePicks: pending, tossupScoreboards: tossups, lockedTossupScoreboards: locked, overUnderScoreboards: overUnder }));
  } catch {}
  manualStateInMemoryDate = selectedDate;
  return true;
}

function snapshotManualStateForSync(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const trackedKey = trackedPlayersStorageKey(selectedDate);
  persistManualStateSnapshot(selectedDate);
  savePendingGamePicks({
    allowEmpty: true,
    forceEmpty: !pendingGamePickSelections.size,
    date: selectedDate,
  });
  saveTossupScoreboards(selectedDate, {
    allowEmpty: true,
    forceEmpty: !tossupScoreboardGamePks.size,
  });
  saveLockedTossupScoreboards(selectedDate, {
    allowEmpty: true,
    forceEmpty: !lockedTossupScoreboardGamePks.size,
  });
  saveOverUnderScoreboards(selectedDate, {
    allowEmpty: true,
    forceEmpty: !overUnderScoreboardSelections.size,
  });
  if (trackedPlayersMemoryByDate.has(trackedKey)) {
    const tracked = normalizeTrackedPlayerEntries(trackedPlayersMemoryByDate.get(trackedKey) || []);
    saveTrackedPlayers(tracked, selectedDate, {
      allowEmpty: true,
      forceEmpty: !tracked.length,
    });
  } else {
    const tracked = normalizeTrackedPlayerEntries(getTrackedPlayers(selectedDate));
    if (tracked.length) saveTrackedPlayers(tracked, selectedDate);
  }
  writeManualStateSyncSnapshot(selectedDate);
}

function refreshManualStateAfterSync(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  manualStateInMemoryDate = '';
  manualStateCrossDeviceFingerprint = '';
  trackedPlayersMemoryByDate.delete(trackedPlayersStorageKey(selectedDate));
  const snapshotApplied = applyManualStateSnapshot(readManualStateSyncSnapshot(selectedDate), selectedDate);
  if (!snapshotApplied) reconcileCrossDeviceManualState(selectedDate);
  if (playerTrackerListEl) playerTrackerListEl.dataset.renderFingerprint = '';
  renderPlayerTrackerList(latestRenderedGames);
  refreshLineupTrackedPlayerHighlights();
  renderPendingGamePicks(latestRenderedGames);
  syncAllCardGamePickStates(latestRenderedGames);
  syncTossupScoreboardStates(latestRenderedGames);
  syncOverUnderScoreboardStates(latestRenderedGames);
  if (activeLineupGame) syncLineupGamePickState(activeLineupGame);
}

function syncChangedManualStateDates(keys = new Set(), fallbackDate = dateInput.value || formatDate(new Date())) {
  const dates = new Set([String(fallbackDate || dateInput.value || formatDate(new Date()))]);
  for (const key of keys || []) {
    const value = String(key || '');
    const match = value.match(/(?:manual-state-current:v1|manual-state-backup:v1|player-tracker:v1|pending-game-picks:v1|tossup-scoreboards:v1|locked-tossup-scoreboards:v1|over-under-scoreboards:v1):(\d{4}-\d{2}-\d{2})$/);
    if (match?.[1]) dates.add(match[1]);
  }
  return [...dates];
}

function refreshManualStateDatesAfterSync(keys = new Set(), fallbackDate = dateInput.value || formatDate(new Date())) {
  for (const syncDate of syncChangedManualStateDates(keys, fallbackDate)) {
    refreshManualStateAfterSync(syncDate);
  }
}

function initOwenToolsSoftSyncRefresh() {
  window.addEventListener('owentools:sync-before-push', () => {
    snapshotManualStateForSync();
  });
  window.addEventListener('owentools:sync-pulled', (event) => {
    refreshManualStateDatesAfterSync(new Set(listify(event?.detail?.changedKeys).map((key) => String(key || ''))));
  });
  window.addEventListener('owentools:sync-state-changed', (event) => {
    const selectedDate = dateInput.value || formatDate(new Date());
    const keys = new Set(listify(event?.detail?.changedKeys).map((key) => String(key || '')));
    const lineupWindowKeys = new Set([
      LINEUP_STAT_WINDOW_KEY,
      storageKey(LINEUP_STAT_WINDOW_KEY),
    ]);
    const playerSeasonRecentKeys = new Set([
      PLAYER_STAT_SEASON_RECENT_DAYS_KEY,
      storageKey(PLAYER_STAT_SEASON_RECENT_DAYS_KEY),
    ]);
    const manualKeys = new Set([
      MANUAL_STATE_MIRROR_KEY,
      MANUAL_STATE_DURABLE_KEY,
      PLAYER_TRACKER_STORAGE_KEY,
      PLAYER_TRACKER_BACKUP_STORAGE_KEY,
      trackedPlayersStorageKey(selectedDate),
      `${PENDING_GAME_PICKS_STORAGE_KEY}:${selectedDate}`,
      tossupScoreboardStorageKey(selectedDate),
      lockedTossupScoreboardStorageKey(selectedDate),
      overUnderScoreboardStorageKey(selectedDate),
      manualStateBackupKey(selectedDate),
      manualStateSyncKey(selectedDate),
    ]);
    const allChanged = keys.size === 0;
    if (allChanged || keys.has(ROTOWIRE_DYNAMIC_LINEUP_STORAGE_KEY)) {
      globalThis.ROTOWIRE_DYNAMIC_LINEUP_SOURCE_LOADED = false;
      invalidateRotowireLineupCachesForDate(selectedDate);
      nonLiveLineupRenderSignature = '';
      if (activeLineupGame) {
        syncLineupOverlay(activeLineupGame, { forceOpen: true }).catch(() => {});
      }
    }
    const manualChanged = allChanged || [...manualKeys].some((key) => keys.has(key));
    if (manualChanged) {
      manualStateInMemoryDate = '';
      manualStateCrossDeviceFingerprint = '';
    }
    if (allChanged || keys.has(trackedPlayersStorageKey(selectedDate)) || keys.has(PLAYER_TRACKER_STORAGE_KEY) || keys.has(PLAYER_TRACKER_BACKUP_STORAGE_KEY) || keys.has(MANUAL_STATE_MIRROR_KEY) || keys.has(MANUAL_STATE_DURABLE_KEY) || keys.has(manualStateBackupKey(selectedDate)) || keys.has(manualStateSyncKey(selectedDate))) {
      trackedPlayersMemoryByDate.delete(trackedPlayersStorageKey(selectedDate));
      if (playerTrackerListEl) playerTrackerListEl.dataset.renderFingerprint = '';
      renderPlayerTrackerList(latestRenderedGames);
    }
    if (manualChanged) {
      refreshManualStateDatesAfterSync(keys, selectedDate);
    }
    if (allChanged || [...lineupWindowKeys].some((key) => keys.has(key))) {
      const nextWindow = savedLineupStatWindow();
      if (nextWindow !== lineupStatGameWindow) {
        lineupStatGameWindow = nextWindow;
        nonLiveLineupRenderSignature = '';
        syncLineupStatWindowToggle();
        if (activeLineupGame) {
          syncLineupOverlay(activeLineupGame, { forceOpen: true }).catch(() => {});
        }
      }
    }
    if (allChanged || [...playerSeasonRecentKeys].some((key) => keys.has(key))) {
      const nextDays = savedPlayerStatSeasonRecentDays();
      if (nextDays !== playerStatSeasonRecentDays) {
        playerStatSeasonRecentDays = nextDays;
        if (activePlayerStatContext?.profile && activePlayerStatContext?.game && playerStatOverlayEl?.dataset?.playerRole !== 'pitcher') {
          renderPlayerBattingSeasonBlock(activePlayerStatContext.profile, activePlayerStatContext.game);
        }
      }
    }
  });
}

function clearCompletedPendingGamePicks(games = latestRenderedGames) {
  return false;
}

function clearPendingGamePicks({ render = true } = {}) {
  pendingGamePickSelections = new Map();
  savePendingGamePicks({ allowEmpty: true, forceEmpty: true });
  if (render) renderPendingGamePicks(latestRenderedGames);
}

function setPendingGamePick(game, side) {
  if (!game?.gamePk) return;
  const normalizedSide = normalizeGamePickSide(side);
  const key = manualGameStateKey(game);
  const aliases = manualGameStateKeysForGame(game);
  const existingSide = pendingGamePickSideForGame(game);
  aliases.forEach((alias) => pendingGamePickSelections.delete(alias));
  if (!normalizedSide) {
    // Manual clear only.
  } else if (existingSide === normalizedSide) {
    // Clicking the same team again is the manual off switch.
  } else {
    for (const alias of aliases) pendingGamePickSelections.set(alias, normalizedSide);
  }
  savePendingGamePicks({ allowEmpty: true, forceEmpty: !pendingGamePickSelections.size });
  renderPendingGamePicks(latestRenderedGames);
}

function closeGamePickDialog() {
  if (!gamePickDialogEl) return;
  if (typeof gamePickDialogEl.close === 'function') {
    try {
      gamePickDialogEl.close();
      return;
    } catch {}
  }
  gamePickDialogEl.removeAttribute('open');
}

function openGamePickDialog() {
  const picks = getPendingGamePickEntries(latestRenderedGames);
  if (!picks.length || !gamePickDialogEl || !gamePickDialogSummaryEl || !gamePickDialogOddsEl || !gamePickDialogAmountEl) return;

  gamePickDialogSummaryEl.replaceChildren();
  for (const pick of picks) {
    const chip = document.createElement('div');
    chip.className = 'game-pick-dialog-chip';
    const logo = document.createElement('img');
    logo.className = 'game-pick-dialog-logo';
    setLogo(logo, pick.teamLogo || getLogoPath(pick.teamAbbrev), `${displayTeamAbbrev(pick.teamAbbrev)} logo`);
    const text = document.createElement('span');
    text.textContent = `${displayTeamAbbrev(pick.teamAbbrev)} WIN`;
    chip.append(logo, text);
    gamePickDialogSummaryEl.appendChild(chip);
  }

  gamePickDialogOddsEl.value = String(betOddsEl?.value || '').trim();
  gamePickDialogAmountEl.value = String(betAmountEl?.value || '').trim();

  if (typeof gamePickDialogEl.showModal === 'function') {
    if (!gamePickDialogEl.open) gamePickDialogEl.showModal();
  } else {
    gamePickDialogEl.setAttribute('open', 'open');
  }

  requestAnimationFrame(() => {
    gamePickDialogOddsEl.focus();
    queueTextSelection(gamePickDialogOddsEl);
  });
}

function buildGamePickBetDescription(picks = []) {
  return `${picks.map((pick) => displayTeamAbbrev(pick.teamAbbrev)).join(' + ')} to win`;
}

function combinedDraftBetLegs(games = latestRenderedGames) {
  return [
    ...getPendingGamePickEntries(games).map((pick) => ({ ...pick })),
    ...draftBetLegs.map((leg) => ({ ...leg })),
  ];
}

function buildBetDescriptionFromLegs(desc, legs = []) {
  const cleanDesc = cleanSummary(desc);
  const autoDesc = buildBetSlipText(legs);
  if (!cleanDesc) return autoDesc;
  const playerOnlyDesc = buildBetSlipText(draftBetLegs);
  return cleanDesc === playerOnlyDesc ? (autoDesc || cleanDesc) : cleanDesc;
}

function addBetToLog({ desc, odds, amount, legs = [] }) {
  const cleanOdds = String(odds || '').trim();
  const numericAmount = Number(amount);
  const cleanDesc = cleanSummary(desc);
  if (!cleanDesc || !cleanOdds || !Number.isFinite(numericAmount) || numericAmount <= 0) return false;
  const payout = oddsToPayout(cleanOdds, numericAmount);
  if (!Number.isFinite(payout) || payout <= 0) return false;
  const bets = getBets();
  bets.unshift({
    id: String(Date.now()),
    desc: cleanDesc,
    odds: cleanOdds,
    amount: numericAmount,
    payout,
    ts: Date.now(),
    legs: Array.isArray(legs) ? legs.map((leg) => ({ ...leg })) : [],
  });
  saveBets(bets);
  return true;
}

function saveGamePickBetEntry(picks, odds, amount) {
  return addBetToLog({
    desc: buildGamePickBetDescription(picks),
    odds,
    amount,
    legs: picks,
  });
}

function focusBetInputField(field) {
  if (field === 'odds') {
    betOddsEl?.focus();
    queueTextSelection(betOddsEl);
    return;
  }
  if (field === 'amount') {
    betAmountEl?.focus();
    queueTextSelection(betAmountEl);
    return;
  }
  betDescEl?.focus();
  queueTextSelection(betDescEl);
}

function buildBetSubmissionPayload(options = {}) {
  const {
    descOverride = null,
    oddsOverride = null,
    amountOverride = null,
    includePendingGamePicks = true,
  } = options;
  const pendingPicks = includePendingGamePicks ? getPendingGamePickEntries(latestRenderedGames) : [];
  const legs = [
    ...pendingPicks.map((pick) => ({ ...pick })),
    ...draftBetLegs.map((leg) => ({ ...leg })),
  ];
  return {
    pendingPicks,
    legs,
    desc: buildBetDescriptionFromLegs(descOverride ?? betDescEl?.value ?? '', legs),
    odds: String(oddsOverride ?? betOddsEl?.value ?? '').trim(),
    amount: Number(amountOverride ?? betAmountEl?.value),
  };
}

function submitBetInput(options = {}) {
  const payload = buildBetSubmissionPayload(options);
  if (!payload.desc) {
    focusBetInputField('desc');
    return false;
  }
  if (!payload.odds) {
    focusBetInputField('odds');
    return false;
  }
  if (!Number.isFinite(payload.amount) || payload.amount <= 0) {
    focusBetInputField('amount');
    return false;
  }
  if (!addBetToLog({
    desc: payload.desc,
    odds: payload.odds,
    amount: payload.amount,
    legs: payload.legs,
  })) return false;

  betFormEl?.reset();
  clearDraftBetSlip();
  renderPendingGamePicks(latestRenderedGames);
  renderBetList();
  return true;
}

function canSubmitPendingGamePicksFromMainForm(desc, pendingPicks = getPendingGamePickEntries(latestRenderedGames)) {
  if (!Array.isArray(pendingPicks) || !pendingPicks.length) return false;
  if (draftBetLegs.length) return false;
  const cleanDesc = String(desc || '').trim();
  return !cleanDesc || cleanDesc === buildGamePickBetDescription(pendingPicks);
}

function isGamePickLeg(leg) {
  return (leg?.propType || leg?.type) === 'teamWin';
}

function isGamePickBet(bet) {
  if (bet?.betType === 'gamePicks') return true;
  return Array.isArray(bet?.legs) && bet.legs.length > 0 && bet.legs.every((leg) => isGamePickLeg(leg));
}

function renderPendingGamePicks(games = latestRenderedGames) {
  const picks = getPendingGamePickEntries(games);
  if (betDescEl) {
    const shouldRelaxRequired = picks.length > 0 && draftBetLegs.length === 0;
    betDescEl.required = !shouldRelaxRequired;
    if (shouldRelaxRequired && !String(betDescEl.value || '').trim()) {
      betDescEl.placeholder = 'Game picks selected below. Enter odds and amount, then click Add, or use Confirm Game Picks.';
    } else {
      betDescEl.placeholder = 'Build legs below or type a manual bet';
    }
  }
  syncAllCardGamePickStates(games);
  if (activeLineupGame) syncLineupGamePickState(activeLineupGame);
}

function createBetProgressBoxes(completed, total, status = 'pending') {
  const totalCount = Math.max(0, Math.floor(Number(total)) || 0);
  const completeCount = Math.max(0, Math.min(totalCount, Math.floor(Number(completed)) || 0));
  const wrap = document.createElement('span');
  wrap.className = `bet-progress-boxes bet-progress-${status}`;
  wrap.setAttribute('role', 'img');
  wrap.setAttribute('aria-label', `${completeCount} of ${totalCount}`);
  for (let index = 0; index < totalCount; index += 1) {
    const box = document.createElement('span');
    box.className = 'bet-progress-box';
    if (index < completeCount) {
      box.classList.add('is-complete');
      box.textContent = '✓';
    }
    wrap.appendChild(box);
  }
  return wrap;
}

function buildBetStatusPill(resolved) {
  const statusPill = document.createElement('span');
  statusPill.className = 'bet-status-pill';
  const legs = resolved?.legs || [];
  if (legs.length > 1) {
    const completed = legs.filter((leg) => leg.status === 'hit').length;
    const label = resolved.status === 'hit' ? 'PARLAY HIT'
      : resolved.status === 'miss' ? 'PARLAY MISS'
      : 'PARLAY';
    statusPill.append(document.createTextNode(`${label} `), createBetProgressBoxes(completed, legs.length, resolved.status));
    return statusPill;
  }
  statusPill.textContent = resolved?.label || 'MANUAL';
  return statusPill;
}

function formatBetRate(value, digits = 3) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return '.000';
  return numeric.toFixed(digits).replace(/^0\./, '.');
}

function ordinalNumber(value) {
  const num = Math.floor(Number(value));
  if (!Number.isFinite(num) || num <= 0) return '';
  const mod100 = num % 100;
  if (mod100 >= 11 && mod100 <= 13) return `${num}th`;
  switch (num % 10) {
    case 1: return `${num}st`;
    case 2: return `${num}nd`;
    case 3: return `${num}rd`;
    default: return `${num}th`;
  }
}

function summarizeLastFiveBatting(splits = []) {
  const details = summarizeLastFiveBattingDetails(splits);
  if (!details) return null;
  return details.totalsRows.map(([label, value]) => `${label}${label.startsWith('L') ? ':' : ''} ${value}`);
}

function gameIsLiveForRecentHistory(game) {
  if (!game) return false;
  if (shouldPreferProbablePitcher(game)) return false;
  const abstractState = String(game?.status?.abstractGameState || '').toLowerCase();
  const text = `${game?.status?.detailedState || game?.status || ''} ${game?.inning || ''} ${game?.inningShort || ''}`.toLowerCase();
  return abstractState !== 'final' && !/\bfinal\b/.test(text);
}

function statLogSplitGamePk(split) {
  const value = split?.game?.gamePk
    ?? split?.game?.pk
    ?? split?.gamePk
    ?? split?.game?.id
    ?? split?.game?.game?.pk
    ?? null;
  const numeric = Number(value);
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
}

function filteredRecentHistorySplits(splits = [], game = null) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const currentDate = calendarDateOnly(game?.officialDate || game?.gameDate || selectedDate, selectedDate);
  const eligible = listify(splits)
    .filter((split) => split?.date && String(split.date) <= String(selectedDate))
    .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')));
  if (currentDate) {
    return eligible.filter((split) => String(split?.date || '') < currentDate);
  }
  if (!gameIsLiveForRecentHistory(game)) return eligible;
  const currentGamePk = Number(game?.gamePk);
  let skippedSameDayFallback = false;
  return eligible.filter((split) => {
    if (String(split?.date || '') !== currentDate) return true;
    const splitGamePk = statLogSplitGamePk(split);
    if (Number.isFinite(currentGamePk) && Number.isFinite(splitGamePk) && splitGamePk === currentGamePk) return false;
    if (!skippedSameDayFallback) {
      skippedSameDayFallback = true;
      return false;
    }
    return true;
  });
}

function battingSplitExtraBaseHits(stat = {}) {
  return statNumber(stat.doubles) + statNumber(stat.triples) + statNumber(stat.homeRuns);
}

function gamesSinceBattingEvent(eligibleGames = [], hasEvent = () => false) {
  let gamesSince = 0;
  for (const split of eligibleGames) {
    const stat = split?.stat || {};
    if (hasEvent(stat)) return gamesSince;
    gamesSince += 1;
  }
  return eligibleGames.length ? gamesSince : null;
}

function battingGamesSinceEventsFromSplits(eligibleGames = []) {
  return {
    hr: gamesSinceBattingEvent(eligibleGames, (stat) => statNumber(stat.homeRuns) > 0),
    xbh: gamesSinceBattingEvent(eligibleGames, (stat) => battingSplitExtraBaseHits(stat) > 0),
  };
}

function summarizeLastFiveBattingDetails(splits = [], game = null, gameLimit = 5) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const eligibleGames = filteredRecentHistorySplits(splits, game);
  const games = eligibleGames.slice(0, Math.max(1, Math.floor(Number(gameLimit)) || 5));
  if (!games.length) return null;
  const gamesSince = battingGamesSinceEventsFromSplits(eligibleGames);
  const totals = games.reduce((sum, split) => {
    const stat = split?.stat || {};
    sum.games += 1;
    sum.atBats += statNumber(stat.atBats);
    sum.hits += statNumber(stat.hits);
    sum.hr += statNumber(stat.homeRuns);
    sum.rbi += statNumber(stat.rbi);
    sum.walks += statNumber(stat.baseOnBalls ?? stat.walks);
    sum.so += statNumber(stat.strikeOuts);
    sum.doubles += statNumber(stat.doubles);
    sum.triples += statNumber(stat.triples);
    sum.totalBases += statNumber(stat.totalBases) || totalBasesFromBatting(stat);
    return sum;
  }, { games: 0, atBats: 0, hits: 0, hr: 0, rbi: 0, walks: 0, so: 0, doubles: 0, triples: 0, totalBases: 0 });
  const avg = totals.atBats > 0 ? totals.hits / totals.atBats : 0;
  const obpDenominator = totals.atBats + totals.walks;
  const obp = obpDenominator > 0 ? (totals.hits + totals.walks) / obpDenominator : 0;
  const slg = totals.atBats > 0 ? totals.totalBases / totals.atBats : 0;
  const ops = obp + slg;
  let hitStreak = 0;
  for (const split of eligibleGames) {
    const stat = split?.stat || {};
    const hits = statNumber(stat.hits);
    const atBats = statNumber(stat.atBats);
    if (hits > 0) {
      hitStreak += 1;
      continue;
    }
    if (atBats > 0) break;
  }
  const lastSplit = games[0];
  const lastStat = lastSplit?.stat || {};
  const lastOpponent = displayTeamAbbrev(
    lastSplit?.opponent?.abbreviation
      || lastSplit?.opponent?.teamCode
      || lastSplit?.opponent?.name
      || lastSplit?.opponentTeam?.abbreviation
      || lastSplit?.opponentTeam?.name
      || '',
  );
  return {
    feature: {
      label: 'LAST GAME',
      meta: [formatLeadersDateLabel(lastSplit?.date || selectedDate), lastOpponent ? `vs ${lastOpponent}` : ''].filter(Boolean).join(' '),
      main: `${statNumber(lastStat.hits)}-${statNumber(lastStat.atBats)}`,
      side: `TB ${statNumber(lastStat.totalBases) || totalBasesFromBatting(lastStat)}`,
      chips: [
        `HR ${statNumber(lastStat.homeRuns)}`,
        `RBI ${statNumber(lastStat.rbi)}`,
        `BB ${statNumber(lastStat.baseOnBalls ?? lastStat.walks)}`,
        `K ${statNumber(lastStat.strikeOuts)}`,
      ],
    },
    lastGame: {
      date: formatLeadersDateLabel(lastSplit?.date || selectedDate),
      rawDate: lastSplit?.date || selectedDate,
      opponent: lastOpponent,
      hits: statNumber(lastStat.hits),
      atBats: statNumber(lastStat.atBats),
      totalBases: statNumber(lastStat.totalBases) || totalBasesFromBatting(lastStat),
      hr: statNumber(lastStat.homeRuns),
      rbi: statNumber(lastStat.rbi),
      walks: statNumber(lastStat.baseOnBalls ?? lastStat.walks),
      so: statNumber(lastStat.strikeOuts),
    },
    heatGames: eligibleGames.map((split) => {
      const stat = split?.stat || {};
      const opponent = displayTeamAbbrev(
        split?.opponent?.abbreviation
        || split?.opponent?.teamCode
        || split?.opponent?.name
        || split?.opponentTeam?.abbreviation
        || split?.opponentTeam?.name
        || '',
      );
      return {
        date: formatLeadersDateLabel(split?.date || selectedDate),
        rawDate: split?.date || selectedDate,
        gamePk: Number(split?.game?.gamePk ?? split?.gamePk) || null,
        opponent,
        hits: statNumber(stat.hits),
        atBats: statNumber(stat.atBats),
        plateAppearances: batterHeatPlateAppearancesFromStat(stat),
        totalBases: statNumber(stat.totalBases) || totalBasesFromBatting(stat),
        hr: statNumber(stat.homeRuns),
        rbi: statNumber(stat.rbi),
        walks: statNumber(stat.baseOnBalls ?? stat.walks),
        so: statNumber(stat.strikeOuts),
        hitByPitch: statNumber(stat.hitByPitch),
        sacFlies: statNumber(stat.sacFlies ?? stat.sacrificeFlies),
        sacBunts: statNumber(stat.sacBunts ?? stat.sacrificeBunts),
        catchersInterference: statNumber(stat.catchersInterference),
      };
    }).filter(batterHeatGameQualifies).slice(0, 3),
    totals: {
      games: totals.games,
      atBats: totals.atBats,
      hits: totals.hits,
      homeRuns: totals.hr,
      rbi: totals.rbi,
      walks: totals.walks,
      strikeOuts: totals.so,
      doubles: totals.doubles,
      triples: totals.triples,
      totalBases: totals.totalBases,
      xbh: totals.doubles + totals.triples + totals.hr,
    },
    metrics: {
      avg,
      obp,
      slg,
      ops,
    },
    gamesSince,
    hitStreak,
    totalsRows: [
      [`L${totals.games}`, `${totals.hits}-${totals.atBats}`],
      ['AVG', formatBetRate(avg)],
      ['OPS', formatBetRate(ops)],
      ['SLG', formatBetRate(slg)],
      ['XBH', totals.doubles + totals.triples + totals.hr],
      ['HR', totals.hr],
      ['K', totals.so],
    ],
  };
}

function summarizeLastFivePitchingAppearancesDetails(splits = [], game = null) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const dataAsOfDate = game ? addDaysToDateValue(officialDateForGame(game, selectedDate), -1) : addDaysToDateValue(selectedDate, -1);
  const appearances = filteredRecentHistorySplits(splits, game)
    .filter((split) => inningsToOuts(split?.stat?.inningsPitched) > 0 || statNumber(split?.stat?.gamesPlayed) > 0)
    .slice(0, 5);
  if (!appearances.length) return null;
  const reducePitchingSplits = (list = []) => list.reduce((sum, split) => {
    const stat = split?.stat || {};
    sum.games += 1;
    sum.starts += statNumber(stat.gamesStarted) > 0 ? 1 : 0;
    sum.outs += inningsToOuts(stat.inningsPitched);
    sum.k += statNumber(stat.strikeOuts);
    sum.bb += statNumber(stat.baseOnBalls ?? stat.walks);
    sum.hits += statNumber(stat.hits);
    sum.er += statNumber(stat.earnedRuns);
    sum.hr += statNumber(stat.homeRuns ?? stat.hrAllowed ?? stat.hr);
    sum.pitches += statNumber(stat.numberOfPitches ?? stat.pitchesThrown);
    return sum;
  }, { games: 0, starts: 0, outs: 0, k: 0, bb: 0, hits: 0, er: 0, hr: 0, pitches: 0 });
  const totals = reducePitchingSplits(appearances);
  const seasonTotals = reducePitchingSplits(filteredRecentHistorySplits(splits, game)
    .filter((split) => inningsToOuts(split?.stat?.inningsPitched) > 0 || statNumber(split?.stat?.gamesPlayed) > 0));
  const era = totals.outs > 0 ? (totals.er * 27) / totals.outs : null;
  const whip = totals.outs > 0 ? ((totals.hits + totals.bb) * 3) / totals.outs : null;
  const seasonEra = seasonTotals.outs > 0 ? (seasonTotals.er * 27) / seasonTotals.outs : null;
  const seasonWhip = seasonTotals.outs > 0 ? ((seasonTotals.hits + seasonTotals.bb) * 3) / seasonTotals.outs : null;
  const lastSplit = appearances[0];
  const lastStat = lastSplit?.stat || {};
  const lastOpponent = displayTeamAbbrev(
    lastSplit?.opponent?.abbreviation
      || lastSplit?.opponent?.teamCode
      || lastSplit?.opponent?.name
      || lastSplit?.opponentTeam?.abbreviation
      || lastSplit?.opponentTeam?.name
      || '',
  );
  const lastPitches = statNumber(lastStat.numberOfPitches ?? lastStat.pitchesThrown);
  return {
    asOfDate: dataAsOfDate,
    historyTitle: 'RECENT APPEARANCES',
    feature: {
      label: 'LAST APP',
      meta: [formatLeadersDateLabel(lastSplit?.date || selectedDate), lastOpponent ? `vs ${lastOpponent}` : ''].filter(Boolean).join(' '),
      main: `IP ${cleanSummary(lastStat.inningsPitched) || '0.0'}`,
      side: `ER ${statNumber(lastStat.earnedRuns)}`,
      chips: [
        `K ${statNumber(lastStat.strikeOuts)}`,
        `BB ${statNumber(lastStat.baseOnBalls ?? lastStat.walks)}`,
        `H ${statNumber(lastStat.hits)}`,
        `HR ${statNumber(lastStat.homeRuns ?? lastStat.hrAllowed ?? lastStat.hr)}`,
        lastPitches ? `P ${lastPitches}` : 'P --',
      ],
    },
    lastGame: {
      date: formatLeadersDateLabel(lastSplit?.date || selectedDate),
      rawDate: lastSplit?.date || selectedDate,
      opponent: lastOpponent,
      outs: inningsToOuts(lastStat.inningsPitched),
      inningsPitched: cleanSummary(lastStat.inningsPitched) || '0.0',
      strikeOuts: statNumber(lastStat.strikeOuts),
      walks: statNumber(lastStat.baseOnBalls ?? lastStat.walks),
      hits: statNumber(lastStat.hits),
      earnedRuns: statNumber(lastStat.earnedRuns),
      homeRuns: statNumber(lastStat.homeRuns ?? lastStat.hrAllowed ?? lastStat.hr),
      pitches: lastPitches,
    },
    totals,
    seasonTotals,
    seasonMetrics: {
      era: seasonEra,
      whip: seasonWhip,
      k9: seasonTotals.outs > 0 ? (seasonTotals.k * 27) / seasonTotals.outs : null,
      hr9: seasonTotals.outs > 0 ? (seasonTotals.hr * 27) / seasonTotals.outs : null,
    },
    metrics: {
      era,
      whip,
      k9: totals.outs > 0 ? (totals.k * 27) / totals.outs : null,
    },
    totalsRows: [
      [`L${totals.games} G`, `${outsToInnings(totals.outs)} IP`],
      ['GS', totals.starts],
      ['ERA', formatRateValue(era, 2, false)],
      ['WHIP', formatRateValue(whip, 2, false)],
      ['K', totals.k],
      ['BB', totals.bb],
      ['H', totals.hits],
      ['ER', totals.er],
      ['HR', totals.hr],
    ],
  };
}

function playerStatRowsHtml(title, rows = []) {
    const safeRows = rows
      .filter((row) => Array.isArray(row) && row.length >= 2)
      .map(([label, value], index) => {
        const isRecentWindow = index === 0 && /^L\d+$/.test(String(label || ''));
        const labelHtml = isRecentWindow
          ? `<button class="player-recent-window-toggle" type="button" aria-pressed="${playerStatRecentGameWindow === 10 ? 'true' : 'false'}" title="Toggle last 5 / last 10 game stats">L${playerStatRecentGameWindow}</button>`
          : escapeHtml(label);
        return `
      <tr>
        <th>${labelHtml}</th>
        <td>${escapeHtml(value)}</td>
      </tr>
    `;
      })
      .join('');
  return `<strong>${escapeHtml(title)}</strong><table class="player-stat-table"><tbody>${safeRows || '<tr><td colspan="2">---</td></tr>'}</tbody></table>`;
}

function splitPlayerStatLine(line) {
  const value = cleanSummary(line);
  if (!value) return ['Info', 'Unavailable'];
  const colonIndex = value.indexOf(':');
  if (colonIndex > 0) return [value.slice(0, colonIndex).trim(), value.slice(colonIndex + 1).trim()];
  const spaceIndex = value.indexOf(' ');
  if (spaceIndex > 0) return [value.slice(0, spaceIndex).trim(), value.slice(spaceIndex + 1).trim()];
  return ['Info', value];
}

function playerLastGameFeatureHtml(last) {
  if (!last) return '';
  return `
    <div class="player-last-game">
      <div class="player-last-game-top">
        <span>${escapeHtml(last.label || 'LAST GAME')}</span>
        <em>${escapeHtml(last.meta || '')}</em>
      </div>
      <div class="player-last-game-line">
        <b>${escapeHtml(last.main || '---')}</b>
        <span>${escapeHtml(last.side || '')}</span>
      </div>
      <div class="player-last-game-chips">
        ${(Array.isArray(last.chips) ? last.chips : []).map((chip) => `<span>${escapeHtml(chip)}</span>`).join('')}
      </div>
    </div>
  `;
}




function playerBatterHeatCompactDate(game = {}) {
  const raw = cleanSummary(game.date || game.rawDate || '');
  if (!raw) return '--';
  const parts = raw.split('-');
  if (parts.length === 3) {
    const date = new Date(`${raw}T00:00:00`);
    if (!Number.isNaN(date.getTime())) return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  }
  return raw.replace(/^\d{4}-/, '').replace('-', '/');
}

function playerBatterHeatGameResultText(game = null) {
  if (!game) return '--';
  const hits = statNumber(game.hits);
  const atBats = statNumber(game.atBats);
  const tb = statNumber(game.totalBases);
  const hr = statNumber(game.hr ?? game.homeRuns);
  const parts = [`${hits}-${atBats}`, `${tb} TB`];
  if (hr > 0) parts.push(`${hr} HR`);
  return parts.join(', ');
}

function batterHeatPlateAppearancesFromStat(stat = {}) {
  const explicitPa = Number(stat.plateAppearances ?? stat.plateAppearance ?? stat.pa ?? stat.PA);
  if (Number.isFinite(explicitPa) && explicitPa >= 0) return explicitPa;
  return Math.max(0,
    statNumber(stat.atBats)
    + statNumber(stat.baseOnBalls ?? stat.walks)
    + statNumber(stat.hitByPitch)
    + statNumber(stat.sacFlies ?? stat.sacrificeFlies)
    + statNumber(stat.sacBunts ?? stat.sacrificeBunts)
    + statNumber(stat.catchersInterference)
  );
}

function batterHeatGameQualifies(game = null) {
  if (!game) return false;
  const plateAppearances = batterHeatPlateAppearancesFromStat(game);
  if (plateAppearances >= 3) return true;
  const atBats = statNumber(game.atBats);
  const hits = statNumber(game.hits);
  const homeRuns = statNumber(game.hr ?? game.homeRuns);
  return atBats === 1 && hits === 1 && homeRuns > 0;
}


function playerBatterHeatContactStat(contact = null, key = '', game = null) {
  const src = contact || {};
  const detail = cleanSummary(src.detail || src.contactDetail || '');
  const gameHr = statNumber(game?.hr ?? game?.homeRuns);
  const sourceHr = Number(src.homeRuns ?? src.hr ?? src.homeRun ?? detail.match(/(?:HR|home[-\s]*run[s]?)\s*(\d+)/i)?.[1] ?? 0);
  const hasHomeRun = gameHr > 0 || (Number.isFinite(sourceHr) && sourceHr > 0);
  const fallbackBip = Math.max(0, statNumber(game?.atBats) - statNumber(game?.so ?? game?.strikeOuts));
  const bbeRaw = Number(src.bbe ?? src.bip ?? src.battedBalls ?? detail.match(/(\d+)\s*BBE/i)?.[1] ?? (fallbackBip || 0));
  const hardRaw = Number(src.hardHit ?? src.hh ?? src.hardContact ?? detail.match(/HH\s*(\d+)/i)?.[1] ?? detail.match(/hard[-\s]*hit(?:\s*balls?)?\s*(\d+)/i)?.[1] ?? 0);
  const barrelRaw = Number(src.barrelLike ?? src.barrels ?? src.barrel ?? detail.match(/barrel(?:-like)?\s*(\d+)/i)?.[1] ?? 0);
  // Contact feeds can miss hitData for some historical HR plays. For the heat heuristic, a HR should never render as 0 hard contact / 0 barrel-like contact.
  const bbe = Math.max(hasHomeRun ? 1 : 0, Number.isFinite(bbeRaw) ? bbeRaw : 0);
  const hardHit = Math.max(hasHomeRun ? 1 : 0, Number.isFinite(hardRaw) ? hardRaw : 0);
  const barrelLike = Math.max(hasHomeRun ? 1 : 0, Number.isFinite(barrelRaw) ? barrelRaw : 0);
  const gameLoaded = Boolean(game) || Boolean(contact);
  if (key === 'bip') return bbe > 0 ? String(Math.round(bbe)) : gameLoaded ? '0' : '--';
  if (key === 'hard') return hardHit > 0 ? String(Math.round(hardHit)) : gameLoaded ? '0' : '--';
  if (key === 'barrel') return barrelLike > 0 ? String(Math.round(barrelLike)) : gameLoaded ? '0' : '--';
  return '--';
}

function playerBatterHeatGameScoreValue(game = null, index = 0) {
  if (!game) return null;
  if (typeof batterHeatGameScore === 'function') return batterHeatGameScore(game, index);
  const hits = statNumber(game.hits);
  const atBats = statNumber(game.atBats);
  const tb = statNumber(game.totalBases);
  const hr = statNumber(game.hr ?? game.homeRuns);
  return clamp(Math.round(18 + (hr > 0 ? 34 : 0) + Math.min(22, tb * 6) + Math.min(14, hits * 5) - Math.min(6, Math.max(0, atBats - hits) * 1.2)), 0, 100);
}

function playerBatterHeatGameNumbersHtml(games = []) {
  const padded = [...listify(games).slice(0, 3), null, null, null].slice(0, 3);
  return `
    <div class="player-batter-heat-mini-row" aria-label="Last three game heat scores">
      <span>Score</span>
      ${padded.map((game, index) => {
        const score = playerBatterHeatGameScoreValue(game, index);
        const label = `G${index + 1}`;
        const result = playerBatterHeatGameResultText(game);
        const title = game ? `${label}: ${result}` : `${label}: no recent game loaded`;
        return `<b title="${escapeHtml(title)}"><small>${escapeHtml(label)}</small>${Number.isFinite(score) ? Math.round(score) : '--'}</b>`;
      }).join('')}
    </div>
  `;
}

function playerBatterHeatContactGridHtml(games = [], contacts = []) {
  const gameRows = [...listify(games).slice(0, 3), null, null, null].slice(0, 3);
  const contactRows = listify(contacts).slice(0, 3);
  const contactFor = (index) => contactRows[index] || gameRows[index]?.contactHeat || null;
  const cell = (index, key) => escapeHtml(playerBatterHeatContactStat(contactFor(index), key, gameRows[index]));
  return `
    <div class="player-batter-heat-contact-table" aria-label="Last three game contact quality">
      <span></span><b>G1</b><b>G2</b><b>G3</b>
      <strong>BIP</strong><em>${cell(0, 'bip')}</em><em>${cell(1, 'bip')}</em><em>${cell(2, 'bip')}</em>
      <strong>Hard</strong><em>${cell(0, 'hard')}</em><em>${cell(1, 'hard')}</em><em>${cell(2, 'hard')}</em>
      <strong>Brl</strong><em>${cell(0, 'barrel')}</em><em>${cell(1, 'barrel')}</em><em>${cell(2, 'barrel')}</em>
    </div>
  `;
}

function playerBatterHeatFeatureHtml(heat = null) {
  if (!heat) return '';
  const loading = Boolean(heat.loading);
  const score = Number(heat.score);
  const scoreText = Number.isFinite(score) ? `${Math.round(score)}/100` : loading ? '...' : '--';
  const level = Number.isFinite(score) && score >= 75 ? 'is-hot' : Number.isFinite(score) && score >= 62 ? 'is-warm' : 'is-neutral';
  const games = listify(heat.games || heat.heatGames).slice(0, 3);
  const contacts = listify(heat.contactGames || heat.contactByGame).slice(0, 3);
  const detail = cleanSummary(heat.detail || heat.contactDetail || '') || (loading ? 'checking recent box scores and contact data' : 'recent result/contact heat neutral');
  return `
    <div class="player-batter-heat ${level}${loading ? ' is-loading' : ''}" title="${escapeHtml(detail)}">
      <div class="player-batter-heat-header"><strong>HEAT</strong><b>${escapeHtml(scoreText)}</b></div>
      ${playerBatterHeatGameNumbersHtml(games)}
      ${playerBatterHeatContactGridHtml(games, contacts)}
    </div>
  `;
}


function playerBatterHeatContactWithGameFloor(contact = null, game = null) {
  const gameHr = statNumber(game?.hr ?? game?.homeRuns);
  const sourceHr = Number(contact?.homeRuns ?? contact?.hr ?? contact?.homeRun ?? 0);
  if (!(gameHr > 0 || (Number.isFinite(sourceHr) && sourceHr > 0))) return contact;
  const src = contact ? { ...contact } : {};
  const bbe = Math.max(1, Number(src.bbe ?? src.bip ?? src.battedBalls) || 0);
  const hardHit = Math.max(1, Number(src.hardHit ?? src.hh ?? src.hardContact) || 0);
  const barrelLike = Math.max(1, Number(src.barrelLike ?? src.barrels ?? src.barrel) || 0);
  const homeRuns = Math.max(gameHr, Number(src.homeRuns ?? src.hr ?? src.homeRun) || 0);
  return {
    ...src,
    score: Math.max(Number(src.score) || 0, 78),
    bbe,
    bip: bbe,
    hardHit,
    barrelLike,
    homeRuns,
    detail: cleanSummary(src.detail || src.contactDetail) || `${bbe} BBE, HH ${hardHit}, barrel-like ${barrelLike}, HR ${homeRuns}`,
  };
}

function playerBatterHeatPayload(details = null, recentContactHeat = null, contactGames = []) {
  if (!details) return null;
  const games = batterHeatGameRows(details).slice(0, 3);
  const rawContacts = listify(contactGames).length ? listify(contactGames).slice(0, 3) : (recentContactHeat ? [recentContactHeat] : []);
  const contacts = games.map((game, index) => playerBatterHeatContactWithGameFloor(rawContacts[index] || null, game));
  const aggregateContact = contacts.filter(Boolean).length
    ? {
        score: predictionWeightedScore(contacts.filter(Boolean).map((contact, index) => ({ score: Number(contact?.score) || 0, weight: [0.40, 0.30, 0.30][index] || 0.10 }))),
        bbe: contacts.reduce((sum, contact) => sum + (Number(contact?.bbe) || 0), 0),
        hardHit: contacts.reduce((sum, contact) => sum + (Number(contact?.hardHit) || 0), 0),
        barrelLike: contacts.reduce((sum, contact) => sum + (Number(contact?.barrelLike) || 0), 0),
      }
    : recentContactHeat;
  const score = predictionBatterHeatScore(details, details?.metrics || {}, aggregateContact || null);
  const detail = predictionBatterHeatDetail(details, aggregateContact || null);
  return {
    score,
    detail,
    contact: aggregateContact || null,
    recentContactHeat: aggregateContact || null,
    contactGames: contacts,
    contactByGame: contacts,
    games,
    heatGames: games.map((game, index) => ({ ...game, contactHeat: contacts[index] || null })),
  };
}

function playerStatTodayWithLastGameHtml(todayLine, details = null, title = 'TODAY', options = {}) {
  const heatHtml = playerBatterHeatFeatureHtml(options.batterHeat || null);
  const lastGameHtml = heatHtml ? '' : playerLastGameFeatureHtml(details?.feature || null);
  return `${playerStatRowsHtml(title, [['Line', todayLine]])}${lastGameHtml}${heatHtml}`;
}


function renderRecentBattingHistoryHtml(lines) {
  if (lines && typeof lines === 'object' && !Array.isArray(lines)) {
    return `<strong>${escapeHtml(lines.historyTitle || 'RECENT HISTORY')}</strong>${playerStatTableHtml(lines.totalsRows || [])}`;
  }
  const rows = Array.isArray(lines) && lines.length ? lines : ['Recent history unavailable'];
  return playerStatRowsHtml('RECENT HISTORY', rows.map(splitPlayerStatLine));
}

function playerStatTableHtml(rows = []) {
  const safeRows = rows
    .filter((row) => Array.isArray(row) && row.length >= 2)
    .map(([label, value], index) => {
      const isRecentWindow = index === 0 && /^L\d+$/.test(String(label || ''));
      const labelHtml = isRecentWindow
        ? `<button class="player-recent-window-toggle" type="button" aria-pressed="${playerStatRecentGameWindow === 10 ? 'true' : 'false'}" title="Toggle last 5 / last 10 game stats">L${playerStatRecentGameWindow}</button>`
        : escapeHtml(label);
      return `
      <tr>
        <th>${labelHtml}</th>
        <td>${escapeHtml(value)}</td>
      </tr>
    `;
    })
    .join('');
  return `<table class="player-stat-table"><tbody>${safeRows || '<tr><td colspan="2">---</td></tr>'}</tbody></table>`;
}

async function loadPlayerContractRows() {
  if (playerContractsRows.length) return playerContractsRows;
  if (Array.isArray(window.MLB_CONTRACT_ROWS) && window.MLB_CONTRACT_ROWS.length) {
    playerContractsRows = window.MLB_CONTRACT_ROWS;
    return playerContractsRows;
  }
  if (playerContractsLoadPromise) return playerContractsLoadPromise;
  playerContractsLoadPromise = fetch(PLAYER_CONTRACTS_CSV_URL, { cache: 'no-store' })
    .then((response) => {
      if (!response.ok) throw new Error(`Contracts CSV request failed ${response.status}`);
      return response.text();
    })
    .then((text) => {
      playerContractsRows = parseCsvRows(text);
      return playerContractsRows;
    })
    .catch((error) => {
      playerContractsLoadPromise = null;
      throw error;
    });
  return playerContractsLoadPromise;
}

function contractNumber(value) {
  const numeric = Number(String(value ?? '').replace(/[$,%\s]/g, '').replace(/,/g, ''));
  return Number.isFinite(numeric) ? numeric : null;
}

function contractMoney(value) {
  const numeric = contractNumber(value);
  if (numeric == null) return cleanSummary(value) || '--';
  const abs = Math.abs(numeric);
  const sign = numeric < 0 ? '-' : '';
  if (abs >= 1000000) return `${sign}$${(abs / 1000000).toFixed(abs >= 10000000 ? 1 : 2).replace(/\.0+$/, '')}M`;
  if (abs >= 1000) return `${sign}$${Math.round(abs / 1000)}K`;
  return `${sign}$${Math.round(abs).toLocaleString()}`;
}

function contractText(value, fallback = '--') {
  return cleanSummary(value) || fallback;
}

function contractSourceLink(row = {}) {
  return contractText(row.source_urls, '').split('|').map((value) => cleanSummary(value)).find(Boolean);
}

function contractTooltip(label = '') {
  const key = normalizeNameKey(label);
  const tips = {
    '2026pay': 'Season-specific pay values from the 2026 contract snapshot.',
    contract: 'Overall contract shape, value, and timing.',
    control: 'Roster/control information tied to this contract row.',
    source: 'Import, validation, and source-link details for this row.',
    luxurytax: 'The payroll value charged to CBT/luxury-tax calculations for this season.',
    totalcash: 'Actual cash compensation assigned to this player for the selected season.',
    basecash: 'Base salary cash for the selected season, excluding listed bonuses.',
    signingbonus: 'Signing-bonus cash allocated in this data set.',
    type: 'Contract bucket from the contract/cash source, such as free agent, arbitration, extension, or pre-arbitration.',
    subtype: 'More specific contract classification when the source provides one.',
    term: 'Total reported contract length and total reported contract value.',
    aav: 'Average annual value of the full contract.',
    range: 'Contract start year through contract end year.',
    signed: 'Year the contract was signed, when available.',
    team: 'Team page or roster context used by the contract data.',
    status: 'Current roster status from the contract/roster data.',
    position: 'Position listed in the contract data.',
    age: 'Player age listed in the contract data.',
    service: 'MLB service time in years.days format when available.',
    options: 'Minor league options remaining, if the source provides it.',
    freeagent: 'Year the player is projected to reach free agency, if available.',
    matched: 'Whether the contract row matched an MLB 40-man roster/player identity.',
    validation: 'Data-quality notes from the contract import.',
    snapshot: 'Timestamp when this contract data snapshot was generated.',
    link: 'Primary external source used for this row.',
  };
  return tips[key] || 'Contract data field from the 2026 contract snapshot.';
}

function playerContractRowForProfile(rows = [], profile = {}) {
  const id = Number(profile?.id ?? profile?.playerId);
  if (Number.isFinite(id) && id > 0) {
    const byId = rows.find((row) => Number(row.mlb_person_id) === id);
    if (byId) return byId;
  }
  const profileNameKey = normalizeNameKey(profile?.fullName || profile?.name || profile?.person?.fullName || '');
  const profileTeam = canonicalTeamAbbrev(profile?.teamAbbrev || profile?.team || '');
  if (!profileNameKey) return null;
  return rows.find((row) => {
    if (normalizeNameKey(row.player || '') !== profileNameKey) return false;
    return !profileTeam || sameTeamAbbrev(row.team_abbr, profileTeam) || sameTeamAbbrev(row.mlb_roster_team, profileTeam);
  }) || rows.find((row) => normalizeNameKey(row.player || '') === profileNameKey) || null;
}

function contractMiniTableHtml(title, rows = []) {
  const body = rows.map(([label, value]) => `
    <tr>
      <th title="${escapeHtml(contractTooltip(label))}">${escapeHtml(label)}</th>
      <td>${value?.html ? value.html : escapeHtml(value ?? '--')}</td>
    </tr>
  `).join('');
  return `<article class="player-contract-card"><strong title="${escapeHtml(contractTooltip(title))}">${escapeHtml(title)}</strong><table class="player-stat-table"><tbody>${body}</tbody></table></article>`;
}

function renderPlayerContractHtml(profile = {}, row = null) {
  if (!row) {
    return `<div class="player-stat-loading">No contract row found for ${escapeHtml(profile?.fullName || profile?.name || 'this player')}.</div>`;
  }
  const signed = contractText(row.contract_signed_year, '');
  const start = contractText(row.contract_start_year, '');
  const end = contractText(row.contract_end_year, '');
  const range = [start, end].filter(Boolean).join('-') || '--';
  const freeAgentYear = contractText(row.free_agent_year, '--');
  const sourceUrl = contractSourceLink(row);
  const contractAmount = contractMoney(row.contract_value || row.total_cash || row.luxury_tax_salary);
  const contractYears = contractText(row.contract_years, '--');
  const signedYear = signed || '--';
  const endYear = end || '--';
  const team = canonicalTeamAbbrev(row.team_abbr || profile?.teamAbbrev || '');
  const teamLogo = getLogoPath(team);
  const teamColor = getTeamColor(team) || profile?.teamColor || '#7bd0ff';
  const cards = [
    ['2026 Pay', [
      ['Luxury Tax', contractMoney(row.luxury_tax_salary)],
      ['Total Cash', contractMoney(row.total_cash)],
      ['Base Cash', contractMoney(row.base_cash)],
      ['Signing Bonus', contractMoney(row.signing_bonus)],
    ]],
    ['Contract', [
      ['Type', contractText(row.contract_type_contracts || row.contract_type_tax)],
      ['Subtype', contractText(row.contract_subtype_contracts)],
      ['Term', `${contractText(row.contract_years)} yr | ${contractMoney(row.contract_value)}`],
      ['AAV', contractMoney(row.contract_aav)],
      ['Range', range],
      ['Signed', signed || '--'],
    ]],
    ['Control', [
      ['Team', `${displayTeamAbbrev(row.team_abbr)} | ${contractText(row.team_name)}`],
      ['Status', contractText(row.mlb_roster_status || row.roster_section_contract || row.roster_section_cash)],
      ['Position', contractText(row.position)],
      ['Age', contractText(row.age)],
      ['Service', contractText(row.service_time_yos)],
      ['Options', contractText(row.options_remaining)],
      ['Free Agent', freeAgentYear],
    ]],
    ['Source', [
      ['Matched', contractText(row.matched_to_mlb_40man)],
      ['Validation', contractText(row.validation_flags, 'clean')],
      ['Snapshot', contractText(row.snapshot_utc)],
      ['Link', sourceUrl ? { html: `<a href="${escapeHtml(sourceUrl)}" target="_blank" rel="noopener">Spotrac</a>` } : '--'],
    ]],
  ];
  return `
    <section class="player-contract-shell" style="--contract-team-color:${escapeHtml(teamColor)}; --contract-team-logo:url('${escapeHtml(teamLogo || 'placeholder.png')}')">
      <img class="player-contract-bg-logo" src="${escapeHtml(teamLogo || 'placeholder.png')}" alt="" aria-hidden="true" loading="lazy" />
      <div class="player-contract-hero" title="Contract summary: total amount, contract years, signed year, and end year.">
        <span>${escapeHtml(displayTeamAbbrev(team) || displayTeamAbbrev(profile?.teamAbbrev) || 'MLB')}</span>
        <strong>${escapeHtml(`${contractAmount} | ${contractYears} yr | Signed ${signedYear} | Ends ${endYear}`)}</strong>
        <em>${escapeHtml(contractText(row.contract_type_contracts || row.contract_type_tax))} | FA ${escapeHtml(freeAgentYear)}</em>
      </div>
      <div class="player-contract-grid">
        ${cards.map(([title, rows]) => contractMiniTableHtml(title, rows)).join('')}
      </div>
    </section>
  `;
}

async function renderPlayerContractTab(profile = activePlayerStatContext?.profile || null) {
  if (!playerStatContractEl) return;
  if (!profile) {
    playerStatContractEl.innerHTML = '<div class="player-stat-loading">Contract tab needs a player.</div>';
    return;
  }
  const token = `${profile.id || ''}:${Date.now()}`;
  playerStatContractEl.dataset.contractToken = token;
  playerStatContractEl.innerHTML = '<div class="player-stat-loading">Loading contract...</div>';
  try {
    const rows = await loadPlayerContractRows();
    if (!playerStatContractEl || playerStatContractEl.dataset.contractToken !== token) return;
    playerStatContractEl.innerHTML = renderPlayerContractHtml(profile, playerContractRowForProfile(rows, profile));
  } catch (error) {
    if (!playerStatContractEl || playerStatContractEl.dataset.contractToken !== token) return;
    playerStatContractEl.innerHTML = '<div class="player-stat-loading">Contract data unavailable.</div>';
  }
}

async function getBetPlayerLastFiveLines(playerId) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = dateInput.value || formatDate(new Date());
  const key = `${id}:${selectedDate}:hitting`;
  if (betPlayerLastFiveCache.has(key)) return betPlayerLastFiveCache.get(key);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'hitting');
    url.searchParams.set('season', String(seasonForDate(selectedDate)));
    url.searchParams.set('gameType', 'R');
    const response = await getJson(url.toString());
    return summarizeLastFiveBatting(response?.stats?.[0]?.splits || []);
  })().catch((error) => {
    betPlayerLastFiveCache.delete(key);
    throw error;
  });
  betPlayerLastFiveCache.set(key, promise);
  return promise;
}

async function getPlayerRecentBattingDetails(playerId, game = null, gameLimit = 5) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = dateInput.value || formatDate(new Date());
  const limit = Math.max(1, Math.floor(Number(gameLimit)) || 5);
  const key = `${id}:${selectedDate}:hitting-details:${limit}:${gameIsLiveForRecentHistory(game) ? String(game?.gamePk || 'live') : 'default'}`;
  if (betPlayerLastFiveCache.has(key)) return betPlayerLastFiveCache.get(key);
  const promise = (async () => {
    if (typeof playerStatGameLogSplits === 'function') {
      const splits = await playerStatGameLogSplits(id, 'hitting', game);
      return summarizeLastFiveBattingDetails(splits, game, limit);
    }
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'hitting');
    url.searchParams.set('season', String(seasonForDate(selectedDate)));
    url.searchParams.set('gameType', 'R');
    const response = await getJson(url.toString());
    return summarizeLastFiveBattingDetails(response?.stats?.[0]?.splits || [], game, limit);
  })().catch((error) => {
    betPlayerLastFiveCache.delete(key);
    throw error;
  });
  betPlayerLastFiveCache.set(key, promise);
  return promise;
}

async function getLineupRecentBattingStats(playerId, game = null, gameLimit = 5) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = dateInput.value || formatDate(new Date());
  const limit = Math.max(1, Math.floor(Number(gameLimit)) || 5);
  const key = `${id}:${selectedDate}:${String(game?.gamePk || 'none')}:lineup-l${limit}-hitting`;
  if (lineupRecentBattingCache.has(key)) return lineupRecentBattingCache.get(key);
  const promise = getPlayerRecentBattingDetails(id, game, limit)
    .then(lineupRecentBattingStatsFromDetails)
    .catch((error) => {
      lineupRecentBattingCache.delete(key);
      throw error;
    });
  lineupRecentBattingCache.set(key, promise);
  return promise;
}

function pitcherHandFromStatSplit(split = {}) {
  return handednessCode(
    split?.split?.code
    || split?.split?.abbreviation
    || split?.split?.description
    || split?.split?.displayName
    || split?.pitcherHand?.code
    || split?.pitcherHand?.description
    || split?.handedness
    || split?.name
    || '',
  );
}

function emptyRecentHandStat() {
  return { atBats: 0, hits: 0, totalBases: 0, homeRuns: 0, walks: 0, hbp: 0, sacFlies: 0, xbh: 0 };
}

function addRecentHandStat(target, stat = {}) {
  target.atBats += statNumber(stat.atBats);
  target.hits += statNumber(stat.hits);
  target.totalBases += statNumber(stat.totalBases);
  target.homeRuns += statNumber(stat.homeRuns);
  target.walks += statNumber(stat.baseOnBalls ?? stat.walks);
  target.hbp += statNumber(stat.hitByPitch);
  target.sacFlies += statNumber(stat.sacFlies);
  target.xbh += statNumber(stat.doubles) + statNumber(stat.triples) + statNumber(stat.homeRuns);
}

function formatRecentHandRate(numerator, denominator) {
  if (!denominator) return '---';
  return formatBetRate(numerator / denominator);
}

function formatRecentHandOps(stat = {}) {
  const ab = statNumber(stat.atBats);
  const hits = statNumber(stat.hits);
  const walks = statNumber(stat.walks);
  const tb = statNumber(stat.totalBases);
  const avg = ab ? hits / ab : 0;
  const obpDenom = ab + walks;
  const obp = obpDenom ? (hits + walks) / obpDenom : avg;
  const slg = ab ? tb / ab : 0;
  return ab || walks ? formatBetRate(obp + slg) : '---';
}

function formatRecentHandObp(stat = {}) {
  const ab = statNumber(stat.atBats);
  const hits = statNumber(stat.hits);
  const walks = statNumber(stat.walks);
  const hbp = statNumber(stat.hbp);
  const sacFlies = statNumber(stat.sacFlies);
  const denominator = ab + walks + hbp + sacFlies;
  return denominator ? formatBetRate((hits + walks + hbp) / denominator) : '---';
}

function formatRecentHandSlg(stat = {}) {
  const ab = statNumber(stat.atBats);
  return ab ? formatBetRate(statNumber(stat.totalBases) / ab) : '---';
}

function summarizeRecentBattingHandSplits(splits = [], game = null, days = 14) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const currentDate = calendarDateOnly(game?.officialDate || game?.gameDate || selectedDate, selectedDate);
  const end = parseLocalDateValue(currentDate || selectedDate);
  const start = parseLocalDateValue(currentDate || selectedDate);
  start.setDate(start.getDate() - Math.max(1, Number(days) || 14));
  const summary = { L: emptyRecentHandStat(), R: emptyRecentHandStat() };
  let found = false;
  for (const split of listify(splits)) {
    const date = calendarDateOnly(split?.date || '');
    if (!date) continue;
    const splitDate = parseLocalDateValue(date);
    if (splitDate < start || splitDate >= end) continue;
    const hand = pitcherHandFromStatSplit(split);
    if (hand !== 'L' && hand !== 'R') continue;
    found = true;
    addRecentHandStat(summary[hand], split?.stat || {});
  }
  if (!found) return null;
  return {
    left: {
      ...summary.L,
      avg: formatRecentHandRate(summary.L.hits, summary.L.atBats),
      obp: formatRecentHandObp(summary.L),
      slg: formatRecentHandSlg(summary.L),
      ops: formatRecentHandOps(summary.L),
    },
    right: {
      ...summary.R,
      avg: formatRecentHandRate(summary.R.hits, summary.R.atBats),
      obp: formatRecentHandObp(summary.R),
      slg: formatRecentHandSlg(summary.R),
      ops: formatRecentHandOps(summary.R),
    },
  };
}

function recentBattingHandSplitResult(summary = {}) {
  return {
    left: {
      ...summary.L,
      avg: formatRecentHandRate(summary.L.hits, summary.L.atBats),
      obp: formatRecentHandObp(summary.L),
      slg: formatRecentHandSlg(summary.L),
      ops: formatRecentHandOps(summary.L),
    },
    right: {
      ...summary.R,
      avg: formatRecentHandRate(summary.R.hits, summary.R.atBats),
      obp: formatRecentHandObp(summary.R),
      slg: formatRecentHandSlg(summary.R),
      ops: formatRecentHandOps(summary.R),
    },
  };
}

function battingEventTotalBases(eventType = '') {
  const event = String(eventType || '').toLowerCase();
  if (event === 'single') return 1;
  if (event === 'double') return 2;
  if (event === 'triple') return 3;
  if (event === 'home_run') return 4;
  return 0;
}

function battingEventCountsAtBat(eventType = '') {
  const event = String(eventType || '').toLowerCase();
  return ![
    'walk',
    'base_on_balls',
    'intent_walk',
    'intentional_walk',
    'hit_by_pitch',
    'sac_fly',
    'sac_bunt',
    'catcher_interf',
    'catcher_interference',
  ].includes(event);
}

function battingEventCountsWalk(eventType = '') {
  const event = String(eventType || '').toLowerCase();
  return event === 'walk' || event === 'base_on_balls' || event === 'intent_walk' || event === 'intentional_walk';
}

async function recentBattingHandSplitsFromGameFeeds(playerId, splits = [], game = null, days = 14) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = dateInput.value || formatDate(new Date());
  const currentDate = calendarDateOnly(game?.officialDate || game?.gameDate || selectedDate, selectedDate);
  const end = parseLocalDateValue(currentDate || selectedDate);
  const start = parseLocalDateValue(currentDate || selectedDate);
  start.setDate(start.getDate() - Math.max(1, Number(days) || 14));
  const gamePks = [...new Set(listify(splits)
    .filter((split) => {
      const date = calendarDateOnly(split?.date || '');
      if (!date) return false;
      const splitDate = parseLocalDateValue(date);
      return splitDate >= start && splitDate < end;
    })
    .map((split) => statLogSplitGamePk(split))
    .filter((pk) => Number.isFinite(Number(pk)) && Number(pk) > 0))];
  if (!gamePks.length) return null;
  const summary = { L: emptyRecentHandStat(), R: emptyRecentHandStat() };
  let found = false;
  await mapWithConcurrency(gamePks, 4, async (gamePk) => {
    const feed = await getLiveGameFeed(gamePk).catch(() => null);
    for (const play of listify(feed?.liveData?.plays?.allPlays)) {
      if (Number(play?.matchup?.batter?.id) !== id) continue;
      const hand = handednessCode(play?.matchup?.pitchHand?.code || play?.matchup?.pitchHand?.description || '');
      if (hand !== 'L' && hand !== 'R') continue;
      const event = String(play?.result?.eventType || '').toLowerCase();
      if (!event) continue;
      const target = summary[hand];
      const bases = battingEventTotalBases(event);
      if (battingEventCountsAtBat(event)) target.atBats += 1;
      if (bases > 0) target.hits += 1;
      target.totalBases += bases;
      if (event === 'home_run') target.homeRuns += 1;
      if (bases >= 2) target.xbh += 1;
      if (battingEventCountsWalk(event)) target.walks += 1;
      if (event === 'hit_by_pitch') target.hbp += 1;
      if (event === 'sac_fly') target.sacFlies += 1;
      found = true;
    }
  });
  return found ? recentBattingHandSplitResult(summary) : null;
}

async function getLineupRecentBattingHandSplits(playerId, game = null, days = 14) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = dateInput.value || formatDate(new Date());
  const key = `${id}:${selectedDate}:${String(game?.gamePk || 'none')}:lineup-l${days}-pitcher-hand`;
  if (lineupRecentBattingCache.has(key)) return lineupRecentBattingCache.get(key);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'hitting');
    url.searchParams.set('season', String(seasonForDate(selectedDate)));
    url.searchParams.set('gameType', 'R');
    url.searchParams.set('statSplits', 'pitcherHand');
    const response = await getJson(url.toString());
    const apiSummary = summarizeRecentBattingHandSplits(response?.stats?.[0]?.splits || [], game, days);
    if (apiSummary) return apiSummary;
    const plainUrl = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    plainUrl.searchParams.set('stats', 'gameLog');
    plainUrl.searchParams.set('group', 'hitting');
    plainUrl.searchParams.set('season', String(seasonForDate(selectedDate)));
    plainUrl.searchParams.set('gameType', 'R');
    const plainResponse = await getJson(plainUrl.toString());
    return recentBattingHandSplitsFromGameFeeds(id, plainResponse?.stats?.[0]?.splits || [], game, days);
  })().catch((error) => {
    lineupRecentBattingCache.delete(key);
    throw error;
  });
  lineupRecentBattingCache.set(key, promise);
  return promise;
}

async function getLineupRecentBattingStatsMap(game, lineups = [], gameLimit = 5) {
  if (!document.body?.classList?.contains('dashboard-page')) return new Map();
  const ids = [...new Set(
    listify(lineups)
      .flatMap((lineup) => Array.isArray(lineup) ? lineup : [])
      .map((entry) => Number(entry?.id))
      .filter((id) => Number.isFinite(id) && id > 0),
  )];
  if (!ids.length) return new Map();
  const pairs = await mapWithConcurrency(ids, 10, async (id) => {
    const stats = await getLineupRecentBattingStats(id, game, gameLimit).catch(() => null);
    return [String(id), stats];
  });
  return new Map(pairs.filter((pair) => pair?.[1]));
}

function dueBadgeTitleForEvent(profile, game, details = null, type = 'hr') {
  const batting = profile?.batting || {};
  const games = battingProjectionGames(profile, game);
  const homeRuns = statNumber(batting.hr ?? batting.homeRuns);
  const extraBaseHits = statNumber(batting.doubles) + statNumber(batting.triples) + homeRuns;
  const eventCount = type === 'xbh' ? extraBaseHits : homeRuns;
  const since = Number(type === 'xbh' ? details?.gamesSince?.xbh : details?.gamesSince?.hr);
  const label = type === 'xbh' ? 'XBH' : 'HR';
  if (games <= 0 || eventCount <= 0 || !Number.isFinite(since)) return '';
  const perEvent = games / eventCount;
  const gamesUntilDue = perEvent - since;
  if (gamesUntilDue > 0.75) return '';
  const status = gamesUntilDue > 0 ? `within ${gamesUntilDue.toFixed(1)} games of due` : `${Math.abs(gamesUntilDue).toFixed(1)} games overdue`;
  return `Due: ${since.toFixed(0)} games since ${label}, ${perEvent.toFixed(1)} per ${label} (${status})`;
}

function dueBadgePayload(profile, game, details = null) {
  return {
    hr: dueBadgeTitleForEvent(profile, game, details, 'hr'),
    xbh: dueBadgeTitleForEvent(profile, game, details, 'xbh'),
  };
}

async function getLineupHomeRunDueBadgeMap(game, lineups = []) {
  const entries = listify(lineups).flatMap((lineup) => Array.isArray(lineup) ? lineup : []);
  const ids = [...new Set(entries.map((entry) => Number(entry?.id)).filter((id) => Number.isFinite(id) && id > 0))];
  if (!ids.length) return new Map();
  const pairs = await mapWithConcurrency(ids, 6, async (id) => {
    const fallbackProfile = game?.playerLookup?.[String(id)] || entries.find((entry) => Number(entry?.id) === id) || null;
    const details = await getPlayerRecentBattingDetails(id, game).catch(() => null);
    let payload = dueBadgePayload(fallbackProfile, game, details);
    if (!payload.hr && !payload.xbh) {
      const fetchedProfile = await fetchMlbPlayerProfile(id, game, { role: 'hitter', allowFirstAppearanceFallback: false }).catch(() => null);
      if (fetchedProfile) {
        persistPlayerLookupForGame(game, { [String(id)]: fetchedProfile });
        payload = dueBadgePayload(fetchedProfile, game, details);
      }
    }
    return payload.hr || payload.xbh ? [String(id), payload] : null;
  });
  return new Map(pairs.filter(Boolean));
}

async function getPlayerRecentPitchingDetails(playerId, game = null) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = dateInput.value || formatDate(new Date());
  const season = seasonForDate(selectedDate);
  const key = `${id}:${selectedDate}:pitching-appearances-details:${gameIsLiveForRecentHistory(game) ? String(game?.gamePk || 'live') : 'default'}`;
  if (betPlayerLastFiveCache.has(key)) return betPlayerLastFiveCache.get(key);
  const promise = (async () => {
    const readGameLogSplits = async (targetSeason) => {
      if (typeof playerStatGameLogSplits === 'function') return playerStatGameLogSplits(id, 'pitching', game, targetSeason);
      const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
      url.searchParams.set('stats', 'gameLog');
      url.searchParams.set('group', 'pitching');
      url.searchParams.set('season', String(targetSeason));
      url.searchParams.set('gameType', 'R');
      url.searchParams.set('sportIds', '1');
      const response = await getJson(url.toString());
      return listify(response?.stats?.[0]?.splits);
    };
    const currentSplits = await readGameLogSplits(season);
    const currentDetails = summarizeLastFivePitchingAppearancesDetails(currentSplits, game);
    if (currentDetails) return currentDetails;

    const fallbackProfile = game?.playerLookup?.[String(id)] || resolvePitcherProfileById?.(game, id) || null;
    const currentStat = await getPlayerSeasonStatSplit(id, 'pitching', season).catch(() => ({}));
    const teamGames = teamGamesPlayedForPlayerFallback(id, game, fallbackProfile, null);
    const eligible = !seasonStatHasGameActivity(currentStat, 'pitching') && (
      teamGames >= FIRST_APPEARANCE_FALLBACK_MIN_TEAM_GAMES
      || selectedDateIsPastAprilForFirstAppearanceFallback(selectedDate)
    );
    const previousSeason = Number(season) - 1;
    if (!eligible || !Number.isFinite(previousSeason) || previousSeason <= 1900) return null;

    const previousSplits = await readGameLogSplits(previousSeason).catch(() => []);
    const previousDetails = summarizeLastFivePitchingAppearancesDetails(previousSplits, game);
    return previousDetails ? {
      ...previousDetails,
      historyTitle: `${previousDetails.historyTitle || 'RECENT APPEARANCES'} - ${previousSeason} MLB`,
      sourceSeason: String(previousSeason),
      sourceLabel: `${previousSeason} MLB`,
    } : null;
  })().catch((error) => {
    betPlayerLastFiveCache.delete(key);
    throw error;
  });
  betPlayerLastFiveCache.set(key, promise);
  return promise;
}

function compactMonthDayLabel(date) {
  const value = calendarDateOnly(date || '');
  const match = String(value || '').match(/^\d{4}-(\d{2})-(\d{2})$/);
  if (!match) return cleanSummary(date) || '--';
  return `${Number(match[1])}-${Number(match[2])}`;
}

function splitOpponentTeamAbbrev(split = {}) {
  return displayTeamAbbrev(
    split?.opponent?.abbreviation
      || split?.opponent?.teamCode
      || split?.opponent?.fileCode
      || split?.opponent?.name
      || split?.opponentTeam?.abbreviation
      || split?.opponentTeam?.teamCode
      || split?.opponentTeam?.name
      || '',
  );
}

async function fetchTeamStatsGroupThroughDate(season, group, endDate) {
  const selectedDate = calendarDateOnly(endDate || dateInput.value || formatDate(new Date()));
  if (!selectedDate) return new Map();
  const url = new URL(`${MLB_API_BASE}/teams/stats`);
  url.searchParams.set('stats', 'byDateRange');
  url.searchParams.set('group', group);
  url.searchParams.set('season', String(season));
  url.searchParams.set('gameType', 'R');
  url.searchParams.set('sportIds', '1');
  url.searchParams.set('startDate', `${season}-03-01`);
  url.searchParams.set('endDate', selectedDate);
  const response = await getJson(url.toString());
  const map = new Map();
  for (const split of listify(response?.stats?.[0]?.splits)) {
    const teamId = Number(split?.team?.id);
    if (!Number.isFinite(teamId)) continue;
    map.set(teamId, split?.stat || {});
  }
  return map;
}

function teamStrengthRowsFromStatMaps(teams = [], hittingMap = new Map(), pitchingMap = new Map()) {
  return listify(teams).map((team) => {
    const teamId = Number(team.id);
    const hitting = hittingMap.get(teamId) || {};
    const pitching = pitchingMap.get(teamId) || {};
    const abbrev = displayTeamAbbrev(team.abbreviation);
    return {
      id: teamId,
      abbrev,
      name: team.name,
      logo: getLogoPath(abbrev),
      color: getTeamColor(abbrev),
      runs: statNumber(hitting.runs),
      homeRuns: statNumber(hitting.homeRuns),
      avg: formatTeamRate(hitting.avg ?? hitting.battingAverage),
      slg: formatTeamRate(hitting.slg ?? hitting.sluggingPercentage),
      era: cleanSummary(pitching.era) || '---',
      battingAverageAgainst: formatTeamRate(pitching.avg ?? pitching.battingAverageAgainst ?? pitching.opponentsBattingAverage ?? pitching.opponentAvg),
      pitcherStrikeOuts: statNumber(pitching.strikeOuts),
      pitcherWalks: statNumber(pitching.baseOnBalls ?? pitching.walks),
      homeRunsAllowed: statNumber(pitching.homeRuns ?? pitching.hrAllowed ?? pitching.hr),
    };
  }).sort((a, b) => String(a.abbrev).localeCompare(String(b.abbrev)));
}

async function getTeamStrengthRows(date = '') {
  const selectedDate = calendarDateOnly(date || dateInput.value || formatDate(new Date()), dateInput.value || formatDate(new Date()));
  const season = seasonForDate(selectedDate);
  const cacheKey = `${season}:${selectedDate}:team-strength:v1`;
  if (teamStrengthCache.has(cacheKey)) return teamStrengthCache.get(cacheKey);
  const promise = (async () => {
    const rangeRows = await (async () => {
      const [teams, hittingMap, pitchingMap] = await Promise.all([
        getTeamsForSeason(season),
        fetchTeamStatsGroupThroughDate(season, 'hitting', selectedDate),
        fetchTeamStatsGroupThroughDate(season, 'pitching', selectedDate),
      ]);
      if (!hittingMap.size && !pitchingMap.size) return [];
      return teamStrengthRowsFromStatMaps(teams, hittingMap, pitchingMap);
    })().catch(() => []);
    return rangeRows.length ? rangeRows : getTeamStatsRows(season);
  })().catch((error) => {
    teamStrengthCache.delete(cacheKey);
    throw error;
  });
  teamStrengthCache.set(cacheKey, promise);
  return promise;
}

function teamStrengthNumeric(value) {
  if (value == null || value === '') return null;
  const numeric = Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

function rankTeamStrengthMetric(rows = [], valueFn, direction = 'desc') {
  const scored = listify(rows)
    .map((row) => ({ row, value: valueFn(row) }))
    .filter((entry) => entry.row?.abbrev && Number.isFinite(entry.value));
  scored.sort((a, b) => {
    if (a.value === b.value) return String(a.row.abbrev || '').localeCompare(String(b.row.abbrev || ''));
    return direction === 'asc' ? a.value - b.value : b.value - a.value;
  });
  const ranks = new Map();
  let rank = 0;
  let lastValue = null;
  scored.forEach((entry, index) => {
    if (index === 0 || entry.value !== lastValue) rank = index + 1;
    ranks.set(canonicalTeamAbbrev(entry.row.abbrev), rank);
    lastValue = entry.value;
  });
  return ranks;
}

function strengthScoreFromRank(rank, total) {
  const numericRank = Number(rank);
  const numericTotal = Number(total);
  if (!Number.isFinite(numericRank) || numericRank <= 0 || !Number.isFinite(numericTotal) || numericTotal <= 0) return 0;
  return Math.round(100 - (((numericRank - 1) / Math.max(1, numericTotal - 1)) * 100));
}

function assignOverallTeamStrengthRank(contexts = [], key) {
  const sorted = contexts
    .filter((context) => Number.isFinite(Number(context?.[key]?.score)))
    .sort((a, b) => {
      const diff = Number(b[key].score) - Number(a[key].score);
      return diff || String(a.abbrev || '').localeCompare(String(b.abbrev || ''));
    });
  let rank = 0;
  let lastScore = null;
  sorted.forEach((context, index) => {
    if (index === 0 || context[key].score !== lastScore) rank = index + 1;
    context[key].rank = rank;
    lastScore = context[key].score;
  });
}

function buildTeamStrengthContextMap(rows = []) {
  const usableRows = listify(rows).filter((row) => row?.abbrev);
  const avgRanks = rankTeamStrengthMetric(usableRows, (row) => statRate(row.avg), 'desc');
  const slgRanks = rankTeamStrengthMetric(usableRows, (row) => statRate(row.slg), 'desc');
  const runRanks = rankTeamStrengthMetric(usableRows, (row) => teamStrengthNumeric(row.runs), 'desc');
  const hrRanks = rankTeamStrengthMetric(usableRows, (row) => teamStrengthNumeric(row.homeRuns), 'desc');
  const eraRanks = rankTeamStrengthMetric(usableRows, (row) => statRate(row.era), 'asc');
  const baaRanks = rankTeamStrengthMetric(usableRows, (row) => statRate(row.battingAverageAgainst), 'asc');
  const pitcherKRanks = rankTeamStrengthMetric(usableRows, (row) => teamStrengthNumeric(row.pitcherStrikeOuts), 'desc');
  const pitcherWalkRanks = rankTeamStrengthMetric(usableRows, (row) => teamStrengthNumeric(row.pitcherWalks), 'asc');
  const hrAllowedRanks = rankTeamStrengthMetric(usableRows, (row) => teamStrengthNumeric(row.homeRunsAllowed), 'asc');
  const contexts = usableRows.map((row) => {
    const team = canonicalTeamAbbrev(row.abbrev);
    const avgRank = avgRanks.get(team) || 0;
    const slgRank = slgRanks.get(team) || 0;
    const runRank = runRanks.get(team) || 0;
    const hrRank = hrRanks.get(team) || 0;
    const eraRank = eraRanks.get(team) || 0;
    const baaRank = baaRanks.get(team) || 0;
    const pitcherKRank = pitcherKRanks.get(team) || 0;
    const pitcherWalkRank = pitcherWalkRanks.get(team) || 0;
    const hrAllowedRank = hrAllowedRanks.get(team) || 0;
    const hittingScore = Math.round(
      (strengthScoreFromRank(avgRank, avgRanks.size) * 0.28)
        + (strengthScoreFromRank(slgRank, slgRanks.size) * 0.28)
        + (strengthScoreFromRank(runRank, runRanks.size) * 0.22)
        + (strengthScoreFromRank(hrRank, hrRanks.size) * 0.22),
    );
    const pitchingScore = Math.round(
      (strengthScoreFromRank(eraRank, eraRanks.size) * 0.34)
        + (strengthScoreFromRank(baaRank, baaRanks.size) * 0.12)
        + (strengthScoreFromRank(pitcherKRank, pitcherKRanks.size) * 0.18)
        + (strengthScoreFromRank(pitcherWalkRank, pitcherWalkRanks.size) * 0.20)
        + (strengthScoreFromRank(hrAllowedRank, hrAllowedRanks.size) * 0.16),
    );
    return {
      abbrev: row.abbrev,
      logo: row.logo || getLogoPath(row.abbrev),
      color: row.color || getTeamColor(row.abbrev),
      hitting: {
        score: hittingScore,
        avg: cleanSummary(row.avg) || '---',
        slg: cleanSummary(row.slg) || '---',
        avgRank,
        slgRank,
        hrRank,
      },
      pitching: {
        score: pitchingScore,
        era: cleanSummary(row.era) || '---',
        eraRank,
        baa: cleanSummary(row.battingAverageAgainst) || '---',
        baaRank,
        hrAllowedRank,
      },
    };
  });
  assignOverallTeamStrengthRank(contexts, 'hitting');
  assignOverallTeamStrengthRank(contexts, 'pitching');
  return new Map(contexts.map((context) => [canonicalTeamAbbrev(context.abbrev), context]));
}

async function getTeamStrengthContextMap(date = '') {
  const rows = await getTeamStrengthRows(date);
  return buildTeamStrengthContextMap(rows);
}

function battingSeriesGroupsFromSplits(splits = [], game = null) {
  const eligible = filteredRecentHistorySplits(splits, game);
  const groups = [];
  for (let index = 0; index < eligible.length; index += 1) {
    const split = eligible[index];
    const stat = split?.stat || {};
    const hasPlateAppearance = statNumber(stat.plateAppearances ?? stat.gamesPlayed) > 0
      || statNumber(stat.atBats) > 0
      || statNumber(stat.baseOnBalls ?? stat.walks) > 0
      || statNumber(stat.hitByPitch) > 0
      || statNumber(stat.sacFlies) > 0
      || statNumber(stat.sacBunts) > 0
      || battingStatHomeRuns(stat) > 0
      || statNumber(stat.strikeOuts) > 0;
    if (!hasPlateAppearance) continue;
    const opponent = splitOpponentTeamAbbrev(split);
    const current = groups[groups.length - 1];
    if (current && current.opponent === opponent) {
      current.splits.push(split);
      current.startDate = split?.date || current.startDate;
      continue;
    }
    if (groups.length >= 5) break;
    groups.push({
      opponent,
      startDate: split?.date || '',
      endDate: split?.date || '',
      splits: [split],
    });
    if (groups.length >= 5) {
      const remainingOpponent = opponent;
      for (const next of eligible.slice(index + 1)) {
        if (splitOpponentTeamAbbrev(next) !== remainingOpponent) break;
        groups[groups.length - 1].splits.push(next);
        groups[groups.length - 1].startDate = next?.date || groups[groups.length - 1].startDate;
      }
      break;
    }
  }
  return groups.slice(0, 5);
}

function battingSeriesColumnFromGroup(group = {}, strengthMap = new Map(), gameStartedMap = new Map()) {
  const totals = listify(group.splits).reduce((sum, split) => {
    const stat = split?.stat || {};
    const directStarted = battingSplitGameStartedDirect(split);
    const gamePk = statLogSplitGamePk(split);
    const started = directStarted != null
      ? directStarted
      : (gameStartedMap.has(gamePk) ? gameStartedMap.get(gamePk) : null);
    sum.games += 1;
    sum.atBats += statNumber(stat.atBats);
    sum.hits += statNumber(stat.hits);
    sum.homeRuns += battingStatHomeRuns(stat);
    sum.walks += statNumber(stat.baseOnBalls ?? stat.walks);
    sum.hitByPitch += statNumber(stat.hitByPitch);
    sum.strikeOuts += statNumber(stat.strikeOuts);
    if (started != null) {
      sum.gamesStartedKnown += 1;
      sum.gamesStarted += Number(started) ? 1 : 0;
    }
    sum.totalBases += battingStatTotalBases(stat);
    return sum;
  }, { games: 0, gamesStarted: 0, gamesStartedKnown: 0, atBats: 0, hits: 0, homeRuns: 0, walks: 0, hitByPitch: 0, strikeOuts: 0, totalBases: 0 });
  const opponent = displayTeamAbbrev(group.opponent || '');
  const strength = strengthMap.get(canonicalTeamAbbrev(opponent)) || null;
  const pitching = strength?.pitching || {};
  const avg = totals.atBats > 0 ? formatRateValue(totals.hits / totals.atBats, 3, true) : '---';
  const iso = totals.atBats > 0 ? formatRateValue((totals.totalBases - totals.hits) / totals.atBats, 3, true) : '---';
  return {
    opponent,
    logo: strength?.logo || getLogoPath(opponent),
    color: strength?.color || getTeamColor(opponent),
    hits: totals.hits,
    atBats: totals.atBats,
    gamesStarted: totals.gamesStartedKnown ? totals.gamesStarted : null,
    homeRuns: totals.homeRuns,
    walks: totals.walks,
    hitByPitch: totals.hitByPitch,
    strikeOuts: totals.strikeOuts,
    avg,
    iso,
    baaRank: pitching.baaRank || 0,
    hrAllowedRank: pitching.hrAllowedRank || 0,
  };
}

function batterTeamSideFromFeed(feed = null, batterId = '') {
  const idKey = `ID${Number(batterId)}`;
  const boxscore = feed?.liveData?.boxscore || {};
  if (boxscore?.teams?.home?.players?.[idKey]) return 'home';
  if (boxscore?.teams?.away?.players?.[idKey]) return 'away';
  return '';
}

function starterPitcherFromFeed(feed = null, side = '') {
  const team = feed?.liveData?.boxscore?.teams?.[side] || {};
  const players = team.players || {};
  const pitcherIds = Array.isArray(team.pitchers) ? team.pitchers : [];
  const starterId = pitcherIds
    .map((rawId) => Number(rawId))
    .find((id) => statNumber(players[`ID${id}`]?.stats?.pitching?.gamesStarted) > 0);
  const fallbackId = starterId || Number(pitcherIds[0]);
  const player = players[`ID${fallbackId}`] || {};
  return fallbackId ? {
    id: fallbackId,
    name: cleanSummary(player?.person?.fullName || player?.person?.name || 'Starter'),
    hand: handednessCode(player?.person?.pitchHand?.code || player?.person?.pitchHand?.description || player?.pitchHand?.code || player?.pitchHand?.description || ''),
  } : null;
}

function battingSideForHalfInning(halfInning = '') {
  const half = String(halfInning || '').toLowerCase();
  if (half === 'top') return 'away';
  if (half === 'bottom') return 'home';
  return '';
}

function starterPitcherFacedBySideFromFeed(feed = null, batterSide = '') {
  const plays = listify(feed?.liveData?.plays?.allPlays);
  const firstTeamBattingPlay = plays.find((play) => battingSideForHalfInning(play?.about?.halfInning) === batterSide && Number(play?.matchup?.pitcher?.id) > 0);
  const pitcher = firstTeamBattingPlay?.matchup?.pitcher || {};
  const id = Number(pitcher.id);
  if (!Number.isFinite(id) || id <= 0) return null;
  return {
    id,
    name: cleanSummary(pitcher.fullName || pitcher.name || 'Starter'),
    hand: handednessCode(firstTeamBattingPlay?.matchup?.pitchHand?.code || firstTeamBattingPlay?.matchup?.pitchHand?.description || ''),
  };
}


function batterPitcherStatlineText(stat = {}) {
  const ab = statNumber(stat.atBats);
  const hits = statNumber(stat.hits);
  const parts = [`${hits}-${ab}`];
  if (statNumber(stat.homeRuns) > 0) parts.push(`${statNumber(stat.homeRuns)} HR`);
  if (statNumber(stat.rbi) > 0) parts.push(`${statNumber(stat.rbi)} RBI`);
  if (statNumber(stat.walks) > 0) parts.push(`${statNumber(stat.walks)} BB`);
  if (statNumber(stat.strikeOuts) > 0) parts.push(`${statNumber(stat.strikeOuts)} K`);
  return parts.join(' ');
}

function addBatterPitcherPlateAppearance(stat = {}, play = {}) {
  const eventType = String(play?.result?.eventType || '').toLowerCase();
  if (!eventType) return;
  if (!['walk', 'intent_walk', 'hit_by_pitch', 'sac_bunt', 'sac_fly', 'catcher_interf', 'catcher_interference'].includes(eventType)) {
    stat.atBats = statNumber(stat.atBats) + 1;
  }
  if (['single', 'double', 'triple', 'home_run'].includes(eventType)) stat.hits = statNumber(stat.hits) + 1;
  if (eventType === 'home_run') stat.homeRuns = statNumber(stat.homeRuns) + 1;
  if (eventType === 'strikeout' || eventType === 'strikeout_double_play') stat.strikeOuts = statNumber(stat.strikeOuts) + 1;
  if (eventType === 'walk' || eventType === 'intent_walk') stat.walks = statNumber(stat.walks) + 1;
  stat.rbi = statNumber(stat.rbi) + statNumber(play?.result?.rbi);
}

function batterPitcherStatlinesFromFeed(feed = null, batterId = '') {
  const id = Number(batterId);
  if (!Number.isFinite(id) || id <= 0) return [];
  const byPitcher = new Map();
  for (const play of listify(feed?.liveData?.plays?.allPlays)) {
    if (Number(play?.matchup?.batter?.id) !== id) continue;
    const pitcher = play?.matchup?.pitcher || {};
    const pitcherId = Number(pitcher?.id);
    if (!Number.isFinite(pitcherId) || pitcherId <= 0) continue;
    const existing = byPitcher.get(pitcherId) || {
      id: pitcherId,
      name: cleanSummary(pitcher?.fullName || pitcher?.name || 'Pitcher'),
      hand: handednessCode(play?.matchup?.pitchHand?.code || play?.matchup?.pitchHand?.description || ''),
      atBats: 0,
      hits: 0,
      homeRuns: 0,
      rbi: 0,
      walks: 0,
      strikeOuts: 0,
    };
    addBatterPitcherPlateAppearance(existing, play);
    byPitcher.set(pitcherId, existing);
  }
  return [...byPitcher.values()].filter((entry) => statNumber(entry.atBats) || statNumber(entry.walks));
}

function batterPitcherStatlineHoverTitle(lines = []) {
  const rows = listify(lines)
    .map((line) => `${line.name || 'Pitcher'}${line.hand ? ` (${line.hand})` : ''}: ${batterPitcherStatlineText(line)}`)
    .filter(Boolean);
  return rows.length ? rows.join('\n') : '';
}

async function batterSeriesStarterContextMap(playerId, groups = []) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return new Map();
  const gamePks = [...new Set(listify(groups)
    .flatMap((group) => listify(group.splits))
    .map((split) => statLogSplitGamePk(split))
    .filter((pk) => Number.isFinite(Number(pk)) && Number(pk) > 0))];
  const pairs = await mapWithConcurrency(gamePks, 4, async (gamePk) => {
    const feed = await getLiveGameFeed(gamePk).catch(() => null);
    const batterSide = batterTeamSideFromFeed(feed, id);
    const pitcherSide = batterSide === 'home' ? 'away' : batterSide === 'away' ? 'home' : '';
    const starter = starterPitcherFacedBySideFromFeed(feed, batterSide) || starterPitcherFromFeed(feed, pitcherSide);
    if (!starter) return [gamePk, null];
    const pitcherLines = batterPitcherStatlinesFromFeed(feed, id);
    let hrInStarterGame = false;
    let hrOffStarter = false;
    for (const play of listify(feed?.liveData?.plays?.allPlays)) {
      if (Number(play?.matchup?.batter?.id) !== id) continue;
      if (String(play?.result?.eventType || '').toLowerCase() !== 'home_run') continue;
      hrInStarterGame = true;
      if (Number(play?.matchup?.pitcher?.id) === Number(starter.id)) hrOffStarter = true;
    }
    return [gamePk, { ...starter, hrInStarterGame, hrOffStarter, pitcherLines }];
  });
  return new Map(pairs.filter((pair) => pair?.[1]));
}

function battingSeriesStarterDetails(group = {}, starterContext = new Map()) {
  return listify(group.splits)
    .map((split) => {
      const starter = starterContext.get(statLogSplitGamePk(split));
      if (!starter) return null;
      const splitHr = battingStatHomeRuns(split?.stat || {}) > 0;
      return {
        ...starter,
        hrInStarterGame: Boolean(starter.hrInStarterGame || splitHr),
        hrOffStarter: Boolean(starter.hrOffStarter || splitHr),
        pitcherLines: listify(starter.pitcherLines),
      };
    })
    .filter(Boolean);
}

function battingSeriesStarterHtml(starters = []) {
  if (!starters.length) return '';
  return `<div class="batter-series-starters">${starters.map((starter) => {
    const classes = [
      'batter-series-starter',
      starter.hrInStarterGame ? 'is-hr-game' : '',
      starter.hrOffStarter ? 'is-hr-off-starter' : '',
    ].filter(Boolean).join(' ');
    const label = `${starter.name || 'Starter'}${starter.hand ? ` (${starter.hand})` : ''}`;
    const hover = batterPitcherStatlineHoverTitle(starter.pitcherLines || []);
    const titleAttr = hover ? ` title="${escapeHtml(hover)}"` : '';
    const name = `<button type="button" class="player-card-link batter-series-starter-link" data-player-card-link data-player-id="${escapeHtml(starter.id || '')}" data-player-role="pitcher"${titleAttr}>${escapeHtml(label)}</button>`;
    const styledName = starter.hrOffStarter
      ? `<em><u>${name}</u></em>`
      : starter.hrInStarterGame
        ? `<em>${name}</em>`
        : name;
    return `<span class="${classes}">${styledName}</span>`;
  }).join('')}</div>`;
}

async function getBatterSeriesHistoryDetails(playerId, game = null) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = playerStatTargetDate(game);
  const liveKey = gameIsLiveForRecentHistory(game) ? String(game?.gamePk || 'live') : 'default';
  const cacheKey = `${id}:${selectedDate}:${liveKey}:batter-series:v5`;
  if (batterSeriesHistoryCache.has(cacheKey)) return batterSeriesHistoryCache.get(cacheKey);
  const promise = (async () => {
    const splits = await playerStatGameLogSplits(id, 'hitting', game);
    const groups = battingSeriesGroupsFromSplits(splits, game);
    const strengthDates = [...new Set(groups
      .map((group) => calendarDateOnly(group.endDate || selectedDate) || selectedDate)
      .map((date) => addDaysToDateValue(date, -1)))];
    const strengthPairs = await Promise.all(strengthDates.map(async (date) => [
      date,
      await getTeamStrengthContextMap(date).catch(() => new Map()),
    ]));
    const gameStartedMap = await batterGameStartedMapForGroups(id, groups).catch(() => new Map());
    const starterContext = await batterSeriesStarterContextMap(id, groups).catch(() => new Map());
    const strengthByDate = new Map(strengthPairs);
    return {
      asOfLabel: '',
      columns: groups.map((group) => {
        const strengthDate = addDaysToDateValue(calendarDateOnly(group.endDate || selectedDate) || selectedDate, -1);
        return {
          ...battingSeriesColumnFromGroup(group, strengthByDate.get(strengthDate) || new Map(), gameStartedMap),
          starters: battingSeriesStarterDetails(group, starterContext),
        };
      }),
    };
  })().catch((error) => {
    batterSeriesHistoryCache.delete(cacheKey);
    throw error;
  });
  batterSeriesHistoryCache.set(cacheKey, promise);
  return promise;
}

function renderBatterSeriesHistoryHtml(details = null) {
  const asOf = details?.asOfLabel || '';
  const columns = Array.isArray(details?.columns) ? details.columns : [];
  if (!details) {
    return `<strong>LAST 5 SERIES</strong><div class="pitcher-opponent-history-empty">Loading series strength</div>`;
  }
  if (!columns.length) {
    return `<strong>LAST 5 SERIES</strong><div class="pitcher-opponent-history-empty">Series history unavailable</div>`;
  }
  return `
    <strong>LAST 5 SERIES${asOf ? ` <span class="player-stat-source">${escapeHtml(asOf)}</span>` : ''}</strong>
    <div class="pitcher-opponent-history-grid batter-series-history-grid">
      ${columns.map((item) => `
        <article class="pitcher-opponent-history-col batter-series-history-col" style="--opp-color:${escapeHtml(item.color || '#7bd0ff')}" title="${escapeHtml(`${item.opponent}: ${item.hits}-${item.atBats}, ${item.gamesStarted ?? '--'} GS, ${item.homeRuns} HR, ${item.walks} BB, ${item.hitByPitch} HBP, ${item.strikeOuts} K`)}">
          <img src="${escapeHtml(item.logo || 'placeholder.png')}" alt="${escapeHtml(item.opponent || 'Opponent')} logo" />
          <div class="batter-series-lines">
            <b>${item.hits}-${item.atBats}</b>
            <span>AVG ${escapeHtml(item.avg || '---')}</span>
            <span>GS ${item.gamesStarted == null ? '--' : escapeHtml(item.gamesStarted)}</span>
            <span>HR ${escapeHtml(item.homeRuns ?? '--')}</span>
            <span>ISO ${escapeHtml(item.iso || '---')}</span>
          </div>
          ${battingSeriesStarterHtml(item.starters || [])}

        </article>
      `).join('')}
    </div>
  `;
}

function pitcherOpponentHistorySplits(splits = [], game = null, profile = null) {
  const appearances = filteredRecentHistorySplits(splits, game)
    .filter((split) => inningsToOuts(split?.stat?.inningsPitched) > 0 || statNumber(split?.stat?.gamesPlayed) > 0);
  if (!pitcherShouldUseStartHistory(profile)) return appearances.slice(0, 5);
  const starts = appearances.filter(isPitchingStartSplit).slice(0, 5);
  return (starts.length ? starts : appearances.slice(0, 5)).slice(0, 5);
}

function pitcherOpponentColumnFromSplit(split = {}, strengthMap = new Map()) {
  const stat = split?.stat || {};
  const opponent = splitOpponentTeamAbbrev(split);
  const strength = strengthMap.get(canonicalTeamAbbrev(opponent)) || null;
  const hitting = strength?.hitting || {};
  const hrBatters = listify(split?.hrAllowedDetails)
    .map((entry) => ({
      id: entry.id,
      label: `${entry.name}${entry.hand ? ` (${entry.hand})` : ''}`,
      pitchInfo: entry.pitchInfo || '',
    }));
  return {
    date: compactMonthDayLabel(split?.date || ''),
    opponent,
    logo: strength?.logo || getLogoPath(opponent),
    color: strength?.color || getTeamColor(opponent),
    innings: cleanSummary(stat.inningsPitched) || outsToInnings(inningsToOuts(stat.inningsPitched)),
    pitches: statNumber(stat.numberOfPitches ?? stat.pitchesThrown ?? stat.pitchCount ?? stat.pitches),
    hits: statNumber(stat.hits),
    homeRuns: statNumber(stat.homeRuns ?? stat.hrAllowed ?? stat.hr),
    earnedRuns: statNumber(stat.earnedRuns),
    hittingRank: hitting.rank || 0,
    avg: hitting.avg || '---',
    slg: hitting.slg || '---',
    avgRank: hitting.avgRank || 0,
    slgRank: hitting.slgRank || 0,
    hrRank: hitting.hrRank || 0,
    hrBatters,
  };
}

async function getPitcherOpponentHistoryDetails(playerId, game = null, profile = null) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return null;
  const selectedDate = playerStatTargetDate(game);
  const liveKey = gameIsLiveForRecentHistory(game) ? String(game?.gamePk || 'live') : 'default';
  const roleKey = pitcherShouldUseStartHistory(profile) ? 'starts' : 'apps';
  const fallbackSeason = Number(profile?.seasonStatSource?.pitching?.season || 0);
  const cacheKey = `${id}:${selectedDate}:${liveKey}:${roleKey}:pitcher-opponents:v3:${fallbackSeason || 'current'}`;
  if (pitcherOpponentHistoryCache.has(cacheKey)) return pitcherOpponentHistoryCache.get(cacheKey);
  const promise = (async () => {
    const splits = await playerStatGameLogSplits(id, 'pitching', game, fallbackSeason);
    const appearances = await enrichPitcherSplitsWithHrAllowedDetails(pitcherOpponentHistorySplits(splits, game, profile), id);
    const strengthDates = [...new Set(appearances
      .map((split) => calendarDateOnly(split?.date || ''))
      .filter(Boolean)
      .map((date) => addDaysToDateValue(date, -1)))];
    const strengthPairs = await Promise.all(strengthDates.map(async (date) => [
      date,
      await getTeamStrengthContextMap(date).catch(() => new Map()),
    ]));
    const strengthByDate = new Map(strengthPairs);
    return {
      asOfLabel: 'Daily SOS',
      columns: appearances.map((split) => {
        const strengthDate = addDaysToDateValue(calendarDateOnly(split?.date || selectedDate) || selectedDate, -1);
        return pitcherOpponentColumnFromSplit(split, strengthByDate.get(strengthDate) || new Map());
      }),
    };
  })().catch((error) => {
    pitcherOpponentHistoryCache.delete(cacheKey);
    throw error;
  });
  pitcherOpponentHistoryCache.set(cacheKey, promise);
  return promise;
}

function renderPitcherOpponentHistoryHtml(details = null) {
  const asOf = details?.asOfLabel || (details?.asOfDate ? `Through ${compactMonthDayLabel(details.asOfDate)}` : '');
  const columns = Array.isArray(details?.columns) ? details.columns : [];
  if (!details) {
    return `<strong>LAST 5 OPPONENTS</strong><div class="pitcher-opponent-history-empty">Loading opponent strength</div>`;
  }
  if (!columns.length) {
    return `<strong>LAST 5 OPPONENTS</strong><div class="pitcher-opponent-history-empty">Opponent history unavailable</div>`;
  }
  return `
    <strong>LAST 5 OPPONENTS${asOf ? ` <span class="player-stat-source">${escapeHtml(asOf)}</span>` : ''}</strong>
    <div class="pitcher-opponent-history-grid">
      ${columns.map((item) => `
        <article class="pitcher-opponent-history-col" style="--opp-color:${escapeHtml(item.color || '#7bd0ff')}">
          <span class="pitcher-opponent-date">${escapeHtml(item.date || '--')}</span>
          <img src="${escapeHtml(item.logo || 'placeholder.png')}" alt="${escapeHtml(item.opponent || 'Opponent')} logo" />
          <b>${escapeHtml(item.innings || '0.0')} IP</b>
          <b>${Number(item.pitches) > 0 ? `P${escapeHtml(item.pitches)}` : 'P--'}</b>
          <span>${item.hits} H</span>
          <span>${item.homeRuns} HR</span>
          ${item.hrBatters?.length ? `<span class="pitcher-opponent-hr-batters">${item.hrBatters.map((entry) => `<i><button type="button" class="player-card-link" data-player-card-link data-player-id="${escapeHtml(entry.id || '')}" data-player-role="hitter"${entry.pitchInfo ? ` title="${escapeHtml(entry.pitchInfo)}"` : ''}>${escapeHtml(entry.label || '')}</button></i>`).join('')}</span>` : ''}
          <span>${item.earnedRuns} ER</span>

        </article>
      `).join('')}
    </div>
  `;
}

function isVeryGoodPitchingAppearance(stat = {}) {
  const earnedRuns = statNumber(stat.earnedRuns);
  const hits = statNumber(stat.hits);
  return hits <= 4 && earnedRuns <= 1;
}

function isBadPitchingAppearance(stat = {}) {
  const earnedRuns = statNumber(stat.earnedRuns);
  const hits = statNumber(stat.hits);
  return hits > 6 && earnedRuns > 5;
}

function pitchingAppearanceHadHomeRun(stat = {}) {
  return statNumber(stat.homeRuns ?? stat.hrAllowed ?? stat.hr) > 0;
}

function isPitchingStartSplit(split = {}) {
  const stat = split?.stat || {};
  const rawStarts = stat.gamesStarted ?? stat.gameStarted ?? stat.starts;
  const starts = statNumber(rawStarts);
  if (starts > 0) return true;
  if (rawStarts != null && starts === 0) return false;
  return false;
}

function lastPitchingStartSplit(splits = []) {
  const selectedDate = dateInput.value || formatDate(new Date());
  return listify(splits)
    .filter((split) => split?.date && String(split.date) <= String(selectedDate))
    .filter(isPitchingStartSplit)
    .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')))[0] || null;
}

function pitcherFireStreakFromSplits(splits = []) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const appearances = listify(splits)
    .filter((split) => split?.date && String(split.date) <= String(selectedDate))
    .filter(isPitchingStartSplit)
    .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')))
    .slice(0, 3);
  let streak = 0;
  for (const appearance of appearances) {
    if (!isVeryGoodPitchingAppearance(appearance?.stat || {})) break;
    streak += 1;
  }
  return Math.min(3, streak);
}

function pitcherColdStreakFromSplits(splits = []) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const appearances = listify(splits)
    .filter((split) => split?.date && String(split.date) <= String(selectedDate))
    .filter(isPitchingStartSplit)
    .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')))
    .slice(0, 3);
  let streak = 0;
  for (const appearance of appearances) {
    if (!isBadPitchingAppearance(appearance?.stat || {})) break;
    streak += 1;
  }
  return Math.min(3, streak);
}

function pitcherLastStartHomeRunFromSplits(splits = []) {
  const lastStart = lastPitchingStartSplit(splits);
  return lastStart ? pitchingAppearanceHadHomeRun(lastStart.stat || {}) : false;
}

const pitcherHrAllowedDetailsCache = new Map();

async function pitcherHrAllowedDetailsForGame(gamePk, pitcherId) {
  const pk = Number(gamePk);
  const id = Number(pitcherId);
  if (!Number.isFinite(pk) || pk <= 0 || !Number.isFinite(id) || id <= 0) return [];
  const key = `${pk}:${id}:hr-allowed-batters`;
  if (pitcherHrAllowedDetailsCache.has(key)) return pitcherHrAllowedDetailsCache.get(key);
  const promise = (async () => {
    const live = await getLiveGameFeed(pk);
    return listify(live?.liveData?.plays?.allPlays)
      .filter((play) => String(play?.result?.eventType || '').toLowerCase() === 'home_run')
      .filter((play) => Number(play?.matchup?.pitcher?.id) === id)
      .map((play) => {
        const batter = play?.matchup?.batter || {};
        const hand = handednessCode(play?.matchup?.batSide?.code || play?.matchup?.batSide?.description || batter?.batSide?.code || batter?.batSide?.description || '');
        return {
          id: Number(batter?.id) || '',
          name: cleanSummary(batter?.fullName || batter?.name || 'Unknown'),
          hand,
          pitchInfo: typeof homeRunPitchDetailLine === 'function' ? homeRunPitchDetailLine(play) : '',
        };
      })
      .filter((entry) => entry.name);
  })().catch((error) => {
    pitcherHrAllowedDetailsCache.delete(key);
    throw error;
  });
  pitcherHrAllowedDetailsCache.set(key, promise);
  return promise;
}

async function enrichPitcherSplitsWithHrAllowedDetails(splits = [], pitcherId = '') {
  const id = Number(pitcherId);
  if (!Number.isFinite(id) || id <= 0) return splits;
  return Promise.all(listify(splits).map(async (split) => {
    if (statNumber(split?.stat?.homeRuns) <= 0) return split;
    const gamePk = statLogSplitGamePk(split);
    const hrAllowedDetails = await pitcherHrAllowedDetailsForGame(gamePk, id).catch(() => []);
    return { ...split, hrAllowedDetails };
  }));
}

async function getPitcherFireStreak(playerId) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return 0;
  const selectedDate = dateInput.value || formatDate(new Date());
  const key = `${id}:${selectedDate}:pitcher-fire-streak`;
  if (pitcherFireStreakCache.has(key)) return pitcherFireStreakCache.get(key);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'pitching');
    url.searchParams.set('season', String(seasonForDate(selectedDate)));
    url.searchParams.set('gameType', 'R');
    const response = await getJson(url.toString());
    return pitcherFireStreakFromSplits(response?.stats?.[0]?.splits || []);
  })().catch((error) => {
    pitcherFireStreakCache.delete(key);
    throw error;
  });
  pitcherFireStreakCache.set(key, promise);
  return promise;
}

