function hydratePitcherLastStartHrMarkers(rootEl) {
  const markers = Array.from(rootEl?.querySelectorAll?.('.pitcher-last-start-hr[data-pitcher-last-hr-id]') || []);
  if (!markers.length) return;
  const selectedDate = selectedPitcherMarkerDate();
  const pendingMarkers = markers.filter((marker) => marker.dataset.lastHrHydratedDate !== selectedDate || marker.dataset.lastHrHydratedId !== marker.dataset.pitcherLastHrId);
  if (!pendingMarkers.length) return;
  const ids = [...new Set(pendingMarkers.map((marker) => Number(marker.dataset.pitcherLastHrId)).filter((id) => Number.isFinite(id) && id > 0))];
  if (!ids.length) return;
  for (const marker of pendingMarkers) {
    const cached = pitcherCachedMarkerValue('lastHr', marker.dataset.pitcherLastHrId, selectedDate);
    if (cached !== undefined) {
      const allowed = cached === true;
      marker.textContent = allowed ? 'HR' : '';
      marker.title = allowed ? 'Allowed a home run in last start' : '';
      marker.dataset.lastHrHydratedDate = selectedDate;
      marker.dataset.lastHrHydratedId = String(marker.dataset.pitcherLastHrId || '');
    }
  }
  Promise.all(ids.map((id) => getPitcherLastStartHomeRun(id).then((allowed) => [id, allowed]).catch(() => [id, false])))
    .then((results) => {
      for (const [id, allowed] of results) pitcherSetCachedMarkerValue('lastHr', id, Boolean(allowed), selectedDate);
      if (selectedPitcherMarkerDate() !== selectedDate) return;
      const allowedMap = new Map(results);
      const currentMarkers = Array.from(rootEl?.querySelectorAll?.('.pitcher-last-start-hr[data-pitcher-last-hr-id]') || []);
      for (const marker of currentMarkers) {
        const markerId = Number(marker.dataset.pitcherLastHrId);
        if (!allowedMap.has(markerId)) continue;
        const allowed = Boolean(allowedMap.get(markerId));
        marker.textContent = allowed ? 'HR' : '';
        marker.title = allowed ? 'Allowed a home run in last start' : '';
        marker.dataset.lastHrHydratedDate = selectedDate;
        marker.dataset.lastHrHydratedId = String(marker.dataset.pitcherLastHrId || '');
      }
    })
    .catch(() => {});
}

function renderBetPlayerLastFive(pill, playerId) {
  const stats = pill.querySelector('.bet-leg-player-stats');
  if (!stats || !playerId) return;
  const token = `${playerId}:${dateInput.value || formatDate(new Date())}:${Date.now()}`;
  stats.dataset.lastFiveToken = token;
  stats.replaceChildren();
  const loading = document.createElement('span');
  loading.textContent = 'L5 loading';
  stats.appendChild(loading);
  getBetPlayerLastFiveLines(playerId)
    .then((lines) => {
      if (stats.dataset.lastFiveToken !== token) return;
      stats.replaceChildren();
      for (const line of lines || ['L5 unavailable']) {
        const row = document.createElement('span');
        row.textContent = line;
        stats.appendChild(row);
      }
    })
    .catch(() => {
      if (stats.dataset.lastFiveToken !== token) return;
      stats.replaceChildren();
      const row = document.createElement('span');
      row.textContent = 'L5 unavailable';
      stats.appendChild(row);
    });
}

function buildBetLegPill(leg) {
  const pill = document.createElement('span');
  const isTeamWin = isGamePickLeg(leg?.leg);
  pill.className = `bet-leg-pill bet-status-${leg.status}${isTeamWin ? ' bet-type-team' : ' bet-type-player'}`;
  if (leg.active) pill.classList.add('bet-leg-pill-active');
  if (leg?.candidate?.playerId) {
    pill.dataset.playerId = String(leg.candidate.playerId);
    pill.dataset.gamePk = String(leg.candidate.gamePk || '');
  }
  if (isTeamWin) {
    pill.dataset.gamePk = String(leg?.candidate?.gamePk || leg?.leg?.gamePk || '');
    pill.title = `${displayTeamAbbrev(leg?.leg?.teamAbbrev)} to win${leg?.label ? ` | ${leg.label}` : ''}`;
    const logo = document.createElement('img');
    logo.className = 'bet-leg-team-logo';
    setLogo(
      logo,
      leg?.candidate?.teamLogo || leg?.leg?.teamLogo || getLogoPath(leg?.leg?.teamAbbrev),
      `${displayTeamAbbrev(leg?.leg?.teamAbbrev)} logo`,
    );
    const goal = document.createElement('span');
    goal.className = 'bet-leg-team-goal';
    goal.textContent = 'WIN';
    pill.append(logo, goal);
    return pill;
  }
  const playerId = leg?.candidate?.playerId || leg?.leg?.playerId;
  const teamAbbrev = leg?.candidate?.teamAbbrev || leg?.leg?.teamAbbrev || '';
  const teamLogo = getLogoPath(teamAbbrev);
  const avatar = document.createElement('img');
  avatar.className = 'bet-leg-player-avatar';
  avatar.alt = `${leg?.leg?.playerName || leg?.candidate?.fullName || 'Player'} headshot`;
  loadStatCardImage(avatar, [
    Number.isFinite(Number(playerId)) ? playerHeadshotUrl(playerId) : '',
    teamLogo,
    'placeholder.png',
  ]);

  const text = document.createElement('span');
  text.className = 'bet-leg-player-text';

  const name = document.createElement('span');
  name.className = 'bet-leg-player-name';
  name.textContent = leg?.leg?.playerName || leg?.candidate?.fullName || 'Unknown';

  const goal = document.createElement('span');
  goal.className = 'bet-leg-player-goal';
  goal.textContent = formatBetLegProp(leg.leg);

  text.append(name, goal);
  pill.append(avatar, text);

  const stats = document.createElement('span');
  stats.className = 'bet-leg-player-stats';

  if (leg.status === 'unmatched') {
    const state = document.createElement('span');
    state.className = 'bet-leg-pill-state';
    state.textContent = leg.label;
    pill.append(state, stats);
    renderBetPlayerLastFive(pill, playerId);
    return pill;
  }

  if (normalizeBetTarget(leg.target) > 1) {
    pill.appendChild(createBetProgressBoxes(Math.min(leg.currentValue || 0, leg.target), leg.target, leg.status));
    pill.title = `${leg.currentValue || 0}/${leg.target}`;
    pill.appendChild(stats);
    renderBetPlayerLastFive(pill, playerId);
    return pill;
  }

  const state = document.createElement('span');
  state.className = 'bet-leg-pill-state';
  state.textContent = leg.label;
  pill.append(state, stats);
  renderBetPlayerLastFive(pill, playerId);
  return pill;
}

function buildBetSlipText(legs) {
  return (legs || []).map((leg) => (
    isGamePickLeg(leg)
      ? `${displayTeamAbbrev(leg.teamAbbrev)} WIN`
      : `${leg.playerName} ${formatBetLegProp(leg)}`
  )).join(' + ');
}

function betLegStatValue(candidate, leg) {
  const type = leg?.type || leg?.propType || 'hit';
  const prop = betPropDefinition(type);
  if (prop.statKey === 'tb') {
    return Number(candidate?.batting?.tb) || totalBasesFromBatting({
      hits: candidate?.batting?.hits,
      doubles: candidate?.batting?.doubles,
      triples: candidate?.batting?.triples,
      hr: candidate?.batting?.hr,
    });
  }
  if (prop.statKey === 'xbh') {
    return (Number(candidate?.batting?.hr) || 0) + (Number(candidate?.batting?.doubles) || 0) + (Number(candidate?.batting?.triples) || 0);
  }
  if (type === 'k') {
    return candidate?.isPitcher ? (Number(candidate?.pitching?.so) || 0) : (Number(candidate?.batting?.so) || 0);
  }
  return Number(candidate?.[prop.statKind]?.[prop.statKey]) || 0;
}

function betLegActive(candidate, leg) {
  const type = leg?.type || leg?.propType || 'hit';
  const prop = betPropDefinition(type);
  if (prop.statKind === 'pitching' || (type === 'k' && candidate?.isPitcher)) {
    return Number(candidate?.activePitcherId) === Number(candidate?.playerId);
  }
  return Number(candidate?.activeBatterId) === Number(candidate?.playerId);
}

function getBetSearchPool(games = latestRenderedGames) {
  const map = new Map();
  const upsert = (player = {}, fallback = {}, game = null) => {
    const id = Number(player?.id ?? player?.playerId ?? fallback?.id);
    if (!Number.isFinite(id)) return;
    const existing = map.get(String(id)) || {};
    const fullName = cleanSummary(player?.fullName || player?.playerName || player?.name || fallback?.fullName || fallback?.name || existing.playerName || 'Unknown');
    const teamAbbrev = canonicalTeamAbbrev(player?.teamAbbrev || player?.team || fallback?.teamAbbrev || fallback?.team || existing.teamAbbrev || '');
    const merged = {
      ...existing.profile,
      ...player,
      teamAbbrev,
      fullName,
    };
    map.set(String(id), {
      playerId: id,
      playerName: fullName,
      playerNameKey: normalizeNameKey(fullName),
      teamAbbrev,
      position: betSearchPrimaryPosition(merged),
      profile: merged,
      batting: betSearchBattingStats(merged),
      pitching: betSearchPitchingStats(merged),
      game: game || existing.game || null,
    });
  };
  for (const game of games || []) {
    for (const profile of Object.values(game?.playerLookup || {})) {
      upsert(profile, {}, game);
    }
    for (const entry of [
      ...(game?.lineup?.away || []),
      ...(game?.lineup?.home || []),
      ...(game?.lineup?.awayBench || []),
      ...(game?.lineup?.homeBench || []),
    ]) {
      upsert(entry, {}, game);
    }
  }
  return [...map.values()].sort((a, b) => (
    String(a.playerName || '').localeCompare(String(b.playerName || ''))
    || String(a.teamAbbrev || '').localeCompare(String(b.teamAbbrev || ''))
  ));
}

function betSearchBattingStats(player = {}) {
  return player?.batting
    || player?.seasonStats?.batting
    || player?.stats?.batting
    || player?.gameBatting
    || {};
}

function betSearchPitchingStats(player = {}) {
  return player?.pitching
    || player?.seasonStats?.pitching
    || player?.stats?.pitching
    || player?.gamePitching
    || {};
}

function betSearchRateValue(...values) {
  for (const value of values) {
    const parsed = rateNumber(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function betSearchStatValue(...values) {
  for (const value of values) {
    if (value === null || value === undefined || value === '') continue;
    const parsed = Number(String(value).replace(/,/g, ''));
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function betSearchIsPitcher(player = {}) {
  const rawPosition = cleanSummary(player?.position || player?.primaryPosition?.abbreviation || player?.primaryPosition?.code || '').toUpperCase();
  if (['P', 'SP', 'RP', 'CP'].includes(rawPosition)) return true;
  const pitching = betSearchPitchingStats(player);
  return Boolean(
    inningsToOuts(pitching?.inningsPitched) > 0
    || statNumber(pitching?.gamesPlayed ?? pitching?.gamesPitched ?? pitching?.gamesStarted) > 0
    || statNumber(pitching?.saves) > 0
  );
}

function betSearchPitcherRole(player = {}) {
  if (!betSearchIsPitcher(player)) return '';
  return cleanSummary(pitcherDisplayUsageRole(player, player?.role || player?.usageRole || player?.rankRole || '')).toUpperCase() || 'RP';
}

function betSearchPrimaryPosition(player = {}) {
  if (betSearchIsPitcher(player)) return betSearchPitcherRole(player) || 'P';
  const rawPosition = cleanSummary(player?.position || player?.primaryPosition?.abbreviation || player?.primaryPosition?.code || '').toUpperCase();
  return rawPosition || '';
}

function betSearchPlayerObp(player = {}) {
  const profileBatting = betSearchBattingStats(player?.profile || player);
  const batting = { ...(profileBatting || {}), ...(player?.batting || {}) };
  const direct = betSearchRateValue(
    batting?.obp,
    batting?.onBasePercentage,
    batting?.onBasePct,
    batting?.onBase,
    player?.obp,
    player?.onBasePercentage,
  );
  if (direct != null) return direct;
  const hits = betSearchStatValue(batting?.hits, batting?.h) || 0;
  const walks = betSearchStatValue(batting?.baseOnBalls, batting?.walks, batting?.bb) || 0;
  const hbp = betSearchStatValue(batting?.hitByPitch, batting?.hbp) || 0;
  const atBats = betSearchStatValue(batting?.atBats, batting?.ab) || 0;
  const sacFlies = betSearchStatValue(batting?.sacFlies, batting?.sacrificeFlies, batting?.sf) || 0;
  const denominator = atBats + walks + hbp + sacFlies;
  return denominator > 0 ? (hits + walks + hbp) / denominator : null;
}

function betSearchPlayerGamesPerHomeRun(player = {}) {
  const profileBatting = betSearchBattingStats(player?.profile || player);
  const batting = { ...(profileBatting || {}), ...(player?.batting || {}) };
  const homeRuns = betSearchStatValue(batting?.homeRuns, batting?.hr, batting?.homeruns, player?.homeRuns, player?.hr);
  if (homeRuns <= 0) return null;
  const games = betSearchStatValue(batting?.gamesPlayed, batting?.games, batting?.g, player?.gamesPlayed, player?.games);
  return games > 0 ? games / homeRuns : null;
}

function betSearchPlayerEra(player = {}) {
  return betSearchRateValue(player?.pitching?.era, pitcherEra(player?.profile || player));
}

function betSearchPlayerMatchesSkill(player = {}, skill = betPlayerSkillFilterEl?.value || '') {
  if (!skill) return true;
  const profile = player.profile || player;
  const role = betSearchPitcherRole(profile);
  const era = betSearchPlayerEra(player);
  if (skill === 'contact') return (betSearchPlayerObp(player) ?? 0) >= 0.350;
  if (skill === 'power') {
    const gamesPerHr = betSearchPlayerGamesPerHomeRun(player);
    return gamesPerHr != null && gamesPerHr < 5.2;
  }
  if (skill === 'qualityStarter') return role === 'SP' && era != null && era < 3.5;
  if (skill === 'qualityRelief') return role === 'RP' && era != null && era < 2;
  if (skill === 'qualityCloser') return role === 'CP' && era != null && era < 1.5;
  return true;
}

function betSearchPlayerMatchesPosition(player = {}, filter = betPlayerPositionFilterEl?.value || '') {
  if (!filter) return true;
  const position = cleanSummary(player.position || betSearchPrimaryPosition(player.profile || player)).toUpperCase();
  if (filter === 'IF') return ['1B', '2B', '3B', 'SS'].includes(position);
  if (filter === 'OF') return ['LF', 'CF', 'RF', 'OF'].includes(position);
  if (filter === 'MIF') return ['2B', 'SS'].includes(position);
  return position === cleanSummary(filter).toUpperCase();
}

function betSearchPlayerHand(player = {}) {
  const profile = player?.profile || player;
  const isPitcher = betSearchIsPitcher(profile) || ['SP', 'RP', 'CP', 'P'].includes(cleanSummary(player?.position || '').toUpperCase());
  const handValue = (value) => (value && typeof value === 'object' ? (value.code || value.description || '') : value);
  return handednessCode(isPitcher
    ? (profile?.throws || handValue(profile?.pitchHand) || player?.throws || handValue(player?.pitchHand))
    : (profile?.bats || handValue(profile?.batSide) || player?.bats || handValue(player?.batSide)));
}

function betSearchPlayerMatchesHand(player = {}, filter = betPlayerHandFilterEl?.value || '') {
  const hand = handednessCode(filter);
  if (!hand) return true;
  return betSearchPlayerHand(player) === hand;
}

function playerSearchNeedsHandProfile(player = {}) {
  if (!player?.id && !player?.playerId) return false;
  if (betSearchPlayerHand(player)) return false;
  const profile = player?.profile || player;
  if (betSearchIsPitcher(profile) || ['SP', 'RP', 'CP', 'P'].includes(cleanSummary(player?.position || '').toUpperCase())) return false;
  return Boolean(player?.game);
}

function requestPlayerSearchHandProfiles(players = [], rerender = null) {
  const targets = listify(players)
    .filter(playerSearchNeedsHandProfile)
    .filter((player) => {
      const key = `${player.game?.gamePk || 'game'}:${Number(player.id ?? player.playerId)}`;
      if (playerSearchHandProfileCache.has(key)) return false;
      playerSearchHandProfileCache.set(key, true);
      return true;
    })
    .slice(0, 150);
  if (!targets.length) return false;
  mapWithConcurrency(targets, 6, async (player) => {
    const id = Number(player.id ?? player.playerId);
    const game = player.game || null;
    const profile = await fetchMlbPlayerProfile(id, game, { role: 'hitter', allowFirstAppearanceFallback: false }).catch(() => null);
    if (!profile) return null;
    persistPlayerLookupForGame(game, { [String(id)]: { ...(game?.playerLookup?.[String(id)] || {}), ...profile } });
    return profile;
  }).then(() => {
    if (typeof rerender === 'function') rerender();
  }).catch(() => {});
  return true;
}

function selectedBetPlayerTeamClassification() {
  const date = String(dateInput?.value || formatDate(new Date()));
  return playerSearchTeamClassCache.get(date) || null;
}

function teamAbbrevFromStanding(team = {}) {
  return canonicalTeamAbbrev(team.abbreviation || team.abbrev || team.teamAbbrev || team.code || team.fileCode || '');
}

async function ensureBetPlayerTeamClassification() {
  const date = String(dateInput?.value || formatDate(new Date()));
  const cached = playerSearchTeamClassCache.get(date);
  if (cached?.ready) return cached;
  if (cached?.promise) return cached.promise;
  const pending = { ready: false, buyers: new Set(), sellers: new Set() };
  playerSearchTeamClassCache.set(date, pending);
  pending.promise = (async () => {
    const standings = await getPlayoffStandings(date);
    const buyers = new Set();
    const sellers = new Set();
    for (const league of ['AL', 'NL']) {
      const picture = playoffLeaguePicture(standings, league);
      const divisionLeaderIds = new Set((picture.divisionWinners || []).map((team) => String(team.id || '')));
      const lastWildCard = picture.lastWildCard || null;
      for (const team of (standings || []).filter((row) => row.league === league)) {
        if (!lastWildCard) continue;
        const teamAbbrev = teamAbbrevFromStanding(team);
        if (!teamAbbrev) continue;
        const gb = playoffGamesBackFromTeam(lastWildCard, team);
        if (!Number.isFinite(gb)) continue;
        const divisionLeader = divisionLeaderIds.has(String(team.id || ''));
        if (gb > 6) sellers.add(teamAbbrev);
        else if (!divisionLeader) buyers.add(teamAbbrev);
      }
    }
    const next = { ready: true, buyers, sellers };
    playerSearchTeamClassCache.set(date, next);
    return next;
  })();
  try {
    return await pending.promise;
  } catch (err) {
    playerSearchTeamClassCache.delete(date);
    throw err;
  }
}

function populateBetPlayerTeamFilterOptions(games = latestRenderedGames) {
  if (!betPlayerTeamFilterEl) return;
  const selected = betPlayerTeamFilterEl.value;
  const teams = new Set(Object.keys(TEAM_IDS || {}));
  for (const game of games || []) {
    if (game?.away) teams.add(canonicalTeamAbbrev(game.away));
    if (game?.home) teams.add(canonicalTeamAbbrev(game.home));
  }
  const values = [
    { value: '', label: 'All Teams' },
    { value: 'sellers', label: 'Seller Teams' },
    { value: 'buyers', label: 'Buyer Teams' },
    ...[...teams].filter(Boolean).sort().map((team) => ({ value: team, label: displayTeamAbbrev(team) })),
  ];
  const fingerprint = values.map((entry) => `${entry.value}:${entry.label}`).join('|');
  if (betPlayerTeamFilterEl.dataset.renderFingerprint !== fingerprint) {
    betPlayerTeamFilterEl.dataset.renderFingerprint = fingerprint;
    betPlayerTeamFilterEl.replaceChildren();
    for (const entry of values) {
      const option = document.createElement('option');
      option.value = entry.value;
      option.textContent = entry.label;
      betPlayerTeamFilterEl.appendChild(option);
    }
  }
  betPlayerTeamFilterEl.value = values.some((entry) => entry.value === selected) ? selected : '';
}

function populateBetPlayerPositionFilterOptions() {
  if (!betPlayerPositionFilterEl) return;
  const selected = betPlayerPositionFilterEl.value;
  const values = [
    { value: '', label: 'Any Position' },
    { value: 'IF', label: 'IF' },
    { value: 'OF', label: 'OF' },
    { value: 'MIF', label: 'Middle IF' },
    ...['C', '1B', '2B', '3B', 'SS', 'LF', 'CF', 'RF', 'OF', 'DH', 'SP', 'RP', 'CP'].map((position) => ({ value: position, label: position })),
  ];
  const fingerprint = values.map((entry) => `${entry.value}:${entry.label}`).join('|');
  if (betPlayerPositionFilterEl.dataset.renderFingerprint !== fingerprint) {
    betPlayerPositionFilterEl.dataset.renderFingerprint = fingerprint;
    betPlayerPositionFilterEl.replaceChildren();
    for (const entry of values) {
      const option = document.createElement('option');
      option.value = entry.value;
      option.textContent = entry.label;
      betPlayerPositionFilterEl.appendChild(option);
    }
  }
  betPlayerPositionFilterEl.value = values.some((entry) => entry.value === selected) ? selected : '';
}

function betPlayerSearchFiltersActive() {
  return Boolean(betPlayerTeamFilterEl?.value || betPlayerSkillFilterEl?.value || betPlayerPositionFilterEl?.value || betPlayerHandFilterEl?.value);
}

function betSearchPlayerMatchesTeam(player = {}, filter = betPlayerTeamFilterEl?.value || '') {
  if (!filter) return true;
  const team = canonicalTeamAbbrev(player.teamAbbrev || player.profile?.teamAbbrev || '');
  if (!team) return false;
  if (filter === 'buyers' || filter === 'sellers') {
    const classification = selectedBetPlayerTeamClassification();
    if (!classification?.ready) return true;
    return Boolean(classification[filter]?.has(team));
  }
  return sameTeamAbbrev(team, filter);
}

function betSearchPlayerMatchesFilters(player = {}) {
  return betSearchPlayerMatchesTeam(player)
    && betSearchPlayerMatchesSkill(player)
    && betSearchPlayerMatchesPosition(player)
    && betSearchPlayerMatchesHand(player);
}

function getFilteredBetSearchPool(games = latestRenderedGames) {
  return getBetSearchPool(games).filter(betSearchPlayerMatchesFilters);
}

