function globalPlayerSearchFiltersActive() {
  return Boolean(globalPlayerTeamFilterEl?.value || globalPlayerSkillFilterEl?.value || globalPlayerPositionFilterEl?.value || globalPlayerAgeFilterEl?.value || globalPlayerHandFilterEl?.value);
}

function globalPlayerSearchAge(player = {}) {
  const direct = Number(player?.profile?.age ?? player?.age);
  if (Number.isFinite(direct) && direct > 0) return direct;
  const rows = playerContractsRows.length ? playerContractsRows : (Array.isArray(window.MLB_CONTRACT_ROWS) ? window.MLB_CONTRACT_ROWS : []);
  const contractRow = rows.length ? playerContractRowForProfile(rows, player?.profile || player) : null;
  const contractAge = Number(contractRow?.age);
  return Number.isFinite(contractAge) && contractAge > 0 ? contractAge : null;
}

function globalPlayerSearchMatchesAge(player = {}, filter = globalPlayerAgeFilterEl?.value || '') {
  if (!filter) return true;
  const match = String(filter).match(/^(\d+)-(\d+)$/);
  if (!match) return true;
  const age = globalPlayerSearchAge(player);
  if (age == null) return false;
  const low = Number(match[1]);
  const high = Number(match[2]);
  return age >= low && age <= high;
}

function globalPlayerSearchMatchesFilters(player = {}) {
  return betSearchPlayerMatchesTeam(player, globalPlayerTeamFilterEl?.value || '')
    && betSearchPlayerMatchesSkill(player, globalPlayerSkillFilterEl?.value || '')
    && betSearchPlayerMatchesPosition(player, globalPlayerPositionFilterEl?.value || '')
    && globalPlayerSearchMatchesAge(player)
    && betSearchPlayerMatchesHand(player, globalPlayerHandFilterEl?.value || '');
}

function globalPlayerSearchGames() {
  const map = new Map();
  for (const game of [...(latestRenderedGames || []), ...getCachedGames()]) {
    const key = String(game?.gamePk || '');
    if (key && !map.has(key)) map.set(key, game);
  }
  return [...map.values()];
}

function globalPlayerSearchPool(games = globalPlayerSearchGames()) {
  const map = new Map();
  const upsert = (player, game, sourceRank = 0) => {
    const id = Number(player?.id ?? player?.playerId);
    if (!Number.isFinite(id) || id <= 0) return;
    const existing = map.get(String(id));
    const fullName = cleanSummary(player?.fullName || player?.playerName || player?.name || existing?.fullName || 'Unknown');
    const teamAbbrev = canonicalTeamAbbrev(player?.teamAbbrev || player?.team || existing?.teamAbbrev || '');
    const profile = {
      ...(existing?.profile || {}),
      ...player,
      id,
      fullName,
      teamAbbrev,
    };
    const next = {
      id,
      fullName,
      nameKey: normalizeNameKey(fullName),
      position: betSearchPrimaryPosition(profile) || cleanSummary(player?.position || existing?.position || '-'),
      teamAbbrev,
      teamColor: player?.teamColor || existing?.teamColor || getTeamColor(teamAbbrev),
      headshot: player?.headshot || existing?.headshot || playerHeadshotUrl(id),
      game: game || existing?.game || null,
      sourceRank: Math.max(sourceRank, existing?.sourceRank || 0),
      profile,
      batting: betSearchBattingStats(profile),
      pitching: betSearchPitchingStats(profile),
    };
    map.set(String(id), next);
  };
  for (const game of games || []) {
    for (const profile of Object.values(game?.playerLookup || {})) {
      upsert(profile, game, 2);
    }
    for (const entry of [
      ...(game?.lineup?.away || []),
      ...(game?.lineup?.home || []),
      ...(game?.lineup?.awayBench || []),
      ...(game?.lineup?.homeBench || []),
    ]) {
      upsert({
        id: entry?.id,
        fullName: entry?.fullName || entry?.name,
        position: entry?.position,
        bats: entry?.bats || entry?.batSide?.code || entry?.batSide?.description || '',
        throws: entry?.throws || entry?.pitchHand?.code || entry?.pitchHand?.description || '',
        teamAbbrev: entry?.teamAbbrev || entry?.team,
      }, game, 1);
    }
  }
  return [...map.values()].filter((player) => player.nameKey && player.nameKey !== 'unknown');
}

function globalPlayerSearchScore(player, query) {
  const raw = cleanSummary(query).toLowerCase();
  const q = normalizeNameKey(raw);
  const parts = q.split(' ').filter(Boolean);
  if (!q) return 0;
  const name = player.nameKey || normalizeNameKey(player.fullName);
  const nameParts = name.split(' ').filter(Boolean);
  const first = nameParts[0] || '';
  const last = nameParts[nameParts.length - 1] || '';
  if (parts.length >= 2) {
    const firstNeedle = parts[0];
    const lastNeedle = parts[parts.length - 1];
    if (first.startsWith(firstNeedle) && last.startsWith(lastNeedle)) return 100 - Math.min(40, name.length / 2);
    if (nameParts.some((part) => part.startsWith(firstNeedle)) && nameParts.some((part) => part.startsWith(lastNeedle))) return 78;
    return 0;
  }
  if (q.length < 3) return 0;
  if (first.startsWith(q)) return 95;
  if (last.startsWith(q)) return 90;
  if (name.startsWith(q)) return 86;
  if (nameParts.some((part) => part.startsWith(q))) return 76;
  if (name.includes(q)) return 58;
  return 0;
}

function renderGlobalPlayerSearchResults(query = '') {
  if (!globalPlayerSearchResultsEl) return;
  populateGlobalPlayerTeamFilterOptions();
  populateGlobalPlayerPositionFilterOptions();
  const q = cleanSummary(query);
  const normalized = normalizeNameKey(q);
  const parts = normalized.split(' ').filter(Boolean);
  const ready = normalized.length >= 3 || parts.length >= 2 || globalPlayerSearchFiltersActive();
  if (!ready) {
    globalPlayerSearchResultsEl.innerHTML = '<div class="global-player-search-empty">Type 3 letters, or initials like r d</div>';
    return;
  }
  const teamFilter = globalPlayerTeamFilterEl?.value || '';
  const classification = selectedBetPlayerTeamClassification();
  if ((teamFilter === 'buyers' || teamFilter === 'sellers') && !classification?.ready) {
    ensureBetPlayerTeamClassification()
      .then(() => renderGlobalPlayerSearchResults(globalPlayerSearchInputEl?.value || ''))
      .catch(() => {});
  }
  const pool = globalPlayerSearchPool();
  const scored = pool
    .map((player) => ({ player, score: normalized ? globalPlayerSearchScore(player, q) : 1 }))
    .filter((entry) => entry.score > 0 || globalPlayerSearchFiltersActive());
  const hydratingHands = handednessCode(globalPlayerHandFilterEl?.value || '')
    ? requestPlayerSearchHandProfiles(scored.map((entry) => entry.player), () => renderGlobalPlayerSearchResults(globalPlayerSearchInputEl?.value || ''))
    : false;
  const results = scored
    .map((entry) => entry.player)
    .filter(globalPlayerSearchMatchesFilters)
    .map((player) => ({ player, score: normalized ? globalPlayerSearchScore(player, q) : 1 }))
    .sort((a, b) => (
      b.score - a.score
      || b.player.sourceRank - a.player.sourceRank
      || String(a.player.teamAbbrev || '').localeCompare(String(b.player.teamAbbrev || ''))
      || String(a.player.fullName).localeCompare(String(b.player.fullName))
    ))
    .slice(0, globalPlayerSearchFiltersActive() ? 30 : 12);
  if (!results.length) {
    globalPlayerSearchResultsEl.innerHTML = hydratingHands
      ? '<div class="global-player-search-empty">Loading handedness...</div>'
      : '<div class="global-player-search-empty">No matching players</div>';
    return;
  }
  globalPlayerSearchResultsEl.innerHTML = results.map(({ player }, index) => `
    <button type="button" class="global-player-search-result" role="option" data-global-player-id="${player.id}" data-game-pk="${escapeHtml(player.game?.gamePk || '')}" style="--result-team-color:${escapeHtml(player.teamColor || getTeamColor(player.teamAbbrev) || '#7bd0ff')}">
      <img src="${escapeHtml(player.headshot || playerHeadshotUrl(player.id))}" alt="" loading="lazy" />
      <strong>${escapeHtml(player.fullName)}</strong>
      <span>${escapeHtml(`${player.position || '-'}${betSearchPlayerHand(player) ? ` | ${betSearchPlayerHand(player)}` : ''}`)}</span>
    </button>
  `).join('');
}

function openGlobalPlayerSearch() {
  if (!globalPlayerSearchOverlayEl || !globalPlayerSearchInputEl) return;
  globalPlayerSearchOverlayEl.hidden = false;
  globalPlayerSearchInputEl.value = '';
  renderGlobalPlayerSearchResults('');
  window.setTimeout(() => globalPlayerSearchInputEl.focus(), 0);
}

function closeGlobalPlayerSearch() {
  if (!globalPlayerSearchOverlayEl) return;
  globalPlayerSearchOverlayEl.hidden = true;
}

function selectGlobalPlayerSearchResult(button) {
  const playerId = Number(button?.dataset?.globalPlayerId);
  if (!Number.isFinite(playerId) || playerId <= 0) return;
  const gamePk = button?.dataset?.gamePk || '';
  const games = globalPlayerSearchGames();
  const game = games.find((candidate) => String(candidate?.gamePk || '') === String(gamePk))
    || games.find((candidate) => Boolean(candidate?.playerLookup?.[String(playerId)]))
    || games.find((candidate) => [
      ...(candidate?.lineup?.away || []),
      ...(candidate?.lineup?.home || []),
      ...(candidate?.lineup?.awayBench || []),
      ...(candidate?.lineup?.homeBench || []),
    ].some((entry) => Number(entry?.id) === playerId));
  closeGlobalPlayerSearch();
  returnToGlobalSearchOnPlayerClose = Boolean(game);
  if (game) openPlayerStatOverlay(playerId, game);
}

function getBetTeamSearchPool(games = latestRenderedGames) {
  const teams = [];
  for (const game of games || []) {
    for (const side of ['away', 'home']) {
      const isAway = side === 'away';
      const teamAbbrev = isAway ? game?.away : game?.home;
      const opponentAbbrev = isAway ? game?.home : game?.away;
      if (!teamAbbrev || !game?.gamePk) continue;
      teams.push({
        gamePk: game.gamePk,
        side,
        teamAbbrev,
        opponentAbbrev,
        teamLogo: isAway ? game.awayLogo : game.homeLogo,
        teamColor: isAway ? game.awayColor : game.homeColor,
        teamNameKey: normalizeNameKey(`${teamSearchText(teamAbbrev)} win w`),
        label: `${displayTeamAbbrev(teamAbbrev)} W vs ${displayTeamAbbrev(opponentAbbrev)}`,
        value: `${displayTeamAbbrev(teamAbbrev)} W vs ${displayTeamAbbrev(opponentAbbrev)} | ${game.gamePk} | ${side}`,
        game,
      });
    }
  }
  return teams.sort((a, b) => (
    String(a.teamAbbrev || '').localeCompare(String(b.teamAbbrev || ''))
    || String(a.opponentAbbrev || '').localeCompare(String(b.opponentAbbrev || ''))
  ));
}

function refreshBetPlayerOptions(games = latestRenderedGames, searchValue = betPlayerSearchEl?.value || '') {
  if (!betPlayerOptionsEl) return;
  populateBetPlayerTeamFilterOptions(games);
  populateBetPlayerPositionFilterOptions();
  const query = normalizeNameKey(searchValue);
  const values = [];
  if (query.length >= 1) {
    const matches = getBetTeamSearchPool(games).filter((team) => (
      team.teamNameKey.includes(query)
      || normalizeNameKey(team.label).includes(query)
      || query.includes(normalizeNameKey(team.teamAbbrev))
    )).slice(0, 12);
    for (const team of matches) {
      values.push(team.value);
    }
    if (betBuilderIsTeamWin()) {
      renderBetOptionValues(values);
      return;
    }
  }
  if (!betBuilderIsTeamWin() && (query.length >= BET_PLAYER_SEARCH_MIN_CHARS || betPlayerSearchFiltersActive())) {
    const teamFilter = betPlayerTeamFilterEl?.value || '';
    const classification = selectedBetPlayerTeamClassification();
    if ((teamFilter === 'buyers' || teamFilter === 'sellers') && !classification?.ready) {
      ensureBetPlayerTeamClassification()
        .then(() => refreshBetPlayerOptions(games, betPlayerSearchEl?.value || ''))
        .catch(() => {});
    }
    const pool = getBetSearchPool(games);
    const queryPool = pool.filter((player) => !query || player.playerNameKey.includes(query));
    if (handednessCode(betPlayerHandFilterEl?.value || '')) {
      requestPlayerSearchHandProfiles(queryPool, () => refreshBetPlayerOptions(games, betPlayerSearchEl?.value || ''));
    }
    const matches = queryPool
      .filter(betSearchPlayerMatchesFilters)
      .slice(0, 50);
    for (const player of matches) {
      values.push(`${player.playerName} | ${player.teamAbbrev || 'MLB'} | ${player.playerId}`);
    }
  }
  renderBetOptionValues(values);
}

function renderBetOptionValues(values = []) {
  if (!betPlayerOptionsEl) return;
  const fingerprint = values.join('\n');
  if (betPlayerOptionsEl.dataset.renderFingerprint === fingerprint) return;
  betPlayerOptionsEl.dataset.renderFingerprint = fingerprint;
  betPlayerOptionsEl.replaceChildren();
  for (const value of values) {
    const option = document.createElement('option');
    option.value = value;
    betPlayerOptionsEl.appendChild(option);
  }
}

function getBetPlayerOptionValues() {
  return betPlayerOptionsEl ? Array.from(betPlayerOptionsEl.options).map((option) => option.value) : [];
}

function maybeSelectSingleBetPlayerOption() {
  if (!betPlayerSearchEl) return false;
  const options = getBetPlayerOptionValues();
  if (options.length !== 1) return false;
  betPlayerSearchEl.value = options[0];
  refreshBetPlayerOptions(latestRenderedGames, betPlayerSearchEl.value);
  return true;
}

function resolveBetSearchPlayer(searchValue, games = latestRenderedGames) {
  const text = cleanSummary(searchValue);
  if (!text) return null;
  const idMatch = text.match(/(?:\||#)\s*(\d{4,})\s*$/);
  const pool = getFilteredBetSearchPool(games);
  if (idMatch) {
    const match = pool.find((player) => String(player.playerId) === String(idMatch[1]));
    if (match) return match;
  }
  const nameOnly = normalizeNameKey(text.split('|')[0] || text);
  const exact = pool.find((player) => player.playerNameKey === nameOnly);
  if (exact) return exact;
  const fuzzy = pool.filter((player) => player.playerNameKey.includes(nameOnly) || nameOnly.includes(player.playerNameKey));
  return fuzzy.length === 1 ? fuzzy[0] : null;
}

function resolveBetSearchTeam(searchValue, games = latestRenderedGames) {
  const text = cleanSummary(searchValue);
  if (!text) return null;
  const teams = getBetTeamSearchPool(games);
  const parts = text.split('|').map((part) => cleanSummary(part)).filter(Boolean);
  if (parts.length >= 3) {
    const gamePk = parts[parts.length - 2];
    const side = normalizeGamePickSide(parts[parts.length - 1]);
    const exact = teams.find((team) => String(team.gamePk) === String(gamePk) && team.side === side);
    if (exact) return exact;
  }
  const query = normalizeNameKey((text.split('|')[0] || text).replace(/\b(?:w|win|wins|to win|moneyline|ml)\b/gi, '').split(' vs ')[0] || text);
  const exact = teams.filter((team) => (
    normalizeNameKey(team.teamAbbrev) === query
    || normalizeNameKey(displayTeamAbbrev(team.teamAbbrev)) === query
    || normalizeNameKey(TEAM_SEARCH_NAMES[canonicalTeamAbbrev(team.teamAbbrev)] || '').split(/\s+/).includes(query)
  ));
  if (exact.length === 1) return exact[0];
  const fuzzy = teams.filter((team) => team.teamNameKey.includes(query) || query.includes(normalizeNameKey(team.teamAbbrev)));
  return fuzzy.length === 1 ? fuzzy[0] : null;
}

function updateBetBuilderMode() {
  const isTeamWin = betBuilderIsTeamWin();
  if (betPlayerSearchEl) {
    betPlayerSearchEl.placeholder = isTeamWin ? 'Search team' : 'Search player';
    betPlayerSearchEl.value = '';
  }
  if (betPropTargetEl) {
    betPropTargetEl.value = '1';
    betPropTargetEl.disabled = isTeamWin;
    betPropTargetEl.closest('label')?.classList.toggle('is-disabled', isTeamWin);
  }
  for (const filter of [betPlayerTeamFilterEl, betPlayerSkillFilterEl, betPlayerPositionFilterEl, betPlayerHandFilterEl]) {
    if (!filter) continue;
    filter.disabled = isTeamWin;
    filter.closest('label')?.classList.toggle('is-disabled', isTeamWin);
  }
  refreshBetPlayerOptions();
}

function renderDraftBetSlip() {
  if (!betDescEl) return;
  if (draftBetLegs.length) {
    betDescEl.value = buildBetSlipText(draftBetLegs);
  }
}

function clearDraftBetSlip() {
  draftBetLegs = [];
  if (betDescEl) betDescEl.value = '';
  if (betPlayerSearchEl) betPlayerSearchEl.value = '';
  if (betPropSelectEl) betPropSelectEl.value = 'hit';
  if (betPropTargetEl) betPropTargetEl.value = '1';
  updateBetBuilderMode();
  refreshBetPlayerOptions();
  focusBetPlayerSearch();
}

function addDraftBetLeg() {
  const propType = betPropSelectEl?.value || 'hit';
  const target = normalizeBetTarget(betPropTargetEl?.value || 1);
  const team = resolveBetSearchTeam(betPlayerSearchEl?.value || '', latestRenderedGames);
  if (propType === 'teamWin' || team) {
    if (!team) return false;
    const leg = createGamePickLeg(team.game, team.side);
    if (!leg) return false;
    const exists = draftBetLegs.some((existing) => (
      isGamePickLeg(existing)
      && String(existing.gamePk) === String(leg.gamePk)
      && normalizeGamePickSide(existing.side) === normalizeGamePickSide(leg.side)
    ));
    if (exists) return false;
    draftBetLegs.push(leg);
    renderDraftBetSlip();
    if (betPlayerSearchEl) betPlayerSearchEl.value = '';
    refreshBetPlayerOptions();
    focusBetPlayerSearch();
    return true;
  }
  const player = resolveBetSearchPlayer(betPlayerSearchEl?.value || '', latestRenderedGames);
  if (!player) return false;
  const exists = draftBetLegs.some((leg) => (
    String(leg.playerId) === String(player.playerId)
    && leg.propType === propType
    && normalizeBetTarget(leg.target) === target
  ));
  if (exists) return false;
  draftBetLegs.push({
    playerId: player.playerId,
    playerName: player.playerName,
    playerNameKey: player.playerNameKey,
    teamAbbrev: player.teamAbbrev,
    propType,
    target,
  });
  renderDraftBetSlip();
  if (betPlayerSearchEl) betPlayerSearchEl.value = '';
  if (betPropTargetEl) betPropTargetEl.value = '1';
  refreshBetPlayerOptions();
  focusBetPlayerSearch();
  return true;
}

function betContextTargetPlayer(target) {
  if (!(target instanceof Element)) return null;
  const row = target.closest('[data-player-id]');
  const playerId = Number(row?.dataset?.playerId);
  if (!Number.isFinite(playerId) || playerId <= 0) return null;

  const game = (lineupOverlayEl && !lineupOverlayEl.hidden && activeLineupGame)
    ? activeLineupGame
    : latestRenderedGames.find((candidate) => candidate?.playerLookup?.[String(playerId)])
      || null;
  if (!game) return null;

  const profile = game.playerLookup?.[String(playerId)] || {};
  const name = profile.fullName || row.getAttribute('title') || row.querySelector?.('.lineup-name')?.textContent || row.textContent || '';
  const rowPosition = row.querySelector?.('.lineup-pos')?.textContent || row.dataset?.position || '';
  const position = rowPosition || profile.position || '';
  const pitcherRow = Boolean(row.closest?.('.lineup-team-pitcher, .current-pitcher-card, .bullpen-item, .pitching-history-list'));
  const hitterRow = Boolean(row.closest?.('.lineup-list')) || row.classList.contains('lineup-sub-player');
    return {
      playerId,
      playerName: cleanSummary(name).replace(/\s+/g, ' ') || 'Unknown',
      playerNameKey: profile.fullNameKey || normalizeNameKey(name),
      teamAbbrev: profile.teamAbbrev || row.dataset.team || '',
      position,
      isPitcher: pitcherRow || (!hitterRow && lineupEntryIsPitcherOnly({ ...profile, position })),
    };
}

function quickAddBetLeg(player, propType, target = 1) {
  if (!player || !propType) return false;
  const normalizedTarget = normalizeBetTarget(target);
  draftBetLegs.push({
    playerId: player.playerId,
    playerName: player.playerName,
    playerNameKey: player.playerNameKey || normalizeNameKey(player.playerName),
    teamAbbrev: player.teamAbbrev || '',
    propType,
    target: normalizedTarget,
  });
  renderDraftBetSlip();
  if (betPropTargetEl) betPropTargetEl.value = '1';
  betOddsEl?.focus();
  return true;
}

function openBetContextMenu(player, x, y) {
  const existing = document.getElementById('playerBetMenu');
  if (existing) existing.remove();
  activeBetContextMenuPlayer = player;
  const menu = document.createElement('div');
  menu.id = 'playerBetMenu';
  menu.className = 'player-bet-menu';
  const props = player.isPitcher
    ? [['pitcherK', 'K'], ['pitcherBB', 'BB'], ['pitcherHits', 'Hits Allowed'], ['pitcherER', 'ER'], ['pitcherHR', 'HR Allowed']]
    : [['hit', 'Hit'], ['double', '2B'], ['triple', '3B'], ['hr', 'HR'], ['run', 'Run'], ['tb', 'Total Bases'], ['xbh', 'XBH'], ['rbi', 'RBI'], ['k', 'K']];
  menu.innerHTML = `
    <div class="player-bet-menu-head">
      <strong>${escapeHtml(player.playerName)}</strong>
      <span>${escapeHtml(displayTeamAbbrev(player.teamAbbrev || ''))}</span>
    </div>
    <button class="player-bet-menu-track" type="button" data-menu-action="track-player">Track Player</button>
    <label class="player-bet-menu-target"><span>#</span><input type="number" min="1" step="1" value="1" /></label>
    <div class="player-bet-menu-options"></div>
  `;
  const optionsEl = menu.querySelector('.player-bet-menu-options');
  for (const [prop, label] of props) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.dataset.propType = prop;
    btn.textContent = label;
    optionsEl.appendChild(btn);
  }
  const handleMenuAction = (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const propBtn = target?.closest?.('[data-prop-type]');
    const trackBtn = target?.closest?.('[data-menu-action="track-player"]');
    const expectationBtn = target?.closest?.('[data-expectation-value]');
    if (!propBtn && !trackBtn && !expectationBtn) return;
    event.preventDefault();
    event.stopPropagation();
    if (trackBtn) {
      showTrackExpectationStep(menu, player);
      return;
    }
    try {
      if (expectationBtn) {
        addPlayerToTracker(player, { expectation: expectationBtn.dataset.expectationValue });
      } else {
        quickAddBetLeg(player, propBtn.dataset.propType, menu.querySelector('input')?.value || 1);
      }
    } catch (error) {
      console.warn('Player context menu action failed', error);
    } finally {
      if (activeBetContextMenuPlayer === player) activeBetContextMenuPlayer = null;
      menu.remove();
    }
  };
  menu.addEventListener('pointerdown', (event) => {
    event.stopPropagation();
    handleMenuAction(event);
  }, true);
  menu.addEventListener('mousedown', (event) => {
    event.stopPropagation();
    handleMenuAction(event);
  }, true);
  menu.addEventListener('click', handleMenuAction, true);
  menu.addEventListener('contextmenu', (event) => event.preventDefault());
  document.body.appendChild(menu);
  const rect = menu.getBoundingClientRect();
  menu.style.left = `${Math.min(Math.max(8, x), window.innerWidth - rect.width - 8)}px`;
  menu.style.top = `${Math.min(Math.max(8, y), window.innerHeight - rect.height - 8)}px`;
}

function showTrackExpectationStep(menu, player) {
  menu.innerHTML = `
    <div class="player-bet-menu-head">
      <strong>${escapeHtml(player.playerName)}</strong>
      <span>What do you expect?</span>
    </div>
    <div class="player-confidence-options" aria-label="Expected outcome">
      ${PLAYER_EXPECTATION_OPTIONS.map(([value, label]) => `<button type="button" data-expectation-value="${value}">${label}</button>`).join('')}
    </div>
    <button class="player-bet-menu-track player-bet-menu-cancel" type="button" data-menu-action="cancel-track">Cancel</button>
  `;
  menu.querySelector('[data-menu-action="cancel-track"]')?.addEventListener('click', () => {
    if (activeBetContextMenuPlayer === player) activeBetContextMenuPlayer = null;
    menu.remove();
  }, { once: true });
}

function initPlayerBetContextMenu() {
  document.addEventListener('contextmenu', (e) => {
    if (isTextEntryTarget(e.target)) return;
    e.preventDefault();
    if (isTooltipLongPressTarget(e.target)) {
      activeBetContextMenuPlayer = null;
      document.getElementById('playerBetMenu')?.remove();
      return;
    }
    const player = betContextTargetPlayer(e.target);
    if (!player) {
      activeBetContextMenuPlayer = null;
      document.getElementById('playerBetMenu')?.remove();
      return;
    }
    openBetContextMenu(player, e.clientX, e.clientY);
  });
  document.addEventListener('pointerdown', (e) => {
    const target = e.target instanceof Element ? e.target : null;
    if (!target?.closest?.('#playerBetMenu')) {
      activeBetContextMenuPlayer = null;
      document.getElementById('playerBetMenu')?.remove();
    }
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      activeBetContextMenuPlayer = null;
      document.getElementById('playerBetMenu')?.remove();
    }
  });
}

function isTooltipLongPressTarget(target) {
  if (!(target instanceof Element)) return false;
  const smallOrTouch = Boolean(
    window.matchMedia?.('(hover: none), (pointer: coarse), (max-width: 760px)')?.matches
    || window.innerWidth <= 760
  );
  if (!smallOrTouch) return false;
  return Boolean(target.closest('[data-theme-tooltip-title], [data-theme-tooltip-html], [title], .has-split-tooltip'));
}

function parseTrackedBet(desc) {
  const text = cleanSummary(desc);
  const teamWinMatch = text.match(/^(.*?)\s+(?:to\s+win|wins?|moneyline|ml)$/i);
  if (teamWinMatch) {
    const teamName = cleanSummary(teamWinMatch[1]);
    if (teamName) {
      return {
        type: 'teamWin',
        propType: 'teamWin',
        target: 1,
        teamAbbrev: teamName,
        teamNameKey: normalizeNameKey(teamName),
        raw: text,
      };
    }
  }
  const patterns = [
    { type: 'hit', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:for\s+a\s+|to\s+record\s+a\s+)?hits?$/i },
    { type: 'double', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:(?:for|to\s+record)\s+)?(?:2b|doubles?)$/i },
    { type: 'triple', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:(?:for|to\s+record)\s+)?(?:3b|triples?)$/i },
    { type: 'hr', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:for\s+a\s+)?(?:home\s+runs?|hrs?)$/i },
    { type: 'run', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:(?:for|to\s+record)\s+)?(?:r|rs|runs?)$/i },
    { type: 'tb', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:(?:for|to\s+record)\s+)?(?:tbs?|total\s+bases?)$/i },
    { type: 'xbh', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:for\s+an?\s+)?(?:xbh|extra\s+base\s+hits?)$/i },
    { type: 'rbi', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:(?:for|to\s+record)\s+)?rbis?$/i },
    { type: 'k', regex: /^(.*?)\s+(?:(\d+)\+\s+)?(?:(?:for|to\s+record)\s+)?(?:ks?|strikeouts?)$/i },
    { type: 'double', regex: /^(.*?)\s+(?:for|to\s+record)\s+(\d+)\+\s+(?:2b|doubles?)$/i },
    { type: 'triple', regex: /^(.*?)\s+(?:for|to\s+record)\s+(\d+)\+\s+(?:3b|triples?)$/i },
    { type: 'run', regex: /^(.*?)\s+(?:for|to\s+record)\s+(\d+)\+\s+(?:r|rs|runs?)$/i },
    { type: 'tb', regex: /^(.*?)\s+(?:for|to\s+record)\s+(\d+)\+\s+(?:tbs?|total\s+bases?)$/i },
    { type: 'rbi', regex: /^(.*?)\s+(?:for|to\s+record)\s+(\d+)\+\s+rbis?$/i },
    { type: 'k', regex: /^(.*?)\s+(?:for|to\s+record)\s+(\d+)\+\s+(?:ks?|strikeouts?)$/i },
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern.regex);
    if (!match) continue;
    const playerName = cleanSummary(match[1]);
    if (!playerName) continue;
    return {
      type: pattern.type,
      propType: pattern.type,
      target: normalizeBetTarget(match[2] || 1),
      playerName,
      playerNameKey: normalizeNameKey(playerName),
      raw: text,
    };
  }
  return null;
}

function gameStatusIsFinal(game) {
  return isCompletedGameCard(game);
}

function trackedBetCandidate(game, tracked) {
  if (!game || (!tracked?.playerNameKey && !tracked?.playerId)) return null;
  const awayCurrentPitcherId = Number(game?.pitching?.away?.current?.id) || null;
  const homeCurrentPitcherId = Number(game?.pitching?.home?.current?.id) || null;
  for (const profile of Object.values(game.playerLookup || {})) {
    const propKind = betPropDefinition(tracked?.type).statKind;
    const profileCanPitch = String(profile?.position || '').toUpperCase() === 'P';
    const profileIsPitcherOnly = lineupEntryIsPitcherOnly(profile);
    if (profileIsPitcherOnly && propKind === 'batting') continue;
    if (!profileCanPitch && propKind === 'pitching') continue;
    const idMatches = Number.isFinite(Number(tracked.playerId)) && Number(profile?.id) === Number(tracked.playerId);
    const nameMatches = tracked?.playerNameKey && profile?.fullNameKey === tracked.playerNameKey;
    if (idMatches || nameMatches) {
      const teamAbbrev = profile.teamAbbrev;
      return {
        gamePk: game.gamePk,
        playerId: profile.id,
        fullName: profile.fullName,
        teamAbbrev,
        teamColor: profile.teamColor || (sameTeamAbbrev(teamAbbrev, game.away) ? game.awayColor : game.homeColor),
        batting: profile.gameBatting || { hr: 0, doubles: 0, triples: 0, runs: 0, rbi: 0, hits: 0, atBats: 0, bb: 0, so: 0, sb: 0, cs: 0 },
        pitching: profile.gamePitching || { ip: '0.0', so: 0, bb: 0 },
        isPitcher: propKind === 'pitching' || profileIsPitcherOnly,
        activeBatterId: game.activeBatterId,
        activePitcherId: sameTeamAbbrev(teamAbbrev, game.away) ? awayCurrentPitcherId : homeCurrentPitcherId,
        final: gameStatusIsFinal(game),
      };
    }
  }
  const sides = [
    { code: game.away, lineup: game.lineup?.away || [] },
    { code: game.home, lineup: game.lineup?.home || [] },
  ];
  for (const side of sides) {
    for (const entry of side.lineup) {
      const propKind = betPropDefinition(tracked?.type).statKind;
      const entryCanPitch = String(entry?.position || '').toUpperCase() === 'P';
      const entryIsPitcherOnly = lineupEntryIsPitcherOnly(entry);
      if (entryIsPitcherOnly && propKind === 'batting') continue;
      if (!entryCanPitch && propKind === 'pitching') continue;
      const idMatches = Number.isFinite(Number(tracked.playerId)) && Number(entry?.id) === Number(tracked.playerId);
      const nameMatches = tracked?.playerNameKey && normalizeNameKey(entry?.fullName || entry?.name || '') === tracked.playerNameKey;
      if (!idMatches && !nameMatches) continue;
      return {
        gamePk: game.gamePk,
        playerId: entry.id,
        fullName: entry.fullName || entry.name,
        teamAbbrev: side.code,
        teamColor: sameTeamAbbrev(side.code, game.away) ? game.awayColor : game.homeColor,
        batting: { hits: 0, doubles: 0, triples: 0, runs: 0, rbi: 0, tb: 0 },
        pitching: { so: 0 },
        isPitcher: propKind === 'pitching' || entryIsPitcherOnly,
        activeBatterId: game.activeBatterId,
        activePitcherId: sameTeamAbbrev(side.code, game.away) ? awayCurrentPitcherId : homeCurrentPitcherId,
        final: gameStatusIsFinal(game),
      };
    }
  }
  return null;
}

function normalizedBetLegs(bet) {
  if (Array.isArray(bet?.legs) && bet.legs.length) {
    return bet.legs.map((leg) => ({
      ...(isGamePickLeg(leg) ? {
        gamePk: leg.gamePk,
        side: normalizeGamePickSide(leg.side || (String(leg.teamAbbrev) === String(leg.away) ? 'away' : 'home')),
        teamAbbrev: leg.teamAbbrev || '',
        opponentAbbrev: leg.opponentAbbrev || '',
        teamLogo: leg.teamLogo || '',
        teamColor: leg.teamColor || '',
      } : {
        playerId: Number(leg.playerId),
        playerName: leg.playerName || 'Unknown',
        playerNameKey: leg.playerNameKey || normalizeNameKey(leg.playerName || ''),
      }),
      type: leg.propType || leg.type || 'hit',
      propType: leg.propType || leg.type || 'hit',
      target: normalizeBetTarget(leg.target || leg.count || 1),
    }));
  }
  const text = cleanSummary(bet?.desc || '');
  const segments = text.split(/\s*(?:\+|;|\/)\s*/).map((segment) => cleanSummary(segment)).filter(Boolean);
  if (segments.length > 1) {
    const parsed = segments.map((segment) => parseTrackedBet(segment)).filter(Boolean);
    if (parsed.length === segments.length) return parsed.map((tracked) => ({ ...tracked, propType: tracked.type }));
  }
  const tracked = parseTrackedBet(text);
  return tracked ? [{ ...tracked, propType: tracked.type }] : [];
}

function resolveTrackedLeg(leg, games = latestRenderedGames) {
  if (isGamePickLeg(leg)) {
    const teamKey = normalizeNameKey(leg?.teamAbbrev || leg?.teamName || '');
    const opponentKey = normalizeNameKey(leg?.opponentAbbrev || '');
    const gameHasTeam = (game, keyOrAbbrev) => {
      const key = normalizeNameKey(keyOrAbbrev || '');
      if (!game || !key) return false;
      return [game.away, game.home].some((abbrev) => (
        sameTeamAbbrev(abbrev, keyOrAbbrev)
        || normalizeNameKey(abbrev) === key
        || normalizeNameKey(displayTeamAbbrev(abbrev)) === key
      ));
    };
    const candidateGame = (games || []).find((game) => String(game?.gamePk) === String(leg?.gamePk))
      || (games || []).find((game) => (
        gameHasTeam(game, leg?.teamAbbrev || leg?.teamName || teamKey)
        && (!opponentKey || gameHasTeam(game, leg?.opponentAbbrev || opponentKey))
      ))
      || null;
    if (!candidateGame) return { leg, status: 'unmatched', label: 'SEARCH', active: false, candidate: null, target: 1, currentValue: 0 };
    const awayMatches = gameHasTeam({ away: candidateGame.away, home: '' }, leg?.teamAbbrev || leg?.teamName || teamKey);
    const pickedSide = normalizeGamePickSide(leg?.side || (awayMatches ? 'away' : 'home'));
    const teamAbbrev = pickedSide === 'home' ? candidateGame.home : candidateGame.away;
    const opponentAbbrev = pickedSide === 'home' ? candidateGame.away : candidateGame.home;
    const teamLogo = pickedSide === 'home' ? candidateGame.homeLogo : candidateGame.awayLogo;
    const teamColor = pickedSide === 'home' ? candidateGame.homeColor : candidateGame.awayColor;
    const scoreState = scoreStateForGame(candidateGame);
    const final = gameStatusIsFinal(candidateGame);
    let status = 'pending';
    let label = 'TIED';
    if (scoreState.scoreKnown && scoreState.leaderSide) {
      if (final) {
        status = scoreState.leaderSide === pickedSide ? 'hit' : 'miss';
        label = status === 'hit' ? 'WIN' : 'LOSS';
      } else {
        status = scoreState.leaderSide === pickedSide ? 'leading' : 'trailing';
        label = status === 'leading' ? 'AHEAD' : 'BEHIND';
      }
    } else if (!final && candidateGame?.status?.includes('Not Started')) {
      label = 'PREGAME';
    } else if (final) {
      label = 'FINAL';
    }
    return {
      leg: { ...leg, side: pickedSide, teamAbbrev, opponentAbbrev, teamLogo, teamColor },
      candidate: {
        gamePk: candidateGame.gamePk,
        teamAbbrev,
        opponentAbbrev,
        teamLogo,
        teamColor,
        pickedSide,
        final,
      },
      status,
      label,
      active: false,
      activeRole: 'team',
      currentValue: status === 'hit' ? 1 : 0,
      target: 1,
    };
  }
  const candidates = (games || []).map((game) => trackedBetCandidate(game, leg)).filter(Boolean);
  const candidate = candidates[0] || null;
  if (!candidate) return { leg, status: 'unmatched', label: 'SEARCH', active: false, candidate: null };
  const target = normalizeBetTarget(leg.target);
  const currentValue = betLegStatValue(candidate, leg);
  const active = betLegActive(candidate, leg);
  const activeRole = leg.type === 'k' && candidate?.isPitcher ? 'pitcher' : 'batter';
  if (currentValue >= target) return { leg, candidate, status: 'hit', label: 'HIT', active, activeRole, currentValue, target };
  if (candidate.final) return { leg, candidate, status: 'miss', label: 'MISS', active: false, activeRole, currentValue, target };
  return { leg, candidate, status: 'pending', label: `${currentValue}/${target}`, active, activeRole, currentValue, target };
}

function resolveTrackedBet(bet, games = latestRenderedGames) {
  const legs = normalizedBetLegs(bet);
  if (!legs.length) return { tracked: null, status: 'manual', label: 'MANUAL', active: false, legs: [] };
  const resolvedLegs = legs.map((leg) => resolveTrackedLeg(leg, games));
  const allHit = resolvedLegs.every((leg) => leg.status === 'hit');
  const anyMiss = resolvedLegs.some((leg) => leg.status === 'miss');
  const anyPending = resolvedLegs.some((leg) => ['pending', 'leading', 'trailing'].includes(leg.status));
  const anyActive = resolvedLegs.some((leg) => leg.active);
  const anyUnmatched = resolvedLegs.some((leg) => leg.status === 'unmatched');
  const status = allHit ? 'hit' : anyMiss ? 'miss' : anyPending ? 'pending' : anyUnmatched ? 'unmatched' : 'manual';
  const hitCount = resolvedLegs.filter((leg) => leg.status === 'hit').length;
  const label = legs.length > 1
    ? (allHit ? 'PARLAY HIT' : anyMiss ? 'PARLAY MISS' : `${hitCount}/${legs.length}`)
    : (resolvedLegs[0]?.label || 'MANUAL');
  return {
    tracked: legs,
    candidate: resolvedLegs.find((leg) => leg.candidate)?.candidate || null,
    status,
    label,
    active: anyActive,
    legs: resolvedLegs,
  };
}

function trackedBetMap(games = latestRenderedGames) {
  const map = new Map();
  for (const bet of getBets()) {
    const resolved = resolveTrackedBet(bet, games);
    for (const leg of resolved.legs || []) {
      if (!leg.active || !leg?.candidate?.gamePk || !leg?.candidate?.playerId) continue;
      if (!map.has(String(leg.candidate.gamePk))) map.set(String(leg.candidate.gamePk), new Set());
      map.get(String(leg.candidate.gamePk)).add(String(leg.candidate.playerId));
    }
  }
  return map;
}

function trackedBetHighlightMap(games = latestRenderedGames) {
  const map = new Map();
  for (const bet of getBets()) {
    const resolved = resolveTrackedBet(bet, games);
    for (const leg of resolved.legs || []) {
      if (leg.activeRole !== 'batter') continue;
      if (!leg.active || !leg?.candidate?.gamePk || !leg?.candidate?.playerId) continue;
      const teamColor = leg.candidate.teamColor;
      if (!teamColor) continue;
      map.set(String(leg.candidate.gamePk), {
        playerId: String(leg.candidate.playerId),
        teamColor,
      });
    }
  }
  return map;
}

function trackedGamePickStateMap(games = latestRenderedGames) {
  const map = new Map();
  for (const bet of getBets()) {
    const resolved = resolveTrackedBet(bet, games);
    for (const leg of resolved.legs || []) {
      if (!isGamePickLeg(leg?.leg) || !leg?.candidate?.gamePk) continue;
      const gamePk = String(leg.candidate.gamePk);
      const side = normalizeGamePickSide(leg?.leg?.side || leg?.candidate?.pickedSide);
      if (!side) continue;
      if (!map.has(gamePk)) map.set(gamePk, { away: '', home: '' });
      const entry = map.get(gamePk);
      entry[side] = leg.status;
    }
  }
  return map;
}

function trackedPlayersStorageKey(date = dateInput.value || formatDate(new Date())) {
  return `${PLAYER_TRACKER_STORAGE_KEY}:${date || formatDate(new Date())}`;
}

function normalizePlayerConfidence(value) {
  const n = Math.round(Number(value));
  return Number.isFinite(n) ? clamp(n, 1, 5) : 3;
}

const PLAYER_EXPECTATION_OPTIONS = [
  ['H', 'H'],
  ['XBH', 'XBH'],
  ['HR', 'HR'],
  ['2+TB', '2+TB'],
];

function normalizePlayerExpectation(value) {
  const text = String(value || '').trim().toUpperCase().replace(/\s+/g, '');
  if (text === '2TB' || text === '2+TB' || text === 'TB2+') return '2+TB';
  if (['H', 'XBH', 'HR'].includes(text)) return text;
  return 'H';
}

function normalizeTrackedPlayerEntries(players = []) {
  const deduped = [];
  const seen = new Set();
  for (const entry of listify(players)) {
    const playerId = Number(entry?.playerId ?? entry?.id);
    if (!Number.isFinite(playerId) || seen.has(String(playerId))) continue;
    seen.add(String(playerId));
    deduped.push({
      playerId,
      playerName: entry?.playerName || entry?.fullName || entry?.name || 'Unknown',
      teamAbbrev: entry?.teamAbbrev || '',
      position: entry?.position || '',
      addedAt: Number(entry?.addedAt) || Date.now() + deduped.length,
      expectation: normalizePlayerExpectation(entry?.expectation || entry?.expected || ''),
    });
  }
  return deduped;
}

function readTrackedPlayersStore(date = dateInput.value || formatDate(new Date())) {
  try {
    const raw = localStorage.getItem(trackedPlayersStorageKey(date));
    if (raw == null) return null;
    return normalizeTrackedPlayerEntries(JSON.parse(raw || '[]'));
  } catch {
    return null;
  }
}

function readTrackedPlayersBackup(date = dateInput.value || formatDate(new Date())) {
  try {
    const parsed = JSON.parse(localStorage.getItem(PLAYER_TRACKER_BACKUP_STORAGE_KEY) || '{}');
    return normalizeTrackedPlayerEntries(parsed?.[date] || []);
  } catch {
    return [];
  }
}

function writeTrackedPlayersBackup(players = [], date = dateInput.value || formatDate(new Date())) {
  try {
    const parsed = JSON.parse(localStorage.getItem(PLAYER_TRACKER_BACKUP_STORAGE_KEY) || '{}');
    localStorage.setItem(PLAYER_TRACKER_BACKUP_STORAGE_KEY, JSON.stringify({ ...(parsed || {}), [date]: normalizeTrackedPlayerEntries(players) }));
  } catch {}
}

function getTrackedPlayers(date = dateInput.value || formatDate(new Date())) {
  const key = trackedPlayersStorageKey(date);
  if (trackedPlayersMemoryByDate.has(key)) {
    return trackedPlayersMemoryByDate.get(key) || [];
  }
  const restoreFromBackup = () => {
    const candidates = [
      normalizeTrackedPlayerEntries(readManualStateBackup(date).trackedPlayers || []),
      normalizeTrackedPlayerEntries(readManualStateMirror(date).trackedPlayers || []),
      normalizeTrackedPlayerEntries(readManualStateDurable(date).trackedPlayers || []),
      readTrackedPlayersBackup(date),
    ];
    try {
      candidates.push(normalizeTrackedPlayerEntries(JSON.parse(sessionStorage.getItem(manualStateBackupKey(date)) || '{}')?.trackedPlayers || []));
    } catch {}
    const durableBackup = candidates
      .filter((items) => items.length)
      .map((items) => manualStateCandidate(items, 0, 'tracked-backup'))
      .sort(compareManualStateCandidates)[0]?.value || [];
    if (durableBackup.length) {
      trackedPlayersMemoryByDate.set(key, durableBackup);
      try {
        localStorage.setItem(key, JSON.stringify(durableBackup));
      } catch {}
      return durableBackup;
    }
    return trackedPlayersMemoryByDate.get(key) || [];
  };
  try {
    const rawTracked = localStorage.getItem(key);
    const parsed = JSON.parse(rawTracked || '[]');
    if (Array.isArray(parsed)) {
      const filtered = normalizeTrackedPlayerEntries(parsed);
      if (!filtered.length && rawTracked != null) {
        const backupUpdatedAt = trackedPlayersBackupUpdatedAt(date);
        const directUpdatedAt = syncMetaUpdatedAt(key);
        if (backupUpdatedAt > directUpdatedAt) {
          const restored = restoreFromBackup();
          if (restored.length) return restored;
        }
        trackedPlayersMemoryByDate.set(key, []);
        writeManualStateBackupPatch({ trackedPlayers: [] }, date, { allowEmpty: true, forceEmpty: true });
        return [];
      }
      if (!filtered.length) return restoreFromBackup();
      const mirrorState = readManualStateMirror(date);
      const backupState = readManualStateBackup(date);
      const durableState = readManualStateDurable(date);
      const best = [
        { items: filtered, updatedAt: Date.now() },
        { items: normalizeTrackedPlayerEntries(mirrorState.trackedPlayers || []), updatedAt: Number(mirrorState.updatedAt) || 0 },
        { items: normalizeTrackedPlayerEntries(backupState.trackedPlayers || []), updatedAt: Number(backupState.updatedAt) || 0 },
        { items: normalizeTrackedPlayerEntries(durableState.trackedPlayers || []), updatedAt: Number(durableState.updatedAt) || 0 },
      ]
        .filter((candidate) => candidate.items.length)
        .map((candidate) => manualStateCandidate(candidate.items, candidate.updatedAt, 'tracked-store'))
        .sort(compareTrackedPlayerStateCandidates)[0]?.value || filtered;
      trackedPlayersMemoryByDate.set(key, best);
      if (best !== filtered) {
        try { localStorage.setItem(key, JSON.stringify(best)); } catch {}
      }
      writeManualStateBackupPatch({ trackedPlayers: best }, date);
      return best;
    }
  } catch {
    return restoreFromBackup();
  }
  return restoreFromBackup();
}

function saveTrackedPlayers(players = [], date = dateInput.value || formatDate(new Date()), options = {}) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const key = trackedPlayersStorageKey(selectedDate);
  let deduped = normalizeTrackedPlayerEntries(players);
  if (!deduped.length && !options.allowEmpty) {
    const backup = normalizeTrackedPlayerEntries(readManualStateBackup(selectedDate).trackedPlayers || []);
    if (backup.length) deduped = backup;
  }
  trackedPlayersMemoryByDate.set(key, deduped);
  try {
    localStorage.setItem(key, JSON.stringify(deduped));
  } catch {}
  manualStateInMemoryDate = selectedDate;
  if (deduped.length || options.allowEmpty) {
    writeManualStateBackupPatch({ trackedPlayers: deduped }, selectedDate, { allowEmpty: options.allowEmpty, forceEmpty: options.forceEmpty });
    if (deduped.length || options.forceEmpty) writeTrackedPlayersBackup(deduped, selectedDate);
  }
  if (playerTrackerListEl) playerTrackerListEl.dataset.renderFingerprint = '';
  refreshLineupTrackedPlayerHighlights();
  window.setTimeout(() => {
    window.OwenToolsSync?.flushUploads?.();
  }, 80);
}

function persistManualStateSnapshot(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = String(date || dateInput.value || formatDate(new Date()));
  const trackedKey = trackedPlayersStorageKey(selectedDate);
  const picks = normalizePendingGamePickEntries([...pendingGamePickSelections.entries()]);
  const tracked = trackedPlayersMemoryByDate.has(trackedKey)
    ? normalizeTrackedPlayerEntries(trackedPlayersMemoryByDate.get(trackedKey) || [])
    : normalizeTrackedPlayerEntries(getTrackedPlayers(selectedDate));
  const patch = {};
  patch.pendingGamePicks = picks;
  patch.tossupScoreboards = [...tossupScoreboardGamePks];
  patch.lockedTossupScoreboards = [...lockedTossupScoreboardGamePks];
  patch.overUnderScoreboards = serializeOverUnderScoreboards();
  if (tracked.length || trackedPlayersMemoryByDate.has(trackedKey)) patch.trackedPlayers = tracked;
  writeManualStateBackupPatch(patch, selectedDate, {
    allowEmpty: true,
    forceEmpty: trackedPlayersMemoryByDate.has(trackedKey) && !tracked.length,
  });
}

function moveTrackedPlayer(playerId, beforePlayerId = '') {
  const movingId = String(playerId || '');
  const beforeId = String(beforePlayerId || '');
  if (!movingId || movingId === beforeId) return false;
  const tracked = [...getTrackedPlayers()];
  const fromIndex = tracked.findIndex((entry) => String(entry.playerId) === movingId);
  if (fromIndex < 0) return false;
  const [moving] = tracked.splice(fromIndex, 1);
  const toIndex = beforeId
    ? tracked.findIndex((entry) => String(entry.playerId) === beforeId)
    : tracked.length;
  tracked.splice(toIndex >= 0 ? toIndex : tracked.length, 0, moving);
  saveTrackedPlayers(tracked);
  renderPlayerTrackerList(latestRenderedGames);
  return true;
}

function setBetPanelMode(mode = 'bets') {
  betPanelMode = mode === 'input' ? 'input' : mode === 'bets' ? 'bets' : 'players';
  betLogTabBtnEl?.classList.toggle('is-active', betPanelMode === 'bets');
  betInputTabBtnEl?.classList.toggle('is-active', betPanelMode === 'input');
  playerTrackerTabBtnEl?.classList.toggle('is-active', betPanelMode === 'players');
  if (betListEl) {
    betListEl.hidden = betPanelMode !== 'bets';
    betListEl.style.display = betPanelMode === 'bets' ? '' : 'none';
  }
  if (playerTrackerListEl) {
    playerTrackerListEl.hidden = betPanelMode !== 'players';
    playerTrackerListEl.style.display = betPanelMode === 'players' ? '' : 'none';
  }
  if (betInputPanelEl) {
    betInputPanelEl.hidden = betPanelMode !== 'input';
    betInputPanelEl.style.display = betPanelMode === 'input' ? '' : 'none';
  }
  const dayLabelWrap = betDayLabelEl?.closest?.('.hint');
  if (dayLabelWrap) dayLabelWrap.hidden = betPanelMode === 'players';
  if (playerTrackerSortBtnEl) {
    playerTrackerSortBtnEl.hidden = betPanelMode !== 'players';
    playerTrackerSortBtnEl.textContent = currentPlayerTrackerSortLabel();
  }
  if (playerTrackerCountsEl) {
    playerTrackerCountsEl.hidden = betPanelMode !== 'players';
  }
  if (clearBetsBtn) {
    clearBetsBtn.hidden = false;
    clearBetsBtn.style.visibility = betPanelMode === 'input' ? 'hidden' : 'visible';
    clearBetsBtn.textContent = betPanelMode === 'players' ? 'CLEAR TRACKED' : 'CLEAR';
  }
}

function resolveTrackedPlayerProfile(entry, games = latestRenderedGames) {
  const playerId = Number(entry?.playerId);
  if (!Number.isFinite(playerId)) return { profile: null, game: null };
  const findLineupEntry = (game) => {
    for (const side of ['away', 'home']) {
      const lineupEntry = listify(game?.lineup?.[side]).find((player) => Number(player?.id ?? player?.playerId) === playerId);
      if (lineupEntry) return { side, lineupEntry };
    }
    return { side: '', lineupEntry: null };
  };
  const hasTrackedPlayer = (candidate) => {
    if (!candidate) return false;
    if (candidate?.playerLookup?.[String(playerId)]) return true;
    return Boolean(findLineupEntry(candidate).lineupEntry);
  };
  const hydrateProfileFromLineup = (gameCard) => {
    if (!gameCard) return null;
    const { side, lineupEntry } = findLineupEntry(gameCard);
    if (!lineupEntry) return null;
    const teamAbbrev = side === 'away' ? gameCard.away : side === 'home' ? gameCard.home : entry?.teamAbbrev || '';
    return {
      id: playerId,
      fullName: lineupEntry.fullName || entry?.playerName || lineupEntry.name || 'Unknown',
      teamAbbrev,
      teamColor: side === 'away' ? gameCard.awayColor : side === 'home' ? gameCard.homeColor : getTeamColor(teamAbbrev),
      teamLogo: side === 'away' ? gameCard.awayLogo : side === 'home' ? gameCard.homeLogo : getLogoPath(teamAbbrev),
      position: lineupEntry.position || entry?.position || '',
      todayBatting: lineupEntry.today || '0-0',
      todayPitching: lineupEntry.todayPitching || '',
      gameBatting: lineupEntry.gameBatting || {},
      batting: lineupEntry.batting || {},
    };
  };
  const game = (games || []).find(hasTrackedPlayer)
    || getCachedGames().find(hasTrackedPlayer)
    || null;
  const lookupProfile = game?.playerLookup?.[String(playerId)] || null;
  const lineupProfile = hydrateProfileFromLineup(game);
  const profile = lookupProfile
    ? {
      ...lookupProfile,
      todayBatting: lineupProfile?.todayBatting || lookupProfile.todayBatting || '',
      todayPitching: lineupProfile?.todayPitching || lookupProfile.todayPitching || '',
      gameBatting: lineupProfile?.gameBatting || lookupProfile.gameBatting || {},
      batting: lineupProfile?.batting || lookupProfile.batting || {},
      teamColor: lookupProfile.teamColor || lineupProfile?.teamColor,
      teamLogo: lookupProfile.teamLogo || lineupProfile?.teamLogo,
    }
    : lineupProfile;
  return { profile, game };
}

function trackedPlayerTodayLine(profile) {
  if (!profile) return 'No game data loaded';
  const batting = cleanSummary(profile.todayBatting || '');
  const pitching = cleanSummary(profile.todayPitching || '');
  const position = String(profile.position || '').toUpperCase();
  if (position === 'P' && pitching && pitching !== 'Unused today') return pitching;
  if (batting && batting !== '0-0') return batting;
  if (pitching && pitching !== 'Unused today') return pitching;
  return batting || pitching || '0-0';
}

function trackedPlayerSideForGame(entry, profile, game) {
  if (!game) return '';
  const teamCode = canonicalTeamAbbrev(profile?.teamAbbrev || entry?.teamAbbrev || '');
  if (teamCode && sameTeamAbbrev(teamCode, game.away)) return 'away';
  if (teamCode && sameTeamAbbrev(teamCode, game.home)) return 'home';
  const playerId = Number(entry?.playerId ?? profile?.id);
  if (!Number.isFinite(playerId) || playerId <= 0) return '';
  const inLineup = (lineup = []) => listify(lineup).some((player) => Number(player?.id ?? player?.playerId) === playerId);
  if (inLineup(game?.lineup?.away)) return 'away';
  if (inLineup(game?.lineup?.home)) return 'home';
  return '';
}

function trackedPlayerLineupForSide(game, side) {
  if (!game || (side !== 'away' && side !== 'home')) return [];
  const lineup = Array.isArray(game?.lineup?.[side]) ? game.lineup[side] : [];
  return normalizeLineupCollectionForSide(game, side, lineup);
}

function trackedPlayerLineupIndex(lineup = [], playerId) {
  const id = Number(playerId);
  if (!Number.isFinite(id) || id <= 0) return -1;
  return listify(lineup).findIndex((entry) => Number(entry?.id ?? entry?.playerId) === id);
}

function trackedPlayerInningStatus(entry, profile, game) {
  const empty = { side: '', lineupEntry: null, isLive: false, isDueThisInning: false, statusText: '' };
  if (!game || !gameHasLiveProgress(game) || isCompletedGameCard(game)) return empty;
  const side = trackedPlayerSideForGame(entry, profile, game);
  const battingSide = game?.battingSide === 'away' || game?.battingSide === 'home' ? game.battingSide : '';
  if (!side || side !== battingSide) return { ...empty, side };
  const outs = Number(game?.outs ?? game?.activePlay?.count?.outs ?? 0);
  if (Number.isFinite(outs) && outs >= 3) return { ...empty, side };
  const playerId = Number(entry?.playerId ?? profile?.id);
  const activeBatterId = Number(game?.activeBatterId || game?.activePlay?.matchup?.batter?.id || 0);
  const lineup = trackedPlayerLineupForSide(game, side);
  const playerIndex = trackedPlayerLineupIndex(lineup, playerId);
  const lineupEntry = playerIndex >= 0 ? lineup[playerIndex] : null;
  const isLive = Number.isFinite(activeBatterId) && activeBatterId > 0 && activeBatterId === playerId;
  const anchorId = Number.isFinite(activeBatterId) && activeBatterId > 0
    ? activeBatterId
    : liveLineupNextBatterIdForSide(game, side, lineup);
  const anchorIndex = trackedPlayerLineupIndex(lineup, anchorId);
  const isDueByOrder = playerIndex >= 0 && anchorIndex >= 0 && playerIndex >= anchorIndex;
  const isDueThisInning = Boolean(isLive || isDueByOrder || lineupEntry?.isActive || lineupEntry?.isNextUp);
  return {
    side,
    lineupEntry,
    isLive,
    isDueThisInning,
    statusText: isLive ? 'UP NOW' : isDueThisInning ? 'DUE THIS INNING' : '',
  };
}

function trackedPlayerGameBattingStats(profile, lineupEntry = null) {
  const source = lineupEntry?.gameBatting || profile?.gameBatting || {};
  const stats = lineupGameBattingStats({ gameBatting: source });
  if (lineupGameStatsHasAction(stats) || statNumber(stats.totalBases) > 0) return stats;
  const text = cleanSummary(profile?.todayBatting || lineupEntry?.today || '');
  const hitMatch = text.match(/\b(\d+)-(\d+)\b/);
  const hrMatch = text.match(/\b(\d+)\s*HR\b/i) || text.match(/\bHR\s*(\d+)\b/i);
  const doublesMatch = text.match(/\b(\d+)\s*2B\b/i) || text.match(/\b2B\s*(\d+)\b/i);
  const triplesMatch = text.match(/\b(\d+)\s*3B\b/i) || text.match(/\b3B\s*(\d+)\b/i);
  const xbhMatch = text.match(/\b(\d+)\s*XBH\b/i) || text.match(/\bXBH\s*(\d+)\b/i);
  const hits = hitMatch ? statNumber(hitMatch[1]) : 0;
  const atBats = hitMatch ? statNumber(hitMatch[2]) : 0;
  const homeRuns = hrMatch ? statNumber(hrMatch[1]) : 0;
  const doubles = doublesMatch ? statNumber(doublesMatch[1]) : 0;
  const triples = triplesMatch ? statNumber(triplesMatch[1]) : 0;
  const extraBaseHits = xbhMatch ? statNumber(xbhMatch[1]) : doubles + triples + homeRuns;
  const singles = Math.max(0, hits - doubles - triples - homeRuns);
  return {
    atBats,
    hits,
    doubles: Math.max(doubles, extraBaseHits - triples - homeRuns),
    triples,
    homeRuns,
    runs: 0,
    rbi: 0,
    walks: /\bBB\b/i.test(text) ? 1 : 0,
    strikeOuts: /\bK\b/i.test(text) ? 1 : 0,
    totalBases: singles + (Math.max(doubles, extraBaseHits - triples - homeRuns) * 2) + (triples * 3) + (homeRuns * 4),
  };
}

function trackedPlayerExpectationHit(profile, lineupEntry = null, expectation = 'H') {
  const stats = trackedPlayerGameBattingStats(profile, lineupEntry);
  const value = normalizePlayerExpectation(expectation);
  if (value === 'HR') return statNumber(stats.homeRuns) > 0;
  if (value === 'XBH') return statNumber(stats.doubles) + statNumber(stats.triples) + statNumber(stats.homeRuns) > 0;
  if (value === '2+TB') return statNumber(stats.totalBases) >= 2;
  return statNumber(stats.hits) > 0;
}

function playerTrackerSummaryHtml(counts) {
  return `
    <span class="player-tracker-count" title="Tracked players" aria-label="Tracked players: ${counts.tracked}">${counts.tracked}</span>
    <span class="player-tracker-count is-due" title="Tracked players up or coming to bat this inning" aria-label="Tracked players up or coming to bat this inning: ${counts.dueThisInning}">${counts.dueThisInning}</span>
    <span class="player-tracker-count is-live" title="Tracked players live right now" aria-label="Tracked players live right now: ${counts.liveNow}">${counts.liveNow}</span>
  `;
}

function renderPlayerTrackerSummary(counts = { tracked: 0, dueThisInning: 0, liveNow: 0 }) {
  if (!playerTrackerCountsEl) return;
  const renderKey = `${counts.tracked}:${counts.dueThisInning}:${counts.liveNow}:${betPanelMode}`;
  if (playerTrackerCountsEl.dataset.renderKey === renderKey) return;
  playerTrackerCountsEl.dataset.renderKey = renderKey;
  playerTrackerCountsEl.innerHTML = playerTrackerSummaryHtml(counts);
  playerTrackerCountsEl.hidden = betPanelMode !== 'players';
}

function currentPlayerTrackerSortLabel() {
  if (playerTrackerSortMode === 'game') return 'game time';
  if (playerTrackerSortMode === 'tb') return 'TB';
  return 'time added';
}

function nextPlayerTrackerSortMode() {
  if (playerTrackerSortMode === 'added') return 'game';
  if (playerTrackerSortMode === 'game') return 'tb';
  return 'added';
}

function trackedPlayerSortValue(entry, games = latestRenderedGames) {
  const { profile, game } = resolveTrackedPlayerProfile(entry, games);
  if (playerTrackerSortMode === 'game') return gameStartTimeMs(game) ?? Number.MAX_SAFE_INTEGER;
  if (playerTrackerSortMode === 'tb') return statNumber(profile?.gameBatting?.tb ?? profile?.gameBatting?.totalBases);
  return Number(entry?.addedAt) || 0;
}

function sortTrackedPlayersForDisplay(tracked = [], games = latestRenderedGames) {
  return tracked.map((entry, index) => ({ entry, index })).sort((a, b) => {
    if (playerTrackerSortMode === 'tb') {
      return trackedPlayerSortValue(b.entry, games) - trackedPlayerSortValue(a.entry, games)
        || a.index - b.index;
    }
    return trackedPlayerSortValue(a.entry, games) - trackedPlayerSortValue(b.entry, games)
      || a.index - b.index;
  }).map(({ entry }) => entry);
}

function trackedPlayerNavEntries(games = latestRenderedGames) {
  return sortTrackedPlayersForDisplay(getTrackedPlayers(), games).map((entry) => {
    const { profile, game } = resolveTrackedPlayerProfile(entry, games);
    return {
      id: Number(entry.playerId),
      game,
      fullName: profile?.fullName || entry.playerName || 'Unknown',
      teamAbbrev: profile?.teamAbbrev || entry.teamAbbrev || '',
      position: profile?.position || entry.position || '',
    };
  }).filter((entry) => Number.isFinite(entry.id) && entry.id > 0);
}

function trackedPlayerNavContext(playerId, games = latestRenderedGames) {
  const entries = trackedPlayerNavEntries(games);
  const current = entries.find((entry) => Number(entry.id) === Number(playerId)) || entries[0] || null;
  if (!current) return null;
  return {
    kind: 'tracked',
    entries,
    playerId: Number(playerId),
    game: current.game || null,
  };
}

function renderPlayerTrackerList(games = latestRenderedGames) {
  if (!playerTrackerListEl) return;
  const tracked = sortTrackedPlayersForDisplay(getTrackedPlayers(), games);
  const rows = tracked.map((entry) => {
    const { profile, game } = resolveTrackedPlayerProfile(entry, games);
    const expectation = normalizePlayerExpectation(entry?.expectation);
    const inningStatus = trackedPlayerInningStatus(entry, profile, game);
    const expectationHit = trackedPlayerExpectationHit(profile, inningStatus.lineupEntry, expectation);
    return { entry, profile, game, expectation, inningStatus, expectationHit };
  });
  const counts = {
    tracked: rows.length,
    dueThisInning: rows.filter((row) => row.inningStatus.isDueThisInning).length,
    liveNow: rows.filter((row) => row.inningStatus.isLive).length,
  };
  if (tracked.length) {
    setBetPanelMode('players');
  }
  if (playerTrackerSortBtnEl) playerTrackerSortBtnEl.textContent = currentPlayerTrackerSortLabel();
  renderPlayerTrackerSummary(counts);
  const fingerprint = JSON.stringify({
    day: dateInput.value,
    sort: playerTrackerSortMode,
    tracked,
    counts,
    stats: rows.map((row) => {
      const stats = trackedPlayerGameBattingStats(row.profile, row.inningStatus.lineupEntry);
      return [
        row.entry.playerId,
        row.profile?.todayBatting || '',
        row.profile?.todayPitching || '',
        row.profile?.teamAbbrev || '',
        row.expectation,
        row.expectationHit ? 1 : 0,
        row.inningStatus.isLive ? 1 : 0,
        row.inningStatus.isDueThisInning ? 1 : 0,
        row.game?.gamePk || '',
        row.game?.activeBatterId || '',
        row.game?.battingSide || '',
        row.game?.outs ?? '',
        stats.hits,
        stats.homeRuns,
        stats.totalBases,
      ].join(':');
    }),
  });
  if (playerTrackerListEl.dataset.renderFingerprint === fingerprint) return;
  const scrollTop = playerTrackerListEl.scrollTop;
  const previousLines = new Map(
    Array.from(playerTrackerListEl.querySelectorAll('.player-track-item[data-player-id]'))
      .map((item) => [String(item.dataset.playerId || ''), item.dataset.todayLine || '']),
  );
  playerTrackerListEl.dataset.renderFingerprint = fingerprint;
  playerTrackerListEl.replaceChildren();
  const fragment = document.createDocumentFragment();
  const updatedItems = [];
  if (!tracked.length) {
    const empty = document.createElement('div');
    empty.className = 'lineup-empty';
    empty.textContent = 'No players tracked yet.';
    fragment.appendChild(empty);
  }
  for (const row of rows) {
    const { entry, profile, game, expectation, inningStatus, expectationHit } = row;
    const playerId = Number(entry.playerId);
    const teamAbbrev = profile?.teamAbbrev || entry.teamAbbrev || '';
    const position = profile?.position || entry.position || '';
    const teamColor = profile?.teamColor || game?.awayColor || game?.homeColor || '#66d9ff';
    const todayLine = trackedPlayerTodayLine(profile);
    const playerName = profile?.fullName || entry.playerName || 'Unknown';
    const expectationOptions = PLAYER_EXPECTATION_OPTIONS
      .map(([value, label]) => `<option value="${value}"${expectation === value ? ' selected' : ''}>${label}</option>`)
      .join('');
    const statusChip = inningStatus.statusText
      ? `<span class="player-track-status">${escapeHtml(inningStatus.statusText)}</span>`
      : '';
    const el = document.createElement('div');
    el.className = [
      'panel-item',
      'player-track-item',
      inningStatus.isDueThisInning ? 'is-tracker-up-inning' : '',
      inningStatus.isLive ? 'is-tracker-live' : '',
      expectationHit ? 'is-expectation-hit' : '',
    ].filter(Boolean).join(' ');
    el.dataset.playerId = String(playerId);
    el.dataset.gamePk = String(game?.gamePk || '');
    el.dataset.todayLine = todayLine;
    el.draggable = true;
    el.style.setProperty('--tracker-team-color', teamColor);
    el.style.setProperty('--tracker-team-rgb', hexToRgb(teamColor));
    el.innerHTML = `
      <button class="player-track-drag" type="button" draggable="true" data-player-track-drag="${playerId}" aria-label="Drag to reorder tracked player">||</button>
      <img class="player-track-face" src="${playerHeadshotUrl(playerId)}" alt="${escapeHtml(playerName)} headshot" />
      <div class="player-track-copy">
        <strong>${escapeHtml(playerName)}</strong>
        <div class="player-track-meta">
          <span>${escapeHtml([displayTeamAbbrev(teamAbbrev), position].filter(Boolean).join(' | '))}</span>
          ${statusChip}
          <label class="player-track-confidence" title="Tracked expectation">
            <span>EXP</span>
            <select class="player-track-expectation" data-tracked-expectation-id="${playerId}" aria-label="Expectation for ${escapeHtml(playerName)}">
              ${expectationOptions}
            </select>
          </label>
        </div>
        <div class="player-track-line">${escapeHtml(todayLine)}</div>
      </div>
      <button class="player-track-remove" type="button" data-tracked-player-id="${playerId}" aria-label="Remove tracked player">X</button>
    `;
    const img = el.querySelector('.player-track-face');
    if (img) {
      img.onerror = () => {
        img.onerror = null;
        img.src = profile?.teamLogo || getLogoPath(teamAbbrev) || 'placeholder.png';
      };
    }
    fragment.appendChild(el);
    if (previousLines.has(String(playerId)) && previousLines.get(String(playerId)) !== todayLine) {
      updatedItems.push([el, teamColor]);
    }
  }
  playerTrackerListEl.appendChild(fragment);
  for (const [item, color] of updatedItems) {
    markPanelItemUpdated(item, color);
  }
  playerTrackerListEl.scrollTop = scrollTop;
}

function refreshLineupTrackedPlayerHighlights() {
  if (!lineupOverlayEl) return;
  const trackedIds = new Set(normalizeTrackedPlayerEntries(getTrackedPlayers()).map((entry) => String(entry.playerId)));
  lineupOverlayEl.querySelectorAll('.lineup-list li[data-player-id]').forEach((row) => {
    row.classList.toggle('lineup-row-tracked', trackedIds.has(String(row.dataset.playerId || '')));
  });
}

function addSelectedPlayerToTracker() {
  let player = resolveBetSearchPlayer(betPlayerSearchEl?.value || '', latestRenderedGames);
  if (!player && maybeSelectSingleBetPlayerOption()) {
    player = resolveBetSearchPlayer(betPlayerSearchEl?.value || '', latestRenderedGames);
  }
  if (!player) return false;
  const key = trackedPlayersStorageKey();
  const tracked = trackedPlayersMemoryByDate.has(key)
    ? [...(trackedPlayersMemoryByDate.get(key) || [])]
    : getTrackedPlayers();
  if (!tracked.some((entry) => String(entry.playerId) === String(player.playerId))) {
    tracked.push({ ...player, expectation: normalizePlayerExpectation(player.expectation) });
  }
  saveTrackedPlayers(tracked);
  if (betPlayerSearchEl) betPlayerSearchEl.value = '';
  refreshBetPlayerOptions();
  setBetPanelMode('players');
  if (playerTrackerListEl) playerTrackerListEl.dataset.renderFingerprint = '';
  renderPlayerTrackerList(latestRenderedGames);
  focusBetPlayerSearch();
  return true;
}

function addPlayerToTracker(player, options = {}) {
  if (!player || !Number.isFinite(Number(player.playerId))) return false;
  const key = trackedPlayersStorageKey();
  const tracked = trackedPlayersMemoryByDate.has(key)
    ? [...(trackedPlayersMemoryByDate.get(key) || [])]
    : getTrackedPlayers();
  const existingIndex = tracked.findIndex((entry) => String(entry.playerId) === String(player.playerId));
  const expectation = normalizePlayerExpectation(options.expectation ?? player.expectation);
  if (existingIndex >= 0) {
    tracked[existingIndex] = { ...tracked[existingIndex], expectation };
  } else {
    tracked.push({ ...player, expectation });
  }
  saveTrackedPlayers(tracked);
  setBetPanelMode('players');
  if (playerTrackerListEl) playerTrackerListEl.dataset.renderFingerprint = '';
  renderPlayerTrackerList(latestRenderedGames);
  return true;
}

window.trackActiveContextPlayer = () => addPlayerToTracker(activeBetContextMenuPlayer);

function applyGamePickLogoState(logoEl, state) {
  if (!logoEl) return;
  logoEl.classList.remove(
    'is-pick-selected',
    'is-game-pick-leading',
    'is-game-pick-trailing',
    'is-game-pick-hit',
    'is-game-pick-miss',
  );
  if (state === 'selected') logoEl.classList.add('is-pick-selected');
  if (state === 'leading') logoEl.classList.add('is-game-pick-leading');
  if (state === 'trailing') logoEl.classList.add('is-game-pick-trailing');
  if (state === 'hit') logoEl.classList.add('is-game-pick-hit');
  if (state === 'miss') logoEl.classList.add('is-game-pick-miss');
}

function applyGamePickSurfaceState(targetEl, state) {
  if (!targetEl) return;
  targetEl.classList.remove(
    'is-pick-selected',
    'is-game-pick-leading',
    'is-game-pick-trailing',
    'is-game-pick-hit',
    'is-game-pick-miss',
  );
  if (state === 'selected') targetEl.classList.add('is-pick-selected');
  if (state === 'leading') targetEl.classList.add('is-game-pick-leading');
  if (state === 'trailing') targetEl.classList.add('is-game-pick-trailing');
  if (state === 'hit') targetEl.classList.add('is-game-pick-hit');
  if (state === 'miss') targetEl.classList.add('is-game-pick-miss');
}

function applyGamePickCardState(card, awayState = '', homeState = '') {
  if (!card) return;
  card.classList.remove(
    'has-game-pick-leading',
    'has-game-pick-trailing',
    'has-game-pick-hit',
    'has-game-pick-miss',
  );
  const states = [awayState, homeState].filter(Boolean);
  if (states.includes('hit')) card.classList.add('has-game-pick-hit');
  else if (states.includes('miss')) card.classList.add('has-game-pick-miss');
  else if (states.includes('leading')) card.classList.add('has-game-pick-leading');
  else if (states.includes('trailing')) card.classList.add('has-game-pick-trailing');
}

function pendingGamePickVisualState(game, side) {
  const pickedSide = normalizeGamePickSide(side);
  if (!game || !pickedSide) return '';
  const scoreState = scoreStateForGame(game);
  if (!scoreState.scoreKnown || !scoreState.leaderSide) return 'selected';
  const final = gameStatusIsFinal(game);
  if (final) return scoreState.leaderSide === pickedSide ? 'hit' : 'miss';
  return scoreState.leaderSide === pickedSide ? 'leading' : 'trailing';
}

function syncCardGamePickState(card, game, gamePickStates = trackedGamePickStateMap(latestRenderedGames)) {
  if (!card || !game?.gamePk) return;
  const pendingSide = pendingGamePickSideForGame(game);
  const tracked = gamePickStates.get(String(game.gamePk)) || { away: '', home: '' };
  const awayState = tracked.away || (pendingSide === 'away' ? pendingGamePickVisualState(game, 'away') : '');
  const homeState = tracked.home || (pendingSide === 'home' ? pendingGamePickVisualState(game, 'home') : '');
  applyGamePickCardState(card, awayState, homeState);
  applyGamePickLogoState(card.querySelector('.away-logo'), awayState);
  applyGamePickLogoState(card.querySelector('.home-logo'), homeState);
  applyGamePickSurfaceState(card.querySelector('.away-row'), awayState);
  applyGamePickSurfaceState(card.querySelector('.home-row'), homeState);
  applyGamePickSurfaceState(card.querySelector('.away-score'), awayState);
  applyGamePickSurfaceState(card.querySelector('.home-score'), homeState);
}

function syncLineupGamePickState(game, gamePickStates = trackedGamePickStateMap(latestRenderedGames)) {
  if (!lineupOverlayEl || !game?.gamePk) return;
  const pendingSide = pendingGamePickSideForGame(game);
  const tracked = gamePickStates.get(String(game.gamePk)) || { away: '', home: '' };
  const awayState = tracked.away || (pendingSide === 'away' ? pendingGamePickVisualState(game, 'away') : '');
  const homeState = tracked.home || (pendingSide === 'home' ? pendingGamePickVisualState(game, 'home') : '');
  applyGamePickLogoState(lineupOverlayEl.querySelector('.away-lineup-logo'), awayState);
  applyGamePickLogoState(lineupOverlayEl.querySelector('.home-lineup-logo'), homeState);
}

function syncAllCardGamePickStates(games = latestRenderedGames) {
  if (!(games || []).length) {
    if (pendingGamePickSelections.size) return;
    for (const card of gamesEl?.querySelectorAll('.game-card') || []) {
      applyGamePickLogoState(card.querySelector('.away-logo'), '');
      applyGamePickLogoState(card.querySelector('.home-logo'), '');
      applyGamePickSurfaceState(card.querySelector('.away-row'), '');
      applyGamePickSurfaceState(card.querySelector('.home-row'), '');
      applyGamePickSurfaceState(card.querySelector('.away-score'), '');
      applyGamePickSurfaceState(card.querySelector('.home-score'), '');
      applyGamePickCardState(card, '', '');
    }
    return;
  }
  const stateMap = trackedGamePickStateMap(games);
  for (const game of games || []) {
    const card = gamesEl?.querySelector(`.game-card[data-game-pk='${game.gamePk}']`);
    if (!card) continue;
    syncCardGamePickState(card, game, stateMap);
  }
}

function renderBetList(games = latestRenderedGames) {
  if (!betListEl || !betDayLabelEl) return;
  betDayLabelEl.textContent = dateInput.value;
  refreshBetPlayerOptions(games);
  setBetPanelMode(betPanelMode);
  renderPlayerTrackerList(games);
  const bets = getBets();
  const betStates = bets.map((bet) => {
    try {
      const resolved = resolveTrackedBet(bet, games);
      return `${resolved.status || ''}:${resolved.label || ''}:${resolved.active ? '1' : '0'}`;
    } catch {
      return 'manual';
    }
  });
  const fingerprint = JSON.stringify({
    day: dateInput.value,
    ids: bets.map((bet) => `${bet.id}:${bet.desc}:${bet.odds}:${bet.amount}:${bet.payout}`),
    states: betStates,
    picks: [...pendingGamePickSelections.entries()],
  });
  if (betListEl.dataset.renderFingerprint === fingerprint) {
    syncAllCardGamePickStates(games);
    return;
  }
  const scrollTop = betListEl.scrollTop;
  betListEl.dataset.renderFingerprint = fingerprint;
  betListEl.replaceChildren();
  if (!bets.length) {
    const empty = document.createElement('div');
    empty.className = 'lineup-empty';
    empty.textContent = 'No bets logged yet.';
    betListEl.appendChild(empty);
  }
  for (const b of bets) {
    const resolved = (() => {
      try {
        return resolveTrackedBet(b, games);
      } catch {
        return { tracked: null, status: 'manual', label: 'MANUAL', active: false, legs: [] };
      }
    })();
    const isGamePick = isGamePickBet(b);
    const amount = Number(b?.amount) || 0;
    const payout = Number(b?.payout) || 0;
    const el = document.createElement('div');
    el.className = `panel-item bet-item bet-status-${resolved.status || 'manual'}`;
    const textWrap = document.createElement('div');
    textWrap.className = 'bet-text';
    const summary = document.createElement('div');
    summary.textContent = `${b.desc || 'Bet'} | ${b.odds} | $${amount.toFixed(2)} -> $${payout.toFixed(2)}`;
    textWrap.appendChild(summary);

    const statusRow = document.createElement('div');
    statusRow.className = 'bet-status-row';
    statusRow.appendChild(buildBetStatusPill(resolved));
    if (isGamePick) {
      const meta = document.createElement('span');
      meta.textContent = 'Goal: WIN';
      statusRow.appendChild(meta);
    } else if (resolved.candidate?.fullName) {
      const meta = document.createElement('span');
      meta.textContent = `${resolved.candidate.fullName} | ${displayTeamAbbrev(resolved.candidate.teamAbbrev)}`;
      statusRow.appendChild(meta);
    }
    textWrap.appendChild(statusRow);

    if (Array.isArray(resolved.legs) && resolved.legs.length) {
      const legsEl = document.createElement('div');
      legsEl.className = 'bet-legs';
      for (const leg of resolved.legs) {
        try {
          legsEl.appendChild(buildBetLegPill(leg));
        } catch {
          const fallbackLeg = document.createElement('span');
          fallbackLeg.className = 'bet-leg-pill bet-status-unmatched';
          fallbackLeg.textContent = isGamePickLeg(leg?.leg)
            ? `${displayTeamAbbrev(leg?.leg?.teamAbbrev)} WIN`
            : `${leg?.leg?.playerName || 'Leg'} ${formatBetLegProp(leg?.leg || {})}`;
          legsEl.appendChild(fallbackLeg);
        }
      }
      textWrap.appendChild(legsEl);
    }

    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'bet-delete-btn';
    deleteBtn.type = 'button';
    deleteBtn.dataset.betId = b.id;
    deleteBtn.textContent = 'X';
    el.append(textWrap, deleteBtn);
    if (resolved.active) el.classList.add('bet-item-active');
    betListEl.appendChild(el);
  }
  syncAllCardGamePickStates(games);
  if (!betListEl.children.length) {
    const empty = document.createElement('div');
    empty.className = 'lineup-empty';
    empty.textContent = 'No bets logged yet.';
    betListEl.appendChild(empty);
  }
  betListEl.scrollTop = scrollTop;
}

function initBetInput() {
  if (betFormEl) betFormEl.noValidate = true;
  renderBetList();
  renderPendingGamePicks();
  clearBetsBtn.addEventListener('pointerdown', (e) => e.stopPropagation());
  betAddLegBtnEl?.addEventListener('pointerdown', (e) => e.stopPropagation());
  betClearLegsBtnEl?.addEventListener('pointerdown', (e) => e.stopPropagation());

  betAddLegBtnEl?.addEventListener('click', addDraftBetLeg);
  betClearLegsBtnEl?.addEventListener('click', clearDraftBetSlip);
  betLogTabBtnEl?.addEventListener('click', () => setBetPanelMode('bets'));
  betInputTabBtnEl?.addEventListener('click', () => setBetPanelMode('input'));
  playerTrackerTabBtnEl?.addEventListener('click', () => {
    setBetPanelMode('players');
    renderPlayerTrackerList(latestRenderedGames);
  });
  playerTrackerSortBtnEl?.addEventListener('click', () => {
    playerTrackerSortMode = nextPlayerTrackerSortMode();
    if (playerTrackerListEl) playerTrackerListEl.dataset.renderFingerprint = '';
    renderPlayerTrackerList(latestRenderedGames);
  });
  clearPendingPicksBtnEl?.addEventListener('click', () => clearPendingGamePicks());
  gamePickDialogCancelBtnEl?.addEventListener('click', closeGamePickDialog);
  gamePickDialogDismissBtnEl?.addEventListener('click', closeGamePickDialog);
  gamePickDialogSaveBtnEl?.addEventListener('click', (e) => {
    e.preventDefault();
    e.stopPropagation();
    confirmPendingGamePicksFromDialog();
  });
  gamePickDialogEl?.addEventListener('cancel', (e) => {
    e.preventDefault();
    closeGamePickDialog();
  });
  initPlayerBetContextMenu();
  updateBetBuilderMode();
  betPlayerSearchEl?.addEventListener('input', () => refreshBetPlayerOptions(latestRenderedGames, betPlayerSearchEl.value));
  for (const filter of [betPlayerTeamFilterEl, betPlayerSkillFilterEl, betPlayerPositionFilterEl, betPlayerHandFilterEl]) {
    filter?.addEventListener('change', () => {
      refreshBetPlayerOptions(latestRenderedGames, betPlayerSearchEl?.value || '');
      if (betPlayerSearchEl && betPlayerSearchEl.value && !resolveBetSearchPlayer(betPlayerSearchEl.value, latestRenderedGames)) {
        betPlayerSearchEl.value = '';
        refreshBetPlayerOptions(latestRenderedGames, '');
      }
    });
  }
  betPlayerSearchEl?.addEventListener('keydown', (e) => {
    if (e.key === 'Tab' && !e.shiftKey) {
      if (maybeSelectSingleBetPlayerOption()) return;
    }
    if (e.key !== 'Enter') return;
    e.preventDefault();
    if (betBuilderIsTeamWin()) {
      if (!resolveBetSearchTeam(betPlayerSearchEl.value, latestRenderedGames)) maybeSelectSingleBetPlayerOption();
      if (addDraftBetLeg()) return;
    }
    if (!resolveBetSearchPlayer(betPlayerSearchEl.value, latestRenderedGames)) maybeSelectSingleBetPlayerOption();
    betPropSelectEl?.focus();
  });
  betPropTargetEl?.addEventListener('input', () => {
    const normalized = normalizeBetTarget(betPropTargetEl.value || 1);
    betPropTargetEl.value = String(normalized);
  });
  betPropTargetEl?.addEventListener('focus', () => queueTextSelection(betPropTargetEl));
  betPropTargetEl?.addEventListener('pointerup', (e) => {
    if (e.pointerType === 'mouse') e.preventDefault();
    queueTextSelection(betPropTargetEl);
  });
  betPropSelectEl?.addEventListener('change', updateBetBuilderMode);
  betPropSelectEl?.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter') return;
    e.preventDefault();
    if (betBuilderIsTeamWin()) {
      focusBetPlayerSearch();
      return;
    }
    betPropTargetEl?.focus();
    queueTextSelection(betPropTargetEl);
  });
  betPropTargetEl?.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter') return;
    e.preventDefault();
    addDraftBetLeg();
  });
  betOddsEl?.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter') return;
    e.preventDefault();
    const pendingPicks = getPendingGamePickEntries(latestRenderedGames);
    const amount = Number(betAmountEl?.value);
    if (canSubmitPendingGamePicksFromMainForm(betDescEl?.value, pendingPicks) && Number.isFinite(amount) && amount > 0) {
      submitBetInput();
      return;
    }
    betAmountEl?.focus();
    betAmountEl?.select?.();
  });
  betAmountEl?.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter') return;
    e.preventDefault();
    submitBetInput();
  });

  betFormEl.addEventListener('submit', (e) => {
    e.preventDefault();
    submitBetInput();
  });

  clearBetsBtn.addEventListener('click', () => {
    if (betPanelMode === 'players') {
      saveTrackedPlayers([], undefined, { allowEmpty: true, forceEmpty: true });
      renderPlayerTrackerList(latestRenderedGames);
      return;
    }
    saveBets([]);
    renderBetList();
  });

  gamePickDialogFormEl?.addEventListener('submit', (e) => {
    e.preventDefault();
    confirmPendingGamePicksFromDialog();
  });

  betListEl.addEventListener('click', (e) => {
    if ((e.ctrlKey || e.metaKey)) {
      const legEl = e.target.closest('.bet-leg-pill[data-player-id]');
      if (legEl) {
        const playerId = Number(legEl.dataset.playerId);
        const gamePk = String(legEl.dataset.gamePk || '');
        const game = latestRenderedGames.find((g) => String(g.gamePk) === gamePk) || getCachedGames().find((g) => String(g.gamePk) === gamePk);
        if (Number.isFinite(playerId) && game) {
          e.preventDefault();
          e.stopPropagation();
          openPlayerStatOverlay(playerId, game);
          return;
        }
      }
      const itemEl = e.target.closest('.bet-item');
      if (itemEl) {
        const firstLeg = itemEl.querySelector('.bet-leg-pill[data-player-id]');
        if (firstLeg) {
          const playerId = Number(firstLeg.dataset.playerId);
          const gamePk = String(firstLeg.dataset.gamePk || '');
          const game = latestRenderedGames.find((g) => String(g.gamePk) === gamePk) || getCachedGames().find((g) => String(g.gamePk) === gamePk);
          if (Number.isFinite(playerId) && game) {
            e.preventDefault();
            e.stopPropagation();
            openPlayerStatOverlay(playerId, game);
            return;
          }
        }
      }
    }
    const button = e.target.closest('[data-bet-id]');
    if (!button) {
      const removeTrackedBtn = e.target.closest('[data-tracked-player-id]');
      if (removeTrackedBtn) {
        const playerId = String(removeTrackedBtn.dataset.trackedPlayerId || '');
        saveTrackedPlayers(getTrackedPlayers().filter((entry) => String(entry.playerId) !== playerId), undefined, { allowEmpty: true, forceEmpty: true });
        renderPlayerTrackerList(latestRenderedGames);
        return;
      }
      const expectationSelect = e.target.closest('[data-tracked-expectation-id]');
      if (expectationSelect) {
        const playerId = String(expectationSelect.dataset.trackedExpectationId || '');
        saveTrackedPlayers(getTrackedPlayers().map((entry) => (
          String(entry.playerId) === playerId
            ? { ...entry, expectation: normalizePlayerExpectation(expectationSelect.value) }
            : entry
        )));
        renderPlayerTrackerList(latestRenderedGames);
        return;
      }
      const trackedItem = e.target.closest('.player-track-item[data-player-id]');
      if (trackedItem && !e.target.closest('button,select,input,label')) {
        const playerId = Number(trackedItem.dataset.playerId);
        const gamePk = String(trackedItem.dataset.gamePk || '');
        const game = latestRenderedGames.find((g) => String(g.gamePk) === gamePk) || getCachedGames().find((g) => String(g.gamePk) === gamePk);
        if (Number.isFinite(playerId) && game) openPlayerStatOverlay(playerId, game);
      }
      return;
    }
    saveBets(getBets().filter((bet) => bet.id !== button.dataset.betId));
    renderBetList();
  });

  playerTrackerListEl?.addEventListener('click', (e) => {
    const removeTrackedBtn = e.target.closest('[data-tracked-player-id]');
    if (removeTrackedBtn) {
      const playerId = String(removeTrackedBtn.dataset.trackedPlayerId || '');
      saveTrackedPlayers(getTrackedPlayers().filter((entry) => String(entry.playerId) !== playerId), undefined, { allowEmpty: true, forceEmpty: true });
      renderPlayerTrackerList(latestRenderedGames);
      return;
    }
    const trackedItem = e.target.closest('.player-track-item[data-player-id]');
    if (!trackedItem || e.target.closest('button,select,input,label')) return;
    const playerId = Number(trackedItem.dataset.playerId);
    const gamePk = String(trackedItem.dataset.gamePk || '');
    const game = latestRenderedGames.find((g) => String(g.gamePk) === gamePk) || getCachedGames().find((g) => String(g.gamePk) === gamePk);
    const navContext = trackedPlayerNavContext(playerId, latestRenderedGames);
    if (Number.isFinite(playerId)) openPlayerStatOverlay(playerId, game || navContext?.game || null, navContext ? { navContext } : {});
  });
  playerTrackerListEl?.addEventListener('change', (e) => {
    const expectationSelect = e.target.closest('[data-tracked-expectation-id]');
    if (!expectationSelect) return;
    const playerId = String(expectationSelect.dataset.trackedExpectationId || '');
    saveTrackedPlayers(getTrackedPlayers().map((entry) => (
      String(entry.playerId) === playerId
        ? { ...entry, expectation: normalizePlayerExpectation(expectationSelect.value) }
        : entry
    )));
    renderPlayerTrackerList(latestRenderedGames);
  });
  playerTrackerListEl?.addEventListener('dragstart', (e) => {
    const item = e.target.closest('.player-track-item[data-player-id]');
    if (!item) return;
    item.classList.add('is-dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', item.dataset.playerId || '');
  });
  playerTrackerListEl?.addEventListener('dragover', (e) => {
    const draggingId = e.dataTransfer?.getData('text/plain') || playerTrackerListEl.querySelector('.player-track-item.is-dragging')?.dataset.playerId || '';
    if (!draggingId) return;
    const overItem = e.target.closest('.player-track-item[data-player-id]');
    if (!overItem || overItem.dataset.playerId === draggingId) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    const rect = overItem.getBoundingClientRect();
    overItem.classList.toggle('is-drop-before', e.clientY < rect.top + (rect.height / 2));
    overItem.classList.toggle('is-drop-after', e.clientY >= rect.top + (rect.height / 2));
  });
  playerTrackerListEl?.addEventListener('dragleave', (e) => {
    const item = e.target.closest('.player-track-item');
    item?.classList.remove('is-drop-before', 'is-drop-after');
  });
  playerTrackerListEl?.addEventListener('drop', (e) => {
    const movingId = e.dataTransfer?.getData('text/plain') || '';
    const overItem = e.target.closest('.player-track-item[data-player-id]');
    if (!movingId || !overItem) return;
    e.preventDefault();
    const rect = overItem.getBoundingClientRect();
    const after = e.clientY >= rect.top + (rect.height / 2);
    const tracked = getTrackedPlayers();
    const overIndex = tracked.findIndex((entry) => String(entry.playerId) === String(overItem.dataset.playerId || ''));
    const beforeEntry = after ? tracked[overIndex + 1] : tracked[overIndex];
    moveTrackedPlayer(movingId, beforeEntry?.playerId || '');
  });
  playerTrackerListEl?.addEventListener('dragend', () => {
    playerTrackerListEl.querySelectorAll('.player-track-item').forEach((item) => {
      item.classList.remove('is-dragging', 'is-drop-before', 'is-drop-after');
    });
  });
}

function buildOfficialScheduleSeedCard(game = null, date = '', cachedCards = new Map()) {
  if (!game) return null;
  const awayAbbrev = canonicalTeamAbbrev(
    game?.teams?.away?.team?.abbreviation
    || game?.teams?.away?.team?.teamCode?.toUpperCase?.()
    || game?.teams?.away?.team?.fileCode?.toUpperCase?.()
    || game?.teams?.away?.team?.name
    || '',
  );
  const homeAbbrev = canonicalTeamAbbrev(
    game?.teams?.home?.team?.abbreviation
    || game?.teams?.home?.team?.teamCode?.toUpperCase?.()
    || game?.teams?.home?.team?.fileCode?.toUpperCase?.()
    || game?.teams?.home?.team?.name
    || '',
  );
  if (!awayAbbrev || !homeAbbrev || awayAbbrev === 'AWAY' || homeAbbrev === 'HOME') return null;
  const identityKey = gameCardInstanceKey({
    away: awayAbbrev,
    home: homeAbbrev,
    gameDate: game?.gameDate || '',
    officialDate: game?.officialDate || date || '',
    gameNumber: game?.gameNumber || 1,
  }, date);
  const cached = cachedCards.get(identityKey) || cachedCards.get(gameMatchKey(awayAbbrev, homeAbbrev)) || cachedCards.get(String(game?.gamePk || '')) || null;
  const awayColor = cached?.awayColor || getTeamColor(awayAbbrev);
  const homeColor = cached?.homeColor || getTeamColor(homeAbbrev);
  const detail = statusLine(game) || 'Scheduled';
  const probablePitchers = sanitizeProbablePitchers({
    away: game?.teams?.away?.probablePitcher || cached?.probablePitchers?.away || null,
    home: game?.teams?.home?.probablePitcher || cached?.probablePitchers?.home || null,
  }, { ...game, playerLookup: cached?.playerLookup || {} }, awayAbbrev, homeAbbrev);
  return normalizeCompletedCard({
    ...(cached || {}),
    officialScheduleSeed: true,
    gamePk: game?.gamePk || cached?.gamePk || `${awayAbbrev}${homeAbbrev}`,
    gameDate: game?.gameDate || cached?.gameDate || '',
    officialDate: game?.officialDate || date || cached?.officialDate || '',
    gameNumber: game?.gameNumber || cached?.gameNumber || 1,
    doubleHeader: game?.doubleHeader || cached?.doubleHeader || 'N',
    away: awayAbbrev,
    home: homeAbbrev,
    awayRecord: formatTeamRecord(game?.teams?.away) || cached?.awayRecord || '',
    homeRecord: formatTeamRecord(game?.teams?.home) || cached?.homeRecord || '',
    awayScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.away?.score ?? cached?.awayScore ?? '-'),
    homeScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.home?.score ?? cached?.homeScore ?? '-'),
    awayHits: cached?.awayHits ?? '-',
    homeHits: cached?.homeHits ?? '-',
    status: detail,
    inning: detail,
    inningShort: game?.status?.abstractGameState === 'Preview' ? 'PRE' : (cached?.inningShort || detail || 'PRE'),
    awayColor,
    homeColor,
    awayLogo: cached?.awayLogo || getLogoPath(awayAbbrev),
    homeLogo: cached?.homeLogo || getLogoPath(homeAbbrev),
    awayPitcher: cached?.awayPitcher || '-',
    homePitcher: cached?.homePitcher || '-',
    awayHitter: cached?.awayHitter || '-',
    homeHitter: cached?.homeHitter || '-',
    probablePitchers,
    balls: cached?.balls ?? 0,
    strikes: cached?.strikes ?? 0,
    outs: cached?.outs ?? 0,
    bases: cached?.bases || { first: false, second: false, third: false },
    ticker: cached?.ticker || [],
    playByPlay: cached?.playByPlay || [],
    lastPlay: firstRealPlayText(cached?.lastPlay, cached?.ticker?.[0]?.text) || defaultPlayText(game),
    currentEvent: cached?.currentEvent || '',
    activeBatterId: cached?.activeBatterId || null,
    battingSide: cached?.battingSide || 'away',
    lineup: lineupCount(cached?.lineup) > 0 ? cached.lineup : emptyLineupData(),
    pitching: cached?.pitching || emptyPitchingData(),
    playerLookup: cached?.playerLookup || {},
  });
}

function emitOfficialScheduleSeedCards(games = [], date = '', cachedCards = new Map(), onCard = null) {
  if (typeof onCard !== 'function') return;
  // Paint every real schedule shell first, in chronological order. These are not
  // fake AWAY/HOME placeholders; they use the official MLB schedule matchup.
  for (const game of sortGameCardsChronologically(listify(games))) {
    const seed = buildOfficialScheduleSeedCard(game, date, cachedCards);
    if (!seed) continue;
    try { onCard(seed); } catch {}
  }
}

function upsertProgressiveGameCard(game = null, selectedDate = '') {
  if (!game || !game.gamePk || !gamesEl) return;
  const targetDate = String(selectedDate || dateInput?.value || formatDate(new Date())).slice(0, 10);
  if (!scoreboardDateStillActive(targetDate)) return;
  if (!gameMatchesScoreboardDate(game, targetDate)) return;
  latestRenderedGamesDate = targetDate;
  gamesEl.dataset.scoreboardDate = targetDate;
  const currentCard = latestRenderedGames.find((existing) => String(existing?.gamePk || '') === String(game?.gamePk || ''))
    || gamesEl.querySelector(`.game-card[data-game-pk='${game.gamePk}']`)?._game
    || null;
  const normalized = normalizeCompletedCard(chooseBestGameCard(currentCard, game));
  const incomingKey = gameCardInstanceKey(normalized, targetDate) || String(normalized.gamePk || '');
  const next = [];
  for (const existing of latestRenderedGames || []) {
    const existingKey = gameCardInstanceKey(existing, targetDate) || String(existing?.gamePk || '');
    if (String(existing?.gamePk || '') === String(normalized.gamePk || '') || (incomingKey && existingKey === incomingKey)) continue;
    next.push(existing);
  }
  next.push(normalized);
  latestRenderedGames = dedupeGameCards(next, targetDate);
  gamesEl.querySelectorAll('.empty, .games-loading').forEach((el) => el.remove());
  updateDashboardSummary(latestRenderedGames);
  upsertCard(normalized);
  syncGameCardDomOrder(latestRenderedGames);
  syncAllCardGamePickStates(latestRenderedGames);
  syncTossupScoreboardStates(latestRenderedGames);
  syncOverUnderScoreboardStates(latestRenderedGames);
  renderPlayerTrackerList(latestRenderedGames);
  renderBetList(latestRenderedGames);
  scheduleVisibleTeamStreakHydration(targetDate, 350);
}


function mergeFocusedHydrationHomeRuns(incomingHomeRuns = [], gamePk = '') {
  const incoming = listify(incomingHomeRuns).filter((hr) => String(hr?.gamePk || '') === String(gamePk || ''));
  if (!incoming.length) return;
  const keyForHr = (hr) => [
    String(hr?.gamePk || ''),
    String(hr?.batterId || hr?.batter || ''),
    String(hr?.eventTimeMs || hr?.eventTimeEt || hr?.inningText || ''),
    String(hr?.pitcherId || hr?.pitcherName || ''),
  ].join('|');
  const map = new Map();
  for (const hr of listify(latestRenderedHomeRuns)) map.set(keyForHr(hr), hr);
  for (const hr of incoming) map.set(keyForHr(hr), hr);
  const mergedHomeRuns = Array.from(map.values()).sort((a, b) => (Number(b.eventTimeMs) || 0) - (Number(a.eventTimeMs) || 0));
  updateHomeRunFeedIfChanged(mergedHomeRuns, { allowEmpty: false });
}

function requestFocusedGameHydration(gamePk, options = {}) {
  const targetGamePk = String(gamePk || '');
  if (!targetGamePk) return;
  const selectedDate = String(dateInput?.value || formatDate(new Date()));
  priorityHydrationGamePk = targetGamePk;
  const requestSeq = ++focusedGameHydrationSeq;
  const card = gamesEl?.querySelector?.(`.game-card[data-game-pk='${targetGamePk}']`);
  if (card) {
    card.classList.add('is-priority-hydrating');
    card.dataset.priorityHydrating = '1';
  }
  window.setTimeout(async () => {
    try {
      const result = await fetchGamesAndHomeRuns(selectedDate, {
        onlyGamePk: targetGamePk,
        suppressScheduleSeeds: true,
        suppressProgressiveHrFeed: true,
        skipDaySideEffects: true,
        onCard: (hydratedCard) => {
          if (requestSeq !== focusedGameHydrationSeq) return;
          if (String(dateInput?.value || '') !== selectedDate) return;
          if (String(hydratedCard?.gamePk || '') !== targetGamePk) return;
          upsertProgressiveGameCard(hydratedCard, selectedDate);
        },
      });
      if (requestSeq !== focusedGameHydrationSeq) return;
      if (String(dateInput?.value || '') !== selectedDate) return;
      const focusedCards = listify(result?.cards).filter((game) => String(game?.gamePk || '') === targetGamePk);
      for (const focusedCard of focusedCards) upsertProgressiveGameCard(focusedCard, selectedDate);
      if (focusedCards.length) {
        const retained = mergeRetainedScoreboardCardsForDate(focusedCards, selectedDate);
        saveCachedGames(retained);
        saveArchivedGames(selectedDate, retained);
        prewarmLineupHrScoresForGames(focusedCards);
        if (activeLineupGame && String(activeLineupGame?.gamePk || '') === targetGamePk) {
          activeLineupGame = chooseBestGameCard(activeLineupGame, focusedCards[0]);
          syncLineupOverlay(activeLineupGame, { forceOpen: true }).catch(() => {});
        }
      }
      mergeFocusedHydrationHomeRuns(result?.homeRuns || [], targetGamePk);
    } catch {} finally {
      const activeCard = gamesEl?.querySelector?.(`.game-card[data-game-pk='${targetGamePk}']`);
      if (activeCard) {
        activeCard.classList.remove('is-priority-hydrating');
        delete activeCard.dataset.priorityHydrating;
      }
    }
  }, Number(options?.delayMs) || 0);
}

function syncGameCardDomOrder(games = latestRenderedGames) {
  if (!gamesEl) return;
  const selectedDate = dateInput?.value || formatDate(new Date());
  const orderedGames = dedupeGameCards(games, selectedDate);
  for (const game of orderedGames) {
    const gamePk = String(game?.gamePk || '');
    if (!gamePk) continue;
    const card = gamesEl.querySelector(`.game-card[data-game-pk='${gamePk}']`);
    if (card) gamesEl.appendChild(card);
  }
}


function scoreboardGameDateKey(game = null, fallbackDate = '') {
  return String(game?.officialDate || game?.gameDate || fallbackDate || dateInput?.value || formatDate(new Date())).slice(0, 10);
}

function rawScoreboardGameDateKey(game = null) {
  return String(game?.officialDate || game?.gameDate || '').slice(0, 10);
}

function activeScoreboardDateKey(fallbackDate = '') {
  return String(fallbackDate || gamesEl?.dataset?.scoreboardDate || latestRenderedGamesDate || dateInput?.value || formatDate(new Date())).slice(0, 10);
}

function scoreboardDateStillActive(date = '') {
  const expected = String(date || '').slice(0, 10);
  if (!expected) return true;
  const selected = String(dateInput?.value || '').slice(0, 10);
  if (selected && selected !== expected) return false;
  const boardDate = String(gamesEl?.dataset?.scoreboardDate || '').slice(0, 10);
  if (boardDate && boardDate !== expected) return false;
  return true;
}

function gameMatchesScoreboardDate(game = null, date = '') {
  const expected = activeScoreboardDateKey(date);
  const actual = rawScoreboardGameDateKey(game);
  return !actual || !expected || actual === expected;
}

function mergeRetainedScoreboardCardsForDate(cards = [], selectedDate = '') {
  const dateKey = String(selectedDate || dateInput?.value || formatDate(new Date()));
  const merged = new Map();
  const addCard = (game, incoming = false) => {
    if (!game || !game.gamePk) return;
    if (scoreboardGameDateKey(game, dateKey) !== dateKey) return;
    const normalized = normalizeCompletedCard(game);
    const key = gameCardInstanceKey(normalized, dateKey) || String(normalized.gamePk || '');
    if (!key) return;
    const existing = merged.get(key);
    if (!existing) {
      merged.set(key, normalized);
      return;
    }
    merged.set(key, incoming ? chooseBestGameCard(existing, normalized) : chooseBestGameCard(normalized, existing));
  };
  if (latestRenderedGamesDate === dateKey) {
    for (const game of listify(latestRenderedGames)) addCard(game, false);
  }
  if (gamesEl?.dataset?.scoreboardDate === dateKey) {
    for (const card of gamesEl.querySelectorAll('.game-card')) {
      if (card?._game) addCard(card._game, false);
    }
  }
  for (const game of listify(cards)) addCard(game, true);
  return dedupeGameCards(Array.from(merged.values()), dateKey);
}

function scheduleGameHasTrackedPlayerTeam(game = null, date = '') {
  const tracked = normalizeTrackedPlayerEntries(getTrackedPlayers(date || dateInput?.value || formatDate(new Date())));
  if (!tracked.length || !game) return false;
  const away = game?.teams?.away?.team?.abbreviation || game?.teams?.away?.team?.teamCode || game?.away || '';
  const home = game?.teams?.home?.team?.abbreviation || game?.teams?.home?.team?.teamCode || game?.home || '';
  return tracked.some((entry) => sameTeamAbbrev(entry.teamAbbrev, away) || sameTeamAbbrev(entry.teamAbbrev, home));
}

function scheduleGameStatusLooksLive(game = null) {
  const text = [
    game?.status?.abstractGameState,
    game?.status?.detailedState,
    game?.status?.codedGameState,
    game?.status,
  ].map((part) => String(part || '')).join(' ').toLowerCase();
  if (/final|game over|completed|postpon|cancel|suspend/.test(text)) return false;
  return /live|in progress|warmup|delayed|top|bottom|bot|mid|end/.test(text);
}

function homeRunGamePkPrioritySetForDate(date = '') {
  const set = new Set();
  for (const hr of [...listify(latestRenderedHomeRuns), ...listify(cachedHomeRunsForSelectedDate())]) {
    const gamePk = String(hr?.gamePk || '');
    if (gamePk) set.add(gamePk);
  }
  return set;
}

function sortScheduleGamesForHydration(games = [], date = '', options = {}) {
  const selectedDate = String(date || dateInput?.value || formatDate(new Date()));
  const hrGamePks = homeRunGamePkPrioritySetForDate(selectedDate);
  const chrono = sortGameCardsChronologically(listify(games));
  const indexByPk = new Map(chrono.map((game, index) => [String(game?.gamePk || ''), index]));
  const priorityGamePk = String(priorityHydrationGamePk || focusedGamePk || '');
  const priority = (game) => {
    if (priorityGamePk && String(game?.gamePk || '') === priorityGamePk) return -1;
    if (hrGamePks.has(String(game?.gamePk || ''))) return 0;
    if (scheduleGameStatusLooksLive(game)) return 1;
    if (scheduleGameHasTrackedPlayerTeam(game, selectedDate)) return 2;
    return 3;
  };
  const startMs = (game) => {
    const ms = Date.parse(game?.gameDate || game?.officialDate || selectedDate || '');
    return Number.isFinite(ms) ? ms : 0;
  };
  const chronologicalCompare = (a, b) => (indexByPk.get(String(a?.gamePk || '')) ?? 9999) - (indexByPk.get(String(b?.gamePk || '')) ?? 9999);
  const reverseTimeCompare = (a, b) => (startMs(b) - startMs(a)) || chronologicalCompare(a, b);
  return chrono.slice().sort((a, b) => priority(a) - priority(b)
    || (options.latestGamesFirst ? reverseTimeCompare(a, b) : chronologicalCompare(a, b)));
}

async function fetchGamesAndHomeRuns(date, options = {}) {
  const homeRunAbortToken = Number.isFinite(Number(options?.homeRunAbortToken))
    ? Number(options.homeRunAbortToken)
    : homeRunFeedAbortSeq;
  const homeRunsAborted = () => homeRunFeedLoadIsStale(date, homeRunAbortToken);
  const schedule = await getSchedule(date);
  const focusOnlyGamePk = String(options?.onlyGamePk || '');
  const allGames = sortGameCardsChronologically((schedule?.dates?.[0]?.games || []).filter((game) => !isPostponedGameStatus(game)));
  const games = focusOnlyGamePk ? allGames.filter((game) => String(game?.gamePk || '') === focusOnlyGamePk) : allGames;
  const homeRuns = [];
  const matchupEvents = [];
  const cachedCards = mapCachedCardsForDate(getCachedGames(), date);
  const onCard = typeof options?.onCard === 'function' ? options.onCard : null;
  const orderedFullCardBuffer = [];
  let nextOrderedFullCardIndex = 0;
  const flushOrderedFullCards = () => {
    if (!onCard) return;
    while (nextOrderedFullCardIndex < games.length && orderedFullCardBuffer[nextOrderedFullCardIndex]) {
      const card = orderedFullCardBuffer[nextOrderedFullCardIndex];
      nextOrderedFullCardIndex += 1;
      try { onCard(card); } catch {}
    }
  };
  const emitCard = (card, orderIndex = null) => {
    const normalized = normalizeCompletedCard(card);
    if (onCard) {
      const index = Number(orderIndex);
      if (Number.isInteger(index) && index >= 0 && !normalized.officialScheduleSeed) {
        orderedFullCardBuffer[index] = normalized;
        flushOrderedFullCards();
      } else {
        try { onCard(normalized); } catch {}
      }
    }
    return normalized;
  };
  const teamStreaks = new Map();
  if (onCard && !options?.suppressScheduleSeeds) {
    try {
      emitOfficialScheduleSeedCards(games, date, cachedCards, onCard);
    } catch {}
  }
  const hydrationGames = sortScheduleGamesForHydration(games, date, { latestGamesFirst: options.latestGamesFirst !== false });
  const cardResults = await mapWithConcurrency(hydrationGames, 2, async (game, gameIndex) => {
    const emitGameCard = (card) => emitCard(card, gameIndex);
    const gamePk = game.gamePk;
    const gameOfficialDate = officialDateForGame(game, date);
    const isFuturePreview = game?.status?.abstractGameState === 'Preview' && gameOfficialDate > formatDate(new Date());
    if (isFuturePreview) {
      const awayTeam = game?.teams?.away?.team || {};
      const homeTeam = game?.teams?.home?.team || {};
      const awayAbbrev = awayTeam.abbreviation || awayTeam.teamCode?.toUpperCase() || awayTeam.name || 'AWAY';
      const homeAbbrev = homeTeam.abbreviation || homeTeam.teamCode?.toUpperCase() || homeTeam.name || 'HOME';
      const awayColor = getTeamColor(awayAbbrev);
      const homeColor = getTeamColor(homeAbbrev);
      let probablePitchers = sanitizeProbablePitchers({
        away: game?.teams?.away?.probablePitcher || null,
        home: game?.teams?.home?.probablePitcher || null,
      }, game, awayAbbrev, homeAbbrev);
      probablePitchers = await resolvePregameProbablePitchersFastFallback(probablePitchers, game, awayAbbrev, homeAbbrev, gameOfficialDate, {
        scheduleTimeoutMs: 1200,
        rotationTimeoutMs: 0,
      }).catch(() => probablePitchers);
      return emitGameCard({
        gamePk,
        gameDate: game?.gameDate || '',
        officialDate: gameOfficialDate,
        gameNumber: game?.gameNumber || 1,
        doubleHeader: game?.doubleHeader || 'N',
        away: awayAbbrev,
        home: homeAbbrev,
        awayRecord: formatTeamRecord(game?.teams?.away),
        homeRecord: formatTeamRecord(game?.teams?.home),
        awayStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.away, null, awayAbbrev),
        homeStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.home, null, homeAbbrev),
        awayScore: '-',
        homeScore: '-',
        awayHits: '-',
        homeHits: '-',
        status: statusLine(game),
        inning: statusLine(game),
        inningShort: 'PRE',
        balls: 0,
        strikes: 0,
        outs: 0,
        lineScoreInnings: [],
        awayColor,
        homeColor,
        awayLogo: getLogoPath(awayAbbrev),
        homeLogo: getLogoPath(homeAbbrev),
        awayPitcher: '-',
        homePitcher: '-',
        awayHitter: '-',
        homeHitter: '-',
        bases: { first: false, second: false, third: false },
        ticker: [],
        playByPlay: [],
        lastPlay: defaultPlayText(game),
        currentEvent: '',
        activeBatterId: null,
        activeBatterName: '',
        activePlayComplete: false,
        activePlayAtBatIndex: null,
        battingSide: 'away',
        probablePitchers,
        lineup: emptyLineupData(),
        pitching: emptyPitchingData(),
        playerLookup: {},
      });
    }
    try {
      const live = await withTimeoutValue(getLiveGameFeed(gamePk), 1800, null);
      if (!live) throw new Error('Live feed fast timeout');
      const boxscore = live?.liveData?.boxscore || {};
      const linescore = live?.liveData?.linescore || {};
      const allPlays = live?.liveData?.plays?.allPlays || [];
      const currentPlay = live?.liveData?.plays?.currentPlay;
      const liveStatusGame = { ...game, status: live?.gameData?.status || game?.status };
      const officialStartReached = gameHasReachedOfficialStart(liveStatusGame);
      const visiblePlays = officialStartReached ? allPlays : [];
      const visibleLinescore = officialStartReached ? linescore : {};
      const activePlay = officialStartReached ? resolveActivePlay(liveStatusGame, currentPlay, visiblePlays) : null;
      const finalByScore = officialStartReached && gameLooksFinalByScore(liveStatusGame, visibleLinescore, visiblePlays, activePlay);
      const statusGame = gameWithInferredFinalStatus(liveStatusGame, finalByScore);

      const awayTeam = live?.gameData?.teams?.away || game?.teams?.away?.team || {};
      const homeTeam = live?.gameData?.teams?.home || game?.teams?.home?.team || {};
      const awayAbbrev = awayTeam.abbreviation || awayTeam.teamCode?.toUpperCase() || awayTeam.name || 'AWAY';
      const homeAbbrev = homeTeam.abbreviation || homeTeam.teamCode?.toUpperCase() || homeTeam.name || 'HOME';
      let probablePitchers = sanitizeProbablePitchers({
        away: live?.gameData?.teams?.away?.probablePitcher || game?.teams?.away?.probablePitcher || null,
        home: live?.gameData?.teams?.home?.probablePitcher || game?.teams?.home?.probablePitcher || null,
      }, statusGame, awayAbbrev, homeAbbrev);
      probablePitchers = await resolveOfficialPregameProbablePitchers(probablePitchers, statusGame, awayAbbrev, homeAbbrev, officialDateForGame(game, date));
      const awayColor = getTeamColor(awayAbbrev);
      const homeColor = getTeamColor(homeAbbrev);

      const awayPlayers = boxscore?.teams?.away?.players || {};
      const homePlayers = boxscore?.teams?.home?.players || {};
      const gamePlayers = live?.gameData?.players || {};
      const playerLookup = {
        ...buildPlayerLookup(awayPlayers, gamePlayers, awayAbbrev, awayColor, getLogoPath(awayAbbrev)),
        ...buildPlayerLookup(homePlayers, gamePlayers, homeAbbrev, homeColor, getLogoPath(homeAbbrev)),
      };

      const ticker = [];
      if (activePlay && !isSubstitutionPlay(activePlay)) {
        ticker.push({ text: eventLabel(activePlay), color: activePlay?.about?.halfInning === 'top' ? awayColor : homeColor });
      }
      for (const play of [...visiblePlays].slice(-10).reverse()) {
        const text = eventLabel(play);
        if (!ticker.find((t) => t.text === text)) ticker.push({ text, color: play?.about?.halfInning === 'top' ? awayColor : homeColor });
        if (ticker.length >= 6) break;
      }

      const pitcherHrTotalsInGame = new Map();
      for (const play of visiblePlays) {
        if (play?.result?.event !== 'Home Run') continue;
        const pitcherId = Number(play?.matchup?.pitcher?.id);
        if (!Number.isFinite(pitcherId)) continue;
        pitcherHrTotalsInGame.set(pitcherId, (pitcherHrTotalsInGame.get(pitcherId) || 0) + 1);
      }
      const pitcherHrSeenInGame = new Map();
      for (const play of visiblePlays) {
        if (play?.about?.isComplete && play?.matchup?.batter?.id && play?.matchup?.pitcher?.id) {
          matchupEvents.push({ play, game: { gamePk, away: awayAbbrev, home: homeAbbrev }, playerLookup });
        }
        if (play?.result?.event === 'Home Run') {
          const batterId = play?.matchup?.batter?.id;
          const pitcherId = play?.matchup?.pitcher?.id;
          const batter = play?.matchup?.batter?.fullName || 'Unknown';
          const pitcherProfile = pitcherId ? playerLookup[String(pitcherId)] || playerLookup[`ID${pitcherId}`] : null;
          const pitcherName = play?.matchup?.pitcher?.fullName || pitcherProfile?.fullName || '';
          const numericPitcherId = Number(pitcherId);
          const pitcherGameHrIndex = Number.isFinite(numericPitcherId) ? (pitcherHrSeenInGame.get(numericPitcherId) || 0) + 1 : 0;
          if (Number.isFinite(numericPitcherId)) pitcherHrSeenInGame.set(numericPitcherId, pitcherGameHrIndex);
          const pitcherSeasonHrAllowed = pitcherProfile ? pitcherHomeRunsAllowed(pitcherProfile) : null;
          const pitcherGameHrTotal = Number.isFinite(numericPitcherId) ? pitcherHrTotalsInGame.get(numericPitcherId) || 0 : 0;
          const pitcherHrAllowedDisplay = Number.isFinite(Number(pitcherSeasonHrAllowed))
            ? Math.max(0, Number(pitcherSeasonHrAllowed) - pitcherGameHrTotal) + pitcherGameHrIndex
            : null;
          const half = play?.about?.halfInning;
          const battingTeamAbbr = half === 'top' ? awayAbbrev : homeAbbrev;
          const battingColor = half === 'top' ? awayColor : homeColor;
          const battingSide = half === 'top' ? 'away' : 'home';
          const players = half === 'top' ? awayPlayers : homePlayers;
          const jersey = players[`ID${batterId}`]?.jerseyNumber || '?';
          const isWalkOffHr = isWalkOffHomeRunByPlayHistory(play, visiblePlays, battingSide);
          const ratingPlay = isWalkOffHr
            ? { ...play, about: { ...(play.about || {}), isWalkOff: true }, result: { ...(play.result || {}), isWalkOff: true } }
            : play;
          if (homeRunsAborted()) continue;
          const parsedHrNo = parseHrNumber(play?.result?.description || '');
          const lookupHrNo = parsedHrNo ? null : lookupPlayerSeasonHomeRuns(batterId, playerLookup);
          const fetchedHrNo = (parsedHrNo || lookupHrNo || homeRunsAborted()) ? null : await getPlayerSeasonHomeRuns(batterId, date).catch(() => null);
          if (homeRunsAborted()) continue;
          const hrNo = parsedHrNo || lookupHrNo || fetchedHrNo;
          const distance = play?.playEvents?.find((e) => e?.hitData?.totalDistance)?.hitData?.totalDistance || null;
          const hit = liveLabHitDetail(play);
          const ratingBreakdown = homeRunRatingBreakdown(ratingPlay, pitcherProfile, distance, battingSide);

          homeRuns.push({
            gamePk,
            atBatIndex: play?.about?.atBatIndex ?? null,
            playId: play?.playEvents?.find((event) => event?.playId)?.playId || '',
            homeAbbr: homeAbbrev,
            batterId,
            batter,
            jersey,
            resultLabel: homeRunResultLabel(play, isWalkOffHr),
            hrNo,
            distance,
            hit,
            pitcherId,
            pitcherName,
            pitcherHand: handednessCode(pitcherProfile?.throws || pitcherProfile?.pitching?.throws || pitcherProfile?.pitchHand?.code || play?.matchup?.pitchHand?.code || ''),
            pitcherHrAllowed: pitcherHrAllowedDisplay,
            pitchDetailLine: homeRunPitchDetailLine(play),
            eventTimeMs: playTimestampMs(play, (Date.parse(game?.gameDate || date) || 0) + ((play?.about?.atBatIndex ?? 0) * 1000)),
            eventTimeEt: formatEasternClock(playTimestampMs(play, (Date.parse(game?.gameDate || date) || 0) + ((play?.about?.atBatIndex ?? 0) * 1000))),
            inningText: formatHrInningText(play),
            rating: ratingBreakdown.score,
            ratingBreakdown,
            teamAbbr: battingTeamAbbr,
            teamColor: battingColor,
            teamLogo: getLogoPath(battingTeamAbbr),
            order: play?.about?.atBatIndex ?? 0,
          });
          if (onCard && !options?.suppressProgressiveHrFeed) {
            updateHomeRunFeedIfChanged(homeRuns, { allowEmpty: false });
          }
        }
      }

      const rawCount = officialStartReached ? countForGame(visibleLinescore, activePlay) : { balls: 0, strikes: 0, outs: 0 };
      const count = finalByScore ? { balls: 0, strikes: 0, outs: 0 } : rawCount;
      const ppl = currentPeople(activePlay, visibleLinescore, statusGame, awayPlayers, homePlayers);
      const inning = finalByScore ? { long: 'Final', short: 'Final' } : inningDisplay(visibleLinescore, statusGame, activePlay);
      let card = {
        gamePk,
        gameDate: game?.gameDate || '',
        officialDate: game?.officialDate || schedule?.dates?.[0]?.date || '',
        gameNumber: game?.gameNumber || 1,
        doubleHeader: game?.doubleHeader || 'N',
        away: awayAbbrev,
        home: homeAbbrev,
        awayRecord: formatTeamRecord(live?.gameData?.teams?.away) || formatTeamRecord(game?.teams?.away),
        homeRecord: formatTeamRecord(live?.gameData?.teams?.home) || formatTeamRecord(game?.teams?.home),
        awayStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.away, live?.gameData?.teams?.away, awayAbbrev),
        homeStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.home, live?.gameData?.teams?.home, homeAbbrev),
        awayScore: shouldPreferProbablePitcher(statusGame) ? '-' : gameScoreForSide(statusGame, visibleLinescore, visiblePlays, 'away'),
        homeScore: shouldPreferProbablePitcher(statusGame) ? '-' : gameScoreForSide(statusGame, visibleLinescore, visiblePlays, 'home'),
        awayHits: shouldPreferProbablePitcher(statusGame) ? '-' : gameHitsForSide(visibleLinescore, 'away'),
        homeHits: shouldPreferProbablePitcher(statusGame) ? '-' : gameHitsForSide(visibleLinescore, 'home'),
        status: statusLine(statusGame),
        inning: inning.long,
        inningShort: inning.short,
        balls: count.balls,
        strikes: count.strikes,
        outs: count.outs,
        lineScoreInnings: officialStartReached && Array.isArray(linescore?.innings) ? linescore.innings : [],
        awayColor,
        homeColor,
        awayLogo: getLogoPath(awayAbbrev),
        homeLogo: getLogoPath(homeAbbrev),
        awayPitcher: ppl.awayPitcher,
        homePitcher: ppl.homePitcher,
        awayHitter: ppl.awayHitter,
        homeHitter: ppl.homeHitter,
        bases: officialStartReached && !finalByScore ? baseState(visibleLinescore, statusGame, activePlay) : { first: false, second: false, third: false },
        ticker,
        playByPlay: visiblePlays.map((play) => ({
          inning: play?.about?.inning || '',
          half: play?.about?.halfInning || '',
          event: play?.result?.event || '',
          description: playByPlayDescription(play),
          color: play?.about?.halfInning === 'top' ? awayColor : homeColor,
          atBatIndex: play?.about?.atBatIndex ?? 0,
        })),
        lastPlay: firstRealPlayText(ticker[0]?.text, activePlay?.result?.description, cachedCards.get(gamePk)?.lastPlay) || defaultPlayText(statusGame),
        currentEvent: activePlay?.result?.event || '',
        activeBatterId: activePlay?.matchup?.batter?.id || null,
        activeBatterName: activePlay?.matchup?.batter?.fullName || '',
        activePlayComplete: Boolean(activePlay?.about?.isComplete),
        activePlayAtBatIndex: activePlay?.about?.atBatIndex ?? null,
        battingSide: ppl.battingSide,
        probablePitchers,
        lineup: emptyLineupData(),
        pitching: emptyPitchingData(),
        playerLookup: {},
      };

      const derived = buildGameDataFromBoxscore(boxscore, statusGame, {
        activePlay,
        gamePlayers,
        awayAbbrev,
        homeAbbrev,
        awayColor,
        homeColor,
        battingSide: ppl.battingSide,
        probablePitchers,
        currentPitcherId: ppl.currentPitcherId,
        allPlays: visiblePlays,
      });
      card.lineup = derived.lineup;
      card.pitching = pitchingWithLatestBoxscoreSnapshot(derived.pitching, boxscore, visiblePlays);
      card.playerLookup = { ...playerLookup, ...derived.playerLookup };

      if (lineupCount(card.lineup) === 0) {
        try {
          const rawBox = await getGameBoxscore(gamePk);
          const box = normalizeBoxscorePayload(rawBox);
          const boxDerived = buildGameDataFromBoxscore(box, statusGame, {
            activePlay,
            gamePlayers,
            awayAbbrev,
            homeAbbrev,
            awayColor,
            homeColor,
            battingSide: ppl.battingSide,
            probablePitchers,
            currentPitcherId: ppl.currentPitcherId,
            allPlays: visiblePlays,
          });
          card = {
            ...card,
            lineup: chooseBetterLineup(boxDerived.lineup, card.lineup),
            pitching: chooseBetterPitching(pitchingWithLatestBoxscoreSnapshot(boxDerived.pitching, box, visiblePlays), card.pitching),
            playerLookup: { ...card.playerLookup, ...boxDerived.playerLookup },
          };
        } catch {}
      }

      if (isCompletedGameCard(card)) {
        card = mergeFinishedGameState(card, cachedCards.get(gamePk));
      }

      return emitGameCard(card);
    } catch (error) {
      const cached = cachedCards.get(gamePk);
      const awayFromSchedule = game?.teams?.away?.team?.abbreviation || game?.teams?.away?.team?.teamCode?.toUpperCase() || cached?.away || 'AWAY';
      const homeFromSchedule = game?.teams?.home?.team?.abbreviation || game?.teams?.home?.team?.teamCode?.toUpperCase() || cached?.home || 'HOME';
      const awayColor = getTeamColor(awayFromSchedule);
      const homeColor = getTeamColor(homeFromSchedule);
      let derivedLineup = emptyLineupData();
      let derivedPitching = emptyPitchingData();
      let derivedLookup = cached?.playerLookup || {};
      const skipSlowFallbackBoxscore = /fast timeout/i.test(String(error?.message || ''));
      try {
        if (skipSlowFallbackBoxscore) throw new Error('Skip slow boxscore after live fast timeout');
        const rawBox = await getGameBoxscore(gamePk);
        const box = normalizeBoxscorePayload(rawBox);
        const boxDerived = buildGameDataFromBoxscore(box, game, {
          awayAbbrev: awayFromSchedule,
          homeAbbrev: homeFromSchedule,
          awayColor,
          homeColor,
        });
        derivedLineup = chooseBetterLineup(boxDerived.lineup, derivedLineup);
        derivedPitching = chooseBetterPitching(pitchingWithLatestBoxscoreSnapshot(boxDerived.pitching, box, []), derivedPitching);
        derivedLookup = { ...derivedLookup, ...boxDerived.playerLookup };
      } catch {}
      let fallbackProbablePitchers = sanitizeProbablePitchers({
        away: game?.teams?.away?.probablePitcher || cached?.probablePitchers?.away || null,
        home: game?.teams?.home?.probablePitcher || cached?.probablePitchers?.home || null,
      }, { ...game, playerLookup: derivedLookup }, awayFromSchedule, homeFromSchedule);
      // First scoreboard paint must not wait on probable-pitcher page scraping.
      // Schedule probables/cached probables are enough here; the lineup layer hydrates later.
      if (skipSlowFallbackBoxscore && !cached) return null;
      if (cached) {
        return emitGameCard({
          ...cached,
          gameDate: game?.gameDate || cached?.gameDate || '',
          officialDate: game?.officialDate || schedule?.dates?.[0]?.date || cached?.officialDate || '',
          gameNumber: game?.gameNumber || cached?.gameNumber || 1,
          doubleHeader: game?.doubleHeader || cached?.doubleHeader || 'N',
          lineup: lineupCount(derivedLineup) > 0 ? derivedLineup : emptyLineupData(),
          pitching: chooseBetterPitching(derivedPitching, cached?.pitching),
          awayScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.away?.score ?? cached.awayScore),
          homeScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.home?.score ?? cached.homeScore),
          awayRecord: formatTeamRecord(game?.teams?.away) || cached?.awayRecord || '',
          homeRecord: formatTeamRecord(game?.teams?.home) || cached?.homeRecord || '',
          awayStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.away, null, awayFromSchedule) || cached?.awayStreak || '',
          homeStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.home, null, homeFromSchedule) || cached?.homeStreak || '',
          status: statusLine(game) || cached.status,
          probablePitchers: fallbackProbablePitchers,
          playerLookup: { ...(cached.playerLookup || {}), ...derivedLookup },
        });
      }
      return emitGameCard({
        gamePk,
        gameDate: game?.gameDate || '',
        officialDate: game?.officialDate || schedule?.dates?.[0]?.date || '',
        gameNumber: game?.gameNumber || 1,
        doubleHeader: game?.doubleHeader || 'N',
        away: awayFromSchedule,
        home: homeFromSchedule,
        awayRecord: formatTeamRecord(game?.teams?.away),
        homeRecord: formatTeamRecord(game?.teams?.home),
        awayStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.away, null, awayFromSchedule),
        homeStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.home, null, homeFromSchedule),
        awayScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.away?.score ?? '-'),
        homeScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.home?.score ?? '-'),
        status: statusLine(game),
        inning: statusLine(game),
        inningShort: statusLine(game),
        balls: 0,
        strikes: 0,
        outs: 0,
        awayColor,
        homeColor,
        awayLogo: getLogoPath(awayFromSchedule),
        homeLogo: getLogoPath(homeFromSchedule),
        awayPitcher: '-',
        homePitcher: '-',
        awayHitter: '-',
        homeHitter: '-',
        bases: { first: false, second: false, third: false },
        ticker: [],
        playByPlay: [],
        lastPlay: defaultPlayText(game),
        currentEvent: '',
        activeBatterId: null,
        activeBatterName: '',
        activePlayComplete: false,
        activePlayAtBatIndex: null,
        battingSide: 'away',
        probablePitchers: fallbackProbablePitchers,
        lineup: derivedLineup,
        pitching: derivedPitching,
        playerLookup: derivedLookup,
      });
    }
  });

  const scheduleSeedCards = options?.suppressScheduleSeeds ? [] : games
    .map((game) => buildOfficialScheduleSeedCard(game, date, cachedCards))
    .filter(Boolean);
  const cards = dedupeGameCards([...scheduleSeedCards, ...cardResults.filter(Boolean)], date);
  if (!options?.skipDaySideEffects) {
    saveAnalyticsDayIndex(date, buildDailyAnalyticsIndex(date, cards, matchupEvents));
  }
  if (homeRunsAborted()) return { cards, homeRuns: [] };
  const dedupedHomeRuns = mergeHomeRunFeedItems([], homeRuns);
  if (!options?.skipDaySideEffects) {
    try {
      localStorage.setItem(`hrs:${date}`, JSON.stringify(dedupedHomeRuns.slice(0, 120)));
      localStorage.setItem(hrLoadedStorageKey(date), '1');
    } catch {}
  }
  return { cards, homeRuns: dedupedHomeRuns };
}

async function fetchMlbScheduleOnlyCards(date, cachedCards = new Map()) {
  try {
    const schedule = await getSchedule(date);
    const games = (schedule?.dates?.[0]?.games || []).filter((game) => !isPostponedGameStatus(game));
    if (!games.length) return [];
    const teamStreaks = new Map();
    const cards = games.map((game) => {
      const awayAbbrev = game?.teams?.away?.team?.abbreviation || game?.teams?.away?.team?.teamCode?.toUpperCase() || 'AWAY';
      const homeAbbrev = game?.teams?.home?.team?.abbreviation || game?.teams?.home?.team?.teamCode?.toUpperCase() || 'HOME';
      const identityKey = gameCardInstanceKey({
        away: awayAbbrev,
        home: homeAbbrev,
        gameDate: game?.gameDate || '',
        officialDate: game?.officialDate || date || '',
        gameNumber: game?.gameNumber || 1,
      }, date);
      const cached = cachedCards.get(identityKey) || cachedCards.get(gameMatchKey(awayAbbrev, homeAbbrev)) || cachedCards.get(String(game.gamePk || '')) || null;
      const awayColor = cached?.awayColor || getTeamColor(awayAbbrev);
      const homeColor = cached?.homeColor || getTeamColor(homeAbbrev);
      const detail = statusLine(game);
      const probablePitchers = sanitizeProbablePitchers({
        away: game?.teams?.away?.probablePitcher || cached?.probablePitchers?.away || null,
        home: game?.teams?.home?.probablePitcher || cached?.probablePitchers?.home || null,
      }, { ...game, playerLookup: cached?.playerLookup || {} }, awayAbbrev, homeAbbrev);
      return normalizeCompletedCard({
        ...(cached || {}),
        fastScheduleShell: true,
        gamePk: game.gamePk || cached?.gamePk || `${awayAbbrev}${homeAbbrev}`,
        gameDate: game?.gameDate || cached?.gameDate || '',
        officialDate: game?.officialDate || date || cached?.officialDate || '',
        gameNumber: game?.gameNumber || cached?.gameNumber || 1,
        doubleHeader: game?.doubleHeader || cached?.doubleHeader || 'N',
        away: awayAbbrev,
        home: homeAbbrev,
        awayRecord: formatTeamRecord(game?.teams?.away) || cached?.awayRecord || '',
        homeRecord: formatTeamRecord(game?.teams?.home) || cached?.homeRecord || '',
        awayStreak: cached?.awayStreak || teamStreakForGameTeam(teamStreaks, game?.teams?.away, null, awayAbbrev) || '',
        homeStreak: cached?.homeStreak || teamStreakForGameTeam(teamStreaks, game?.teams?.home, null, homeAbbrev) || '',
        awayScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.away?.score ?? cached?.awayScore ?? '-'),
        homeScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.home?.score ?? cached?.homeScore ?? '-'),
        awayHits: cached?.awayHits ?? '-',
        homeHits: cached?.homeHits ?? '-',
        status: detail || cached?.status || 'Scheduled',
        inning: detail || cached?.inning || 'Scheduled',
        inningShort: cached?.inningShort || (game?.status?.abstractGameState === 'Preview' ? 'PRE' : detail || 'PRE'),
        awayColor,
        homeColor,
        awayLogo: cached?.awayLogo || getLogoPath(awayAbbrev),
        homeLogo: cached?.homeLogo || getLogoPath(homeAbbrev),
        awayPitcher: cached?.awayPitcher || '-',
        homePitcher: cached?.homePitcher || '-',
        awayHitter: cached?.awayHitter || '-',
        homeHitter: cached?.homeHitter || '-',
        probablePitchers,
        balls: cached?.balls ?? 0,
        strikes: cached?.strikes ?? 0,
        outs: cached?.outs ?? 0,
        bases: cached?.bases || { first: false, second: false, third: false },
        ticker: cached?.ticker || [],
        playByPlay: cached?.playByPlay || [],
        lastPlay: firstRealPlayText(cached?.lastPlay, cached?.ticker?.[0]?.text) || defaultPlayText(game),
        currentEvent: cached?.currentEvent || '',
        activeBatterId: cached?.activeBatterId || null,
        activeBatterName: cached?.activeBatterName || '',
        activePlayComplete: Boolean(cached?.activePlayComplete),
        activePlayAtBatIndex: cached?.activePlayAtBatIndex ?? null,
        battingSide: cached?.battingSide || 'away',
        lineup: lineupCount(cached?.lineup) > 0 ? cached.lineup : emptyLineupData(),
        pitching: cached?.pitching || emptyPitchingData(),
        playerLookup: cached?.playerLookup || {},
      });
    });
    return dedupeGameCards(cards, date);
  } catch {
    return [];
  }
}

async function fetchMlbFallbackCards(date, cachedCards) {
  try {
    const schedule = await getSchedule(date);
    const games = (schedule?.dates?.[0]?.games || []).filter((game) => !isPostponedGameStatus(game));
    if (!games.length) return [];
    const teamStreaks = new Map();

    const cards = await Promise.all(games.map(async (game) => {
      const awayAbbrev = game?.teams?.away?.team?.abbreviation || game?.teams?.away?.team?.teamCode?.toUpperCase() || 'AWAY';
      const homeAbbrev = game?.teams?.home?.team?.abbreviation || game?.teams?.home?.team?.teamCode?.toUpperCase() || 'HOME';
      const identityKey = gameCardInstanceKey({
        away: awayAbbrev,
        home: homeAbbrev,
        gameDate: game?.gameDate || '',
        officialDate: game?.officialDate || date || '',
        gameNumber: game?.gameNumber || 1,
      }, date);
      const cached = cachedCards.get(identityKey) || cachedCards.get(gameMatchKey(awayAbbrev, homeAbbrev)) || null;
      const awayColor = cached?.awayColor || getTeamColor(awayAbbrev);
      const homeColor = cached?.homeColor || getTeamColor(homeAbbrev);
      const detail = statusLine(game);
      let derivedLineup = emptyLineupData();
      let derivedPitching = emptyPitchingData();
      let derivedLookup = cached?.playerLookup || {};

      try {
        const rawBox = await getGameBoxscore(game.gamePk);
        const box = normalizeBoxscorePayload(rawBox);
        const derived = buildGameDataFromBoxscore(box, game, {
          awayAbbrev,
          homeAbbrev,
          awayColor,
          homeColor,
        });
        derivedLineup = chooseBetterLineup(derived.lineup, derivedLineup);
        derivedPitching = chooseBetterPitching(pitchingWithLatestBoxscoreSnapshot(derived.pitching, box, []), derivedPitching);
        derivedLookup = { ...derivedLookup, ...derived.playerLookup };
      } catch {}

      let probablePitchers = sanitizeProbablePitchers({
        away: game?.teams?.away?.probablePitcher || cached?.probablePitchers?.away || null,
        home: game?.teams?.home?.probablePitcher || cached?.probablePitchers?.home || null,
      }, { ...game, playerLookup: derivedLookup }, awayAbbrev, homeAbbrev);
      probablePitchers = await resolveOfficialPregameProbablePitchers(
        probablePitchers,
        { ...game, playerLookup: derivedLookup },
        awayAbbrev,
        homeAbbrev,
        officialDateForGame(game, date),
      );

      return {
        ...(cached || {}),
        gamePk: cached?.gamePk || game.gamePk || `${awayAbbrev}${homeAbbrev}`,
        gameDate: game?.gameDate || cached?.gameDate || '',
        officialDate: game?.officialDate || date || cached?.officialDate || '',
        gameNumber: game?.gameNumber || cached?.gameNumber || 1,
        doubleHeader: game?.doubleHeader || cached?.doubleHeader || 'N',
        away: awayAbbrev,
        home: homeAbbrev,
        awayRecord: formatTeamRecord(game?.teams?.away) || cached?.awayRecord || '',
        homeRecord: formatTeamRecord(game?.teams?.home) || cached?.homeRecord || '',
        awayStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.away, null, awayAbbrev) || cached?.awayStreak || '',
        homeStreak: teamStreakForGameTeam(teamStreaks, game?.teams?.home, null, homeAbbrev) || cached?.homeStreak || '',
        awayScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.away?.score ?? cached?.awayScore ?? '-'),
        homeScore: game?.status?.abstractGameState === 'Preview' ? '-' : (game?.teams?.home?.score ?? cached?.homeScore ?? '-'),
        status: detail || cached?.status || 'Unknown',
        inning: /cancel|postpon|suspend|delay|makeup/i.test(detail) ? detail : (cached?.inning || detail),
        inningShort: /cancel|postpon|suspend|delay|makeup/i.test(detail) ? detail : (cached?.inningShort || detail),
        awayColor,
        homeColor,
        awayLogo: cached?.awayLogo || getLogoPath(awayAbbrev),
        homeLogo: cached?.homeLogo || getLogoPath(homeAbbrev),
        awayPitcher: cached?.awayPitcher || '-',
        homePitcher: cached?.homePitcher || '-',
        awayHitter: cached?.awayHitter || '-',
        homeHitter: cached?.homeHitter || '-',
        probablePitchers,
        balls: cached?.balls ?? 0,
        strikes: cached?.strikes ?? 0,
        outs: cached?.outs ?? 0,
        bases: cached?.bases || { first: false, second: false, third: false },
        ticker: cached?.ticker || [],
        lastPlay: firstRealPlayText(cached?.lastPlay, cached?.ticker?.[0]?.text) || defaultPlayText(game),
        currentEvent: cached?.currentEvent || '',
        lineup: lineupCount(cached?.lineup) > 0 ? cached.lineup : derivedLineup,
        pitching: chooseBetterPitching(derivedPitching, cached?.pitching),
        playerLookup: derivedLookup,
      };
    }));

    return dedupeGameCards(cards.map(normalizeCompletedCard), date);
  } catch {
    return [];
  }
}

function currentHomeRunSortLabel() {
  if (homeRunFeedSortMode === 'rating') return 'highest rated first';
  if (homeRunFeedSortMode === 'distance') return 'longest first';
  return 'latest first';
}

function homeRunSortValue(hr) {
  const rating = Number(hr?.rating ?? hr?.ratingBreakdown?.score);
  return Number.isFinite(rating) ? rating : -1;
}

function homeRunDistanceValue(hr) {
  const distance = Number(hr?.distance ?? hr?.ratingBreakdown?.distanceFeet ?? hr?.hit?.distance);
  return Number.isFinite(distance) ? distance : -1;
}

function homeRunGradeLabel(value) {
  const rating = Number(value);
  if (!Number.isFinite(rating)) return '--';
  if (rating < 150) return 'C';
  if (rating < 200) return 'C+';
  if (rating <= 250) return 'B-';
  if (rating < 300) return 'B';
  if (rating <= 350) return 'B+';
  if (rating <= 400) return 'A-';
  if (rating <= 450) return 'A';
  if (rating < 500) return 'A+';
  return 'S';
}

function homeRunRatingDisplayLabel(value) {
  const rating = Number(value);
  if (!Number.isFinite(rating)) return '--';
  return homeRunRatingDisplayMode === 'letter' ? homeRunGradeLabel(rating) : String(Math.round(rating));
}

function sortHomeRunFeedItems(items) {
  return items.slice().sort((a, b) => {
    if (homeRunFeedSortMode === 'rating') {
      return homeRunSortValue(b) - homeRunSortValue(a)
        || (Number(b.eventTimeMs) || 0) - (Number(a.eventTimeMs) || 0)
        || Number(b.gamePk || 0) - Number(a.gamePk || 0)
        || Number(b.order || 0) - Number(a.order || 0);
    }
    if (homeRunFeedSortMode === 'distance') {
      return homeRunDistanceValue(b) - homeRunDistanceValue(a)
        || homeRunSortValue(b) - homeRunSortValue(a)
        || (Number(b.eventTimeMs) || 0) - (Number(a.eventTimeMs) || 0)
        || Number(b.gamePk || 0) - Number(a.gamePk || 0)
        || Number(b.order || 0) - Number(a.order || 0);
    }
    return (Number(b.eventTimeMs) || 0) - (Number(a.eventTimeMs) || 0)
      || Number(b.gamePk || 0) - Number(a.gamePk || 0)
      || Number(b.order || 0) - Number(a.order || 0);
  });
}

function cachedHomeRunsForSelectedDate() {
  try {
    return JSON.parse(localStorage.getItem(storageKey('hrs')) || '[]');
  } catch {
    return [];
  }
}

function abortHomeRunFeedLoading(date = '') {
  homeRunFeedAbortSeq += 1;
  homeRunOnlyRefreshInFlight = false;
  const nextDate = String(date || dateInput?.value || formatDate(new Date()));
  latestRenderedHomeRuns = [];
  latestHomeRunFeedDate = nextDate;
  latestHomeRunFeedSignature = homeRunFeedDataSignature([]);
}

function homeRunFeedLoadIsStale(date = '', token = homeRunFeedAbortSeq) {
  const expectedDate = String(date || '');
  const selectedDate = String(dateInput?.value || formatDate(new Date()));
  return Number(token) !== Number(homeRunFeedAbortSeq) || (expectedDate && selectedDate !== expectedDate);
}

function clearHomeRunFeedForDate(date = '') {
  const nextDate = String(date || dateInput?.value || formatDate(new Date()));
  abortHomeRunFeedLoading(nextDate);
  if (hrListEl) {
    hrListEl.querySelectorAll('.hr-item[data-hr-key]').forEach((item) => item.remove());
    hrListEl.querySelectorAll('.empty').forEach((item) => item.remove());
  }
  renderHomeRunFeed([], { forceClear: true });
}

function homeRunEventPart(value = '') {
  return String(value ?? '').trim().replace(/\s+/g, ' ');
}

function homeRunPositiveInteger(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n < 0) return null;
  return Math.round(n);
}

function homeRunEventKey(hr = {}) {
  const gamePk = homeRunEventPart(hr.gamePk ?? hr.gamePkString ?? hr.gameId ?? '');
  const batter = homeRunEventPart(hr.batterId ?? hr.playerId ?? hr.batter ?? hr.batterName ?? '');
  if (!gamePk || !batter) return '';

  // Use the official at-bat index/order as the primary identity. The same HR can
  // arrive first from progressive game hydration and later from a quiet/full-day
  // refresh with a better event timestamp or HR number. Timestamp-based keys made
  // that look like two separate HRs after a delay. The at-bat index is stable.
  const order = homeRunPositiveInteger(hr.atBatIndex ?? hr.order ?? hr.playIndex ?? hr.about?.atBatIndex);
  if (order !== null) return [gamePk, batter, `ab${order}`].join(':');

  const playId = homeRunEventPart(hr.playId ?? hr.playGuid ?? hr.playEventId ?? hr.guid ?? '');
  if (playId) return [gamePk, batter, `play${playId}`].join(':');

  const hrNo = homeRunPositiveInteger(hr.hrNo ?? hr.homeRunNo ?? hr.number ?? hr.seasonHr ?? hr.seasonHomeRunNo);
  if (hrNo !== null && hrNo > 0) return [gamePk, batter, `hr${hrNo}`].join(':');

  const inning = homeRunEventPart(hr.inningText ?? hr.inning ?? '');
  const pitcher = homeRunEventPart(hr.pitcherId ?? hr.pitcherName ?? '');
  if (inning && pitcher) return [gamePk, batter, `inn${inning}`, `p${pitcher}`].join(':');

  const eventMs = homeRunAudioEventMs(hr);
  if (Number.isFinite(eventMs) && eventMs > 0) return [gamePk, batter, `t${Math.floor(eventMs / 60000)}`].join(':');

  return [gamePk, batter, 'unknown'].join(':');
}

function homeRunAudioStorageKey() {
  try {
    return typeof storageKey === 'function' ? storageKey(HOME_RUN_AUDIO_PLAYED_STORAGE_KEY) : HOME_RUN_AUDIO_PLAYED_STORAGE_KEY;
  } catch {
    return HOME_RUN_AUDIO_PLAYED_STORAGE_KEY;
  }
}

function loadPlayedHomeRunAudioKeys() {
  try {
    const raw = localStorage.getItem(homeRunAudioStorageKey());
    const parsed = JSON.parse(raw || '[]');
    if (Array.isArray(parsed)) return new Set(parsed.filter(Boolean).slice(-500));
    if (parsed && typeof parsed === 'object') return new Set(Object.keys(parsed).filter(Boolean).slice(-500));
  } catch {}
  return new Set();
}

function savePlayedHomeRunAudioKeys(keys = new Set()) {
  try {
    const compact = [...keys].filter(Boolean).slice(-500);
    localStorage.setItem(homeRunAudioStorageKey(), JSON.stringify(compact));
  } catch {}
}

function rememberPlayedHomeRunAudioKey(key = '') {
  if (!key) return;
  const played = loadPlayedHomeRunAudioKeys();
  played.add(key);
  savePlayedHomeRunAudioKeys(played);
}

function homeRunAudioEventMs(hr = {}) {
  const numericCandidates = [
    hr.eventTimeMs,
    hr.eventMs,
    hr.timestampMs,
    hr.playTimeMs,
    hr.timeMs,
  ];
  for (const candidate of numericCandidates) {
    const value = Number(candidate);
    if (Number.isFinite(value) && value > 0) return value;
  }
  const stringCandidates = [
    hr.eventTime,
    hr.endTime,
    hr.startTime,
    hr.timestamp,
    hr.dateTime,
  ];
  for (const candidate of stringCandidates) {
    const value = Date.parse(candidate);
    if (Number.isFinite(value) && value > 0) return value;
  }
  return null;
}

function homeRunAudioWithinWindow(hr = {}, now = Date.now()) {
  const eventMs = homeRunAudioEventMs(hr);
  if (!Number.isFinite(eventMs) || eventMs <= 0) return false;
  return now >= eventMs - 10000 && now - eventMs <= HOME_RUN_AUDIO_WINDOW_MS;
}

function homeRunAudioAlreadyHandled(key = '') {
  if (!key) return true;
  return announcedHomeRunAudioKeys.has(key) || loadPlayedHomeRunAudioKeys().has(key);
}

function playHomeRunAudioForEvent(hr = {}, options = {}) {
  const key = homeRunEventKey(hr);
  if (homeRunAudioAlreadyHandled(key)) return false;
  if (!homeRunAudioWithinWindow(hr)) return false;
  announcedHomeRunAudioKeys.add(key);
  rememberPlayedHomeRunAudioKey(key);
  playHomeRunAudio({ source: options.source || 'home-run-feed' });
  return true;
}

function isFinalLikeHomeRunAudioGame(game = null) {
  const statusText = [
    game?.status,
    game?.statusCode,
    game?.statusDetailedState,
    game?.statusState,
    game?.abstractGameState,
    game?.detailedState,
    game?.inningShort,
    game?.inningState,
  ].map((value) => String(value || '')).join(' ');
  return /\b(final|game\s*over|completed)\b/i.test(statusText);
}

function ensureHomeRunAudio() {
  if (!homeRunAudioEl) {
    homeRunAudioEl = new Audio('homerun.mp3');
    homeRunAudioEl.preload = 'auto';
    homeRunAudioEl.volume = 1;
    homeRunAudioEl.muted = false;
    homeRunAudioEl.setAttribute('playsinline', '');
  }
  return homeRunAudioEl;
}

function ensureHomeRunAudioContext() {
  if (homeRunAudioContext) return homeRunAudioContext;
  const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextCtor) return null;
  try {
    homeRunAudioContext = new AudioContextCtor();
  } catch {
    homeRunAudioContext = null;
  }
  return homeRunAudioContext;
}

function playHomeRunAudioFallbackBeep() {
  const context = ensureHomeRunAudioContext();
  if (!context) return;
  const play = () => {
    try {
      const now = context.currentTime || 0;
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      oscillator.type = 'triangle';
      oscillator.frequency.setValueAtTime(660, now);
      oscillator.frequency.exponentialRampToValueAtTime(990, now + 0.16);
      gain.gain.setValueAtTime(0.0001, now);
      gain.gain.exponentialRampToValueAtTime(0.22, now + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.48);
      oscillator.connect(gain);
      gain.connect(context.destination);
      oscillator.start(now);
      oscillator.stop(now + 0.5);
    } catch {}
  };
  if (context.state === 'suspended') {
    context.resume().then(play).catch(() => {});
  } else {
    play();
  }
}

function drainPendingHomeRunAudioPlays() {
  const count = Math.min(3, Number(pendingHomeRunAudioPlayCount) || 0);
  pendingHomeRunAudioPlayCount = 0;
  for (let i = 0; i < count; i += 1) {
    window.setTimeout(() => playHomeRunAudio({ fromPendingQueue: true }), i * 550);
  }
}

function unlockHomeRunAudio() {
  if (homeRunAudioUnlocked || homeRunAudioUnlockInFlight) return;
  homeRunAudioUnlockInFlight = true;
  try {
    const audio = ensureHomeRunAudio();
    const previousMuted = audio.muted;
    const previousVolume = audio.volume;
    audio.muted = true;
    audio.volume = 0;
    audio.load();
    const unlockPromise = audio.play();
    const finish = (unlocked) => {
      try {
        audio.pause();
        audio.currentTime = 0;
        audio.muted = previousMuted;
        audio.volume = previousVolume || 1;
      } catch {}
      homeRunAudioUnlocked = Boolean(unlocked);
      homeRunAudioUnlockInFlight = false;
      if (homeRunAudioUnlocked) drainPendingHomeRunAudioPlays();
    };
    if (unlockPromise?.then) {
      unlockPromise.then(() => finish(true)).catch(() => finish(false));
    } else {
      finish(true);
    }
  } catch {
    homeRunAudioUnlockInFlight = false;
  }

  const context = ensureHomeRunAudioContext();
  if (context?.state === 'suspended') context.resume().catch(() => {});
}

function initHomeRunAudioUnlock() {
  const unlock = () => unlockHomeRunAudio();
  ['pointerdown', 'mousedown', 'touchstart', 'keydown', 'click'].forEach((eventName) => {
    document.addEventListener(eventName, unlock, { capture: true, passive: true });
  });
}

function playHomeRunAudio(options = {}) {
  const now = Date.now();
  if (!options.fromPendingQueue && now - (lastHomeRunAudioAttemptAt || 0) < 1200) return;
  if (homeRunAudioPlayInFlight) return;
  lastHomeRunAudioAttemptAt = now;
  homeRunAudioPlayInFlight = true;
  if (!homeRunAudioUnlocked) unlockHomeRunAudio();

  try {
    const audio = ensureHomeRunAudio();
    audio.muted = false;
    audio.volume = 1;
    audio.currentTime = 0;
    const playPromise = audio.play();
    if (playPromise?.then) {
      playPromise
        .then(() => {
          homeRunAudioUnlocked = true;
        })
        .catch(() => {
          playHomeRunAudioFallbackBeep();
        })
        .finally(() => {
          homeRunAudioPlayInFlight = false;
        });
    } else {
      homeRunAudioUnlocked = true;
      homeRunAudioPlayInFlight = false;
    }
  } catch {
    playHomeRunAudioFallbackBeep();
    homeRunAudioPlayInFlight = false;
  }
}

function resetHomeRunAudioAlerts() {
  homeRunAudioPrimed = false;
  announcedHomeRunAudioKeys = loadPlayedHomeRunAudioKeys();
  announcedScoreboardHomeRunAudioKeys = new Set();
}

function syncHomeRunAudioAlerts(homeRuns = []) {
  const events = listify(homeRuns)
    .map((hr) => ({ hr, key: homeRunEventKey(hr) }))
    .filter((item) => item.key);
  const played = loadPlayedHomeRunAudioKeys();

  if (!homeRunAudioPrimed) {
    announcedHomeRunAudioKeys = new Set([...played, ...events.map((item) => item.key)]);
    homeRunAudioPrimed = true;
    return;
  }

  const candidates = events.filter((item) => !announcedHomeRunAudioKeys.has(item.key) && !played.has(item.key));
  events.forEach((item) => announcedHomeRunAudioKeys.add(item.key));
  const playable = candidates.find((item) => homeRunAudioWithinWindow(item.hr));
  if (!playable) return;

  rememberPlayedHomeRunAudioKey(playable.key);
  playHomeRunAudio({ source: 'home-run-feed' });
}

function maybePlayScoreboardHomeRunAudio(game = null, side = '', signature = '') {
  if (isFinalLikeHomeRunAudioGame(game)) return;
  const text = `${game?.currentEvent || ''} ${game?.lastPlay || ''}`;
  if (!/home\s*run|homerun|\bhr\b/i.test(text)) return;

  const gamePk = String(game?.gamePk || '');
  const matchingHomeRun = currentHomeRunFeedItems()
    .find((hr) => String(hr?.gamePk || '') === gamePk && homeRunAudioWithinWindow(hr) && !homeRunAudioAlreadyHandled(homeRunEventKey(hr)));
  if (!matchingHomeRun) return;

  const key = homeRunEventKey(matchingHomeRun);
  const scoreboardKey = [activeScoreboardDateKey(), gamePk, side || '', signature || key].join(':');
  if (announcedScoreboardHomeRunAudioKeys.has(scoreboardKey)) return;
  announcedScoreboardHomeRunAudioKeys.add(scoreboardKey);
  playHomeRunAudioForEvent(matchingHomeRun, { source: 'scoreboard' });
}

function currentHomeRunFeedItems(homeRuns = []) {
  const incoming = Array.isArray(homeRuns) ? homeRuns.slice() : [];
  if (incoming.length) return incoming;
  if (latestRenderedHomeRuns.length) return latestRenderedHomeRuns.slice();
  return cachedHomeRunsForSelectedDate();
}

function homeRunFeedHasVisibleItems() {
  return Boolean(hrListEl?.querySelector?.('.hr-item[data-hr-key]'));
}

function mergeHomeRunItemData(previous = {}, incoming = {}) {
  const merged = { ...(previous || {}), ...(incoming || {}) };
  const preserveKeys = [
    'batter', 'resultLabel', 'hrNo', 'distance', 'hit', 'pitcherId', 'pitcherName',
    'pitcherHand', 'pitcherHrAllowed', 'pitchDetailLine', 'eventTimeMs', 'eventTimeEt',
    'inningText', 'rating', 'ratingBreakdown', 'teamAbbr', 'teamColor', 'teamLogo',
    'homeAbbr', 'order', 'atBatIndex', 'playId',
  ];
  for (const key of preserveKeys) {
    const nextValue = merged[key];
    const prevValue = previous?.[key];
    if ((nextValue === null || nextValue === undefined || nextValue === '')
      && prevValue !== null && prevValue !== undefined && prevValue !== '') {
      merged[key] = prevValue;
    }
  }
  return merged;
}

function mergeHomeRunFeedItems(existing = [], incoming = []) {
  const map = new Map();
  const add = (hr, preferIncoming = false) => {
    if (!hr) return;
    const key = homeRunEventKey(hr);
    if (!key) return;
    const previous = map.get(key);
    if (!previous) {
      map.set(key, hr);
      return;
    }
    map.set(key, preferIncoming ? mergeHomeRunItemData(previous, hr) : mergeHomeRunItemData(hr, previous));
  };
  listify(existing).forEach((hr) => add(hr, false));
  listify(incoming).forEach((hr) => add(hr, true));
  return sortHomeRunFeedItems(Array.from(map.values()));
}

function markPanelItemUpdated(item, color = '#66d9ff') {
  if (!item) return;
  item.style.setProperty('--panel-update-rgb', hexToRgb(color || '#66d9ff'));
  item.classList.remove('panel-item-updated');
  void item.offsetWidth;
  item.classList.add('panel-item-updated');
  window.setTimeout(() => item.classList.remove('panel-item-updated'), 1200);
}


function playerStatLoadingDotsHtml(label = 'Loading') {
  const safeLabel = escapeHtml(label || 'Loading');
  return `<span class="player-stat-loading-dots" aria-label="${safeLabel}" title="${safeLabel}"><i></i><i></i><i></i></span>`;
}

function initPanelScrollPerformance() {
  for (const listEl of [playerTrackerListEl, hrListEl]) {
    if (!listEl || listEl.dataset.scrollPerfBound === '1') continue;
    listEl.dataset.scrollPerfBound = '1';
    let scrollTimer = 0;
    listEl.addEventListener('scroll', () => {
      listEl.classList.add('is-scrolling');
      window.clearTimeout(scrollTimer);
      scrollTimer = window.setTimeout(() => {
        listEl.classList.remove('is-scrolling');
      }, 150);
    }, { passive: true });
  }
}

function refreshHomeRunFeedAfterControlChange() {
  if (hrRatingDialogEl) hrRatingDialogEl.hidden = true;
  renderHomeRunFeed(latestRenderedHomeRuns);
  if (!latestRenderedHomeRuns.length && !cachedHomeRunsForSelectedDate().length && !loadGamesInFlight) {
    loadGames({ invalidate: true });
  }
}


function homeRunFeedDataSignature(homeRuns = []) {
  const source = Array.isArray(homeRuns) ? homeRuns.slice() : [];
  return JSON.stringify(sortHomeRunFeedItems(source).map((hr) => [
    homeRunEventKey(hr),
    hr.batter || '',
    hr.resultLabel || '',
    hr.rating ?? hr.ratingBreakdown?.score ?? '',
    hr.distance || '',
    hr.eventTimeEt || '',
    hr.inningText || '',
    hr.pitcherName || '',
    hr.pitchDetailLine || '',
    hr.homeAbbr || '',
    hr.teamAbbr || '',
  ]));
}

function updateHomeRunFeedIfChanged(homeRuns = [], options = {}) {
  const selectedDate = String(options.date || dateInput?.value || formatDate(new Date()));
  if (!options.allowStaleDate && homeRunFeedLoadIsStale(selectedDate, options.homeRunAbortToken ?? homeRunFeedAbortSeq)) return false;
  const incoming = Array.isArray(homeRuns) ? homeRuns.slice() : [];
  const sameDate = latestHomeRunFeedDate === selectedDate || !latestHomeRunFeedDate;
  const cached = cachedHomeRunsForSelectedDate();
  const retained = sameDate ? mergeHomeRunFeedItems(cached, latestRenderedHomeRuns) : [];
  const hasExistingFeed = retained.length > 0 || homeRunFeedHasVisibleItems();

  if (options.forceClear) {
    latestHomeRunFeedDate = selectedDate;
    latestHomeRunFeedSignature = homeRunFeedDataSignature(incoming);
    latestRenderedHomeRuns = incoming;
    renderHomeRunFeed(incoming, { forceClear: true });
    return true;
  }

  // Same-date focus/tab/menu refreshes can legitimately return an empty or partial HR payload.
  // Empty means "no reliable update", not "clear the feed" unless forceClear/date change says so.
  if (!incoming.length && hasExistingFeed) {
    latestHomeRunFeedDate = selectedDate;
    latestRenderedHomeRuns = retained;
    latestHomeRunFeedSignature = homeRunFeedDataSignature(retained);
    syncHomeRunAudioAlerts(retained);
    if (!homeRunFeedHasVisibleItems() && retained.length) renderHomeRunFeed(retained);
    return false;
  }

  const nextHomeRuns = incoming.length && sameDate && !options.replace
    ? mergeHomeRunFeedItems(retained, incoming)
    : incoming;
  if (!nextHomeRuns.length && !options.allowEmpty && hasExistingFeed) return false;

  const signature = homeRunFeedDataSignature(nextHomeRuns);
  const domNeedsRestore = Boolean(nextHomeRuns.length && !homeRunFeedHasVisibleItems());
  if (!options.force && !domNeedsRestore && latestHomeRunFeedDate === selectedDate && latestHomeRunFeedSignature === signature) return false;

  latestHomeRunFeedDate = selectedDate;
  latestHomeRunFeedSignature = signature;
  latestRenderedHomeRuns = nextHomeRuns;
  syncHomeRunAudioAlerts(nextHomeRuns);
  renderHomeRunFeed(nextHomeRuns);
  return true;
}


async function refreshHomeRunFeedOnlyQuiet(options = {}) {
  const selectedDate = String(options.date || dateInput?.value || formatDate(new Date()));
  if (!selectedDate) return false;
  const homeRunAbortToken = homeRunFeedAbortSeq;
  const now = Date.now();
  const minGap = Number(options.minGapMs) || 25000;
  if (homeRunOnlyRefreshInFlight) return false;
  if (!options.force && now - (lastHomeRunOnlyRefreshAt || 0) < minGap) return false;
  homeRunOnlyRefreshInFlight = true;
  lastHomeRunOnlyRefreshAt = now;
  try {
    const result = await fetchGamesAndHomeRuns(selectedDate, {
      suppressScheduleSeeds: true,
      suppressProgressiveHrFeed: true,
      skipDaySideEffects: true,
      homeRunAbortToken,
    });
    if (homeRunFeedLoadIsStale(selectedDate, homeRunAbortToken)) return false;
    return updateHomeRunFeedIfChanged(result?.homeRuns || [], {
      date: selectedDate,
      allowEmpty: false,
      homeRunAbortToken,
    });
  } catch {
    return false;
  } finally {
    homeRunOnlyRefreshInFlight = false;
  }
}

function renderHomeRunFeed(homeRuns, options = {}) {
  const explicitEmptyInput = Array.isArray(homeRuns) && homeRuns.length === 0;
  const hasVisibleHrItems = homeRunFeedHasVisibleItems();
  if (explicitEmptyInput && hasVisibleHrItems && !options.forceClear && !latestRenderedHomeRuns.length) return;
  if (hrSortToggleBtnEl) hrSortToggleBtnEl.textContent = currentHomeRunSortLabel();
  if (hrGradeToggleBtnEl) hrGradeToggleBtnEl.textContent = homeRunRatingDisplayMode === 'letter' ? 'letter' : 'number';
  const list = options.forceClear ? [] : mergeHomeRunFeedItems([], currentHomeRunFeedItems(homeRuns));
  const seen = new Set();
  const hadHrItems = Boolean(hrListEl.querySelector('.hr-item[data-hr-key]'));
  for (const hr of list) {
    const key = homeRunEventKey(hr);
    seen.add(key);
    let item = hrListEl.querySelector(`.hr-item[data-hr-key="${cssEscape(key)}"]`);
    const existed = Boolean(item);
    if (!item) {
      item = document.createElement('div');
      item.className = 'panel-item hr-item';
      item.dataset.hrKey = key;
      item.innerHTML = `
        <img class="hr-logo" src="placeholder.png" alt="team" />
        <div class="hr-copy">
          <div class="hr-name"></div>
          <div class="hr-meta"></div>
        </div>
        <div class="hr-rating" title="1000-point Home Run Rating"></div>
      `;
      const img = item.querySelector('img');
      img.onerror = () => {
        img.onerror = null;
        img.src = 'placeholder.png';
      };
    }
    const renderFingerprint = JSON.stringify([
      hr.batter || '',
      hr.resultLabel || '',
      hr.rating ?? hr.ratingBreakdown?.score ?? '',
      hr.distance || '',
      hr.eventTimeEt || '',
      hr.inningText || '',
      hr.pitcherName || '',
      hr.pitchDetailLine || '',
      hr.homeAbbr || '',
      hr.hit?.key || '',
    ]);
    const changed = (existed && item.dataset.renderFingerprint && item.dataset.renderFingerprint !== renderFingerprint)
      || (!existed && hadHrItems);
    item.dataset.renderFingerprint = renderFingerprint;
    item.dataset.gamePk = String(hr.gamePk ?? '');
    item.dataset.playerId = String(hr.batterId ?? '');
    const isWalkOff = Number(hr?.ratingBreakdown?.walkOff || 0) > 0;
    item.classList.toggle('hr-item-walkoff', isWalkOff);
    item.dataset.hr = JSON.stringify({
      batter: hr.batter || 'Unknown',
      resultLabel: hr.resultLabel || 'Homerun',
      rating: hr.rating ?? hr.ratingBreakdown?.score ?? null,
      ratingBreakdown: hr.ratingBreakdown || null,
      distance: hr.distance || null,
      hit: hr.hit || null,
      inningText: hr.inningText || '',
      pitcherName: hr.pitcherName || '',
      pitcherHand: hr.pitcherHand || '',
      pitchDetailLine: hr.pitchDetailLine || '',
      gamePk: hr.gamePk || null,
      atBatIndex: hr.atBatIndex ?? hr.order ?? null,
      homeAbbr: hr.homeAbbr || '',
      teamAbbr: hr.teamAbbr || '',
      teamColor: hr.teamColor || '',
      teamLogo: hr.teamLogo || '',
    });
    item.style.setProperty('--hr-team-color', hr.teamColor || '#66d9ff');
    item.style.setProperty('--hr-team-rgb', hexToRgb(hr.teamColor || '#66d9ff'));
    const img = item.querySelector('.hr-logo');
    if (img && img.dataset.src !== String(hr.teamLogo || 'placeholder.png')) {
      img.dataset.src = String(hr.teamLogo || 'placeholder.png');
      img.src = img.dataset.src;
    }
    if (img) img.alt = `${hr.teamAbbr || 'team'} logo`;
    const nameEl = item.querySelector('.hr-name');
    if (nameEl) {
      nameEl.textContent = `${hr.batter || 'Unknown'} ${hr.resultLabel || 'Homerun'}`;
      nameEl.style.color = hr.teamColor || '#dbebff';
    }
    const metaEl = item.querySelector('.hr-meta');
    if (metaEl) {
      const hrBits = [
        hr.hrNo ? `${ordinalNumber(hr.hrNo)} HR of season` : 'Season HR #?',
        hr.distance ? `${hr.distance} ft` : '',
        hr.eventTimeEt ? `${hr.eventTimeEt} EST${hr.inningText ? ` | ${hr.inningText}` : ''}` : (hr.inningText || ''),
      ].filter(Boolean);
      const pitcherBits = [
        hr.pitcherName ? `${hr.pitcherName} (${hr.pitcherHand || '-'})` : '',
        Number.isFinite(Number(hr.pitcherHrAllowed)) ? `HR allowed #${Number(hr.pitcherHrAllowed)}` : '',
      ].filter(Boolean);
      const lines = [
        hrBits.join(' | '),
        pitcherBits.join(' | '),
        hr.pitchDetailLine || '',
      ].filter(Boolean);
      metaEl.textContent = lines.join('\n');
    }
    const ratingEl = item.querySelector('.hr-rating');
    if (ratingEl) {
      const rating = Number(hr.rating);
      ratingEl.textContent = homeRunRatingDisplayLabel(rating);
      ratingEl.title = 'Click for Home Run Rating breakdown';
    }
    if (changed) markPanelItemUpdated(item, hr.teamColor || '#66d9ff');
    hrListEl.appendChild(item);
  }
  for (const item of Array.from(hrListEl.querySelectorAll('.hr-item[data-hr-key]'))) {
    if (!seen.has(item.dataset.hrKey)) item.remove();
  }
}

function currentLeaderTeamSelection() {
  const option = leadersTeamSelectEl?.selectedOptions?.[0] || null;
  return {
    teamId: leadersTeamSelectEl?.value || '',
    teamAbbrev: option?.dataset.abbrev || '',
    teamName: option?.dataset.name || option?.textContent || 'MLB',
  };
}

function selectedLeaderMatchup(games = latestRenderedGames) {
  const { teamAbbrev } = currentLeaderTeamSelection();
  if (!teamAbbrev) return null;
  const team = String(teamAbbrev || '').toUpperCase();
  return games.find((game) => String(game.away).toUpperCase() === team || String(game.home).toUpperCase() === team) || null;
}

function currentFilteredTeamAbbrevs(games = latestRenderedGames) {
  const { teamAbbrev } = currentLeaderTeamSelection();
  const selected = String(teamAbbrev || '').toUpperCase();
  if (!selected) return [];
  if (!currentLeadersOpponentMode) return [selected];
  const matchup = selectedLeaderMatchup(games);
  if (!matchup) return [selected];
  return [String(matchup.away || '').toUpperCase(), String(matchup.home || '').toUpperCase()].filter(Boolean);
}

function currentFilteredTeamIds(games = latestRenderedGames) {
  const teamAbbrevs = currentFilteredTeamAbbrevs(games);
  if (!teamAbbrevs.length) {
    const { teamId } = currentLeaderTeamSelection();
    return teamId ? [Number(teamId)].filter((value) => Number.isFinite(value) && value > 0) : [];
  }
  return teamAbbrevs
    .map((abbrev) => latestLeaderTeams.find((team) => String(team.abbreviation).toUpperCase() === abbrev)?.id)
    .filter((value) => Number.isFinite(Number(value)) && Number(value) > 0)
    .map(Number);
}

function currentFocusedGame(games = latestRenderedGames) {
  if (focusedGamePk === null) return null;
  return games.find((game) => String(game?.gamePk) === String(focusedGamePk))
    || getCachedGames().find((game) => String(game?.gamePk) === String(focusedGamePk))
    || null;
}

function gameMatchesCurrentFilter(game, games = latestRenderedGames) {
  const teams = currentFilteredTeamAbbrevs(games);
  if (!teams.length) return true;
  return teams.includes(String(game?.away || '').toUpperCase()) || teams.includes(String(game?.home || '').toUpperCase());
}

function leaderContextSummary() {
  const date = dateInput.value || formatDate(new Date());
  const season = seasonForDate(date);
  const { teamAbbrev } = currentLeaderTeamSelection();
  const matchup = selectedLeaderMatchup(latestRenderedGames);
  const range = selectedLeaderDateRange();
  const rangeText = leaderDateRangeIsSeason(range) ? String(season) : range.label;
  const qualifierText = selectedLeaderQualifierMode() === 'all'
    ? ' | all samples'
    : leaderDateRangeIsSeason(range)
      ? ' | rate min: 2x team games PA, 1x team games IP'
      : ' | rate min: range activity';
  if (currentOverlayPage === 'hot') {
    if (currentLeadersOpponentMode && matchup) return `${displayTeamAbbrev(matchup.away)} vs ${displayTeamAbbrev(matchup.home)} hot hitters | last 7 days`;
    if (teamAbbrev) return `${displayTeamAbbrev(teamAbbrev)} hot hitters | last 7 days`;
    return `MLB hot hitters | last 7 days`;
  }
  if (currentOverlayPage === 'teamStats') {
    if (currentLeadersOpponentMode && matchup) return `${displayTeamAbbrev(matchup.away)} vs ${displayTeamAbbrev(matchup.home)} team stats | ${season}`;
    if (teamAbbrev) return `${displayTeamAbbrev(teamAbbrev)} team stats | ${season}`;
    return `MLB team stats | ${season}`;
  }
  if (currentOverlayPage === 'predictions') {
    const tab = currentPredictionTab === 'moneylines' ? 'moneylines' : `${currentPredictionTab} predictions`;
    if (currentLeadersOpponentMode && matchup) return `${displayTeamAbbrev(matchup.away)} vs ${displayTeamAbbrev(matchup.home)} ${tab} | ${formatLeadersDateLabel(date)}`;
    if (teamAbbrev) return `${displayTeamAbbrev(teamAbbrev)} ${tab} | ${formatLeadersDateLabel(date)}`;
    return `MLB ${tab} | ${formatLeadersDateLabel(date)}`;
  }
  if (currentOverlayPage === 'hrLeaderboard') {
    return `Playoff picture | ${season} | 12-team format`;
  }
  const positionText = selectedLeaderPosition() ? ` | ${selectedLeaderPosition()}` : '';
  if (currentLeadersOpponentMode && matchup) return `${displayTeamAbbrev(matchup.away)} vs ${displayTeamAbbrev(matchup.home)} leaders | ${rangeText}${positionText}${qualifierText}`;
  if (teamAbbrev) return `${displayTeamAbbrev(teamAbbrev)} leaders | ${rangeText}${positionText}${qualifierText}`;
  return `MLB leaders | ${rangeText}${positionText}${qualifierText}`;
}

function updateLeadersContext() {
  if (!leadersContextEl) return;
  leadersContextEl.textContent = leaderContextSummary();
}

function overlayPageLabel(page) {
  switch (page) {
    case 'leaders': return 'Leaders';
    case 'hot': return 'Hot Players';
    case 'teamStats': return 'Team Stats';
    case 'predictions': return 'Predictions';
    case 'hrLeaderboard': return 'Playoff Picture';
    default: return 'Scoreboard';
  }
}

function hrBreakdownRowsHtml(breakdown) {
  const rows = [
    ['Walk-off', breakdown?.walkOff],
    ['Inning', breakdown?.inning],
    ['Result', breakdown?.result],
    ['Runs', breakdown?.runs],
    ['Pitcher Difficulty', breakdown?.pitcher],
    ['Distance', breakdown?.distance],
  ];
  return rows.map(([label, value]) => `
    <div class="hr-rating-row">
      <span>${escapeHtml(label)}</span>
      <strong>${Number.isFinite(Number(value)) ? Math.round(Number(value)) : '--'}</strong>
    </div>
  `).join('');
}

function homeRunRatingDesktopVisualEnabled() {
  return Boolean(window.matchMedia?.('(min-width: 900px) and (hover: hover) and (pointer: fine)').matches);
}

function homeRunDialogGame(data = {}, item = null) {
  const gamePk = String(data?.gamePk || item?.dataset?.gamePk || '');
  return latestRenderedGames.find((game) => String(game?.gamePk) === gamePk)
    || getCachedGames().find((game) => String(game?.gamePk) === gamePk)
    || { home: data?.homeAbbr || '', homeColor: data?.teamColor || getTeamColor(data?.teamAbbr) };
}

function homeRunMiniDefsId(data = {}, item = null, suffix = '') {
  const raw = `${data?.gamePk || item?.dataset?.hrKey || 'hr'}-${suffix}`;
  return `hrMini${String(raw).replace(/[^a-zA-Z0-9_-]/g, '') || 'Field'}`;
}

function homeRunMiniGeometryHtml(model, defsId) {
  const wallPoints = model.wall.map((entry) => entry.point);
  const warningPoints = model.warningTrack.map((entry) => entry.point);
  const wallLine = wallPoints.map(liveLabPointAttr).join(' L ');
  const warningLine = [...warningPoints].reverse().map(liveLabPointAttr).join(' L ');
  const trackPath = `M ${wallLine} L ${warningLine} Z`;
  const infieldGrass = [model.home, model.first, model.second, model.third];
  const basePath = [model.home, model.first, model.second, model.third, model.home];
  const wallFaces = model.wall.slice(0, -1).map((entry, index) => {
    const next = model.wall[index + 1];
    const entryLift = liveLabWallHeightPx(entry.height);
    const nextLift = liveLabWallHeightPx(next.height);
    const topA = { x: entry.point.x, y: entry.point.y - entryLift };
    const topB = { x: next.point.x, y: next.point.y - nextLift };
    const maxHeight = Math.max(entry.height || 0, next.height || 0);
    return `
      <polygon class="live-lab-svg-wall-face" points="${[
        entry.point,
        next.point,
        topB,
        topA,
      ].map(liveLabPointAttr).join(' ')}" fill="${liveLabWallFaceFill(maxHeight)}" />
      <line class="live-lab-svg-wall-top" x1="${topA.x.toFixed(1)}" y1="${topA.y.toFixed(1)}" x2="${topB.x.toFixed(1)}" y2="${topB.y.toFixed(1)}" />
    `;
  }).join('');
  const wallSegments = model.wall.slice(0, -1).map((entry, index) => {
    const next = model.wall[index + 1];
    const stroke = liveLabWallStroke(Math.max(entry.height || 0, next.height || 0));
    const width = Math.max(3, Math.min(7, ((entry.height || next.height || 8) / 7) + 2));
    return `<line class="live-lab-svg-wall-segment" x1="${entry.point.x.toFixed(1)}" y1="${entry.point.y.toFixed(1)}" x2="${next.point.x.toFixed(1)}" y2="${next.point.y.toFixed(1)}" stroke="${stroke}" stroke-width="${width.toFixed(1)}" />`;
  }).join('');
  const bases = [model.first, model.second, model.third, model.home].map((point) => `
    <g class="live-lab-svg-base-group" transform="translate(${point.x.toFixed(1)} ${point.y.toFixed(1)})">
      <rect class="live-lab-svg-base" x="-7" y="-7" width="14" height="14" transform="rotate(45)" />
    </g>
  `).join('');
  return `
    <defs>
      <pattern id="${defsId}MowPattern" width="70" height="720" patternUnits="userSpaceOnUse" patternTransform="rotate(10 500 650)">
        <rect width="35" height="720" fill="#ffffff" opacity="0.035" />
        <rect x="35" width="35" height="720" fill="#000000" opacity="0.035" />
      </pattern>
      <radialGradient id="${defsId}InfieldGrassGradient" cx="50%" cy="78%" r="62%">
        <stop offset="0%" stop-color="#2f7a49" stop-opacity="0.98" />
        <stop offset="100%" stop-color="#1b5735" stop-opacity="0.96" />
      </radialGradient>
    </defs>
    <path class="live-lab-svg-outfield" d="M ${liveLabPointAttr(model.home)} L ${wallLine} Z" />
    <path class="live-lab-svg-outfield-mow" style="fill:url(#${defsId}MowPattern)" d="M ${liveLabPointAttr(model.home)} L ${wallLine} Z" />
    <path class="live-lab-svg-warning-track" d="${trackPath}" />
    ${wallFaces}
    ${wallSegments}
    <path class="live-lab-svg-foul" d="M ${liveLabPointAttr(model.home)} L ${liveLabPointAttr(model.wall[0].point)}" />
    <path class="live-lab-svg-foul" d="M ${liveLabPointAttr(model.home)} L ${liveLabPointAttr(model.wall[model.wall.length - 1].point)}" />
    <polygon class="live-lab-svg-infield-grass" style="fill:url(#${defsId}InfieldGrassGradient)" points="${infieldGrass.map(liveLabPointAttr).join(' ')}" />
    <polyline class="live-lab-svg-basepath" points="${basePath.map(liveLabPointAttr).join(' ')}" />
    <circle class="live-lab-svg-mound-dirt" cx="${model.mound.x.toFixed(1)}" cy="${model.mound.y.toFixed(1)}" r="${(9 * LIVE_LAB_FIELD_SCALE).toFixed(1)}" />
    <rect class="live-lab-svg-rubber" x="${(model.mound.x - 10).toFixed(1)}" y="${(model.mound.y - 3).toFixed(1)}" width="20" height="6" rx="1.5" />
    <path class="live-lab-svg-home-dirt" d="M ${liveLabPointAttr(liveLabPoint(-45, 18))} Q ${LIVE_LAB_FIELD_CENTER.x},${LIVE_LAB_FIELD_CENTER.y + 22} ${liveLabPointAttr(liveLabPoint(45, 18))} Q ${LIVE_LAB_FIELD_CENTER.x},${LIVE_LAB_FIELD_CENTER.y - 12} ${liveLabPointAttr(liveLabPoint(-45, 18))}" />
    ${bases}
  `;
}

function homeRunMiniHit(data = {}) {
  const hit = data?.hit && typeof data.hit === 'object' ? data.hit : {};
  const distance = Number(hit.distance ?? data?.distance ?? data?.ratingBreakdown?.distanceFeet);
  const sprayAngle = Number(hit.sprayAngle ?? data?.sprayAngle);
  const launchAngle = Number(hit.launchAngle);
  const apex = Number(hit.apex);
  return {
    distance: Number.isFinite(distance) ? distance : 390,
    sprayAngle: Number.isFinite(sprayAngle) ? sprayAngle : 0,
    apex: Number.isFinite(apex) ? apex : Math.max(24, Math.min(48, 24 + Math.max(0, Number.isFinite(launchAngle) ? launchAngle : 24) * 0.55)),
  };
}

function homeRunVisualHtml(data = {}, item = null) {
  const game = homeRunDialogGame(data, item);
  const model = liveLabFieldModel({ ...game, home: data?.homeAbbr || game?.home || '' });
  const defsId = homeRunMiniDefsId(data, item, 'visual');
  const hit = homeRunMiniHit(data);
  const distance = Math.max(30, Math.min(470, hit.distance));
  const end = liveLabPoint(hit.sprayAngle || 0, distance);
  const control = {
    x: model.home.x + ((end.x - model.home.x) * 0.5),
    y: Math.min(model.home.y, end.y) - Math.max(38, hit.apex * 2.2),
  };
  const path = `M ${liveLabPointAttr(model.home)} Q ${liveLabPointAttr(control)} ${liveLabPointAttr(end)}`;
  const teamColor = data?.teamColor || getTeamColor(data?.teamAbbr) || '#ffd166';
  const parkLabel = model.ballpark?.name || displayTeamAbbrev(data?.homeAbbr || game?.home || 'MLB');
  const distanceLabel = Number.isFinite(hit.distance) ? `${Math.round(hit.distance)} FT` : '-- FT';
  return `
    <div class="hr-visual-mini" style="--hr-visual-team:${escapeHtml(teamColor)};--hr-visual-team-rgb:${hexToRgb(teamColor)}">
      <div class="hr-visual-field">
        <svg class="live-lab-field-svg hr-visual-svg" viewBox="-50 95 1100 595" role="img" aria-label="Home run visual">
          <g>${homeRunMiniGeometryHtml(model, defsId)}</g>
          <g class="live-lab-replay-contact is-hr hr-visual-trace" style="--replay-trace-duration:1.45s">
            <path pathLength="100" d="${path}" />
            <circle class="live-lab-replay-ball" r="6.4">
              <animateMotion dur="1.45s" fill="freeze" path="${path}" />
            </circle>
            <circle class="live-lab-replay-landing" cx="${end.x.toFixed(1)}" cy="${end.y.toFixed(1)}" r="11" />
            <text class="live-lab-replay-distance-label" x="${end.x.toFixed(1)}" y="${(end.y - 22).toFixed(1)}">${escapeHtml(distanceLabel)}</text>
          </g>
        </svg>
      </div>
      <div class="hr-visual-caption">
        <strong>${escapeHtml(data?.batter || 'Home Run')}</strong>
        <span>${escapeHtml(`${parkLabel} | ${distanceLabel}`)}</span>
      </div>
    </div>
  `;
}

function homeRunGradingHtml(breakdown, pitcherContext = '') {
  return breakdown
    ? `<div class="hr-rating-rows">${hrBreakdownRowsHtml(breakdown)}</div>${pitcherContext}`
    : '<p class="hr-rating-note">Breakdown unavailable for this cached home run. New home runs will include the full scoring detail.</p>';
}

function openHomeRunRatingDialogFromItem(item) {
  if (!hrRatingDialogEl || !item) return;
  let data = null;
  try {
    data = JSON.parse(item.dataset.hr || '{}');
  } catch {
    data = null;
  }
  const breakdown = data?.ratingBreakdown || null;
  const score = Number(data?.rating ?? breakdown?.score);
  const detailBits = [];
  if (breakdown?.inningText || data?.inningText) detailBits.push(breakdown?.inningText || data.inningText);
  if (Number.isFinite(Number(breakdown?.runsScored))) detailBits.push(`${breakdown.runsScored} run${Number(breakdown.runsScored) === 1 ? '' : 's'}`);
  if (Number.isFinite(Number(breakdown?.distanceFeet ?? data?.distance))) detailBits.push(`${Number(breakdown?.distanceFeet ?? data.distance)} ft`);
  if (data?.pitcherName) detailBits.push(`${data.pitcherName}${data.pitcherHand ? ` (${data.pitcherHand})` : ''}`);
  const pitcherContext = breakdown && Number.isFinite(Number(breakdown.pitcherHr9))
    ? `<p class="hr-rating-note">Pitcher difficulty used ${Number(breakdown.pitcherHr9).toFixed(2)} HR/9 over ${Number(breakdown.pitcherIp || 0).toFixed(1)} IP (${Math.round(Number(breakdown.pitcherBase || 0))} base x ${Number(breakdown.pitcherMultiplier || 0).toFixed(2)} reliability).</p>`
    : '';
  const gradingHtml = homeRunGradingHtml(breakdown, pitcherContext);
  const visualEnabled = homeRunRatingDesktopVisualEnabled();
  const dialogColor = data?.teamColor || getTeamColor(data?.teamAbbr) || '#66d9ff';
  hrRatingDialogEl.style.setProperty('--hr-visual-team', dialogColor);
  hrRatingDialogEl.style.setProperty('--hr-visual-team-rgb', hexToRgb(dialogColor));
  hrRatingDialogEl.innerHTML = `
    ${visualEnabled ? `
      <div class="hr-rating-tabs" role="tablist" aria-label="Home run detail tabs">
        <button type="button" class="active" data-hr-rating-tab="visual" role="tab" aria-selected="true">Visual</button>
        <button type="button" data-hr-rating-tab="grading" role="tab" aria-selected="false">Grading</button>
      </div>
    ` : ''}
    <button type="button" class="hr-rating-close" aria-label="Close home run rating breakdown">x</button>
    <header>
      <strong>${Number.isFinite(score) ? Math.round(score) : '--'}</strong>
      <div>
        <div class="hr-rating-title">${escapeHtml(data?.batter || 'Home Run')} ${escapeHtml(data?.resultLabel || '')}</div>
        <div class="hr-rating-subtitle">${escapeHtml(detailBits.join(' | ') || 'Rating breakdown')}</div>
      </div>
    </header>
    ${visualEnabled ? `
      <section class="hr-rating-tab-panel" data-hr-rating-panel="visual" role="tabpanel">
        ${homeRunVisualHtml(data, item)}
      </section>
      <section class="hr-rating-tab-panel" data-hr-rating-panel="grading" role="tabpanel" hidden>
        ${gradingHtml}
      </section>
    ` : gradingHtml}
  `;
  hrRatingDialogEl.hidden = false;
  hrRatingDialogEl.querySelector('.hr-rating-close')?.addEventListener('click', () => {
    hrRatingDialogEl.hidden = true;
  }, { once: true });
  hrRatingDialogEl.querySelectorAll('[data-hr-rating-tab]').forEach((button) => {
    button.addEventListener('click', () => {
      const tab = button.dataset.hrRatingTab || 'visual';
      hrRatingDialogEl.querySelectorAll('[data-hr-rating-tab]').forEach((tabButton) => {
        const active = tabButton.dataset.hrRatingTab === tab;
        tabButton.classList.toggle('active', active);
        tabButton.setAttribute('aria-selected', active ? 'true' : 'false');
      });
      hrRatingDialogEl.querySelectorAll('[data-hr-rating-panel]').forEach((panel) => {
        panel.hidden = panel.dataset.hrRatingPanel !== tab;
      });
    });
  });
}

function parseHrStorageDate(key = '') {
  const match = String(key).match(/^hrs:(\d{4}-\d{2}-\d{2})$/);
  return match ? match[1] : '';
}

function hrLoadedStorageKey(date) {
  return `hrs-loaded:${date}`;
}

function hrLeaderboardDateRange(period = hrLeaderboardPeriod) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const selectedMs = Date.parse(`${selectedDate}T12:00:00`);
  if (!Number.isFinite(selectedMs)) return [];
  const selectedYear = seasonForDate(selectedDate);
  const startMs = period === 'week'
    ? selectedMs - (6 * 24 * 60 * 60 * 1000)
    : period === 'month'
      ? selectedMs - (30 * 24 * 60 * 60 * 1000)
      : Date.parse(`${selectedYear}-03-01T12:00:00`);
  const effectiveStartMs = Math.min(selectedMs, Number.isFinite(startMs) ? startMs : selectedMs);
  const dates = [];
  for (let time = effectiveStartMs; time <= selectedMs; time += 24 * 60 * 60 * 1000) {
    dates.push(formatDate(new Date(time)));
  }
  return dates;
}

function hrLeaderboardDatesNeedingLoad(period = hrLeaderboardPeriod) {
  return hrLeaderboardDateRange(period).filter((date) => {
    try {
      if (localStorage.getItem(hrLoadedStorageKey(date)) === '1') return false;
      const stored = JSON.parse(localStorage.getItem(`hrs:${date}`) || 'null');
      if (Array.isArray(stored) && stored.length > 0) return false;
    } catch {}
    return true;
  });
}

async function hydrateHrLeaderboardPeriod(period = hrLeaderboardPeriod) {
  const periodKey = `${period}:${dateInput.value || formatDate(new Date())}`;
  if (hrLeaderboardHydratingPeriods.has(periodKey)) return;
  const dates = hrLeaderboardDatesNeedingLoad(period);
  if (!dates.length) return;
  hrLeaderboardHydratingPeriods.add(periodKey);
  hrLeaderboardPageEl?.classList.add('is-loading-period');
  try {
    for (let i = 0; i < dates.length; i += 2) {
      const chunk = dates.slice(i, i + 2);
      await Promise.all(chunk.map(async (date) => {
        try {
          await fetchGamesAndHomeRuns(date);
        } catch {
          try {
            if (localStorage.getItem(`hrs:${date}`) === null) localStorage.setItem(`hrs:${date}`, '[]');
          } catch {}
        }
      }));
      if (currentOverlayPage === 'hrLeaderboard' && hrLeaderboardPeriod === period) {
        hrLeaderboardPageEl?.replaceChildren(renderHrLeaderboardBoard(period, {
          loadingText: `Loading ${Math.min(i + chunk.length, dates.length)} of ${dates.length} dates...`,
        }));
      }
    }
  } finally {
    hrLeaderboardHydratingPeriods.delete(periodKey);
    hrLeaderboardPageEl?.classList.remove('is-loading-period');
    if (currentOverlayPage === 'hrLeaderboard' && hrLeaderboardPeriod === period) {
      hrLeaderboardPageEl?.replaceChildren(renderHrLeaderboardBoard(period));
    }
  }
}

function collectStoredHomeRunsForPeriod(period = hrLeaderboardPeriod) {
  const selectedDate = dateInput.value || formatDate(new Date());
  const selectedMs = Date.parse(`${selectedDate}T12:00:00`);
  const selectedYear = seasonForDate(selectedDate);
  const cutoffMs = period === 'week'
    ? selectedMs - (6 * 24 * 60 * 60 * 1000)
    : period === 'month'
      ? selectedMs - (30 * 24 * 60 * 60 * 1000)
      : Date.parse(`${selectedYear}-01-01T00:00:00`);
  const byKey = new Map();
  const addHr = (hr, fallbackDate = '') => {
    if (!hr) return;
    const bucketTime = Date.parse(`${fallbackDate || selectedDate}T12:00:00`);
    const eventTime = Number(hr.eventTimeMs);
    const time = Number.isFinite(eventTime) ? eventTime : bucketTime;
    const filterTime = Number.isFinite(bucketTime) ? bucketTime : time;
    if (!Number.isFinite(filterTime) || filterTime < cutoffMs || filterTime > selectedMs + (36 * 60 * 60 * 1000)) return;
    if (period === 'season' && seasonForDate(fallbackDate || new Date(filterTime).toISOString().slice(0, 10)) !== selectedYear) return;
    const key = homeRunEventKey(hr);
    byKey.set(key, { ...hr, eventTimeMs: time, leaderboardDate: fallbackDate || selectedDate });
  };
  for (const hr of latestRenderedHomeRuns || []) addHr(hr);
  try {
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i) || '';
      const date = parseHrStorageDate(key);
      if (!date) continue;
      const list = JSON.parse(localStorage.getItem(key) || '[]');
      if (!Array.isArray(list)) continue;
      for (const hr of list) addHr(hr, date);
    }
  } catch {}
  return [...byKey.values()];
}

function hrLeaderboardPeriodLabel(period = hrLeaderboardPeriod) {
  if (period === 'month') return 'month';
  if (period === 'season') return 'season';
  return 'week';
}

function hrLeaderboardScore(value) {
  const rating = Number(value);
  return Number.isFinite(rating) ? String(Math.round(rating)) : '-';
}

function hrLeaderboardPoints(value) {
  const num = Number(value);
  return Number.isFinite(num) ? String(Math.round(num)) : '-';
}

function hrLeaderboardMedalClass(index) {
  if (index === 0) return 'hr-medal hr-medal-gold';
  if (index === 1) return 'hr-medal hr-medal-silver';
  if (index === 2) return 'hr-medal hr-medal-bronze';
  return '';
}

function renderHrLeaderboardTable(items, emptyText, columns) {
  if (!items.length) return `<div class="leaders-empty">${escapeHtml(emptyText)}</div>`;
  return `
    <div class="hr-leaderboard-table-wrap">
      <table class="hr-leaderboard-table">
        <thead>
          <tr>
            ${columns.map((column) => `<th>${escapeHtml(column.label)}</th>`).join('')}
          </tr>
        </thead>
        <tbody>
          ${items.map((item, index) => {
            const teamColor = item.teamColor || getTeamColor(item.teamAbbr) || '#66d9ff';
            const rowClass = hrLeaderboardMedalClass(index);
            const style = `--hr-leaderboard-team:${teamColor};--hr-leaderboard-team-rgb:${hexToRgb(teamColor)};`;
            return `
              <tr class="${rowClass}" style="${escapeHtml(style)}">
                ${columns.map((column) => `<td class="${column.className || ''}">${column.render(item, index)}</td>`).join('')}
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;
}

function renderHrLeaderboardBoard(period = hrLeaderboardPeriod, options = {}) {
  const hrs = collectStoredHomeRunsForPeriod(period);
  const topHomeRuns = hrs
    .slice()
    .sort((a, b) => homeRunSortValue(b) - homeRunSortValue(a) || (Number(b.eventTimeMs) || 0) - (Number(a.eventTimeMs) || 0))
    .slice(0, 10)
    .map((hr) => ({
      ...hr,
      title: `${hr.batter || 'Unknown'} ${hr.resultLabel || 'Homerun'}`,
      meta: [
        hr.teamAbbr ? displayTeamAbbrev(hr.teamAbbr) : '',
        hr.inningText || '',
        hr.distance ? `${hr.distance} ft` : '',
      ].filter(Boolean).join(' | '),
      scoreText: hrLeaderboardScore(hr.rating ?? hr.ratingBreakdown?.score),
      teamColor: hr.teamColor || getTeamColor(hr.teamAbbr),
    }));
  const playerTotals = new Map();
  for (const hr of hrs) {
    const key = String(hr.batterId || hr.batter || '');
    if (!key) continue;
    const breakdown = hr.ratingBreakdown || {};
    const existing = playerTotals.get(key) || {
      batter: hr.batter || 'Unknown',
      teamAbbr: hr.teamAbbr || '',
      teamLogo: hr.teamLogo || getLogoPath(hr.teamAbbr),
      teamColor: hr.teamColor || getTeamColor(hr.teamAbbr),
      total: 0,
      count: 0,
      best: 0,
      breakdown: {
        walkOff: 0,
        inning: 0,
        result: 0,
        runs: 0,
        pitcher: 0,
        distance: 0,
      },
    };
    const score = Number(hr.rating ?? hr.ratingBreakdown?.score) || 0;
    existing.total += score;
    existing.count += 1;
    existing.best = Math.max(existing.best, score);
    existing.breakdown.walkOff += Number(breakdown.walkOff) || 0;
    existing.breakdown.inning += Number(breakdown.inning) || 0;
    existing.breakdown.result += Number(breakdown.result) || 0;
    existing.breakdown.runs += Number(breakdown.runs) || 0;
    existing.breakdown.pitcher += Number(breakdown.pitcher) || 0;
    existing.breakdown.distance += Number(breakdown.distance) || 0;
    existing.teamAbbr = existing.teamAbbr || hr.teamAbbr || '';
    existing.teamLogo = existing.teamLogo || hr.teamLogo || getLogoPath(hr.teamAbbr);
    existing.teamColor = existing.teamColor || hr.teamColor || getTeamColor(hr.teamAbbr);
    playerTotals.set(key, existing);
  }
  const topPlayers = [...playerTotals.values()]
    .sort((a, b) => b.total - a.total || b.count - a.count || a.batter.localeCompare(b.batter))
    .slice(0, 10)
    .map((player) => ({
      teamLogo: player.teamLogo,
      teamAbbr: player.teamAbbr,
      teamColor: player.teamColor,
      title: player.batter,
      meta: `${displayTeamAbbrev(player.teamAbbr)} | ${player.count} HR`,
      scoreText: String(Math.round(player.total)),
      rating: player.total,
      count: player.count,
      average: player.count ? player.total / player.count : 0,
      best: player.best,
      ratingBreakdown: player.breakdown,
    }));
  const label = hrLeaderboardPeriodLabel(period);
  const hrColumns = [
    { label: '#', className: 'rank-cell', render: (_item, index) => String(index + 1) },
    { label: 'Home Run', className: 'name-cell', render: (item) => `
      <span class="hr-leaderboard-player">
        <img class="hr-leaderboard-logo" src="${escapeHtml(item.teamLogo || getLogoPath(item.teamAbbr) || 'placeholder.png')}" alt="" />
        <span><strong>${escapeHtml(item.title || item.batter || 'Unknown')}</strong><small>${escapeHtml(item.meta || '')}</small></span>
      </span>
    ` },
    { label: 'Score', className: 'score-cell', render: (item) => hrLeaderboardScore(item.rating ?? item.ratingBreakdown?.score) },
    { label: 'WO', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.walkOff) },
    { label: 'Inn', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.inning) },
    { label: 'Result', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.result) },
    { label: 'Runs', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.runs) },
    { label: 'Pitcher', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.pitcher) },
    { label: 'Dist', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.distance) },
  ];
  const playerColumns = [
    { label: '#', className: 'rank-cell', render: (_item, index) => String(index + 1) },
    { label: 'Player', className: 'name-cell', render: (item) => `
      <span class="hr-leaderboard-player">
        <img class="hr-leaderboard-logo" src="${escapeHtml(item.teamLogo || getLogoPath(item.teamAbbr) || 'placeholder.png')}" alt="" />
        <span><strong>${escapeHtml(item.title || item.batter || 'Unknown')}</strong><small>${escapeHtml(item.meta || '')}</small></span>
      </span>
    ` },
    { label: 'Total', className: 'score-cell', render: (item) => hrLeaderboardScore(item.rating) },
    { label: 'HR', render: (item) => hrLeaderboardPoints(item.count) },
    { label: 'Avg', render: (item) => hrLeaderboardScore(item.average) },
    { label: 'Best', render: (item) => hrLeaderboardScore(item.best) },
    { label: 'WO', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.walkOff) },
    { label: 'Inn', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.inning) },
    { label: 'Result', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.result) },
    { label: 'Runs', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.runs) },
    { label: 'Pitcher', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.pitcher) },
    { label: 'Dist', render: (item) => hrLeaderboardPoints(item.ratingBreakdown?.distance) },
  ];
  const shell = document.createElement('div');
  shell.className = 'leaders-shell hr-leaderboard-shell';
  shell.innerHTML = `
    <section class="leaders-section hr-leaderboard-section">
      <div class="leaders-section-header">
        <div>
          <span class="leaders-section-title">HR Leaderboard</span>
          <span class="leaders-section-subtitle">Top rated home runs and cumulative player scores | ${escapeHtml(label)}${options.loadingText ? ` | ${escapeHtml(options.loadingText)}` : ''}</span>
        </div>
        <div class="hr-leaderboard-periods">
          ${['week', 'month', 'season'].map((value) => `<button type="button" data-hr-period="${value}" class="${value === period ? 'active' : ''}">${value}</button>`).join('')}
        </div>
      </div>
      <div class="hr-leaderboard-grid">
        <section class="hr-leaderboard-table-section">
          <h3>Top 10 Home Runs Of The ${escapeHtml(label)}</h3>
          ${renderHrLeaderboardTable(topHomeRuns, `No rated home runs found for this ${label}.`, hrColumns)}
        </section>
        <section class="hr-leaderboard-table-section">
          <h3>Top 10 Cumulative HR Scores</h3>
          ${renderHrLeaderboardTable(topPlayers, `No player home run scores found for this ${label}.`, playerColumns)}
        </section>
      </div>
    </section>
  `;
  return shell;
}

async function getPlayoffStandings(date = dateInput.value || formatDate(new Date())) {
  const selectedDate = formatDate(parseLocalDateValue(date || formatDate(new Date())));
  const season = seasonForDate(selectedDate);
  const cacheKey = `playoff:${season}:${selectedDate}`;
  if (leadersStandingsCache.has(cacheKey)) return leadersStandingsCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/standings`);
    url.searchParams.set('leagueId', '103,104');
    url.searchParams.set('season', String(season));
    url.searchParams.set('date', selectedDate);
    url.searchParams.set('standingsTypes', 'regularSeason');
    url.searchParams.set('hydrate', 'team');
    const response = await getJson(url.toString());
    return listify(response?.records).flatMap((record) => {
      const leagueId = Number(record?.league?.id);
      const league = leagueId === 103 ? 'AL' : leagueId === 104 ? 'NL' : (record?.league?.abbreviation || 'MLB');
      const division = record?.division?.name || record?.division?.abbreviation || '';
      return listify(record?.teamRecords).map((teamRecord) => {
        const team = teamRecord?.team || {};
        const abbreviation = canonicalTeamAbbrev(team?.abbreviation || team?.fileCode || team?.teamCode || team?.name || '');
        const wins = statNumber(teamRecord?.wins ?? teamRecord?.leagueRecord?.wins);
        const losses = statNumber(teamRecord?.losses ?? teamRecord?.leagueRecord?.losses);
        const gamesPlayed = wins + losses;
        const pct = Number(teamRecord?.winningPercentage ?? teamRecord?.leagueRecord?.pct ?? (gamesPlayed ? wins / gamesPlayed : 0));
        return {
          id: Number(team?.id),
          abbreviation,
          name: team?.name || abbreviation || 'Team',
          league,
          leagueId,
          division,
          divisionId: Number(record?.division?.id) || 0,
          wins,
          losses,
          gamesPlayed,
          pct: Number.isFinite(pct) ? pct : 0,
          gamesBack: cleanSummary(teamRecord?.gamesBack) || '-',
          wildCardGamesBack: cleanSummary(teamRecord?.wildCardGamesBack) || '-',
          divisionRecord: standingsSplitRecordText(teamRecord, ['division', 'vsdivision']),
          homeRecord: standingsSplitRecordText(teamRecord, ['home']),
          awayRecord: standingsSplitRecordText(teamRecord, ['away']),
          divisionRank: Number(teamRecord?.divisionRank) || 99,
          leagueRank: Number(teamRecord?.leagueRank) || 99,
          wildCardRank: Number(teamRecord?.wildCardRank) || 99,
          divisionLeader: Boolean(teamRecord?.divisionLeader),
          streak: teamRecord?.streak?.streakCode || '',
          lastTen: lastTenRecordText(teamRecord),
          logo: getLogoPath(abbreviation),
          color: getTeamColor(abbreviation),
        };
      });
    }).filter((team) => team.abbreviation && Number.isFinite(team.id));
  })().catch((error) => {
    leadersStandingsCache.delete(cacheKey);
    throw error;
  });
  leadersStandingsCache.set(cacheKey, promise);
  return promise;
}

function playoffPctText(team = {}) {
  return Number.isFinite(Number(team.pct)) ? Number(team.pct).toFixed(3).replace(/^0/, '') : '---';
}

function playoffRecordText(team = {}) {
  return `${statNumber(team.wins)}-${statNumber(team.losses)}`;
}

function playoffGamesBackFromTeam(target = null, team = null) {
  if (!target || !team) return null;
  const gb = ((statNumber(target.wins) - statNumber(team.wins)) + (statNumber(team.losses) - statNumber(target.losses))) / 2;
  return Number.isFinite(gb) ? Math.max(0, gb) : null;
}

function playoffGamesBackText(value) {
  const gb = Number(value);
  if (!Number.isFinite(gb)) return '--';
  if (gb <= 0) return '0.0';
  return gb.toFixed(1).replace(/\.0$/, '.0');
}

function playoffSort(a, b) {
  return (Number(b.pct) || 0) - (Number(a.pct) || 0)
    || statNumber(b.wins) - statNumber(a.wins)
    || statNumber(a.losses) - statNumber(b.losses)
    || (Number(a.leagueRank) || 99) - (Number(b.leagueRank) || 99)
    || (Number(a.wildCardRank) || 99) - (Number(b.wildCardRank) || 99)
    || String(a.name || '').localeCompare(String(b.name || ''));
}

function playoffLeaguePicture(teams = [], league = '') {
  const leagueTeams = teams.filter((team) => team.league === league);
  const divisions = new Map();
  for (const team of leagueTeams) {
    const key = team.divisionId || team.division || 'division';
    const group = divisions.get(key) || [];
    group.push(team);
    divisions.set(key, group);
  }
  const divisionWinners = [...divisions.values()]
    .map((group) => group.slice().sort(playoffSort)[0])
    .filter(Boolean)
    .sort(playoffSort);
  const divisionWinnerIds = new Set(divisionWinners.map((team) => String(team.id)));
  const wildCards = leagueTeams
    .filter((team) => !divisionWinnerIds.has(String(team.id)))
    .sort(playoffSort);
  const seeds = [
    ...divisionWinners.slice(0, 3).map((team, index) => ({
      seed: index + 1,
      team,
      type: index < 2 ? 'Division bye' : 'Division winner',
      slot: index < 2 ? 'Bye to LDS' : 'Hosts WC3',
    })),
    ...wildCards.slice(0, 3).map((team, index) => ({
      seed: index + 4,
      team,
      type: `Wild Card ${index + 1}`,
      slot: index === 0 ? 'Hosts WC2' : index === 1 ? 'At WC1' : 'At seed 3',
    })),
  ];
  const seedIds = new Set(seeds.map((row) => String(row.team?.id || '')));
  const lastWildCard = seeds.find((row) => row.seed === 6)?.team || null;
  const hunt = leagueTeams
    .filter((team) => !seedIds.has(String(team.id)))
    .map((team) => ({
      ...team,
      gbFromLastWildCard: playoffGamesBackFromTeam(lastWildCard, team),
    }))
    .sort((a, b) => Number(a.gbFromLastWildCard ?? 999) - Number(b.gbFromLastWildCard ?? 999) || playoffSort(a, b));
  return { league, seeds, hunt, wildCards, divisionWinners, lastWildCard };
}

function playoffTeamCell(team = {}) {
  const teamAbbrev = canonicalTeamAbbrev(team.abbreviation || team.abbrev || '');
  return `
    <span class="playoff-team-cell" role="button" tabindex="0" data-team-detail-team="${escapeHtml(teamAbbrev)}" style="--team-color:${escapeHtml(team.color || getTeamColor(team.abbreviation))}">
      <img src="${escapeHtml(team.logo || getLogoPath(team.abbreviation) || 'placeholder.png')}" alt="" />
      <span><strong>${escapeHtml(displayTeamAbbrev(team.abbreviation) || team.name || 'Team')}</strong><small>${escapeHtml(`${team.name || ''}${team.wins != null ? ` | ${playoffRecordText(team)}` : ''}`)}</small></span>
    </span>
  `;
}

function playoffBracketTeam(team = null, seed = '') {
  const teamAbbrev = canonicalTeamAbbrev(team?.abbreviation || team?.abbrev || '');
  return `
    <div class="playoff-bracket-team${team ? '' : ' is-empty'}" ${team ? `role="button" tabindex="0" data-team-detail-team="${escapeHtml(teamAbbrev)}"` : ''} style="--team-color:${escapeHtml(team?.color || getTeamColor(team?.abbreviation || ''))}">
      <span class="playoff-seed-chip">${escapeHtml(seed)}</span>
      ${team ? `<img src="${escapeHtml(team.logo || getLogoPath(team.abbreviation) || 'placeholder.png')}" alt="" />` : ''}
      <span>
        <strong>${escapeHtml(team ? (displayTeamAbbrev(team.abbreviation) || team.name || 'Team') : '--')}</strong>
        <small>${escapeHtml(team ? playoffRecordText(team) : 'TBD')}</small>
      </span>
    </div>
  `;
}

function renderPlayoffSeedTable(picture = {}) {
  const rows = picture.seeds || [];
  if (!rows.length) return '<div class="leaders-empty">Standings unavailable.</div>';
  return `
    <div class="hr-leaderboard-table-wrap playoff-table-wrap">
      <table class="hr-leaderboard-table playoff-table">
        <thead><tr><th>Seed</th><th>Team</th><th>Role</th><th>Record</th><th>Pct</th><th>Path</th></tr></thead>
        <tbody>
          ${rows.map((row) => `
            <tr>
              <td class="rank-cell">${row.seed}</td>
              <td class="name-cell">${playoffTeamCell(row.team)}</td>
              <td>${escapeHtml(row.type)}</td>
              <td>${escapeHtml(playoffRecordText(row.team))}</td>
              <td>${escapeHtml(playoffPctText(row.team))}</td>
              <td>${escapeHtml(row.slot)}</td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

function playoffHuntCells(team = null) {
  if (!team) {
    return '<td class="name-cell is-empty">--</td><td>--</td><td>--</td><td>--</td>';
  }
  return `
    <td class="name-cell">${playoffTeamCell(team)}</td>
    <td class="score-cell">${escapeHtml(playoffGamesBackText(team.gbFromLastWildCard))}</td>
    <td>${escapeHtml(playoffRecordText(team))}</td>
    <td>${escapeHtml(team.lastTen || '--')}</td>
  `;
}

function renderCombinedPlayoffHuntTable(alPicture = {}, nlPicture = {}) {
  const alRows = alPicture.hunt || [];
  const nlRows = nlPicture.hunt || [];
  const rowCount = Math.max(alRows.length, nlRows.length);
  if (!rowCount) return '<div class="leaders-empty">No teams outside the playoff field.</div>';
  return `
    <div class="hr-leaderboard-table-wrap playoff-table-wrap playoff-hunt-wrap">
      <table class="hr-leaderboard-table playoff-table playoff-hunt-table playoff-combined-hunt-table">
        <thead>
          <tr class="playoff-hunt-league-row"><th colspan="4">AL In The Hunt</th><th colspan="4">NL In The Hunt</th></tr>
          <tr><th>Team</th><th>GB</th><th>Record</th><th>L10</th><th>Team</th><th>GB</th><th>Record</th><th>L10</th></tr>
        </thead>
        <tbody>
          ${Array.from({ length: rowCount }, (_, index) => `
            <tr>
              ${playoffHuntCells(alRows[index] || null)}
              ${playoffHuntCells(nlRows[index] || null)}
            </tr>
          `).join('')}
        </tbody>
      </table>
    </div>
  `;
}

