function refreshHrLeaderboardView() {
  if (!hrLeaderboardPageEl || currentOverlayPage !== 'hrLeaderboard') return;
  updateLeadersContext();
  hrLeaderboardPageEl.replaceChildren(createLeaderEmpty('Loading playoff picture...'));
  getPlayoffStandings(dateInput.value || formatDate(new Date()))
    .then((teams) => {
      if (currentOverlayPage !== 'hrLeaderboard') return;
      hrLeaderboardPageEl.replaceChildren(renderPlayoffPictureBoard(teams));
    })
    .catch((error) => {
      if (currentOverlayPage !== 'hrLeaderboard') return;
      hrLeaderboardPageEl.replaceChildren(createLeaderEmpty(`Could not load playoff picture (${error.message}).`));
    });
}

function updateDashboardSummary(games = latestRenderedGames) {
  if (!dashboardSummaryEl) return;
  const list = Array.isArray(games) ? games : [];
  const live = list.filter((game) => /top|bot|live/i.test(`${game?.inningShort || ''} ${game?.status || ''}`)).length;
  dashboardSummaryEl.textContent = `${list.length} games | ${live} live | ${dateInput.value || formatDate(new Date())}`;
}

function refreshScoreboardPageOnReturn() {
  const selectedDate = String(dateInput?.value || formatDate(new Date()));
  renderHomeRunFeed(latestRenderedHomeRuns.length ? latestRenderedHomeRuns : cachedHomeRunsForSelectedDate());
  const dateMismatch = Boolean(latestRenderedGamesDate && latestRenderedGamesDate !== selectedDate);
  if (dateMismatch) {
    loadGames({ invalidate: true, showLoading: true });
    return;
  }
  if (!latestRenderedGames.length) {
    loadGames({ showLoading: false, passive: true });
    return;
  }
  // Returning from another page should not repaint already-hydrated pitcher rows.
  // Let the normal timer handle stale/live hydration; keep the visible board stable here.
  refreshHomeRunFeedOnlyQuiet({ minGapMs: 30000 });
}

function setOverlayPage(page, options = {}) {
  const { persist = true, refresh = true } = options;
  currentOverlayPage = normalizeOverlayPage(page);
  document.body.dataset.dashboardPage = currentOverlayPage;
  for (const btn of document.querySelectorAll('[data-page-nav]')) {
    const active = btn.dataset.pageNav === currentOverlayPage;
    btn.classList.toggle('active', active);
    btn.setAttribute('aria-selected', active ? 'true' : 'false');
  }
  if (gamesEl) {
    gamesEl.hidden = currentOverlayPage !== 'scoreboard';
    gamesEl.style.display = currentOverlayPage === 'scoreboard' ? '' : 'none';
  }
  if (leadersPageEl) {
    leadersPageEl.hidden = currentOverlayPage !== 'leaders';
    leadersPageEl.style.display = currentOverlayPage === 'leaders' ? '' : 'none';
  }
  if (hotPageEl) {
    hotPageEl.hidden = currentOverlayPage !== 'hot';
    hotPageEl.style.display = currentOverlayPage === 'hot' ? '' : 'none';
  }
  if (teamStatsPageEl) {
    teamStatsPageEl.hidden = currentOverlayPage !== 'teamStats';
    teamStatsPageEl.style.display = currentOverlayPage === 'teamStats' ? '' : 'none';
  }
  if (predictionsPageEl) {
    predictionsPageEl.hidden = currentOverlayPage !== 'predictions';
    predictionsPageEl.style.display = currentOverlayPage === 'predictions' ? '' : 'none';
  }
  if (hrLeaderboardPageEl) {
    hrLeaderboardPageEl.hidden = currentOverlayPage !== 'hrLeaderboard';
    hrLeaderboardPageEl.style.display = currentOverlayPage === 'hrLeaderboard' ? '' : 'none';
  }
  if (leadersToolbarEl) leadersToolbarEl.hidden = currentOverlayPage === 'scoreboard' || currentOverlayPage === 'hrLeaderboard';
  const qualifierFilterEl = leadersQualifierSelectEl?.closest?.('.leaders-min-pa-filter');
  if (qualifierFilterEl) qualifierFilterEl.hidden = currentOverlayPage !== 'leaders';
  if (scoreboardColumnsBtnEl) scoreboardColumnsBtnEl.hidden = false;
  if (persist) {
    try {
      localStorage.setItem(OVERLAY_PAGE_KEY, currentOverlayPage);
    } catch {}
  }
  updateLeadersContext();
  scheduleAutoRefresh();
  if (refresh && currentOverlayPage === 'scoreboard') refreshScoreboardPageOnReturn();
  if (refresh && currentOverlayPage === 'leaders') refreshLeadersView();
  if (refresh && currentOverlayPage === 'hot') refreshHotView();
  if (refresh && currentOverlayPage === 'teamStats') refreshTeamStatsView();
  if (refresh && currentOverlayPage === 'predictions') refreshPredictionsView();
  if (refresh && currentOverlayPage === 'hrLeaderboard') refreshHrLeaderboardView();
}

function initOverlayPageControl() {
  const params = new URLSearchParams(window.location.search);
  const saved = normalizeOverlayPage(params.get('page') || localStorage.getItem(OVERLAY_PAGE_KEY) || 'scoreboard');
  for (const btn of document.querySelectorAll('[data-page-nav]')) {
    btn.addEventListener('click', () => setOverlayPage(btn.dataset.pageNav));
  }
  setOverlayPage(saved, { persist: false, refresh: false });
}

function isTextEntryTarget(target = document.activeElement) {
  if (!target || target === document.body || target === document.documentElement) return false;
  if (target.isContentEditable) return true;
  const tagName = String(target.tagName || '').toLowerCase();
  return tagName === 'input' || tagName === 'textarea' || tagName === 'select';
}

function setOverlayWindowFullscreen(enabled) {
  currentOverlayWindowFullscreen = Boolean(enabled);
  document.body.classList.toggle('overlay-window-fullscreen', currentOverlayWindowFullscreen);
  requestAnimationFrame(refreshAllScoreboardResponsiveLayout);
}

function toggleOverlayWindowFullscreen() {
  setOverlayWindowFullscreen(!currentOverlayWindowFullscreen);
}


function scoreboardOverlayInteractionActive() {
  return Boolean(
    (lineupOverlayEl && !lineupOverlayEl.hidden)
      || (playerStatOverlayEl && !playerStatOverlayEl.hidden)
      || (teamDetailOverlayEl && !teamDetailOverlayEl.hidden)
      || (lineupSplitPeerEl && !lineupSplitPeerEl.hidden)
  );
}

function holdPassiveScoreboardRefresh(ms = 25000) {
  const until = Date.now() + Math.max(1000, Number(ms) || 25000);
  passiveScoreboardRefreshHoldUntil = Math.max(passiveScoreboardRefreshHoldUntil || 0, until);
}

function passiveScoreboardRefreshHeld() {
  return Date.now() < (passiveScoreboardRefreshHoldUntil || 0);
}

function cancelFocusedGameHydration() {
  priorityHydrationGamePk = '';
  focusedGameHydrationSeq += 1;
  gamesEl?.querySelectorAll?.('.game-card.is-priority-hydrating').forEach((card) => {
    card.classList.remove('is-priority-hydrating');
    delete card.dataset.priorityHydrating;
  });
}

function firstScrollableElement(candidates = []) {
  for (const candidate of candidates) {
    if (!candidate || candidate.hidden) continue;
    const rect = candidate.getBoundingClientRect?.();
    if (!rect || rect.width <= 0 || rect.height <= 0) continue;
    if (candidate.scrollHeight > candidate.clientHeight + 2) return candidate;
  }
  return candidates.find((candidate) => candidate && !candidate.hidden) || null;
}

function currentOverlayScrollTarget() {
  if (playerStatOverlayEl && !playerStatOverlayEl.hidden) {
    return firstScrollableElement([
      playerStatOverlayEl.querySelector('.player-stat-right'),
      playerStatOverlayEl.querySelector('.player-stat-body'),
      playerStatOverlayEl.querySelector('.player-stat-modal'),
    ]);
  }

  if (lineupOverlayEl && !lineupOverlayEl.hidden) {
    const activePanel = lineupOverlayEl.querySelector(`[data-lineup-panel="${currentLineupView}"]`);
    const activePanelScrollAreas = activePanel
      ? Array.from(activePanel.querySelectorAll('.lineup-modal-team, .lineup-pitching-panel, .lineup-roster-panel'))
      : [];
    return firstScrollableElement([
      activePanel,
      ...activePanelScrollAreas,
      lineupOverlayEl.querySelector('.lineup-modal-body'),
      lineupOverlayEl.querySelector('.lineup-modal'),
    ]);
  }

  if (currentOverlayPage === 'leaders') {
    return firstScrollableElement([leadersPageEl?.querySelector('.leaders-shell'), leadersPageEl]);
  }

  if (currentOverlayPage === 'hot') {
    return firstScrollableElement([hotPageEl?.querySelector('.leaders-shell'), hotPageEl]);
  }

  if (currentOverlayPage === 'teamStats') {
    return firstScrollableElement([teamStatsPageEl?.querySelector('.leaders-shell'), teamStatsPageEl]);
  }

  if (currentOverlayPage === 'predictions') {
    return firstScrollableElement([predictionsPageEl?.querySelector('.leaders-shell'), predictionsPageEl]);
  }

  if (currentOverlayPage === 'hrLeaderboard') {
    return firstScrollableElement([hrLeaderboardPageEl?.querySelector('.leaders-shell'), hrLeaderboardPageEl]);
  }

  return firstScrollableElement([gamesEl, overlayEl]);
}

function scrollCurrentOverlay(direction) {
  const target = currentOverlayScrollTarget();
  if (!target) return false;
  const amount = Math.max(72, Math.round((target.clientHeight || 0) * 0.72));
  target.scrollBy({ top: amount * direction, behavior: 'auto' });
  return true;
}

function normalizedWheelDelta(event, target) {
  const unit = event.deltaMode === WheelEvent.DOM_DELTA_LINE
    ? 16
    : event.deltaMode === WheelEvent.DOM_DELTA_PAGE
      ? Math.max(1, target?.clientHeight || window.innerHeight || 800)
      : 1;
  return {
    x: event.deltaX * unit,
    y: event.deltaY * unit,
  };
}

function canElementScroll(element) {
  return Boolean(
    element
      && !element.hidden
      && (
        element.scrollHeight > element.clientHeight + 2
        || element.scrollWidth > element.clientWidth + 2
      ),
  );
}

function overlayWheelScrollTarget(event) {
  const target = event.target instanceof Element ? event.target : null;
  const local = target?.closest?.([
    '.player-stat-heatmap',
    '.player-stat-body',
    '.player-stat-right',
    '.lineup-modal-team',
    '.lineup-pitching-panel',
    '.lineup-roster-panel',
    '.lineup-modal-columns',
    '.lineup-pitching-grid',
    '.lineup-roster-grid',
    '.lineup-modal-body',
  ].join(','));
  if (canElementScroll(local)) return local;
  return currentOverlayScrollTarget();
}

function handleOverlayWheelScroll(event) {
  if (
    (!lineupOverlayEl || lineupOverlayEl.hidden)
    && (!playerStatOverlayEl || playerStatOverlayEl.hidden)
  ) return;
  const target = overlayWheelScrollTarget(event);
  if (!canElementScroll(target)) return;
  const { x, y } = normalizedWheelDelta(event, target);
  const beforeTop = target.scrollTop;
  const beforeLeft = target.scrollLeft;
  target.scrollTop += y;
  target.scrollLeft += x;
  if (target.scrollTop !== beforeTop || target.scrollLeft !== beforeLeft) {
    event.preventDefault();
    event.stopPropagation();
  }
}

function handlePlayoffPictureWheel(event) {
  const target = event.target instanceof Element ? event.target : null;
  const canvas = target?.closest?.('.playoff-picture-canvas');
  if (!canvas) return;
  const shell = hrLeaderboardPageEl?.querySelector?.('.playoff-picture-shell') || hrLeaderboardPageEl?.querySelector?.('.leaders-shell') || hrLeaderboardPageEl;
  const { x, y } = normalizedWheelDelta(event, shell || canvas);
  const mostlyVertical = Math.abs(y) >= Math.abs(x);
  const scrollTarget = mostlyVertical ? shell : canvas;
  if (!canElementScroll(scrollTarget)) return;
  const beforeTop = scrollTarget.scrollTop;
  const beforeLeft = scrollTarget.scrollLeft;
  if (mostlyVertical) scrollTarget.scrollTop += y;
  else scrollTarget.scrollLeft += x;
  if (scrollTarget.scrollTop !== beforeTop || scrollTarget.scrollLeft !== beforeLeft) {
    event.preventDefault();
    event.stopPropagation();
  }
}

function shiftOverlayPage(direction) {
  const pages = ['scoreboard', 'leaders', 'hot', 'teamStats', 'hrLeaderboard'];
  const index = Math.max(0, pages.indexOf(currentOverlayPage));
  const nextIndex = (index + direction + pages.length) % pages.length;
  setOverlayPage(pages[nextIndex]);
}

function initOverlayKeyboardShortcuts() {
  document.addEventListener('keydown', (e) => {
    if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey) return;
    if (isTextEntryTarget(e.target)) return;
    const lineupOpen = lineupOverlayEl && !lineupOverlayEl.hidden;
    const playerCardOpen = playerStatOverlayEl && !playerStatOverlayEl.hidden;

    if ((e.key === 's' || e.key === 'S') && !lineupOpen && !playerCardOpen) {
      e.preventDefault();
      toggleOverlayWindowFullscreen();
      return;
    }

    if (e.key === 'ArrowLeft') {
      e.preventDefault();
      if (playerStatOverlayEl && !playerStatOverlayEl.hidden) {
        navigatePlayerStatCard(-1);
        return;
      }
      if (!navigateOpenLineupGame(-1)) shiftOverlayPage(-1);
      return;
    }

    if (e.key === 'ArrowRight') {
      e.preventDefault();
      if (playerStatOverlayEl && !playerStatOverlayEl.hidden) {
        navigatePlayerStatCard(1);
        return;
      }
      if (!navigateOpenLineupGame(1)) shiftOverlayPage(1);
      return;
    }

    if (e.key === 'ArrowUp') {
      if (navigatePitcherHeatMapLineup(-1)) {
        e.preventDefault();
        return;
      }
      if (scrollCurrentOverlay(-1)) e.preventDefault();
      return;
    }

    if (e.key === 'ArrowDown') {
      if (navigatePitcherHeatMapLineup(1)) {
        e.preventDefault();
        return;
      }
      if (scrollCurrentOverlay(1)) e.preventDefault();
    }
  });
}

async function syncLeaderTeamOptions(games = latestRenderedGames) {
  if (!leadersTeamSelectEl) return;
  const previous = leadersTeamSelectEl.value || '';
  const season = seasonForDate(dateInput.value || formatDate(new Date()));
  try {
    latestLeaderTeams = await getTeamsForSeason(season);
  } catch {
    const fallback = new Map();
    for (const game of games) {
      fallback.set(game.away, { id: game.away, abbreviation: game.away, name: game.away });
      fallback.set(game.home, { id: game.home, abbreviation: game.home, name: game.home });
    }
    latestLeaderTeams = [...fallback.values()].sort((a, b) => String(a.abbreviation).localeCompare(String(b.abbreviation)));
  }
  const currentSignature = Array.from(leadersTeamSelectEl.options).map((option) => `${option.value}:${option.textContent}`).join('|');
  const nextOptions = [
    { value: '', text: 'League', abbrev: '', name: 'MLB' },
    ...latestLeaderTeams.map((team) => ({
      value: String(team.id),
      text: `${displayTeamAbbrev(team.abbreviation)} | ${team.name}`,
      abbrev: team.abbreviation,
      name: team.name,
    })),
  ];
  const nextSignature = nextOptions.map((option) => `${option.value}:${option.text}`).join('|');
  if (currentSignature !== nextSignature) {
    leadersTeamSelectEl.replaceChildren();
    for (const team of nextOptions) {
      const option = document.createElement('option');
      option.value = team.value;
      option.dataset.abbrev = team.abbrev;
      option.dataset.name = team.name;
      option.textContent = team.text;
      leadersTeamSelectEl.appendChild(option);
    }
  }

  const valid = new Set(Array.from(leadersTeamSelectEl.options).map((option) => option.value));
  leadersTeamSelectEl.value = valid.has(previous) ? previous : '';
}

function syncLeadersOpponentsButton(games = latestRenderedGames) {
  if (!leadersOpponentsBtnEl) return;
  const matchup = selectedLeaderMatchup(games);
  const enabled = Boolean(matchup);
  leadersOpponentsBtnEl.disabled = !enabled;
  leadersOpponentsBtnEl.classList.toggle('is-active', enabled && currentLeadersOpponentMode);
  leadersOpponentsBtnEl.title = enabled
    ? `Filter leaders to ${matchup.away} and ${matchup.home}`
    : 'Select a team that is playing on the selected date';
  if (!enabled) currentLeadersOpponentMode = false;
}

async function syncLeaderFilters(games = latestRenderedGames) {
  await syncLeaderTeamOptions(games);
  populateLeaderDateRangeOptions();
  syncLeadersOpponentsButton(games);
  updateLeadersContext();
}

function createLeaderEmpty(message) {
  const empty = document.createElement('div');
  empty.className = 'leaders-empty';
  empty.textContent = message;
  return empty;
}

async function fetchTeamStatsGroup(season, group) {
  const url = new URL(`${MLB_API_BASE}/teams/stats`);
  url.searchParams.set('stats', 'season');
  url.searchParams.set('group', group);
  url.searchParams.set('season', String(season));
  url.searchParams.set('gameType', 'R');
  url.searchParams.set('sportIds', '1');
  const response = await getJson(url.toString());
  const map = new Map();
  for (const split of listify(response?.stats?.[0]?.splits)) {
    const teamId = Number(split?.team?.id);
    if (!Number.isFinite(teamId)) continue;
    map.set(teamId, split?.stat || {});
  }
  return map;
}

async function fetchTeamRispStatsMap(season) {
  const url = new URL(`${MLB_API_BASE}/teams/stats`);
  url.searchParams.set('stats', 'statSplits');
  url.searchParams.set('group', 'hitting');
  url.searchParams.set('sitCodes', 'risp');
  url.searchParams.set('season', String(season));
  url.searchParams.set('gameType', 'R');
  url.searchParams.set('sportIds', '1');
  const response = await getJson(url.toString());
  const map = new Map();
  for (const split of listify(response?.stats?.[0]?.splits)) {
    const teamId = Number(split?.team?.id);
    if (!Number.isFinite(teamId)) continue;
    map.set(teamId, split?.stat || {});
  }
  return map;
}

async function fetchTeamRecordMap(season) {
  const url = new URL(`${MLB_API_BASE}/standings`);
  url.searchParams.set('sportId', '1');
  url.searchParams.set('leagueId', '103,104');
  url.searchParams.set('season', String(season));
  url.searchParams.set('standingsTypes', 'regularSeason');
  const response = await getJson(url.toString());
  const map = new Map();
  for (const record of listify(response?.records)) {
    for (const teamRecord of listify(record?.teamRecords)) {
      const teamId = Number(teamRecord?.team?.id);
      if (!Number.isFinite(teamId)) continue;
      const wins = statNumber(teamRecord?.wins);
      const losses = statNumber(teamRecord?.losses);
      map.set(teamId, {
        text: `${wins}-${losses}`,
        pct: cleanSummary(teamRecord?.winningPercentage || ''),
        gb: cleanSummary(teamRecord?.divisionGamesBack ?? teamRecord?.gamesBack ?? ''),
        lastTen: lastTenRecordText(teamRecord),
      });
    }
  }
  return map;
}

function lastTenRecordText(teamRecord) {
  const candidates = [
    ...listify(teamRecord?.records?.splitRecords),
    ...listify(teamRecord?.records?.overallRecords),
    ...listify(teamRecord?.splitRecords),
    ...listify(teamRecord?.overallRecords),
  ];
  const found = candidates.find((entry) => /last\s*ten|last10/i.test(String(entry?.type || entry?.description || '')));
  if (!found) return '--';
  const wins = statNumber(found.wins);
  const losses = statNumber(found.losses);
  return `${wins}-${losses}`;
}

function selectedTeamStatsIds() {
  const ids = currentFilteredTeamIds(latestRenderedGames);
  return ids.length ? new Set(ids.map((id) => Number(id))) : null;
}

function latestRenderedRecordForTeam(abbrev) {
  const team = String(abbrev || '').toUpperCase();
  for (const game of latestRenderedGames) {
    if (String(game.away || '').toUpperCase() === team && game.awayRecord) return game.awayRecord;
    if (String(game.home || '').toUpperCase() === team && game.homeRecord) return game.homeRecord;
  }
  return '';
}

function parseRecordValue(record = '') {
  const match = String(record || '').match(/(\d+)\s*-\s*(\d+)/);
  if (!match) return { wins: 0, losses: 0, pct: 0 };
  const wins = Number(match[1]) || 0;
  const losses = Number(match[2]) || 0;
  return { wins, losses, pct: wins + losses > 0 ? wins / (wins + losses) : 0 };
}

function formatTeamRate(value) {
  const rate = statRate(value);
  if (rate == null) return '---';
  return formatRateValue(rate, 3, true);
}

function emptyTeamStarterHandBucket() {
  return { wins: 0, losses: 0, atBats: 0, hits: 0, homeRuns: 0, avg: '' };
}

function emptyTeamStarterHandSummary() {
  return {
    vsLStarter: emptyTeamStarterHandBucket(),
    vsRStarter: emptyTeamStarterHandBucket(),
    opener: emptyTeamStarterHandBucket(),
    withOpener: emptyTeamStarterHandBucket(),
  };
}

function updateStarterHandSummary(map, teamId, hand, won, batting = {}) {
  const normalizedHand = handednessCode(hand);
  if (!Number.isFinite(Number(teamId)) || !['L', 'R'].includes(normalizedHand)) return;
  if (!map.has(Number(teamId))) map.set(Number(teamId), emptyTeamStarterHandSummary());
  const bucket = map.get(Number(teamId))[normalizedHand === 'L' ? 'vsLStarter' : 'vsRStarter'];
  if (won) bucket.wins += 1;
  else bucket.losses += 1;
  bucket.atBats += statNumber(batting.atBats);
  bucket.hits += statNumber(batting.hits);
  bucket.homeRuns += statNumber(batting.homeRuns ?? batting.hr);
}

function updateOpenerSummary(map, teamId, won, batting = {}) {
  if (!Number.isFinite(Number(teamId))) return;
  if (!map.has(Number(teamId))) map.set(Number(teamId), emptyTeamStarterHandSummary());
  const bucket = map.get(Number(teamId)).opener || emptyTeamStarterHandBucket();
  if (won) bucket.wins += 1;
  else bucket.losses += 1;
  bucket.atBats += statNumber(batting.atBats);
  bucket.hits += statNumber(batting.hits);
  bucket.homeRuns += statNumber(batting.homeRuns ?? batting.hr);
  map.get(Number(teamId)).opener = bucket;
}

function updateWithOpenerSummary(map, teamId, won, batting = {}) {
  if (!Number.isFinite(Number(teamId))) return;
  if (!map.has(Number(teamId))) map.set(Number(teamId), emptyTeamStarterHandSummary());
  const bucket = map.get(Number(teamId)).withOpener || emptyTeamStarterHandBucket();
  if (won) bucket.wins += 1;
  else bucket.losses += 1;
  bucket.atBats += statNumber(batting.atBats);
  bucket.hits += statNumber(batting.hits);
  bucket.homeRuns += statNumber(batting.homeRuns ?? batting.hr);
  map.get(Number(teamId)).withOpener = bucket;
}

function recordBucketText(bucket = {}, options = {}) {
  const wins = Number(bucket.wins) || 0;
  const losses = Number(bucket.losses) || 0;
  const games = wins + losses;
  const minGames = Number(options.minGames || 0);
  if (!games) return '--';
  if (minGames > 0 && games < minGames) return options.pendingText || '...';
  return `${wins}-${losses}`;
}

function teamStarterHandAvgText(bucket = {}) {
  const direct = cleanSummary(bucket?.avg);
  if (direct) return direct;
  return bucket && Number(bucket.atBats) > 0 ? formatRateValue(Number(bucket.hits) / Number(bucket.atBats), 3, true) : '---';
}

function starterHandBucketWithAvg(stat = {}) {
  const bucket = emptyTeamStarterHandBucket();
  bucket.atBats = statNumber(stat.atBats ?? stat.ab);
  bucket.hits = statNumber(stat.hits ?? stat.h);
  bucket.homeRuns = statNumber(stat.homeRuns ?? stat.hr);
  bucket.avg = formatTeamRate(stat.avg ?? stat.battingAverage);
  return bucket;
}

function seasonDateRangeForStarterHandStats(season) {
  const year = Number(season) || new Date().getFullYear();
  const selected = parseLocalDateValue(parseFlexibleDateInput(dateInput?.value || '') || formatDate(new Date()));
  const end = selected.getFullYear() === year ? selected : new Date(year, 9, 31);
  return { start: `${year}-03-01`, end: formatDate(end) };
}

async function fetchTeamVsPitcherHandBattingMap(season) {
  const map = new Map();
  const splitResponses = await Promise.all([
    ['L', 'vl'],
    ['R', 'vr'],
  ].map(async ([hand, sitCode]) => {
    const url = new URL(`${MLB_API_BASE}/teams/stats`);
    url.searchParams.set('stats', 'statSplits');
    url.searchParams.set('group', 'hitting');
    url.searchParams.set('sitCodes', sitCode);
    url.searchParams.set('season', String(season));
    url.searchParams.set('gameType', 'R');
    url.searchParams.set('sportIds', '1');
    const response = await getJson(url.toString());
    return [hand, listify(response?.stats?.[0]?.splits)];
  }));
  for (const [hand, splits] of splitResponses) {
    for (const split of splits) {
      const teamId = Number(split?.team?.id);
      if (!Number.isFinite(teamId)) continue;
      if (!map.has(teamId)) map.set(teamId, emptyTeamStarterHandSummary());
      const bucketKey = hand === 'L' ? 'vsLStarter' : 'vsRStarter';
      map.get(teamId)[bucketKey] = {
        ...map.get(teamId)[bucketKey],
        ...starterHandBucketWithAvg(split?.stat || {}),
      };
    }
  }
  return map;
}

function isHistoricalOpenerStartProfile(player = null) {
  const gp = pitcherGamesPlayed(player);
  const gs = pitcherGamesStarted(player);
  const outs = inningsToOuts(pitcherInningsPitched(player));
  if (gp <= 0 || gs <= 0 || outs <= 0) return false;
  const startsShare = gs / Math.max(1, gp);
  const avgStartIp = (outs / 3) / Math.max(1, gs);
  if (isStarterLikePitcher(player)) return false;
  if (avgStartIp >= 3.0) return false;
  if (gs >= 3 && startsShare >= 0.25) return false;
  return avgStartIp < 2.75 && startsShare < 0.35;
}

async function fetchTeamVsStarterHandRecordMap(season) {
  const { start, end } = seasonDateRangeForStarterHandStats(season);
  const url = new URL(`${MLB_API_BASE}/schedule`);
  url.searchParams.set('sportId', '1');
  url.searchParams.set('season', String(season));
  url.searchParams.set('gameType', 'R');
  url.searchParams.set('startDate', start);
  url.searchParams.set('endDate', end);
  url.searchParams.set('hydrate', 'probablePitcher');
  const response = await getJson(url.toString());
  const games = listify(response?.dates)
    .flatMap((date) => listify(date?.games))
    .filter((game) => /final|game over|completed/i.test(String(game?.status?.detailedState || game?.status?.abstractGameState || '')));
  const map = new Map();

  // Keep this path fast and complete. For team-vs-starter-side records we only need
  // the opposing starter hand and the final score; do not boxscore-scrape every game,
  // because live deployments can timeout and produce bogus partial records like 0-3.
  await mapWithConcurrency(games, 10, async (game) => {
    const away = game?.teams?.away || {};
    const home = game?.teams?.home || {};
    const awayTeamId = Number(away?.team?.id);
    const homeTeamId = Number(home?.team?.id);
    const awayScore = Number(away?.score);
    const homeScore = Number(home?.score);
    if (!Number.isFinite(awayTeamId) || !Number.isFinite(homeTeamId) || !Number.isFinite(awayScore) || !Number.isFinite(homeScore)) return;

    const awayProbable = away?.probablePitcher || null;
    const homeProbable = home?.probablePitcher || null;
    const [awayStarterHand, homeStarterHand] = await Promise.all([
      teamStatsPitcherHandForPerson(awayProbable),
      teamStatsPitcherHandForPerson(homeProbable),
    ]);

    if (homeStarterHand) updateStarterHandSummary(map, awayTeamId, homeStarterHand, awayScore > homeScore);
    if (awayStarterHand) updateStarterHandSummary(map, homeTeamId, awayStarterHand, homeScore > awayScore);
  });
  return map;
}

async function fetchTeamVsStarterHandFastSummaryMap(season) {
  const [recordMap, battingMap] = await Promise.all([
    fetchTeamVsStarterHandRecordMap(season).catch(() => new Map()),
    fetchTeamVsPitcherHandBattingMap(season).catch(() => new Map()),
  ]);
  const teamIds = new Set([...recordMap.keys(), ...battingMap.keys()]);
  const map = new Map();
  for (const teamId of teamIds) {
    const recordSummary = recordMap.get(teamId) || emptyTeamStarterHandSummary();
    const battingSummary = battingMap.get(teamId) || emptyTeamStarterHandSummary();
    map.set(teamId, {
      vsLStarter: { ...recordSummary.vsLStarter, ...battingSummary.vsLStarter },
      vsRStarter: { ...recordSummary.vsRStarter, ...battingSummary.vsRStarter },
      opener: recordSummary.opener || emptyTeamStarterHandBucket(),
      withOpener: recordSummary.withOpener || emptyTeamStarterHandBucket(),
    });
  }
  return map;
}

async function teamStatsPitcherHandForPerson(player = null) {
  const direct = handednessCode(
    player?.person?.pitchHand?.code
      || player?.person?.pitchHand?.description
      || player?.pitchHand?.code
      || player?.pitchHand?.description
      || '',
  );
  if (direct) return direct;
  const id = Number(player?.person?.id || player?.id);
  if (!Number.isFinite(id) || id <= 0) return '';
  if (teamStatsPersonHandCache.has(id)) return teamStatsPersonHandCache.get(id);
  const promise = getPerson(id)
    .then((payload) => handednessCode(payload?.people?.[0]?.pitchHand?.code || payload?.people?.[0]?.pitchHand?.description || ''))
    .catch(() => '');
  teamStatsPersonHandCache.set(id, promise);
  return promise;
}

function boxscorePitcherStartedGame(player = null) {
  const pitching = player?.stats?.pitching || {};
  if (statNumber(pitching.gamesStarted ?? pitching.gs) > 0) return true;
  return statNumber(pitching.battersFaced) > 0 && statNumber(pitching.gamesPitched ?? pitching.games) > 0 && inningsToOuts(pitching.inningsPitched) > 0;
}

function boxscoreStarterForSide(boxscore = null, side = '') {
  const team = boxscore?.teams?.[side] || {};
  const players = team?.players || {};
  const pitcherIds = listify(team?.pitchers);
  const started = pitcherIds
    .map((id) => players[`ID${id}`] || players[id])
    .find(boxscorePitcherStartedGame);
  if (started) return started;
  const firstId = pitcherIds[0];
  return firstId ? (players[`ID${firstId}`] || players[firstId] || null) : null;
}

async function boxscoreStarterUsageProfile(player = null, season = seasonForDate(dateInput?.value || formatDate(new Date()))) {
  const id = Number(player?.person?.id || player?.id);
  if (!Number.isFinite(id) || id <= 0) return player;
  const cacheKey = `${season}:${id}:pitcher-role`;
  if (teamStatsPitcherRoleCache.has(cacheKey)) return teamStatsPitcherRoleCache.get(cacheKey);
  const fallback = {
    id,
    fullName: player?.person?.fullName || player?.fullName || '',
    position: 'P',
  };
  const promise = getPlayerSeasonStatSplit(id, 'pitching', season)
    .then((pitching) => ({
      ...fallback,
      pitching: pitching || {},
      gamesStarted: statNumber(pitching?.gamesStarted),
      gamesPlayed: statNumber(pitching?.gamesPlayed),
    }))
    .catch(() => fallback);
  teamStatsPitcherRoleCache.set(cacheKey, promise);
  return promise;
}

function getTeamStarterHandSummaryMap(season) {
  const cacheDate = parseFlexibleDateInput(dateInput?.value || '') || formatDate(new Date());
  const key = `${season}:${cacheDate}:starter-hand`;
  let promise = teamStatsStarterHandCache.get(key);
  if (!promise) {
    promise = fetchTeamVsStarterHandFastSummaryMap(season).catch((error) => {
      teamStatsStarterHandCache.delete(key);
      throw error;
    });
    teamStatsStarterHandCache.set(key, promise);
  }
  return promise;
}

function getTeamStarterHandBattingOnlyMap(season) {
  const key = `${season}:starter-hand-batting-only`;
  let promise = teamStatsStarterHandCache.get(key);
  if (!promise) {
    promise = fetchTeamVsPitcherHandBattingMap(season).catch((error) => {
      teamStatsStarterHandCache.delete(key);
      throw error;
    });
    teamStatsStarterHandCache.set(key, promise);
  }
  return promise;
}

function getTeamStarterHandRecordOnlyMap(season) {
  const cacheDate = parseFlexibleDateInput(dateInput?.value || '') || formatDate(new Date());
  const key = `${season}:${cacheDate}:starter-hand-record-only`;
  let promise = teamStatsStarterHandCache.get(key);
  if (!promise) {
    promise = fetchTeamVsStarterHandRecordMap(season).catch((error) => {
      teamStatsStarterHandCache.delete(key);
      throw error;
    });
    teamStatsStarterHandCache.set(key, promise);
  }
  return promise;
}

function teamStarterHandSplitText(teamAbbrev, opponentStarterHand = '', starterHandSummaryMap = new Map()) {
  const hand = handednessCode(opponentStarterHand);
  const teamId = TEAM_IDS[canonicalTeamAbbrev(teamAbbrev)];
  const summary = starterHandSummaryMap.get(Number(teamId)) || null;
  const bucket = hand === 'L' ? summary?.vsLStarter : hand === 'R' ? summary?.vsRStarter : null;
  if (!bucket) return '';
  const record = recordBucketText(bucket, { minGames: 8, pendingText: '...' });
  return `v${hand}HP AVG ${teamStarterHandAvgText(bucket)} | v${hand}SP REC ${record} HR ${statNumber(bucket.homeRuns)}`;
}

function scoreboardOpponentStarterHand(game, side) {
  const opponentSide = side === 'away' ? 'home' : side === 'home' ? 'away' : '';
  if (!opponentSide) return '';
  const pitcherSummary = resolveLineupPitcherForDisplay(game, opponentSide);
  const pitcher = pitcherSummary?.starter || pitcherSummary?.current || game?.probablePitchers?.[opponentSide] || game?.teams?.[opponentSide]?.probablePitcher || null;
  return pitcher?.throws || pitcher?.pitchHand?.code || pitcher?.pitchHand?.description || pitcher?.person?.pitchHand?.code || pitcher?.person?.pitchHand?.description || '';
}

function lineupTeamRecordLine(game, side) {
  const base = side === 'away' ? game?.awayRecord : side === 'home' ? game?.homeRecord : '';
  return cleanSummary(base);
}

function hydrateGameCardStarterHandRecordLine(card, game) {
  if (!card || !game || (game.awayStarterHandRecordLine && game.homeStarterHandRecordLine)) return;
  const date = parseFlexibleDateInput(dateInput?.value || '') || formatDate(new Date());
  getTeamStarterHandSummaryMap(seasonForDate(date)).then((starterHandSummaryMap) => {
    if (!card.isConnected) return;
    game.awayStarterHandRecordLine = teamStarterHandSplitText(game.away, scoreboardOpponentStarterHand(game, 'away'), starterHandSummaryMap);
    game.homeStarterHandRecordLine = teamStarterHandSplitText(game.home, scoreboardOpponentStarterHand(game, 'home'), starterHandSummaryMap);
    const awayRecordEl = card.querySelector('.away-record');
    const homeRecordEl = card.querySelector('.home-record');
    if (awayRecordEl) awayRecordEl.textContent = lineupTeamRecordLine(game, 'away');
    if (homeRecordEl) homeRecordEl.textContent = lineupTeamRecordLine(game, 'home');
  }).catch(() => {});
}

function teamDetailGameContext(teamAbbrev = '') {
  const selectedDate = dateInput?.value || formatDate(new Date());
  return {
    officialDate: selectedDate,
    gameDate: selectedDate,
    teamId: TEAM_IDS[canonicalTeamAbbrev(teamAbbrev)],
  };
}

function teamDetailSplitForHand(splits = null, hand = 'R') {
  return handednessCode(hand) === 'L' ? splits?.vsLeft || null : splits?.vsRight || null;
}

function teamDetailSplitScore(split = null, profile = {}) {
  const ops = rateNumber(split?.ops);
  const slg = rateNumber(split?.slg);
  const avg = rateNumber(split?.avg);
  const pa = statNumber(split?.plateAppearances || split?.atBats);
  const seasonOps = rateNumber(profile?.batting?.ops);
  const seasonAvg = rateNumber(profile?.batting?.avg);
  return (Number.isFinite(ops) ? ops : Number.isFinite(slg) ? slg + 0.25 : Number.isFinite(avg) ? avg * 2 : Number.isFinite(seasonOps) ? seasonOps : Number.isFinite(seasonAvg) ? seasonAvg * 2 : 0)
    + Math.min(pa, 220) / 10000
    + Math.min(statNumber(split?.homeRuns), 20) / 100
    + Math.min(statNumber(split?.doubles) + statNumber(split?.triples), 40) / 1000;
}

function teamDetailLineupForHand(hitters = [], hand = 'R') {
  return listify(hitters)
    .map((entry) => ({ ...entry, split: teamDetailSplitForHand(entry.splits, hand), splitHand: handednessCode(hand) }))
    .sort((a, b) => (
      teamDetailSplitScore(b.split, b.profile) - teamDetailSplitScore(a.split, a.profile)
      || fallbackLineupCandidateScore(b.profile || b, b.profile || b) - fallbackLineupCandidateScore(a.profile || a, a.profile || a)
      || String(a.fullName || '').localeCompare(String(b.fullName || ''))
    ))
    .slice(0, 9)
    .map((entry, index) => ({ ...entry, slot: index + 1 }));
}

function teamDetailSplitText(split = null) {
  if (!split) return 'PA -- | AVG --- | OPS --- | SLG --- | XBH -- | HR --';
  const xbh = statNumber(split.doubles) + statNumber(split.triples) + statNumber(split.homeRuns);
  return [
    `PA ${statNumber(split.plateAppearances || split.atBats)}`,
    `AVG ${cleanSummary(split.avg) || '---'}`,
    `OPS ${cleanSummary(split.ops) || '---'}`,
    `SLG ${cleanSummary(split.slg) || '---'}`,
    `XBH ${xbh}`,
    `HR ${statNumber(split.homeRuns)}`,
  ].join(' | ');
}

function teamDetailLineupItemHtml(entry = {}) {
  const color = entry.color || getTeamColor(entry.teamAbbrev);
  return `
    <li class="${teamDetailBatterTrendClass(entry)}" data-player-id="${escapeHtml(String(entry.id || ''))}" role="button" tabindex="0" style="--team-color:${escapeHtml(color)}">
      <span class="lineup-slot">${escapeHtml(String(entry.slot || ''))}</span>
      <span class="lineup-name">
        <span class="lineup-name-text">${escapeHtml(lastName(entry.fullName || entry.name || 'Unknown'))}</span>
        ${handednessHtml(entry.bats)}
      </span>
      <span class="lineup-pos">${escapeHtml(entry.position || '')}</span>
      <span class="lineup-today">${escapeHtml(teamDetailSplitText(entry.split))}</span>
    </li>
  `;
}

function teamDetailBatterTrendClass(entry = {}) {
  if (entry.teamDetailTrend === 'hot') return 'lineup-row-hot';
  if (entry.teamDetailTrend === 'cold') return 'lineup-row-cold';
  const split = entry?.split || null;
  const ops = Number.parseFloat(String(split?.ops || '').replace(/^\./, '0.'));
  const avg = Number.parseFloat(String(split?.avg || '').replace(/^\./, '0.'));
  const slg = Number.parseFloat(String(split?.slg || '').replace(/^\./, '0.'));
  const isHot = (Number.isFinite(ops) && ops >= LINEUP_HOT_OPS_THRESHOLD)
    || (Number.isFinite(avg) && avg >= 0.320)
    || (Number.isFinite(slg) && slg >= 0.550);
  const isCold = !isHot && ((Number.isFinite(ops) && ops <= LINEUP_COLD_OPS_THRESHOLD)
    || ((Number.isFinite(avg) && avg <= 0.180) && (!Number.isFinite(slg) || slg <= 0.320)));
  return isHot ? 'lineup-row-hot' : isCold ? 'lineup-row-cold' : '';
}

async function hydrateTeamDetailBatterTrends(team = '', hitters = [], selectedDate = dateInput.value || formatDate(new Date())) {
  const lineup = listify(hitters).slice(0, 16);
  if (!lineup.length) return hitters;
  const game = {
    gamePk: `team-detail-trends-${canonicalTeamAbbrev(team)}-${selectedDate}`,
    officialDate: selectedDate,
    gameDate: selectedDate,
    away: canonicalTeamAbbrev(team),
    home: canonicalTeamAbbrev(team),
    lineup: { away: lineup, home: [] },
    playerLookup: Object.fromEntries(lineup
      .map((entry) => [String(entry.id || ''), entry])
      .filter(([id]) => id)),
  };
  const hotIds = await getRecognizedLineupHotPlayerIds(game, selectedDate).catch(() => new Set());
  const coldIds = await getRecognizedLineupColdPlayerIds(game, selectedDate, hotIds).catch(() => new Set());
  return listify(hitters).map((entry) => ({
    ...entry,
    teamDetailTrend: hotIds?.has?.(String(entry.id)) ? 'hot' : coldIds?.has?.(String(entry.id)) ? 'cold' : '',
  }));
}

function teamDetailPitcherItemHtml(arm = {}, color = '') {
  const isBullpenDay = Boolean(arm.isBullpenDay);
  return `
    <li class="bullpen-item${teamDetailPitcherTrendClass(arm)}${isBullpenDay ? ' is-bullpen-day' : ''}" data-player-id="${escapeHtml(String(arm.id || ''))}"${isBullpenDay ? '' : ' role="button" tabindex="0"'}>
      <div class="bullpen-main pitcher-priority-line">
        <span class="bullpen-name pitcher-priority-name" title="${escapeHtml(arm.fullName || arm.name || 'Pitcher')}" style="color:${escapeHtml(color)}">${isBullpenDay ? 'Bullpen Day' : teamDetailPitcherNameHtml(arm)}</span>
        <span class="bullpen-meta pitcher-priority-meta">${teamDetailPitcherMetaLine(arm)}</span>
      </div>
    </li>
  `;
}

function teamDetailPitcherNameHtml(arm = {}) {
  const name = escapeHtml(lastName(arm.fullName || arm.name || 'Pitcher'));
  const hand = handednessCode(arm.throws || arm.pitchHand?.code || arm.pitchHand?.description || '');
  return `${name}${hand ? ` <span class="handedness-tag">${escapeHtml(hand)}</span>` : ''}`;
}

function teamDetailPitcherMetaLine(arm = {}) {
  return [
    `IP ${cleanSummary(pitcherInningsPitched(arm)) || '0.0'}`,
    `ERA ${cleanSummary(pitcherEra(arm)) || '---'}`,
    `WHIP ${cleanSummary(pitcherWhip(arm)) || '---'}`,
  ].join(' | ');
}

function teamDetailPitcherTrendClass(arm = {}) {
  const er = Number(arm?.lastStartEarnedRuns ?? arm?.metrics?.last?.earnedRuns ?? arm?.last?.earnedRuns);
  if (!Number.isFinite(er)) return '';
  if (er <= 1) return ' lineup-row-cold';
  if (er >= 2) return ' lineup-row-hot';
  return '';
}

async function teamDetailPitcherLastStartStats(playerId, date = dateInput.value || formatDate(new Date())) {
  const id = Number(playerId);
  const selectedDate = calendarDateOnly(date || dateInput.value || formatDate(new Date()));
  if (!Number.isFinite(id) || id <= 0 || !selectedDate) return null;
  const cacheKey = `${id}:${selectedDate}:team-detail-last-start`;
  if (pitcherLastPitchedCache.has(cacheKey)) return pitcherLastPitchedCache.get(cacheKey);
  const promise = (async () => {
    const url = new URL(`${MLB_API_BASE}/people/${id}/stats`);
    url.searchParams.set('stats', 'gameLog');
    url.searchParams.set('group', 'pitching');
    url.searchParams.set('season', String(seasonForDate(selectedDate)));
    url.searchParams.set('gameType', 'R');
    const response = await getJson(url.toString());
    const split = listify(response?.stats?.[0]?.splits)
      .filter((row) => String(row?.date || '') < selectedDate)
      .filter((row) => statNumber(row?.stat?.gamesStarted) > 0 || inningsToOuts(row?.stat?.inningsPitched) >= 12)
      .sort((a, b) => String(b?.date || '').localeCompare(String(a?.date || '')))[0] || null;
    if (!split) return null;
    return {
      date: split.date || '',
      earnedRuns: statNumber(split?.stat?.earnedRuns),
      inningsPitched: cleanSummary(split?.stat?.inningsPitched || ''),
    };
  })().catch(() => null);
  pitcherLastPitchedCache.set(cacheKey, promise);
  return promise;
}

async function hydrateTeamDetailStarterTrends(starters = [], date = dateInput.value || formatDate(new Date())) {
  return mapWithConcurrency(listify(starters), 4, async (arm) => {
    if (!arm || arm.isBullpenDay || !Number.isFinite(Number(arm.id))) return arm;
    const lastStart = await teamDetailPitcherLastStartStats(arm.id, date).catch(() => null);
    return lastStart ? { ...arm, lastStartEarnedRuns: lastStart.earnedRuns, lastStartDate: lastStart.date, lastStartIp: lastStart.inningsPitched } : arm;
  });
}

function teamDetailPitcherSortValue(arm = {}) {
  return pitcherGamesStarted(arm) * 10000
    + inningsToOuts(pitcherInningsPitched(arm)) * 10
    + pitcherStrikeoutCount(arm);
}

function teamDetailIsStarterCandidate(arm = {}) {
  const gs = pitcherGamesStarted(arm);
  const gp = pitcherGamesPlayed(arm);
  const avgStartIp = pitcherAverageInningsPerStart(arm);
  const roleText = cleanSummary(`${arm.role || ''} ${arm.usageRole || ''} ${arm.rankRole || ''}`).toUpperCase();
  if (/\bSP\b|START/.test(roleText) && gs > 0) return true;
  if (gs >= 2 && avgStartIp >= 2.5) return true;
  return gs >= 4 && gp > 0 && gs >= Math.ceil(gp * 0.35);
}

function splitTeamDetailPitchingStaff(arms = []) {
  const normalized = listify(arms).filter((arm) => Number.isFinite(Number(arm?.id)) && Number(arm.id) > 0 && isHealthyPitcherCandidate(arm));
  const starterPool = normalized
    .filter(teamDetailIsStarterCandidate)
    .sort((a, b) => teamDetailPitcherSortValue(b) - teamDetailPitcherSortValue(a) || String(a?.name || '').localeCompare(String(b?.name || '')));
  const starters = starterPool.slice(0, 5);
  const starterIds = new Set(starters.map((arm) => String(arm.id)));
  const relievers = normalized
    .filter((arm) => !starterIds.has(String(arm.id)))
    .sort((a, b) => {
      const aSave = pitcherSaveCount(a);
      const bSave = pitcherSaveCount(b);
      if (bSave !== aSave) return bSave - aSave;
      const aGames = pitcherGamesPlayed(a);
      const bGames = pitcherGamesPlayed(b);
      if (bGames !== aGames) return bGames - aGames;
      return pitcherStrikeoutCount(b) - pitcherStrikeoutCount(a) || String(a?.name || '').localeCompare(String(b?.name || ''));
    });
  return { starters, relievers };
}

function teamDetailBullpenDaySlot(relievers = []) {
  const values = bullpenSummaryValues(relievers);
  return {
    id: '',
    name: 'Bullpen Day',
    fullName: 'Bullpen Day',
    isBullpenDay: true,
    ip: values?.ip || '0.0',
    era: Number.isFinite(values?.era) ? formatRateValue(values.era, 2, false) : '---',
    whip: Number.isFinite(values?.whip) ? formatRateValue(values.whip, 2, false) : '---',
  };
}

function teamDetailStartingFive(groups = {}) {
  const starters = listify(groups.starters).slice(0, 5);
  while (starters.length < 5) starters.push(teamDetailBullpenDaySlot(groups.relievers));
  return starters;
}

function teamDetailStarterHandCompactText(teamAbbrev = '', hand = '', starterHandSummaryMap = new Map(), starterHandRecordMap = new Map()) {
  const code = handednessCode(hand);
  const teamId = TEAM_IDS[canonicalTeamAbbrev(teamAbbrev)];
  const summary = starterHandSummaryMap.get(Number(teamId)) || null;
  const recordSummary = starterHandRecordMap.get(Number(teamId)) || null;
  const battingBucket = code === 'L' ? summary?.vsLStarter : code === 'R' ? summary?.vsRStarter : null;
  const recordBucket = code === 'L' ? recordSummary?.vsLStarter : code === 'R' ? recordSummary?.vsRStarter : null;
  if (!battingBucket && !recordBucket) return '';
  const bucket = { ...(battingBucket || {}), ...(recordBucket ? { wins: recordBucket.wins, losses: recordBucket.losses } : {}) };
  const record = recordBucketText(bucket);
  return `${teamStarterHandAvgText(bucket)} | REC ${record} | HR ${statNumber(bucket.homeRuns)}`;
}

