    arsenal_hr: entry.arsenalMatchup ? predictionCsvNumber(entry.arsenalMatchup.hrThreatScore) : '',
    arsenal_k: entry.arsenalMatchup ? predictionCsvNumber(entry.arsenalMatchup.kRiskScore) : '',
