    full_2b: fullStats?.doubles ?? '',
    full_3b: fullStats?.triples ?? '',
    full_hr: fullStats?.homeRuns ?? '',
    full_bb: fullStats?.walks ?? '',
    full_k: fullStats?.strikeOuts ?? '',
