    result_1_hit: eligible ? (fullStats.hits >= 1 ? 1 : 0) : '',
    result_2_tb: eligible ? (fullStats.totalBases >= 2 ? 1 : 0) : '',
    result_hr: eligible ? (fullStats.homeRuns >= 1 ? 1 : 0) : '',
